# Патч ДО любых импортов: "cannot import name 'logging' from 'huggingfacehub'"
# Регистрируем stdlib logging как подмодуль, чтобы "from . import logging" в пакете находил его
import sys
import importlib.util
import logging as _stdlib_logging

# Совместимость: некоторые зависимости ожидают logging.get_logger (в stdlib есть getLogger)
if not hasattr(_stdlib_logging, "get_logger") and hasattr(_stdlib_logging, "getLogger"):
    _stdlib_logging.get_logger = _stdlib_logging.getLogger  # type: ignore[attr-defined]

_HF_PKGS = ("huggingfacehub", "huggingface_hub")
for _pkg in _HF_PKGS:
    _sub = f"{_pkg}.logging"
    if _sub not in sys.modules:
        sys.modules[_sub] = _stdlib_logging

class _HuggingfaceLoggingLoader:
    def __init__(self, orig_loader):
        self._orig_loader = orig_loader

    def create_module(self, spec):
        return getattr(self._orig_loader, "create_module", lambda s: None)(spec)

    def exec_module(self, module):
        pkg_name = getattr(module, "__name__", "")
        sub_name = f"{pkg_name}.logging"
        if sub_name not in sys.modules:
            sys.modules[sub_name] = _stdlib_logging
        module.logging = _stdlib_logging  # type: ignore[attr-defined]
        if hasattr(module, "__all__") and "logging" not in module.__all__:
            module.__all__ = list(module.__all__) + ["logging"]  # type: ignore[attr-defined]
        if hasattr(self._orig_loader, "exec_module"):
            self._orig_loader.exec_module(module)

class _HuggingfaceLoggingFinder:
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _HF_PKGS:
            return None
        try:
            _self = self
            if _self in sys.meta_path:
                sys.meta_path.remove(_self)
            try:
                spec = importlib.util.find_spec(fullname, path, target)
            finally:
                if _self in sys.meta_path:
                    pass
                else:
                    sys.meta_path.insert(0, _self)
        except Exception:
            spec = None
        if spec is None or not getattr(spec, "loader", None):
            return None
        spec.loader = _HuggingfaceLoggingLoader(spec.loader)
        return spec

_HF_FINDER = _HuggingfaceLoggingFinder()
sys.meta_path.insert(0, _HF_FINDER)

# Глобальный перехват RecursionError (голосовые и др.) — логируем, не падаем
import traceback as _traceback
def _global_exception_handler(exc_type, exc_value, exc_tb):
    if exc_type is RecursionError:
        try:
            print("RECURSION ERROR CAUGHT:", exc_value, file=sys.stderr)
            _traceback.print_tb(exc_tb)
        except Exception:
            pass
        try:
            _stdlib_logging.getLogger(__name__).error(
                "RECURSION ERROR CAUGHT: %s", exc_value, exc_info=(exc_type, exc_value, exc_tb)
            )
        except Exception:
            pass
        return
    sys.__excepthook__(exc_type, exc_value, exc_tb)
sys.excepthook = _global_exception_handler
try:
    sys.setrecursionlimit(10000)
except Exception:
    pass

