# SQLite PARSE_DECLTYPES: стандартный convert_timestamp ломается на ISO «2026-03-20T12:00:00» (нет пробела).
def _sqlite_timestamp_converter(val: object) -> object:
    if val is None:
        return None
    if isinstance(val, bytes):
        val = val.decode("utf-8", errors="ignore")
    s = str(val).strip()
    if not s:
        return None
    if "T" in s:
        s = s.replace("T", " ", 1)
    if "+" in s:
        s = s.split("+", 1)[0].strip()
    if s.endswith("Z"):
        s = s[:-1]
    base = s.split(".")[0]
    if len(base) >= 19:
        try:
            return datetime.strptime(base[:19], "%Y-%m-%d %H:%M:%S")
        except Exception:
            pass
    try:
        return datetime.fromisoformat(str(val).replace("Z", "+00:00"))
    except Exception:
        return val


sqlite3.register_converter("TIMESTAMP", _sqlite_timestamp_converter)
