def get_pil_font(size: int = 20) -> ImageFont.ImageFont:
    """Возвращает шрифт с поддержкой кириллицы (macOS, Linux, Windows)."""
    candidates = [
        "/System/Library/Fonts/Supplemental/Arial Unicode.ttf",
        "/System/Library/Fonts/Supplemental/Arial.ttf",
        "/System/Library/Fonts/Supplemental/Helvetica.ttc",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
        "/usr/share/fonts/TTF/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
    ]
    for path in candidates:
        try:
            if Path(path).exists():
                return ImageFont.truetype(path, size)
        except Exception:
            continue
    return ImageFont.load_default()


def _load_watermark_overlay(watermark: Dict[str, Any]) -> Optional[Image.Image]:
    """Загружает и подготавливает watermark-картинку."""
    try:
        if not watermark.get("enabled"):
            return None
        wm: Optional[Image.Image] = None

        # 1) Приоритет локальному файлу: переживает перезапуски и обновления.
        local_path = watermark.get("local_path")
        if local_path:
            p = Path(str(local_path))
            if p.exists():
                wm = Image.open(p).convert("RGBA")

        # 2) Fallback на Telegram file_id (только если бот уже инициализирован).
        if wm is None:
            file_id = watermark.get("file_id")
            if file_id:
                bot_ref = globals().get("bot")
                if bot_ref is None or not hasattr(bot_ref, "get_file"):
                    return None
                file_info = bot_ref.get_file(file_id)
                downloaded_file = bot_ref.download_file(file_info.file_path)
                wm = Image.open(io.BytesIO(downloaded_file)).convert("RGBA")
            else:
                return None

        size = int(watermark.get("size", 100))
        wm = wm.resize((max(24, size), max(24, size)))
        opacity = max(0, min(255, int(float(watermark.get("opacity", 0.3)) * 255)))
        wm.putalpha(opacity)
        return wm
    except Exception as e:
        logging.getLogger(__name__).error("Watermark load error: %s", e)
        return None


def _apply_watermark(base: Image.Image, overlay: Optional[Image.Image], watermark: Dict[str, Any]) -> None:
    """Накладывает watermark на изображение (in-place)."""
    if overlay is None:
        return
    try:
        positions = {
            "bottom_right": (base.width - overlay.width - 16, base.height - overlay.height - 16),
            "bottom_left": (16, base.height - overlay.height - 16),
            "top_right": (base.width - overlay.width - 16, 16),
            "top_left": (16, 16),
            "center": ((base.width - overlay.width) // 2, (base.height - overlay.height) // 2),
        }
        pos = positions.get(watermark.get("position", "bottom_right"), positions["bottom_right"])
        base.paste(overlay, pos, overlay)
    except Exception as e:
        logging.getLogger(__name__).error("Watermark apply error: %s", e)

def _strip_emoji_for_image(text: str) -> str:
    """Убирает эмодзи из строки для отрисовки в PIL (чтобы не было квадратиков). Оставляет латиницу и кириллицу."""
    if not text:
        return ""
    result = []
    for ch in str(text):
        o = ord(ch)
        if o <= 0x024F or (0x0300 <= o <= 0x036F) or (0x0400 <= o <= 0x04FF):
            result.append(ch)
        elif 0x1F300 <= o <= 0x1F9FF or 0x2600 <= o <= 0x26FF or 0x2700 <= o <= 0x27BF or o > 0xFFFF:
            continue
        else:
            result.append(ch)
    out = "".join(result).strip()
    return out if out else "".join(c for c in str(text) if ord(c) < 0x0500)[:50]


def _is_emoji_char(c: str) -> bool:
    """Проверяет, является ли символ эмодзи (любой эмодзи из Telegram / Unicode)."""
    if not c:
        return False
    o = ord(c)
    return (
        0x1F1E6 <= o <= 0x1F1FF   # флаги (regional indicators)
        or 0x1F000 <= o <= 0x1F02F   # маджонг, домино и т.д.
        or 0x1F300 <= o <= 0x1F9FF   # символы, смайлы, доп. символы
        or 0x2300 <= o <= 0x23FF   # разное (⏰ и т.д.)
        or 0x2600 <= o <= 0x26FF   # разное (☀️ и т.д.)
        or 0x2700 <= o <= 0x27BF   # Dingbats
        or 0x2B50 <= o <= 0x2B55   # звёзды, стрелки
        or o in (0x3030, 0x303D, 0x3297, 0x3299)  # символы
        or (o > 0xFFFF and o <= 0x10FFFF)
    )


def _is_emoji_modifier(c: str) -> bool:
    """Символы, которые должны идти в одном сегменте с предыдущим эмодзи (вариационный селектор, тон кожи, ZWJ, ключ-кап)."""
    if not c:
        return False
    o = ord(c)
    return (
        o == 0xFE0F  # variation selector-16 (например ❤️ = ❤ + FE0F)
        or o == 0x200D  # ZWJ (соединение эмодзи)
        or o == 0x20E3  # combining enclosing keycap (1️⃣ = 1 + FE0F + 20E3)
        or 0x1F3FB <= o <= 0x1F3FF  # skin tone
        or o == 0xFE0E  # variation selector-15 (text style)
    )


def _truncate_preserving_emoji(s: str, max_len: int) -> str:
    """Обрезает строку до max_len символов, не разрывая эмодзи: если обрезка попадает на вариационный селектор (❤️) или тон кожи (👋🏿), добиваем сегмент до конца. Нормализация NFC."""
    if not s or max_len <= 0:
        return ""
    s = unicodedata.normalize("NFC", str(s))
    if len(s) <= max_len:
        return s
    out = s[:max_len]
    # После обрезки следующий символ может быть модификатором (FE0F и т.д.) — добавить, чтобы не получить контур вместо заливки
    while len(s) > len(out) and _is_emoji_modifier(s[len(out)]):
        out += s[len(out)]
    return out


def _split_text_and_emoji(s: str) -> List[Tuple[str, bool]]:
    """Разбивает строку на сегменты: (текст, False) и (эмодзи, True). Вариационный селектор (❤️) и тон кожи не отрываются от эмодзи.
    Поддерживаются смешанные форматы: «ангелина🖤❤️», «вася dead🖤», «sqwoz❤️bab» и т.д. Вход нормализуется в NFC."""
    if not s:
        return []
    s = unicodedata.normalize("NFC", str(s))
    segments: List[Tuple[str, bool]] = []
    current_text: List[str] = []
    current_emoji: List[str] = []

    def flush_text():
        if current_text:
            segments.append(("".join(current_text), False))
            current_text.clear()

    def flush_emoji():
        if current_emoji:
            segments.append(("".join(current_emoji), True))
            current_emoji.clear()

    for c in str(s):
        if _is_emoji_char(c):
            flush_text()
            current_emoji.append(c)
        elif _is_emoji_modifier(c) and current_emoji:
            # Вариационный селектор / тон кожи / ZWJ — добавляем к текущему эмодзи (❤️, 👋🏿)
            current_emoji.append(c)
        else:
            flush_emoji()
            current_text.append(c)
    flush_text()
    flush_emoji()
    return segments


# Кэш картинок Twemoji: ключ (hex, size), значение (PIL Image, timestamp)
_twemoji_cache: Dict[Tuple[str, int], Tuple[Image.Image, float]] = {}
_twemoji_cache_lock = threading.Lock()
_TWEMOJI_CACHE_MAX = 80
_TWEMOJI_CACHE_TTL = 3600  # 1 час
_TWEMOJI_BASES = [
    "https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/72x72",
    "https://raw.githubusercontent.com/twitter/twemoji/master/assets/72x72",
]


def _get_twemoji_hex(emoji_chars: str) -> str:
    """Кодирует последовательность эмодзи в hex для Twemoji (например 1f44b-1f3ff)."""
    parts = []
    for c in emoji_chars:
        parts.append(f"{ord(c):x}")
    return "-".join(parts)


def _create_emoji_fallback(emoji_char: str, size: int) -> Image.Image:
    """Создаёт заглушку для эмодзи, если загрузка не удалась."""
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    font = get_pil_font(max(8, size - 4))
    draw.text((2, 2), emoji_char, fill=(255, 255, 255, 200), font=font)
    return img


def _load_twemoji_image(codepoint_hex: str, size: int) -> Optional[Image.Image]:
    """
    Загружает картинку эмодзи из Twemoji с кэшированием и ограничением размера кэша.
    Использует блокировку для thread-safety.
    """
    key = (codepoint_hex, size)
    now = time.time()

    with _twemoji_cache_lock:
        if key in _twemoji_cache:
            img, timestamp = _twemoji_cache[key]
            if now - timestamp < _TWEMOJI_CACHE_TTL:
                return img
            del _twemoji_cache[key]

    to_try = [codepoint_hex]
    if codepoint_hex.endswith("-fe0f"):
        to_try.append(codepoint_hex[:-5])

    img = None
    for base in _TWEMOJI_BASES:
        if img is not None:
            break
        for hex_str in to_try:
            url = f"{base}/{hex_str}.png"
            for attempt in range(2):
                try:
                    resp = requests.get(url, timeout=3)
                    resp.raise_for_status()
                    img = Image.open(io.BytesIO(resp.content)).convert("RGBA")
                    img = img.resize((size, size), Image.Resampling.LANCZOS)
                    break
                except Exception as e:
                    logger.debug("Twemoji %s %s (attempt %s): %s", hex_str, base[:40], attempt + 1, e)

    if img is None:
        return _create_emoji_fallback("❓", size)

    with _twemoji_cache_lock:
        if len(_twemoji_cache) >= _TWEMOJI_CACHE_MAX:
            oldest_key = min(_twemoji_cache.keys(), key=lambda k: _twemoji_cache[k][1])
            del _twemoji_cache[oldest_key]
        _twemoji_cache[key] = (img, now)

    return img


def _preload_common_emojis() -> None:
    """Фоново предзагружает часто используемые эмодзи."""
    common_emojis = ["2764", "1f44d", "1f44e", "1f60a", "1f602", "1f44b", "1f44c", "1f91d"]
    common_size = 32
    for hex_str in common_emojis:
        try:
            _load_twemoji_image(hex_str, common_size)
        except Exception:
            pass


def _draw_text_with_emoji(
    img: Image.Image,
    draw: ImageDraw.ImageDraw,
    x: int,
    y: int,
    text: str,
    font: ImageFont.ImageFont,
    fill: Tuple[int, int, int],
    emoji_size: int = 32,
) -> None:
    """Рисует строку на изображении: текст шрифтом, эмодзи — картинками Twemoji (без прямоугольников)."""
    if not text:
        return
    # Нормализация NFC: единый вид символов (Telegram может отдавать NFD), чтобы hex для Twemoji совпадал
    text = unicodedata.normalize("NFC", str(text))
    segments = _split_text_and_emoji(text)

    for part, is_emoji in segments:
        if not part:
            continue
        if is_emoji:
            hex_str = _get_twemoji_hex(part)
            emoji_img = _load_twemoji_image(hex_str, emoji_size)
            if emoji_img:
                mask = emoji_img.split()[3] if emoji_img.mode == "RGBA" and len(emoji_img.split()) >= 4 else None
                img.paste(emoji_img, (x, y), mask)
                x += emoji_size
            else:
                # Twemoji не загрузился — не рисуем шрифтом (даёт прямоугольник); оставляем пропуск по ширине эмодзи
                x += emoji_size
        else:
            draw.text((x, y), part, fill=fill, font=font)
            try:
                bbox = font.getbbox(part)
                x += bbox[2] - bbox[0]
            except (AttributeError, TypeError):
                w = draw.textlength(part, font=font) if hasattr(draw, "textlength") else len(part) * 12
                x += int(w)


def create_stats_image(data: Dict[str, Any], watermark: Dict[str, Any], lang: str = "ru") -> bytes:
    """
    Создаёт изображение со статистикой (без эмодзи в тексте — только текст/цифры для корректного отображения).
    """
    img = Image.new('RGB', (800, 400), color=(30, 30, 30))
    draw = ImageDraw.Draw(img)
    font = get_pil_font(24)

    title = _strip_emoji_for_image(t(lang, "stats_image_title"))
    user_label = _strip_emoji_for_image(data.get('user', t(lang, "stats_image_user")))
    draw.text((50, 30), title, fill=(255, 255, 255), font=font)
    draw.text((50, 60), user_label[:40], fill=(100, 200, 255), font=font)

    y = 100
    for key, value in data.get('data', {}).items():
        draw.text((50, y), f"{_strip_emoji_for_image(str(key))}: {value}", fill=(255, 255, 255), font=font)
        y += 30

    # Накладываем водяной знак, если он включён
    _apply_watermark(img, _load_watermark_overlay(watermark), watermark)
    
    # Конвертируем в байты
    img_bytes = io.BytesIO()
    img.save(img_bytes, format='PNG')
    img_bytes.seek(0)
    
    return img_bytes.getvalue()


def _sync_watermark_settings_to_config() -> None:
    """Синхронизирует watermark_settings в settings (обратная совместимость + новые ключи)."""
