# В продакшене обязательно: export BOT_TOKEN=... ; export ADMIN_CHAT_ID=... ; export CHAT_ID=...
def _env_int(key: str, default: Optional[int] = None) -> Optional[int]:
    """
    Получает целое число из переменной окружения.
    Если переменная не задана и default не указан, возвращает None.
    """
    val = os.getenv(key, "").strip()
    if not val:
        return default
    try:
        return int(val)
    except ValueError:
        return default


# ID разработчиков (владельцев бота) из переменных окружения или settings.json
def _load_developer_ids() -> list:
    """Загружает список разработчиков из переменных окружения или настроек."""
    ids = []

    # Из переменных окружения DEVELOPER_ID_1, DEVELOPER_ID_2, ...
    for i in range(1, 5):
        env_id = os.getenv(f"DEVELOPER_ID_{i}")
        if env_id and str(env_id).strip().isdigit():
            ids.append(int(str(env_id).strip()))

    # Для обратной совместимости: если в окружении ничего нет — используем ADMIN_CHAT_ID из env
    if not ids:
        admin_id = os.getenv("ADMIN_CHAT_ID")
        if admin_id and str(admin_id).strip().isdigit():
            ids = [int(str(admin_id).strip())]

    return ids


