def notify_admin_error(title: str, details: str) -> None:
    """
    Отправляет уведомление об ошибке владельцу бота и в канал логов (если настроен).
    В личку админу (ADMIN_CHAT_ID) и дубликат в канал логов (LOG_BOT_CHAT_ID).
    Используется даже до полной инициализации bot-объекта.
    """
    if not BOT_TOKEN:
        return
    text = f"⚠️ {title}\n\n{details}"
    if len(text) > 3900:
        text = text[:3900] + "…"
    payload = {
        "text": text,
        "parse_mode": "HTML",
        "disable_web_page_preview": True,
    }
    # В личку админу
    if ADMIN_CHAT_ID:
        try:
            requests.post(
                f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
                data={**payload, "chat_id": ADMIN_CHAT_ID},
                timeout=5,
            )
        except Exception:
            pass
    # В канал логов (все логи по логике идут в отдельный канал)
    if LOG_BOT_CHAT_ID:
        try:
            requests.post(
                f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
                data={**payload, "chat_id": LOG_BOT_CHAT_ID},
                timeout=5,
            )
        except Exception:
            pass


class PollingExceptionNotifier(telebot.ExceptionHandler):
    """Глобальный обработчик ошибок polling, чтобы бот не останавливался."""

    def __init__(self):
        self._last_notify_ts = 0.0
        self._last_transient_notify_ts = 0.0

    @staticmethod
    def _is_transient_network_error(err_text: str) -> bool:
        """Определяет временные сетевые ошибки Telegram API."""
        transient_markers = (
            "Read timed out",
            "ConnectTimeout",
            "Connection reset by peer",
            "EOF occurred in violation of protocol",
            "UNEXPECTED_EOF_WHILE_READING",
            "Temporary failure in name resolution",
            "Max retries exceeded",
            "RemoteDisconnected",
            "ProxyError",
            "SSLError",
        )
        return any(marker in err_text for marker in transient_markers)

    @staticmethod
    def _is_polling_conflict_error(err_text: str) -> bool:
        """Определяет конфликт одновременного getUpdates (HTTP 409)."""
        txt = (err_text or "").lower()
        return (
            "error code: 409" in txt
            or "terminated by other getupdates request" in txt
            or "conflict: terminated by other getupdates request" in txt
        )

    def handle(self, exception):
        try:
            err_text = str(exception)
            if self._is_polling_conflict_error(err_text):
                logger.error(f"Polling conflict detected: {err_text}")
                now = time.time()
                if now - self._last_notify_ts >= 120:
                    self._last_notify_ts = now
                    notify_admin_error(
                        "Конфликт polling (409)",
                        "Обнаружен второй процесс с тем же BOT_TOKEN. "
                        "Оставь запущенным только один экземпляр бота.",
                    )
                return True

            is_transient = self._is_transient_network_error(err_text)
            if is_transient:
                logger.warning(f"Polling transient network issue: {err_text}")
            else:
                logger.error(f"Polling exception handled: {err_text}")

            # Анти-спам уведомлений владельцу
            now = time.time()
            if is_transient:
                # Для сетевых флапов уведомляем редко (раз в 10 минут)
                if now - self._last_transient_notify_ts >= 600:
                    self._last_transient_notify_ts = now
                    notify_admin_error(
                        "Сетевой сбой Telegram API (бот продолжает работать)",
                        html.escape(err_text),
                    )
            elif now - self._last_notify_ts >= 10:
                self._last_notify_ts = now
                notify_admin_error(
                    "Ошибка обработчика (бот продолжает работать)",
                    html.escape(err_text),
                )
        except Exception:
            pass

        # Ключевое: сообщаем TeleBot, что ошибка обработана.
        return True

