class TelegramErrorLogHandler(logging.Handler):
    """
    Отправляет записи уровня ERROR и CRITICAL в канал логов. Используется основной бот (BOT_TOKEN),
    сообщения уходят в чат/канал LOG_BOT_CHAT_ID (настройка log_bot_chat_id в settings или LOG_BOT_CHAT_ID в env).
    Отправка выполняется в отдельном потоке, чтобы не блокировать основной код.
    """
    def emit(self, record: logging.LogRecord) -> None:
        try:
            token = BOT_TOKEN
            chat_id = LOG_BOT_CHAT_ID
            if not token or not chat_id:
                return
            msg = self.format(record)
            if len(msg) > 3900:
                msg = msg[:3900] + "\n…"
            text = f"🔴 <b>{record.levelname}</b>\n<pre>{html.escape(msg)}</pre>"
            payload = {"chat_id": chat_id, "text": text, "parse_mode": "HTML", "disable_web_page_preview": True}
            def _send() -> None:
                try:
                    requests.post(
                        f"https://api.telegram.org/bot{token}/sendMessage",
                        data=payload,
                        timeout=8,
                    )
                except Exception:
                    pass
            threading.Thread(target=_send, daemon=True).start()
        except Exception:
            self.handleError(record)


def setup_logging() -> logging.Logger:
    """
    Настраивает систему логирования.
    
    Создаёт:
    - Файловый логгер с ротацией по дням
    - Консольный логгер для отладки
    - Логгер ошибок отдельно
    
    Returns:
        logging.Logger: Настроенный логгер
    """
    
    # Создаём директорию для логов, если её нет
    LOGS_DIR.mkdir(parents=True, exist_ok=True)
    
    # Создаём форматтер для логов
    formatter = logging.Formatter(LOG_FORMAT, LOG_DATE_FORMAT)
    
    # Настраиваем корневой логгер
    root_logger = logging.getLogger()
    root_logger.setLevel(logging.DEBUG)
    
    # Удаляем существующие обработчики
    for handler in root_logger.handlers[:]:
        root_logger.removeHandler(handler)
    
    # Файловый обработчик для всех уровней
    file_handler = logging.FileHandler(LOG_FILE, encoding='utf-8', mode='a')
    file_handler.setLevel(logging.DEBUG)
    file_handler.setFormatter(formatter)
    root_logger.addHandler(file_handler)
    
    # Файловый обработчик только для ошибок
    error_log_file = LOGS_DIR / f"errors_{datetime.now().strftime('%Y%m%d')}.log"
    error_handler = logging.FileHandler(error_log_file, encoding='utf-8', mode='a')
    error_handler.setLevel(logging.ERROR)
    error_handler.setFormatter(formatter)
    root_logger.addHandler(error_handler)
    
    # Консольный обработчик
    console_handler = logging.StreamHandler(sys.stdout)
    console_handler.setLevel(logging.INFO)
    console_handler.setFormatter(formatter)
    root_logger.addHandler(console_handler)
    
    # Отправка ошибок в отдельного Telegram-бота (токен/chat_id из env или settings — проверяются в emit)
    telegram_error_handler = TelegramErrorLogHandler()
    telegram_error_handler.setLevel(logging.ERROR)
    telegram_error_handler.setFormatter(formatter)
    root_logger.addHandler(telegram_error_handler)
    
    # Логгер для этого модуля
    logger = logging.getLogger(__name__)
    logger.info("=" * 60)
    logger.info(f"Запуск бота {BOT_NAME} v{BOT_VERSION}")
    logger.info(f"Время запуска: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    logger.info(f"Директория: {BASE_DIR}")
    logger.info("=" * 60)
    
    return logger

# Создаём логгер
logger = setup_logging()

