# ===== TTL-КЭШ С АВТОМАТИЧЕСКОЙ ОЧИСТКОЙ =====
class TTLCache:
    """Словарь с автоматическим удалением устаревших записей."""

    def __init__(self, name: str, default_ttl: int = 3600, max_size: int = 10000) -> None:
        self.name = name
        self.default_ttl = default_ttl
        self.max_size = max_size
        self._data: Dict[Any, Tuple[Any, float]] = {}
        self._lock = threading.Lock()

    def set(self, key: Any, value: Any, ttl: Optional[int] = None) -> None:
        """Сохраняет значение с TTL."""
        expires = time.time() + (ttl if ttl is not None else self.default_ttl)
        with self._lock:
            if len(self._data) >= self.max_size:
                self._cleanup_oldest()
            self._data[key] = (value, expires)

    def get(self, key: Any) -> Optional[Any]:
        """Получает значение, если оно не истекло."""
        with self._lock:
            if key not in self._data:
                return None
            value, expires = self._data[key]
            if time.time() > expires:
                del self._data[key]
                return None
            return value

    def delete(self, key: Any) -> bool:
        """Удаляет ключ."""
        with self._lock:
            if key in self._data:
                del self._data[key]
                return True
        return False

    def _cleanup_oldest(self) -> None:
        """Удаляет самую старую запись при превышении лимита."""
        if not self._data:
            return
        oldest_key = min(self._data.keys(), key=lambda k: self._data[k][1])
        del self._data[oldest_key]

    def cleanup_expired(self) -> int:
        """Удаляет все истекшие записи. Возвращает количество удалённых."""
        now = time.time()
        expired = []
        with self._lock:
            for key, (_, expires) in self._data.items():
                if now > expires:
                    expired.append(key)
            for key in expired:
                del self._data[key]
        return len(expired)

    def size(self) -> int:
        """Текущий размер кэша."""
        with self._lock:
            return len(self._data)

    def clear(self) -> None:
        """Полная очистка."""
        with self._lock:
            self._data.clear()


_ttl_caches: List[TTLCache] = []
_ttl_cleanup_lock = threading.Lock()


def register_ttl_cache(cache: TTLCache) -> None:
    """Регистрирует кэш для автоматической очистки."""
    with _ttl_cleanup_lock:
        _ttl_caches.append(cache)


def _ttl_cleanup_worker() -> None:
    """Фоновый поток для очистки всех TTL-кэшей."""
    while True:
        time.sleep(300)
        try:
            total_cleaned = 0
            with _ttl_cleanup_lock:
                for cache in _ttl_caches:
                    try:
                        cleaned = cache.cleanup_expired()
                        total_cleaned += cleaned
                    except Exception as e:
                        logger.error("Error cleaning cache %s: %s", cache.name, e)
            if total_cleaned > 0:
                logger.debug("TTL cleanup: removed %s expired entries", total_cleaned)
        except Exception as e:
            logger.error("Error in TTL cleanup worker: %s", e)


threading.Thread(target=_ttl_cleanup_worker, daemon=True).start()


def _report_uncaught_exception(exc_type, exc_value, exc_traceback) -> None:
    """Глобальный репорт непойманных исключений."""
    try:
        details = "".join(traceback.format_exception(exc_type, exc_value, exc_traceback))
        logger.critical("Uncaught exception:\n%s", details)
        notify_admin_error(
            "Критическая ошибка (непойманное исключение)",
            html.escape(details[-3500:]),
        )
    except Exception:
        pass


def _thread_exception_hook(args: threading.ExceptHookArgs) -> None:
    """Репорт непойманных исключений в фоновых потоках."""
    try:
        details = "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
        logger.critical("Thread exception in %s:\n%s", args.thread.name if args.thread else "unknown", details)
        notify_admin_error(
            f"Ошибка в потоке: {html.escape(args.thread.name if args.thread else 'unknown')}",
            html.escape(details[-3500:]),
        )
    except Exception:
        pass


sys.excepthook = _report_uncaught_exception
threading.excepthook = _thread_exception_hook

# ============================================================================
# ИНИЦИАЛИЗАЦИЯ БОТА (создаём до первых @bot.message_handler)
# ============================================================================

def init_bot() -> telebot.TeleBot:
    """
    Инициализирует и настраивает экземпляр бота.
    """
    token = BOT_TOKEN
    for settings_path in (SETTINGS_FILE, Path.cwd() / "settings.json"):
        settings_path = settings_path.resolve()
        if not settings_path.exists():
            logger.debug("Файл настроек не найден: %s", settings_path)
            continue
        try:
            with open(settings_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not token:
                token = (
                    (data.get("bot_token") or data.get("BOT_TOKEN") or data.get("token")) or ""
                ).strip()
                if token:
                    globals()["BOT_TOKEN"] = token
                    logger.info("Токен бота загружен из %s (bot_token)", settings_path)
                else:
                    logger.warning(
                        "В %s нет ключа bot_token/BOT_TOKEN/token или значение пустое. Ключи в файле: %s",
                        settings_path,
                        list(data.keys())[:20],
                    )
            oid = data.get("owner_user_id")
            if oid is not None and str(oid).strip() != "":
                try:
                    globals()["ADMIN_CHAT_ID"] = int(oid)
                    logger.info("ADMIN_CHAT_ID загружен из settings.json (owner_user_id): %s", globals()["ADMIN_CHAT_ID"])
                except (ValueError, TypeError):
                    pass
            mid = data.get("main_chat_id")
            if mid is not None and str(mid).strip() != "":
                try:
                    globals()["CHAT_ID"] = int(mid)
                    logger.info("CHAT_ID загружен из settings.json (main_chat_id): %s", globals()["CHAT_ID"])
                except (ValueError, TypeError):
                    pass
            break
        except Exception as e:
            logger.warning("Не удалось прочитать %s при инициализации: %s", settings_path, e)

    if not token:
        settings_resolved = SETTINGS_FILE.resolve()
        logger.critical(
            "Токен бота не указан! Проверьте: 1) export BOT_TOKEN=... или 2) файл settings.json с ключом \"bot_token\". "
            "Ожидаемый путь: %s (существует: %s), текущая папка: %s",
            settings_resolved,
            settings_resolved.exists(),
            Path.cwd(),
        )
        raise ValueError(
            "BOT_TOKEN не может быть пустым. "
            "Задайте переменную окружения: export BOT_TOKEN=<токен от @BotFather> "
            "или создайте/добавьте в settings.json (в папке с bot.py) ключ \"bot_token\"."
        )

    logger.info(f"Инициализация бота с токеном: {token[:10]}...")
    bot = telebot.TeleBot(
        token,
        parse_mode="Markdown",
        disable_web_page_preview=True,
        threaded=True,
        num_threads=MAX_THREADS,
        exception_handler=PollingExceptionNotifier(),
    )
    try:
        me = bot.get_me()
        logger.info(f"✅ Бот успешно подключён: @{me.username} (ID: {me.id})")
    except Exception as e:
        logger.critical(f"❌ Не удалось подключиться к Telegram API: {e}")
        raise
    return bot

# Создаём экземпляр бота до первого использования в декораторах
bot = init_bot()

# Безопасная отправка сообщений: fallback при ошибках Markdown
_original_send_message = bot.send_message
_original_reply_to = bot.reply_to
_original_edit_message_text = bot.edit_message_text


def safe_handler(func: Callable) -> Callable:
    """
    Универсальный перехватчик ошибок хендлеров:
    - не даёт боту падать,
    - показывает пользователю понятное сообщение,
    - отправляет детали владельцу.
    - проверяет наличие from_user у Message/CallbackQuery (защита от crash).
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            if args:
                first = args[0]
                if isinstance(first, Message):
                    if not getattr(first, "from_user", None):
                        return None
                    if not check_command_access(first):
                        return None
                elif isinstance(first, CallbackQuery):
                    if not getattr(first, "from_user", None):
                        try:
                            bot.answer_callback_query(first.id)
                        except Exception:
                            pass
                        return None
            return func(*args, **kwargs)
        except Exception as e:
            err_id = uuid.uuid4().hex[:8]
            tb = traceback.format_exc()
            logger.error(f"[{err_id}] Handler error in {func.__name__}: {e}\n{tb}")
            ctx = ""
            if args:
                first = args[0]
                try:
                    if isinstance(first, Message):
                        ctx = f"user={first.from_user.id}, chat={first.chat.id}, text={first.text!r}"
                    elif isinstance(first, CallbackQuery):
                        ctx = f"user={first.from_user.id}, chat={first.message.chat.id}, data={first.data!r}"
                except Exception:
                    pass
            notify_admin_error(
                f"Ошибка хендлера [{err_id}]",
                html.escape(f"{func.__name__}\n{ctx}\n\n{str(e)}\n\n{tb[-2500:]}")
            )
            user_text = (
                f"⚠️ Временная ошибка (ID: {err_id}).\n"
                "Команда сейчас недоступна.\n"
                "Попробуй чуть позже. Возможно, этот раздел на техобслуживании."
            )
            try:
                sent_msg = None
                if args:
                    first = args[0]
                    if isinstance(first, Message):
                        sent_msg = bot.reply_to(first, user_text)
                    elif isinstance(first, CallbackQuery):
                        _lang = get_user_language(first.from_user.id)
                        bot.answer_callback_query(first.id, t(_lang, "error_temporary_try_later"))
                        sent_msg = bot.send_message(first.message.chat.id, user_text)
                try:
                    delay = int(globals().get("COMMAND_MESSAGES_TTL", 30))
                    delay = max(10, min(delay, 300))
                    deleter = globals().get("schedule_deletion")
                    if sent_msg and callable(deleter):
                        deleter(sent_msg.chat.id, sent_msg.message_id, delay)
                except Exception:
                    pass
            except Exception:
                pass
            return None
    return wrapper


