# ДЕКОРАТОРЫ ДЛЯ ПРОВЕРОК
# ============================================================================

def admin_only(func: Callable) -> Callable:
    """
    Декоратор для ограничения доступа только главному администратору.
    
    Args:
        func: Функция-обработчик команды
    
    Returns:
        Callable: Обёрнутая функция с проверкой прав
    
    Example:
        @bot.message_handler(commands=['admin'])
        @admin_callback_only
        def admin_command(message):
            bot.reply_to(message, t(get_user_language(message.from_user.id), "admin_you_are_admin"))
    """
    @wraps(func)
    def wrapper(message: Message, *args, **kwargs):
        # Проверяем, что отправитель - разработчик
        if message.from_user.id not in DEVELOPER_IDS:
            logger.warning(f"Попытка доступа к админ-функции от пользователя {message.from_user.id}")
            lang = get_user_language(message.from_user.id)
            bot.reply_to(message, t(lang, "admin_only_denied"), parse_mode="Markdown")
            return
        return func(message, *args, **kwargs)
    return wrapper


# ---------- Пароль на админ-панель ----------
admin_password_state: Dict[int, str] = {}  # user_id -> "waiting_for_password" | "waiting_input"

# ---------- Состояния вывода и P2P ----------
withdraw_state: Dict[int, Dict[str, Any]] = {}  # user_id -> {step, amount, currency, ...}
p2p_state: Dict[int, Dict[str, Any]] = {}  # user_id -> {step, amount, order_id, ...}


def _hash_admin_password(password: str) -> str:
    """Хеширует пароль с солью."""
    salt = secrets.token_hex(16)
    return salt + ":" + hashlib.sha256((salt + password).encode()).hexdigest()


def _verify_admin_password(password: str, password_hash: str) -> bool:
    """Проверяет пароль."""
    if ":" not in password_hash:
        return False
    salt, hash_value = password_hash.split(":", 1)
    return hash_value == hashlib.sha256((salt + password).encode()).hexdigest()


def _get_admin_password_row(user_id: int) -> Optional[Any]:
    """Возвращает строку admin_passwords для user_id или None."""
    rows = execute_query(USERS_DB, "SELECT password_hash, last_used FROM admin_passwords WHERE user_id = ?", (user_id,))
    if rows and len(rows) > 0:
        return rows[0]
    return None


def try_show_admin_panel(chat_id: int, user_id: int) -> None:
    """Показывает админ-панель или запрашивает пароль, если он установлен."""
    if user_id not in DEVELOPER_IDS:
        send_admin_panel_message(chat_id, user_id)
        return
    row = _get_admin_password_row(user_id)
    if row:
        with _state_lock:
            admin_password_state[user_id] = "waiting_input"
        lang = get_user_language(user_id)
        bot.send_message(
            chat_id,
            t(lang, "admin_password_prompt"),
            parse_mode="Markdown",
        )
    else:
        send_admin_panel_message(chat_id, user_id)


@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and m.from_user.id in admin_password_state)
@safe_handler
def admin_password_message_handler(message: Message):
    """Обработка ввода пароля админки или установки нового пароля."""
    user_id = message.from_user.id
    chat_id = message.chat.id
    state = admin_password_state.get(user_id)
    if not state:
        return
    text = (message.text or "").strip()
    try_delete_message(chat_id, message.message_id)
    if state == "waiting_input":
        row = _get_admin_password_row(user_id)
        if not row:
            with _state_lock:
                del admin_password_state[user_id]
            send_admin_panel_message(chat_id, user_id)
            return
        if _verify_admin_password(text, row[0]):
            with database_connection(USERS_DB) as conn:
                conn.execute("UPDATE admin_passwords SET last_used = ? WHERE user_id = ?", (datetime.now().isoformat(), user_id))
            with _state_lock:
                del admin_password_state[user_id]
            lang = get_user_language(user_id)
            bot.send_message(chat_id, t(lang, "admin_password_ok"))
            send_admin_panel_message(chat_id, user_id)
        else:
            lang = get_user_language(user_id)
            bot.send_message(chat_id, t(lang, "admin_password_wrong"))
    elif state == "waiting_for_password":
        with _state_lock:
            del admin_password_state[user_id]
        lang = get_user_language(user_id)
        if text == "0" or text.lower() == "отключить" or text.lower() == "disable":
            with database_connection(USERS_DB) as conn:
                conn.execute("DELETE FROM admin_passwords WHERE user_id = ?", (user_id,))
            bot.send_message(chat_id, t(lang, "admin_password_disabled"))
        elif len(text) < 4:
            bot.send_message(chat_id, t(lang, "admin_password_too_short"))
        else:
            ph = _hash_admin_password(text)
            with database_connection(USERS_DB) as conn:
                conn.execute(
                    "INSERT OR REPLACE INTO admin_passwords (user_id, password_hash, created_at) VALUES (?, ?, ?)",
                    (user_id, ph, datetime.now().isoformat()),
                )
            bot.send_message(chat_id, t(lang, "admin_password_set"))


# ---------- Обязательные подписки ----------
def check_all_subscriptions(user_id: int) -> Tuple[bool, List[Dict[str, Any]]]:
    """Проверяет, подписан ли пользователь на все обязательные каналы. Возвращает (ok, список неподписанных)."""
    rows = execute_query(
        USERS_DB,
        "SELECT chat_id, chat_username, title FROM required_subscriptions WHERE is_mandatory = 1",
    )
    if not rows:
        return True, []
    not_subscribed = []
    for r in rows:
        chat_id = int(r[0])
        try:
            member = bot.get_chat_member(chat_id, user_id)
            status = getattr(member, "status", "") or ""
            if status not in ("member", "administrator", "creator"):
                not_subscribed.append({
                    "chat_id": chat_id,
                    "chat_username": r[1] or "",
                    "title": r[2] or str(chat_id),
                })
        except Exception:
            not_subscribed.append({
                "chat_id": chat_id,
                "chat_username": r[1] or "",
                "title": r[2] or str(chat_id),
            })
    return len(not_subscribed) == 0, not_subscribed


def require_subscriptions(func: Callable) -> Callable:
    """Декоратор: перед выполнением проверяет обязательные подписки; если не подписан — показывает кнопки."""
    @wraps(func)
    def wrapper(message: Message, *args, **kwargs):
        user_id = message.from_user.id
        if user_id in DEVELOPER_IDS:
            return func(message, *args, **kwargs)
        ok, missing = check_all_subscriptions(user_id)
        if not ok:
            buttons = []
            for ch in missing:
                if ch.get("chat_username"):
                    uname = ch["chat_username"].lstrip("@")
                    buttons.append([
                        InlineKeyboardButton(
                            text=f"📢 Подписаться на {ch.get('title', uname)}",
                            url=f"https://t.me/{uname}",
                        )
                    ])
            _lang = get_user_language(user_id)
            buttons.append([InlineKeyboardButton(t(_lang, "check_sub_btn"), callback_data="check_subscriptions")])
            lang = _lang
            text = (
                "❌ **Доступ ограничен**\n\n"
                "Для использования этой функции необходимо подписаться:\n"
                + "\n".join(f"• {ch.get('title', ch.get('chat_username', ''))}" for ch in missing)
            )
            bot.reply_to(
                message,
                text,
                reply_markup=InlineKeyboardMarkup(buttons),
                parse_mode="Markdown",
            )
            return
        return func(message, *args, **kwargs)
    return wrapper


def group_only(func: Callable) -> Callable:
    """
    Декоратор для ограничения использования только в группах.
    
    Args:
        func: Функция-обработчик команды
    
    Returns:
        Callable: Обёрнутая функция с проверкой типа чата
    """
    @wraps(func)
    def wrapper(message: Message, *args, **kwargs):
        # Проверяем, что команда вызвана в группе
        if message.chat.type not in ['group', 'supergroup']:
            lang = get_user_language(message.from_user.id)
            bot.reply_to(message, t(lang, "group_only_denied"), parse_mode="Markdown")
            return
        return func(message, *args, **kwargs)
    return wrapper

def private_only(func: Callable) -> Callable:
    """
    Декоратор для ограничения использования только в личных сообщениях.
    
    Args:
        func: Функция-обработчик команды
    
    Returns:
        Callable: Обёрнутая функция с проверкой типа чата
    """
    @wraps(func)
    def wrapper(message: Message, *args, **kwargs):
        # Проверяем, что команда вызвана в личном чате
        if message.chat.type != 'private':
            lang = get_user_language(message.from_user.id)
            bot.reply_to(message, t(lang, "private_only_denied"), parse_mode="Markdown")
            return
        return func(message, *args, **kwargs)
    return wrapper

def permission_required(permission: str) -> Callable:
    """
    Декоратор для проверки наличия определённого права у пользователя.
    
    Args:
        permission: Название необходимого права
    
    Returns:
        Callable: Декоратор с параметром
    
    Example:
        @bot.message_handler(commands=['warn'])
        @permission_required('can_warn')
        def warn_command(message):
            # ...
    """
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(message: Message, *args, **kwargs):
            user_id = message.from_user.id
            chat_id = getattr(message.chat, "id", None) if getattr(message, "chat", None) else None
            # В группе учитываем локальные права (group_roles.permissions), чтобы глобальные изменения не сбрасывали их
            if not has_permission_in_chat(user_id, chat_id, permission):
                level = get_user_rank(user_id)
                rank_name = get_rank_name(level)
                lang = get_user_language(user_id)
                logger.warning(
                    f"Пользователь {user_id} попытался использовать "
                    f"{permission} без прав (ранг: {level})"
                )
                bot.reply_to(
                    message,
                    t(lang, "not_enough_rights") + "\n\n"
                    + t(lang, "your_rank", rank=rank_name) + "\n"
                    + t(lang, "required_permission", permission=permission) + "\n\n"
                    + t(lang, "contact_admin_rank"),
                    parse_mode="Markdown"
                )
                return
            return func(message, *args, **kwargs)
        return wrapper
    return decorator


def ensure_user_access(
    message: Message,
    require_group: bool = False,
    require_private: bool = False,
    silent: bool = False
) -> bool:
    """
    Централизованная проверка доступа к функциям бота.
    """
    user = getattr(message, "from_user", None)
    chat = getattr(message, "chat", None)

    if user is None or chat is None:
        return False

    user_id = user.id
    chat_type = chat.type
    chat_id = chat.id
    lang = get_user_language(user_id)

    # Владелец всегда имеет доступ.
    if user_id in DEVELOPER_IDS:
        return True

    if user_id in BANNED_USERS:
        if not silent:
            bot.reply_to(message, t(lang, "access_denied"))
        return False

    if MAINTENANCE_MODE and user_id not in DEVELOPER_IDS:
        if not silent:
            bot.reply_to(message, t(lang, "maintenance"))
        return False

    # Если бот ограничен списком групп — работаем только в этих группах.
    if chat_type in ("group", "supergroup") and ALLOWED_GROUPS:
        if chat_id not in ALLOWED_GROUPS:
            if not silent:
                bot.reply_to(message, t(lang, "bot_not_in_group"))
            return False

    # Белый режим трактуем как строгий режим разрешённых групп.
    if WHITELIST_MODE and chat_type in ("group", "supergroup"):
        if chat_id not in ALLOWED_GROUPS:
            if not silent:
                bot.reply_to(message, t(lang, "group_not_whitelist"))
            return False

    if require_group and chat_type not in ("group", "supergroup"):
        if not silent:
            bot.reply_to(message, t(lang, "only_in_group"))
        return False

    if require_private and chat_type != "private":
        if not silent:
            bot.reply_to(message, t(lang, "only_private"))
        return False

    # Требование подписки на основную группу только в ЛС: в личке без подписки доступен только /start.
    # В группах подписку не проверяем — в группе бот доступен всем участникам без требования вступить в основную группу.
    if chat_type == "private":
        if user_id not in DEVELOPER_IDS and not is_user_in_chat(user_id):
            allowed_private_commands = {"start"}
            command_name = _extract_command_name(getattr(message, "text", None))
            if command_name not in allowed_private_commands:
                if not silent:
                    # Удаляем команду пользователя
                    try:
                        bot.delete_message(chat_id, message.message_id)
                    except Exception:
                        pass
                    # Удаляем предыдущее уведомление о подписке (если есть)
                    cache_key = f"last_sub_message_{user_id}"
                    last_msg_id = cache_get(cache_key)
                    if last_msg_id:
                        try:
                            bot.delete_message(chat_id, last_msg_id)
                        except Exception:
                            pass
                    markup = InlineKeyboardMarkup()
                    markup.add(InlineKeyboardButton(t(lang, "return_to_chat"), url=_inline_keyboard_http_url(INVITE_LINK)))
                    markup.add(InlineKeyboardButton(t(lang, "check_sub_btn"), callback_data="check_sub"))
                    sent_msg = bot.send_message(
                        chat_id,
                        t(lang, "access_limited_left"),
                        reply_markup=markup,
                    )
                    cache_set(cache_key, sent_msg.message_id, ttl=3600)
                return False

    # В группах проверку подписки на основную группу НЕ делаем — в группе бот доступен всем.
    # Подписка требуется только в ЛС (блок выше: chat_type == "private").

    # Проверка доступности категории по команде (отключённые категории — техработы)
    text = getattr(message, "text", "") or ""
    if text.strip().startswith("/"):
        # Нормализуем: /cpc@Bot -> /cpc, /кнб@Bot -> /кнб (иначе маппинг CATEGORY_MAPPING не срабатывает)
        cmd_name = _extract_command_name(text)
        cmd = ("/" + cmd_name) if cmd_name else ""
        if cmd and user_id not in DEVELOPER_IDS:
            allowed, cat_msg = check_category_access(cmd, user_id, chat_id)
            if not allowed and cat_msg:
                if not silent:
                    markup = InlineKeyboardMarkup()
                    markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
                    bot.reply_to(message, t(lang, cat_msg), reply_markup=markup, parse_mode="Markdown")
                return False

    return True


def _fake_message_for_call(call: CallbackQuery, text: str = "/_callback") -> Any:
    """Минимальный Message-подобный объект для проверок доступа из callback."""
    chat = getattr(call, "message", None) and getattr(call.message, "chat", None)
    chat_id = getattr(chat, "id", 0) if chat else 0
    chat_type = getattr(chat, "type", "private") if chat else "private"
    fake = type("FakeMessage", (), {})()
    fake.chat = type("Chat", (), {"id": chat_id, "type": chat_type})()
    fake.from_user = call.from_user
    fake.text = text
    fake.content_type = "text"
    return fake


def ensure_call_access(
    call: CallbackQuery,
    require_group: bool = False,
    require_private: bool = False,
    silent: bool = False,
    allow_before_subscription: bool = False,
) -> bool:
    """
    Проверка доступа для callback'ов.
    В отличие от `ensure_user_access(call.message, ...)` (где from_user — это бот),
    здесь используется call.from_user.
    """
    if not getattr(call, "from_user", None) or not getattr(call, "message", None) or not getattr(call.message, "chat", None):
        return False

    # До подписки разрешаем только «безопасные» callbacks (например проверка подписки/язык)
    text = "/start" if allow_before_subscription else "/_callback"
    fake = _fake_message_for_call(call, text=text)
    # В callback'ах не пытаемся делать bot.reply_to(fake, ...) — у fake нет message_id.
    return ensure_user_access(fake, require_group=require_group, require_private=require_private, silent=True)


def get_subcategory_for_data(data: str) -> Optional[str]:
    """Возвращает ключ подкатегории по callback_data/команде или None."""
    if not data:
        return None
    data = (data or "").strip()
    if data in SUBCATEGORY_MAPPING:
        return SUBCATEGORY_MAPPING[data]
    for prefix, subcat in SUBCATEGORY_MAPPING.items():
        if prefix.endswith("_") and data.startswith(prefix):
            return subcat
    return None


def get_category_display_name(cat_key: str, lang: str) -> str:
    """Возвращает читаемое название категории/подкатегории для отображения (без сырых ключей)."""
    if not cat_key:
        return ""
    if cat_key.startswith("games_") and cat_key != "games":
        key = "subcat_name_" + cat_key
    else:
        key = "cat_name_" + cat_key
    name = t(lang, key)
    if name and name != key:
        return name
    return t(lang, "unknown_label")


def is_category_available(category: str, subcategory: Optional[str] = None) -> Tuple[bool, Optional[str]]:
    """
    Проверяет, доступна ли категория (и подкатегория, если указана).
    Возвращает (доступна ли, сообщение о причине при недоступности).
    """
    key_map = {
        "economy": "category_unavailable_economy", "shop": "category_unavailable_shop",
        "games": "category_unavailable_games", "moderation": "category_unavailable_moderation",
        "ai": "category_unavailable_ai", "profile": "category_unavailable_profile",
        "stats": "category_unavailable_stats", "referrals": "category_unavailable_referrals",
        "donations": "category_unavailable_donations", "p2p": "category_unavailable_p2p",
        "withdraw": "category_unavailable_withdraw", "vip": "category_unavailable_vip",
        "legend": "category_unavailable_legend", "marriage": "category_unavailable_marriage",
        "relationships": "category_unavailable_relationships", "achievements": "category_unavailable_achievements",
    }
    msg_key = key_map.get(category, "category_unavailable_default")
    if subcategory and not CATEGORY_STATUS.get(subcategory, True):
        return False, msg_key
    if not CATEGORY_STATUS.get(category, True):
        return False, msg_key
    return True, None


def get_back_button(chat_type: str, lang: str) -> InlineKeyboardMarkup:
    """
    Кнопка «Назад» в зависимости от типа чата.
    В ЛС — возврат в главное меню; в группе — «Закрыть» (удаляет сообщение).
    """
    markup = InlineKeyboardMarkup()
    if chat_type in ("group", "supergroup"):
        markup.add(InlineKeyboardButton("🔙 " + t(lang, "user_close_btn"), callback_data="delete_this_message"))
    else:
        markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
    return markup


def _show_category_unavailable(call: CallbackQuery, message_key: str, lang: str) -> None:
    """Показывает сообщение о недоступности категории по callback (редактирует сообщение или отправляет новое)."""
    message = t(lang, message_key) if message_key else ""
    bot.answer_callback_query(call.id, (message or "")[:200], show_alert=True)
    chat_type = getattr(call.message.chat, "type", "private")
    markup = get_back_button(chat_type, lang)
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    try:
        bot.edit_message_text(message, chat_id, msg_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(chat_id, message, reply_markup=markup, parse_mode="Markdown")


def require_category(category: str):
    """Декоратор: при выключенной категории показывает сообщение и не выполняет функцию. Разработчики всегда проходят."""

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            user_id = None
            chat_type = "private"
            message_obj = None
            callback_obj = None
            if args and isinstance(args[0], Message):
                message_obj = args[0]
                user_id = message_obj.from_user.id
                chat_type = getattr(message_obj.chat, "type", "private")
            elif args and isinstance(args[0], CallbackQuery):
                callback_obj = args[0]
                user_id = callback_obj.from_user.id
                chat_type = getattr(callback_obj.message.chat, "type", "private")
            if user_id is None:
                return func(*args, **kwargs)
            if user_id in DEVELOPER_IDS:
                return func(*args, **kwargs)
            available, msg_key = is_category_available(category)
            if available:
                return func(*args, **kwargs)
            lang = get_user_language(user_id)
            msg_text = t(lang, msg_key) if msg_key else ""
            markup = get_back_button(chat_type, lang)
            if message_obj:
                bot.reply_to(message_obj, msg_text, reply_markup=markup, parse_mode="Markdown")
            elif callback_obj:
                bot.answer_callback_query(callback_obj.id, (msg_text or "")[:200], show_alert=True)
                chat_id = callback_obj.message.chat.id
                msg_id = callback_obj.message.message_id
                try:
                    bot.edit_message_text(msg_text, chat_id, msg_id, reply_markup=markup, parse_mode="Markdown")
                except Exception:
                    bot.send_message(chat_id, msg_text, reply_markup=markup, parse_mode="Markdown")
            return None

        return wrapper

    return decorator


