def get_category_for_data(data: str) -> Optional[str]:
    """Определяет категорию по callback_data или команде. None если не в маппинге."""
    if not data:
        return None
    data = (data or "").strip()
    if data in CATEGORY_MAPPING:
        return CATEGORY_MAPPING[data]
    for key, cat in CATEGORY_MAPPING.items():
        if key.endswith("_") and data.startswith(key):
            return cat
    return None


def check_category_access(data: str, user_id: int, chat_id: Optional[int] = None) -> Tuple[bool, Optional[str]]:
    """
    Проверяет доступ к категории по callback_data или команде.
    Возвращает (доступно ли, сообщение об ошибке при недоступности).
    """
    if user_id in DEVELOPER_IDS:
        return True, None
    category = get_category_for_data(data)
    if not category:
        return True, None
    subcategory = get_subcategory_for_data(data)
    available, message = is_category_available(category, subcategory)
    if available:
        return True, None
    return False, message


def _callback_should_block_category(call: CallbackQuery) -> bool:
    """True, если callback ведёт в отключённую категорию и пользователь не разработчик."""
    if not getattr(call, "data", None) or not getattr(call, "from_user", None):
        return False
    if call.from_user.id in DEVELOPER_IDS:
        return False
    category = get_category_for_data(call.data)
    if not category:
        return False
    subcategory = get_subcategory_for_data(call.data or "")
    available, _ = is_category_available(category, subcategory)
    return not available


@bot.callback_query_handler(func=_callback_should_block_category)
@safe_handler
def _callback_category_block(call: CallbackQuery):
    """Блокирует доступ к отключённым категориям по callback (показывает сообщение о техработах)."""
    allowed, message_key = check_category_access(call.data or "", call.from_user.id, getattr(call.message.chat, "id", None))
    if allowed:
        return
    lang = get_user_language(call.from_user.id)
    msg_text = t(lang, message_key) if message_key else ""
    chat_type = getattr(call.message.chat, "type", "private")
    markup = get_back_button(chat_type, lang)
    bot.answer_callback_query(call.id, (msg_text or "")[:200], show_alert=True)
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    try:
        bot.edit_message_text(msg_text or "", chat_id, msg_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(chat_id, msg_text or "", reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data == "delete_this_message")
@safe_handler
def callback_delete_message(call: CallbackQuery):
    """Удаляет текущее сообщение (кнопка «Закрыть» в группах)."""
    try:
        bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    bot.answer_callback_query(call.id)


def normalize_stats_periods(raw: Any) -> List[int]:
    """Нормализует периоды статистики: 1..3650 дней, до 8 уникальных значений."""
    values: List[int] = []
    if isinstance(raw, list):
        source = raw
    elif isinstance(raw, str):
        source = [x.strip() for x in raw.replace(";", ",").split(",")]
    else:
        source = []

    for item in source:
        try:
            day = int(item)
        except Exception:
            continue
        if 1 <= day <= 3650 and day not in values:
            values.append(day)
        if len(values) >= 8:
            break

    if not values:
        values = [1, 3, 7, 30, 90, 365]
    return sorted(values)


def update_stats_periods(new_periods: Any) -> List[int]:
    """Обновляет глобальные периоды статистики и сохраняет в settings."""
    global STATS_PERIOD_DAYS
    STATS_PERIOD_DAYS = normalize_stats_periods(new_periods)
    settings["stats_period_days"] = STATS_PERIOD_DAYS
    save_settings(settings)
    return STATS_PERIOD_DAYS


def remember_user_if_bot(user: Optional[telebot.types.User]) -> None:
    """Кэширует ID бота/сервиса, чтобы исключать его из статы/экономики."""
    if not user:
        return
    try:
        if getattr(user, "is_bot", False):
            BOT_USER_IDS.add(int(user.id))
    except Exception:
        pass


def is_excluded_bot_user(user_id: int) -> bool:
    """Проверяет, нужно ли исключить пользователя как бота из расчётов."""
    try:
        uid = int(user_id)
    except Exception:
        return False
    if uid in BOT_USER_IDS:
        return True

    # Ленивое доопределение (для старых данных в БД).
    try:
        member = bot.get_chat_member(CHAT_ID, uid)
        if getattr(member.user, "is_bot", False):
            BOT_USER_IDS.add(uid)
            return True
    except Exception:
        pass
    return False

# Глобальный менеджер rate limit с автоматической очисткой
class RateLimitManager:
    """Потокобезопасный менеджер для rate limiting с автоматической очисткой."""

    def __init__(self) -> None:
        self._locks: Dict[int, threading.Lock] = {}
        self._last_calls: Dict[int, List[float]] = {}
        self._global_lock = threading.Lock()
        self._cleanup_counter = 0
        self._max_cleanup = 1000

    def _get_user_lock(self, user_id: int) -> threading.Lock:
        """Получает или создаёт блокировку для пользователя."""
        with self._global_lock:
            if user_id not in self._locks:
                self._locks[user_id] = threading.Lock()
            return self._locks[user_id]

    def _cleanup_old_entries(self) -> None:
        """Периодическая очистка старых записей."""
        now = time.time()
        with self._global_lock:
            expired_users = []
            for user_id, calls in list(self._last_calls.items()):
                if not calls or (now - calls[-1] > 3600):
                    expired_users.append(user_id)
            for user_id in expired_users:
                self._last_calls.pop(user_id, None)
                self._locks.pop(user_id, None)
            self._cleanup_counter = 0

    def check_and_add(self, user_id: int, max_per_minute: int) -> Tuple[bool, Optional[int]]:
        """
        Проверяет лимит и добавляет вызов.
        Возвращает (разрешено ли, сколько секунд ждать если нет).
        """
        user_lock = self._get_user_lock(user_id)

        with user_lock:
            now = time.time()
            minute_ago = now - 60
            calls = self._last_calls.get(user_id, [])
            calls = [t for t in calls if t > minute_ago]
            if len(calls) >= max_per_minute:
                wait_time = int(60 - (now - calls[0]))
                return False, max(1, wait_time)
            calls.append(now)
            self._last_calls[user_id] = calls

        with self._global_lock:
            self._cleanup_counter += 1
            need_cleanup = self._cleanup_counter >= self._max_cleanup
            if need_cleanup:
                self._cleanup_counter = 0
        if need_cleanup:
            self._cleanup_old_entries()

        return True, None


_rate_limit_manager = RateLimitManager()


def rate_limit(max_per_minute: int = 10) -> Callable:
    """
    Потокобезопасный декоратор для ограничения частоты использования команд.
    """
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(message: Message, *args, **kwargs):
            user_id = message.from_user.id
            if user_id in DEVELOPER_IDS:
                return func(message, *args, **kwargs)
            allowed, wait_time = _rate_limit_manager.check_and_add(user_id, max_per_minute)
            if not allowed and wait_time is not None:
                logger.info(f"Rate limit для пользователя {user_id}: {wait_time} сек")
                if wait_time == 1:
                    time_str = "секунду"
                elif 2 <= wait_time <= 4:
                    time_str = "секунды"
                else:
                    time_str = "секунд"
                bot.reply_to(
                    message,
                    f"⏳ **Слишком много запросов**\n\n"
                    f"Подожди ещё {wait_time} {time_str}.",
                    parse_mode="Markdown"
                )
                return
            return func(message, *args, **kwargs)
        return wrapper
    return decorator


def _rate_limit_cleanup_worker() -> None:
    """Фоновый поток для очистки rate limit данных."""
    while True:
        time.sleep(3600)
        try:
            _rate_limit_manager._cleanup_old_entries()
            logger.debug("Rate limit cache cleaned up")
        except Exception as e:
            logger.error("Error in rate limit cleanup: %s", e)


threading.Thread(target=_rate_limit_cleanup_worker, daemon=True).start()


def _cleanup_all_caches() -> None:
    """Периодическая очистка всех in-memory словарей."""
    logger.debug("Starting cache cleanup...")
    total_cleaned = 0
    try:
        cleaned = transfer_rate_tracker.cleanup()
        total_cleaned += cleaned
        if cleaned:
            logger.debug("transfer_rate_tracker: cleaned %s", cleaned)
    except Exception as e:
        logger.error("Error cleaning transfer_rate_tracker: %s", e)
    try:
        cleaned = rp_rate_limit_tracker.cleanup()
        total_cleaned += cleaned
        if cleaned:
            logger.debug("rp_rate_limit_tracker: cleaned %s", cleaned)
    except Exception as e:
        logger.error("Error cleaning rp_rate_limit_tracker: %s", e)
    try:
        cleaned = ai_request_tracker.cleanup()
        total_cleaned += cleaned
        if cleaned:
            logger.debug("ai_request_tracker: cleaned %s", cleaned)
    except Exception as e:
        logger.error("Error cleaning ai_request_tracker: %s", e)
    try:
        global anti_abuse_received_from_new
        today_str = date.today().isoformat()
        for user_id in list(anti_abuse_received_from_new.keys()):
            if anti_abuse_received_from_new[user_id][0] != today_str:
                del anti_abuse_received_from_new[user_id]
                total_cleaned += 1
        if total_cleaned:
            logger.debug("anti_abuse: cleaned")
    except Exception as e:
        logger.error("Error cleaning anti_abuse: %s", e)
    try:
        global ai_daily_request_count
        today_str = date.today().isoformat()
        for user_id in list(ai_daily_request_count.keys()):
            if ai_daily_request_count[user_id][0] != today_str:
                del ai_daily_request_count[user_id]
                total_cleaned += 1
    except Exception as e:
        logger.error("Error cleaning ai_daily_request_count: %s", e)
    logger.debug("Cache cleanup completed, removed %s entries", total_cleaned)


def _cache_cleanup_worker() -> None:
    """Фоновый поток для очистки кэшей."""
    while True:
        time.sleep(1800)
        try:
            _cleanup_all_caches()
        except Exception as e:
            logger.error("Error in cache cleanup worker: %s", e)


threading.Thread(target=_cache_cleanup_worker, daemon=True).start()
logger.info("✅ Cache cleanup worker started")


def retry_on_error(max_retries: int = 3, delay: float = 1.0) -> Callable:
    """
    Декоратор для автоматического повторения при ошибках.
    
    Args:
        max_retries: Максимальное количество попыток
        delay: Задержка между попытками в секундах
    
    Returns:
        Callable: Декоратор с параметром
    """
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_error = e
                    logger.warning(
                        f"Попытка {attempt + 1}/{max_retries} для {func.__name__} "
                        f"не удалась: {e}"
                    )
                    if attempt < max_retries - 1:
                        time.sleep(delay * (attempt + 1))  # Увеличиваем задержку
            
            # Если все попытки не удались
            logger.error(
                f"Все {max_retries} попыток для {func.__name__} не удались. "
                f"Последняя ошибка: {last_error}"
            )
            raise last_error
        return wrapper
    return decorator

def log_execution_time(func: Callable) -> Callable:
    """
    Декоратор для логирования времени выполнения функции.
    
    Args:
        func: Функция для измерения
    
    Returns:
        Callable: Обёрнутая функция с логированием времени
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        
        try:
            result = func(*args, **kwargs)
            execution_time = time.time() - start_time
            
            logger.debug(f"Функция {func.__name__} выполнена за {execution_time:.3f} сек")
            
            return result
        except Exception as e:
            execution_time = time.time() - start_time
            logger.error(
                f"Функция {func.__name__} завершилась с ошибкой через "
                f"{execution_time:.3f} сек: {e}"
            )
            raise
    return wrapper

def async_handler(func: Callable) -> Callable:
    """
    Декоратор для асинхронной обработки в отдельном потоке.
    
    Args:
        func: Функция-обработчик
    
    Returns:
        Callable: Обёрнутая функция, запускаемая в потоке
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        thread = threading.Thread(target=func, args=args, kwargs=kwargs, daemon=True)
        thread.start()
        return thread
    return wrapper

def _is_parse_entities_error(error: Exception) -> bool:
    """Проверяет, связана ли ошибка с некорректной разметкой parse_mode."""
    text = str(error).lower()
    if "can't parse entities" in text:
        return True
    # Варианты Telegram 400 / pyTelegramBotAPI при битом Markdown/HTML
    if "can't parse" in text and ("entity" in text or "entities" in text):
        return True
    if "message to parse" in text or ("unsupported" in text and "entity" in text):
        return True
    return False


def _safe_message_kwargs(kwargs: Dict[str, Any]) -> Dict[str, Any]:
    """Подготавливает kwargs для fallback-отправки."""
    safe_kwargs = dict(kwargs)
    safe_kwargs["parse_mode"] = "HTML"
    safe_kwargs.pop("entities", None)
    return safe_kwargs


def _safe_text(text: Any) -> str:
    """Экранирует текст для безопасной HTML-отправки."""
    if text is None:
        return ""
    return html.escape(str(text))


def _escape_markdown_caption(text: str) -> str:
    """Экранирует символы для подстановки в caption с parse_mode=Markdown. Эмодзи не трогаем."""
    if not text:
        return ""
    s = str(text)
    for char, repl in [("\\", "\\\\"), ("_", "\\_"), ("*", "\\*"), ("`", "\\`"), ("[", "\\["), ("]", "\\]")]:
        s = s.replace(char, repl)
    return s


def _escape_html_caption(text: str) -> str:
    """Экранирует <, >, & для подстановки в caption с parse_mode=HTML. Эмодзи не трогаем."""
    if not text:
        return ""
    return html.escape(str(text))


def send_message_safe(chat_id: Union[int, str], text: Any, *args, **kwargs):
    """Обёртка над send_message с fallback при parse entities error."""
    try:
        return _original_send_message(chat_id, text, *args, **kwargs)
    except Exception as e:
        if not _is_parse_entities_error(e):
            raise

        logger.warning(f"send_message fallback на HTML из-за parse entities error: {e}")
        safe_kwargs = _safe_message_kwargs(kwargs)
        return _original_send_message(chat_id, _safe_text(text), *args, **safe_kwargs)


def reply_to_safe(message: Message, text: Any, *args, **kwargs):
    """Обёртка над reply_to: fallback при parse entities error; при «message to be replied not found» — отправка без reply."""
    try:
        return _original_reply_to(message, text, *args, **kwargs)
    except Exception as e:
        err_str = str(e).lower()
        # Сообщение удалено или недоступно — отправляем без reply (например, после try_delete_message)
        if "message to be replied not found" in err_str:
            logger.debug(f"reply_to: сообщение для ответа не найдено, отправляем без reply: {e}")
            send_kwargs = {k: v for k, v in kwargs.items() if k != "reply_parameters"}
            return _original_send_message(message.chat.id, text, *args, **send_kwargs)
        if not _is_parse_entities_error(e):
            raise

        logger.warning(f"reply_to fallback на HTML из-за parse entities error: {e}")
        safe_kwargs = _safe_message_kwargs(kwargs)
        return _original_reply_to(message, _safe_text(text), *args, **safe_kwargs)


def edit_message_text_safe(text: Any, *args, **kwargs):
    """Обёртка над edit_message_text с fallback при parse entities error."""
    try:
        return _original_edit_message_text(text, *args, **kwargs)
    except Exception as e:
        # 1) Telegram 400 "message is not modified" — просто игнорируем, это не критическая ошибка.
        if "message is not modified" in str(e):
            logger.debug(f"edit_message_text: message is not modified, игнорируем: {e}")
            return None

        # 2) Любые другие ошибки, кроме parse entities, пробрасываем наверх.
        if not _is_parse_entities_error(e):
            raise

        logger.warning(f"edit_message_text fallback на HTML из-за parse entities error: {e}")
        safe_kwargs = _safe_message_kwargs(kwargs)
        return _original_edit_message_text(_safe_text(text), *args, **safe_kwargs)


# Глобально подменяем методы, чтобы все обработчики были защищены от падения.
bot.send_message = send_message_safe  # type: ignore[assignment]
bot.reply_to = reply_to_safe  # type: ignore[assignment]
bot.edit_message_text = edit_message_text_safe  # type: ignore[assignment]

