def format_com_amount(amount: float) -> str:
    """
    Форматирует количество внутренних монет COM.
    < 1000: целое число (500 🪙); 1000–999999: суффикс K (1.5K 🪙); >= 1M: суффикс M и 👑 (2.50M 👑).
    """
    if amount >= 1_000_000:
        return f"{amount / 1_000_000:.2f}M {COM_EMOJI_LARGE}"
    elif amount >= 1_000:
        return f"{amount / 1_000:.2f}K {COM_EMOJI}"
    else:
        return f"{int(amount)} {COM_EMOJI}"


def format_ton_amount(amount: float) -> str:
    """
    Форматирует количество TON с эмодзи 💎.
    Маленькие суммы — в десятичном виде; >= 1000 — суффиксы K/M.
    """
    if amount >= 1_000_000:
        return f"{amount / 1_000_000:.2f}M {TON_EMOJI}"
    elif amount >= 1_000:
        return f"{amount / 1_000:.2f}K {TON_EMOJI}"
    elif amount >= 1:
        return f"{amount:.2f} {TON_EMOJI}"
    elif amount >= 0.000001:
        return f"{amount:.6f} {TON_EMOJI}".rstrip("0").rstrip(".")
    else:
        return f"{amount:.8f} {TON_EMOJI}".rstrip("0").rstrip(".")


def get_currency_emoji(currency: str) -> str:
    """Возвращает эмодзи для валюты (COM → 🪙, TON → 💎 и т.д.)."""
    c = (currency or "").strip().upper()
    return CURRENCY_EMOJI.get(c, c)


