# КУРСЫ ВАЛЮТ (рассчитаны относительно 1 COM = 0.1 RUB)
# Актуально на 06.03.2026
COM_TO_CURRENCY = {
    "COM": 1.0,            # внутренняя единица

    # Фиатные валюты
    "RUB": 0.1,             # 1 COM = 0.1 рубля
    "USD": 0.001111,        # 1 USD = 90 RUB → 1 COM = 0.1/90 = 0.001111 USD
    "EUR": 0.001053,        # 1 EUR = 95 RUB → 1 COM = 0.1/95 = 0.001053 EUR
    "GBP": 0.00087,         # 1 GBP = 115 RUB → 1 COM = 0.1/115 = 0.00087 GBP
    "CNY": 0.008,           # 1 CNY = 12.5 RUB → 1 COM = 0.1/12.5 = 0.008 CNY
    "JPY": 0.1667,          # 1 JPY = 0.6 RUB → 1 COM = 0.1/0.6 = 0.1667 JPY
    "KZT": 0.526,           # 1 KZT = 0.19 RUB → 1 COM = 0.1/0.19 = 0.526 KZT
    "BYN": 0.00345,         # 1 BYN = 29 RUB → 1 COM = 0.1/29 = 0.00345 BYN
    "UAH": 0.0435,          # 1 UAH = 2.3 RUB → 1 COM = 0.1/2.3 = 0.0435 UAH
    "TRY": 0.03125,         # 1 TRY = 3.2 RUB → 1 COM = 0.1/3.2 = 0.03125 TRY
    "INR": 0.0952,          # 1 INR = 1.05 RUB → 1 COM = 0.1/1.05 = 0.0952 INR
    "BRL": 0.00625,         # 1 BRL = 16 RUB → 1 COM = 0.1/16 = 0.00625 BRL
    "CHF": 0.00098,         # 1 CHF = 102 RUB → 1 COM = 0.1/102 = 0.00098 CHF

    # Криптовалюты
    "BTC": 0.0000000185,    # 1 BTC = 5,400,000 RUB → 1 COM = 0.1/5400000 = 1.85e-8
    "ETH": 0.000000556,     # 1 ETH = 180,000 RUB → 1 COM = 0.1/180000 = 5.56e-7
    "TON": 0.0001667,       # 1 TON = 600 RUB → 1 COM = 0.1/600 = 0.0001667
}


class CurrencyManager:
    """Менеджер валют: курсы COM -> валюта, конвертация и форматирование."""

    def __init__(self):
        self.base_rates = dict(COM_TO_CURRENCY)
        self.base_rates["RUB"] = COM_TO_CURRENCY.get("RUB", 0.1)  # гарантия 1 COM = 0.1 ₽
        self._cache: Dict[str, Tuple[float, datetime]] = {}
        self.last_update: Optional[datetime] = None
        self.update_interval = 3600
        self._lock = threading.Lock()

    def update_rates(self) -> None:
        """
        Обновляет курсы из API (USD/RUB и производные).
        Если API недоступен, использует fallback-значения из COM_TO_CURRENCY.
        """
        try:
            r = requests.get("https://api.exchangerate-api.com/v4/latest/USD", timeout=10)
            if r.status_code == 200:
                data = r.json()
                rates = data.get("rates", {})
                usd_to_rub = float(rates.get("RUB", 90))
                with self._lock:
                    # RUB для отображения всегда из COM_TO_CURRENCY (1 COM = 0.1 ₽), не перезаписываем
                    rub_per_com = COM_TO_CURRENCY.get("RUB", 0.1)
                    # 1 COM в USD = (RUB за 1 COM) / (RUB за 1 USD)
                    self.base_rates["USD"] = rub_per_com / usd_to_rub
                    for cur in ("EUR", "GBP", "JPY", "CNY", "CHF", "TRY", "INR", "BRL", "KZT", "BYN", "UAH"):
                        if cur in rates:
                            self.base_rates[cur] = self.base_rates["USD"] * float(rates[cur])
                    self.base_rates["RUB"] = rub_per_com
                    self.last_update = datetime.now()
                    logger.info("✅ Курсы валют обновлены из API: %s", self.last_update)
            else:
                logger.warning("API вернул статус %s, использую fallback-курсы", r.status_code)
                self._use_fallback_rates()
        except Exception as e:
            logger.warning("Ошибка обновления курсов валют из API: %s", e)
            self._use_fallback_rates()

    def _use_fallback_rates(self) -> None:
        """Использует fallback-курсы из COM_TO_CURRENCY."""
        with self._lock:
            for cur, rate in COM_TO_CURRENCY.items():
                if cur != "COM":
                    self.base_rates[cur] = rate
            self.last_update = datetime.now()
            logger.info("✅ Использованы fallback-курсы: %s", self.last_update)

    def get_rate(self, currency: str) -> float:
        """
        Возвращает курс 1 COM в указанной валюте.
        Сначала пробует обновлённые курсы, затем fallback.
        RUB для отображения всегда берётся из COM_TO_CURRENCY (1 COM = 0.1 ₽).
        """
        currency = (currency or "RUB").upper()
        # Гарантия корректного курса RUB для отображения (1 COM = 0.1 ₽)
        if currency == "RUB":
            return COM_TO_CURRENCY.get("RUB", 0.1)
        with self._lock:
            if currency in self.base_rates:
                return self.base_rates[currency]
        return COM_TO_CURRENCY.get(currency, 1.0)

    def convert(self, com_amount: float, to_currency: str) -> Optional[float]:
        """Конвертирует COM в указанную валюту."""
        rate = self.get_rate(to_currency)
        return com_amount * rate if rate else None

    def format_amount(self, com_amount: float, currency: str, include_com: bool = True) -> str:
        """Форматирует сумму: 🪙 для COM, 💎 для TON, остальные по формату валюты."""
        currency = (currency or "RUB").upper()
        com_part = format_com_amount(com_amount)
        if currency == "COM":
            return com_part
        info = AVAILABLE_CURRENCIES.get(currency, AVAILABLE_CURRENCIES["RUB"])
        # Для RUB принудительно 1 COM = 0.1 ₽ (защита от перезаписи курса)
        rate = 0.1 if currency == "RUB" else self.get_rate(currency)
        converted = com_amount * rate
        decimals = info["decimals"]
        if currency == "TON":
            result = format_ton_amount(converted)
        else:
            if converted >= 1_000_000:
                formatted = f"{converted / 1_000_000:.2f}M"
            elif converted >= 1_000:
                formatted = f"{converted / 1_000:.2f}K"
            else:
                s = f"{converted:.{decimals}f}"
                # Убираем только хвостовые нули после точки (10.50 → 10.5), не трогаем целые (10 → 10)
                if "." in s:
                    s = s.rstrip("0").rstrip(".")
                formatted = s
            result = info["format"].format(amount=formatted, symbol=info["symbol"])
        if not include_com:
            return result
        return f"{com_part} (~{result})"

    def get_user_currency(self, user_id: int) -> str:
        """Валюта отображения пользователя из economy users."""
        rows = execute_query(ECONOMY_DB, "SELECT display_currency FROM users WHERE user_id = ?", (user_id,))
        cur: str | None = None
        if rows and len(rows) > 0 and rows[0][0]:
            c = (rows[0][0] or "").strip().upper()
            if c in AVAILABLE_CURRENCIES:
                cur = c
        # EN: суммы по умолчанию в долларах ($), пока не выбрана другая валюта в /currency
        lang = get_user_language(user_id)
        if lang == "en":
            if cur is None or cur == "RUB":
                return "USD"
            return cur
        if cur is None:
            return "RUB"
        return cur

    def set_user_currency(self, user_id: int, currency: str) -> bool:
        """Устанавливает валюту отображения для пользователя."""
        currency = (currency or "RUB").upper()
        if currency not in AVAILABLE_CURRENCIES:
            return False
        register_user(user_id)
        with database_connection(ECONOMY_DB) as conn:
            conn.execute(
                "UPDATE users SET display_currency = ? WHERE user_id = ?",
                (currency, user_id),
            )
            conn.commit()
        return True


currency_manager = CurrencyManager()


def verify_currency_rates() -> None:
    """Проверяет корректность всех курсов."""
    logger.info("🔍 Проверка курсов валют...")
    rub_rate = currency_manager.get_rate("RUB")
    usd_rate = currency_manager.get_rate("USD")
    if abs(rub_rate - 0.1) > 0.001:
        logger.warning("⚠️ Курс RUB отличается от ожидаемого: %s (ожидалось 0.1)", rub_rate)
    if usd_rate and usd_rate > 0:
        implied_usd_rub = rub_rate / usd_rate
        if abs(implied_usd_rub - 90) > 5:
            logger.warning("⚠️ Кросс-курс USD/RUB отличается: %.2f (ожидалось ~90)", implied_usd_rub)
    ton_rate = currency_manager.get_rate("TON")
    if abs(ton_rate - 0.0001667) > 0.00005:
        logger.warning("⚠️ Курс TON отличается: %s (ожидалось 0.0001667)", ton_rate)
    logger.info("✅ Проверка курсов завершена")


verify_currency_rates()


def format_amount_for_user(user_id: int, com_amount: float, include_com: bool = True) -> str:
    """Форматирует сумму в валюте пользователя."""
    currency = currency_manager.get_user_currency(user_id)
    return currency_manager.format_amount(com_amount, currency, include_com=include_com)


