def _format_fine_notification(user_id: int, amount_deducted: int, reason: str, new_balance: int, lang: str = None) -> str:
    """Формирует текст уведомления о штрафе на языке пользователя."""
    _lang = (lang or get_user_language(user_id) or "ru")[:2]
    return t(
        _lang,
        "violator_fine_message",
        amount=amount_deducted,
        balance=new_balance,
        reason=reason,
        sign=COM_EMOJI,
    )


def _send_or_save_fine_notification(user_id: int, amount_deducted: int, reason: str, new_balance: int) -> None:
    """Отправляет уведомление о штрафе в личку; при неудаче сохраняет для отправки при /start."""
    text = _format_fine_notification(user_id, amount_deducted, reason, new_balance)
    try:
        bot.send_message(user_id, text, parse_mode="Markdown")
    except Exception as e:
        logger.warning("Не удалось отправить уведомление о штрафе пользователю %s: %s. Сохраняем для отправки при /start.", user_id, e)
        try:
            execute_query(
                ECONOMY_DB,
                """INSERT INTO pending_fine_notifications (user_id, amount_deducted, reason, new_balance) VALUES (?, ?, ?, ?)""",
                (user_id, amount_deducted, reason, new_balance),
            )
        except Exception as ins_e:
            logger.error("Ошибка сохранения отложенного уведомления о штрафе: %s", ins_e)


def send_pending_fine_notifications(user_id: int) -> None:
    """Отправляет пользователю все накопленные уведомления о штрафах (при /start) и удаляет их из очереди."""
    try:
        rows = execute_query(
            ECONOMY_DB,
            "SELECT id, amount_deducted, reason, new_balance FROM pending_fine_notifications WHERE user_id = ? ORDER BY created_at",
            (user_id,),
        )
        if not rows:
            return
        for row in rows:
            _id, amount_deducted, reason, new_balance = row[0], row[1], row[2], row[3]
            text = _format_fine_notification(user_id, amount_deducted, reason, new_balance)
            try:
                bot.send_message(user_id, text, parse_mode="Markdown")
            except Exception as e:
                logger.warning("Не удалось отправить отложенное уведомление о штрафе %s пользователю %s: %s", _id, user_id, e)
            execute_query(ECONOMY_DB, "DELETE FROM pending_fine_notifications WHERE id = ?", (_id,))
    except Exception as e:
        logger.warning("Ошибка при отправке отложенных уведомлений о штрафах пользователю %s: %s", user_id, e)


@bot.message_handler(commands=["fine", "penalty", "штраф"])
@safe_handler
def cmd_fine(message: Message):
    """Штраф пользователю: вычесть сумму из баланса (только разработчик). Обязателен комментарий — он сохраняется и отправляется нарушителю."""
    if message.from_user.id not in DEVELOPER_IDS:
        return
    user_id = message.from_user.id
    lang = get_user_language(user_id) or "ru"
    text = (message.text or "").strip()
    parts = text.split()
    target_id = None
    amount = None
    reason = ""
    help_text = t(lang, "fine_help_text")
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        target_id = message.reply_to_message.from_user.id
        if getattr(message.reply_to_message.from_user, "is_bot", False):
            bot.reply_to(message, t(lang, "fine_cannot_bot"))
            return
        if len(parts) >= 2 and parts[1].isdigit():
            amount = int(parts[1])
            reason = " ".join(parts[2:]).strip()
        else:
            bot.reply_to(message, help_text, parse_mode="Markdown")
            return
    else:
        if len(parts) < 4:
            bot.reply_to(message, help_text, parse_mode="Markdown")
            return
        try:
            target_id = int(parts[1])
        except ValueError:
            bot.reply_to(message, "❌ Неверный user_id. Укажи число.")
            return
        if parts[2].isdigit():
            amount = int(parts[2])
            reason = " ".join(parts[3:]).strip()
        else:
            bot.reply_to(message, t(lang, "fine_amount_must_be_number"))
            return
    if not reason:
        bot.reply_to(message, t(lang, "fine_no_comment") + "\n\n" + help_text, parse_mode="Markdown")
        return
    if target_id is None or amount is None or amount < 1:
        bot.reply_to(message, t(lang, "fine_specify_params") + "\n\n" + help_text, parse_mode="Markdown")
        return
    if target_id in DEVELOPER_IDS:
        bot.reply_to(message, t(lang, "fine_cannot_developer"))
        return
    if is_excluded_bot_user(target_id):
        bot.reply_to(message, t(lang, "fine_cannot_bot"))
        return
    current = get_balance(target_id, use_cache=False)
    new_balance = max(0, current - amount)
    deducted = current - new_balance
    if deducted <= 0:
        bot.reply_to(message, t(lang, "fine_no_balance", target_id=target_id, current=current, sign=COM_EMOJI))
        return
    ok = set_balance(target_id, new_balance, f"Штраф: {reason}", admin_id=user_id)
    if ok:
        if message.reply_to_message and message.reply_to_message.from_user.id == target_id:
            mention = get_user_mention(target_id)
        else:
            mention = f"`{target_id}`"
        bot.reply_to(
            message,
            t(lang, "fine_success", mention=mention, deducted=deducted, reason=reason, new_balance=new_balance, sign=COM_EMOJI),
            parse_mode="Markdown",
        )
        # Уведомление нарушителю в личку бота; при неудаче — сохраняем для отправки после /start
        _send_or_save_fine_notification(target_id, deducted, reason, new_balance)
    else:
        bot.reply_to(message, t(lang, "fine_fail"))


