# Анти-фрод переводов (TTL 1 час)
class TransferRateTracker:
    def __init__(self) -> None:
        self._data: Dict[int, List[float]] = {}
        self._lock = threading.Lock()

    def add(self, user_id: int) -> None:
        with self._lock:
            now = time.time()
            minute_ago = now - 60
            calls = self._data.get(user_id, [])
            calls = [t for t in calls if t > minute_ago]
            calls.append(now)
            self._data[user_id] = calls

    def check(self, user_id: int, max_per_minute: int) -> Tuple[bool, int]:
        with self._lock:
            now = time.time()
            minute_ago = now - 60
            calls = self._data.get(user_id, [])
            calls = [t for t in calls if t > minute_ago]
            if len(calls) >= max_per_minute:
                wait = max(1, int(60 - (now - calls[0])))
                return False, wait
            return True, 0

    def cleanup(self) -> int:
        now = time.time()
        with self._lock:
            expired = [uid for uid, calls in self._data.items() if not calls or (now - calls[-1] > 3600)]
            for uid in expired:
                del self._data[uid]
        return len(expired)


class RPRateLimitTracker:
    def __init__(self) -> None:
        self._data: Dict[Tuple[int, int], List[float]] = {}
        self._lock = threading.Lock()

    def check_and_add(self, chat_id: int, user_id: int, limit_per_minute: int = 20) -> bool:
        key = (chat_id, user_id)
        with self._lock:
            now = time.time()
            minute_ago = now - 60
            calls = self._data.get(key, [])
            calls = [t for t in calls if t > minute_ago]
            if len(calls) >= limit_per_minute:
                return False
            calls.append(now)
            self._data[key] = calls
            return True

    def cleanup(self) -> int:
        now = time.time()
        with self._lock:
            expired = [key for key, calls in self._data.items() if not calls or (now - calls[-1] > 3600)]
            for key in expired:
                del self._data[key]
        return len(expired)


