# Ограничения ИИ (anti-spam)
class AIRequestTracker:
    def __init__(self) -> None:
        self.times: Dict[int, List[float]] = {}
        self.last_ts: Dict[int, float] = {}
        self.active_users: Set[int] = set()
        self._lock = threading.Lock()

    def check_and_add(self, user_id: int) -> Tuple[bool, Optional[str]]:
        with self._lock:
            now = time.time()
            if now - self.last_ts.get(user_id, 0) < 5:
                wait = int(5 - (now - self.last_ts.get(user_id, 0))) + 1
                return False, f"⏳ Подожди {wait} сек"
            minute_ago = now - 60
            calls = self.times.get(user_id, [])
            calls = [t for t in calls if t > minute_ago]
            if len(calls) >= 8:
                self.times[user_id] = calls
                return False, "⏳ Слишком много запросов. Попробуй через минуту."
            calls.append(now)
            self.times[user_id] = calls
            self.last_ts[user_id] = now
            return True, None

    def cleanup(self) -> int:
        now = time.time()
        with self._lock:
            expired = [uid for uid, calls in self.times.items() if not calls or (now - calls[-1] > 3600)]
            for uid in expired:
                self.times.pop(uid, None)
                self.last_ts.pop(uid, None)
        return len(expired)


