# ============================================================================
# ГОРЯЧАЯ ПЕРЕЗАГРУЗКА (Monolith Reloader)
# ============================================================================
# Используется при запуске через launcher.py: состояние сохраняется перед
# перезагрузкой модуля и восстанавливается после. FSM нет (telebot) — сохраняем
# кэши, активные ссылки/дуэли, сессии, контекст Кома и т.д.

# Событие для launcher: установить после /reload и stop_polling()
_reload_event: Optional[threading.Event] = None
# Событие для webhook_server: по /reload перезагрузить модуль без перезапуска процесса
_webhook_reload_event: Optional[threading.Event] = None

def set_reload_event(ev: Optional[threading.Event]) -> None:
    """Устанавливает событие перезагрузки (вызывается из launcher.py)."""
    global _reload_event
    _reload_event = ev

def set_webhook_reload_event(ev: Optional[threading.Event]) -> None:
    """Устанавливает событие перезагрузки кода (вызывается из webhook_server.py)."""
    global _webhook_reload_event
    _webhook_reload_event = ev

# Имена глобальных переменных, состояние которых нужно сохранять при перезагрузке
# (active_links, support_requests, ad_requests, transfer_rate_tracker, rp_rate_limit_tracker,
#  ai_request_tracker — TTL/трекеры, не сохраняем при reload)
_RELOAD_STATE_KEYS = (
    "user_messages", "user_ranks",
    "broadcast_active", "broadcast_stats", "broadcast_draft",
    "active_duels", "duel_counter",
    "request_counter", "ad_request_last_time",
    "cache", "cache_timestamps",
    "command_stats", "user_command_stats",
    "anti_abuse_received_from_new",
    "ai_daily_request_count",
    "_kom_chat_context", "_kom_chat_title_cache",
    "message_reward_tracker",
)

def _reload_snapshot_value(name: str, value: Any) -> Any:
    """Подготавливает значение для снимка (копия, пригодная для pickle/restore)."""
    if value is None:
        return None
    if isinstance(value, defaultdict):
        return copy.deepcopy(dict(value))
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            if name == "_kom_chat_context" and isinstance(v, deque):
                out[k] = list(v)  # deque -> list для сериализации
            else:
                try:
                    out[k] = copy.deepcopy(v)
                except Exception:
                    out[k] = v
        return out
    if isinstance(value, set):
        return set(value)
    if isinstance(value, (int, float, str, bool)):
        return value
    try:
        return copy.deepcopy(value)
    except Exception:
        return value

def _reload_restore_value(name: str, value: Any, original_type: type) -> Any:
    """Восстанавливает значение в нужный тип (defaultdict, deque и т.д.)."""
    if value is None:
        return None
    if name == "_kom_chat_context" and isinstance(value, dict):
        return {k: deque(v, maxlen=_KOM_CONTEXT_MAX_MESSAGES) for k, v in value.items()}
    if name == "user_messages":
        return defaultdict(list, value)
    if name == "command_stats":
        return defaultdict(int, value)
    if name == "user_command_stats":
        return defaultdict(lambda: defaultdict(int), {k: defaultdict(int, v) for k, v in value.items()})
    if name == "message_reward_tracker":
        return defaultdict(lambda: {"last_reward_ts": 0.0, "recent_rewards": [], "last_text_times": {}}, value)
    return value

def take_reload_snapshot() -> Dict[str, Any]:
    """
    Сохраняет снимок состояния бота для горячей перезагрузки.
    Вызывается из launcher.py перед importlib.reload(bot).
    """
    g = globals()
    snapshot = {}
    for name in _RELOAD_STATE_KEYS:
        if name not in g:
            continue
        try:
            val = g[name]
            snapshot[name] = _reload_snapshot_value(name, val)
        except Exception as e:
            logger.warning(f"reload snapshot skip {name}: {e}")
    return snapshot

def restore_reload_snapshot(snapshot: Dict[str, Any]) -> None:
    """
    Восстанавливает состояние бота из снимка после перезагрузки модуля.
    Вызывается из launcher.py после importlib.reload(bot).
    """
    if not snapshot:
        return
    g = globals()
    for name, value in snapshot.items():
        if name not in g:
            continue
        try:
            orig_type = type(g[name])
            g[name] = _reload_restore_value(name, value, orig_type)
        except Exception as e:
            logger.warning(f"reload restore skip {name}: {e}")
    logger.info("Состояние бота восстановлено после перезагрузки")

class MonolithReloader:
    """
    Горячая перезагрузка для монолитного bot.py (telebot).
    Сохраняет кэши, активные игры/сессии и контекст; FSM нет.
    """

    def __init__(self, bot_instance: "telebot.TeleBot"):
        self.bot = bot_instance
        self.snapshot: Dict[str, Any] = {}
        self.is_reloading = False

    async def take_snapshot(self) -> Dict[str, Any]:
        """Сохраняет снимок состояния (асинхронная обёртка над take_reload_snapshot)."""
        self.snapshot = take_reload_snapshot()
        return self.snapshot

    def take_snapshot_sync(self) -> Dict[str, Any]:
        """Синхронный снимок состояния."""
        self.snapshot = take_reload_snapshot()
        return self.snapshot

    def restore_snapshot(self) -> None:
        """Восстанавливает состояние из снимка."""
        restore_reload_snapshot(self.snapshot)
        self.snapshot = {}

    def request_reload(self) -> bool:
        """
        Запрашивает перезагрузку (для вызова из обработчика /reload).
        Останавливает polling и устанавливает событие для launcher.
        """
        global _reload_event
        if self.is_reloading:
            return False
        if _reload_event is None:
            logger.warning("Перезагрузка недоступна: запустите бота через launcher.py")
            return False
        try:
            self.bot.stop_polling()
            _reload_event.set()
            return True
        except Exception as e:
            logger.error(f"Ошибка запроса перезагрузки: {e}")
            return False


# Экземпляр релоадера создаётся здесь, т.к. класс определён выше в этом же модуле
monolith_reloader = MonolithReloader(bot)


def _store_group_message_for_kom(chat_id: int, from_user: Any, text: str) -> None:
    """Сохраняет сообщение из группы для контекста Кома. Вызывать при каждом текстовом сообщении в группе."""
    if not text or not from_user:
        return
    name = (getattr(from_user, "first_name", None) or getattr(from_user, "username", None) or "?")
    if getattr(from_user, "username", None):
        name = f"{name} (@{from_user.username})"
    with _kom_chat_context_lock:
        if chat_id not in _kom_chat_context:
            _kom_chat_context[chat_id] = deque(maxlen=_KOM_CONTEXT_MAX_MESSAGES)
        _kom_chat_context[chat_id].append({"name": name[:64], "text": (text or "")[:500]})
        # Подрезаем по суммарной длине
        total = sum(len(m["text"]) for m in _kom_chat_context[chat_id])
        while total > _KOM_CONTEXT_MAX_CHARS and len(_kom_chat_context[chat_id]) > 1:
            _kom_chat_context[chat_id].popleft()
            total = sum(len(m["text"]) for m in _kom_chat_context[chat_id])

def _get_group_context_for_kom(chat_id: int) -> str:
    """Возвращает форматированный контекст последних сообщений чата для промпта Кома."""
    with _kom_chat_context_lock:
        messages = list(_kom_chat_context.get(chat_id, []))
    if not messages:
        return ""
    lines = []
    for m in messages[-_KOM_CONTEXT_MAX_MESSAGES:]:
        lines.append(f"  • {m['name']}: {m['text']}")
    return "\n".join(lines)

def _get_chat_title_for_kom(chat_id: int) -> str:
    """Возвращает название чата для контекста Кома (с кэшем)."""
    now = time.time()
    with _kom_chat_context_lock:
        if chat_id in _kom_chat_title_cache:
            title, ts = _kom_chat_title_cache[chat_id]
            if now - ts < _KOM_CHAT_TITLE_CACHE_TTL:
                return title
    try:
        chat = bot.get_chat(chat_id)
        title = getattr(chat, "title", None) or getattr(chat, "first_name", None) or f"Чат {chat_id}"
        with _kom_chat_context_lock:
            _kom_chat_title_cache[chat_id] = (title, now)
        return title
    except Exception as e:
        logger.debug(f"get_chat_title_for_kom({chat_id}): {e}")
        return f"Чат"


def _kom_context_update_listener(new_messages: list) -> None:
    """Вызывается при каждом пачке новых сообщений: сохраняем текст из групп для контекста Кома (бот может быть в разных группах)."""
    if not new_messages:
        return
    for msg in new_messages:
        try:
            if not getattr(msg, "chat", None) or getattr(msg.chat, "type", None) not in ("group", "supergroup"):
                continue
            text = getattr(msg, "text", None)
            if not text or not getattr(msg, "from_user", None):
                continue
            _store_group_message_for_kom(msg.chat.id, msg.from_user, text)
        except Exception as e:
            logger.debug(f"kom context listener: {e}")

