# ============================================================================
# ФУНКЦИИ ДЛЯ РАБОТЫ С КЭШЕМ
# ============================================================================

def cache_set(key: str, value: Any, ttl: Optional[int] = None) -> None:
    """
    Сохраняет значение в кэш.
    
    Args:
        key: Ключ кэша
        value: Значение для сохранения
        ttl: Время жизни в секундах (None = использовать CACHE_TTL)
    """
    if not CACHE_ENABLED:
        return
    
    # Очищаем устаревшие записи если превышен размер
    if len(cache) >= CACHE_MAX_SIZE:
        cleanup_cache()
    
    cache[key] = {
        "value": value,
        "timestamp": time.time()
    }
    cache_timestamps[key] = time.time() + (ttl if ttl is not None else CACHE_TTL)
    
    logger.debug(f"Кэш установлен: {key}")

def cache_get(key: str) -> Optional[Any]:
    """
    Получает значение из кэша.
    
    Args:
        key: Ключ кэша
    
    Returns:
        Optional[Any]: Значение из кэша или None
    """
    if not CACHE_ENABLED:
        return None
    
    try:
        if key not in cache:
            return None
        if time.time() > cache_timestamps.get(key, 0):
            cache.pop(key, None)
            cache_timestamps.pop(key, None)
            return None
        entry = cache.get(key)
        if not isinstance(entry, dict) or "value" not in entry:
            return None
        logger.debug(f"Кэш получен: {key}")
        return entry["value"]
    except KeyError:
        return None

def cache_delete(key: str) -> bool:
    """
    Удаляет значение из кэша.
    
    Args:
        key: Ключ кэша
    
    Returns:
        bool: True если ключ существовал
    """
    try:
        if cache.pop(key, None) is not None:
            cache_timestamps.pop(key, None)
            logger.debug(f"Кэш удалён: {key}")
            return True
    except KeyError:
        pass
    return False

def cache_clear() -> None:
    """Очищает весь кэш."""
    cache.clear()
    cache_timestamps.clear()
    logger.info("Кэш полностью очищен")

def cleanup_cache() -> None:
    """Очищает устаревшие записи кэша."""
    now = time.time()
    expired = [k for k, v in cache_timestamps.items() if now > v]
    for key in expired:
        cache.pop(key, None)
        cache_timestamps.pop(key, None)
    if expired:
        logger.debug(f"Очищено {len(expired)} устаревших записей кэша")


