def _load_user_cities() -> Dict[int, str]:
    """Загружает словарь городов пользователей из JSON. Пустые значения не загружаются — в профиле город по умолчанию показывается как прочерк."""
    try:
        if USER_CITIES_FILE.exists():
            with open(USER_CITIES_FILE, "r", encoding="utf-8") as f:
                raw = json.load(f)
            return {int(k): str(v).strip() for k, v in raw.items() if str(v).strip()}
    except Exception as e:
        logger.warning(f"Не удалось загрузить user_cities: {e}")
    return {}


def _save_user_cities() -> None:
    """Сохраняет словарь городов в JSON."""
    try:
        with open(USER_CITIES_FILE, "w", encoding="utf-8") as f:
            json.dump(user_cities, f, ensure_ascii=False, indent=0)
    except Exception as e:
        logger.warning(f"Не удалось сохранить user_cities: {e}")


user_cities: Dict[int, str] = _load_user_cities()


def get_user_city(user_id: int) -> str:
    """Возвращает город пользователя; по умолчанию пустая строка (в профиле показывается прочерк и подсказка /city)."""
    return user_cities.get(user_id, "")


def set_user_city(user_id: int, city: str) -> None:
    """Устанавливает город пользователя и сохраняет в файл."""
    city = (city or "").strip()
    if not city:
        if user_id in user_cities:
            del user_cities[user_id]
            _save_user_cities()
        return
    user_cities[user_id] = city
    _save_user_cities()


MOSCOW_TZ = ZoneInfo("Europe/Moscow")


def get_moscow_time() -> datetime:
    """Возвращает текущее московское время (MSK, UTC+3). Использовать для отображения времени пользователю."""
    return datetime.now(MOSCOW_TZ)


def get_moscow_time_str() -> Tuple[str, str, str]:
    """Возвращает (время МСК, дата, день недели) для отображения."""
    now_msk = get_moscow_time()
    time_str = now_msk.strftime("%H:%M:%S")
    date_str = now_msk.strftime("%d.%m.%Y")
    weekday_ru = {
        0: "понедельник", 1: "вторник", 2: "среда", 3: "четверг",
        4: "пятница", 5: "суббота", 6: "воскресенье",
    }.get(now_msk.weekday(), "")
    return time_str, date_str, weekday_ru


def get_local_time_str(tz_name: str) -> Tuple[str, str, str]:
    """Возвращает (время, дата, день недели) для заданного часового пояса (например Europe/Berlin)."""
    try:
        z = ZoneInfo(tz_name)
    except Exception:
        return "", "", ""
    now = datetime.now(z)
    time_str = now.strftime("%H:%M:%S")
    date_str = now.strftime("%d.%m.%Y")
    weekday_ru = {
        0: "понедельник", 1: "вторник", 2: "среда", 3: "четверг",
        4: "пятница", 5: "суббота", 6: "воскресенье",
    }.get(now.weekday(), "")
    return time_str, date_str, weekday_ru


# ============================================================================
# ФУНКЦИИ ДЛЯ РАБОТЫ С БАЗАМИ ДАННЫХ
# ============================================================================

@contextmanager
def database_connection(db_path: Path, timeout: int = DB_TIMEOUT):
    """
    Контекстный менеджер для работы с базой данных SQLite.
    
    Args:
        db_path: Путь к файлу базы данных
        timeout: Таймаут подключения в секундах
    
    Yields:
        sqlite3.Connection: Подключение к базе данных
    
    Raises:
        sqlite3.Error: При ошибках работы с БД
    """
    conn = None
    try:
        conn = sqlite3.connect(
            db_path,
            timeout=timeout,
            detect_types=sqlite3.PARSE_DECLTYPES | sqlite3.PARSE_COLNAMES,
            isolation_level=None  # Автокоммит
        )
        conn.row_factory = sqlite3.Row  # Возвращаем строки как словари
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute("PRAGMA journal_mode = WAL")  # Write-Ahead Logging для производительности
        # FULL — гарантированная запись на диск при перезапуске (economy: балансы; users: настройки групп, отношения)
        if db_path in (ECONOMY_DB, USERS_DB):
            conn.execute("PRAGMA synchronous = FULL")
        else:
            conn.execute("PRAGMA synchronous = NORMAL")  # Баланс скорости и надёжности
        conn.execute("PRAGMA cache_size = -20000")  # 20MB кэша
        conn.execute("PRAGMA temp_store = MEMORY")  # Хранить временные таблицы в памяти
        
        logger.debug(f"Подключение к БД {db_path.name} установлено")
        yield conn
        
    except sqlite3.Error as e:
        if "duplicate column" not in str(e).lower():
            logger.error(f"Ошибка SQLite при работе с {db_path.name}: {e}")
        raise
    finally:
        if conn:
            conn.close()
            logger.debug(f"Подключение к БД {db_path.name} закрыто")

def execute_query(db_path: Path, query: str, params: tuple = (), retries: int = DB_RETRY_COUNT) -> Optional[List[sqlite3.Row]]:
    """
    Выполняет SQL запрос с повторными попытками при ошибках.
    
    Args:
        db_path: Путь к базе данных
        query: SQL запрос
        params: Параметры запроса
        retries: Количество попыток
    
    Returns:
        Optional[List[sqlite3.Row]]: Результат запроса или None при ошибке
    """
    def _normalize_sql_param(value: Any) -> Any:
        """Приводит параметры к формату, безопасному для sqlite3 на Python 3.12+."""
        if isinstance(value, datetime):
            return value.isoformat(sep=' ', timespec='seconds')
        if isinstance(value, date):
            return value.isoformat()
        return value
    
    for attempt in range(retries):
        try:
            with database_connection(db_path) as conn:
                normalized_params = tuple(_normalize_sql_param(p) for p in params)
                cursor = conn.execute(query, normalized_params)
                
                # Определяем тип запроса
                query_type = query.strip().upper()[:6]
                
                if query_type == 'SELECT':
                    result = cursor.fetchall()
                    logger.debug(f"Запрос SELECT выполнен: {cursor.rowcount} строк")
                    return result
                if 'RETURNING' in query.upper():
                    result = cursor.fetchall()
                    conn.commit()
                    logger.debug(f"Запрос с RETURNING выполнен: {cursor.rowcount} строк")
                    return result
                conn.commit()
                logger.debug(f"Запрос {query_type} выполнен: {cursor.rowcount} строк изменено")
                return []
                    
        except sqlite3.OperationalError as e:
            err_msg = str(e).lower()
            if "duplicate column" in err_msg:
                # Колонка уже есть (миграция) — не считаем ошибкой
                return []
            if "database is locked" in err_msg and attempt < retries - 1:
                # Меньше блокируем основной поток: короткие бэкоффы
                wait_time = (attempt + 1) * 0.15
                logger.warning(f"БД заблокирована, попытка {attempt + 1}/{retries} через {wait_time}с")
                time.sleep(wait_time)
            else:
                logger.error(f"Ошибка выполнения запроса после {retries} попыток: {e}")
                return None
        except Exception as e:
            logger.error(f"Неожиданная ошибка при выполнении запроса: {e}")
            return None
    
    return None

def execute_many(db_path: Path, query: str, params_list: List[tuple]) -> bool:
    """
    Выполняет множественные вставки/обновления.
    
    Args:
        db_path: Путь к базе данных
        query: SQL запрос
        params_list: Список кортежей параметров
    
    Returns:
        bool: True если успешно
    """
    try:
        with database_connection(db_path) as conn:
            cursor = conn.cursor()
            normalized_params = [
                tuple(
                    p.isoformat(sep=' ', timespec='seconds') if isinstance(p, datetime)
                    else p.isoformat() if isinstance(p, date)
                    else p
                    for p in params
                )
                for params in params_list
            ]
            cursor.executemany(query, normalized_params)
            conn.commit()
            logger.debug(f"Множественный запрос выполнен: {cursor.rowcount} строк")
            return True
    except Exception as e:
        logger.error(f"Ошибка при множественном запросе: {e}")
        return False

def vacuum_database(db_path: Path) -> bool:
    """
    Оптимизирует базу данных (VACUUM).
    
    Args:
        db_path: Путь к базе данных
    
    Returns:
        bool: True если успешно
    """
    try:
        with database_connection(db_path) as conn:
            conn.execute("VACUUM")
            logger.info(f"База данных {db_path.name} оптимизирована")
            return True
    except Exception as e:
        logger.error(f"Ошибка при оптимизации БД {db_path.name}: {e}")
        return False

def backup_database(db_path: Path, compress: bool = BACKUP_COMPRESS) -> Optional[Path]:
    """
    Создаёт резервную копию базы данных.
    
    Args:
        db_path: Путь к базе данных
        compress: Сжимать ли копию
    
    Returns:
        Optional[Path]: Путь к резервной копии или None
    """
    try:
        # Создаём директорию для бэкапов
        BACKUPS_DIR.mkdir(parents=True, exist_ok=True)
        
        # Имя файла с временной меткой
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        backup_name = f"{db_path.stem}_backup_{timestamp}.db"
        backup_path = BACKUPS_DIR / backup_name
        
        # Копируем файл
        shutil.copy2(db_path, backup_path)
        
        # Если нужно сжать
        if compress:
            import gzip
            with open(backup_path, 'rb') as f_in:
                with gzip.open(f"{backup_path}.gz", 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)
            backup_path.unlink()  # Удаляем несжатый файл
            backup_path = Path(f"{backup_path}.gz")
        
        logger.info(f"✅ Создана резервная копия {db_path.name}: {backup_path}")
        return backup_path
        
    except Exception as e:
        logger.error(f"❌ Ошибка создания резервной копии {db_path.name}: {e}")
        return None

