def init_moderation_db() -> None:
    """Инициализирует базу данных модерации."""
    queries = [
        # Таблица предупреждений
        """
        CREATE TABLE IF NOT EXISTS warnings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            chat_id INTEGER NOT NULL,
            reason TEXT NOT NULL,
            admin_id INTEGER NOT NULL,
            date TIMESTAMP NOT NULL,
            expires TIMESTAMP,
            active BOOLEAN DEFAULT 1
        )
        """,
        
        # Индексы для warnings
        "CREATE INDEX IF NOT EXISTS idx_warnings_user ON warnings(user_id, chat_id)",
        "CREATE INDEX IF NOT EXISTS idx_warnings_date ON warnings(date)",
        "CREATE INDEX IF NOT EXISTS idx_warnings_admin ON warnings(admin_id)",
        
        # Таблица мутов
        """
        CREATE TABLE IF NOT EXISTS mutes (
            user_id INTEGER PRIMARY KEY,
            chat_id INTEGER NOT NULL,
            until TIMESTAMP NOT NULL,
            admin_id INTEGER NOT NULL,
            reason TEXT,
            date TIMESTAMP NOT NULL,
            UNIQUE(user_id, chat_id)
        )
        """,
        
        # Индекс для mutes
        "CREATE INDEX IF NOT EXISTS idx_mutes_until ON mutes(until)",
        
        # Таблица банов
        """
        CREATE TABLE IF NOT EXISTS bans (
            user_id INTEGER PRIMARY KEY,
            chat_id INTEGER NOT NULL,
            admin_id INTEGER NOT NULL,
            reason TEXT,
            date TIMESTAMP NOT NULL,
            expires TIMESTAMP,
            UNIQUE(user_id, chat_id)
        )
        """,
        
        # Индекс для bans
        "CREATE INDEX IF NOT EXISTS idx_bans_expires ON bans(expires)",
        
        # Таблица запрещённых слов
        """
        CREATE TABLE IF NOT EXISTS banned_words (
            word TEXT PRIMARY KEY,
            added_by INTEGER,
            added_date TIMESTAMP,
            severity INTEGER DEFAULT 1  -- 1-10, степень серьёзности
        )
        """,
        
        # Таблица логов модерации
        """
        CREATE TABLE IF NOT EXISTS moderation_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action TEXT NOT NULL,  -- warn, mute, ban, kick, unwarn, unmute, unban
            user_id INTEGER NOT NULL,
            admin_id INTEGER NOT NULL,
            chat_id INTEGER NOT NULL,
            reason TEXT,
            details TEXT,  -- JSON с дополнительной информацией
            date TIMESTAMP NOT NULL
        )
        """,
        
        "CREATE INDEX IF NOT EXISTS idx_mod_log_date ON moderation_log(date)",
        "CREATE INDEX IF NOT EXISTS idx_mod_log_user ON moderation_log(user_id)",
        "CREATE INDEX IF NOT EXISTS idx_mod_log_admin ON moderation_log(admin_id)",
        
        # Таблица настроек модерации для чатов
        """
        CREATE TABLE IF NOT EXISTS moderation_settings (
            chat_id INTEGER PRIMARY KEY,
            auto_moderate BOOLEAN DEFAULT 1,
            max_warnings INTEGER DEFAULT 3,
            mute_duration INTEGER DEFAULT 24,
            ban_on_max_warnings BOOLEAN DEFAULT 1,
            profanity_filter BOOLEAN DEFAULT 1,
            filter_strength REAL DEFAULT 0.8,
            updated TIMESTAMP
        )
        """
    ]
    
    for query in queries:
        execute_query(MODERATION_DB, query)
    
    logger.info("✅ База данных модерации инициализирована")

