# ФУНКЦИИ АВТОМАТИЧЕСКИХ БЭКАПОВ
# ============================================================================

def backup_all_databases(compress: bool = BACKUP_COMPRESS) -> Dict[str, Optional[Path]]:
    """
    Создаёт резервные копии всех баз данных.
    
    Args:
        compress: Сжимать ли копии
    
    Returns:
        Dict[str, Optional[Path]]: Словарь с путями к копиям
    """
    logger.info("=" * 50)
    logger.info("СОЗДАНИЕ РЕЗЕРВНЫХ КОПИЙ")
    logger.info("=" * 50)
    
    backups = {}
    db_paths = {
        "moderation": MODERATION_DB,
        "activity": ACTIVITY_DB,
        "message_stats": MESSAGE_STATS_DB,
        "economy": ECONOMY_DB,
        "users": USERS_DB,
        "settings": SETTINGS_FILE
    }
    
    for name, path in db_paths.items():
        if path.exists():
            backup_path = backup_database(path, compress)
            backups[name] = backup_path
    
    # Удаляем старые бэкапы
    cleanup_old_backups()
    
    logger.info("=" * 50)
    logger.info(f"✅ СОЗДАНО {len([b for b in backups.values() if b])} РЕЗЕРВНЫХ КОПИЙ")
    logger.info("=" * 50)
    
    return backups

def cleanup_old_backups() -> int:
    """
    Удаляет старые резервные копии.
    
    Returns:
        int: Количество удалённых файлов
    """
    try:
        # Получаем все файлы бэкапов
        backup_files = []
        for ext in ['*.db', '*.db.gz', '*.json', '*.json.gz']:
            backup_files.extend(BACKUPS_DIR.glob(ext))
        
        # Сортируем по времени создания
        backup_files.sort(key=lambda p: p.stat().st_mtime)
        
        # Удаляем лишние
        deleted = 0
        while len(backup_files) > BACKUP_KEEP_COUNT:
            oldest = backup_files.pop(0)
            oldest.unlink()
            deleted += 1
            logger.debug(f"Удалён старый бэкап: {oldest}")
        
        if deleted:
            logger.info(f"✅ Удалено {deleted} старых резервных копий")
        
        return deleted
        
    except Exception as e:
        logger.error(f"❌ Ошибка при очистке старых бэкапов: {e}")
        return 0

def restore_from_backup(backup_path: Path, target_path: Path) -> bool:
    """
    Восстанавливает базу данных из резервной копии.
    
    Args:
        backup_path: Путь к резервной копии
        target_path: Путь для восстановления
    
    Returns:
        bool: True если успешно
    """
    try:
        # Проверяем существование копии
        if not backup_path.exists():
            logger.error(f"Резервная копия не найдена: {backup_path}")
            return False
        
        # Если копия сжата
        if backup_path.suffix == '.gz':
            import gzip
            with gzip.open(backup_path, 'rb') as f_in:
                with open(target_path, 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)
        else:
            shutil.copy2(backup_path, target_path)
        
        logger.info(f"✅ База данных восстановлена из {backup_path}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка восстановления из бэкапа: {e}")
        return False

def scheduled_backup_worker() -> None:
    """Фоновый процесс для регулярного создания бэкапов."""
    logger.info("🔄 Запущен планировщик резервного копирования")
    
    while True:
        try:
            # Ждём до следующего бэкапа
            if _shutdown_event.wait(timeout=BACKUP_INTERVAL):
                break
            
            if BACKUP_ENABLED:
                logger.info("Запуск планового резервного копирования")
                backup_all_databases()
                
        except Exception as e:
            logger.error(f"Ошибка в планировщике бэкапов: {e}")
            if _shutdown_event.wait(timeout=60):
                break  # Пауза перед повторной попыткой

# Запускаем планировщик бэкапов в отдельном потоке
if BACKUP_ENABLED and not any(t.name == "backup_scheduler" for t in threading.enumerate()):
    backup_thread = threading.Thread(
        target=scheduled_backup_worker,
        daemon=True,
        name="backup_scheduler"
    )
    backup_thread.start()
    logger.info("✅ Планировщик резервного копирования запущен")

