# ФУНКЦИИ АВТОУДАЛЕНИЯ СООБЩЕНИЙ
# ============================================================================

def schedule_deletion(chat_id: int, message_id: int, delay: int = DELETE_DELAY) -> threading.Thread:
    """
    Планирует удаление сообщения через указанное количество секунд.
    
    Args:
        chat_id: ID чата
        message_id: ID сообщения
        delay: Задержка в секундах
    
    Returns:
        threading.Thread: Поток для удаления
    """
    def delete_worker():
        time.sleep(delay)
        try:
            bot.delete_message(chat_id, message_id)
            logger.debug(f"Сообщение {message_id} удалено через {delay}с")
        except Exception as e:
            logger.debug(f"Не удалось удалить сообщение {message_id}: {e}")
    
    thread = threading.Thread(target=delete_worker, daemon=True)
    thread.start()
    return thread

def save_message_id(user_id: int, message_id: int) -> None:
    """
    Сохраняет ID сообщения для последующего удаления.
    
    Args:
        user_id: ID пользователя
        message_id: ID сообщения
    """
    user_messages[user_id].append(message_id)
    
    # Ограничиваем размер списка
    if len(user_messages[user_id]) > MAX_MESSAGES_PER_USER:
        removed = user_messages[user_id].pop(0)
        logger.debug(f"Удалено старое сообщение {removed} из истории пользователя {user_id}")

def delete_user_messages(chat_id: int, user_id: int, keep_last: int = 0) -> int:
    """
    Удаляет все сохранённые сообщения пользователя.
    
    Args:
        chat_id: ID чата
        user_id: ID пользователя
        keep_last: Сколько последних сообщений оставить
    
    Returns:
        int: Количество удалённых сообщений
    """
    if user_id not in user_messages:
        return 0
    
    messages = user_messages[user_id]
    deleted = 0
    
    if keep_last > 0:
        to_delete = messages[:-keep_last]
        user_messages[user_id] = messages[-keep_last:]
    else:
        to_delete = messages
        user_messages[user_id] = []
    
    for msg_id in to_delete:
        try:
            bot.delete_message(chat_id, msg_id)
            deleted += 1
        except Exception as e:
            logger.debug(f"Не удалось удалить сообщение {msg_id}: {e}")
    
    if deleted:
        logger.debug(f"Удалено {deleted} сообщений пользователя {user_id}")
    
    return deleted

def clear_all_user_messages(user_id: int) -> None:
    """
    Очищает всю историю сообщений пользователя без удаления.
    
    Args:
        user_id: ID пользователя
    """
    if user_id in user_messages:
        user_messages[user_id].clear()
        logger.debug(f"История сообщений пользователя {user_id} очищена")


def try_delete_service_notification(message: Message) -> None:
    """
    Пытается удалить системное service-сообщение Telegram (вход/выход, закрепил и т.д.).
    В группах используется настройка группы delete_service_notifications; по умолчанию включено.
    В личке не вызывается. Глобальная настройка DELETE_SERVICE_NOTIFICATIONS — fallback.
    """
    try:
        if not message or not getattr(message, "chat", None):
            return
        if message.chat.type not in ("group", "supergroup"):
            return
        chat_id = message.chat.id
        delete_it = True
        if chat_id < 0:
            gs = get_group_settings(chat_id)
            delete_it = gs.get("delete_service_notifications", True)
        if not delete_it:
            return
        if not DELETE_SERVICE_NOTIFICATIONS:
            return
        bot.delete_message(chat_id, message.message_id)
    except Exception as e:
        logger.debug(f"Не удалось удалить service-уведомление {getattr(message, 'message_id', '?')}: {e}")

