def notify_developer_bot_added_to_group(
    chat_id: int,
    chat_title: str,
    added_by_user_id: int,
    bot_has_admin_rights: bool,
) -> None:
    """Отправляет разработчику уведомление: кто добавил бота в группу и выданы ли права админа."""
    if not ADMIN_CHAT_ID:
        return
    try:
        adder_mention = get_user_mention(added_by_user_id) or f"ID{added_by_user_id}"
        admin_status = "✅ Да" if bot_has_admin_rights else "❌ Нет"
        title_esc = (chat_title or str(chat_id))[:200].replace("<", "&lt;").replace(">", "&gt;")
        text = (
            "🤖 <b>Бот добавлен в группу</b>\n\n"
            f"👥 Группа: <b>{title_esc}</b>\n"
            f"🆔 chat_id: <code>{chat_id}</code>\n"
            f"👤 Добавил: {adder_mention} (ID: <code>{added_by_user_id}</code>)\n"
            f"🛡️ Права админа у бота: <b>{admin_status}</b>"
        )
        bot.send_message(ADMIN_CHAT_ID, text, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as e:
        logger.debug("notify_developer_bot_added_to_group: %s", e)


def notify_developer_bot_admin_rights_changed(chat_id: int, chat_title: str, granted: bool) -> None:
    """Уведомляет разработчика об изменении прав админа у бота в группе (выданы или сняты)."""
    if not ADMIN_CHAT_ID:
        return
    try:
        title_esc = (chat_title or str(chat_id))[:200].replace("<", "&lt;").replace(">", "&gt;")
        if granted:
            text = f"🛡️ <b>Боту выданы права админа</b>\n\n👥 Группа: <b>{title_esc}</b>\n🆔 <code>{chat_id}</code>"
        else:
            text = f"⚠️ <b>У бота сняты права админа</b>\n\n👥 Группа: <b>{title_esc}</b>\n🆔 <code>{chat_id}</code>"
        bot.send_message(ADMIN_CHAT_ID, text, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as e:
        logger.debug("notify_developer_bot_admin_rights_changed: %s", e)


