def migrate_existing_groups() -> None:
    """Переносит существующие группы из group_settings и group_roles в bot_groups, если их там нет."""
    try:
        # Группы из group_settings и group_roles, которых ещё нет в bot_groups (только группы, group_id < 0)
        rows = execute_query(
            USERS_DB,
            """SELECT DISTINCT g.id FROM (
                SELECT group_id AS id FROM group_settings WHERE group_id < 0
                UNION
                SELECT group_id AS id FROM group_roles WHERE group_id < 0
            ) g WHERE g.id NOT IN (SELECT chat_id FROM bot_groups)""",
            (),
        ) or []
        migrated = 0
        for row in rows:
            if not row or row[0] is None:
                continue
            group_id = int(row[0])
            if group_id >= 0:
                continue
            try:
                chat = bot.get_chat(group_id)
                chat_title = getattr(chat, "title", None) or str(group_id)
                save_bot_added_to_group(group_id, 0, chat_title)
                migrated += 1
            except Exception as e:
                logger.debug("Не удалось получить информацию о чате %s: %s", group_id, e)
                save_bot_added_to_group(group_id, 0, str(group_id))
                migrated += 1
        if migrated:
            logger.info("✅ Мигрировано %s групп в bot_groups", migrated)
    except Exception as e:
        logger.error("Ошибка миграции групп в bot_groups: %s", e)


# Вызов после инициализации БД (init_all_databases уже выполнен при загрузке модуля)
migrate_existing_groups()


def save_bot_added_fallback(chat_id: int, chat_title: str, from_user_id: Optional[int]) -> None:
    """
    Запасное сохранение группы при добавлении бота (например из обработчика my_chat_member).
    Вызывать, если new_chat_members не сработал и записи в bot_groups ещё нет.
    """
    if not from_user_id:
        return
    try:
        row = execute_query(USERS_DB, "SELECT 1 FROM bot_groups WHERE chat_id = ? LIMIT 1", (chat_id,))
        if row and len(row) > 0:
            return
        save_bot_added_to_group(chat_id, from_user_id, chat_title or str(chat_id))
        ensure_group_owner_role_and_settings(chat_id, from_user_id)
        logger.info("bot_groups: saved chat_id=%s via fallback, added_by=%s", chat_id, from_user_id)
    except Exception as e:
        logger.debug("save_bot_added_fallback: %s", e)


