# Пять ролей модерации по умолчанию (ранги 1–5): совпадают с rank_names
DEFAULT_ROLE_TITLES = {
    "junior_mod": "Помощник",       # ранг 1
    "moderator": "Модератор",       # ранг 2
    "senior_mod": "Старший модератор",  # ранг 3
    "admin": "Админ",               # ранг 4
    "owner": "Владелец",            # ранг 5
}

# Соответствие уровень ранга (1–5) -> ключ роли для названий
RANK_LEVEL_TO_ROLE_KIND = {1: "junior_mod", 2: "moderator", 3: "senior_mod", 4: "admin", 5: "owner"}

# Ключи переводов для названий ролей (RU/EN)
ROLE_TITLE_I18N_KEYS = {
    "owner": "role_title_owner", "admin": "role_title_admin", "moderator": "role_title_moderator",
    "senior_mod": "role_title_senior_mod", "junior_mod": "role_title_junior_mod",
}


def get_group_role_display_name(chat_id: int, role_kind: str, lang: Optional[str] = None) -> str:
    """Возвращает отображаемое название роли для группы (кастомное из group_settings или по умолчанию). Поддерживает 5 ролей. lang — для перевода умолчаний (ru/en)."""
    if not role_kind:
        return "?"
    rk = (role_kind or "").strip().lower()
    gs = get_group_settings(chat_id)
    col_map = {
        "owner": "owner_role_title", "admin": "admin_role_title", "moderator": "mod_role_title",
        "senior_mod": "senior_mod_role_title", "junior_mod": "junior_mod_role_title",
    }
    if rk in col_map:
        custom = (gs.get(col_map[rk]) or "").strip()
        if custom:
            # Если в БД сохранён ключ перевода (role_title_*) — подставляем перевод, а не показываем ключ
            if custom in list(ROLE_TITLE_I18N_KEYS.values()):
                return t(lang, custom) if lang else DEFAULT_ROLE_TITLES.get(rk, custom)
            return custom
        if lang and rk in ROLE_TITLE_I18N_KEYS:
            return t(lang, ROLE_TITLE_I18N_KEYS[rk])
        return DEFAULT_ROLE_TITLES.get(rk, (role_kind or "?"))
    return DEFAULT_ROLE_TITLES.get(rk, (role_kind or "?"))


def get_group_rank_display_name(chat_id: Optional[int], level: int, lang: Optional[str] = None) -> str:
    """Возвращает отображаемое название ранга (0–5) в контексте группы: кастом из настроек группы или по умолчанию. lang — для перевода (ru/en). Ранг 0 — участник. При chat_id=None — только умолчания по lang."""
    if level == 0 and lang:
        return t(lang, "rank_0_participant")
    role_kind = RANK_LEVEL_TO_ROLE_KIND.get(level)
    if role_kind:
        if chat_id is not None:
            return get_group_role_display_name(chat_id, role_kind, lang=lang)
        if lang and role_kind in ROLE_TITLE_I18N_KEYS:
            return t(lang, ROLE_TITLE_I18N_KEYS[role_kind])
    return get_rank_name(level)


def set_group_role_title(chat_id: int, role_kind: str, title: Optional[str]) -> None:
    """Устанавливает кастомное название роли в группе (все 5 ролей: junior_mod, moderator, senior_mod, admin, owner). title=None или пусто — сброс на умолчание."""
    rk = (role_kind or "").strip().lower()
    col_map = {
        "owner": "owner_role_title", "admin": "admin_role_title", "moderator": "mod_role_title",
        "senior_mod": "senior_mod_role_title", "junior_mod": "junior_mod_role_title",
    }
    if rk not in col_map:
        return
    col = col_map[rk]
    val = (title or "").strip()[:32] if title else None
    try:
        _ensure_group_settings_row(chat_id)
        execute_query(
            USERS_DB,
            f"UPDATE group_settings SET {col} = ?, updated_at = CURRENT_TIMESTAMP WHERE group_id = ?",
            (val, chat_id),
        )
    except Exception as e:
        logger.error("Ошибка установки названия роли %s: %s", rk, e)


def is_feature_enabled_for_chat(chat_id: int, feature: str, user_id: Optional[int] = None) -> bool:
    """
    Проверяет, включена ли функция для чата. В личке всё разрешено. В группе — по features_mode.
    feature: 'ai' (только Ком), 'shop', 'economy', 'games', 'moderation', 'group_admin'.
    В режиме restricted разрешён только 'ai'.
    """
    if chat_id >= 0:
        return True
    if user_id is not None and user_id in DEVELOPER_IDS:
        return True
    gs = get_group_settings(chat_id)
    mode = (gs.get("features_mode") or "full").strip().lower()
    if mode == "full":
        return True
    if mode == "restricted":
        return feature == "ai"
    return False


def require_group_feature(message_or_chat_id, feature: str, user_id: int, from_callback: bool = False, call: Optional[Any] = None) -> bool:
    """Возвращает True, если функция доступна; иначе отправляет сообщение и возвращает False."""
    chat_id = message_or_chat_id if from_callback else getattr(message_or_chat_id, "chat", None) and message_or_chat_id.chat.id
    if chat_id is None:
        return True
    if chat_id >= 0:
        return True
    if is_feature_enabled_for_chat(chat_id, feature, user_id):
        return True
    lang = get_user_language(user_id)
    msg = t(lang, "feature_disabled_in_group") or "❌ Эта функция отключена в данной группе. Доступен только AI (Kom)."
    if from_callback and call is not None:
        try:
            bot.answer_callback_query(call.id, (msg or "❌ Функция отключена.")[:200], show_alert=True)
        except Exception:
            pass
    else:
        try:
            bot.reply_to(message_or_chat_id, msg or "❌ Эта функция отключена в данной группе. Доступен только AI (Kom).")
        except Exception:
            pass
    return False


def set_group_features_mode(chat_id: int, mode: str) -> None:
    """Устанавливает режим функций группы: 'full' (всё) или 'restricted' (только AI)."""
    mode = "restricted" if (mode or "").strip().lower() == "restricted" else "full"
    try:
        execute_query(
            USERS_DB,
            "INSERT INTO group_settings (group_id, updated_at) VALUES (?, CURRENT_TIMESTAMP) ON CONFLICT(group_id) DO NOTHING",
            (chat_id,),
        )
        execute_query(
            USERS_DB,
            "UPDATE group_settings SET features_mode = ?, updated_at = CURRENT_TIMESTAMP WHERE group_id = ?",
            (mode, chat_id),
        )
    except Exception as e:
        logger.debug("set_group_features_mode %s: %s", chat_id, e)


def get_group_admin_ids(chat_id: int) -> List[int]:
    """Список user_id администраторов группы (owner + admin) для отправки расшифровок."""
    if chat_id >= 0:
        return []
    admin_ids: List[int] = []
    try:
        rows = execute_query(
            USERS_DB,
            "SELECT user_id FROM group_roles WHERE group_id = ? AND LOWER(TRIM(role)) IN ('owner', 'admin')",
            (chat_id,),
        ) or []
        admin_ids.extend(int(r[0]) for r in rows if r and r[0])
        creator = get_chat_creator_id(chat_id)
        if creator and creator not in admin_ids:
            admin_ids.append(creator)
        admins = bot.get_chat_administrators(chat_id)
        for adm in admins:
            uid = getattr(adm.user, "id", None)
            if uid and int(uid) not in admin_ids:
                admin_ids.append(int(uid))
    except Exception as e:
        logger.debug("get_group_admin_ids: %s", e)
    return admin_ids


