# ============================================================================
# ФИЛЬТР МАТА (РАСШИРЕННЫЙ)
# ============================================================================

class ProfanityFilter:
    """
    Расширенный фильтр мата с поддержкой:
    - Регулярных выражений
    - Замены символов (а→@, е→3, и т.д.)
    - Разных уровней строгости
    - Исключений
    """
    
    def __init__(self):
        self.words: List[str] = []
        self.patterns: List[re.Pattern] = []
        self.exceptions: List[str] = []
        self.replacement_chars: Dict[str, str] = {
            'а': '[аa@]',
            'б': '[бb6]',
            'в': '[вv]',
            'г': '[гr]',
            'д': '[дd]',
            'е': '[еe3]',
            'ё': '[ёe]',
            'ж': '[ж]',
            'з': '[з3]',
            'и': '[иi1]',
            'й': '[йi]',
            'к': '[кk]',
            'л': '[лl]',
            'м': '[мm]',
            'н': '[нn]',
            'о': '[оo0]',
            'п': '[пp]',
            'р': '[рr]',
            'с': '[сc]',
            'т': '[тt]',
            'у': '[уy]',
            'ф': '[фf]',
            'х': '[хx]',
            'ц': '[цc]',
            'ч': '[ч4]',
            'ш': '[ш]',
            'щ': '[щ]',
            'ъ': '[ъ]',
            'ы': '[ы]',
            'ь': '[ь]',
            'э': '[эe]',
            'ю': '[ю]',
            'я': '[яa]'
        }
        self.load_words()
    
    def load_words(self) -> None:
        """Загружает запрещённые слова из БД."""
        try:
            result = execute_query(
                MODERATION_DB,
                "SELECT word, severity FROM banned_words ORDER BY severity DESC"
            )
            
            if result:
                self.words = [row[0] for row in result]
                self.update_patterns()
                
            logger.info(f"✅ Загружено {len(self.words)} запрещённых слов")
            
        except Exception as e:
            logger.error(f"❌ Ошибка загрузки слов: {e}")
            self.words = []
    
    def add_word(self, word: str, severity: int = 5) -> bool:
        """
        Добавляет слово в фильтр.
        
        Args:
            word: Слово для добавления
            severity: Степень серьёзности (1-10)
        
        Returns:
            bool: True если успешно
        """
        word = word.lower().strip()
        
        if not word:
            return False
        
        try:
            execute_query(
                MODERATION_DB,
                "INSERT INTO banned_words (word, added_by, added_date, severity) VALUES (?, ?, ?, ?)",
                (word, 0, datetime.now(), severity)
            )
            
            self.words.append(word)
            self.update_patterns()
            
            logger.info(f"✅ Добавлено слово в фильтр: {word} (severity: {severity})")
            return True
            
        except sqlite3.IntegrityError:
            logger.warning(f"Слово уже существует: {word}")
            return False
        except Exception as e:
            logger.error(f"❌ Ошибка добавления слова {word}: {e}")
            return False
    
    def remove_word(self, word: str) -> bool:
        """
        Удаляет слово из фильтра.
        
        Args:
            word: Слово для удаления
        
        Returns:
            bool: True если успешно
        """
        word = word.lower().strip()
        
        try:
            execute_query(
                MODERATION_DB,
                "DELETE FROM banned_words WHERE word=?",
                (word,)
            )
            
            if word in self.words:
                self.words.remove(word)
                self.update_patterns()
            
            logger.info(f"✅ Удалено слово из фильтра: {word}")
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка удаления слова {word}: {e}")
            return False
    
    def add_exception(self, word: str) -> None:
        """
        Добавляет слово в исключения (не фильтровать).
        
        Args:
            word: Слово-исключение
        """
        word = word.lower().strip()
        if word not in self.exceptions:
            self.exceptions.append(word)
            logger.info(f"✅ Добавлено исключение: {word}")
    
    def remove_exception(self, word: str) -> None:
        """
        Удаляет слово из исключений.
        
        Args:
            word: Слово-исключение
        """
        word = word.lower().strip()
        if word in self.exceptions:
            self.exceptions.remove(word)
            logger.info(f"✅ Удалено исключение: {word}")
    
    def create_pattern(self, word: str) -> str:
        """
        Создаёт регулярное выражение для слова с учётом замен.
        
        Args:
            word: Исходное слово
        
        Returns:
            str: Регулярное выражение
        """
        pattern = ''
        for char in word.lower():
            if char in self.replacement_chars:
                pattern += self.replacement_chars[char]
            else:
                pattern += re.escape(char)
        
        # Добавляем границы слова
        return r'\b' + pattern + r'\b'
    
    def update_patterns(self) -> None:
        """Обновляет регулярные выражения для всех слов."""
        self.patterns = []
        for word in self.words:
            try:
                pattern = self.create_pattern(word)
                self.patterns.append(re.compile(pattern, re.IGNORECASE))
            except Exception as e:
                logger.error(f"❌ Ошибка создания паттерна для {word}: {e}")
    
    def check(self, text: Optional[str]) -> Tuple[bool, Optional[str], int]:
        """
        Проверяет текст на наличие запрещённых слов.
        
        Args:
            text: Текст для проверки
        
        Returns:
            Tuple[bool, Optional[str], int]: 
                - Есть ли мат
                - Найденное слово
                - Степень серьёзности
        """
        if not text or not PROFANITY_ENABLED:
            return False, None, 0
        
        # Проверяем исключения
        text_lower = text.lower()
        for exception in self.exceptions:
            if exception in text_lower:
                return False, None, 0
        
        # Проверяем паттерны
        for pattern in self.patterns:
            match = pattern.search(text)
            if match:
                # Получаем степень серьёзности
                word = match.group()
                severity = 5  # По умолчанию
                
                # Можно получить из БД, но для скорости используем кэш
                cache_key = f"word_severity_{word}"
                cached = cache_get(cache_key)
                if cached is not None:
                    severity = cached
                
                return True, word, severity
        
        return False, None, 0
    
    def censor(self, text: str, replacement: str = '*') -> str:
        """
        Заменяет запрещённые слова на звёздочки.
        
        Args:
            text: Исходный текст
            replacement: Символ замены
        
        Returns:
            str: Текст с заменёнными словами
        """
        if not text or not PROFANITY_ENABLED:
            return text
        
        result = text
        for pattern in self.patterns:
            result = pattern.sub(lambda m: replacement * len(m.group()), result)
        
        return result
    
    def get_stats(self) -> Dict[str, Any]:
        """
        Возвращает статистику фильтра.
        
        Returns:
            Dict[str, Any]: Статистика
        """
        return {
            "total_words": len(self.words),
            "total_patterns": len(self.patterns),
            "exceptions": len(self.exceptions),
            "enabled": PROFANITY_ENABLED,
            "strength": PROFANITY_FILTER_STRENGTH
        }

# Создаём экземпляр фильтра
profanity_filter = ProfanityFilter()
logger.info(f"✅ Фильтр мата инициализирован: {len(profanity_filter.words)} слов")

# ============================================================================
# СИСТЕМА ПРЕДУПРЕЖДЕНИЙ (WARN)
# ============================================================================

def add_warning(
    user_id: int,
    chat_id: int,
    reason: str,
    admin_id: int,
    expires_days: int = 30
) -> Optional[int]:
    """
    Добавляет предупреждение пользователю.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        reason: Причина предупреждения
        admin_id: ID администратора
        expires_days: Через сколько дней истекает (0 = никогда)
    
    Returns:
        Optional[int]: ID предупреждения или None
    """
    try:
        expires = None
        if expires_days > 0:
            expires = datetime.now() + timedelta(days=expires_days)
        now_iso = datetime.now().isoformat(sep=" ", timespec="seconds")
        exp_iso = expires.isoformat(sep=" ", timespec="seconds") if expires else None
        warning_id = None
        
        try:
            result = execute_query(
                MODERATION_DB,
                """INSERT INTO warnings 
                   (user_id, chat_id, reason, admin_id, date, expires) 
                   VALUES (?, ?, ?, ?, ?, ?)
                   RETURNING id""",
                (user_id, chat_id, reason, admin_id, now_iso, exp_iso)
            )
            if result and len(result) > 0:
                warning_id = result[0][0]
        except Exception:
            pass
        if warning_id is None:
            # SQLite < 3.35 без RETURNING: вставляем и берём last_insert_rowid
            try:
                with database_connection(MODERATION_DB) as conn:
                    cur = conn.execute(
                        """INSERT INTO warnings 
                           (user_id, chat_id, reason, admin_id, date, expires) 
                           VALUES (?, ?, ?, ?, ?, ?)""",
                        (user_id, chat_id, reason, admin_id, now_iso, exp_iso)
                    )
                    conn.commit()
                    warning_id = cur.lastrowid
            except Exception as fallback_e:
                logger.error(f"❌ Ошибка добавления предупреждения: {fallback_e}")
                return None
        
        if warning_id:
            # Логируем действие
            log_moderation_action(
                action="warn",
                user_id=user_id,
                admin_id=admin_id,
                chat_id=chat_id,
                reason=reason,
                details=f"warning_id={warning_id}"
            )
            cache_delete(f"warnings_count_{user_id}_{chat_id}")
            logger.info(f"✅ Предупреждение #{warning_id} выдано пользователю {user_id}")
            return warning_id
        
        return None
        
    except Exception as e:
        logger.error(f"❌ Ошибка добавления предупреждения: {e}")
        return None

def get_warnings_count(user_id: int, chat_id: int, active_only: bool = True) -> int:
    """
    Возвращает количество предупреждений пользователя в конкретной группе (chat_id).

    Args:
        user_id: ID пользователя
        chat_id: ID чата (статистика привязана к этой группе)
        active_only: Только активные (не истекшие)
    
    Returns:
        int: Количество предупреждений
    """
    # Проверяем кэш
    cache_key = f"warnings_count_{user_id}_{chat_id}_{active_only}"
    cached = cache_get(cache_key)
    if cached is not None:
        return cached
    
    try:
        if active_only:
            result = execute_query(
                MODERATION_DB,
                """SELECT COUNT(*) FROM warnings 
                   WHERE user_id=? AND chat_id=? AND active=1 
                   AND (expires IS NULL OR expires > datetime('now'))""",
                (user_id, chat_id)
            )
        else:
            result = execute_query(
                MODERATION_DB,
                "SELECT COUNT(*) FROM warnings WHERE user_id=? AND chat_id=?",
                (user_id, chat_id)
            )
        
        count = result[0][0] if result else 0
        
        # Сохраняем в кэш
        cache_set(cache_key, count, ttl=60)  # 1 минута
        
        return count
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения количества предупреждений: {e}")
        return 0

def get_user_warnings(
    user_id: int,
    chat_id: int,
    limit: int = 20,
    active_only: bool = True
) -> List[Dict[str, Any]]:
    """
    Возвращает список предупреждений пользователя.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        limit: Максимальное количество
        active_only: Только активные
    
    Returns:
        List[Dict[str, Any]]: Список предупреждений
    """
    try:
        if active_only:
            result = execute_query(
                MODERATION_DB,
                """SELECT id, reason, admin_id, date, expires 
                   FROM warnings 
                   WHERE user_id=? AND chat_id=? AND active=1 
                   AND (expires IS NULL OR expires > datetime('now'))
                   ORDER BY date DESC LIMIT ?""",
                (user_id, chat_id, limit)
            )
        else:
            result = execute_query(
                MODERATION_DB,
                """SELECT id, reason, admin_id, date, expires 
                   FROM warnings 
                   WHERE user_id=? AND chat_id=?
                   ORDER BY date DESC LIMIT ?""",
                (user_id, chat_id, limit)
            )
        
        warnings = []
        if result:
            for row in result:
                warnings.append({
                    "id": row[0],
                    "reason": row[1],
                    "admin_id": row[2],
                    "date": row[3],
                    "expires": row[4]
                })
        
        return warnings
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения списка предупреждений: {e}")
        return []

def remove_warning(
    user_id: int,
    chat_id: int,
    warning_id: Optional[int] = None,
    admin_id: Optional[int] = None,
    reason: str = ""
) -> bool:
    """
    Удаляет предупреждение (деактивирует).
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        warning_id: ID предупреждения (None = последнее)
        admin_id: ID администратора
        reason: Комментарий к снятию варна (для лога)
    
    Returns:
        bool: True если успешно
    """
    try:
        if warning_id:
            # Удаляем конкретное предупреждение
            execute_query(
                MODERATION_DB,
                "UPDATE warnings SET active=0 WHERE id=? AND user_id=? AND chat_id=?",
                (warning_id, user_id, chat_id)
            )
            removed_id = warning_id
        else:
            # Удаляем последнее предупреждение
            result = execute_query(
                MODERATION_DB,
                """SELECT id FROM warnings 
                   WHERE user_id=? AND chat_id=? AND active=1 
                   ORDER BY date DESC LIMIT 1""",
                (user_id, chat_id)
            )
            
            if result:
                removed_id = result[0][0]
                execute_query(
                    MODERATION_DB,
                    "UPDATE warnings SET active=0 WHERE id=?",
                    (removed_id,)
                )
            else:
                return False
        
        # Логируем действие
        if admin_id:
            log_moderation_action(
                action="unwarn",
                user_id=user_id,
                admin_id=admin_id,
                chat_id=chat_id,
                reason=reason,
                details=f"warning_id={removed_id}"
            )
        
        # Очищаем кэш
        cache_delete(f"warnings_count_{user_id}_{chat_id}")
        
        logger.info(f"✅ Предупреждение #{removed_id} удалено")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка удаления предупреждения: {e}")
        return False

def clear_old_warnings() -> int:
    """
    Удаляет устаревшие предупреждения.
    
    Returns:
        int: Количество удалённых
    """
    try:
        result = execute_query(
            MODERATION_DB,
            "UPDATE warnings SET active=0 WHERE expires < datetime('now')"
        )
        
        # Очищаем кэш (лучше перебором, но для простоты сбросим всё)
        for key in list(cache.keys()):
            if key.startswith("warnings_count_"):
                cache_delete(key)
        
        logger.info(f"✅ Устаревшие предупреждения очищены")
        return result[0][0] if result else 0
        
    except Exception as e:
        logger.error(f"❌ Ошибка очистки предупреждений: {e}")
        return 0

# ============================================================================
# ПРОВЕРКА ПРАВ БОТА В ЧАТЕ (для модерации)
# ============================================================================

def bot_has_restrict_rights(chat_id: int) -> Tuple[bool, str]:
    """Проверяет, что бот в чате имеет право ограничивать участников (мут). Возвращает (ok, сообщение_об_ошибке)."""
    try:
        me = bot.get_me()
        member = bot.get_chat_member(chat_id, me.id)
        status = getattr(member, "status", "") or ""
        if status == "creator":
            return True, ""
        if status != "administrator":
            return False, "❌ Бот не является администратором чата. Добавьте бота в админы с правом «Ограничивать участников»."
        if getattr(member, "can_restrict_members", False):
            return True, ""
        return False, "❌ У бота нет права «Ограничивать участников». Выдайте это право в настройках чата."
    except Exception as e:
        logger.debug("bot_has_restrict_rights: %s", e)
        return False, "❌ Не удалось проверить права бота в чате."

def bot_has_ban_rights(chat_id: int) -> Tuple[bool, str]:
    """Проверяет, что бот в чате имеет право банить. Возвращает (ok, сообщение_об_ошибке)."""
    try:
        me = bot.get_me()
        member = bot.get_chat_member(chat_id, me.id)
        status = getattr(member, "status", "") or ""
        if status == "creator":
            return True, ""
        if status != "administrator":
            return False, "❌ Бот не является администратором чата. Добавьте бота в админы с правом «Удалять участников»."
        if getattr(member, "can_restrict_members", False) or getattr(member, "can_ban_users", False):
            return True, ""
        return False, "❌ У бота нет права банить/удалять участников. Выдайте это право в настройках чата."
    except Exception as e:
        logger.debug("bot_has_ban_rights: %s", e)
        return False, "❌ Не удалось проверить права бота в чате."

# ============================================================================
# СИСТЕМА МУТОВ (MUTE)
# ============================================================================

def set_mute(
    user_id: int,
    chat_id: int,
    duration_minutes: int,
    admin_id: int,
    reason: str = ""
) -> bool:
    """
    Отправляет пользователя в мут.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        duration_minutes: Длительность в минутах (например 60 = 1 час)
        admin_id: ID администратора
        reason: Причина мута
    
    Returns:
        bool: True если успешно
    """
    try:
        until = datetime.now() + timedelta(minutes=duration_minutes)

        # Применяем мут через Telegram API
        bot.restrict_chat_member(
            chat_id,
            user_id,
            until_date=until,
            can_send_messages=False,
            can_send_media_messages=False,
            can_send_other_messages=False,
            can_add_web_page_previews=False
        )

        # Сохраняем в БД только если API вызов успешен
        execute_query(
            MODERATION_DB,
            """INSERT OR REPLACE INTO mutes 
               (user_id, chat_id, until, admin_id, reason, date) 
               VALUES (?, ?, ?, ?, ?, ?)""",
            (user_id, chat_id, until, admin_id, reason, datetime.now())
        )

        # Логируем
        log_moderation_action(
            action="mute",
            user_id=user_id,
            admin_id=admin_id,
            chat_id=chat_id,
            reason=reason,
            details=f"duration={duration_minutes}min, until={until}"
        )
        
        # Очищаем кэш
        cache_delete(f"is_muted_{user_id}_{chat_id}")
        
        logger.info(f"✅ Пользователь {user_id} замучен на {duration_minutes} мин")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка мута пользователя {user_id}: {e}")
        return False

def remove_mute(user_id: int, chat_id: int, admin_id: Optional[int] = None, reason: str = "") -> bool:
    """
    Снимает мут с пользователя.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        admin_id: ID администратора
        reason: Комментарий к размуту (для лога)
    
    Returns:
        bool: True если успешно
    """
    try:
        # Снимаем ограничения через Telegram API
        bot.restrict_chat_member(
            chat_id,
            user_id,
            can_send_messages=True,
            can_send_media_messages=True,
            can_send_other_messages=True,
            can_add_web_page_previews=True
        )

        # Удаляем из БД только если API вызов успешен
        execute_query(
            MODERATION_DB,
            "DELETE FROM mutes WHERE user_id=? AND chat_id=?",
            (user_id, chat_id)
        )
        
        # Логируем
        if admin_id:
            log_moderation_action(
                action="unmute",
                user_id=user_id,
                admin_id=admin_id,
                chat_id=chat_id,
                reason=reason
            )
        
        # Очищаем кэш
        cache_delete(f"is_muted_{user_id}_{chat_id}")
        
        logger.info(f"✅ Мут снят с пользователя {user_id}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка снятия мута с {user_id}: {e}")
        return False

def is_muted(user_id: int, chat_id: int) -> bool:
    """
    Проверяет, находится ли пользователь в муте.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
    
    Returns:
        bool: True если в муте
    """
    # Проверяем кэш
    cache_key = f"is_muted_{user_id}_{chat_id}"
    cached = cache_get(cache_key)
    if cached is not None:
        return cached
    
    try:
        result = execute_query(
            MODERATION_DB,
            "SELECT until FROM mutes WHERE user_id=? AND chat_id=? AND until > datetime('now')",
            (user_id, chat_id)
        )
        
        is_muted_flag = bool(result)
        
        # Сохраняем в кэш
        cache_set(cache_key, is_muted_flag, ttl=30)  # 30 секунд
        
        return is_muted_flag
        
    except Exception as e:
        logger.error(f"❌ Ошибка проверки мута: {e}")
        return False

