def cleanup_expired_mutes() -> int:
    """
    Очищает истёкшие муты.
    
    Returns:
        int: Количество очищенных
    """
    try:
        # Получаем истёкшие муты
        result = execute_query(
            MODERATION_DB,
            "SELECT user_id, chat_id FROM mutes WHERE until <= datetime('now')"
        )
        
        if result:
            for user_id, chat_id in result:
                # Снимаем ограничения
                try:
                    bot.restrict_chat_member(
                        chat_id,
                        user_id,
                        can_send_messages=True,
                        can_send_media_messages=True,
                        can_send_other_messages=True,
                        can_add_web_page_previews=True
                    )
                except Exception:
                    pass
                
                # Удаляем из БД
                execute_query(
                    MODERATION_DB,
                    "DELETE FROM mutes WHERE user_id=? AND chat_id=?",
                    (user_id, chat_id)
                )
                
                cache_delete(f"is_muted_{user_id}_{chat_id}")
        
        count = len(result) if result else 0
        logger.info(f"✅ Очищено {count} истёкших мутов")
        return count
        
    except Exception as e:
        logger.error(f"❌ Ошибка очистки мутов: {e}")
        return 0

