# ============================================================================
# ЛОГИРОВАНИЕ ДЕЙСТВИЙ МОДЕРАЦИИ
# ============================================================================

def log_moderation_action(
    action: str,
    user_id: int,
    admin_id: Optional[int] = None,
    chat_id: Optional[int] = None,
    reason: str = "",
    details: str = ""
) -> bool:
    """
    Логирует действие модерации.
    
    Args:
        action: Тип действия (warn, mute, ban, etc.)
        user_id: ID целевого пользователя
        admin_id: ID администратора
        chat_id: ID чата
        reason: Причина
        details: Дополнительные детали (JSON)
    
    Returns:
        bool: True если успешно
    """
    try:
        execute_query(
            MODERATION_DB,
            """INSERT INTO moderation_log 
               (action, user_id, admin_id, chat_id, reason, details, date) 
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (action, user_id, admin_id, chat_id, reason, details, datetime.now())
        )
        
        # Также логируем в файл
        log_msg = f"MODERATION: {action} | user={user_id}"
        if admin_id:
            log_msg += f" | admin={admin_id}"
        if chat_id:
            log_msg += f" | chat={chat_id}"
        if reason:
            log_msg += f" | reason={reason}"
        if details:
            log_msg += f" | details={details}"
        
        logger.info(log_msg)
        
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка логирования действия {action}: {e}")
        return False

def get_moderation_logs(
    limit: int = 100,
    user_id: Optional[int] = None,
    admin_id: Optional[int] = None,
    chat_id: Optional[int] = None,
    action: Optional[str] = None,
    days: int = 7
) -> List[Dict[str, Any]]:
    """
    Получает логи модерации.
    
    Args:
        limit: Максимальное количество записей
        user_id: Фильтр по пользователю
        admin_id: Фильтр по администратору
        chat_id: Фильтр по чату
        action: Фильтр по действию
        days: За сколько дней
    
    Returns:
        List[Dict[str, Any]]: Список логов
    """
    try:
        query = """SELECT action, user_id, admin_id, chat_id, reason, details, date 
                   FROM moderation_log 
                   WHERE date > datetime('now', ?)"""
        params = [f"-{days} days"]
        
        if user_id:
            query += " AND user_id=?"
            params.append(user_id)
        
        if admin_id:
            query += " AND admin_id=?"
            params.append(admin_id)
        
        if chat_id is not None:
            query += " AND chat_id=?"
            params.append(chat_id)
        
        if action:
            query += " AND action=?"
            params.append(action)
        
        query += " ORDER BY date DESC LIMIT ?"
        params.append(limit)
        
        result = execute_query(MODERATION_DB, query, tuple(params))
        
        logs = []
        if result:
            for row in result:
                logs.append({
                    "action": row[0],
                    "user_id": row[1],
                    "admin_id": row[2],
                    "chat_id": row[3],
                    "reason": row[4],
                    "details": row[5],
                    "date": row[6]
                })
        
        return logs
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения логов: {e}")
        return []

# ============================================================================
# УПРАВЛЕНИЕ ЗАПРЕЩЁННЫМИ СЛОВАМИ
# ============================================================================

def get_banned_words() -> List[Dict[str, Any]]:
    """
    Возвращает список запрещённых слов.
    
    Returns:
        List[Dict[str, Any]]: Список слов с метаданными
    """
    try:
        result = execute_query(
            MODERATION_DB,
            "SELECT word, added_by, added_date, severity FROM banned_words ORDER BY severity DESC, word"
        )
        
        words = []
        if result:
            for row in result:
                words.append({
                    "word": row[0],
                    "added_by": row[1],
                    "added_date": row[2],
                    "severity": row[3]
                })
        
        return words
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения списка слов: {e}")
        return []

def update_word_severity(word: str, severity: int) -> bool:
    """
    Обновляет степень серьёзности слова.
    
    Args:
        word: Слово
        severity: Новая степень (1-10)
    
    Returns:
        bool: True если успешно
    """
    try:
        execute_query(
            MODERATION_DB,
            "UPDATE banned_words SET severity=? WHERE word=?",
            (severity, word.lower())
        )
        
        # Обновляем фильтр
        profanity_filter.load_words()
        
        logger.info(f"✅ Степень слова '{word}' изменена на {severity}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка обновления степени слова: {e}")
        return False

# ============================================================================
# КИК ПОЛЬЗОВАТЕЛЯ
# ============================================================================

def kick_user(
    user_id: int,
    chat_id: int,
    admin_id: int,
    reason: str = ""
) -> bool:
    """
    Выгоняет пользователя из чата (кик).
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
        admin_id: ID администратора
        reason: Причина
    
    Returns:
        bool: True если успешно
    """
    try:
        # Баним и сразу разбаниваем (кик)
        bot.ban_chat_member(chat_id, user_id)
        bot.unban_chat_member(chat_id, user_id)
        
        # Логируем
        log_moderation_action(
            action="kick",
            user_id=user_id,
            admin_id=admin_id,
            chat_id=chat_id,
            reason=reason
        )
        
        logger.info(f"✅ Пользователь {user_id} выгнан из чата {chat_id}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка кика пользователя {user_id}: {e}")
        return False

# ============================================================================
# ОЧИСТКА СООБЩЕНИЙ
# ============================================================================

def clear_messages(
    chat_id: int,
    user_id: Optional[int] = None,
    limit: int = 100
) -> int:
    """
    Очищает сообщения в чате.
    
    Args:
        chat_id: ID чата
        user_id: ID пользователя (None = все)
        limit: Максимальное количество
    
    Returns:
        int: Количество удалённых сообщений
    """
    deleted = 0
    limit = max(1, min(limit, 500))

    try:
        if user_id is not None:
            result = execute_query(
                USERS_DB,
                """SELECT details
                   FROM user_history
                   WHERE user_id=? AND action='message'
                   ORDER BY date DESC
                   LIMIT ?""",
                (user_id, limit),
            ) or []
        else:
            result = execute_query(
                USERS_DB,
                """SELECT details
                   FROM user_history
                   WHERE action='message'
                   ORDER BY date DESC
                   LIMIT ?""",
                (limit,),
            ) or []

        for row in result:
            details_raw = row[0]
            if not details_raw:
                continue
            try:
                details = json.loads(details_raw)
                msg_id = details.get("message_id")
            except Exception:
                continue

            if not msg_id:
                continue

            try:
                bot.delete_message(chat_id, int(msg_id))
                deleted += 1
            except Exception:
                continue

        return deleted
    except Exception as e:
        logger.error(f"Ошибка clear_messages: {e}")
        return deleted

