#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Telegram Bot для управления чатом
Часть 3: Экономика (базовые функции)
Версия: 3.0 (Полная)

Эта часть содержит:
- Управление балансом пользователей
- Система транзакций
- Переводы монет между пользователями
- История операций
- Статистика экономики
- Топы богачей
- Кэширование для производительности
"""

# ============================================================================
# ПОДКЛЮЧЕНИЕ К ЧАСТЯМ 1-2
# ============================================================================

# Эта часть должна быть добавлена после Частей 1 и 2
# Все базовые функции уже есть в предыдущих частях

# ============================================================================
# БАЗОВЫЕ ФУНКЦИИ ЭКОНОМИКИ
# ============================================================================

def register_user(user_id: int) -> bool:
    """
    Регистрирует пользователя в экономической системе.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        bool: True если успешно или пользователь уже существует
    """
    if is_excluded_bot_user(user_id):
        logger.debug(f"Пользователь {user_id} пропущен в экономике (бот)")
        return False

    try:
        # Проверяем, существует ли пользователь
        result = execute_query(
            ECONOMY_DB,
            "SELECT user_id FROM users WHERE user_id=?",
            (user_id,)
        )
        
        if result:
            # Пользователь уже существует
            logger.debug(f"Пользователь {user_id} уже зарегистрирован в экономике")
            return True
        
        # Регистрируем нового пользователя
        now = datetime.now()
        execute_query(
            ECONOMY_DB,
            """INSERT INTO users 
               (user_id, balance, total_earned, total_spent, games_played, games_won, 
                daily_streak, registered, last_seen) 
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (user_id, COINS_START_BALANCE, 0, 0, 0, 0, 0, now, now)
        )
        
        logger.info(f"✅ Новый пользователь {user_id} зарегистрирован в экономике")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка регистрации пользователя {user_id}: {e}")
        return False

def get_balance(user_id: int, use_cache: bool = True) -> int:
    """
    Возвращает баланс пользователя.
    
    Args:
        user_id: ID пользователя
        use_cache: Использовать кэш
    
    Returns:
        int: Текущий баланс
    """
    if is_excluded_bot_user(user_id):
        return 0

    # Проверяем кэш
    if use_cache:
        cache_key = f"balance_{user_id}"
        cached = cache_get(cache_key)
        if cached is not None:
            return cached
    
    try:
        # Пробуем получить баланс из БД
        result = execute_query(
            ECONOMY_DB,
            "SELECT balance FROM users WHERE user_id=?",
            (user_id,)
        )
        
        if result:
            balance = result[0][0]
        else:
            # Пользователь не найден - регистрируем
            register_user(user_id)
            balance = COINS_START_BALANCE
        
        # Сохраняем в кэш
        if use_cache:
            cache_set(cache_key, balance, ttl=30)  # 30 секунд
        
        return balance
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения баланса {user_id}: {e}")
        return 0


def verify_user_balance(user_id: int) -> bool:
    """Проверяет, что баланс пользователя сохранён в БД (для диагностики)."""
    balance = get_balance(user_id, use_cache=False)
    if balance < 0:
        logger.warning("Баланс пользователя %s отрицательный: %s", user_id, balance)
        return False
    if balance < COINS_START_BALANCE and user_id not in DEVELOPER_IDS:
        logger.debug("Баланс пользователя %s ниже стартового: %s", user_id, balance)
    return True


def set_balance(
    user_id: int,
    new_balance: int,
    reason: str = "",
    admin_id: Optional[int] = None
) -> bool:
    """
    Устанавливает точный баланс пользователя.
    
    Args:
        user_id: ID пользователя
        new_balance: Новый баланс
        reason: Причина изменения
        admin_id: ID администратора
    
    Returns:
        bool: True если успешно
    """
    if new_balance < 0:
        logger.warning(f"Попытка установить отрицательный баланс {user_id}: {new_balance}")
        return False
    if is_excluded_bot_user(user_id):
        logger.warning(f"Попытка установить баланс боту {user_id}")
        return False
    
    try:
        # Получаем старый баланс
        old_balance = get_balance(user_id, use_cache=False)
        
        # Обновляем баланс
        execute_query(
            ECONOMY_DB,
            "UPDATE users SET balance=? WHERE user_id=?",
            (new_balance, user_id)
        )
        
        # Записываем транзакцию
        amount_diff = new_balance - old_balance
        if amount_diff != 0:
            record_transaction(
                from_id=admin_id or 0,
                to_id=user_id,
                amount=amount_diff,
                reason=reason or "Установка баланса",
                transaction_type="admin_set"
            )
        
        # Обновляем статистику
        if amount_diff > 0:
            update_total_earned(user_id, amount_diff)
        elif amount_diff < 0:
            update_total_spent(user_id, -amount_diff)
        
        # Очищаем кэш
        cache_delete(f"balance_{user_id}")
        try:
            with database_connection(ECONOMY_DB) as conn:
                conn.execute("PRAGMA wal_checkpoint(FULL)")
        except Exception as e:
            logger.debug("wal_checkpoint после set_balance: %s", e)
        logger.info(f"✅ Баланс пользователя {user_id} изменён с {old_balance} на {new_balance}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка установки баланса {user_id}: {e}")
        return False

def add_coins(
    user_id: int,
    amount: int,
    reason: str = "",
    admin_id: Optional[int] = None,
    transaction_type: Optional[str] = None,
) -> bool:
    """
    Добавляет монеты пользователю.
    
    Args:
        user_id: ID пользователя
        amount: Количество монет
        reason: Причина начисления
        admin_id: ID администратора (если выдаёт админ)
        transaction_type: Тип транзакции (referral, system, admin_give и т.д.); если None — выводится по admin_id
    
    Returns:
        bool: True если успешно
    """
    if amount <= 0:
        logger.warning(f"Попытка добавить неположительное количество монет: {amount}")
        return False
    if is_excluded_bot_user(user_id):
        logger.debug(f"Начисление монет боту {user_id} пропущено")
        return False
    
    try:
        # Гарантируем, что пользователь существует (иначе UPDATE ничего не изменит)
        register_user(user_id)

        # Атомарное начисление: избегаем гонок при параллельных запросах
        try:
            with database_connection(ECONOMY_DB) as conn:
                cur = conn.execute(
                    "UPDATE users SET balance = balance + ?, total_earned = total_earned + ? WHERE user_id = ?",
                    (amount, amount, user_id),
                )
                if cur.rowcount <= 0:
                    logger.error(f"❌ add_coins: не удалось обновить баланс user_id={user_id}")
                    return False
                conn.commit()
        except Exception as e:
            logger.error(f"❌ add_coins: сбой БД при обновлении баланса user_id={user_id}: {e}")
            return False

        # Записываем транзакцию
        tx_type = transaction_type or ("admin_give" if admin_id else "system")
        record_transaction(
            from_id=admin_id or 0,
            to_id=user_id,
            amount=amount,
            reason=reason or "Начисление монет",
            transaction_type=tx_type,
        )
        
        # Обновляем время последнего действия
        update_last_seen(user_id)
        
        # Очищаем кэш
        cache_delete(f"balance_{user_id}")
        # Принудительная запись WAL в основной файл БД, чтобы баланс сохранялся после перезапуска
        try:
            with database_connection(ECONOMY_DB) as conn:
                conn.execute("PRAGMA wal_checkpoint(FULL)")
        except Exception as e:
            logger.debug("wal_checkpoint после add_coins: %s", e)
        
        logger.info(f"✅ Пользователю {user_id} добавлено {amount} монет. Причина: {reason}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка добавления монет {user_id}: {e}")
        return False


def get_referrer_id(user_id: int) -> Optional[int]:
    """Возвращает user_id пригласившего (реферера) или None."""
    try:
        row = execute_query(ECONOMY_DB, "SELECT referred_by FROM users WHERE user_id = ?", (user_id,))
        if row and row[0] and row[0][0] is not None:
            return int(row[0][0])
    except Exception:
        pass
    return None


def commission_amount(amount: int, percent: int) -> int:
    """Единый расчёт суммы комиссии: max(1, amount * percent / 100)."""
    if amount <= 0 or percent <= 0:
        return 0
    return max(1, int(amount * percent / 100))


def set_referrer(user_id: int, referrer_id: int) -> bool:
    """Сохраняет пригласившего для пользователя (только если referred_by ещё не задан)."""
    if user_id == referrer_id or referrer_id <= 0:
        return False
    try:
        with database_connection(ECONOMY_DB) as conn:
            conn.execute(
                "UPDATE users SET referred_by = ? WHERE user_id = ? AND (referred_by IS NULL OR referred_by = 0)",
                (referrer_id, user_id),
            )
            conn.commit()
            return True
    except Exception as e:
        logger.debug("set_referrer: %s", e)
        return False


def get_bot_pm_link() -> str:
    """Ссылка на бота в личку (для кнопки «Сменить роль в личке» и т.п.)."""
    try:
        me = bot.get_me()
        uname = (me.username or "").strip() or "YourBot"
        return f"https://t.me/{uname}"
    except Exception:
        return "https://t.me/YourBot"


def get_referral_link(referrer_id: int) -> str:
    """Возвращает реферальную ссылку для пользователя: t.me/BOT?start=ref_REFERRER_ID."""
    try:
        me = bot.get_me()
        uname = (me.username or "").strip() or "YourBot"
        return f"https://t.me/{uname}?start=ref_{referrer_id}"
    except Exception:
        return f"https://t.me/YourBot?start=ref_{referrer_id}"


def get_referrals_list(referrer_id: int, limit: int = 50) -> List[Dict[str, Any]]:
    """Список пользователей, приглашённых данным реферером (user_id, balance для отображения)."""
    try:
        rows = execute_query(
            ECONOMY_DB,
            "SELECT user_id, balance FROM users WHERE referred_by = ? ORDER BY user_id LIMIT ?",
            (referrer_id, limit),
        )
        if not rows:
            return []
        return [{"user_id": int(r[0]), "balance": int(r[1]) if r[1] is not None else 0} for r in rows]
    except Exception as e:
        logger.debug("get_referrals_list: %s", e)
        return []


def get_referral_earnings(referrer_id: int) -> int:
    """Сумма начисленных реферальных комиссий пользователю (транзакции type=referral, to_id=referrer_id)."""
    try:
        row = execute_query(
            ECONOMY_DB,
            "SELECT COALESCE(SUM(amount), 0) FROM transactions WHERE to_id = ? AND type = 'referral'",
            (referrer_id,),
        )
        return int(row[0][0]) if row and row[0][0] is not None else 0
    except Exception as e:
        logger.debug("get_referral_earnings: %s", e)
        return 0


def _apply_referral_commission(buyer_id: int, coins_purchased: int) -> None:
    """Начисляет пригласившему процент с покупки монет рефералом (процент задаётся в настройках экономики)."""
    if coins_purchased <= 0:
        return
    global REFERRAL_COMMISSION_PERCENT
    if REFERRAL_COMMISSION_PERCENT <= 0:
        return
    referrer_id = get_referrer_id(buyer_id)
    if not referrer_id or referrer_id == buyer_id:
        return
    commission = commission_amount(coins_purchased, REFERRAL_COMMISSION_PERCENT)
    try:
        add_coins(referrer_id, commission, f"Реферальные отчисления с покупки (реферал {buyer_id})", admin_id=None, transaction_type="referral")
        cache_delete(f"balance_{referrer_id}")
        ref_lang = get_user_language(referrer_id)
        msg = (
            f"💰 С покупки вашего реферала вам начислено {commission} {COM_EMOJI} ({REFERRAL_COMMISSION_PERCENT}%)."
            if ref_lang == "ru"
            else f"💰 Referral commission: +{commission} {COM_EMOJI} ({REFERRAL_COMMISSION_PERCENT}% of referral's purchase)."
        )
        bot.send_message(referrer_id, "✅ " + msg)
    except Exception as e:
        logger.debug("_apply_referral_commission: %s", e)


def _apply_developer_commission(buyer_id: int, coins_purchased: int) -> None:
    """Начисляет разработчику (ADMIN_CHAT_ID) процент с покупки монет в боте. Все покупки проходят только в боте."""
    if coins_purchased <= 0:
        return
    global DEVELOPER_COMMISSION_PERCENT
    if DEVELOPER_COMMISSION_PERCENT <= 0:
        return
    dev_id = ADMIN_CHAT_ID
    if not dev_id or dev_id == buyer_id:
        return
    commission = commission_amount(coins_purchased, DEVELOPER_COMMISSION_PERCENT)
    try:
        add_coins(dev_id, commission, f"Комиссия с покупки монет (покупатель {buyer_id})", admin_id=None)
        cache_delete(f"balance_{dev_id}")
        logger.info(f"Комиссия разработчика: +{commission} {COM_EMOJI} с покупки {buyer_id} ({DEVELOPER_COMMISSION_PERCENT}%)")
    except Exception as e:
        logger.debug("_apply_developer_commission: %s", e)


def apply_purchase_commissions(buyer_id: int, coins_purchased: int) -> None:
    """Распределяет комиссионные с покупки монет в боте: рефереру и разработчику. Вызывать после начисления монет покупателю."""
    _apply_referral_commission(buyer_id, coins_purchased)
    _apply_developer_commission(buyer_id, coins_purchased)


def remove_coins(
    user_id: int,
    amount: int,
    reason: str = "",
    admin_id: Optional[int] = None
) -> bool:
    """
    Забирает монеты у пользователя.
    
    Args:
        user_id: ID пользователя
        amount: Количество монет
        reason: Причина списания
        admin_id: ID администратора
    
    Returns:
        bool: True если успешно и достаточно средств
    """
    if amount <= 0:
        logger.warning(f"Попытка снять неположительное количество монет: {amount}")
        return False
    if is_excluded_bot_user(user_id):
        logger.warning(f"Попытка списания монет у бота {user_id}")
        return False
    
    try:
        # Гарантируем, что пользователь существует
        register_user(user_id)

        # Атомарное списание: одно выражение UPDATE с условием balance >= amount
        try:
            with database_connection(ECONOMY_DB) as conn:
                cur = conn.execute(
                    "UPDATE users SET balance = balance - ?, total_spent = total_spent + ? "
                    "WHERE user_id = ? AND balance >= ?",
                    (amount, amount, user_id, amount),
                )
                if cur.rowcount <= 0:
                    # Недостаточно средств (или пользователь не найден, но register_user должен был создать)
                    return False
                conn.commit()
        except Exception as e:
            logger.error(f"❌ remove_coins: сбой БД при обновлении баланса user_id={user_id}: {e}")
            return False

        # Записываем транзакцию
        record_transaction(
            from_id=user_id,
            to_id=admin_id or 0,
            amount=-amount,
            reason=reason or "Списание монет",
            transaction_type="admin_take" if admin_id else "system"
        )
        
        # Обновляем время последнего действия
        update_last_seen(user_id)
        
        # Очищаем кэш
        cache_delete(f"balance_{user_id}")
        try:
            with database_connection(ECONOMY_DB) as conn:
                conn.execute("PRAGMA wal_checkpoint(FULL)")
        except Exception as e:
            logger.debug("wal_checkpoint после remove_coins: %s", e)
        logger.info(f"✅ У пользователя {user_id} снято {amount} монет. Причина: {reason}")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка снятия монет {user_id}: {e}")
        return False


def get_withdrawal_limits(user_id: int) -> Dict[str, Any]:
    """Возвращает лимиты вывода для пользователя; создаёт запись с дефолтами при отсутствии."""
    ensure_withdrawal_limits_reset(user_id)
    with database_connection(ECONOMY_DB) as conn:
        row = conn.execute(
            "SELECT daily_limit_com, monthly_limit_com, daily_used_com, monthly_used_com, "
            "last_daily_reset, last_monthly_reset, verified_level, total_withdrawn_com, "
            "total_trades, successful_trades, dispute_count, rating FROM user_withdrawal_limits WHERE user_id = ?",
            (user_id,)
        ).fetchone()
        if row:
            return {
                "daily_limit_com": row[0], "monthly_limit_com": row[1],
                "daily_used_com": row[2], "monthly_used_com": row[3],
                "last_daily_reset": row[4], "last_monthly_reset": row[5],
                "verified_level": row[6], "total_withdrawn_com": row[7],
                "total_trades": row[8], "successful_trades": row[9],
                "dispute_count": row[10], "rating": row[11],
            }
        conn.execute(
            "INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)",
            (user_id,)
        )
        conn.commit()
    return get_withdrawal_limits(user_id)


def ensure_withdrawal_limits_reset(user_id: int) -> None:
    """Сбрасывает daily_used_com/monthly_used_com при смене дня/месяца."""
    today = date.today().isoformat()
    month_start = today[:7] + "-01"
    with database_connection(ECONOMY_DB) as conn:
        row = conn.execute(
            "SELECT last_daily_reset, last_monthly_reset FROM user_withdrawal_limits WHERE user_id = ?",
            (user_id,)
        ).fetchone()
        if not row:
            return
        if row[0] != today:
            conn.execute(
                "UPDATE user_withdrawal_limits SET daily_used_com = 0, last_daily_reset = ? WHERE user_id = ?",
                (today, user_id)
            )
        if row[1] != month_start:
            conn.execute(
                "UPDATE user_withdrawal_limits SET monthly_used_com = 0, last_monthly_reset = ? WHERE user_id = ?",
                (month_start, user_id)
            )
        conn.commit()


# ---------- Система чеков ----------
def _generate_check_code(length: int = 8) -> str:
    """Генерирует уникальный код чека."""
    chars = string.ascii_uppercase + string.digits
    for _ in range(20):
        code = "".join(random.choices(chars, k=length))
        r = execute_query(ECONOMY_DB, "SELECT 1 FROM checks WHERE code = ?", (code,))
        if not r:
            return code
    return "".join(random.choices(chars, k=length + 4))


def _get_user_by_username(username: str) -> Optional[Dict[str, Any]]:
    """Возвращает данные пользователя из БД по username (с @ или без)."""
    username_clean = (username or "").strip().lstrip("@").lower()
    if not username_clean:
        return None
    rows = execute_query(USERS_DB, "SELECT user_id, username, first_name FROM users WHERE LOWER(REPLACE(COALESCE(username, ''), '@', '')) = ? LIMIT 1", (username_clean,))
    if rows:
        return {"user_id": int(rows[0][0]), "username": rows[0][1], "first_name": rows[0][2] or ""}
    return None


def _check_user_filters_for_check(user_id: int, check_row: Any, bot_instance: Any) -> Tuple[bool, str]:
    """Проверяет фильтры чека (min_age, min_activity, allowed_countries, blocked_users). Возвращает (ok, error_message)."""
    try:
        if check_row.get("blocked_users"):
            try:
                blocked = json.loads(check_row["blocked_users"]) if isinstance(check_row["blocked_users"], str) else check_row["blocked_users"]
                if isinstance(blocked, list) and user_id in blocked:
                    return False, "Вы в чёрном списке этого чека."
            except Exception:
                pass
        if check_row.get("min_age"):
            try:
                mem = bot_instance.get_chat_member(user_id, user_id)
                if getattr(mem, "user", None) and getattr(mem.user, "id", None):
                    # Telegram API не отдаёт created_at пользователя в get_chat_member — пропускаем проверку возраста
                    pass
            except Exception:
                pass
        if check_row.get("min_activity"):
            cnt = execute_query(USERS_DB, "SELECT COUNT(*) FROM user_history WHERE user_id = ?", (user_id,))
            total = int(cnt[0][0]) if cnt else 0
            if total < int(check_row["min_activity"]):
                return False, f"Минимальная активность: {check_row['min_activity']} действий."
        return True, ""
    except Exception as e:
        logger.warning("check_user_filters: %s", e)
        return True, ""


def _activate_check(message: Message, code: str) -> None:
    """Активация чека по коду."""
    user_id = message.from_user.id
    chat_id = message.chat.id
    lang = get_user_language(user_id)
    code = (code or "").strip().upper()
    if not code:
        bot.send_message(chat_id, t(lang, "check_invalid_link"))
        return
    rows = execute_query(ECONOMY_DB, "SELECT id, creator_id, type, total_amount, remaining_amount, min_amount, max_amount, fixed_amount, target_user_id, max_claims, claims_count, required_language, required_premium, required_subscription, expires_at, is_active, min_age, min_activity, blocked_users FROM checks WHERE code = ? AND is_active = 1", (code,))
    if not rows:
        bot.send_message(chat_id, t(lang, "check_not_found"))
        return
    r = rows[0]
    check_id = r[0]
    creator_id = r[1]
    ctype = r[2]
    remaining = int(r[4])
    min_a = r[5]
    max_a = r[6]
    fixed_a = r[7]
    target_uid = r[8]
    max_claims = int(r[9] or 0)
    claims_count = int(r[10] or 0)
    req_lang = r[11]
    req_premium = bool(r[12])
    req_sub = bool(r[13])
    expires_at = r[14]
    if expires_at:
        try:
            exp_dt = datetime.fromisoformat(expires_at.replace("Z", "+00:00")) if isinstance(expires_at, str) else expires_at
            now = datetime.now(exp_dt.tzinfo) if getattr(exp_dt, "tzinfo", None) else datetime.now()
            if now > exp_dt:
                execute_query(ECONOMY_DB, "UPDATE checks SET is_active = 0 WHERE id = ?", (check_id,))
                bot.send_message(chat_id, t(lang, "check_expired"))
                return
        except Exception:
            pass
    if max_claims > 0 and claims_count >= max_claims:
        execute_query(ECONOMY_DB, "UPDATE checks SET is_active = 0 WHERE id = ?", (check_id,))
        bot.send_message(chat_id, t(lang, "check_max_uses"))
        return
    if ctype == "individual" and target_uid and int(target_uid) != user_id:
        bot.send_message(chat_id, t(lang, "check_wrong_user"))
        return
    already = execute_query(ECONOMY_DB, "SELECT 1 FROM check_claims WHERE check_id = ? AND user_id = ?", (check_id, user_id))
    if already:
        bot.send_message(chat_id, t(lang, "check_already_claimed"))
        return
    if req_lang:
        ulang = get_user_language(user_id)
        if ulang != req_lang:
            bot.send_message(chat_id, t(lang, "check_wrong_lang", lang=req_lang))
            return
    if req_premium:
        try:
            u = message.from_user
            if not getattr(u, "is_premium", False):
                bot.send_message(chat_id, t(lang, "check_premium_only"))
                return
        except Exception:
            bot.send_message(chat_id, t(lang, "check_premium_only"))
            return
    if req_sub:
        ok_sub, _ = check_all_subscriptions(user_id)
        if not ok_sub:
            bot.send_message(chat_id, t(lang, "check_subscribe_required"))
            return
    check_row_dict = {"min_age": r[16] if len(r) > 16 else None, "min_activity": r[17] if len(r) > 17 else None, "blocked_users": r[18] if len(r) > 18 else None}
    ok_f, err_f = _check_user_filters_for_check(user_id, check_row_dict, bot)
    if not ok_f:
        err_msg = t(lang, "check_blacklisted") if (err_f and "чёрном списке" in err_f) else (err_f or t(lang, "check_blacklisted"))
        if err_msg and not err_msg.startswith("❌"):
            err_msg = "❌ " + err_msg
        bot.send_message(chat_id, err_msg or t(lang, "check_blacklisted"))
        return
    if ctype == "random" and min_a is not None and max_a is not None:
        amount = random.randint(int(min_a), int(max_a))
    else:
        amount = int(fixed_a or 0)
    if amount <= 0 or amount > remaining:
        amount = remaining
    if amount <= 0:
        bot.send_message(chat_id, t(lang, "check_no_funds"))
        return
    new_remaining = remaining - amount
    new_claims = claims_count + 1
    with database_connection(ECONOMY_DB) as conn:
        conn.execute(
            "UPDATE checks SET remaining_amount = ?, claims_count = ?, is_active = CASE WHEN ? <= 0 OR (? > 0 AND ? >= ?) THEN 0 ELSE 1 END WHERE id = ?",
            (new_remaining, new_claims, new_remaining, max_claims, new_claims, max_claims, check_id),
        )
        conn.execute("INSERT INTO check_claims (check_id, user_id, amount) VALUES (?, ?, ?)", (check_id, user_id, amount))
        conn.execute("UPDATE users SET balance = balance + ? WHERE user_id = ?", (amount, user_id))
        conn.commit()
    cache_delete(f"balance_{user_id}")
    try:
        creator_lang = get_user_language(creator_id)
        bot.send_message(
            creator_id,
            t(creator_lang, "check_activated_notify", code=code, name=message.from_user.full_name or str(message.from_user.id), amount=amount, remaining=new_remaining),
        )
    except Exception:
        pass
    amount_str = format_amount_for_user(user_id, amount)
    bot.send_message(
        chat_id,
        f"✅ **Чек активирован!**\n\n💰 Вы получили: {amount_str}\n📊 Осталось активаций: {max_claims - new_claims if max_claims > 0 else '∞'}",
        parse_mode="Markdown",
    )


def transfer_coins(
    from_id: int,
    to_id: int,
    amount: int,
    reason: str = "Перевод"
) -> Tuple[bool, str]:
    """
    Переводит монеты от одного пользователя другому.
    
    Args:
        from_id: ID отправителя
        to_id: ID получателя
        amount: Сумма перевода
        reason: Причина перевода
    
    Returns:
        Tuple[bool, str]: (успех, сообщение)
    """
    lang = get_user_language(from_id)
    # Валидация
    if amount <= 0:
        return False, "❌ Сумма перевода должна быть положительной"

    if from_id == to_id:
        return False, t(lang, "transfer_self")
    if is_excluded_bot_user(from_id) or is_excluded_bot_user(to_id):
        return False, t(lang, "transfer_bots")
    
    if from_id in DEVELOPER_IDS:
        # Админ может переводить без ограничений
        pass
    elif amount < 10:
        return False, "❌ Минимальная сумма перевода: 10 монет"

    # Анти-абуз: лимиты для новых и лимит приёма от новых (при ошибке не блокируем перевод)
    try:
        if ANTI_ABUSE_ENABLED:
            abuse_err = _check_anti_abuse_transfer(from_id, to_id, amount)
            if abuse_err:
                return False, abuse_err
    except Exception as e:
        logger.warning(f"Анти-абуз проверка перевода пропущена из-за ошибки: {e}")

    try:
        # Проверяем баланс отправителя
        from_balance = get_balance(from_id, use_cache=False)
        
        if from_balance < amount:
            return False, t(lang, "transfer_insufficient", balance=from_balance, sign=COM_EMOJI)
        
        # Рассчитываем сумму с учётом налога (с VIP-скидкой)
        effective_tax_rate = COINS_TRANSFER_TAX
        vip_discount = ItemEffects.get_transfer_tax_discount_percent(from_id)
        if vip_discount > 0:
            effective_tax_rate = COINS_TRANSFER_TAX * max(0.0, 1 - vip_discount / 100)

        tax = int(amount * effective_tax_rate) if effective_tax_rate > 0 else 0
        final_amount = amount - tax
        
        # Начинаем транзакцию
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.cursor()
            
            # Списываем у отправителя
            cursor.execute(
                "UPDATE users SET balance = balance - ?, total_spent = total_spent + ? WHERE user_id=?",
                (amount, amount, from_id)
            )
            
            # Начисляем получателю
            cursor.execute(
                "UPDATE users SET balance = balance + ?, total_earned = total_earned + ? WHERE user_id=?",
                (final_amount, final_amount, to_id)
            )
            
            # Если есть налог, записываем его отдельно
            if tax > 0:
                cursor.execute(
                    "UPDATE users SET balance = balance + ? WHERE user_id=?",
                    (tax, ADMIN_CHAT_ID)
                )
            
            # Записываем транзакции
            now = datetime.now()
            
            # Основной перевод
            cursor.execute(
                """INSERT INTO transactions 
                   (from_id, to_id, amount, reason, date, type) 
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (from_id, to_id, final_amount, reason, now, "transfer")
            )
            
            # Налог (если есть)
            if tax > 0:
                cursor.execute(
                    """INSERT INTO transactions 
                       (from_id, to_id, amount, reason, date, type) 
                       VALUES (?, ?, ?, ?, ?, ?)""",
                    (from_id, ADMIN_CHAT_ID, -tax, f"Налог на перевод: {reason}", now, "tax")
                )
            
            conn.commit()
        
        # Обновляем время последнего действия
        update_last_seen(from_id)
        update_last_seen(to_id)
        
        # Очищаем кэш
        cache_delete(f"balance_{from_id}")
        cache_delete(f"balance_{to_id}")
        
        # Проверяем достижения
        check_transfer_achievements(from_id, to_id, amount)

        try:
            if ANTI_ABUSE_ENABLED and _anti_abuse_is_new_user(from_id):
                _anti_abuse_increment_received_from_new(to_id)
                if ANTI_ABUSE_LOG_SUSPICIOUS:
                    logger.info(f"[Anti-abuse] Перевод от нового {from_id} к {to_id}: {amount} {COM_EMOJI}")
        except Exception as e:
            logger.warning(f"Анти-абуз учёт после перевода: {e}")

        logger.info(f"✅ Перевод {amount} монет от {from_id} к {to_id} (налог: {tax})")
        
        if tax > 0:
            return True, f"✅ Перевод выполнен!\nОтправлено: {final_amount} {COM_EMOJI}\nНалог: {tax} {COM_EMOJI}"
        else:
            return True, f"✅ Перевод выполнен!\nОтправлено: {final_amount} {COM_EMOJI}"
        
    except Exception as e:
        logger.error(f"❌ Ошибка перевода монет: {e}")
        return False, "❌ Ошибка при выполнении перевода"

# ============================================================================
# СИСТЕМА ТРАНЗАКЦИЙ
# ============================================================================

def record_transaction(
    from_id: int,
    to_id: int,
    amount: int,
    reason: str = "",
    transaction_type: str = "transfer"
) -> Optional[int]:
    """
    Записывает транзакцию в базу данных.
    Совместимо с SQLite без RETURNING (использует lastrowid).
    
    Args:
        from_id: ID отправителя (0 = система)
        to_id: ID получателя (0 = система)
        amount: Сумма (положительная = получение, отрицательная = отправка)
        reason: Причина
        transaction_type: Тип транзакции
    
    Returns:
        Optional[int]: ID транзакции или None
    """
    try:
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.execute(
                """INSERT INTO transactions 
                   (from_id, to_id, amount, reason, date, type) 
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (from_id, to_id, amount, reason, datetime.now(), transaction_type)
            )
            conn.commit()
            transaction_id = cursor.lastrowid
        if transaction_id:
            logger.debug(f"✅ Транзакция #{transaction_id} записана: {amount} от {from_id} к {to_id}")
            return transaction_id
        return None
    except Exception as e:
        logger.error(f"❌ Ошибка записи транзакции: {e}")
        return None


# --- Платежи: покупка монет (рубли, карты, крипта, Stars) ---

def get_exchange_rate(currency_from: str, currency_to: str = "COINS") -> float:
    """Возвращает курс обмена currency_from -> currency_to (монеты). Если нет — 0."""
    try:
        r = execute_query(
            ECONOMY_DB,
            "SELECT rate FROM exchange_rates WHERE currency_from=? AND currency_to=? ORDER BY updated_at DESC LIMIT 1",
            (currency_from.upper(), currency_to.upper()),
        )
        return float(r[0][0]) if r else 0.0
    except Exception as e:
        logger.warning(f"get_exchange_rate {currency_from}->{currency_to}: {e}")
        return 0.0


def record_payment_transaction(
    user_id: int,
    coins_received: int,
    payment_method: str,
    payment_system: str,
    transaction_id: Optional[str] = None,
    amount_usd: Optional[float] = None,
    amount_rub: Optional[float] = None,
    amount_ton: Optional[float] = None,
    amount_stars: Optional[int] = None,
    status: str = "completed",
) -> Optional[int]:
    """Записывает платёж в payment_transactions. Возвращает id записи или None."""
    try:
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.execute(
                """INSERT INTO payment_transactions
                   (user_id, amount_usd, amount_rub, amount_ton, amount_stars, coins_received,
                    payment_method, payment_system, transaction_id, status, completed_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    user_id,
                    amount_usd,
                    amount_rub,
                    amount_ton,
                    amount_stars,
                    coins_received,
                    payment_method,
                    payment_system,
                    transaction_id,
                    status,
                    datetime.now() if status == "completed" else None,
                ),
            )
            conn.commit()
            return cursor.lastrowid
    except Exception as e:
        logger.error(f"Ошибка записи платёжной транзакции: {e}")
        return None


def is_payment_transaction_processed(transaction_id: str) -> bool:
    """Проверка идемпотентности: уже начисляли по этому transaction_id?"""
    if not transaction_id:
        return False
    try:
        r = execute_query(
            ECONOMY_DB,
            "SELECT 1 FROM payment_transactions WHERE transaction_id=? AND status='completed'",
            (transaction_id,),
        )
        return bool(r)
    except Exception as e:
        logger.warning(f"is_payment_transaction_processed: {e}")
        return True  # при сомнении не начисляем повторно


def update_payment_transaction_completed(transaction_id: str) -> bool:
    """Обновляет запись платежа на status=completed (для ЮKassa/Stripe по вебхуку)."""
    if not transaction_id:
        return False
    try:
        execute_query(
            ECONOMY_DB,
            "UPDATE payment_transactions SET status='completed', completed_at=? WHERE transaction_id=? AND status='pending'",
            (datetime.now(), transaction_id),
        )
        return True
    except Exception as e:
        logger.warning(f"update_payment_transaction_completed: {e}")
        return False


def get_transaction_history(
    user_id: int,
    limit: int = 20,
    offset: int = 0,
    transaction_type: Optional[str] = None
) -> List[Dict[str, Any]]:
    """
    Возвращает историю транзакций пользователя.
    
    Args:
        user_id: ID пользователя
        limit: Максимальное количество
        offset: Смещение для пагинации
        transaction_type: Фильтр по типу
    
    Returns:
        List[Dict[str, Any]]: Список транзакций
    """
    try:
        query = """SELECT id, from_id, to_id, amount, reason, date, type 
                   FROM transactions 
                   WHERE from_id=? OR to_id=?"""
        params = [user_id, user_id]
        
        if transaction_type:
            query += " AND type=?"
            params.append(transaction_type)
        
        query += " ORDER BY date DESC LIMIT ? OFFSET ?"
        params.extend([limit, offset])
        
        result = execute_query(ECONOMY_DB, query, tuple(params))
        
        transactions = []
        if result:
            for row in result:
                transactions.append({
                    "id": row[0],
                    "from_id": row[1],
                    "to_id": row[2],
                    "amount": row[3],
                    "reason": row[4],
                    "date": row[5],
                    "type": row[6]
                })
        
        return transactions
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения истории транзакций: {e}")
        return []

def get_transaction_stats(
    user_id: int,
    days: int = 30
) -> Dict[str, Any]:
    """
    Возвращает статистику транзакций пользователя.
    
    Args:
        user_id: ID пользователя
        days: За сколько дней
    
    Returns:
        Dict[str, Any]: Статистика
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            """SELECT 
                COUNT(*) as total_count,
                SUM(CASE WHEN to_id=? THEN amount ELSE 0 END) as total_received,
                SUM(CASE WHEN from_id=? THEN -amount ELSE 0 END) as total_sent,
                COUNT(CASE WHEN to_id=? THEN 1 END) as received_count,
                COUNT(CASE WHEN from_id=? THEN 1 END) as sent_count
               FROM transactions 
               WHERE (from_id=? OR to_id=?) AND date > datetime('now', ?)""",
            (user_id, user_id, user_id, user_id, user_id, user_id, f"-{days} days")
        )
        
        if result:
            row = result[0]
            return {
                "total_count": row[0] or 0,
                "total_received": row[1] or 0,
                "total_sent": row[2] or 0,
                "received_count": row[3] or 0,
                "sent_count": row[4] or 0,
                "net_flow": (row[1] or 0) - (row[2] or 0)
            }
        
        return {
            "total_count": 0,
            "total_received": 0,
            "total_sent": 0,
            "received_count": 0,
            "sent_count": 0,
            "net_flow": 0
        }
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики транзакций: {e}")
        return {}

# ============================================================================
# ДОНАТЫ И РЕЙТИНГ ГРУПП
# ============================================================================

DONATE_MIN_AMOUNT = 1
DONATE_MAX_AMOUNT = 1_000_000
DONATE_COOLDOWN_SEC = 10
RATING_PAGE_SIZE = 10
_donate_last_time: Dict[int, float] = {}

def donations_ensure_group(
    group_id: int,
    group_name: Optional[str] = None,
    group_link: Optional[str] = None,
    members_count: Optional[int] = None,
) -> bool:
    """Создаёт или обновляет запись группы в groups_donations."""
    try:
        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        mcount = members_count if members_count is not None else 0
        execute_query(
            ECONOMY_DB,
            """INSERT INTO groups_donations (group_id, group_name, group_link, total_donations, members_count, last_donation, created_at)
               VALUES (?, ?, ?, 0, ?, NULL, ?)
               ON CONFLICT(group_id) DO UPDATE SET
                 group_name = COALESCE(NULLIF(?, ''), group_name),
                 group_link = COALESCE(NULLIF(?, ''), group_link),
                 members_count = CASE WHEN ? > 0 THEN ? ELSE members_count END
            """,
            (group_id, group_name or "", group_link or "", mcount, now, group_name or "", group_link or "", mcount, mcount),
        )
        if group_id < 0 and not (group_link or "").strip():
            update_group_invite_link(group_id, group_name)
        return True
    except Exception as e:
        logger.error(f"donations_ensure_group: {e}")
        return False


def _get_group_invite_link(group_id: int) -> Optional[str]:
    """Получает или создаёт инвайт-ссылку на группу (бот должен быть админом)."""
    if not isinstance(group_id, int) or group_id >= 0:
        return None
    try:
        link = bot.export_chat_invite_link(group_id)
        if link and isinstance(link, str):
            return link
        if link and getattr(link, "invite_link", None):
            return link.invite_link
    except Exception as e:
        logger.debug("export_chat_invite_link %s: %s", group_id, e)
    try:
        link = bot.create_chat_invite_link(chat_id=group_id)
        if link and getattr(link, "invite_link", None):
            return link.invite_link
    except Exception as e:
        logger.debug("create_chat_invite_link %s: %s", group_id, e)
    return None


def update_group_invite_link(group_id: int, group_name: Optional[str] = None) -> bool:
    """Обновляет в БД ссылку и (опционально) название группы. Возвращает True если ссылка получена и сохранена."""
    if not isinstance(group_id, int) or group_id >= 0:
        return False
    invite_link = _get_group_invite_link(group_id)
    if not invite_link:
        return False
    try:
        execute_query(
            ECONOMY_DB,
            """UPDATE groups_donations SET group_link = ?, group_name = COALESCE(NULLIF(?, ''), group_name) WHERE group_id = ?""",
            (invite_link, (group_name or "").strip() or None, group_id),
        )
        return True
    except Exception as e:
        logger.debug("update_group_invite_link: %s", e)
        return False


def donations_do_donate(
    user_id: int,
    group_id: int,
    amount: int,
    comment: str = "",
) -> Tuple[bool, str]:
    """
    Выполняет донат: списание монет у пользователя, зачисление в группу, обновление рейтинга.
    Атомарно в одной транзакции БД. Возвращает (успех, сообщение об ошибке или пусто).
    """
    if amount < DONATE_MIN_AMOUNT:
        return False, f"Минимальная сумма доната: {DONATE_MIN_AMOUNT} монет"
    if amount > DONATE_MAX_AMOUNT:
        return False, f"Максимальная сумма доната: {DONATE_MAX_AMOUNT} монет"
    balance = get_balance(user_id, use_cache=False)
    if balance < amount:
        return False, f"Недостаточно монет. Баланс: {balance} {COM_EMOJI}"
    try:
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT balance FROM users WHERE user_id=?", (user_id,))
            row = cursor.fetchone()
            if not row or (row[0] or 0) < amount:
                return False, f"Недостаточно монет. Баланс: {row[0] if row else 0} {COM_EMOJI}"
            new_balance = (row[0] or 0) - amount
            cursor.execute(
                "UPDATE users SET balance=?, total_spent=total_spent+? WHERE user_id=?",
                (new_balance, amount, user_id),
            )
            cursor.execute(
                """INSERT INTO donations (user_id, group_id, amount, message, created_at)
                   VALUES (?, ?, ?, ?, ?)""",
                (user_id, group_id, amount, (comment or "")[:500], datetime.now().isoformat(sep=" ", timespec="seconds")),
            )
            cursor.execute(
                """INSERT INTO group_top_donators (group_id, user_id, total_donated, last_donate)
                   VALUES (?, ?, ?, ?)
                   ON CONFLICT(group_id, user_id) DO UPDATE SET
                     total_donated = total_donated + excluded.total_donated,
                     last_donate = excluded.last_donate""",
                (group_id, user_id, amount, datetime.now().isoformat(sep=" ", timespec="seconds")),
            )
            now_iso = datetime.now().isoformat(sep=" ", timespec="seconds")
            cursor.execute(
                """UPDATE groups_donations SET group_xp = COALESCE(group_xp, 0) + ?, last_donation = ? WHERE group_id = ?""",
                (amount, now_iso, group_id),
            )
            conn.commit()
        cache_delete(f"balance_{user_id}")
        record_transaction(
            from_id=user_id,
            to_id=0,
            amount=-amount,
            reason=f"Донат в группу {group_id}",
            transaction_type="donate",
        )
        owner_id = get_chat_creator_id(group_id)
        if owner_id:
            fee = commission_amount(amount, DEVELOPER_COMMISSION_PERCENT)
            to_owner = amount - fee
            if to_owner > 0:
                add_coins(owner_id, to_owner, f"Донат в группу {group_id} (за вычетом комиссии)", admin_id=None, transaction_type="donate_to_owner")
            if fee > 0 and ADMIN_CHAT_ID:
                add_coins(ADMIN_CHAT_ID, fee, f"Комиссия с доната в группу {group_id}", admin_id=None, transaction_type="donate_commission")
        recalc_donations_rating_positions()
        _save_rating_history_for_group(group_id)
        return True, ""
    except Exception as e:
        logger.error(f"donations_do_donate: {e}")
        return False, "Ошибка при выполнении доната"


def donation_from_purchase(group_id: int, user_id: int, amount: int, message: str = "С покупки в группе") -> bool:
    """
    Зачисляет группе 100% суммы как очки рейтинга (Гром/Thunder); владельцу группы — сумма за вычетом комиссии разработчика.
    Используется при покупке товара (например VIP) для конкретной группы.
    """
    if amount <= 0:
        return False
    try:
        donations_ensure_group(group_id)
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.cursor()
            cursor.execute(
                """INSERT INTO donations (user_id, group_id, amount, message, created_at)
                   VALUES (?, ?, ?, ?, ?)""",
                (user_id, group_id, amount, (message or "С покупки в группе")[:500], datetime.now().isoformat(sep=" ", timespec="seconds")),
            )
            cursor.execute(
                """INSERT INTO group_top_donators (group_id, user_id, total_donated, last_donate)
                   VALUES (?, ?, ?, ?)
                   ON CONFLICT(group_id, user_id) DO UPDATE SET
                     total_donated = total_donated + excluded.total_donated,
                     last_donate = excluded.last_donate""",
                (group_id, user_id, amount, datetime.now().isoformat(sep=" ", timespec="seconds")),
            )
            now_iso = datetime.now().isoformat(sep=" ", timespec="seconds")
            cursor.execute(
                """UPDATE groups_donations SET group_xp = COALESCE(group_xp, 0) + ?, last_donation = ? WHERE group_id = ?""",
                (amount, now_iso, group_id),
            )
            conn.commit()
        to_owner = 0
        owner_id = get_chat_creator_id(group_id)
        if owner_id:
            fee = commission_amount(amount, DEVELOPER_COMMISSION_PERCENT)
            to_owner = amount - fee
            if to_owner > 0:
                add_coins(owner_id, to_owner, f"С покупки в группе {group_id} (за вычетом комиссии)", admin_id=None, transaction_type="donate_to_owner")
            if fee > 0 and ADMIN_CHAT_ID:
                add_coins(ADMIN_CHAT_ID, fee, f"Комиссия с покупки в группе {group_id}", admin_id=None, transaction_type="donate_commission")
        recalc_donations_rating_positions()
        _save_rating_history_for_group(group_id)
        logger.info(f"Группе {group_id} +{amount} очков рейтинга (Гром), владельцу зачислено {to_owner} {COM_EMOJI}")
        return True
    except Exception as e:
        logger.error(f"donation_from_purchase: {e}")
        return False


def recalc_donations_rating_positions() -> None:
    """Пересчитывает рейтинг (позиции) всех групп по очкам рейтинга (group_xp)."""
    try:
        rows = execute_query(
            ECONOMY_DB,
            "SELECT group_id FROM groups_donations ORDER BY COALESCE(group_xp, 0) DESC",
            (),
        )
        if not rows:
            return
        with database_connection(ECONOMY_DB) as conn:
            cursor = conn.cursor()
            for pos, row in enumerate(rows, 1):
                cursor.execute(
                    "UPDATE groups_donations SET rating_position=? WHERE group_id=?",
                    (pos, row[0]),
                )
            conn.commit()
    except Exception as e:
        logger.error(f"recalc_donations_rating_positions: {e}")

def _save_rating_history_for_group(group_id: int) -> None:
    """Сохраняет снимок очков рейтинга (group_xp) и позиции в rating_history на сегодня."""
    try:
        today = get_moscow_time().strftime("%Y-%m-%d")
        row = execute_query(
            ECONOMY_DB,
            "SELECT COALESCE(group_xp, 0), rating_position FROM groups_donations WHERE group_id=?",
            (group_id,),
        )
        if not row:
            return
        total = row[0][0] or 0
        pos = row[0][1]
        execute_query(
            ECONOMY_DB,
            """INSERT INTO rating_history (group_id, date, total_donations, position)
               VALUES (?, ?, ?, ?)
               ON CONFLICT(group_id, date) DO UPDATE SET total_donations=?, position=?""",
            (group_id, today, total, pos, total, pos),
        )
    except Exception as e:
        logger.error(f"_save_rating_history_for_group: {e}")

def get_group_donation_stats(group_id: int) -> Optional[Dict[str, Any]]:
    """Возвращает статистику группы: group (с group_xp как очки рейтинга), top_donators, history, last_donations."""
    try:
        group_row = execute_query(
            ECONOMY_DB,
            "SELECT group_id, group_name, group_link, COALESCE(group_xp, 0), members_count, last_donation, rating_position FROM groups_donations WHERE group_id=?",
            (group_id,),
        )
        if not group_row:
            return None
        r = group_row[0]
        top = execute_query(
            ECONOMY_DB,
            """SELECT user_id, total_donated FROM group_top_donators WHERE group_id=? ORDER BY total_donated DESC LIMIT 10""",
            (group_id,),
        ) or []
        history = execute_query(
            ECONOMY_DB,
            """SELECT date, total_donations, position FROM rating_history WHERE group_id=? ORDER BY date DESC LIMIT 30""",
            (group_id,),
        ) or []
        last_dons = execute_query(
            ECONOMY_DB,
            """SELECT user_id, amount, created_at FROM donations WHERE group_id=? ORDER BY created_at DESC LIMIT 10""",
            (group_id,),
        ) or []
        return {
            "group": {
                "group_id": r[0],
                "group_name": r[1] or "Группа",
                "group_link": r[2] or "",
                "total_donations": r[3] or 0,
                "group_xp": r[3] or 0,
                "members_count": r[4] or 0,
                "last_donation": r[5],
                "rating_position": r[6],
            },
            "top_donators": [{"user_id": t[0], "total_donated": t[1]} for t in top],
            "history": [{"date": h[0], "total_donations": h[1], "position": h[2]} for h in history],
            "last_donations": [{"user_id": l[0], "amount": l[1], "created_at": l[2]} for l in last_dons],
        }
    except Exception as e:
        logger.error(f"get_group_donation_stats: {e}")
        return None

def get_rating_groups_page(page: int = 1) -> Tuple[List[Dict[str, Any]], int]:
    """Страница рейтинга групп по очкам (Гром/Thunder). Возвращает (список групп, общее количество)."""
    try:
        count_row = execute_query(ECONOMY_DB, "SELECT COUNT(*) FROM groups_donations WHERE COALESCE(group_xp, 0) > 0", ())
        total = count_row[0][0] if count_row else 0
        offset = (page - 1) * RATING_PAGE_SIZE
        rows = execute_query(
            ECONOMY_DB,
            """SELECT group_id, group_name, group_link, COALESCE(group_xp, 0), members_count, rating_position
               FROM groups_donations WHERE COALESCE(group_xp, 0) > 0 ORDER BY COALESCE(group_xp, 0) DESC LIMIT ? OFFSET ?""",
            (RATING_PAGE_SIZE, offset),
        ) or []
        return (
            [
                {
                    "group_id": r[0],
                    "group_name": r[1] or str(r[0]),
                    "group_link": r[2] or "",
                    "total_donations": r[3] or 0,
                    "group_xp": r[3] or 0,
                    "members_count": r[4] or 0,
                    "rating_position": r[5] or 0,
                }
                for r in rows
            ],
            total,
        )
    except Exception as e:
        logger.error(f"get_rating_groups_page: {e}")
        return [], 0

def get_my_donations(user_id: int, limit: int = 30) -> List[Dict[str, Any]]:
    """История донатов пользователя с названиями групп."""
    try:
        rows = execute_query(
            ECONOMY_DB,
            """SELECT d.group_id, d.amount, d.created_at, g.group_name
               FROM donations d
               LEFT JOIN groups_donations g ON g.group_id = d.group_id
               WHERE d.user_id=? ORDER BY d.created_at DESC LIMIT ?""",
            (user_id, limit),
        ) or []
        return [
            {"group_id": r[0], "amount": r[1], "created_at": r[2], "group_name": r[3] or str(r[0])}
            for r in rows
        ]
    except Exception as e:
        logger.error(f"get_my_donations: {e}")
        return []

