def get_group_inventory_list(group_id: int, limit: int = 30) -> List[Dict[str, Any]]:
    """Список предметов в инвентаре, привязанных к группе (покупки для этой группы)."""
    try:
        rows = execute_query(
            ECONOMY_DB,
            """SELECT i.user_id, s.name, i.purchase_date, i.used
               FROM inventory i
               JOIN shop_items s ON i.item_id = s.id
               WHERE i.group_id = ?
               ORDER BY i.purchase_date DESC
               LIMIT ?""",
            (group_id, limit),
        )
        if not rows:
            return []
        return [
            {"user_id": row[0], "item_name": row[1], "purchase_date": row[2], "used": bool(row[3])}
            for row in rows
        ]
    except Exception as e:
        logger.debug("get_group_inventory_list: %s", e)
        return []


def group_treasury_pay(group_id: int, admin_user_id: int, to_user_id: int, amount: int) -> Tuple[bool, str]:
    """
    Выплата из казны группы участнику. Только админ группы может инициировать.
    Возвращает (успех, сообщение об ошибке или пусто).
    """
    if amount < 1:
        return False, "Сумма должна быть больше 0"
    try:
        donations_ensure_group(group_id)
        total = get_group_total_donations(group_id)
        if total < amount:
            return False, f"В казне группы недостаточно средств. Доступно: {total} {COM_EMOJI}"
        with database_connection(ECONOMY_DB) as conn:
            cur = conn.execute(
                "UPDATE groups_donations SET total_donations = total_donations - ? WHERE group_id = ? AND total_donations >= ?",
                (amount, group_id, amount),
            )
            if cur.rowcount <= 0:
                return False, "Не удалось списать из казны (недостаточно средств или группа не найдена)"
            conn.commit()
        add_coins(to_user_id, amount, f"Выплата из казны группы {group_id}", admin_id=None, transaction_type="treasury_payout")
        _save_rating_history_for_group(group_id)
        logger.info(f"Выплата из казны группы {group_id}: {amount} {COM_EMOJI} пользователю {to_user_id} (инициатор {admin_user_id})")
        return True, ""
    except Exception as e:
        logger.error(f"group_treasury_pay: {e}")
        return False, str(e)


