def get_top_richest(limit: int = 10) -> List[Dict[str, Any]]:
    """
    Возвращает топ богатых пользователей.
    
    Args:
        limit: Количество пользователей
    
    Returns:
        List[Dict[str, Any]]: Список с ID и балансом
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            "SELECT user_id, balance FROM users ORDER BY balance DESC LIMIT ?",
            (max(limit * 4, 50),)
        )
        
        top = []
        if result:
            for row in result:
                if is_excluded_bot_user(row[0]):
                    continue
                top.append({
                    "user_id": row[0],
                    "balance": row[1]
                })
                if len(top) >= limit:
                    break
        
        return top
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения топа богачей: {e}")
        return []

