def get_top_by_winrate(limit: int = 10, min_games: int = 10) -> List[Dict[str, Any]]:
    """
    Возвращает топ по проценту побед.
    
    Args:
        limit: Количество пользователей
        min_games: Минимальное количество игр
    
    Returns:
        List[Dict[str, Any]]: Список с ID и процентом побед
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            """SELECT user_id, games_played, games_won 
               FROM users 
               WHERE games_played >= ? 
               ORDER BY CAST(games_won AS REAL) / games_played DESC 
               LIMIT ?""",
            (min_games, max(limit * 4, 50))
        )
        
        top = []
        if result:
            for row in result:
                if is_excluded_bot_user(row[0]):
                    continue
                win_rate = (row[2] / row[1] * 100) if row[1] > 0 else 0
                top.append({
                    "user_id": row[0],
                    "games_played": row[1],
                    "games_won": row[2],
                    "win_rate": win_rate
                })
                if len(top) >= limit:
                    break
        
        return top
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения топа по проценту побед: {e}")
        return []

