def get_user_rank_position(user_id: int, by: str = "balance") -> Optional[int]:
    """
    Возвращает позицию пользователя в топе.
    
    Args:
        user_id: ID пользователя
        by: По какому показателю ("balance", "games", "wins", "streak")
    
    Returns:
        Optional[int]: Позиция или None
    """
    if is_excluded_bot_user(user_id):
        return None

    try:
        order_map = {
            "balance": "balance DESC",
            "games": "games_played DESC",
            "wins": "games_won DESC",
            "streak": "daily_streak DESC"
        }
        
        order_by = order_map.get(by, "balance DESC")
        
        # Получаем всех пользователей с сортировкой
        result = execute_query(
            ECONOMY_DB,
            f"SELECT user_id FROM users ORDER BY {order_by}"
        )
        
        if result:
            rank_pos = 0
            for row in result:
                uid = int(row[0])
                if is_excluded_bot_user(uid):
                    continue
                rank_pos += 1
                if uid == user_id:
                    return rank_pos
        
        return None
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения позиции пользователя: {e}")
        return None

