def get_economy_stats() -> Dict[str, Any]:
    """
    Возвращает общую статистику экономики (без ботов).
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            "SELECT user_id, balance, total_earned, total_spent, games_played, games_won FROM users"
        )

        humans = [row for row in (result or []) if not is_excluded_bot_user(int(row[0]))]
        total_users = len(humans)
        total_coins = sum(int(row[1] or 0) for row in humans)
        total_earned = sum(int(row[2] or 0) for row in humans)
        total_spent = sum(int(row[3] or 0) for row in humans)
        total_games = sum(int(row[4] or 0) for row in humans)
        total_wins = sum(int(row[5] or 0) for row in humans)
        avg_balance = (total_coins / total_users) if total_users > 0 else 0
        max_balance = max((int(row[1] or 0) for row in humans), default=0)
        winrates = [
            (int(row[5] or 0) / int(row[4])) for row in humans
            if int(row[4] or 0) > 0
        ]
        avg_winrate = (sum(winrates) / len(winrates) * 100) if winrates else 0

        tx_result = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*), SUM(amount) FROM transactions WHERE date > datetime('now', '-7 days')"
        )
        tx_count = tx_result[0][0] if tx_result else 0
        tx_volume = tx_result[0][1] if tx_result and tx_result[0][1] else 0

        return {
            "total_users": total_users,
            "total_coins": total_coins,
            "avg_balance": avg_balance,
            "max_balance": max_balance,
            "total_earned": total_earned,
            "total_spent": total_spent,
            "total_games": total_games,
            "total_wins": total_wins,
            "avg_winrate": avg_winrate,
            "transactions_week": tx_count,
            "transaction_volume_week": tx_volume
        }

    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики экономики: {e}")
        return {}

def get_daily_stats(days: int = 7) -> List[Dict[str, Any]]:
    """
    Возвращает ежедневную статистику.
    
    Args:
        days: Количество дней
    
    Returns:
        List[Dict[str, Any]]: Статистика по дням
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            """SELECT 
                date(date) as day,
                COUNT(DISTINCT from_id) as unique_senders,
                COUNT(DISTINCT to_id) as unique_receivers,
                COUNT(*) as tx_count,
                SUM(amount) as tx_volume,
                SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END) as received,
                SUM(CASE WHEN amount < 0 THEN -amount ELSE 0 END) as sent
               FROM transactions 
               WHERE date > datetime('now', ?)
               GROUP BY date(date)
               ORDER BY day DESC""",
            (f"-{days} days",)
        )
        
        stats = []
        if result:
            for row in result:
                stats.append({
                    "day": row[0],
                    "unique_senders": row[1],
                    "unique_receivers": row[2],
                    "tx_count": row[3],
                    "tx_volume": row[4],
                    "received": row[5],
                    "sent": row[6]
                })
        
        return stats
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения дневной статистики: {e}")
        return []

