def check_transfer_achievements(from_id: int, to_id: int, amount: int) -> None:
    """
    Checks transfer-related achievements (first transfer, etc.) and awards them via award_achievement().
    """
    if amount <= 0:
        return
    try:
        award_achievement(from_id, "first_transfer")
    except Exception:
        pass


def check_balance_achievements(user_id: int) -> None:
    """
    Checks balance milestone achievements and awards them when user crosses thresholds.
    """
    try:
        balance = get_balance(user_id)
        if balance >= 10000:
            award_achievement(user_id, "balance_10k")
        if balance >= 1000:
            award_achievement(user_id, "balance_1k")
        if balance >= 100:
            award_achievement(user_id, "balance_100")
    except Exception:
        pass

