def cleanup_old_transactions(days: int = 90) -> int:
    """
    Удаляет старые транзакции.
    
    Args:
        days: Старше скольких дней
    
    Returns:
        int: Количество удалённых
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            "DELETE FROM transactions WHERE date < datetime('now', ?)",
            (f"-{days} days",)
        )
        
        # Не можем получить количество удалённых через RETURNING в SQLite
        # Поэтому просто логируем
        logger.info(f"✅ Очищены транзакции старше {days} дней")
        return 0
        
    except Exception as e:
        logger.error(f"❌ Ошибка очистки старых транзакций: {e}")
        return 0

def recalculate_user_stats(user_id: int) -> bool:
    """
    Пересчитывает статистику пользователя на основе данных.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        bool: True если успешно
    """
    try:
        # Получаем сумму всех транзакций
        tx_result = execute_query(
            ECONOMY_DB,
            """SELECT 
                SUM(CASE WHEN to_id=? THEN amount ELSE 0 END) as earned,
                SUM(CASE WHEN from_id=? THEN -amount ELSE 0 END) as spent
               FROM transactions 
               WHERE from_id=? OR to_id=?""",
            (user_id, user_id, user_id, user_id)
        )
        
        earned = tx_result[0][0] if tx_result and tx_result[0][0] else 0
        spent = tx_result[0][1] if tx_result and tx_result[0][1] else 0
        
        # Получаем статистику игр
        games_result = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*), SUM(win) FROM games WHERE user_id=?",
            (user_id,)
        )
        
        games_played = games_result[0][0] if games_result else 0
        games_won = games_result[0][1] if games_result and games_result[0][1] else 0
        
        # Обновляем статистику
        execute_query(
            ECONOMY_DB,
            """UPDATE users 
               SET total_earned=?, total_spent=?, games_played=?, games_won=?
               WHERE user_id=?""",
            (earned, spent, games_played, games_won, user_id)
        )
        
        # Очищаем кэш
        cache_delete(f"balance_{user_id}")
        
        logger.info(f"✅ Статистика пользователя {user_id} пересчитана")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка пересчёта статистики {user_id}: {e}")
        return False

def recalculate_all_stats() -> Dict[str, int]:
    """
    Пересчитывает статистику для всех пользователей.
    
    Returns:
        Dict[str, int]: Результаты
    """
    try:
        # Получаем всех пользователей
        users = execute_query(ECONOMY_DB, "SELECT user_id FROM users")
        
        success = 0
        failed = 0
        
        if users:
            for row in users:
                if recalculate_user_stats(row[0]):
                    success += 1
                else:
                    failed += 1
        
        logger.info(f"✅ Пересчитана статистика для {success} пользователей, ошибок: {failed}")
        return {"success": success, "failed": failed}
        
    except Exception as e:
        logger.error(f"❌ Ошибка пересчёта всей статистики: {e}")
        return {"success": 0, "failed": 0}

