def export_user_data(user_id: int) -> Optional[Dict[str, Any]]:
    """
    Экспортирует все данные пользователя.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        Optional[Dict[str, Any]]: Данные пользователя
    """
    try:
        # Основная информация
        user_stats = get_user_stats(user_id)
        if not user_stats:
            return None
        
        # Транзакции
        transactions = get_transaction_history(user_id, limit=1000)
        
        # Игры
        games = execute_query(
            ECONOMY_DB,
            "SELECT game, bet, result, win, date FROM games WHERE user_id=? ORDER BY date DESC LIMIT 100",
            (user_id,)
        )
        
        games_list = []
        if games:
            for row in games:
                games_list.append({
                    "game": row[0],
                    "bet": row[1],
                    "result": row[2],
                    "win": row[3],
                    "date": row[4]
                })
        
        return {
            "user_id": user_id,
            "stats": user_stats,
            "transactions": transactions,
            "games": games_list,
            "export_date": datetime.now().isoformat()
        }
        
    except Exception as e:
        logger.error(f"❌ Ошибка экспорта данных пользователя {user_id}: {e}")
        return None

def import_user_data(data: Dict[str, Any]) -> bool:
    """
    Импортирует данные пользователя.
    
    Args:
        data: Данные для импорта
    
    Returns:
        bool: True если успешно
    """
    try:
        user_id = data["user_id"]
        stats = data["stats"]
        
        # Обновляем основную информацию
        execute_query(
            ECONOMY_DB,
            """UPDATE users 
               SET balance=?, total_earned=?, total_spent=?, games_played=?, games_won=?
               WHERE user_id=?""",
            (stats["balance"], stats["total_earned"], stats["total_spent"],
             stats["games_played"], stats["games_won"], user_id)
        )
        
        # Очищаем кэш
        cache_delete(f"balance_{user_id}")
        
        logger.info(f"✅ Данные пользователя {user_id} импортированы")
        return True
        
    except Exception as e:
        logger.error(f"❌ Ошибка импорта данных: {e}")
        return False

