def _cleanup_economy_transactions() -> None:
    """Очистка старых транзакций."""
    cleanup_old_transactions(days=90)


def _cleanup_expired_inventory() -> None:
    """Очистка кэша балансов (balance_)."""
    for key in list(cache.keys()):
        if key.startswith("balance_"):
            cache_delete(key)


def _cleanup_expired_vip() -> None:
    """Очистка истёкших VIP-статусов."""
    pass


def _cleanup_old_ai_dialogs() -> None:
    """Очистка старых AI диалогов."""
    pass


def scheduled_economy_cleanup() -> None:
    """Плановая очистка экономических данных."""
    while True:
        if globals().get("_shutdown_event") is not None and globals()["_shutdown_event"].wait(timeout=86400):
            break
        time.sleep(0)
        try:
            _cleanup_economy_transactions()
        except Exception as e:
            logger.error(f"❌ Ошибка в очистке транзакций: {e}")
        try:
            _cleanup_expired_inventory()
        except Exception as e:
            logger.error(f"❌ Ошибка в очистке инвентаря: {e}")
        try:
            _cleanup_expired_vip()
        except Exception as e:
            logger.error(f"❌ Ошибка в очистке VIP: {e}")
        try:
            _cleanup_old_ai_dialogs()
        except Exception as e:
            logger.error(f"❌ Ошибка в очистке AI диалогов: {e}")
        logger.info("✅ Плановая очистка экономики выполнена")

