# ============================================================================
# СИСТЕМА DAILY БОНУСА
# ============================================================================

class DailyBonus:
    """
    Класс для управления ежедневным бонусом.
    
    Особенности:
    - Streak увеличивается при ежедневном получении
    - Бонус растёт с каждым днём streak
    - Максимальный streak ограничен
    - При пропуске streak сбрасывается
    """
    
    # Настройки бонуса
    BASE_REWARD = COINS_DAILY_REWARD
    STREAK_BONUS = COINS_DAILY_STREAK_BONUS
    MAX_STREAK = COINS_MAX_STREAK
    RANDOM_ENABLED = DAILY_RANDOM_ENABLED
    RANDOM_MIN = DAILY_RANDOM_MIN
    RANDOM_MAX = DAILY_RANDOM_MAX

    @staticmethod
    def _random_bounds() -> Tuple[int, int]:
        low = min(DailyBonus.RANDOM_MIN, DailyBonus.RANDOM_MAX)
        high = max(DailyBonus.RANDOM_MIN, DailyBonus.RANDOM_MAX)
        return max(0, low), max(0, high)

    @staticmethod
    def _weighted_random_reward(rnd_min: int, rnd_max: int) -> int:
        """Случайная сумма в [rnd_min, rnd_max]: меньшие значения выпадают чаще, чем максимальные."""
        if rnd_min >= rnd_max:
            return rnd_min
        # Веса: у min вес максимальный, у max — минимальный (линейное убывание)
        values = list(range(rnd_min, rnd_max + 1))
        weights = [rnd_max - v + 1 for v in values]
        return random.choices(values, weights=weights, k=1)[0]
    
    @staticmethod
    def can_claim(user_id: int) -> Tuple[bool, Optional[str]]:
        """
        Проверяет, может ли пользователь получить бонус.
        Улучшенная версия с защитой от багов (формат last_daily, 24ч).
        """
        try:
            result = execute_query(
                ECONOMY_DB,
                "SELECT last_daily, daily_streak FROM users WHERE user_id=?",
                (user_id,)
            )

            if not result:
                register_user(user_id)
                return True, None

            last_daily = result[0][0]

            # Если никогда не получал — можно получить
            if last_daily is None:
                return True, None

            # Преобразуем в datetime
            try:
                if isinstance(last_daily, str):
                    try:
                        last = datetime.fromisoformat(last_daily.replace("Z", "+00:00")[:19])
                    except ValueError:
                        try:
                            last = datetime.strptime(last_daily[:19], "%Y-%m-%d %H:%M:%S")
                        except ValueError:
                            logger.warning("Неверный формат last_daily для пользователя %s: %s", user_id, last_daily)
                            return True, None
                elif isinstance(last_daily, datetime):
                    last = last_daily
                else:
                    logger.warning("Неверный тип last_daily для пользователя %s: %s", user_id, type(last_daily))
                    return True, None
            except Exception as e:
                logger.error("Ошибка парсинга last_daily для пользователя %s: %s", user_id, e)
                return True, None

            now = datetime.now()
            time_diff = (now - last).total_seconds()

            if time_diff < 86400:  # 24 часа
                wait_seconds = int(86400 - time_diff)
                hours = wait_seconds // 3600
                minutes = (wait_seconds % 3600) // 60
                return False, f"⏳ Следующий бонус через {hours}ч {minutes}м"

            return True, None

        except Exception as e:
            logger.error("Ошибка проверки daily бонуса: %s", e)
            return False, "❌ Ошибка при проверке бонуса"
    
    @staticmethod
    def claim(user_id: int) -> Tuple[bool, int, int, str]:
        """
        Получает ежедневный бонус.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, int, int, str]: (успех, сумма, новый streak, сообщение)
        """
        try:
            # Проверяем, можно ли получить
            can, error = DailyBonus.can_claim(user_id)
            if not can:
                return False, 0, 0, error or "❌ Нельзя получить бонус"

            # Анти-абуз: блокировка daily для новых пользователей на N часов (если включено)
            if ANTI_ABUSE_ENABLED and ANTI_ABUSE_NEW_USER_NO_DAILY_HOURS > 0 and user_id not in DEVELOPER_IDS:
                reg = get_user_registered_at(user_id)
                if reg:
                    hours_since = (datetime.now() - reg).total_seconds() / 3600.0
                    if hours_since < ANTI_ABUSE_NEW_USER_NO_DAILY_HOURS:
                        left = int(ANTI_ABUSE_NEW_USER_NO_DAILY_HOURS - hours_since)
                        return False, 0, 0, (
                            f"🛡 Daily доступен через {left} ч после регистрации (защита от злоупотреблений)."
                        )
            
            # Получаем текущий streak
            result = execute_query(
                ECONOMY_DB,
                "SELECT daily_streak, last_daily FROM users WHERE user_id=?",
                (user_id,)
            )
            
            current_streak = 0
            last_daily = None
            
            if result and result[0][0]:
                current_streak = result[0][0]
                last_daily = result[0][1]
            
            now = datetime.now()

            # Проверяем, был ли пропуск
            if last_daily and isinstance(last_daily, str):
                try:
                    last = datetime.fromisoformat(last_daily)
                except (ValueError, TypeError):
                    last = None
            else:
                last = None

            if last is not None:
                days_diff = (now - last).days

                if days_diff == 1:
                    # Streak продолжается
                    new_streak = min(current_streak + 1, DailyBonus.MAX_STREAK)
                elif days_diff > 1:
                    # Streak сброшен
                    new_streak = 1
                else:
                    # Менее 24 часов (уже отсекли в can_claim)
                    new_streak = current_streak
            else:
                # Первый раз
                new_streak = 1
            
            # Рассчитываем базу daily (фикс или рандом; при рандоме меньшие суммы выпадают чаще)
            if DailyBonus.RANDOM_ENABLED:
                rnd_min, rnd_max = DailyBonus._random_bounds()
                base_reward = DailyBonus._weighted_random_reward(rnd_min, rnd_max)
            else:
                base_reward = DailyBonus.BASE_REWARD

            # Общий бонус с учётом streak
            streak_part = (new_streak - 1) * DailyBonus.STREAK_BONUS
            bonus = base_reward + streak_part

            # VIP-бонус к daily
            vip_daily_percent = ItemEffects.get_daily_bonus_percent(user_id)
            if vip_daily_percent > 0:
                bonus += int(bonus * vip_daily_percent / 100)

            # Одноразовый x2 daily из предмета магазина (из БД)
            double_daily_active = ItemEffects.has_double_daily(user_id)
            if double_daily_active:
                bonus *= 2
                ItemEffects.consume_double_daily(user_id)

            # Одна атомарная транзакция: запись в transactions + обновление balance и last_daily.
            # Так бонус не «слетает» после перезапуска скрипта — либо сохраняется всё, либо ничего.
            now_str = now.strftime("%Y-%m-%d %H:%M:%S")
            reason_daily = f"Ежедневный бонус (streak: {new_streak})"
            with database_connection(ECONOMY_DB) as conn:
                cursor = conn.execute(
                    """UPDATE users
                       SET balance = balance + ?,
                           last_daily = ?,
                           daily_streak = ?,
                           last_daily_streak = ?
                       WHERE user_id = ?
                         AND (last_daily IS NULL OR (julianday(?) - julianday(last_daily)) >= 1)""",
                    (bonus, now_str, new_streak, now_str, user_id, now_str),
                )
                if cursor.rowcount == 0:
                    cache_delete(f"balance_{user_id}")
                    return False, 0, 0, "❌ Бонус уже получен сегодня"
                conn.execute(
                    """INSERT INTO transactions (from_id, to_id, amount, reason, date, type)
                       VALUES (?, ?, ?, ?, ?, ?)""",
                    (0, user_id, bonus, reason_daily, now, "daily"),
                )
                conn.commit()

            cache_delete(f"balance_{user_id}")
            
            # Формируем сообщение
            if new_streak > 1:
                message = f"🔥 Streak: {new_streak} дней! (+{streak_part} к daily)"
            else:
                message = "🎉 Начинаем streak!"
            
            if DailyBonus.RANDOM_ENABLED:
                rnd_min, rnd_max = DailyBonus._random_bounds()
                message += f"\n🎲 Базовый daily: {base_reward} (диапазон {rnd_min}-{rnd_max})"
            if vip_daily_percent > 0:
                message += f"\n👑 VIP бонус: +{vip_daily_percent}% к daily"
            if double_daily_active:
                message += "\n✨ Применён буст: x2 к daily"
            
            logger.info(f"✅ Пользователь {user_id} получил daily бонус: {bonus} (streak: {new_streak})")
            return True, bonus, new_streak, message
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения daily бонуса: {e}")
            return False, 0, 0, "❌ Ошибка при получении бонуса"
    
    @staticmethod
    def get_streak_info(user_id: int) -> Dict[str, Any]:
        """
        Возвращает информацию о streak пользователя.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            Dict[str, Any]: Информация о streak
        """
        try:
            result = execute_query(
                ECONOMY_DB,
                "SELECT daily_streak, last_daily, last_daily_streak FROM users WHERE user_id=?",
                (user_id,)
            )
            
            if not result:
                rnd_min, rnd_max = DailyBonus._random_bounds()
                default_next = DailyBonus.BASE_REWARD
                if DailyBonus.RANDOM_ENABLED:
                    default_next = (rnd_min + rnd_max) // 2
                return {
                    "streak": 0,
                    "last_claim": None,
                    "next_bonus": default_next,
                    "next_bonus_min": rnd_min if DailyBonus.RANDOM_ENABLED else default_next,
                    "next_bonus_max": rnd_max if DailyBonus.RANDOM_ENABLED else default_next,
                    "can_claim": True,
                    "time_left": None
                }
            
            streak = result[0][0] or 0
            last_daily = result[0][1]
            last_streak = result[0][2]
            
            now = datetime.now()
            if DailyBonus.RANDOM_ENABLED:
                rnd_min, rnd_max = DailyBonus._random_bounds()
                next_bonus_min = rnd_min + streak * DailyBonus.STREAK_BONUS
                next_bonus_max = rnd_max + streak * DailyBonus.STREAK_BONUS
                next_bonus = (next_bonus_min + next_bonus_max) // 2
            else:
                next_bonus = DailyBonus.BASE_REWARD + streak * DailyBonus.STREAK_BONUS
                next_bonus_min = next_bonus
                next_bonus_max = next_bonus
            
            # Проверяем, можно ли получить
            can_claim = True
            time_left = None

            if last_daily and isinstance(last_daily, str):
                try:
                    last = datetime.fromisoformat(last_daily)
                    time_diff = now - last

                    if time_diff.total_seconds() < 86400:
                        can_claim = False
                        next_time = last + timedelta(hours=24)
                        remaining = next_time - now
                        hours = int(remaining.total_seconds() // 3600)
                        minutes = int((remaining.total_seconds() % 3600) // 60)
                        time_left = f"{hours}ч {minutes}м"
                except (ValueError, TypeError) as e:
                    logger.warning("Неверный формат last_daily для пользователя %s: %s", user_id, last_daily)

            return {
                "streak": streak,
                "last_claim": last_daily,
                "last_streak_update": last_streak,
                "next_bonus": next_bonus,
                "next_bonus_min": next_bonus_min,
                "next_bonus_max": next_bonus_max,
                "can_claim": can_claim,
                "time_left": time_left
            }
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения информации о streak: {e}")
            return {"streak": 0, "next_bonus": DailyBonus.BASE_REWARD, "next_bonus_min": DailyBonus.BASE_REWARD, "next_bonus_max": DailyBonus.BASE_REWARD, "can_claim": False}
    
    @staticmethod
    def reset_streak(user_id: int, admin_id: Optional[int] = None) -> bool:
        """
        Сбрасывает streak пользователя (для админов).
        
        Args:
            user_id: ID пользователя
            admin_id: ID администратора
        
        Returns:
            bool: True если успешно
        """
        try:
            execute_query(
                ECONOMY_DB,
                "UPDATE users SET daily_streak=0 WHERE user_id=?",
                (user_id,)
            )
            
            logger.info(f"✅ Streak пользователя {user_id} сброшен админом {admin_id}")
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка сброса streak: {e}")
            return False

