class ShopItem:
    """
    Класс для представления товара в магазине.
    """
    
    def __init__(
        self,
        id: int,
        name: str,
        description: str,
        price: int,
        stock: int,
        type: str,
        data: Optional[Dict[str, Any]] = None
    ):
        self.id = id
        self.name = name
        self.description = description
        self.price = price
        self.stock = stock
        self.type = type
        self.data = data or {}
    
    def to_dict(self) -> Dict[str, Any]:
        """Преобразует товар в словарь."""
        return {
            "id": self.id,
            "name": self.name,
            "description": self.description,
            "price": self.price,
            "stock": self.stock,
            "type": self.type,
            "data": self.data
        }
    
    @classmethod
    def from_db_row(cls, row) -> 'ShopItem':
        """Создаёт товар из строки БД."""
        return cls(
            id=row[0],
            name=row[1],
            description=row[2],
            price=row[3],
            stock=row[4],
            type=row[5],
            data=json.loads(row[6]) if row[6] else {}
        )

