    @staticmethod
    def get_all_items(include_out_of_stock: bool = False) -> List[ShopItem]:
        """
        Возвращает все товары в магазине.
        
        Args:
            include_out_of_stock: Включать ли товары с нулевым стоком
        
        Returns:
            List[ShopItem]: Список товаров
        """
        try:
            if include_out_of_stock:
                query = "SELECT * FROM shop_items ORDER BY price"
                result = execute_query(ECONOMY_DB, query)
            else:
                query = "SELECT * FROM shop_items WHERE stock > 0 OR stock = -1 ORDER BY price"
                result = execute_query(ECONOMY_DB, query)
            
            items = []
            if result:
                for row in result:
                    items.append(ShopItem.from_db_row(row))
            
            return items
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения товаров: {e}")
            return []
    
    @staticmethod
    def get_item(item_id: int) -> Optional[ShopItem]:
        """
        Возвращает товар по ID.
        
        Args:
            item_id: ID товара
        
        Returns:
            Optional[ShopItem]: Товар или None
        """
        try:
            result = execute_query(
                ECONOMY_DB,
                "SELECT * FROM shop_items WHERE id=?",
                (item_id,)
            )
            
            if result:
                return ShopItem.from_db_row(result[0])
            
            return None
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения товара {item_id}: {e}")
            return None
    
    @staticmethod
    def add_item(
        name: str,
        description: str,
        price: int,
        stock: int,
        item_type: str,
        data: Optional[Dict[str, Any]] = None,
        admin_id: Optional[int] = None
    ) -> Optional[int]:
        """
        Добавляет новый товар в магазин.
        
        Args:
            name: Название
            description: Описание
            price: Цена
            stock: Количество (-1 = бесконечно)
            item_type: Тип товара
            data: Дополнительные данные
            admin_id: ID администратора
        
        Returns:
            Optional[int]: ID нового товара или None
        """
        try:
            # Проверяем тип
            if item_type not in ShopManager.ITEM_TYPES:
                logger.warning(f"Неизвестный тип товара: {item_type}")
                return None
            
            result = execute_query(
                ECONOMY_DB,
                """INSERT INTO shop_items 
                   (name, description, price, stock, type, data, added, updated) 
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                   RETURNING id""",
                (
                    name, description, price, stock, item_type,
                    json.dumps(data or {}), datetime.now(), datetime.now()
                )
            )
            
            if result:
                item_id = result[0][0]
                logger.info(f"✅ Добавлен товар #{item_id}: {name} (админ: {admin_id})")
                return item_id
            
            return None
            
        except Exception as e:
            logger.error(f"❌ Ошибка добавления товара: {e}")
            return None
    
    @staticmethod
    def update_item(
        item_id: int,
        name: Optional[str] = None,
        description: Optional[str] = None,
        price: Optional[int] = None,
        stock: Optional[int] = None,
        data: Optional[Dict[str, Any]] = None,
        admin_id: Optional[int] = None
    ) -> bool:
        """
        Обновляет товар.
        
        Args:
            item_id: ID товара
            name: Новое название
            description: Новое описание
            price: Новая цена
            stock: Новое количество
            data: Новые данные
            admin_id: ID администратора
        
        Returns:
            bool: True если успешно
        """
        try:
            updates = []
            params = []
            
            if name is not None:
                updates.append("name=?")
                params.append(name)
            
            if description is not None:
                updates.append("description=?")
                params.append(description)
            
            if price is not None:
                updates.append("price=?")
                params.append(price)
            
            if stock is not None:
                updates.append("stock=?")
                params.append(stock)
            
            if data is not None:
                updates.append("data=?")
                params.append(json.dumps(data))
            
            updates.append("updated=?")
            params.append(datetime.now())
            params.append(item_id)
            
            if not updates:
                return False
            
            query = f"UPDATE shop_items SET {', '.join(updates)} WHERE id=?"
            execute_query(ECONOMY_DB, query, tuple(params))
            
            logger.info(f"✅ Товар #{item_id} обновлён (админ: {admin_id})")
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка обновления товара {item_id}: {e}")
            return False
    
    @staticmethod
    def delete_item(item_id: int, admin_id: Optional[int] = None) -> bool:
        """
        Удаляет товар из магазина.
        
        Args:
            item_id: ID товара
            admin_id: ID администратора
        
        Returns:
            bool: True если успешно
        """
        try:
            execute_query(
                ECONOMY_DB,
                "DELETE FROM shop_items WHERE id=?",
                (item_id,)
            )
            
            logger.info(f"✅ Товар #{item_id} удалён (админ: {admin_id})")
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка удаления товара {item_id}: {e}")
            return False
    
    @staticmethod
    def decrease_stock_if_available(item_id: int, amount: int = 1) -> bool:
        """
        Атомарно уменьшает сток только если товар в наличии (stock > 0).
        Защита от гонки при ограниченном количестве.
        Returns:
            bool: True если сток уменьшен, False если товар закончился или ошибка
        """
        try:
            with database_connection(ECONOMY_DB) as conn:
                cursor = conn.execute(
                    "UPDATE shop_items SET stock = stock - ? WHERE id = ? AND stock > 0",
                    (amount, item_id)
                )
                conn.commit()
                return cursor.rowcount > 0
        except Exception as e:
            logger.error(f"❌ Ошибка атомарного уменьшения стока товара {item_id}: {e}")
            return False

    @staticmethod
    def decrease_stock(item_id: int, amount: int = 1) -> bool:
        """
        Уменьшает количество товара.
        
        Args:
            item_id: ID товара
            amount: На сколько уменьшить
        
        Returns:
            bool: True если успешно
        """
        try:
            item = ShopManager.get_item(item_id)
            if not item:
                return False
            
            if item.stock == -1:  # Бесконечный товар
                return True
            
            new_stock = max(0, item.stock - amount)
            
            execute_query(
                ECONOMY_DB,
                "UPDATE shop_items SET stock=? WHERE id=?",
                (new_stock, item_id)
            )
            
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка уменьшения стока товара {item_id}: {e}")
            return False
    
    @staticmethod
    def increase_stock(item_id: int, amount: int = 1) -> bool:
        """
        Увеличивает количество товара.
        
        Args:
            item_id: ID товара
            amount: На сколько увеличить
        
        Returns:
            bool: True если успешно
        """
        try:
            item = ShopManager.get_item(item_id)
            if not item or item.stock == -1:
                return False
            
            execute_query(
                ECONOMY_DB,
                "UPDATE shop_items SET stock=stock+? WHERE id=?",
                (amount, item_id)
            )
            
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка увеличения стока товара {item_id}: {e}")
            return False

