def init_shop() -> None:
    """Инициализирует магазин."""
    try:
        # Проверяем, есть ли товары
        result = execute_query(ECONOMY_DB, "SELECT COUNT(*) FROM shop_items")
        
        if result and result[0][0] == 0:
            # Добавляем товары по умолчанию
            ShopManager.init_default_items()
        else:
            logger.info(f"✅ Магазин уже инициализирован, товаров: {result[0][0]}")

        # Прячем товары, которые не дают реальной ценности в текущей логике бота.
        optimize_shop_catalog()
            
    except Exception as e:
        logger.error(f"❌ Ошибка инициализации магазина: {e}")


def optimize_shop_catalog() -> None:
    """
    Приводит ассортимент магазина к рабочему состоянию:
    - архивирует декоративные/неиспользуемые позиции.
    - VIP и legend заданы в init_default_items(), не перезаписываем.
    """
    try:
        # Эти типы сейчас не дают стабильной/прозрачной пользы в Telegram-чате.
        deprecated_types = ("color_nick", "custom_color", "custom_title", "ad")
        for t in deprecated_types:
            execute_query(
                ECONOMY_DB,
                "UPDATE shop_items SET stock=0 WHERE type=? AND stock != 0",
                (t,),
            )

        logger.info("✅ Ассортимент магазина оптимизирован")
    except Exception as e:
        logger.error(f"❌ Ошибка оптимизации ассортимента: {e}")

# Запускаем инициализацию
init_shop()

