# СИСТЕМА ИНВЕНТАРЯ
# ============================================================================

class InventoryItem:
    """
    Класс для представления предмета в инвентаре.
    """
    
    def __init__(
        self,
        inventory_id: int,
        user_id: int,
        item: ShopItem,
        purchase_date: datetime,
        used: bool = False,
        used_date: Optional[datetime] = None,
        expires: Optional[datetime] = None
    ):
        self.inventory_id = inventory_id
        self.user_id = user_id
        self.item = item
        self.purchase_date = purchase_date
        self.used = used
        self.used_date = used_date
        self.expires = expires
    
    def is_expired(self) -> bool:
        """Проверяет, истёк ли предмет."""
        if self.expires:
            return datetime.now() > self.expires
        return False
    
    def can_use(self) -> Tuple[bool, str]:
        """
        Проверяет, можно ли использовать предмет.
        
        Returns:
            Tuple[bool, str]: (можно ли, сообщение)
        """
        if self.used:
            return False, "❌ Предмет уже использован"
        
        if self.is_expired():
            return False, "❌ Срок действия предмета истёк"
        
        return True, "✅ Можно использовать"

class InventoryManager:
    """
    Класс для управления инвентарём пользователей.
    """
    
    @staticmethod
    def _parse_db_datetime(value: Any) -> Optional[datetime]:
        """Нормализует значение даты из SQLite (datetime/str/None)."""
        if value is None:
            return None
        if isinstance(value, datetime):
            return value
        if isinstance(value, str):
            try:
                return datetime.fromisoformat(value)
            except Exception:
                try:
                    return datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
                except Exception:
                    return None
        return None

    @staticmethod
    def add_item(
        user_id: int,
        item_id: int,
        expires_days: Optional[int] = None,
        group_id: Optional[int] = None,
    ) -> Optional[int]:
        """
        Добавляет предмет в инвентарь пользователя.
        
        Args:
            user_id: ID пользователя
            item_id: ID товара
            expires_days: Через сколько дней истекает
            group_id: ID группы (для привязки покупки и отчисления % в казну)
        
        Returns:
            Optional[int]: ID записи в инвентаре
        """
        try:
            item = ShopManager.get_item(item_id)
            if not item:
                logger.warning(f"Попытка добавить несуществующий товар {item_id}")
                return None
            
            expires = None
            if expires_days:
                expires = datetime.now() + timedelta(days=expires_days)
            
            result = execute_query(
                ECONOMY_DB,
                """INSERT INTO inventory 
                   (user_id, item_id, purchase_date, expires, group_id) 
                   VALUES (?, ?, ?, ?, ?)
                   RETURNING id""",
                (user_id, item_id, datetime.now(), expires, group_id)
            )
            
            if result:
                inv_id = result[0][0]
                logger.info(f"✅ Предмет #{item_id} добавлен в инвентарь пользователя {user_id}")
                return inv_id
            
            return None
            
        except Exception as e:
            logger.error(f"❌ Ошибка добавления в инвентарь: {e}")
            return None
    
    @staticmethod
    def get_user_inventory(
        user_id: int,
        include_used: bool = False,
        include_expired: bool = False
    ) -> List[InventoryItem]:
        """
        Возвращает инвентарь пользователя.
        
        Args:
            user_id: ID пользователя
            include_used: Включать использованные
            include_expired: Включать истёкшие
        
        Returns:
            List[InventoryItem]: Список предметов
        """
        try:
            query = """SELECT i.id, i.user_id, i.purchase_date, i.used, i.used_date, i.expires,
                              s.id, s.name, s.description, s.price, s.stock, s.type, s.data
                       FROM inventory i
                       JOIN shop_items s ON i.item_id = s.id
                       WHERE i.user_id = ?"""
            params = [user_id]
            
            if not include_used:
                query += " AND i.used = 0"
            
            result = execute_query(ECONOMY_DB, query, tuple(params))
            
            items = []
            if result:
                for row in result:
                    # Проверяем истекшие
                    expires = row[5]
                    expires_dt = InventoryManager._parse_db_datetime(expires)
                    if not include_expired and expires_dt and expires_dt < datetime.now():
                        continue
                    
                    item = ShopItem(
                        id=row[6],
                        name=row[7],
                        description=row[8],
                        price=row[9],
                        stock=row[10],
                        type=row[11],
                        data=json.loads(row[12]) if row[12] else {}
                    )
                    
                    inventory_item = InventoryItem(
                        inventory_id=row[0],
                        user_id=row[1],
                        item=item,
                        purchase_date=InventoryManager._parse_db_datetime(row[2]),
                        used=bool(row[3]),
                        used_date=InventoryManager._parse_db_datetime(row[4]),
                        expires=expires_dt,
                    )
                    
                    items.append(inventory_item)
            
            return items
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения инвентаря: {e}")
            return []
    
    @staticmethod
    def get_item_by_inventory_id(inventory_id: int) -> Optional[InventoryItem]:
        """
        Возвращает предмет из инвентаря по ID записи.
        
        Args:
            inventory_id: ID записи в инвентаре
        
        Returns:
            Optional[InventoryItem]: Предмет или None
        """
        try:
            result = execute_query(
                ECONOMY_DB,
                """SELECT i.id, i.user_id, i.purchase_date, i.used, i.used_date, i.expires,
                          s.id, s.name, s.description, s.price, s.stock, s.type, s.data
                   FROM inventory i
                   JOIN shop_items s ON i.item_id = s.id
                   WHERE i.id = ?""",
                (inventory_id,)
            )
            
            if result:
                row = result[0]
                item = ShopItem(
                    id=row[6],
                    name=row[7],
                    description=row[8],
                    price=row[9],
                    stock=row[10],
                    type=row[11],
                    data=json.loads(row[12]) if row[12] else {}
                )
                
                return InventoryItem(
                    inventory_id=row[0],
                    user_id=row[1],
                    item=item,
                    purchase_date=InventoryManager._parse_db_datetime(row[2]),
                    used=bool(row[3]),
                    used_date=InventoryManager._parse_db_datetime(row[4]),
                    expires=InventoryManager._parse_db_datetime(row[5]),
                )
            
            return None
            
        except Exception as e:
            logger.error(f"❌ Ошибка получения предмета {inventory_id}: {e}")
            return None
    
    @staticmethod
    def use_item(inventory_id: int, user_id: int) -> Tuple[bool, str, Any]:
        """
        Использует предмет из инвентаря.
        
        Args:
            inventory_id: ID записи в инвентаре
            user_id: ID пользователя (для проверки)
        
        Returns:
            Tuple[bool, str, Any]: (успех, сообщение, результат)
        """
        try:
            # Получаем предмет
            inv_item = InventoryManager.get_item_by_inventory_id(inventory_id)
            
            if not inv_item:
                return False, "❌ Предмет не найден", None
            
            # Проверяем владельца
            if inv_item.user_id != user_id:
                return False, "❌ Это не твой предмет", None
            
            # Проверяем, можно ли использовать
            can, msg = inv_item.can_use()
            if not can:
                return False, msg, None
            
            # Применяем эффект в зависимости от типа
            result = None
            
            if inv_item.item.type == "luck":
                # Случайный выигрыш (Большой подарок — взвешенная лотерея 100–500, чаще ~200)
                data = inv_item.item.data or {}
                item_name = (inv_item.item.name or "")
                if "Большой подарок" in item_name:
                    win = _random_big_gift_prize()
                elif "Секретный подарок" in item_name:
                    win = _random_secret_gift_prize()
                elif "min" in data and "max" in data:
                    min_coins = int(data.get("min", 100))
                    max_coins = int(data.get("max", 1000))
                    if max_coins < min_coins:
                        max_coins = min_coins
                    win = random.randint(min_coins, max_coins)
                else:
                    min_coins, max_coins = 100, 1000
                    win = random.randint(min_coins, max_coins)
                add_coins(user_id, win, "Подарок из магазина")
                result = {"won": win}
                message = f"🎉 Ты выиграл {win} {COM_EMOJI}!"
                
            elif inv_item.item.type == "unwarn":
                # Снятие предупреждения
                if remove_warning(user_id, CHAT_ID):
                    message = "✅ Одно предупреждение снято!"
                else:
                    return False, "❌ У тебя нет предупреждений", None
            
            elif inv_item.item.type == "color_nick":
                # Цветной ник (будет реализовано в Части 7)
                message = "🌈 Теперь твой ник будет цветным!"
                result = {"color": "rainbow", "duration": inv_item.item.data.get("duration", 7)}
            
            elif inv_item.item.type == "vip":
                # VIP статус
                message = "👑 Ты получил VIP статус на 30 дней!"
                result = {"vip": True, "duration": 30}
            
            else:
                message = f"✅ Предмет {inv_item.item.name} использован!"
            
            # Отмечаем предмет как использованный
            execute_query(
                ECONOMY_DB,
                "UPDATE inventory SET used=1, used_date=? WHERE id=?",
                (datetime.now(), inventory_id)
            )
            
            logger.info(f"✅ Пользователь {user_id} использовал предмет #{inventory_id}")
            return True, message, result
            
        except Exception as e:
            logger.error(f"❌ Ошибка использования предмета: {e}")
            return False, "❌ Ошибка при использовании предмета", None

