# Блокировка от двойного нажатия "Подтвердить покупку" (user_id в процессе покупки)
_purchase_in_progress: set = set()

# Выбранная группа для покупок в магазине: user_id -> group_id (0 или None = без группы)
_shop_selected_group: Dict[int, Optional[int]] = {}
_shop_page_by_user: Dict[int, int] = {}
SHOP_PAGE_SIZE = 5


def _check_purchase_availability(user_id: int, item: Any, lang: str) -> Tuple[bool, str, Optional[InventoryItem]]:
    """Проверка наличия товара, баланса и резервирование стока. Возвращает (True, '', None) или (False, msg, None)."""
    if item.stock == 0:
        return False, t(lang, "buy_item_out_of_stock"), None
    balance = get_balance(user_id)
    if balance < item.price:
        return False, t(lang, "buy_item_insufficient", price=item.price, sign=COM_EMOJI), None
    limited_stock = item.stock != -1
    if limited_stock and not ShopManager.decrease_stock_if_available(item.id):
        return False, t(lang, "buy_item_out_of_stock"), None
    return True, "", None


def _execute_purchase(
    user_id: int, item: Any, item_id: int, group_id: Optional[int], lang: str
) -> Tuple[bool, Optional[InventoryItem], Optional[int], str]:
    """Списание монет и добавление предмета в инвентарь. Возвращает (success, inv_item, inv_id, msg)."""
    limited_stock = item.stock != -1
    if not remove_coins(user_id, item.price, f"Покупка: {item.name}"):
        if limited_stock:
            ShopManager.increase_stock(item_id)
        return False, None, None, t(lang, "buy_item_deduct_error")
    try:
        inv_id = InventoryManager.add_item(
            user_id=user_id,
            item_id=item_id,
            expires_days=item.data.get("duration") if item.data and "duration" in item.data else None,
            group_id=group_id if group_id else None,
        )
    except Exception as e:
        logger.error("Ошибка после списания при покупке, возврат монет и стока: %s", e)
        add_coins(user_id, item.price, "Возврат при ошибке покупки")
        if limited_stock:
            ShopManager.increase_stock(item_id)
        return False, None, None, t(lang, "buy_item_error_refunded")
    inv_item = InventoryManager.get_item_by_inventory_id(inv_id) if inv_id else None
    return True, inv_item, inv_id, ""


def _apply_post_purchase_effects(
    user_id: int, item: Any, inv_item: Optional[InventoryItem], group_id: Optional[int], lang: str
) -> Tuple[bool, str]:
    """Применение эффектов купленного предмета (VIP, luck и т.д.). Возвращает (apply_ok, apply_msg)."""
    apply_msg = ""
    apply_ok = True
    if inv_item and inv_item.item.type in ("vip", "luck", "double_daily", "mute_protection", "xp_boost", "legend", "ad", "unwarn", "color_nick"):
            try:
                it = inv_item.item
                data = it.data or {}
                if it.type == "color_nick":
                    duration = data.get("duration", 7)
                    color = data.get("color", "rainbow")
                    if ItemEffects.apply_color_nick(user_id, color, duration):
                        apply_msg = f"\n\n🌈 Цветное имя в боте на {duration} дн. активировано!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "vip":
                    duration = data.get("duration", 30)
                    if ItemEffects.apply_vip_status(user_id, duration, group_id=group_id):
                        apply_msg = f"\n\n👑 VIP на {duration} дней активирован!" + (f" (в группе)" if group_id else "")
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "luck":
                    item_name = (it.name or "")
                    if "Большой подарок" in item_name:
                        win = ItemEffects.apply_luck_gift(user_id, 100, 500, big_gift=True)
                    elif "Секретный подарок" in item_name:
                        win = ItemEffects.apply_luck_gift(user_id, 10, 100, secret_gift=True)
                    elif "min" in data and "max" in data:
                        min_coins = int(data.get("min", 100))
                        max_coins = int(data.get("max", 1000))
                        if max_coins < min_coins:
                            max_coins = min_coins
                        win = ItemEffects.apply_luck_gift(user_id, min_coins, max_coins)
                    else:
                        win = ItemEffects.apply_luck_gift(user_id, 100, 1000)
                    apply_msg = f"\n\n🎉 Подарок: +{win} {COM_EMOJI}!"
                    execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "double_daily":
                    if ItemEffects.apply_double_daily(user_id):
                        apply_msg = "\n\n✨ Следующий daily будет x2!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "mute_protection":
                    duration = data.get("duration", 24)
                    if ItemEffects.apply_mute_protection(user_id, duration):
                        apply_msg = f"\n\n🔇 Защита от мута на {duration} ч!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "xp_boost":
                    if ItemEffects.apply_xp_boost(user_id, data.get("duration", 60), data.get("multiplier", 2)):
                        apply_msg = "\n\n⚡ Буст активирован!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "legend":
                    if ItemEffects.apply_legend_status(user_id, data.get("color", "rainbow"), data.get("badge", "👑")):
                        apply_msg = "\n\n💎 Легендарный статус!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "ad":
                    if ItemEffects.apply_ad_post(user_id, data.get("duration", 24)):
                        apply_msg = "\n\n📢 Заявка на рекламу создана!"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
                elif it.type == "unwarn":
                    ok, msg = ItemEffects.apply_unwarn(user_id)
                    if ok:
                        apply_msg = f"\n\n{msg}"
                        execute_query(ECONOMY_DB, "UPDATE inventory SET used=1, used_date=? WHERE id=?", (datetime.now(), inv_item.inventory_id))
            except Exception as e:
                logger.warning(f"Автоприменение предмета после покупки: {e}")
                apply_ok = False
    return (apply_ok, apply_msg)


def buy_item(user_id: int, item_id: int, group_id: Optional[int] = None) -> Tuple[bool, str, Optional[InventoryItem]]:
    """
    Покупает товар в магазине.
    """
    if user_id in _purchase_in_progress:
        lang = get_user_language(user_id)
        return False, t(lang, "buy_item_wait"), None
    _purchase_in_progress.add(user_id)
    lang = get_user_language(user_id)
    try:
        item = ShopManager.get_item(item_id)
        if not item:
            return False, t(lang, "buy_item_not_found"), None
        check_result = _check_purchase_availability(user_id, item, lang)
        if not check_result[0]:
            return check_result[0], check_result[1], check_result[2]
        success, inv_item, inv_id, exec_msg = _execute_purchase(user_id, item, item_id, group_id, lang)
        if not success:
            return False, exec_msg, None
        apply_ok, apply_msg = _apply_post_purchase_effects(user_id, item, inv_item, group_id, lang)
        if not apply_ok:
            add_coins(user_id, item.price, "Возврат при ошибке активации")
            ShopManager.increase_stock(item_id)
            if inv_id:
                execute_query(ECONOMY_DB, "DELETE FROM inventory WHERE id=?", (inv_id,))
            return False, t(lang, "buy_item_activate_error"), None
        record_transaction(
            from_id=user_id,
            to_id=0,
            amount=-item.price,
            reason=f"Покупка: {item.name}",
            transaction_type="shop"
        )
        if group_id and PURCHASE_DONATION_TO_GROUP_PERCENT > 0:
            donation_amount = commission_amount(item.price, PURCHASE_DONATION_TO_GROUP_PERCENT)
            donation_from_purchase(group_id, user_id, donation_amount, "С покупки в группе")
        apply_purchase_commissions(user_id, item.price)
        logger.info(f"✅ Пользователь {user_id} купил {item.name} за {item.price}")
        if item.stock == -1:
            stock_msg = ""
        else:
            new_stock = max(0, item.stock - 1)
            stock_msg = t(lang, "buy_stock_left", count=new_stock)
        extra = stock_msg + apply_msg
        msg = t(lang, "buy_success", name=item.name, price=item.price, sign=COM_EMOJI, extra=extra)
        return True, msg, inv_item
    except Exception as e:
        logger.error(f"❌ Ошибка покупки: {e}")
        return False, t(get_user_language(user_id), "buy_item_error_generic"), None
    finally:
        _purchase_in_progress.discard(user_id)

# ============================================================================
# СПЕЦИАЛЬНЫЕ ЭФФЕКТЫ ПРЕДМЕТОВ
# ============================================================================

def _priv_group_id(group_id: Optional[int]) -> int:
    """Для БД: глобальные привилегии храним с group_id=0."""
    return int(group_id) if group_id is not None else 0


class PrivilegeManager:
    """Менеджер привилегий с сохранением в БД (legend, custom_title, color_nick, mute_protection, double_daily)."""

    @staticmethod
    def set_privilege(
        user_id: int,
        priv_type: str,
        value: Any = None,
        group_id: Optional[int] = None,
        expires_at: Optional[float] = None,
    ) -> bool:
        try:
            value_json = json.dumps(value, ensure_ascii=False) if value is not None else None
            expires = float(expires_at) if expires_at is not None else 0.0
            gid = _priv_group_id(group_id)
            execute_query(
                ECONOMY_DB,
                """INSERT INTO user_privileges (user_id, privilege_type, group_id, value, expires_at, updated_at)
                   VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                   ON CONFLICT(user_id, privilege_type, group_id) DO UPDATE SET
                   value = excluded.value,
                   expires_at = excluded.expires_at,
                   updated_at = CURRENT_TIMESTAMP""",
                (user_id, priv_type, gid, value_json, expires),
            )
            cache_key = f"{priv_type}_{user_id}_{group_id}" if group_id else f"{priv_type}_{user_id}"
            cache_delete(cache_key)
            return True
        except Exception as e:
            logger.error("Ошибка сохранения привилегии %s для %s: %s", priv_type, user_id, e)
            return False

    @staticmethod
    def get_privilege(
        user_id: int, priv_type: str, group_id: Optional[int] = None
    ) -> Optional[Dict[str, Any]]:
        cache_key = f"{priv_type}_{user_id}_{group_id}" if group_id else f"{priv_type}_{user_id}"
        cached = cache_get(cache_key)
        if cached is not None:
            return cached
        try:
            gid = _priv_group_id(group_id)
            result = execute_query(
                ECONOMY_DB,
                "SELECT value, expires_at FROM user_privileges WHERE user_id=? AND privilege_type=? AND group_id=?",
                (user_id, priv_type, gid),
            )
            if not result or not result[0]:
                return None
            value_json, expires_at = result[0][0], (result[0][1] or 0)
            if expires_at and float(expires_at) > 0 and float(expires_at) <= time.time():
                PrivilegeManager.remove_privilege(user_id, priv_type, group_id)
                return None
            data = {
                "value": json.loads(value_json) if value_json else None,
                "expires": float(expires_at) if expires_at else 0,
            }
            ttl = int(float(expires_at) - time.time()) if expires_at and float(expires_at) > 0 else 3600
            cache_set(cache_key, data, ttl=max(1, ttl))
            return data
        except Exception as e:
            logger.debug("Ошибка получения привилегии %s для %s: %s", priv_type, user_id, e)
            return None

    @staticmethod
    def remove_privilege(user_id: int, priv_type: str, group_id: Optional[int] = None) -> bool:
        try:
            gid = _priv_group_id(group_id)
            execute_query(
                ECONOMY_DB,
                "DELETE FROM user_privileges WHERE user_id=? AND privilege_type=? AND group_id=?",
                (user_id, priv_type, gid),
            )
            cache_key = f"{priv_type}_{user_id}_{group_id}" if group_id else f"{priv_type}_{user_id}"
            cache_delete(cache_key)
            return True
        except Exception as e:
            logger.error("Ошибка удаления привилегии %s для %s: %s", priv_type, user_id, e)
            return False

    @staticmethod
    def cleanup_expired() -> int:
        try:
            execute_query(
                ECONOMY_DB,
                "DELETE FROM user_privileges WHERE expires_at > 0 AND expires_at <= ?",
                (time.time(),),
            )
            return 0
        except Exception as e:
            logger.debug("Ошибка очистки привилегий: %s", e)
            return 0


def _random_big_gift_prize() -> int:
    """
    Случайный приз для «Большой подарок»: 100–500 💎 по цене 200 💎.
    Чаще выпадает в районе 200, чаще меньше чем больше; чем выше сумма — тем реже.
    """
    # Взвешенные диапазоны (мин, макс+1, вес): пик 150–250, ниже 200 чаще чем выше, 400+ редко
    ranges = [
        (100, 151, 22),   # 100–150 — часто
        (151, 201, 38),   # 151–200 — самый частый
        (201, 251, 22),   # 201–250 — ещё часто
        (251, 301, 10),   # 251–300 — реже
        (301, 351, 4),    # 301–350
        (351, 401, 2),    # 351–400
        (401, 501, 2),    # 401–500 — редко
    ]
    weights = [r[2] for r in ranges]
    chosen = random.choices(ranges, weights=weights, k=1)[0]
    return random.randint(chosen[0], chosen[1] - 1)


def _random_secret_gift_prize() -> int:
    """
    Случайный приз для «Секретный подарок»: 10–100 💎 по цене 50 💎.
    Чаще выпадает в районе 50, чаще меньше чем больше; чем выше сумма — тем реже.
    """
    ranges = [
        (10, 26, 22),    # 10–25 — часто
        (26, 41, 35),    # 25–40 — очень часто
        (41, 56, 28),    # 40–55 — пик
        (56, 71, 10),    # 55–70 — реже
        (71, 86, 3),     # 70–85
        (86, 101, 2),    # 85–100 — редко
    ]
    weights = [r[2] for r in ranges]
    chosen = random.choices(ranges, weights=weights, k=1)[0]
    return random.randint(chosen[0], chosen[1] - 1)


class ItemEffects:
    """
    Класс для применения эффектов предметов.
    """
    
    @staticmethod
    def apply_color_nick(user_id: int, color: str = "rainbow", duration: int = 7) -> bool:
        """Применяет цветной ник в боте: сохраняет в БД (user_privileges)."""
        expires = time.time() + duration * 86400
        ok = PrivilegeManager.set_privilege(
            user_id=user_id,
            priv_type="color_nick",
            value={"color": color},
            expires_at=expires,
        )
        if ok:
            cache_set(
                f"color_nick_{user_id}",
                {"color": color, "expires": expires},
                ttl=int(duration * 86400),
            )
        return ok

    @staticmethod
    def get_color_nick_profile(user_id: int) -> Optional[Dict[str, Any]]:
        """Возвращает активный цветной ник (color, expires) из БД с кэшем."""
        data = PrivilegeManager.get_privilege(user_id, "color_nick")
        if not data or not data.get("value"):
            return None
        val = data["value"]
        expires = data.get("expires") or 0
        if expires > 0 and expires <= time.time():
            return None
        return {"color": val.get("color", "rainbow"), "expires": expires}

    @staticmethod
    def apply_vip_status(user_id: int, duration: int = 30, group_id: Optional[int] = None) -> bool:
        """
        Применяет VIP статус. При group_id — VIP в этой группе (user_group_vip); иначе глобально (users.vip_till).
        """
        now = time.time()
        current = ItemEffects.get_vip_profile(user_id, group_id=group_id)
        if current and current.get("expires", 0) > now:
            new_expires = current["expires"] + duration * 86400
        else:
            new_expires = now + duration * 86400
        ttl_sec = int(new_expires - now)
        profile = {
            "active": True,
            "message_bonus": 1,
            "daily_bonus_percent": 15,
            "tax_discount_percent": 50,
            "expires": new_expires,
        }
        cache_key = f"vip_status_{user_id}_{group_id}" if group_id else f"vip_status_{user_id}"
        cache_set(cache_key, profile, ttl=ttl_sec)
        try:
            if group_id:
                execute_query(
                    ECONOMY_DB,
                    """INSERT INTO user_group_vip (user_id, group_id, vip_till) VALUES (?, ?, ?)
                       ON CONFLICT(user_id, group_id) DO UPDATE SET vip_till = excluded.vip_till""",
                    (user_id, group_id, new_expires),
                )
            else:
                register_user(user_id)
                execute_query(
                    ECONOMY_DB,
                    "UPDATE users SET vip_till = ? WHERE user_id = ?",
                    (new_expires, user_id),
                )
        except Exception as e:
            logger.warning(f"Сохранение VIP для {user_id} group={group_id}: {e}")
        return True

    @staticmethod
    def get_vip_profile(user_id: int, group_id: Optional[int] = None) -> Optional[Dict[str, Any]]:
        """Возвращает VIP-профиль: при group_id — VIP в этой группе (user_group_vip), иначе глобальный (users.vip_till)."""
        cache_key = f"vip_status_{user_id}_{group_id}" if group_id else f"vip_status_{user_id}"
        vip = cache_get(cache_key)
        if vip:
            if vip.get("expires", 0) <= time.time():
                cache_delete(cache_key)
                if group_id:
                    execute_query(ECONOMY_DB, "DELETE FROM user_group_vip WHERE user_id = ? AND group_id = ?", (user_id, group_id))
                else:
                    execute_query(ECONOMY_DB, "UPDATE users SET vip_till = NULL WHERE user_id = ?", (user_id,))
                return None
            return vip
        try:
            if group_id:
                result = execute_query(ECONOMY_DB, "SELECT vip_till FROM user_group_vip WHERE user_id = ? AND group_id = ?", (user_id, group_id))
            else:
                result = execute_query(ECONOMY_DB, "SELECT vip_till FROM users WHERE user_id = ?", (user_id,))
            if not result or result[0][0] is None:
                return None
            raw = result[0][0]
            try:
                expires_ts = float(raw)
            except (TypeError, ValueError):
                try:
                    exp_dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
                    expires_ts = exp_dt.timestamp()
                except Exception:
                    return None
            if expires_ts <= time.time():
                if group_id:
                    execute_query(ECONOMY_DB, "DELETE FROM user_group_vip WHERE user_id = ? AND group_id = ?", (user_id, group_id))
                else:
                    execute_query(ECONOMY_DB, "UPDATE users SET vip_till = NULL WHERE user_id = ?", (user_id,))
                return None
            profile = {
                "active": True,
                "message_bonus": 1,
                "daily_bonus_percent": 15,
                "tax_discount_percent": 50,
                "expires": expires_ts,
            }
            ttl_sec = max(1, int(expires_ts - time.time()))
            cache_set(cache_key, profile, ttl=ttl_sec)
            return profile
        except Exception as e:
            logger.debug(f"get_vip_profile из БД для {user_id} group={group_id}: {e}")
            return None

    @staticmethod
    def remove_vip_status(user_id: int) -> bool:
        """Снимает VIP у пользователя (кэш + БД). Для использования админом."""
        cache_delete(f"vip_status_{user_id}")
        try:
            execute_query(ECONOMY_DB, "UPDATE users SET vip_till = NULL WHERE user_id = ?", (user_id,))
            return True
        except Exception as e:
            logger.warning(f"remove_vip_status для {user_id}: {e}")
            return False

    @staticmethod
    def get_message_reward_bonus(user_id: int) -> int:
        """Дополнительная награда за сообщение от VIP-статуса."""
        vip = ItemEffects.get_vip_profile(user_id)
        if not vip:
            return 0
        return int(vip.get("message_bonus", 0))

    @staticmethod
    def get_daily_bonus_percent(user_id: int) -> int:
        """Процентный бонус к daily от VIP-статуса."""
        vip = ItemEffects.get_vip_profile(user_id)
        if not vip:
            return 0
        return int(vip.get("daily_bonus_percent", 0))

    @staticmethod
    def get_transfer_tax_discount_percent(user_id: int) -> int:
        """Скидка на налог перевода для VIP."""
        vip = ItemEffects.get_vip_profile(user_id)
        if not vip:
            return 0
        return int(vip.get("tax_discount_percent", 0))
    
    @staticmethod
    def apply_xp_boost(user_id: int, duration: int = 60, multiplier: int = 2) -> bool:
        """
        Применяет ускорение получения опыта.
        
        Args:
            user_id: ID пользователя
            duration: Длительность в минутах
            multiplier: Множитель
        
        Returns:
            bool: True если успешно
        """
        # Сохраняем в кэш
        cache_set(f"xp_boost_{user_id}", {
            "multiplier": multiplier,
            "expires": time.time() + duration * 60
        }, ttl=duration * 60)
        
        return True

    @staticmethod
    def apply_luck_gift(user_id: int, min_coins: int = 100, max_coins: int = 1000, big_gift: bool = False, secret_gift: bool = False) -> int:
        """Выдаёт случайный подарок монетами и возвращает сумму. big_gift=True — 100–500 (чаще ~200); secret_gift=True — 10–100 (чаще ~50)."""
        if big_gift:
            win = _random_big_gift_prize()
        elif secret_gift:
            win = _random_secret_gift_prize()
        else:
            win = random.randint(min_coins, max_coins)
        add_coins(user_id, win, "Подарок из магазина")
        return win

    @staticmethod
    def apply_legend_status(user_id: int, color: str = "rainbow", badge: str = "👑") -> bool:
        """Сохраняет легендарный статус в БД (навсегда, expires_at=0)."""
        ok = PrivilegeManager.set_privilege(
            user_id=user_id,
            priv_type="legend",
            value={"color": color, "badge": badge},
            expires_at=0,
        )
        if ok:
            cache_set(f"legend_status_{user_id}", {"color": color, "badge": badge}, ttl=86400 * 365)
        return ok

    @staticmethod
    def get_legend_status(user_id: int) -> Optional[Dict[str, Any]]:
        """Возвращает легендарный статус из БД (value) или None."""
        data = PrivilegeManager.get_privilege(user_id, "legend")
        return data.get("value") if data else None

    @staticmethod
    def apply_ad_post(user_id: int, duration: int = 24) -> bool:
        """Создаёт простую заявку на рекламный пост."""
        global request_counter
        request_counter += 1
        ad_requests.set(request_counter, {
            "user_id": user_id,
            "duration": duration,
            "created_at": datetime.now().isoformat(),
            "status": "pending",
        })
        return True

    @staticmethod
    def apply_unwarn(user_id: int) -> Tuple[bool, str]:
        """Снимает одно предупреждение пользователя."""
        if remove_warning(user_id, CHAT_ID):
            return True, "✅ Одно предупреждение снято!"
        return False, "❌ У тебя нет предупреждений"

    @staticmethod
    def apply_mute_protection(user_id: int, duration: int = 24) -> bool:
        """Активирует защиту от мута (сохранение в БД)."""
        expires = time.time() + duration * 3600
        ok = PrivilegeManager.set_privilege(
            user_id=user_id,
            priv_type="mute_protection",
            value={},
            expires_at=expires,
        )
        if ok:
            cache_set(f"mute_protection_{user_id}", {"expires": expires}, ttl=duration * 3600)
        return ok

    @staticmethod
    def has_mute_protection(user_id: int) -> bool:
        """Проверяет, активна ли у пользователя защита от мута (из БД)."""
        data = PrivilegeManager.get_privilege(user_id, "mute_protection")
        if not data:
            return False
        exp = data.get("expires") or 0
        return exp > 0 and exp > time.time()

    @staticmethod
    def apply_double_daily(user_id: int) -> bool:
        """Активирует двойной следующий daily (сохранение в БД, ~3 дня на активацию)."""
        expires = time.time() + 86400 * 3
        ok = PrivilegeManager.set_privilege(
            user_id=user_id,
            priv_type="double_daily",
            value={"active": True},
            expires_at=expires,
        )
        if ok:
            cache_set(f"double_daily_{user_id}", {"active": True}, ttl=86400 * 3)
        return ok

    @staticmethod
    def has_double_daily(user_id: int) -> bool:
        """Проверяет, есть ли неиспользованный двойной daily (из БД)."""
        data = PrivilegeManager.get_privilege(user_id, "double_daily")
        return data is not None and bool(data.get("value"))

    @staticmethod
    def consume_double_daily(user_id: int) -> bool:
        """Снимает двойной daily после использования (при получении daily бонуса)."""
        return PrivilegeManager.remove_privilege(user_id, "double_daily")

    @staticmethod
    def apply_custom_title(user_id: int, title: str, duration: int = 7) -> bool:
        """Применяет кастомный титул (сохранение в БД)."""
        expires = time.time() + duration * 86400
        return PrivilegeManager.set_privilege(
            user_id=user_id,
            priv_type="custom_title",
            value={"title": title},
            expires_at=expires,
        )

    @staticmethod
    def get_custom_title(user_id: int) -> Optional[str]:
        """Возвращает кастомный титул из БД или None."""
        data = PrivilegeManager.get_privilege(user_id, "custom_title")
        if not data or not data.get("value"):
            return None
        return data["value"].get("title")
    
    @staticmethod
    def get_xp_multiplier(user_id: int) -> int:
        """
        Возвращает множитель опыта для пользователя.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            int: Множитель (1 по умолчанию)
        """
        boost = cache_get(f"xp_boost_{user_id}")
        if boost and boost["expires"] > time.time():
            return boost["multiplier"]
        return 1

@bot.callback_query_handler(func=lambda call: call.data.startswith('use_'))
def callback_use(call: CallbackQuery):
    """
    Обработчик использования предметов.
    """
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    try:
        parts = call.data.split('_')
        if len(parts) < 2:
            bot.answer_callback_query(call.id, t(lang, "err_invalid_format"))
            return
        inv_id = int(parts[1])
    except (ValueError, IndexError):
        bot.answer_callback_query(call.id, t(lang, "err_data_error"))
        return

    # Получаем предмет
    inv_item = InventoryManager.get_item_by_inventory_id(inv_id)
    
    if not inv_item or inv_item.user_id != user_id:
        bot.answer_callback_query(call.id, t(lang, "item_not_found"))
        return
    
    # Проверяем, можно ли использовать
    if inv_item.used:
        bot.answer_callback_query(call.id, t(lang, "item_already_used"))
        return
    
    if inv_item.is_expired():
        bot.answer_callback_query(call.id, t(lang, "item_expired"))
        return
    
    # Применяем эффект в зависимости от типа
    success = False
    message = ""
    result = None
    
    item_type = inv_item.item.type
    item_data = inv_item.item.data or {}
    
    if item_type == "color_nick":
        duration = item_data.get("duration", 7)
        color = item_data.get("color", "rainbow")
        success = ItemEffects.apply_color_nick(user_id, color, duration)
        message = f"🌈 Цветное имя в боте на {duration} дн. активировано! Теперь в профиле и топах будет 🌈 перед именем."
    
    elif item_type == "custom_color":
        bot.answer_callback_query(call.id, t(lang, "send_hex_color"))
        save_temp_data(user_id, "custom_color_item", inv_id)
        bot.register_next_step_handler(call.message, process_custom_color)
        return
    
    elif item_type == "luck":
        item_name = (inv_item.item.name or "")
        if "Большой подарок" in item_name:
            win = ItemEffects.apply_luck_gift(user_id, 100, 500, big_gift=True)
        elif "Секретный подарок" in item_name:
            win = ItemEffects.apply_luck_gift(user_id, 10, 100, secret_gift=True)
        elif "min" in item_data and "max" in item_data:
            min_coins = int(item_data.get("min", 100))
            max_coins = int(item_data.get("max", 1000))
            if max_coins < min_coins:
                max_coins = min_coins
            win = ItemEffects.apply_luck_gift(user_id, min_coins, max_coins)
        else:
            win = ItemEffects.apply_luck_gift(user_id, 100, 1000)
        success = True
        message = f"🎉 Ты выиграл {win} {COM_EMOJI}!"
    
    elif item_type == "vip":
        duration = item_data.get("duration", 30)
        success = ItemEffects.apply_vip_status(user_id, duration)
        message = (
            f"👑 Ты получил VIP статус на {duration} дней!\n"
            f"• +1 монета за сообщение\n"
            f"• +15% к daily\n"
            f"• -50% налог на переводы"
        )
        
        # Отправляем уведомление в чат
        try:
            bot.send_message(
                CHAT_ID,
                f"👑 Пользователь {call.from_user.first_name} получил VIP статус!",
                parse_mode="Markdown"
            )
        except Exception:
            pass
    
    elif item_type == "legend":
        color = item_data.get("color", "rainbow")
        badge = item_data.get("badge", "👑")
        success = ItemEffects.apply_legend_status(user_id, color, badge)
        message = f"💎 Ты получил ЛЕГЕНДАРНЫЙ статус навсегда!"
        
        # Отправляем уведомление в чат
        try:
            bot.send_message(
                CHAT_ID,
                f"💎 Пользователь {call.from_user.first_name} получил ЛЕГЕНДАРНЫЙ статус!",
                parse_mode="Markdown"
            )
        except Exception:
            pass
    
    elif item_type == "ad":
        duration = item_data.get("duration", 24)
        success = ItemEffects.apply_ad_post(user_id, duration)
        message = f"📢 Заявка на рекламу создана! Администратор свяжется с тобой."
    
    elif item_type == "unwarn":
        success, message = ItemEffects.apply_unwarn(user_id)
    
    elif item_type == "mute_protection":
        duration = item_data.get("duration", 24)
        success = ItemEffects.apply_mute_protection(user_id, duration)
        message = f"🔇 Защита от мута активирована на {duration} часов!"
    
    elif item_type == "double_daily":
        success = ItemEffects.apply_double_daily(user_id)
        message = f"✨ Следующий daily бонус будет x2!"
    
    elif item_type == "xp_boost":
        duration = item_data.get("duration", 60)
        multiplier = item_data.get("multiplier", 2)
        success = ItemEffects.apply_xp_boost(user_id, duration, multiplier)
        message = f"⚡ Буст x{multiplier} активирован на {duration} минут!"
    
    elif item_type == "custom_title":
        bot.answer_callback_query(call.id, t(lang, "send_title_text"))
        save_temp_data(user_id, "custom_title_item", inv_id)
        bot.register_next_step_handler(call.message, process_custom_title)
        return
    
    else:
        message = f"✅ Предмет {inv_item.item.name} использован!"
        success = True
    
    if success:
        # Отмечаем предмет как использованный
        execute_query(
            ECONOMY_DB,
            "UPDATE inventory SET used=1, used_date=? WHERE id=?",
            (datetime.now(), inv_id)
        )
        
        bot.answer_callback_query(call.id, t(lang, "item_used_ok"))
        
        # Отправляем результат
        bot.send_message(
            call.message.chat.id,
            message,
            parse_mode="Markdown"
        )
        
        # Обновляем инвентарь
        cmd_inventory(call.message)
    else:
        bot.answer_callback_query(call.id, message or t(lang, "err_use_failed"))

