def get_shop_stats() -> Dict[str, Any]:
    """
    Возвращает статистику магазина.
    
    Returns:
        Dict[str, Any]: Статистика
    """
    try:
        items = ShopManager.get_all_items(include_out_of_stock=True)
        
        total_items = len(items)
        in_stock = sum(1 for i in items if i.stock > 0 or i.stock == -1)
        out_of_stock = sum(1 for i in items if i.stock == 0)
        unlimited = sum(1 for i in items if i.stock == -1)
        
        # Самая дорогая и дешёвая
        if items:
            max_price = max(i.price for i in items)
            min_price = min(i.price for i in items)
        else:
            max_price = min_price = 0
        
        # Статистика покупок
        purchases = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*), SUM(-amount) FROM transactions WHERE type='shop' AND date > datetime('now', '-30 days')"
        )
        
        purchases_count = purchases[0][0] if purchases else 0
        purchases_volume = purchases[0][1] if purchases and purchases[0][1] else 0
        
        return {
            "total_items": total_items,
            "in_stock": in_stock,
            "out_of_stock": out_of_stock,
            "unlimited": unlimited,
            "min_price": min_price,
            "max_price": max_price,
            "purchases_30d": purchases_count,
            "volume_30d": purchases_volume
        }
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики магазина: {e}")
        return {}

def get_user_shop_stats(user_id: int) -> Dict[str, Any]:
    """
    Возвращает статистику покупок пользователя.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        Dict[str, Any]: Статистика
    """
    try:
        # Количество покупок
        purchases = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*), SUM(-amount) FROM transactions WHERE from_id=? AND type='shop'",
            (user_id,)
        )
        
        purchase_count = purchases[0][0] if purchases else 0
        total_spent = purchases[0][1] if purchases and purchases[0][1] else 0
        
        # Предметы в инвентаре
        inventory = InventoryManager.get_user_inventory(user_id)
        unused = sum(1 for i in inventory if not i.used and not i.is_expired())
        used = sum(1 for i in inventory if i.used)
        expired = sum(1 for i in inventory if i.is_expired())
        
        return {
            "purchase_count": purchase_count,
            "total_spent": total_spent,
            "inventory_unused": unused,
            "inventory_used": used,
            "inventory_expired": expired,
            "total_items": len(inventory)
        }
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики пользователя: {e}")
        return {}

