def cleanup_expired_inventory() -> int:
    """
    Очищает истёкшие предметы из инвентаря.
    
    Returns:
        int: Количество удалённых
    """
    try:
        # Отмечаем истёкшие как использованные (или удаляем)
        result = execute_query(
            ECONOMY_DB,
            "UPDATE inventory SET used=1, used_date=? WHERE expires < datetime('now') AND used=0",
            (datetime.now(),)
        )
        
        # Не можем получить количество
        logger.info("✅ Истёкшие предметы очищены")
        return 0
        
    except Exception as e:
        logger.error(f"❌ Ошибка очистки инвентаря: {e}")
        return 0

# ============================================================================
# ПЛАНОВЫЕ ЗАДАЧИ ДЛЯ ЭКОНОМИКИ
# ============================================================================

def scheduled_economy_tasks() -> None:
    """Плановые задачи для экономики."""
    while True:
        if globals().get("_shutdown_event") is not None and globals()["_shutdown_event"].wait(timeout=3600):
            break
        time.sleep(0)  # yield
        
        try:
            # Очищаем истёкшие предметы
            cleanup_expired_inventory()
            
            # Проверяем и сбрасываем истёкшие бусты
            # (будет реализовано позже)
            
            logger.debug("✅ Плановые задачи экономики выполнены")
            
        except Exception as e:
            logger.error(f"❌ Ошибка в плановых задачах: {e}")

# Запускаем планировщик
economy_thread = threading.Thread(target=scheduled_economy_tasks, daemon=True)
economy_thread.start()
logger.info("✅ Планировщик задач экономики запущен")

