def admin_add_item(
    admin_id: int,
    name: str,
    description: str,
    price: int,
    stock: int,
    item_type: str,
    data: Optional[Dict[str, Any]] = None
) -> Tuple[bool, str, Optional[int]]:
    """
    Админ-функция для добавления товара.
    
    Args:
        admin_id: ID администратора
        name: Название
        description: Описание
        price: Цена
        stock: Количество
        item_type: Тип
        data: Данные
    
    Returns:
        Tuple[bool, str, Optional[int]]: (успех, сообщение, ID)
    """
    if not has_permission(admin_id, "can_manage_shop"):
        lang = get_user_language(admin_id)
        return False, t(lang, "admin_insufficient_rights"), None

    item_id = ShopManager.add_item(
        name=name,
        description=description,
        price=price,
        stock=stock,
        item_type=item_type,
        data=data,
        admin_id=admin_id
    )
    
    if item_id:
        return True, f"✅ Товар #{item_id} добавлен", item_id
    else:
        return False, "❌ Ошибка при добавлении товара", None

def admin_update_item(
    admin_id: int,
    item_id: int,
    **kwargs
) -> Tuple[bool, str]:
    """
    Админ-функция для обновления товара.
    
    Args:
        admin_id: ID администратора
        item_id: ID товара
        **kwargs: Поля для обновления
    
    Returns:
        Tuple[bool, str]: (успех, сообщение)
    """
    if not has_permission(admin_id, "can_manage_shop"):
        lang = get_user_language(admin_id)
        return False, t(lang, "admin_insufficient_rights")

    if ShopManager.update_item(item_id, admin_id=admin_id, **kwargs):
        return True, f"✅ Товар #{item_id} обновлён"
    else:
        return False, "❌ Ошибка при обновлении"

def admin_delete_item(admin_id: int, item_id: int) -> Tuple[bool, str]:
    """
    Админ-функция для удаления товара.
    
    Args:
        admin_id: ID администратора
        item_id: ID товара
    
    Returns:
        Tuple[bool, str]: (успех, сообщение)
    """
    if not has_permission(admin_id, "can_manage_shop"):
        lang = get_user_language(admin_id)
        return False, t(lang, "admin_insufficient_rights")

    if ShopManager.delete_item(item_id, admin_id):
        return True, f"✅ Товар #{item_id} удалён"
    else:
        return False, "❌ Ошибка при удалении"

def admin_give_item(
    admin_id: int,
    user_id: int,
    item_id: int,
    expires_days: Optional[int] = None
) -> Tuple[bool, str]:
    """
    Админ-функция для выдачи предмета пользователю.
    
    Args:
        admin_id: ID администратора
        user_id: ID пользователя
        item_id: ID товара
        expires_days: Через сколько дней истекает
    
    Returns:
        Tuple[bool, str]: (успех, сообщение)
    """
    if not has_permission(admin_id, "can_manage_economy"):
        lang = get_user_language(admin_id)
        return False, t(lang, "admin_insufficient_rights")

    inv_id = InventoryManager.add_item(user_id, item_id, expires_days)
    
    if inv_id:
        item = ShopManager.get_item(item_id)
        item_name = item.name if item else f"#{item_id}"
        logger.info(f"✅ Админ {admin_id} выдал предмет {item_name} пользователю {user_id}")
        return True, f"✅ Предмет {item_name} выдан пользователю"
    else:
        return False, "❌ Ошибка при выдаче предмета"

