#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Telegram Bot для управления чатом
Часть 5: Игры (рулетка, кости, дуэли)
Версия: 3.0 (Полная)

Эта часть содержит:
- Русская рулетка
- Игра в кости
- Дуэли между игроками (PvP)
- Система ставок и выигрышей
- Статистика игр
- Рейтинги игроков
- Достижения за игры
"""

# ============================================================================
# ПОДКЛЮЧЕНИЕ К ЧАСТЯМ 1-4
# ============================================================================

# Эта часть должна быть добавлена после Частей 1, 2, 3 и 4
# Все базовые функции уже есть в предыдущих частях

# ============================================================================
# БАЗОВЫЕ ФУНКЦИИ ДЛЯ ИГР
# ============================================================================

class GameResult:
    """Класс для хранения результата игры."""
    
    def __init__(
        self,
        user_id: int,
        game: str,
        bet: int,
        won: bool,
        profit: int,
        details: Dict[str, Any]
    ):
        self.user_id = user_id
        self.game = game
        self.bet = bet
        self.won = won
        self.profit = profit
        self.details = details
        self.timestamp = datetime.now()
    
    def to_dict(self) -> Dict[str, Any]:
        """Преобразует результат в словарь."""
        return {
            "user_id": self.user_id,
            "game": self.game,
            "bet": self.bet,
            "won": self.won,
            "profit": self.profit,
            "details": self.details,
            "timestamp": self.timestamp.isoformat()
        }
    
    def save(self) -> bool:
        """Сохраняет результат игры в БД."""
        try:
            execute_query(
                ECONOMY_DB,
                """INSERT INTO games 
                   (user_id, game, bet, result, win, profit, date) 
                   VALUES (?, ?, ?, ?, ?, ?, ?)""",
                (
                    self.user_id,
                    self.game,
                    self.bet,
                    json.dumps(self.details),
                    1 if self.won else 0,
                    self.profit,
                    self.timestamp
                )
            )
            
            # Обновляем статистику пользователя
            update_game_stats(self.user_id, self.game, self.bet, self.won)
            
            logger.info(f"✅ Игра {self.game}: пользователь {self.user_id}, "
                       f"{'выигрыш' if self.won else 'проигрыш'} {self.profit}")
            return True
            
        except Exception as e:
            logger.error(f"❌ Ошибка сохранения игры: {e}")
            return False

def update_game_stats(user_id: int, game: str, bet: int, won: bool) -> None:
    """
    Обновляет статистику игр пользователя.
    
    Args:
        user_id: ID пользователя
        game: Название игры
        bet: Ставка
        won: Победил ли
    """
    try:
        # Обновляем общую статистику
        if won:
            execute_query(
                ECONOMY_DB,
                "UPDATE users SET games_played = games_played + 1, games_won = games_won + 1 WHERE user_id=?",
                (user_id,)
            )
        else:
            execute_query(
                ECONOMY_DB,
                "UPDATE users SET games_played = games_played + 1 WHERE user_id=?",
                (user_id,)
            )
        
        # Обновляем статистику по конкретной игре
        result = execute_query(
            ECONOMY_DB,
            "SELECT total_bet, total_won, games_played, games_won FROM game_stats WHERE user_id=? AND game=?",
            (user_id, game)
        )
        
        if result:
            # Обновляем существующую запись
            total_bet, total_won, games_played, games_won = result[0]
            new_bet = total_bet + bet
            new_won = total_won + (bet if won else 0)
            new_played = games_played + 1
            new_games_won = games_won + (1 if won else 0)
            
            execute_query(
                ECONOMY_DB,
                """UPDATE game_stats 
                   SET total_bet=?, total_won=?, games_played=?, games_won=?
                   WHERE user_id=? AND game=?""",
                (new_bet, new_won, new_played, new_games_won, user_id, game)
            )
        else:
            # Создаём новую запись
            execute_query(
                ECONOMY_DB,
                """INSERT INTO game_stats 
                   (user_id, game, total_bet, total_won, games_played, games_won) 
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (user_id, game, bet, bet if won else 0, 1, 1 if won else 0)
            )
        
    except Exception as e:
        logger.error(f"❌ Ошибка обновления статистики игр: {e}")

def get_game_stats(user_id: int, game: Optional[str] = None) -> Dict[str, Any]:
    """
    Возвращает статистику игр пользователя.
    
    Args:
        user_id: ID пользователя
        game: Название игры (None = все)
    
    Returns:
        Dict[str, Any]: Статистика
    """
    try:
        if game:
            result = execute_query(
                ECONOMY_DB,
                "SELECT total_bet, total_won, games_played, games_won FROM game_stats WHERE user_id=? AND game=?",
                (user_id, game)
            )
            
            if result:
                total_bet, total_won, played, won = result[0]
                win_rate = (won / played * 100) if played > 0 else 0
                roi = ((total_won - total_bet) / total_bet * 100) if total_bet > 0 else 0
                
                return {
                    "game": game,
                    "played": played,
                    "won": won,
                    "lost": played - won,
                    "win_rate": win_rate,
                    "total_bet": total_bet,
                    "total_won": total_won,
                    "profit": total_won - total_bet,
                    "roi": roi
                }
            else:
                return {
                    "game": game,
                    "played": 0,
                    "won": 0,
                    "lost": 0,
                    "win_rate": 0,
                    "total_bet": 0,
                    "total_won": 0,
                    "profit": 0,
                    "roi": 0
                }
        else:
            # Статистика по всем играм
            result = execute_query(
                ECONOMY_DB,
                "SELECT game, total_bet, total_won, games_played, games_won FROM game_stats WHERE user_id=?",
                (user_id,)
            )
            
            games = []
            total_bet = 0
            total_won = 0
            total_played = 0
            total_wins = 0
            
            if result:
                for row in result:
                    game_data = {
                        "game": row[0],
                        "total_bet": row[1],
                        "total_won": row[2],
                        "played": row[3],
                        "won": row[4]
                    }
                    games.append(game_data)
                    
                    total_bet += row[1]
                    total_won += row[2]
                    total_played += row[3]
                    total_wins += row[4]
            
            return {
                "games": games,
                "total_played": total_played,
                "total_wins": total_wins,
                "total_bet": total_bet,
                "total_won": total_won,
                "total_profit": total_won - total_bet,
                "overall_win_rate": (total_wins / total_played * 100) if total_played > 0 else 0
            }
            
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики игр: {e}")
        return {}

# ============================================================================
# РУССКАЯ РУЛЕТКА
# ============================================================================

class RussianRoulette:
    """
    Класс для игры в русскую рулетку.
    
    Правила:
    - Игрок делает ставку
    - Барабан: 6 камор, 3 патрона (проигрыш при выстреле 1, 2 или 3)
    - Шанс проигрыша: 3/6 (50%)
    - Шанс выигрыша: 3/6 (50%) — есть шанс выиграть
    - Выигрыш: ставка × множитель (по умолчанию 1.89)
    - Антиабуз: кулдаун, лимит игр в час, лимит игр в день
    """
    # Номера выстрелов, при которых игрок проигрывает (1-based: 1, 2, 3 = три патрона из шести)
    LOSE_SHOTS = (1, 2, 3)
    
    # Настройки
    MIN_BET = ROULETTE_MIN_BET
    MAX_BET = ROULETTE_MAX_BET
    MULTIPLIER = ROULETTE_MULTIPLIER
    
    @staticmethod
    def check_anti_abuse(user_id: int) -> Tuple[bool, str, Optional[int]]:
        """
        Проверяет антиабуз: кулдаун между играми и лимит игр в час.
        Returns:
            (True, "", None) — можно играть
            (False, "key", wait_sec_or_None) — нельзя; key — ключ локализации, для cooldown — wait_sec
        """
        if user_id in DEVELOPER_IDS:
            return True, "", None
        now = time.time()
        # Кулдаун
        cache_key_cd = f"roulette_cd_{user_id}"
        last_ts = cache_get(cache_key_cd)
        if last_ts is not None:
            elapsed = now - last_ts
            if elapsed < ROULETTE_COOLDOWN_SEC:
                wait_sec = int(ROULETTE_COOLDOWN_SEC - elapsed)
                return False, "roulette_cooldown", wait_sec
        # Лимит игр в час (по БД)
        try:
            row = execute_query(
                ECONOMY_DB,
                "SELECT COUNT(*) FROM games WHERE user_id = ? AND game = 'roulette' AND date >= datetime('now', '-1 hour')",
                (user_id,),
            )
            count = row[0][0] if row and row[0] else 0
            if count >= ROULETTE_MAX_PER_HOUR:
                return False, "roulette_max_per_hour", None
        except Exception as e:
            logger.debug("roulette anti-abuse count: %s", e)
        # Лимит игр в сутки (антиабуз)
        try:
            row = execute_query(
                ECONOMY_DB,
                "SELECT COUNT(*) FROM games WHERE user_id = ? AND game = 'roulette' AND date >= date('now')",
                (user_id,),
            )
            count_day = row[0][0] if row and row[0] else 0
            if count_day >= ROULETTE_MAX_PER_DAY:
                return False, "roulette_max_per_day", None
        except Exception as e:
            logger.debug("roulette anti-abuse daily: %s", e)
        return True, "", None
    
    @staticmethod
    def _set_cooldown(user_id: int) -> None:
        """Ставит кулдаун после игры (для антиабуза)."""
        if user_id in DEVELOPER_IDS:
            return
        cache_set(f"roulette_cd_{user_id}", time.time(), ttl=ROULETTE_COOLDOWN_SEC)
    
    @staticmethod
    def validate_bet(bet: int, user_id: int) -> Tuple[bool, str]:
        """
        Проверяет корректность ставки.
        
        Args:
            bet: Ставка
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, str]: (валидно, сообщение об ошибке)
        """
        if bet < RussianRoulette.MIN_BET:
            return False, f"❌ Минимальная ставка: {RussianRoulette.MIN_BET} {COM_EMOJI}"
        
        if bet > RussianRoulette.MAX_BET:
            return False, f"❌ Максимальная ставка: {RussianRoulette.MAX_BET} {COM_EMOJI}"
        
        balance = get_balance(user_id)
        if balance < bet:
            return False, f"❌ Недостаточно средств. Баланс: {balance} {COM_EMOJI}"
        
        return True, ""
    
    @staticmethod
    def play(user_id: int, bet: int) -> GameResult:
        """
        Играет в русскую рулетку.
        
        Args:
            user_id: ID пользователя
            bet: Ставка
        
        Returns:
            GameResult: Результат игры
        """
        # Проверяем ставку
        valid, error = RussianRoulette.validate_bet(bet, user_id)
        if not valid:
            raise ValueError(error)
        
        # Списываем ставку (атомарно; при гонке можем не списать даже после validate_bet)
        if not remove_coins(user_id, bet, "Ставка в русской рулетке"):
            raise ValueError(f"❌ Недостаточно средств. Баланс: {get_balance(user_id)} {COM_EMOJI}")
        
        # Определяем результат: 6 камор, проигрыш при выстрелах из LOSE_SHOTS
        shot = random.randint(1, 6)
        won = shot not in RussianRoulette.LOSE_SHOTS
        
        if won:
            win_amount = int(round(bet * RussianRoulette.MULTIPLIER))
            profit = win_amount - bet
            add_coins(user_id, win_amount, "Выигрыш в русской рулетке")
            result_text = f"🎉 **ПОВЕЗЛО!** Выстрел #{shot} - пустой!\nТы выиграл {win_amount} {COM_EMOJI}!"
        else:
            profit = -bet
            result_text = f"💥 **БАХ!** Выстрел #{shot} - пуля твоя!\nТы потерял {bet} {COM_EMOJI}..."
        
        # Создаём результат
        result = GameResult(
            user_id=user_id,
            game="roulette",
            bet=bet,
            won=won,
            profit=profit,
            details={
                "shot": shot,
                "multiplier": RussianRoulette.MULTIPLIER
            }
        )
        
        # Сохраняем
        result.save()
        # Антиабуз: кулдаун до следующей игры
        RussianRoulette._set_cooldown(user_id)
        
        return result, result_text

# ============================================================================
# ИГРА В КОСТИ
# ============================================================================

class DiceGame:
    """
    Класс для игры в кости.
    
    Правила:
    - Игрок делает ставку и загадывает число от 1 до 6
    - Бросается кубик
    - Если число совпало - выигрыш x6
    - Если нет - проигрыш ставки
    """
    
    # Настройки
    MIN_BET = DICE_MIN_BET
    MAX_BET = DICE_MAX_BET
    MULTIPLIER = DICE_MULTIPLIER
    
    @staticmethod
    def validate_bet(bet: int, guess: int, user_id: int) -> Tuple[bool, str]:
        """
        Проверяет корректность ставки и числа.
        
        Args:
            bet: Ставка
            guess: Загаданное число
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, str]: (валидно, сообщение об ошибке)
        """
        if guess < 1 or guess > 6:
            return False, "❌ Число должно быть от 1 до 6"
        
        if bet < DiceGame.MIN_BET:
            return False, f"❌ Минимальная ставка: {DiceGame.MIN_BET} {COM_EMOJI}"
        
        if bet > DiceGame.MAX_BET:
            return False, f"❌ Максимальная ставка: {DiceGame.MAX_BET} {COM_EMOJI}"
        
        balance = get_balance(user_id)
        if balance < bet:
            return False, f"❌ Недостаточно средств. Баланс: {balance} {COM_EMOJI}"
        
        return True, ""
    
    @staticmethod
    def play(user_id: int, bet: int, guess: int, roll: Optional[int] = None) -> Tuple[GameResult, str]:
        """
        Играет в кости. Если передан roll (1–6), используется он (результат кубика Telegram);
        иначе бросок случайный.

        Args:
            user_id: ID пользователя
            bet: Ставка
            guess: Загаданное число
            roll: Результат броска 1–6 (если None — random)

        Returns:
            Tuple[GameResult, str]: (результат, текст сообщения)
        """
        valid, error = DiceGame.validate_bet(bet, guess, user_id)
        if not valid:
            raise ValueError(error)

        if not remove_coins(user_id, bet, "Ставка в кости"):
            raise ValueError(f"❌ Недостаточно средств. Баланс: {get_balance(user_id)} {COM_EMOJI}")

        if roll is not None:
            roll = max(1, min(6, int(roll)))
        else:
            roll = random.randint(1, 6)

        won = roll == guess

        if won:
            profit = bet * (DiceGame.MULTIPLIER - 1)
            add_coins(user_id, bet * DiceGame.MULTIPLIER, "Выигрыш в кости")
            result_text = f"🎲 **УГАДАЛ!** Выпало {roll}!\nТы выиграл {bet * DiceGame.MULTIPLIER} {COM_EMOJI}!"
        else:
            profit = -bet
            result_text = f"🎲 **МИМО!** Выпало {roll}, а ты ставил на {guess}\nТы потерял {bet} {COM_EMOJI}..."

        result = GameResult(
            user_id=user_id,
            game="dice",
            bet=bet,
            won=won,
            profit=profit,
            details={
                "roll": roll,
                "guess": guess,
                "multiplier": DiceGame.MULTIPLIER
            }
        )
        result.save()

        return result, result_text

# ============================================================================
# ИГРА «МОНЕТКА» (ОРЁЛ/РЕШКА) СО СТАВКОЙ
# ============================================================================

class FlipGame:
    """
    Класс для игры в орёл/решка со ставкой.
    
    Правила:
    - Игрок делает ставку и выбирает орёл или решка
    - Шанс 50/50
    - Выигрыш: ставка x2
    """
    
    MIN_BET = FLIP_MIN_BET
    MAX_BET = FLIP_MAX_BET
    MULTIPLIER = FLIP_MULTIPLIER
    
    @staticmethod
    def validate_bet(bet: int, user_id: int) -> Tuple[bool, str]:
        if bet < FlipGame.MIN_BET:
            return False, f"❌ Минимальная ставка: {FlipGame.MIN_BET} {COM_EMOJI}"
        if bet > FlipGame.MAX_BET:
            return False, f"❌ Максимальная ставка: {FlipGame.MAX_BET} {COM_EMOJI}"
        balance = get_balance(user_id)
        if balance < bet:
            return False, f"❌ Недостаточно средств. Баланс: {balance} {COM_EMOJI}"
        return True, ""
    
    @staticmethod
    def play(user_id: int, bet: int, guess: str) -> Tuple[GameResult, str]:
        """guess: 'орёл' или 'решка'. Возвращает (GameResult, текст)."""
        valid, error = FlipGame.validate_bet(bet, user_id)
        if not valid:
            raise ValueError(error)
        if not remove_coins(user_id, bet, "Ставка в монетке"):
            raise ValueError(f"❌ Недостаточно средств. Баланс: {get_balance(user_id)} {COM_EMOJI}")
        side = "орёл" if random.random() < 0.5 else "решка"
        won = (side == guess)
        if won:
            profit = bet * (FlipGame.MULTIPLIER - 1)
            add_coins(user_id, bet * FlipGame.MULTIPLIER, "Выигрыш в монетке")
            result_text = f"🪙 **УГАДАЛ!** Выпало: **{side}**.\nТы выиграл {bet * FlipGame.MULTIPLIER} {COM_EMOJI}!"
        else:
            profit = -bet
            result_text = f"🪙 **МИМО!** Выпало: **{side}**, ты ставил на **{guess}**.\nТы потерял {bet} {COM_EMOJI}..."
        result = GameResult(
            user_id=user_id,
            game="flip",
            bet=bet,
            won=won,
            profit=profit,
            details={"side": side, "guess": guess, "multiplier": FlipGame.MULTIPLIER}
        )
        result.save()
        return result, result_text

# ============================================================================
# PvP ИГРЫ (ТОЛЬКО USER VS USER)
# ============================================================================

def _pvp_now_ts() -> datetime:
    return datetime.now()


def _pvp_json_dumps(obj: Any) -> str:
    try:
        return json.dumps(obj, ensure_ascii=False)
    except Exception:
        return "{}"


def _pvp_json_loads(s: Optional[str]) -> Dict[str, Any]:
    if not s:
        return {}
    try:
        v = json.loads(s)
        return v if isinstance(v, dict) else {}
    except Exception:
        return {}


def _pvp_hold_coins(conn: sqlite3.Connection, user_id: int, amount: int, offer_id: int, reason: str) -> bool:
    """Эскроу-холд: атомарно списываем с баланса и фиксируем в pvp_escrow + transactions."""
    if amount <= 0:
        return False
    # ensure user exists in economy users
    register_user(user_id)
    cur = conn.execute(
        "UPDATE users SET balance = balance - ?, total_spent = total_spent + ? WHERE user_id = ? AND balance >= ?",
        (amount, amount, user_id, amount),
    )
    if cur.rowcount <= 0:
        return False
    conn.execute(
        "INSERT OR REPLACE INTO pvp_escrow (offer_id, user_id, amount, status, created_at) VALUES (?, ?, ?, 'held', ?)",
        (offer_id, user_id, amount, _pvp_now_ts()),
    )
    conn.execute(
        "INSERT INTO transactions (from_id, to_id, amount, reason, date, type) VALUES (?, ?, ?, ?, ?, 'game')",
        (user_id, 0, -amount, reason, _pvp_now_ts()),
    )
    return True


def _pvp_refund(conn: sqlite3.Connection, offer_id: int, user_id: int, amount: int, reason: str) -> None:
    """Возврат эскроу."""
    if amount <= 0:
        return
    conn.execute(
        "UPDATE users SET balance = balance + ?, total_earned = total_earned + ? WHERE user_id = ?",
        (amount, amount, user_id),
    )
    conn.execute(
        "UPDATE pvp_escrow SET status = 'refunded' WHERE offer_id = ? AND user_id = ?",
        (offer_id, user_id),
    )
    conn.execute(
        "INSERT INTO transactions (from_id, to_id, amount, reason, date, type) VALUES (?, ?, ?, ?, ?, 'game')",
        (0, user_id, amount, reason, _pvp_now_ts()),
    )


def _pvp_payout(conn: sqlite3.Connection, offer_id: int, winner_id: int, amount: int, reason: str) -> None:
    """Выплата победителю."""
    if amount <= 0:
        return
    conn.execute(
        "UPDATE users SET balance = balance + ?, total_earned = total_earned + ? WHERE user_id = ?",
        (amount, amount, winner_id),
    )
    conn.execute(
        "INSERT INTO transactions (from_id, to_id, amount, reason, date, type) VALUES (?, ?, ?, ?, ?, 'game')",
        (0, winner_id, amount, reason, _pvp_now_ts()),
    )
    conn.execute(
        "UPDATE pvp_escrow SET status = 'released' WHERE offer_id = ?",
        (offer_id,),
    )


def pvp_expire_offers() -> int:
    """Истекающие pending-офферы → expired + возврат player1 (если был холд)."""
    expired = 0
    cutoff = _pvp_now_ts() - timedelta(seconds=max(60, PVP_OFFER_TTL_SEC))
    try:
        with database_connection(ECONOMY_DB) as conn:
            rows = conn.execute(
                "SELECT id, player1_id, bet FROM pvp_offers WHERE status = 'pending' AND player2_id IS NULL AND created_at < ?",
                (cutoff,),
            ).fetchall()
            for offer_id, p1, bet in rows:
                # mark expired
                conn.execute(
                    "UPDATE pvp_offers SET status='expired', finished_at=? WHERE id=? AND status='pending' AND player2_id IS NULL",
                    (_pvp_now_ts(), offer_id),
                )
                # refund if escrow held
                escrow = conn.execute(
                    "SELECT amount, status FROM pvp_escrow WHERE offer_id=? AND user_id=?",
                    (offer_id, p1),
                ).fetchone()
                if escrow and escrow[1] == "held":
                    _pvp_refund(conn, offer_id, int(p1), int(escrow[0] or bet or 0), "PvP: истёк вызов — возврат ставки")
                expired += 1
            conn.commit()
    except Exception as e:
        logger.debug("pvp_expire_offers: %s", e)
    return expired


def _pvp_expire_worker() -> None:
    while True:
        try:
            pvp_expire_offers()
        except Exception:
            pass
        time.sleep(60)


if PVP_GAMES_ONLY:
    try:
        threading.Thread(target=_pvp_expire_worker, daemon=True).start()
    except Exception:
        pass


def pvp_create_offer(player1_id: int, game_type: str, bet: int, params: Dict[str, Any]) -> int:
    """Создаёт PvP оффер (без публикации), делает эскроу-холд у player1. Возвращает offer_id."""
    if bet <= 0:
        raise ValueError("❌ Неверная ставка")
    if game_type not in ("dice", "coin"):
        raise ValueError("❌ Неверный тип игры")
    # limits: reuse existing min/max where possible
    if game_type == "dice":
        if bet < DICE_MIN_BET or bet > DICE_MAX_BET:
            raise ValueError(f"❌ Ставка должна быть {DICE_MIN_BET}..{DICE_MAX_BET} {COM_EMOJI}")
    if game_type == "coin":
        if bet < FLIP_MIN_BET or bet > FLIP_MAX_BET:
            raise ValueError(f"❌ Ставка должна быть {FLIP_MIN_BET}..{FLIP_MAX_BET} {COM_EMOJI}")

    now = _pvp_now_ts()
    with database_connection(ECONOMY_DB) as conn:
        cur = conn.execute(
            "INSERT INTO pvp_offers (type, status, chat_id, message_id, player1_id, player2_id, bet, params_json, created_at) "
            "VALUES (?, 'draft', 0, NULL, ?, NULL, ?, ?, ?)",
            (game_type, player1_id, bet, _pvp_json_dumps(params), now),
        )
        offer_id = int(cur.lastrowid)
        ok = _pvp_hold_coins(conn, player1_id, bet, offer_id, f"PvP {game_type}: холд ставки (оффер #{offer_id})")
        if not ok:
            conn.execute("DELETE FROM pvp_offers WHERE id=?", (offer_id,))
            conn.execute("DELETE FROM pvp_escrow WHERE offer_id=?", (offer_id,))
            conn.commit()
            raise ValueError(f"❌ Недостаточно средств. Баланс: {get_balance(player1_id)} {COM_EMOJI}")
        conn.execute("UPDATE pvp_offers SET status='pending' WHERE id=?", (offer_id,))
        conn.commit()
        return offer_id


def pvp_post_offer(offer_id: int, chat_id: int, message_id: int) -> bool:
    """Закрепляет оффер за чатом и сообщением."""
    try:
        with database_connection(ECONOMY_DB) as conn:
            cur = conn.execute(
                "UPDATE pvp_offers SET chat_id=?, message_id=? WHERE id=? AND status='pending' AND chat_id=0",
                (chat_id, message_id, offer_id),
            )
            conn.commit()
            return cur.rowcount > 0
    except Exception:
        return False


def _pvp_resolve_coin(params: Dict[str, Any]) -> Dict[str, Any]:
    side = "heads" if random.random() < 0.5 else "tails"
    return {"flip": side, "p1_choice": params.get("side")}


def _pvp_resolve_dice() -> Dict[str, Any]:
    return {"p1_roll": random.randint(1, 6), "p2_roll": random.randint(1, 6)}


def pvp_accept_and_resolve(offer_id: int, player2_id: int) -> Tuple[bool, str, Optional[Dict[str, Any]]]:
    """
    Принять pending-оффер, сделать холд ставки у player2, резолвить игру, выплатить победителю или вернуть при ничьей.
    Возвращает (ok, text, result_dict).
    """
    pvp_expire_offers()
    now = _pvp_now_ts()
    with database_connection(ECONOMY_DB) as conn:
        row = conn.execute(
            "SELECT type, status, chat_id, player1_id, player2_id, bet, params_json FROM pvp_offers WHERE id=?",
            (offer_id,),
        ).fetchone()
        if not row:
            return False, "❌ Игра не найдена", None
        game_type, status, chat_id, p1, p2, bet, params_json = row
        p1 = int(p1)
        bet = int(bet)
        if status != "pending" or (p2 is not None and int(p2 or 0) != 0):
            return False, "⏳ Этот вызов уже принят или завершён", None
        if player2_id == p1:
            return False, "❌ Нельзя играть с самим собой", None
        # claim offer atomically
        cur = conn.execute(
            "UPDATE pvp_offers SET player2_id=?, accepted_at=?, status='active' WHERE id=? AND status='pending' AND player2_id IS NULL",
            (player2_id, now, offer_id),
        )
        if cur.rowcount <= 0:
            return False, "⏳ Этот вызов уже принят", None

        ok = _pvp_hold_coins(conn, player2_id, bet, offer_id, f"PvP {game_type}: холд ставки (оффер #{offer_id})")
        if not ok:
            # rollback accept
            conn.execute(
                "UPDATE pvp_offers SET player2_id=NULL, accepted_at=NULL, status='pending' WHERE id=?",
                (offer_id,),
            )
            conn.commit()
            return False, f"❌ У тебя недостаточно монет для ставки {bet} {COM_EMOJI}", None

        params = _pvp_json_loads(params_json)

        # resolve
        winner_id: Optional[int] = None
        result: Dict[str, Any] = {"type": game_type, "bet": bet, "offer_id": offer_id, "p1": p1, "p2": player2_id}
        if game_type == "coin":
            res = _pvp_resolve_coin(params)
            result.update(res)
            p1_choice = str(res.get("p1_choice") or "")
            flip = str(res.get("flip") or "")
            winner_id = p1 if p1_choice == flip else player2_id
        elif game_type == "dice":
            res = _pvp_resolve_dice()
            result.update(res)
            r1, r2 = int(res["p1_roll"]), int(res["p2_roll"])
            if r1 > r2:
                winner_id = p1
            elif r2 > r1:
                winner_id = player2_id
            else:
                winner_id = None
        else:
            winner_id = None

        if winner_id is None:
            # tie: refund both
            _pvp_refund(conn, offer_id, p1, bet, f"PvP {game_type}: ничья — возврат ставки (оффер #{offer_id})")
            _pvp_refund(conn, offer_id, player2_id, bet, f"PvP {game_type}: ничья — возврат ставки (оффер #{offer_id})")
            conn.execute(
                "UPDATE pvp_offers SET status='finished', result_json=?, finished_at=? WHERE id=?",
                (_pvp_json_dumps({**result, "winner": None}), _pvp_now_ts(), offer_id),
            )
            conn.commit()
            return True, "🤝 Ничья! Ставки возвращены.", {**result, "winner": None}

        # payout: pot = 2*bet
        _pvp_payout(conn, offer_id, winner_id, bet * 2, f"PvP {game_type}: банк {bet*2} {COM_EMOJI} (оффер #{offer_id})")
        conn.execute(
            "UPDATE pvp_offers SET status='finished', result_json=?, finished_at=? WHERE id=?",
            (_pvp_json_dumps({**result, "winner": winner_id}), _pvp_now_ts(), offer_id),
        )

        # record per-user game rows in games table
        for uid, won in ((p1, winner_id == p1), (player2_id, winner_id == player2_id)):
            details = {**result, "winner": winner_id, "you_won": bool(won)}
            conn.execute(
                "INSERT INTO games (user_id, game, bet, result, win, profit, date) VALUES (?, ?, ?, ?, ?, ?, ?)",
                (uid, f"pvp_{game_type}", bet, _pvp_json_dumps(details), 1 if won else 0, (bet if won else -bet), _pvp_now_ts()),
            )

        conn.commit()

    # stats/achievements outside transaction using existing helpers
    try:
        update_game_stats(p1, f"pvp_{game_type}", bet, winner_id == p1)
        update_game_stats(player2_id, f"pvp_{game_type}", bet, winner_id == player2_id)
        # achievements: call for each participant (without saving GameResult again)
        for uid, won in ((p1, winner_id == p1), (player2_id, winner_id == player2_id)):
            gr = GameResult(user_id=uid, game=f"pvp_{game_type}", bet=bet, won=bool(won), profit=(bet if won else -bet), details=result)
            check_game_achievements(uid, gr)
    except Exception as e:
        logger.debug("pvp stats/achievements: %s", e)

    if game_type == "coin":
        flip = str(result.get("flip") or "")
        flip_ru = "орёл" if flip == "heads" else "решка"
        p1_choice = str(result.get("p1_choice") or "")
        p1_choice_ru = "орёл" if p1_choice == "heads" else "решка"
        text = (
            f"🪙 PvP монетка! Выпало: **{flip_ru}**. "
            f"Выбор игрока 1: **{p1_choice_ru}**. "
            f"Победитель: <a href=\"tg://user?id={winner_id}\">игрок</a>"
        )
        return True, text, {**result, "winner": winner_id}

    # dice
    text = (
        f"🎲 PvP кости! Игрок 1: {result.get('p1_roll')} · Игрок 2: {result.get('p2_roll')}. "
        f"Победитель: <a href=\"tg://user?id={winner_id}\">игрок</a>"
    )
    return True, text, {**result, "winner": winner_id}
# ============================================================================
# ДУЭЛИ (PvP)
# ============================================================================

class Duel:
    """
    Класс для проведения дуэлей между игроками.
    
    Правила:
    - Два игрока делают ставки
    - Каждый кидает кубик
    - У кого больше - тот выигрывает раунд
    - Можно играть до N побед (best of)
    """
    
    # Настройки
    MIN_BET = DUEL_MIN_BET
    MAX_BET = DUEL_MAX_BET
    MAX_ROUNDS = DUEL_MAX_ROUNDS
    
    def __init__(self, duel_id: int, challenger_id: int, opponent_id: int, bet: int, max_wins: int = 1, chat_id: int = 0):
        self.id = duel_id
        self.challenger_id = challenger_id
        self.opponent_id = opponent_id
        self.bet = bet
        self.max_wins = max_wins
        self.chat_id = chat_id  # чат, в котором создана дуэль (для отмены при выходе)
        
        self.challenger_wins = 0
        self.opponent_wins = 0
        self.current_round = 0
        self.status = "waiting"  # waiting, active, finished, cancelled
        self.challenger_roll = None
        self.opponent_roll = None
        self.round_results = []
        
        self.created_at = datetime.now()
        self.updated_at = datetime.now()
        self.expires_at = datetime.now() + timedelta(minutes=5)
        self.round_started_at = None  # устанавливается в accept() и _resolve_round() для таймаута хода
    
    def to_dict(self) -> Dict[str, Any]:
        """Преобразует дуэль в словарь."""
        return {
            "id": self.id,
            "challenger_id": self.challenger_id,
            "opponent_id": self.opponent_id,
            "bet": self.bet,
            "max_wins": self.max_wins,
            "chat_id": self.chat_id,
            "challenger_wins": self.challenger_wins,
            "opponent_wins": self.opponent_wins,
            "current_round": self.current_round,
            "status": self.status,
            "round_results": self.round_results,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
            "expires_at": self.expires_at.isoformat()
        }
    
    def is_expired(self) -> bool:
        """Проверяет, истекла ли дуэль."""
        return datetime.now() > self.expires_at
    
    def can_join(self, user_id: int) -> Tuple[bool, str]:
        """
        Проверяет, может ли пользователь присоединиться к дуэли.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, str]: (можно ли, сообщение)
        """
        if self.status != "waiting":
            return False, "❌ Дуэль уже началась или закончилась"
        
        if user_id != self.opponent_id:
            return False, "❌ Это не твой вызов"
        
        if self.is_expired():
            return False, "❌ Время для принятия дуэли истекло"
        
        balance = get_balance(user_id)
        if balance < self.bet:
            return False, f"❌ Недостаточно средств. Нужно: {self.bet} {COM_EMOJI}"
        
        return True, ""
    
    def accept(self, user_id: int) -> Tuple[bool, str]:
        """
        Принимает дуэль.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, str]: (успех, сообщение)
        """
        can, msg = self.can_join(user_id)
        if not can:
            return False, msg
        
        self.status = "active"
        self.updated_at = datetime.now()
        self.round_started_at = datetime.now()
        
        logger.info(f"✅ Дуэль #{self.id} принята игроком {user_id}")
        return True, "✅ Дуэль принята! Игроки, кидайте кубики!"
    
    def decline(self, user_id: int) -> Tuple[bool, str]:
        """
        Отклоняет дуэль.
        
        Args:
            user_id: ID пользователя
        
        Returns:
            Tuple[bool, str]: (успех, сообщение)
        """
        if user_id != self.opponent_id:
            return False, "❌ Это не твой вызов"
        
        self.status = "cancelled"
        self.updated_at = datetime.now()
        
        logger.info(f"❌ Дуэль #{self.id} отклонена игроком {user_id}")
        return True, "❌ Дуэль отклонена"
    
    def roll(self, user_id: int, roll: int) -> Tuple[bool, str, bool]:
        """
        Игрок кидает кубик.
        
        Args:
            user_id: ID пользователя
            roll: Результат броска
        
        Returns:
            Tuple[bool, str, bool]: (успех, сообщение, раунд завершён)
        """
        if self.status != "active":
            return False, "❌ Дуэль не активна", False
        
        if user_id == self.challenger_id:
            if self.challenger_roll is not None:
                return False, "❌ Ты уже кинул кубик в этом раунде", False
            self.challenger_roll = roll
            logger.info(f"🎲 Дуэль #{self.id}: вызвавший кинул {roll}")
        elif user_id == self.opponent_id:
            if self.opponent_roll is not None:
                return False, "❌ Ты уже кинул кубик в этом раунде", False
            self.opponent_roll = roll
            logger.info(f"🎲 Дуэль #{self.id}: противник кинул {roll}")
        else:
            return False, "❌ Ты не участвуешь в этой дуэли", False
        
        # Проверяем, кинули ли оба
        round_complete = self.challenger_roll is not None and self.opponent_roll is not None
        
        if round_complete:
            self._resolve_round()
        
        self.updated_at = datetime.now()
        return True, f"🎲 Ты выбросил {roll}!", round_complete
    
    def _resolve_round(self) -> None:
        """Завершает текущий раунд и определяет победителя."""
        self.current_round += 1
        
        if self.challenger_roll > self.opponent_roll:
            self.challenger_wins += 1
            winner = "challenger"
            round_winner = self.challenger_id
        elif self.opponent_roll > self.challenger_roll:
            self.opponent_wins += 1
            winner = "opponent"
            round_winner = self.opponent_id
        else:
            winner = "draw"
            round_winner = None
        
        # Сохраняем результат раунда
        self.round_results.append({
            "round": self.current_round,
            "challenger_roll": self.challenger_roll,
            "opponent_roll": self.opponent_roll,
            "winner": winner
        })
        
        # Сбрасываем броски и обновляем время старта следующего раунда (для таймаута)
        self.challenger_roll = None
        self.opponent_roll = None
        self.round_started_at = datetime.now()
        
        logger.info(f"⚔️ Дуэль #{self.id}: раунд {self.current_round} завершён, победитель: {winner}")
    
    def is_finished(self) -> bool:
        """Проверяет, завершена ли дуэль."""
        return (self.challenger_wins >= self.max_wins or 
                self.opponent_wins >= self.max_wins or
                self.status in ["finished", "cancelled"])
    
    def get_winner(self) -> Optional[int]:
        """
        Возвращает ID победителя.
        
        Returns:
            Optional[int]: ID победителя или None
        """
        if self.challenger_wins >= self.max_wins:
            return self.challenger_id
        elif self.opponent_wins >= self.max_wins:
            return self.opponent_id
        return None
    
    def finish(self) -> Tuple[Optional[int], int]:
        """
        Завершает дуэль и переводит монеты.
        
        Returns:
            Tuple[Optional[int], int]: (ID победителя, сумма выигрыша)
        """
        winner_id = self.get_winner()
        
        if winner_id:
            # Рассчитываем выигрыш
            total_pot = self.bet * 2  # Оба игрока поставили
            transfer_coins(
                self.challenger_id if winner_id == self.opponent_id else self.opponent_id,
                winner_id,
                self.bet * 2,
                f"Выигрыш в дуэли #{self.id}"
            )
            
            self.status = "finished"
            self.updated_at = datetime.now()
            
            # Сохраняем игры для обоих игроков
            GameResult(
                user_id=self.challenger_id,
                game="duel",
                bet=self.bet,
                won=winner_id == self.challenger_id,
                profit=self.bet if winner_id == self.challenger_id else -self.bet,
                details={"duel_id": self.id, "opponent": self.opponent_id, "wins": self.challenger_wins}
            ).save()
            
            GameResult(
                user_id=self.opponent_id,
                game="duel",
                bet=self.bet,
                won=winner_id == self.opponent_id,
                profit=self.bet if winner_id == self.opponent_id else -self.bet,
                details={"duel_id": self.id, "opponent": self.challenger_id, "wins": self.opponent_wins}
            ).save()
            
            logger.info(f"🏆 Дуэль #{self.id} завершена! Победитель: {winner_id}")
            return winner_id, self.bet * 2
        
        return None, 0

# ============================================================================
# УПРАВЛЕНИЕ ДУЭЛЯМИ
# ============================================================================

class DuelManager:
    """
    Класс для управления активными дуэлями.
    """
    
    def __init__(self):
        self.duels: Dict[int, Duel] = {}
        self.counter = 0
        self.lock = threading.Lock()
    
    def create_duel(
        self,
        challenger_id: int,
        opponent_id: int,
        bet: int,
        max_wins: int = 1,
        chat_id: int = 0
    ) -> Optional[Duel]:
        """
        Создаёт новую дуэль.
        
        Args:
            challenger_id: ID вызвавшего
            opponent_id: ID противника
            bet: Ставка
            max_wins: Побед для победы
            chat_id: ID чата, в котором создана дуэль
        
        Returns:
            Optional[Duel]: Созданная дуэль или None
        """
        with self.lock:
            # Проверяем ставку
            if bet < Duel.MIN_BET:
                return None
            
            if bet > Duel.MAX_BET:
                return None
            
            # Проверяем балансы
            chall_balance = get_balance(challenger_id)
            opp_balance = get_balance(opponent_id)
            
            if chall_balance < bet:
                return None
            
            if opp_balance < bet:
                return None
            
            # Создаём дуэль
            self.counter += 1
            duel = Duel(
                duel_id=self.counter,
                challenger_id=challenger_id,
                opponent_id=opponent_id,
                bet=bet,
                max_wins=max_wins,
                chat_id=chat_id
            )
            
            self.duels[self.counter] = duel
            logger.info(f"✅ Создана дуэль #{self.counter}: {challenger_id} vs {opponent_id}, ставка {bet}")
            
            return duel
    
    def get_duel(self, duel_id: int) -> Optional[Duel]:
        """Возвращает дуэль по ID."""
        return self.duels.get(duel_id)
    
    def remove_duel(self, duel_id: int) -> bool:
        """Удаляет дуэль."""
        with self.lock:
            if duel_id in self.duels:
                del self.duels[duel_id]
                logger.info(f"🗑️ Дуэль #{duel_id} удалена")
                return True
        return False
    
    def cleanup_expired(self) -> int:
        """Очищает истёкшие дуэли."""
        with self.lock:
            expired = []
            for duel_id, duel in self.duels.items():
                if duel.is_expired() and duel.status == "waiting":
                    expired.append(duel_id)
            
            for duel_id in expired:
                del self.duels[duel_id]
            
            if expired:
                logger.info(f"🧹 Очищено {len(expired)} истёкших дуэлей")
            
            return len(expired)
    
    def get_active_duels_for_user(self, user_id: int) -> List[Duel]:
        """Возвращает активные дуэли пользователя."""
        return [
            duel for duel in self.duels.values()
            if duel.status == "active" and (duel.challenger_id == user_id or duel.opponent_id == user_id)
        ]
    
    def get_waiting_duels_for_user(self, user_id: int) -> List[Duel]:
        """Возвращает ожидающие дуэли для пользователя."""
        return [
            duel for duel in self.duels.values()
            if duel.status == "waiting" and duel.opponent_id == user_id
        ]

    def get_duels_in_chat_involving_user(self, chat_id: int, user_id: int) -> List[tuple]:
        """Возвращает список (duel_id, duel) дуэлей в данном чате с участием user_id (waiting или active)."""
        return [
            (duel_id, duel) for duel_id, duel in self.duels.items()
            if getattr(duel, "chat_id", 0) == chat_id
            and duel.status in ("waiting", "active")
            and (duel.challenger_id == user_id or duel.opponent_id == user_id)
        ]

    def cleanup_round_timeouts(self) -> int:
        """Обрабатывает таймаут хода в активных дуэлях: проигрыш раунда или отмена. Возвращает количество обработанных."""
        timeout_sec = (DUEL_ROUND_TIMEOUT_MINUTES or 5) * 60
        now = datetime.now()
        processed = 0
        with self.lock:
            for duel_id in list(self.duels.keys()):
                duel = self.duels.get(duel_id)
                if not duel or duel.status != "active":
                    continue
                started = getattr(duel, "round_started_at", None)
                if not started or (now - started).total_seconds() < timeout_sec:
                    continue
                processed += 1
                chat_id = getattr(duel, "chat_id", 0)
                _dl = get_user_language(duel.challenger_id)
                if duel.challenger_roll is not None and duel.opponent_roll is None:
                    duel.opponent_roll = 0
                    duel._resolve_round()
                    try:
                        bot.send_message(chat_id, t(_dl, "duel_timeout_challenger", duel_id=duel_id))
                    except Exception:
                        pass
                elif duel.challenger_roll is None and duel.opponent_roll is not None:
                    duel.challenger_roll = 0
                    duel._resolve_round()
                    try:
                        bot.send_message(chat_id, t(_dl, "duel_timeout_opponent", duel_id=duel_id))
                    except Exception:
                        pass
                else:
                    try:
                        bot.send_message(chat_id, t(_dl, "duel_cancelled_timeout", duel_id=duel_id))
                    except Exception:
                        pass
                    del self.duels[duel_id]
                    logger.info(f"Дуэль #{duel_id} отменена по таймауту (никто не сделал ход)")
                    continue
                if duel.is_finished():
                    winner_id = duel.get_winner()
                    if winner_id:
                        duel.finish()
                    try:
                        bot.send_message(chat_id, t(_dl, "duel_finished_timeout", duel_id=duel_id))
                    except Exception:
                        pass
                    del self.duels[duel_id]
                    logger.info(f"Дуэль #{duel_id} завершена по таймауту раунда")
        return processed

# Создаём глобальный менеджер дуэлей
duel_manager = DuelManager()

# ============================================================================
# СТАТИСТИКА ДУЭЛЕЙ
# ============================================================================

def get_duel_stats(user_id: int) -> Dict[str, Any]:
    """
    Возвращает статистику дуэлей пользователя.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        Dict[str, Any]: Статистика дуэлей
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            """SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN win=1 THEN 1 ELSE 0 END) as wins,
                SUM(CASE WHEN win=0 THEN 1 ELSE 0 END) as losses,
                SUM(profit) as total_profit,
                AVG(bet) as avg_bet,
                MAX(profit) as max_win,
                MIN(profit) as max_loss
               FROM games 
               WHERE user_id=? AND game='duel'""",
            (user_id,)
        )
        
        if result and result[0]:
            row = result[0]
            total = row[0] or 0
            wins = row[1] or 0
            losses = row[2] or 0
            win_rate = (wins / total * 100) if total > 0 else 0
            
            return {
                "total_duels": total,
                "wins": wins,
                "losses": losses,
                "win_rate": win_rate,
                "total_profit": row[3] or 0,
                "avg_bet": row[4] or 0,
                "max_win": row[5] or 0,
                "max_loss": row[6] or 0
            }
        
        return {
            "total_duels": 0,
            "wins": 0,
            "losses": 0,
            "win_rate": 0,
            "total_profit": 0,
            "avg_bet": 0,
            "max_win": 0,
            "max_loss": 0
        }
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики дуэлей: {e}")
        return {}

def get_duel_leaderboard(limit: int = 10) -> List[Dict[str, Any]]:
    """
    Возвращает лидерборд по дуэлям.
    
    Args:
        limit: Количество записей
    
    Returns:
        List[Dict[str, Any]]: Лидерборд
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            """SELECT 
                user_id,
                COUNT(*) as total,
                SUM(CASE WHEN win=1 THEN 1 ELSE 0 END) as wins,
                SUM(profit) as profit
               FROM games 
               WHERE game='duel'
               GROUP BY user_id
               ORDER BY wins DESC, profit DESC
               LIMIT ?""",
            (limit,)
        )
        
        leaderboard = []
        if result:
            for row in result:
                leaderboard.append({
                    "user_id": row[0],
                    "total": row[1],
                    "wins": row[2],
                    "profit": row[3] or 0,
                    "win_rate": (row[2] / row[1] * 100) if row[1] > 0 else 0
                })
        
        return leaderboard
        
    except Exception as e:
        logger.error(f"❌ Ошибка получения лидерборда дуэлей: {e}")
        return []

# ============================================================================
# ДОСТИЖЕНИЯ ЗА ИГРЫ
# ============================================================================

def check_game_achievements(user_id: int, game_result: GameResult) -> List[str]:
    """
    Проверяет достижения, связанные с играми.
    
    Args:
        user_id: ID пользователя
        game_result: Результат игры
    
    Returns:
        List[str]: Список полученных достижений
    """
    earned = []
    
    # Получаем статистику
    stats = get_game_stats(user_id)
    duel_stats = get_duel_stats(user_id) if game_result.game == "duel" else None
    
    # Первая игра
    if stats.get("total_played") == 1:
        if award_achievement(user_id, "first_game"):
            earned.append("first_game")
    
    # 10 игр
    if stats.get("total_played") == 10:
        if award_achievement(user_id, "game_master"):
            earned.append("game_master")
    
    # 100 игр
    if stats.get("total_played") == 100:
        if award_achievement(user_id, "game_legend"):
            earned.append("game_legend")
    
    # Первая победа
    if game_result.won and stats.get("total_wins") == 1:
        if award_achievement(user_id, "first_win"):
            earned.append("first_win")
    
    # 10 побед
    if stats.get("total_wins") == 10:
        if award_achievement(user_id, "win_master"):
            earned.append("win_master")
    
    # 50 побед
    if stats.get("total_wins") == 50:
        if award_achievement(user_id, "win_legend"):
            earned.append("win_legend")
    
    # Дуэли
    if game_result.game == "duel":
        if duel_stats and duel_stats["total_duels"] == 1 and game_result.won:
            if award_achievement(user_id, "duel_winner"):
                earned.append("duel_winner")
        
        if duel_stats and duel_stats["wins"] == 10:
            if award_achievement(user_id, "duel_master"):
                earned.append("duel_master")
    
    return earned

# ============================================================================
# ПЛАНОВАЯ ОЧИСТКА ДУЭЛЕЙ
# ============================================================================

def scheduled_duel_cleanup() -> None:
    """Плановая очистка истёкших дуэлей."""
    while True:
        if _shutdown_event.wait(timeout=60):
            break  # Каждую минуту
        
        try:
            count = duel_manager.cleanup_expired()
            if count > 0:
                logger.debug(f"🧹 Очищено {count} истёкших дуэлей")
            count2 = duel_manager.cleanup_round_timeouts()
            if count2 > 0:
                logger.debug(f"🧹 Обработано {count2} дуэлей по таймауту раунда")
        except Exception as e:
            logger.error(f"❌ Ошибка в очистке дуэлей: {e}")
        try:
            from rock_paper_scissors import run_cpc_cleanup
            run_cpc_cleanup()
        except Exception as e:
            logger.debug("Очистка CPC: %s", e)

# Запускаем планировщик
duel_cleanup_thread = threading.Thread(
    target=scheduled_duel_cleanup,
    daemon=True,
    name="duel_cleanup",
)
duel_cleanup_thread.start()
logger.info("✅ Планировщик очистки дуэлей запущен")

# ============================================================================
# СТАТИСТИКА ИГР
# ============================================================================

def _get_games_stats_from_games_table() -> Dict[str, Any]:
    """Статистика из таблицы games."""
    result = execute_query(
        ECONOMY_DB,
        """SELECT 
            COUNT(*) as total_games,
            SUM(CASE WHEN win=1 THEN 1 ELSE 0 END) as total_wins,
            SUM(profit) as total_profit,
            AVG(bet) as avg_bet,
            COUNT(DISTINCT user_id) as unique_players
           FROM games"""
    )
    if not result or not result[0]:
        return {"total_games": 0}
    row = result[0]
    total_games = row[0] or 0
    total_wins = row[1] or 0
    total_profit = row[2] or 0
    avg_bet = row[3] or 0
    unique_players = row[4] or 0
    games_by_type = execute_query(
        ECONOMY_DB,
        """SELECT game, COUNT(*), SUM(win), SUM(profit)
           FROM games 
           GROUP BY game"""
    )
    games_stats = {}
    if games_by_type:
        for g in games_by_type:
            games_stats[g[0]] = {"total": g[1], "wins": g[2] or 0, "profit": g[3] or 0}
    if total_games > 0:
        winrate = (total_wins / total_games * 100) if total_games else 0.0
        return {
            "total_games": total_games,
            "total_wins": total_wins,
            "total_profit": total_profit,
            "avg_bet": avg_bet,
            "unique_players": unique_players,
            "avg_winrate": winrate,
            "by_game": games_stats
        }
    return {"total_games": 0}


def _get_games_stats_from_game_stats() -> Dict[str, Any]:
    """Статистика из таблицы game_stats (агрегаты)."""
    gs = execute_query(
        ECONOMY_DB,
        """SELECT 
            COALESCE(SUM(games_played), 0),
            COALESCE(SUM(games_won), 0),
            COALESCE(SUM(total_won - total_bet), 0),
            COUNT(DISTINCT user_id)
           FROM game_stats"""
    )
    if not gs or not gs[0]:
        return {"total_games": 0, "total_wins": 0, "total_profit": 0, "avg_bet": 0, "unique_players": 0, "avg_winrate": 0, "by_game": {}}
    total_games = int(gs[0][0] or 0)
    total_wins = int(gs[0][1] or 0)
    total_profit = int(gs[0][2] or 0)
    unique_players = int(gs[0][3] or 0)
    by_type = execute_query(
        ECONOMY_DB,
        """SELECT game, SUM(games_played), SUM(games_won), SUM(total_won - total_bet)
           FROM game_stats GROUP BY game"""
    )
    games_stats = {}
    if by_type:
        for g in by_type:
            games_stats[g[0]] = {"total": int(g[1] or 0), "wins": int(g[2] or 0), "profit": int(g[3] or 0)}
    winrate = (total_wins / total_games * 100) if total_games else 0
    return {
        "total_games": total_games,
        "total_wins": total_wins,
        "total_profit": total_profit,
        "avg_bet": 0,
        "unique_players": unique_players,
        "avg_winrate": winrate,
        "by_game": games_stats
    }


def get_games_stats() -> Dict[str, Any]:
    """
    Возвращает общую статистику игр.
    Сначала пробует таблицу games (детальные записи), при нулях — из game_stats (агрегаты по пользователям).
    """
    try:
        stats = _get_games_stats_from_games_table()
        if stats.get("total_games", 0) > 0:
            return stats
        return _get_games_stats_from_game_stats()
    except Exception as e:
        logger.error(f"❌ Ошибка получения статистики игр: {e}")
        return {"total_games": 0, "total_wins": 0, "total_profit": 0, "avg_bet": 0, "unique_players": 0, "avg_winrate": 0, "by_game": {}}

