# -*- coding: utf-8 -*-

"""
Telegram Bot для управления чатом
Часть 6: Команды для пользователей
Версия: 3.0 (Полная)

Эта часть содержит:
- Команды экономики (/balance, /daily, /top, /send)
- Игровые команды (/roulette, /dice)
- Команды дуэлей (/duel, /duel_stats)
- Команды магазина (/shop, /inventory, /use)
- Команды достижений (/achievements)
- Обработчики всех пользовательских команд
"""

# ============================================================================
# ПОДКЛЮЧЕНИЕ К ЧАСТЯМ 1-5
# ============================================================================

# Эта часть должна быть добавлена после Частей 1, 2, 3, 4 и 5
# Все базовые функции уже есть в предыдущих частях

# ============================================================================
# ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ДЛЯ КОМАНД
# ============================================================================

def format_number(num: int) -> str:
    """
    Форматирует число с разделителями.
    
    Args:
        num: Число
    
    Returns:
        str: Отформатированное число
    """
    return f"{num:,}".replace(",", " ")


def format_success(text: str) -> str:
    """Форматирует успешное сообщение."""
    return f"✅ **{text}**"


def format_error(text: str) -> str:
    """Форматирует сообщение об ошибке."""
    return f"❌ {text}"


def format_warning(text: str) -> str:
    """Форматирует предупреждение."""
    return f"⚠️ {text}"


def format_info(text: str) -> str:
    """Форматирует информационное сообщение."""
    return f"ℹ️ {text}"


def format_balance_emoji(amount: int, sign: str = None) -> str:
    """Форматирует баланс с эмодзи по уровню (для красоты в интерфейсе). sign — символ валюты (COINS_SIGN)."""
    coin_sign = sign or COM_EMOJI
    num_str = format_number(amount)
    if amount >= 10000:
        return f"💎 {num_str} {coin_sign}"
    if amount >= 5000:
        return f"💰 {num_str} {coin_sign}"
    if amount >= 1000:
        return f"🪙 {num_str} {coin_sign}"
    return f"👛 {num_str} {coin_sign}"


def get_user_mention(user_id: int, name: str = None, lang: str = None) -> str:
    """
    Возвращает упоминание пользователя (ник с гиперссылкой tg://user?id=...).
    Если name не передан — подставляется локализованное «Пользователь»/«User» по lang.
    Имена экранируются: при глобальном parse_mode=Markdown символы _*[] в нике ломали разметку
    и приводили к «Временная ошибка» из safe_handler.
    """
    if name:
        safe = _escape_markdown_caption(str(name).strip())
        return f"[{safe}](tg://user?id={user_id})"
    _lang = lang or "ru"
    safe_fb = _escape_markdown_caption(t(_lang, "user_default_name"))
    return f"[{safe_fb}](tg://user?id={user_id})"


def get_user_display_name(chat_id: int, user_id: int, lang: str = None) -> str:
    """Получить отображаемое имя пользователя в чате (first_name) для подстановки в упоминание. При ошибке — локализованное «Пользователь»/«User»."""
    _fallback = t(lang or "ru", "user_default_name")
    try:
        member = bot.get_chat_member(chat_id, user_id)
        if member and getattr(member, "user", None):
            return (member.user.first_name or "").strip() or _fallback
    except Exception:
        pass
    return _fallback

def create_progress_bar(current: int, total: int, length: int = 10) -> str:
    """
    Создаёт прогресс-бар.
    
    Args:
        current: Текущее значение
        total: Максимальное значение
        length: Длина бара
    
    Returns:
        str: Прогресс-бар
    """
    filled = int((current / total) * length) if total > 0 else 0
    filled = min(filled, length)
    empty = length - filled
    
    return "█" * filled + "░" * empty

