def _user_exists_in_economy(user_id: int) -> bool:
    """Проверяет, есть ли пользователь в таблице users (экономика)."""
    try:
        result = execute_query(
            ECONOMY_DB,
            "SELECT user_id FROM users WHERE user_id = ? LIMIT 1",
            (user_id,),
        )
        return result is not None and len(result) > 0
    except Exception:
        return False


def user_has_groups(user_id: int) -> bool:
    """Проверяет, есть ли у пользователя доступные группы (добавленные им или по роли в group_roles)."""
    return len(get_user_manageable_groups(user_id)) > 0


def user_is_donator(user_id: int) -> bool:
    """Проверяет, донатил ли пользователь (total_spent > 0 или есть в рейтинге донатеров)."""
    try:
        row = execute_query(
            ECONOMY_DB,
            "SELECT total_spent FROM users WHERE user_id = ? LIMIT 1",
            (user_id,),
        )
        if row and (row[0][0] or 0) > 0:
            return True
        # Проверка по group_top_donators (если есть такая таблица в ECONOMY_DB)
        donated = execute_query(
            ECONOMY_DB,
            "SELECT 1 FROM group_top_donators WHERE user_id = ? LIMIT 1",
            (user_id,),
        )
        return donated is not None and len(donated) > 0
    except Exception:
        return False


def get_start_add_bot_url() -> str:
    """URL для добавления бота в группу."""
    try:
        username = (bot.get_me()).username
        return f"https://t.me/{username or 'YourBot'}?startgroup=new" if username else "https://t.me/YourBot?startgroup=new"
    except Exception:
        return "https://t.me/YourBot?startgroup=new"


def _inline_keyboard_http_url(url: Optional[str]) -> str:
    """
    InlineKeyboardButton с пустым или невалидным url даёт 400:
    «Text buttons are unallowed in the inline keyboard».
    Нужен полный http(s) URL. Частый случай в настройках: «t.me/...» без схемы — API отклоняет.
    """
    u = (url or "").strip()
    if not u:
        try:
            return get_start_add_bot_url()
        except Exception:
            return "https://t.me/telegram"
    if u.startswith("http://") or u.startswith("https://"):
        return u
    # Без https:// Telegram считает кнопку «текстовой» и возвращает 400
    if re.match(r"^(t\.me|telegram\.me)/", u, re.I):
        return "https://" + u
    try:
        return get_start_add_bot_url()
    except Exception:
        return "https://t.me/telegram"


def get_greeting(user_id: int, lang: str, name: Optional[str] = None) -> str:
    """Персонализированное приветствие по времени суток + баланс и краткая статистика."""
    hour = datetime.now().hour
    if 5 <= hour < 12:
        time_greeting = "Доброе утро" if lang == "ru" else "Good morning"
    elif 12 <= hour < 18:
        time_greeting = "Добрый день" if lang == "ru" else "Good afternoon"
    elif 18 <= hour < 23:
        time_greeting = "Добрый вечер" if lang == "ru" else "Good evening"
    else:
        time_greeting = "Доброй ночи" if lang == "ru" else "Good night"

    # Оба вызова get_greeting отправляют результат с parse_mode="Markdown",
    # а имя приходит из Telegram — символ * или _ в нём ломал приветствие.
    display_name = _escape_markdown_caption((name or "друг") if lang == "ru" else (name or "friend"))
    balance = get_balance(user_id)
    stats = get_user_stats(user_id) or {}
    games_played = stats.get("games_played", 0)
    role_emoji = "👤"
    if user_id in DEVELOPER_IDS:
        role_emoji = "💻"
    elif user_has_groups(user_id):
        role_emoji = "👑"

    if lang == "ru":
        return (
            f"{time_greeting}, {role_emoji} **{display_name}**!\n\n"
            f"💰 Твой баланс: **{format_number(balance)}** {COM_EMOJI}\n"
            f"📊 Игр сыграно: **{games_played}**\n"
        )
    return (
        f"{time_greeting}, {role_emoji} **{display_name}**!\n\n"
        f"💰 Your balance: **{format_number(balance)}** {COM_EMOJI}\n"
        f"📊 Games played: **{games_played}**\n"
    )


