# ============================================================================
# КОМАНДА /START (ВСТУПЛЕНИЕ В ЧАТ)
# ============================================================================

@bot.message_handler(commands=['start', 'kom_start'])
@safe_handler
def cmd_start(message: Message):
    """
    Обработчик команды /start.
    Для разработчика: панель разработчика. Для пользователя: проверяет, в чате ли, выдаёт ссылку.
    /start dev — выход из режима тестирования (только разработчик).
    /start check_CODE — активация чека.
    """
    global DEVELOPER_TESTING_MODE
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id
    chat_id = message.chat.id

    # Активация чека по ссылке /start check_CODE
    args_start = (message.text or "").strip().split()
    if len(args_start) > 1 and args_start[1].startswith("check_"):
        code = args_start[1][6:].strip()
        if code:
            _activate_check(message, code)
            return

    # Ссылка на страницу команд: t.me/bot?start=commands
    if len(args_start) > 1 and args_start[1].lower() == "commands":
        try_delete_message(chat_id, message.message_id)
        lang = get_user_language(user_id)
        telegraph_url = get_telegraph_commands_url(lang)
        if telegraph_url:
            markup = InlineKeyboardMarkup()
            markup.add(InlineKeyboardButton("📋 " + t(lang, "menu_commands"), url=telegraph_url))
            markup.add(InlineKeyboardButton(t(lang, "main_menu_back"), callback_data="main_menu"))
            text = t(lang, "commands_page_intro")
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        else:
            # Ссылка на гайд на сайте не собрана — показываем обычную помощь
            fake = _FakeMessage(chat_id, message.from_user, message.message_id, "/help")
            cmd_help(fake)
        return

    # В личке: отложенные уведомления о штрафах (если бот не был запущен в момент штрафа)
    if message.chat.type == "private":
        send_pending_fine_notifications(user_id)

    # Первый запуск в личке: спрашиваем язык только у действительно новых пользователей (нет в user_settings и нет в users).
    # Если пользователь уже есть в БД (например, заходил в группе или после замены скрипта БД та же) — не спрашиваем, сохраняем текущий язык в user_settings.
    if message.chat.type == "private":
        try:
            settings_row = execute_query(
                USERS_DB,
                "SELECT language FROM user_settings WHERE user_id = ? LIMIT 1",
                (user_id,),
            )
            has_settings = settings_row is not None and len(settings_row) > 0
            if not has_settings:
                users_row = execute_query(
                    USERS_DB,
                    "SELECT user_id FROM users WHERE user_id = ? LIMIT 1",
                    (user_id,),
                )
                has_user = users_row is not None and len(users_row) > 0
                if has_user:
                    # Уже есть в БД (группа или повторный /start после замены скрипта) — фиксируем язык по умолчанию и не спрашиваем
                    lang_default = get_user_language(user_id)
                    set_user_language(user_id, lang_default)
                else:
                    # Совсем новый пользователь — показываем выбор языка
                    try_delete_message(chat_id, message.message_id)
                    lang = get_user_language(user_id)
                    markup = InlineKeyboardMarkup(row_width=2)
                    markup.add(
                        InlineKeyboardButton(t("ru", "lang_ru"), callback_data="lang_set_ru"),
                        InlineKeyboardButton(t("en", "lang_en"), callback_data="lang_set_en"),
                    )
                    bot.send_message(
                        chat_id,
                        t(lang, "lang_select"),
                        reply_markup=markup,
                        parse_mode="Markdown",
                    )
                    return
        except Exception:
            pass

    # Переход по ссылке настройки группы (group_setup_<id>), но пользователь ещё не подписан — сохраняем id и показываем экран подписки
    if message.chat.type == "private" and user_id not in DEVELOPER_IDS and not is_user_in_chat(user_id) and len(args_start) > 1:
        arg1 = (args_start[1] or "").strip().lower()
        if arg1.startswith("group_setup_"):
            try:
                gid_str = arg1.split("_", 2)[-1]
                pending_gid = int(gid_str)
                save_temp_data(user_id, "pending_group_setup_chat_id", pending_gid)
            except (ValueError, IndexError):
                pending_gid = None
            if pending_gid is not None:
                lang = get_user_language(user_id)
                markup = InlineKeyboardMarkup()
                markup.add(InlineKeyboardButton(t(lang, "return_to_chat"), url=_inline_keyboard_http_url(INVITE_LINK)))
                markup.add(InlineKeyboardButton(t(lang, "check_sub_btn"), callback_data="check_sub"))
                try_delete_message(chat_id, message.message_id)
                bot.send_message(chat_id, t(lang, "access_limited_left"), reply_markup=markup)
                return

    try_delete_message(chat_id, message.message_id)

    # Сбрасываем незавершённые шаги (заявка на рекламу, поддержка и т.д.), чтобы старые «напиши ниже» не путали
    clear_temp_data(user_id)
    # Текущий язык пользователя для всех дальнейших текстов
    lang = get_user_language(user_id)

    # В личке: переход по ссылке start=group_setup_<id> или start=group_<id> — панель управления этой группой
    if message.chat.type == "private" and len(args_start) > 1:
        arg1 = (args_start[1] or "").strip()
        if arg1.lower().startswith("group_setup"):
            delete_bot_added_setup_messages_for_user(user_id)
            if arg1.lower().startswith("group_setup_"):
                try:
                    gid = int(arg1.strip().lower().split("_", 2)[-1])
                except (ValueError, IndexError):
                    gid = None
                if gid is not None and _admin_group_can_manage(user_id, gid):
                    _send_group_management_panel(chat_id, user_id, gid)
                    return
            send_mygroups_panel(chat_id, user_id, lang)
            return
        if arg1.startswith("group_") and not arg1.lower().startswith("group_setup"):
            try:
                gid = int(arg1[6:].strip())
            except ValueError:
                gid = None
            if gid is not None and _admin_group_can_manage(user_id, gid):
                _send_group_management_panel(chat_id, user_id, gid)
                return

    # Проверяем, новый ли пользователь (ещё нет в экономике) — до регистрации
    is_new_user = not _user_exists_in_economy(user_id)

    # Фиксируем пользователя в БД, чтобы потом работал /send @username даже вне группы.
    register_user(user_id)
    update_user_info(user_id, message.from_user)
    # Сохраняем дату первого запуска бота (личка) в user_first_join — после перезагрузки не сбрасывается.
    if message.chat.type == "private":
        ensure_user_first_join_recorded(user_id)

    # Уведомление админу «Новый участник» только при первом запуске бота (личка), с полями: имя, юзернейм, ID, язык Telegram, язык бота, премиум, город.
    if message.chat.type == "private" and ADMIN_CHAT_ID and not is_new_member_notified(user_id):
        try:
            u = message.from_user
            name = (getattr(u, "first_name", None) or "").strip() or (getattr(u, "last_name", None) or "").strip() or "—"
            username = f"@{u.username}" if getattr(u, "username", None) else "—"
            lang_tg = (getattr(u, "language_code", None) or "—").strip() or "—"
            lang_bot = get_user_language(user_id) or "—"
            premium = "✅" if getattr(u, "is_premium", False) else "❌"
            city = (get_user_city(user_id) or "").strip() or "—"
            text = (
                f"👤 **Новый участник (запустил бота)**\n\n"
                f"Имя: {name}\n"
                f"Юзернейм: {username}\n"
                f"ID: `{user_id}`\n"
                f"Язык Telegram: {lang_tg}\n"
                f"Язык бота: {lang_bot}\n"
                f"Telegram Premium: {premium}\n"
                f"Город: {city}"
            )
            bot.send_message(ADMIN_CHAT_ID, text, parse_mode="Markdown")
            set_new_member_notified(user_id)
            _user_first_join_set_notified(user_id)  # сохраняем first_joined и notified в user_first_join
            _mark_new_member_notified_in_db(user_id)
        except Exception as e:
            logger.debug("Уведомление админу о новом участнике (старт бота): %s", e)

    # Реферальная ссылка /start ref_REFERRER_ID — сохраняем пригласившего; он получает % с покупок реферала
    args = (message.text or "").strip().split()
    ref_id = ""
    referrer_id = None
    if len(args) > 1 and args[1].startswith("ref_"):
        ref_id = args[1][4:].strip()
        if ref_id and ref_id.isdigit():
            try:
                referrer_id = int(ref_id)
            except ValueError:
                referrer_id = None
        if is_new_user and referrer_id and referrer_id != user_id and _user_exists_in_economy(referrer_id):
            if set_referrer(user_id, referrer_id):
                ref_lang = get_user_language(referrer_id)
                if REFERRAL_COMMISSION_PERCENT > 0:
                    ref_msg = (
                        f"По вашей ссылке зарегистрировался новый пользователь. Вы будете получать {REFERRAL_COMMISSION_PERCENT}% с его покупок монет."
                        if ref_lang == "ru"
                        else f"A new user signed up via your link. You'll get {REFERRAL_COMMISSION_PERCENT}% of their coin purchases."
                    )
                else:
                    ref_msg = "По вашей ссылке зарегистрировался новый пользователь. Реферальные отчисления выключены в настройках." if ref_lang == "ru" else "A new user signed up via your link. Referral commission is disabled in settings."
                try:
                    bot.send_message(referrer_id, "✅ " + ref_msg)
                except Exception:
                    pass

    # Выход из режима тестирования по /start dev (только разработчик, в личке)
    if message.chat.type == "private" and user_id in DEVELOPER_IDS and message.text:
        cmd_text = message.text.strip().lower()
        if cmd_text in ("/start dev", "/start dev_exit") or cmd_text.startswith("/start dev "):
            DEVELOPER_TESTING_MODE = None
            bot.send_message(chat_id, t(lang, "test_mode_exit_confirm"))
            send_owner_quick_menu(chat_id)
            try_show_admin_panel(chat_id, user_id)
            return

    # Новый пользователь в личке — развёрнутое приветствие и кнопки «Тур», «Возможности», «Бонус», «Добавить в группу»
    if message.chat.type == "private" and is_new_user:
        welcome_text = get_welcome_text_new_user(lang)
        if len(args) > 1 and args[1].startswith("ref_") and ref_id:
            welcome_text += "\n\n👥 " + t(lang, "welcome_referred")
        new_markup = InlineKeyboardMarkup(row_width=1)
        new_markup.add(InlineKeyboardButton("🚀 " + t(lang, "start_tour_btn"), callback_data="start_tour"))
        new_markup.add(InlineKeyboardButton("❓ " + t(lang, "features_btn"), callback_data="features"))
        new_markup.add(InlineKeyboardButton("🎁 " + t(lang, "daily_bonus_btn"), callback_data="group_welcome_daily"))
        new_markup.add(InlineKeyboardButton("👥 " + t(lang, "add_bot_to_group_btn"), url=get_start_add_bot_url()))
        bot.send_message(chat_id, welcome_text, parse_mode="Markdown", reply_markup=new_markup)
        return

    send_start_panel(chat_id, user_id, lang, message.chat.type, first_name=message.from_user.first_name if message.from_user else None)


def send_start_panel(chat_id: int, user_id: int, lang: str, chat_type: str = "private", first_name: Optional[str] = None) -> None:
    """Показывает стартовую панель (как после /start): админка только в личке, в группе — меню группы."""
    # Панель разработчика/админка только в личке; в группе /start не открывает админку
    if chat_type == "private" and is_admin(user_id) and get_developer_testing_mode() != "user":
        send_owner_quick_menu(chat_id)
        try_show_admin_panel(chat_id, user_id)
        return

    # В группе: админам — ссылка на управление; обычным пользователям — приветствие и список команд
    if chat_type in ("group", "supergroup"):
        ensure_user_group_joined(user_id, datetime.now(), source="observed_private_check")
        group_lang = get_group_language(chat_id) or lang
        try:
            bot_username = (bot.get_me()).username or "YourBot"
        except Exception:
            bot_username = "YourBot"
        is_group_admin = has_group_admin_rights(user_id, chat_id)
        # Удаляем предыдущее сообщение бота, если оно было (сообщение команды /start передаётся только из хэндлера cmd_start)
        with _last_start_lock:
            last_msg_id = _last_start_messages.get(chat_id)
            if last_msg_id:
                try:
                    bot.delete_message(chat_id, last_msg_id)
                except Exception:
                    pass
        if is_group_admin:
            deep_link = f"https://t.me/{bot_username}?start=group_setup_{chat_id}"
            if group_lang == "en":
                text = "👋 To configure this group, open the bot in private messages — the management panel for this group will open there."
                btn_text = "🚀 Open in DM"
            else:
                text = "👋 Для настройки группы перейди в личные сообщения с ботом — там откроется панель управления этой группой."
                btn_text = "🚀 Перейти в ЛС"
            markup = InlineKeyboardMarkup()
            markup.add(InlineKeyboardButton(btn_text, url=deep_link))
            sent_msg = bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        else:
            _lang = group_lang or "ru"
            text = (
                t(_lang, "group_welcome_hi") + "\n\n"
                + t(_lang, "group_welcome_quick") + "\n\n"
                + t(_lang, "group_welcome_full_list")
            )
            sent_msg = bot.send_message(chat_id, text, parse_mode="Markdown")
        with _last_start_lock:
            _last_start_messages[chat_id] = sent_msg.message_id
        return

    # Личка: пользователь уже в основной группе — персонализированное приветствие + виджет баланса + главное меню
    if is_user_in_chat(user_id):
        ensure_user_group_joined(user_id, datetime.now(), source="observed_private_check")
        name = first_name or (lang == "ru" and "друг" or "friend")
        text = get_greeting(user_id, lang, name=name)
        text += "\n" + get_balance_widget(user_id, lang)
        text += "\n\n" + t(lang, "choose_action")
        keyboard = build_main_menu_keyboard(user_id, lang)
        bot.send_message(
            chat_id,
            text,
            parse_mode="Markdown",
            disable_web_page_preview=True,
            reply_markup=keyboard,
        )
        return

    # Пользователь не в группе — обязательная подписка: экран «вступи в группу» + кнопка «Я подписался»
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "must_subscribe_first_btn"), url=_inline_keyboard_http_url(INVITE_LINK)))
    markup.add(InlineKeyboardButton(t(lang, "check_sub_btn"), callback_data="check_sub"))
    full_text = t(lang, "must_subscribe_first") + "\n\n" + t(lang, "check_sub_hint")
    bot.send_message(
        chat_id,
        full_text,
        parse_mode="Markdown",
        disable_web_page_preview=True,
        reply_markup=markup,
    )


def create_owner_quick_reply_keyboard() -> ReplyKeyboardMarkup:
    """Клавиатура в поле ввода для разработчика (личный чат). Одна кнопка — панель разработчика, вторая — Ком."""
    kb = ReplyKeyboardMarkup(resize_keyboard=True, one_time_keyboard=False)
    kb.row(KeyboardButton("👑 Панель разработчика"))
    kb.row(KeyboardButton("🤖 Ком"))
    return kb


def create_group_admin_reply_keyboard() -> ReplyKeyboardMarkup:
    """Клавиатура для режима «как админ группы»: Панель администратора + Ком."""
    kb = ReplyKeyboardMarkup(resize_keyboard=True, one_time_keyboard=False)
    kb.row(KeyboardButton("🛡️ Панель администратора"))
    kb.row(KeyboardButton("🤖 Ком"))
    return kb


def get_owner_reply_keyboard():
    """Возвращает клавиатуру для владельца в зависимости от режима тестирования. Для режима «пользователь» — удаление клавиатуры."""
    mode = get_developer_testing_mode()
    if mode == "user":
        return ReplyKeyboardRemove(selective=False)
    if mode == "group_admin":
        return create_group_admin_reply_keyboard()
    return create_owner_quick_reply_keyboard()


def ensure_bottom_panel_visible(chat_id: int, user_id: int) -> None:
    """
    В личке для владельца/админа отправляет короткое сообщение с reply-клавиатурой (Панель разработчика / Ком),
    чтобы панель оставалась внизу экрана. Предыдущее такое сообщение удаляется.
    """
    if chat_id <= 0 or user_id not in DEVELOPER_IDS:
        return
    slot = "bottom_panel"
    delete_last_slot_message(chat_id, slot)
    try:
        msg = bot.send_message(
            chat_id,
            "👇",
            reply_markup=get_owner_reply_keyboard(),
        )
        remember_slot_message(chat_id, slot, msg.message_id, ttl=86400)
    except Exception as e:
        logger.debug("ensure_bottom_panel_visible: %s", e)


def try_delete_message(chat_id: int, message_id: int) -> None:
    """Пытается удалить сообщение (команду пользователя и т.д.). Ошибки игнорируются (нет прав, личка и т.д.)."""
    try:
        bot.delete_message(chat_id, message_id)
    except Exception:
        pass


def delete_last_slot_message(chat_id: int, slot: str) -> None:
    """Удаляет предыдущее сообщение бота для указанного слота."""
    key = f"slot_msg_{chat_id}_{slot}"
    prev_msg_id = cache_get(key)
    if not prev_msg_id:
        return
    try:
        bot.delete_message(chat_id, int(prev_msg_id))
    except Exception:
        pass


def remember_slot_message(chat_id: int, slot: str, message_id: int, ttl: int = 86400) -> None:
    """Запоминает последнее сообщение бота для указанного слота."""
    key = f"slot_msg_{chat_id}_{slot}"
    cache_set(key, int(message_id), ttl=ttl)


def send_owner_quick_menu(chat_id: int) -> None:
    """Отправляет владельцу закреплённые кнопки быстрого доступа."""
    cache_key = f"owner_quick_menu_msg_{chat_id}"
    prev_msg_id = cache_get(cache_key)
    if prev_msg_id:
        try:
            bot.delete_message(chat_id, int(prev_msg_id))
        except Exception:
            pass

    quick_text = "⚡ Быстрые кнопки: Панель разработчика, Ком."
    if chat_id in DEVELOPER_IDS and get_developer_testing_mode() == "group_admin":
        quick_text = "⚡ Быстрые кнопки: Панель администратора, Ком."
    sent = bot.send_message(
        chat_id,
        quick_text,
        reply_markup=get_owner_reply_keyboard(),
    )
    cache_set(cache_key, sent.message_id, ttl=7 * 24 * 3600)


def send_admin_panel_message(chat_id: int, user_id: Optional[int] = None) -> None:
    """Отправляет главное сообщение панели разработчика или панели администратора (в зависимости от режима тестирования)."""
    cache_key = f"owner_admin_panel_msg_{chat_id}"
    prev_msg_id = cache_get(cache_key)
    if prev_msg_id:
        try:
            bot.delete_message(chat_id, int(prev_msg_id))
        except Exception:
            pass

    lang = get_user_language(user_id or chat_id)
    is_group_admin_mode = chat_id in DEVELOPER_IDS and get_developer_testing_mode() == "group_admin"
    if is_group_admin_mode:
        markup = create_group_admin_panel_keyboard(lang)
        title = t(lang, "admin_panel_admin_title") + "\n\n"
        body = t(lang, "admin_panel_admin_desc")
    else:
        markup = create_admin_keyboard(lang)
        title = t(lang, "admin_panel_title") + "\n\n"
        body = t(lang, "admin_panel_desc")
    sent = bot.send_message(
        chat_id,
        title + body,
        reply_markup=markup,
        parse_mode="Markdown",
    )
    cache_set(cache_key, sent.message_id, ttl=7 * 24 * 3600)


# Тексты кнопок быстрого доступа: при истёкшей сессии (поддержка, заявка, админ-ввод) не слать «Сессия истекла», а передать в этот обработчик
OWNER_QUICK_BUTTON_TEXTS = {
    "👑 панель разработчика",
    "панель разработчика",
    "🛡️ панель администратора",
    "панель администратора",
    "админ-панель",
    "админ панель",
    "панель",
    "управление",
    "admin",
    "admin panel",
    "dev",
    "developer",
    "разработчик",
    "выйти из теста",
    "exit test",
    "🤖 ком",
    "ком",
    "🤖 ии",
    "ии",
    "ai",
    "🤖 ai",
}


@bot.message_handler(
    func=lambda m: (
        m.chat.type == "private"
        and m.from_user
        and m.from_user.id in DEVELOPER_IDS
        and m.content_type == "text"
        and (m.text or "").strip().lower() in OWNER_QUICK_BUTTON_TEXTS
    )
)
@safe_handler
def owner_quick_buttons_handler(message: Message):
    """Обработчик кнопок быстрого доступа разработчика в личке (работает даже в режиме теста «как пользователь»)."""
    global DEVELOPER_TESTING_MODE
    try:
        bot.delete_message(message.chat.id, message.message_id)
    except Exception:
        pass

    text = (message.text or "").strip().lower()
    if "ком" in text or "ии" in text or "ai" in text:
        cmd_ai(message)
        return
    if "выйти из теста" in text or "exit test" in text:
        DEVELOPER_TESTING_MODE = None
        _lang = get_user_language(message.from_user.id)
        bot.send_message(message.chat.id, t(_lang, "test_mode_exit_confirm"))
    try_show_admin_panel(message.chat.id, message.from_user.id)

@bot.callback_query_handler(func=lambda call: call.data == "inv_get_link")
@safe_handler
def callback_get_link(call: CallbackQuery):
    """
    Обработчик нажатия кнопки получения ссылки. Персональная ссылка только для подписчиков группы.
    """
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    lang = get_user_language(user_id)

    # Удаляем сообщение с кнопкой
    try:
        bot.delete_message(chat_id, call.message.message_id)
    except Exception:
        pass

    # Обязательная подписка: без вступления в группу персональную ссылку не выдаём
    if user_id not in DEVELOPER_IDS and not is_user_in_chat(user_id):
        bot.answer_callback_query(call.id)
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "must_subscribe_first_btn"), url=_inline_keyboard_http_url(INVITE_LINK)))
        bot.send_message(
            chat_id,
            t(lang, "must_subscribe_first"),
            parse_mode="Markdown",
            disable_web_page_preview=True,
            reply_markup=markup,
        )
        return

    # Проверяем, не в чате ли уже
    if is_user_in_chat(user_id):
        bot.send_message(
            chat_id,
            "😊 <b>Ты уже в чате!</b>\n\n"
            f"Переходи по ссылке:\n{html.escape(INVITE_LINK)}",
            parse_mode="HTML",
            disable_web_page_preview=True
        )
        bot.answer_callback_query(call.id)
        return

    # Проверяем, есть ли уже активная ссылка
    existing = active_links.get(user_id)
    if existing is not None:
        old_link = existing["link"]
        expires = existing["expires"]
        time_left = format_expiry_time(expires)
        
        bot.send_message(
            chat_id,
            "✅ <b>У тебя уже есть активная ссылка!</b>\n\n"
            f"🔗 {html.escape(old_link)}\n\n"
            f"⏳ <b>Истекает через:</b> <code>{html.escape(time_left)}</code>",
            parse_mode="HTML",
            disable_web_page_preview=True
        )
        bot.answer_callback_query(call.id)
        return
    
    # Отправляем сообщение о создании
    wait_msg = bot.send_message(
        chat_id,
        "⏳ <b>Создаю твою персональную ссылку...</b>",
        parse_mode="HTML"
    )
    
    try:
        # Создаём ссылку (всегда для CHAT_ID — основной чат)
        expires = int(time.time()) + (INVITE_LINK_EXPIRY or 3600)
        link = bot.create_chat_invite_link(
            chat_id=CHAT_ID,
            member_limit=max(1, INVITE_LINK_LIMIT or 1),
            expire_date=expires
        )

        active_links.set(user_id, {
            "link": link.invite_link,
            "expires": expires,
            "created": time.time(),
        })

        try:
            bot.delete_message(chat_id, wait_msg.message_id)
        except Exception:
            pass

        time_left = format_expiry_time(expires)
        bot.send_message(
            chat_id,
            "🎉 <b>ТВОЯ ИНДИВИДУАЛЬНАЯ ССЫЛКА ГОТОВА!</b>\n\n"
            f"🔗 {html.escape(link.invite_link)}\n\n"
            f"⏳ <b>Действует:</b> <code>{html.escape(time_left)}</code>\n"
            f"👤 <b>Использований:</b> <code>{max(1, INVITE_LINK_LIMIT or 1)}</code>\n\n"
            "⚠️ <i>Перейди по ссылке, чтобы присоединиться к чату.</i>",
            parse_mode="HTML",
            disable_web_page_preview=True
        )

        if not is_notified(user_id):
            try:
                user = call.from_user
                username = f"@{user.username}" if user.username else "нет"
                bot.send_message(
                    ADMIN_CHAT_ID,
                    f"👤 **Новый пользователь получил доступ!**\n"
                    f"Имя: {user.first_name}\n"
                    f"Юзернейм: {username}\n"
                    f"ID: `{user.id}`",
                    parse_mode="Markdown"
                )
                set_notified(user_id)
                _mark_admin_notified_in_db(user_id)
            except Exception as e:
                logger.error(f"Ошибка уведомления админа: {e}")

    except Exception as e:
        try:
            bot.delete_message(chat_id, wait_msg.message_id)
        except Exception:
            pass
        logger.exception("Ошибка создания инвайт-ссылки")
        bot.send_message(
            chat_id,
            "⚠️ Не удалось создать персональную ссылку. Используй основную:\n"
            f"{html.escape(INVITE_LINK)}",
            parse_mode="HTML",
            disable_web_page_preview=True
        )

    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda call: call.data == "check_subscriptions")
@safe_handler
def callback_check_subscriptions(call: CallbackQuery):
    """Проверка подписок после нажатия «Я подписался»."""
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    # Удаляем старое сообщение с кнопкой
    try:
        bot.delete_message(chat_id, call.message.message_id)
    except Exception:
        pass
    cache_delete(f"last_sub_message_{user_id}")
    ok, missing = check_all_subscriptions(user_id)
    if ok:
        # Очищаем все сохранённые ID сообщений о подписке для этого пользователя
        for key in list(cache.keys()):
            if key.startswith(f"last_sub_message_{user_id}"):
                cache_delete(key)
        bot.answer_callback_query(call.id)
        lang = get_user_language(user_id)
        bot.send_message(
            chat_id,
            "✅ Подписка проверена. Можете пользоваться ботом." if lang == "ru" else "✅ Subscription verified. You can use the bot.",
            parse_mode="Markdown",
        )
    else:
        lang = get_user_language(call.from_user.id)
        bot.answer_callback_query(call.id, t(lang, "subscribe_all_channels_retry"), show_alert=True)


@bot.callback_query_handler(func=lambda call: call.data == "ad_request_start")
@safe_handler
def callback_ad_request_start(call: CallbackQuery):
    """Кнопка «Заявка на рекламу» — открывает форму заявки в личке."""
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    lang = get_user_language(user_id)
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id, t(lang, "group_welcome_access_closed"))
        return
    if call.message.chat.type != "private":
        bot.answer_callback_query(call.id, t(lang, "ad_only_in_private"))
        return
    ok, err = _can_create_ad_request(user_id)
    if not ok:
        bot.answer_callback_query(call.id, _truncate_preserving_emoji(err, 200))
        return
    username = call.from_user.username or ""
    first_name = call.from_user.first_name or ""
    _send_ad_request_form(chat_id, user_id, username, first_name)
    bot.answer_callback_query(call.id, t(lang, "ad_write_below"))

# ============================================================================
# КОМАНДЫ: ВРЕМЯ И ГОРОД
# Порядок обработки: запросы «ком, который час» обрабатывает ai_direct_handler;
# фразы только о времени без префикса ком/ии — time_text_handler (см. условие ниже).
# ============================================================================

@bot.message_handler(commands=['time', 'время', 'time_msk', 'kom_time'])
@safe_handler
def cmd_time(message: Message):
    """Показывает время по Москве; при аргументе /time [город] — время в указанном городе; иначе — ещё время в сохранённом городе (/city)."""
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    parts = (message.text or "").strip().split(maxsplit=1)
    city_arg = parts[1].strip() if len(parts) > 1 else None

    time_str, date_str, weekday_ru = get_moscow_time_str()
    text = (
        f"🕒 **Московское время (МСК)**\n\n"
        f"• Сейчас: `{time_str}`\n"
        f"• Дата: `{date_str}` ({weekday_ru})"
    )

    # Если указан город в команде — показываем время в нём
    if city_arg:
        geo = _try_geocode_location(city_arg)
        tz_name = (geo or {}).get("timezone")
        if tz_name:
            loc_time, loc_date, loc_weekday = get_local_time_str(tz_name)
            if loc_time:
                city_name = (geo or {}).get("name") or city_arg
                text += (
                    f"\n\n🕐 **В городе {city_name}**\n\n"
                    f"• Сейчас: `{loc_time}`\n"
                    f"• Дата: `{loc_date}` ({loc_weekday})"
                )
            else:
                text += f"\n\n❌ Не удалось определить время для: {city_arg}"
        else:
            text += f"\n\n❌ Город не найден: {city_arg}"
    else:
        # Без аргумента — показываем сохранённый часовой пояс или город пользователя
        user_id = message.from_user.id
        tz = get_user_timezone(user_id)
        if tz:
            try:
                loc_time, loc_date, loc_weekday = get_local_time_str(tz)
                if loc_time:
                    text += (
                        f"\n\n🕐 **В твоём часовом поясе ({tz})**\n\n"
                        f"• Сейчас: `{loc_time}`\n"
                        f"• Дата: `{loc_date}` ({loc_weekday})"
                    )
            except Exception:
                pass
        city = get_user_city(user_id)
        if city and not tz:
            text += f"\n\n📍 Твой город: **{city}**"
            geo = _try_geocode_location(city)
            tz_name = (geo or {}).get("timezone")
            if tz_name:
                loc_time, loc_date, loc_weekday = get_local_time_str(tz_name)
                if loc_time:
                    text += (
                        f"\n\n🕐 **В твоём городе ({city})**\n\n"
                        f"• Сейчас: `{loc_time}`\n"
                        f"• Дата: `{loc_date}` ({loc_weekday})"
                    )
        elif not city and not tz:
            lang = get_user_language(user_id)
            text += "\n\n" + t(lang, "time_city_hint")
    bot.send_message(message.chat.id, text, parse_mode="Markdown")


@bot.message_handler(commands=['city', 'город', 'kom_city'])
@safe_handler
def cmd_city(message: Message):
    """Показать или установить свой город. По умолчанию в профиле показывается прочерк и подсказка /city. Использование: /city [город]"""
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    chat_id = message.chat.id
    parts = (message.text or "").strip().split(maxsplit=1)
    if len(parts) < 2:
        lang = get_user_language(user_id)
        city = get_user_city(user_id)
        msg = t(lang, "city_current", city=city or "—")
        msg += "\n\n" + (t(lang, "city_set_hint") if not city else t(lang, "city_change_hint"))
        bot.send_message(chat_id, msg, parse_mode="Markdown")
        return
    new_city = parts[1].strip()
    if not new_city:
        lang = get_user_language(user_id)
        bot.send_message(chat_id, t(lang, "city_name_example"), parse_mode="Markdown")
        return
    set_user_city(user_id, new_city)
    lang = get_user_language(user_id)
    bot.send_message(chat_id, t(lang, "city_updated_ok", new_city=new_city), parse_mode="Markdown")


@bot.message_handler(commands=['timezone', 'часовой_пояс', 'tz', 'kom_timezone'])
@safe_handler
def cmd_timezone(message: Message):
    """Показать или установить часовой пояс. Использование: /timezone [Europe/Moscow] или /timezone reset"""
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    chat_id = message.chat.id
    lang = get_user_language(user_id)
    parts = (message.text or "").strip().split(maxsplit=1)
    if len(parts) < 2:
        tz = get_user_timezone(user_id)
        if tz:
            try:
                loc_time, loc_date, loc_weekday = get_local_time_str(tz)
                if loc_time:
                    msg = (
                        f"🕐 **{t(lang, 'timezone_current')}** `{tz}`\n\n"
                        f"• {t(lang, 'timezone_time')}: `{loc_time}`\n"
                        f"• {t(lang, 'timezone_date')}: `{loc_date}` ({loc_weekday})"
                    )
                else:
                    msg = f"🕐 **{t(lang, 'timezone_current')}** `{tz}`\n\n❌ {t(lang, 'timezone_invalid')}"
            except Exception:
                msg = f"🕐 **{t(lang, 'timezone_current')}** `{tz}`\n\n❌ {t(lang, 'timezone_invalid')}"
        else:
            msg = (
                f"🕐 **{t(lang, 'timezone_title')}**\n\n"
                f"{t(lang, 'timezone_help')}\n\n"
                f"Пример: `/timezone Europe/London` или `/timezone America/New_York`"
            )
        bot.send_message(chat_id, msg, parse_mode="Markdown")
        return
    arg = parts[1].strip().lower()
    if arg in ("reset", "сброс", "clear", "удалить"):
        set_user_timezone(user_id, None)
        bot.send_message(chat_id, f"✅ {t(lang, 'timezone_reset')}", parse_mode="Markdown")
        return
    tz_name = parts[1].strip()
    loc_time, _, _ = get_local_time_str(tz_name)
    if not loc_time:
        bot.send_message(chat_id, f"❌ {t(lang, 'timezone_invalid')}: {tz_name}\n\n{t(lang, 'timezone_help')}", parse_mode="Markdown")
        return
    set_user_timezone(user_id, tz_name)
    bot.send_message(chat_id, f"✅ {t(lang, 'timezone_set')}: **{tz_name}**", parse_mode="Markdown")


