@bot.message_handler(commands=['weather', 'погода', 'kom_weather'])
@safe_handler
def cmd_weather(message: Message):
    """Погода в твоём городе (из /city) или в указанном: /weather [город]."""
    if not ensure_user_access(message):
        return
    parts = (message.text or "").strip().split(maxsplit=1)
    location = parts[1].strip() if len(parts) > 1 else get_user_city(message.from_user.id)
    if not location:
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "weather_city_prompt"), parse_mode="Markdown")
        return
    query_text = f"погода {location}"
    if maybe_send_weather_reply(message, query_text):
        try_delete_message(message.chat.id, message.message_id)


@bot.message_handler(commands=['forecast', 'прогноз', 'kom_forecast'])
@safe_handler
def cmd_forecast(message: Message):
    """Прогноз погоды на 7 дней. Использование: /forecast [город] (по умолчанию — город из /city)."""
    if not ensure_user_access(message):
        return
    parts = (message.text or "").strip().split(maxsplit=1)
    location = parts[1].strip() if len(parts) > 1 else get_user_city(message.from_user.id)
    if not location:
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "forecast_city_prompt"), parse_mode="Markdown")
        return
    query_text = f"погода {location} на 7 дней"
    if maybe_send_weather_reply(message, query_text):
        try_delete_message(message.chat.id, message.message_id)


