def _pick_random_joke(lang: str) -> str:
    """Локальная случайная шутка по языку (фолбэк, если сеть недоступна)."""
    l = (lang or "").strip().lower()
    pool = JOKES_EN if l == "en" else JOKES_RU
    return random.choice(pool)


def _pick_random_joke_adult(lang: str) -> str:
    """Локальная шутка 18+ (только для /joke18; не смешивать с безопасным API)."""
    l = (lang or "").strip().lower()
    pool = JOKES_EN_ADULT if l == "en" else JOKES_RU_ADULT
    return random.choice(pool)


def _sanitize_joke_text(s: str) -> str:
    t = (s or "").replace("\r\n", "\n").strip()
    if len(t) > 3500:
        t = t[:3497] + "..."
    return t


def _parse_jokeapi_payload(data: dict) -> Optional[str]:
    if not isinstance(data, dict) or data.get("error"):
        return None
    if data.get("type") == "single":
        return (data.get("joke") or "").strip() or None
    if data.get("type") == "twopart":
        setup = (data.get("setup") or "").strip()
        delivery = (data.get("delivery") or "").strip()
        if setup and delivery:
            return f"{setup}\n\n{delivery}"
        return (setup or delivery) or None
    return None


def _fetch_joke_jokeapi_en() -> Optional[str]:
    """Случайная шутка из JokeAPI (без категории Programming; safe-mode + blacklist)."""
    cat_options = (
        "Misc,Pun",
        "Pun",
        "Misc",
        "Spooky",
        "Misc,Spooky",
    )
    headers = {"User-Agent": "TelegramBot/1.0 (KomBot/joke; +https://telegram.org)"}
    for _ in range(3):
        cats = random.choice(cat_options)
        try:
            r = requests.get(
                f"https://v2.jokeapi.dev/joke/{cats}",
                params={
                    "blacklistFlags": "nsfw,religious,political,racist,sexist,explicit",
                    "safe-mode": "",
                    "type": random.choice(["single", "twopart"]),
                },
                timeout=12,
                headers=headers,
            )
            r.raise_for_status()
            text = _parse_jokeapi_payload(r.json())
            if text:
                return text
        except Exception:
            continue
    return None


def _fetch_joke_icanhaz_en() -> Optional[str]:
    """Резерв: icanhazdadjoke (JSON)."""
    try:
        r = requests.get(
            "https://icanhazdadjoke.com/",
            headers={
                "Accept": "application/json",
                "User-Agent": "TelegramBot/1.0 (KomBot/joke)",
            },
            timeout=10,
        )
        r.raise_for_status()
        j = (r.json() or {}).get("joke") or ""
        return j.strip() or None
    except Exception:
        return None


def _lingva_translate_en_to_ru(text: str) -> Optional[str]:
    """Перевод EN→RU через публичный Lingva (Google Translate frontend), без ключей."""
    t = (text or "").strip()
    if not t:
        return None
    if len(t) > 1200:
        t = t[:1197] + "..."
    try:
        seg = quote(t, safe="")
        url = f"https://lingva.ml/api/v1/en/ru/{seg}"
        r = requests.get(
            url,
            timeout=18,
            headers={"User-Agent": "TelegramBot/1.0 (KomBot/joke)"},
        )
        r.raise_for_status()
        data = r.json()
        out = (data.get("translation") or "").strip()
        return out or None
    except Exception:
        return None


def _fetch_joke_from_internet(lang: str) -> Optional[str]:
    """
    Шутка из сети: EN — JokeAPI / icanhaz; RU — та же база + перевод Lingva (актуальный пул англоязычных шуток).
    Перевод может «убить» каламбур — тогда пользователь может вызвать /joke ещё раз.
    """
    l = (lang or "").strip().lower()
    if os.getenv("JOKE_OFFLINE_ONLY", "").strip() == "1":
        return None
    try:
        en_joke = _fetch_joke_jokeapi_en() or _fetch_joke_icanhaz_en()
        if not en_joke:
            return None
        en_joke = _sanitize_joke_text(en_joke)
        if l == "en":
            return en_joke
        if l == "ru":
            ru = _lingva_translate_en_to_ru(en_joke)
            if ru:
                return _sanitize_joke_text(ru)
    except Exception as e:
        logger.warning("Online joke pipeline failed: %s", e)
    return None


def _resolve_joke_for_user(lang: str) -> str:
    """Сеть → локальный пул."""
    online = _fetch_joke_from_internet(lang)
    if online:
        return online
    return _pick_random_joke(lang)


