@bot.message_handler(commands=['roll', 'кубик'])
@safe_handler
@rate_limit(10)
def cmd_roll(message: Message):
    """Бросок кубика: /roll 4 — без ставки; /roll 100 4 — ставка 100 на число 4 (как в костях). Только в группе."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "games", message.from_user.id):
        return
    parts = (message.text or "").strip().split()
    args = parts[1:] if len(parts) > 1 else []
    # Ставка + число: /roll 100 4
    if len(args) >= 2 and args[0].isdigit() and args[1].isdigit():
        try:
            bet = int(args[0])
            guess = int(args[1])
        except ValueError:
            guess = 0
            bet = 0
        if 1 <= guess <= 6:
            user_id = message.from_user.id
            register_user(user_id)
            valid, err = DiceGame.validate_bet(bet, guess, user_id)
            if not valid:
                bot.reply_to(message, err, parse_mode="Markdown")
                return
            # Сообщение команды может быть уже автоудалено — не используем message.message_id для reply/delete
            try:
                dice_msg = bot.send_dice(
                    message.chat.id,
                    emoji="🎲",
                )
                roll = getattr(getattr(dice_msg, "dice", None), "value", None)
                if roll is None or not (1 <= roll <= 6):
                    roll = random.randint(1, 6)
                result, result_text = DiceGame.play(user_id, bet, guess, roll=roll)
                earned = check_game_achievements(user_id, result)
                current_balance = get_balance(user_id, use_cache=False)
                text = result_text + f"\n\n💰 Баланс: {format_amount_for_user(user_id, current_balance)}"
                if earned:
                    text += "\n\n🏆 **Новые достижения!**"
                    for ach in earned:
                        ach_data = achievements.get(ach, {})
                        text += f"\n• {ach_data.get('icon', '🏆')} {ach_data.get('name', ach)}"
                msg = bot.send_message(message.chat.id, text, parse_mode="Markdown", reply_to_message_id=dice_msg.message_id)
            except ValueError as e:
                msg = bot.send_message(message.chat.id, str(e), parse_mode="Markdown")
            if AUTO_DELETE_GAMES and msg:
                schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)
            return
    # Только число 1–6 — без ставки (развлечение)
    guess_str = args[0] if len(args) == 1 else ""
    if not guess_str or not guess_str.isdigit():
        bot.send_message(
            message.chat.id,
            "🎲 **Кубик**\n\nБез ставки: число от 1 до 6 — `/roll 4`\n"
            "Со ставкой: `/roll 100 4` (ставка 100 на 4)\n\n"
            f"Лимиты ставки: {DiceGame.MIN_BET}–{DiceGame.MAX_BET} {COM_EMOJI}",
            parse_mode="Markdown",
        )
        return
    try:
        guess = int(guess_str)
    except ValueError:
        guess = 0
    if guess < 1 or guess > 6:
        bot.send_message(
            message.chat.id,
            "🎲 Укажи число **от 1 до 6**. Например: `/roll 4` или `/roll 100 4`",
            parse_mode="Markdown",
        )
        return
    # Сообщение команды может быть автоудалено — не используем reply_to_message_id=message.message_id
    try:
        dice_msg = bot.send_dice(
            message.chat.id,
            emoji="🎲",
        )
        roll = getattr(getattr(dice_msg, "dice", None), "value", None)
    except Exception as e:
        logger.debug("send_dice failed, fallback to random: %s", e)
        roll = random.randint(1, 6)
        bot.send_message(
            message.chat.id,
            f"🎲 Выпало: **{roll}** (кубик через API недоступен)",
            parse_mode="Markdown",
        )
        return
    if roll is None or not (1 <= roll <= 6):
        roll = random.randint(1, 6)
    if roll == guess:
        result_text = f"Ты загадал **{guess}**. Выпало **{roll}** — угадал! 🎉"
    else:
        result_text = f"Ты загадал **{guess}**. Выпало **{roll}** — не угадал."
    bot.send_message(
        message.chat.id,
        result_text,
        parse_mode="Markdown",
        reply_to_message_id=dice_msg.message_id,
    )


def _normalize_flip_guess(s: str) -> Optional[str]:
    """Возвращает 'орёл' или 'решка' по строке, иначе None."""
    s = (s or "").strip().lower()
    if s in ("орёл", "орел", "орл", "eagle", "heads"):
        return "орёл"
    if s in ("решка", "решку", "tails"):
        return "решка"
    return None


@bot.message_handler(commands=['flip', 'монетка', 'kom_flip'])
@safe_handler
@rate_limit(10)
def cmd_flip(message: Message):
    """Монетка: без ставки — /flip орёл или кнопки; со ставкой — /flip 50 орёл. Только в группе."""
    if PVP_GAMES_ONLY:
        lang = get_group_language(message.chat.id) or "ru"
        bot.send_message(message.chat.id, _pvp_only_hint(lang), parse_mode="Markdown")
        return
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "games", message.from_user.id):
        return
    parts = (message.text or "").strip().split()
    args = parts[1:] if len(parts) > 1 else []
    # Со ставкой: /flip 50 орёл или /flip 50 решка
    if len(args) >= 2 and args[0].isdigit():
        try:
            bet = int(args[0])
            choice_str = " ".join(args[1:]).strip()
            guess = _normalize_flip_guess(choice_str)
        except (ValueError, IndexError):
            guess = None
            bet = 0
        if guess is not None:
            user_id = message.from_user.id
            register_user(user_id)
            valid, err = FlipGame.validate_bet(bet, user_id)
            if not valid:
                bot.send_message(message.chat.id, err, parse_mode="Markdown")
                return
            # Сообщение команды может быть автоудалено — не используем reply_to/schedule для message
            try:
                result, result_text = FlipGame.play(user_id, bet, guess)
                earned = check_game_achievements(user_id, result)
                current_balance = get_balance(user_id, use_cache=False)
                text = result_text + f"\n\n💰 Баланс: {format_amount_for_user(user_id, current_balance)}"
                if earned:
                    text += "\n\n🏆 **Новые достижения!**"
                    for ach in earned:
                        ach_data = achievements.get(ach, {})
                        text += f"\n• {ach_data.get('icon', '🏆')} {ach_data.get('name', ach)}"
                msg = bot.send_message(message.chat.id, text, parse_mode="Markdown")
            except ValueError as e:
                msg = bot.send_message(message.chat.id, str(e), parse_mode="Markdown")
            if AUTO_DELETE_GAMES and msg:
                schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)
            return
    # Без ставки: один аргумент — орёл/решка
    guess = _normalize_flip_guess(args[0]) if len(args) == 1 else None
    if guess is not None:
        side = "орёл" if random.random() < 0.5 else "решка"
        won = (side == guess)
        result_text = f"🪙 Выпало: **{side}**. Ты загадал **{guess}** — {'угадал! 🎉' if won else 'не угадал.'}"
        bot.reply_to(message, result_text, parse_mode="Markdown")
        return
    # Без выбора — показываем кнопки
    lang = get_user_language(message.from_user.id)
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton("🪙 " + t(lang, "flip_btn_heads"), callback_data="flip_choice_orel"),
        InlineKeyboardButton("🪙 " + t(lang, "flip_btn_tails"), callback_data="flip_choice_reshka"),
    )
    hint = t(lang, "coin_flip_hint_bet", min_bet=FlipGame.MIN_BET, max_bet=FlipGame.MAX_BET, sign=COM_EMOJI)
    bot.reply_to(message, t(lang, "coin_flip_choose") + hint, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("flip_choice_"))
@safe_handler
def callback_flip_choice(call: CallbackQuery):
    """Обработка выбора орёл/решка: подбрасываем и показываем результат."""
    chat_id = getattr(call.message, "chat", None) and getattr(call.message.chat, "id", None)
    if chat_id is not None and chat_id < 0 and not is_feature_enabled_for_chat(chat_id, "games", call.from_user.id):
        require_group_feature(chat_id, "games", call.from_user.id, from_callback=True, call=call)
        return
    lang = get_user_language(call.from_user.id)
    if call.data == "flip_choice_orel":
        guess = "орёл"
    else:
        guess = "решка"
    side = "орёл" if random.random() < 0.5 else "решка"
    won = (side == guess)
    result_text = f"🪙 Выпало: **{side}**. Ты выбрал **{guess}** — {'угадал! 🎉' if won else 'не угадал.'}"
    bot.answer_callback_query(call.id, t(lang, "coin_heads") if side == "орёл" else t(lang, "coin_tails"))
    try:
        bot.edit_message_text(result_text, call.message.chat.id, call.message.message_id, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, result_text, parse_mode="Markdown")


def _safe_calc(expr: str) -> Optional[float]:
    """
    Безопасное вычисление арифметики с использованием библиотеки simpleeval.
    Ограничения: длина выражения, ограничение результата.
    """
    expr = (expr or "").strip().replace(",", ".")
    if not expr or len(expr) > MAX_CALC_EXPR_LENGTH:
        return None

    try:
        if SIMPLEEVAL_AVAILABLE and simple_eval is not None:
            result = simple_eval(expr)
        else:
            return _fallback_safe_calc(expr)
        result = float(result)
        if abs(result) > MAX_CALC_RESULT_ABS or (result != result):  # NaN
            return None
        return result
    except (ZeroDivisionError, OverflowError, ValueError, SyntaxError, TypeError):
        return None
    except Exception:
        return None


def _fallback_safe_calc(expr: str) -> Optional[float]:
    """Запасной безопасный калькулятор на ast (без eval). Поддерживает +-*/(), **, унарный минус."""
    import ast as _ast
    import operator as _op
    _ops = {
        _ast.Add: _op.add, _ast.Sub: _op.sub, _ast.Mult: _op.mul,
        _ast.Div: _op.truediv, _ast.FloorDiv: _op.floordiv, _ast.Mod: _op.mod,
        _ast.USub: _op.neg, _ast.UAdd: _op.pos,
    }
    MAX_POW = 10
    def _eval(node, depth=0):
        if depth > 32:
            raise ValueError("too deep")
        if isinstance(node, _ast.Expression):
            return _eval(node.body, depth + 1)
        if isinstance(node, _ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, _ast.BinOp):
            op_type = type(node.op)
            if op_type is _ast.Pow:
                base = _eval(node.left, depth + 1)
                exp = _eval(node.right, depth + 1)
                if abs(exp) > MAX_POW or abs(base) > 1e6:
                    raise ValueError("pow too large")
                return base ** exp
            fn = _ops.get(op_type)
            if not fn:
                raise ValueError("op")
            return fn(_eval(node.left, depth + 1), _eval(node.right, depth + 1))
        if isinstance(node, _ast.UnaryOp):
            fn = _ops.get(type(node.op))
            if not fn:
                raise ValueError("op")
            return fn(_eval(node.operand, depth + 1))
        raise ValueError("unsupported")
    try:
        tree = _ast.parse(expr, mode="eval")
        result = float(_eval(tree))
        if abs(result) > MAX_CALC_RESULT_ABS or (result != result):
            return None
        return result
    except (ZeroDivisionError, OverflowError, ValueError, SyntaxError, TypeError):
        return None
    except Exception:
        return None


@bot.message_handler(commands=['calc', 'калькулятор', 'kom_calc'])
@safe_handler
def cmd_calc(message: Message):
    """Калькулятор: результат озвучивает Ком. /calc 2+2 или /calc 10*3."""
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "ai", message.from_user.id):
        return
    parts = (message.text or "").strip().split(maxsplit=1)
    expr = parts[1].strip() if len(parts) > 1 else ""
    try_delete_message(message.chat.id, message.message_id)
    result = _safe_calc(expr)
    if result is None:
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "calc_hint"), parse_mode="Markdown")
        return
    _run_ai_request(
        message,
        f"Ты бот в чате. Пользователь посчитал: {expr} = {result}. Скажи это коротко и живо в одном предложении.",
    )


