@bot.message_handler(commands=['convert', 'конверт', 'конвертация'])
@safe_handler
def cmd_convert(message: Message):
    """Конвертация COM в валюту. Использование: /convert сумма [валюта]."""
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    parts = (message.text or "").strip().split()
    if len(parts) < 2:
        cur = currency_manager.get_user_currency(user_id)
        if lang == "ru":
            lang = get_user_language(message.from_user.id)
            bot.reply_to(message, t(lang, "convert_amount_hint", cur=cur))
        else:
            bot.reply_to(message, f"❌ Specify amount. Example: /convert 1000 or /convert 500 {cur}")
        return
    try:
        amount = int(parts[1])
        if amount < 0:
            raise ValueError("negative")
    except ValueError:
        bot.reply_to(message, t(lang, "enter_number_example"))
        return
    currency = (parts[2].strip().upper() if len(parts) > 2 else None) or currency_manager.get_user_currency(user_id)
    if currency not in AVAILABLE_CURRENCIES:
        bot.reply_to(message, t(lang, "rate_unknown_currency"))
        return
    converted = currency_manager.convert(amount, currency)
    if converted is None:
        bot.reply_to(message, t(lang, "conversion_error"))
        return
    formatted = currency_manager.format_amount(amount, currency, include_com=True)
    if lang == "ru":
        text = f"💱 **Конвертация**\n\n{formatted}"
    else:
        text = f"💱 **Conversion**\n\n{formatted}"
    bot.reply_to(message, text, parse_mode="Markdown")


