@bot.message_handler(commands=['balance', 'bal', 'kom_balance', 'kom_bal'])
@safe_handler
@require_category("economy")
def cmd_balance(message: Message):
    """
    Команда для просмотра баланса.
    Использование: /balance
    """
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "economy", message.from_user.id):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id

    # Регистрируем пользователя
    register_user(user_id)
    
    # Получаем статистику
    balance = get_balance(user_id)
    stats = get_user_stats(user_id)
    game_stats = get_game_stats(user_id)
    transaction_stats = get_transaction_stats(user_id, days=7)
    
    chat_type = getattr(message.chat, "type", "private")
    in_group = chat_type in ("group", "supergroup")
    chat_id = message.chat.id if in_group else None
    display_rank = get_user_rank_for_display(user_id, chat_type, chat_id=chat_id)
    lang = get_user_language(user_id)
    status_name = get_group_rank_display_name(chat_id, display_rank, lang=lang) if (in_group and chat_id) else get_rank_name(display_rank, in_group=in_group)
    privileges = get_privileges_display(user_id, group_id=message.chat.id if in_group else None)
    maybe_notify_vip_expiring(user_id)
    # Баланс в валюте пользователя
    formatted_balance = format_amount_for_user(user_id, balance)
    other_currencies = []
    for cur in ("USD", "EUR", "BTC", "TON"):
        if cur != currency_manager.get_user_currency(user_id):
            conv = currency_manager.convert(balance, cur)
            if conv is not None:
                other_currencies.append(currency_manager.format_amount(balance, cur, include_com=False))
    other_line = "\n" + ("В других валютах: " if lang == "ru" else "In other currencies: ") + ", ".join(other_currencies) if other_currencies else ""
    # Формируем сообщение
    text = f"""
{t(lang, 'balance_title')}

{t(lang, 'balance_status')} {status_name}
{t(lang, 'balance_privileges')} {privileges}

{COM_EMOJI} {t(lang, 'balance_balance')} {formatted_balance}{other_line}

{t(lang, 'balance_stats')}
• {t(lang, 'balance_total_earned')}: `{format_number(stats['total_earned'])}` {COM_EMOJI}
• {t(lang, 'balance_total_spent')}: `{format_number(stats['total_spent'])}` {COM_EMOJI}
• {t(lang, 'balance_games_played')}: `{stats['games_played']}`
• {t(lang, 'balance_wins')}: `{stats['games_won']}` ({stats['win_rate']:.1f}%)

{t(lang, 'balance_week')}
• {t(lang, 'balance_received')}: `{format_number(transaction_stats['total_received'])}` {COM_EMOJI}
• {t(lang, 'balance_sent')}: `{format_number(transaction_stats['total_sent'])}` {COM_EMOJI}
• {t(lang, 'balance_transactions')}: `{transaction_stats['total_count']}`

{t(lang, 'balance_by_games')}
"""
    game_names = {"roulette": t(lang, "balance_game_roulette"), "dice": t(lang, "balance_game_dice"), "duel": t(lang, "balance_game_duel"), "cpc": t(lang, "balance_game_cpc")}
    if game_stats.get("games"):
        for game in game_stats["games"]:
            game_name = game_names.get(game["game"], game["game"])
            profit = game["total_won"] - game["total_bet"]
            profit_sign = "+" if profit > 0 else ""
            text += f"• {game_name}: {game['played']} {t(lang, 'balance_games_count')}, "
            text += f"{t(lang, 'balance_profit')}: {profit_sign}{format_number(profit)} {COM_EMOJI}\n"
    else:
        text += t(lang, "balance_no_games")
    
    menu_markup = build_main_menu_keyboard(user_id, lang)
    msg = bot.reply_to(message, text, parse_mode=None, reply_markup=menu_markup)
    # Автоудаление
    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)

@bot.message_handler(commands=['daily', 'kom_daily'])
@safe_handler
def cmd_daily(message: Message):
    """
    Команда для получения ежедневного бонуса.
    Использование: /daily
    """
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "economy", message.from_user.id):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id

    # Анонимные сообщения от имени канала/чата не участвуют в экономике.
    if getattr(message, "sender_chat", None) is not None:
        bot.reply_to(message, t(get_user_language(user_id), "daily_anonymous_denied"))
        return
    
    # Регистрируем пользователя
    register_user(user_id)
    
    # Получаем информацию о streak
    streak_info = DailyBonus.get_streak_info(user_id)
    
    # Пытаемся получить бонус
    success, amount, streak, msg_text = DailyBonus.claim(user_id)
    
    if success:
        lang = get_user_language(user_id)
        text = f"""
{t(lang, 'daily_received_title')}

{t(lang, 'daily_you_got')} `+{amount}` {COM_EMOJI}
{t(lang, 'daily_streak')} `{streak}` {t(lang, 'daily_streak_days')}
{t(lang, 'daily_new_balance')} `{format_number(get_balance(user_id))}` {COM_EMOJI}

{msg_text}

{t(lang, 'daily_next_in')}
        """
    else:
        # Показываем, сколько осталось
        lang = get_user_language(user_id)
        hours, minutes = get_next_daily_time(user_id)
        next_bonus_min = streak_info.get("next_bonus_min", streak_info.get("next_bonus", 0))
        next_bonus_max = streak_info.get("next_bonus_max", streak_info.get("next_bonus", 0))
        if DailyBonus.RANDOM_ENABLED:
            next_bonus_text = f"{next_bonus_min}-{next_bonus_max}"
        else:
            next_bonus_text = str(streak_info.get("next_bonus", 0))
        if (lang or "").strip().lower() == "en":
            countdown_str = f"{hours}h {minutes}m" if (hours or minutes) else t(lang, "daily_countdown_available")
        else:
            countdown_str = f"{hours}ч {minutes}м" if (hours or minutes) else t(lang, "daily_countdown_available")
        text = f"""
{t(lang, 'daily_already_title')}

{t(lang, 'daily_your_streak')} `{streak_info['streak']}` {t(lang, 'daily_streak_days')}
{t(lang, 'daily_next_bonus')} `{next_bonus_text}` {COM_EMOJI}

{t(lang, 'daily_until_next')} {countdown_str}

{t(lang, 'daily_come_tomorrow')}
        """
    
    keyboard = InlineKeyboardMarkup(row_width=2)
    keyboard.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
    keyboard.add(InlineKeyboardButton("🛒 " + t(lang, "menu_shop"), callback_data="start_menu_shop"))
    msg = bot.reply_to(message, text, reply_markup=keyboard, parse_mode="Markdown")

    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)


