@bot.message_handler(commands=["buy", "kom_buy"])
@safe_handler
def cmd_buy(message: Message):
    """Главное меню покупки монет."""
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    register_user(user_id)
    balance = get_balance(user_id)
    rate_rub = get_exchange_rate("RUB", "COINS") or PAYMENT_RUB_TO_COINS
    com_rate = 1.0 / rate_rub if rate_rub else 0.1
    text = (
        "💰 **Покупка внутренней валюты**\n\n"
        f"💎 Твой баланс: {format_com_amount(balance)}\n"
        f"📊 Курс: **1 {COM_EMOJI} = {com_rate:.2f} ₽** (1 ₽ = {rate_rub} {COM_EMOJI})\n\n"
        "Выбери способ оплаты:"
    )
    # send_message вместо reply_to: при открытии по кнопке «Купить монеты» сообщение уже удалено, reply_to падает
    try:
        bot.reply_to(message, text, reply_markup=_buy_coins_keyboard(lang), parse_mode="Markdown")
    except Exception:
        bot.send_message(message.chat.id, text, reply_markup=_buy_coins_keyboard(lang), parse_mode="Markdown")


