@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("stars_amt_"))
@safe_handler
def cb_stars_amount(callback: CallbackQuery):
    """Отправка инвойса Telegram Stars."""
    lang = get_user_language(callback.from_user.id)
    parts = callback.data.split("_")
    if len(parts) != 4:
        bot.answer_callback_query(callback.id, t(lang, "err_params"))
        return
    stars_amt = int(parts[2])
    coins_amt = int(parts[3])
    user_id = callback.from_user.id
    payload = f"stars_{user_id}_{stars_amt}_{coins_amt}"
    prices = [LabeledPrice(label=f"{coins_amt} {COINS_NAME}", amount=stars_amt)]
    try:
        bot.send_invoice(
            callback.message.chat.id,
            title="Пополнение баланса",
            description=f"Получить {coins_amt} {COM_EMOJI}",
            invoice_payload=payload,
            provider_token="",  # пусто для Stars
            currency="XTR",
            prices=prices,
            start_parameter="buy_stars",
        )
    except Exception as e:
        logger.exception("send_invoice Stars: %s", e)
        bot.answer_callback_query(callback.id, t(lang, "err_create_invoice"), show_alert=True)
        return
    bot.answer_callback_query(callback.id)


