@bot.message_handler(content_types=["successful_payment"])
@safe_handler
def successful_payment_handler(message: Message):
    """Успешная оплата (Telegram Stars и др.)."""
    if not message.successful_payment:
        return
    sp = message.successful_payment
    payload = getattr(sp, "invoice_payload", "") or ""
    if not payload.startswith("stars_"):
        return
    parts = payload.split("_")
    if len(parts) < 4:
        return
    user_id = int(parts[1])
    stars_amount = sp.total_amount
    coins_amt = int(parts[3])
    # Идемпотентность по invoice_payload (у Telegram один payload на один платёж)
    tx_id = f"stars_{sp.telegram_payment_charge_id}"
    if is_payment_transaction_processed(tx_id):
        lang = get_user_language(user_id)
        bot.reply_to(message, t(lang, "payment_coins_already_added"))
        return
    add_coins(user_id, coins_amt, reason="Покупка за Telegram Stars", admin_id=None)
    apply_purchase_commissions(user_id, coins_amt)
    record_payment_transaction(
        user_id=user_id,
        coins_received=coins_amt,
        payment_method="stars",
        payment_system="telegram_stars",
        transaction_id=tx_id,
        amount_stars=stars_amount,
        status="completed",
    )
    lang = get_user_language(user_id)
    bot.reply_to(message, t(lang, "balance_topup_ok", coins_amt=coins_amt, sign=COM_EMOJI))


