def _crypto_create_invoice(user_id: int, amount_fiat: float, asset: str) -> Optional[Dict[str, Any]]:
    """Создаёт счёт Crypto Pay. Возвращает dict с pay_url и invoice_id или None."""
    try:
        from CryptoPaySDK import cryptopay

        crypto = cryptopay.Crypto(api_token=CRYPTO_PAY_TOKEN, testnet=False)
        bot_username = bot.get_me().username or "YourBot"
        coins = int(amount_fiat * (get_exchange_rate("USD", "COINS") or 900.0))
        invoice = crypto.createInvoice(
            asset,
            str(amount_fiat),
            params={
                "description": f"Пополнение баланса на {coins} монет",
                "payload": str(user_id),
                "expires_in": 3600,
                "paid_btn_name": "openBot",
                "paid_btn_url": f"https://t.me/{bot_username}",
            },
        )
        pay_url = getattr(invoice, "bot_invoice_url", None) or getattr(invoice, "pay_url", None)
        if invoice and pay_url:
            return {"pay_url": pay_url, "invoice_id": getattr(invoice, "invoice_id", None)}
    except ImportError:
        logger.warning("CryptoPaySDK не установлен: pip install CryptoPaySDK")
        return None
    except Exception as e:
        logger.exception("Crypto createInvoice: %s", e)
        return None
    return None


