def _handle_custom_amount_message(message: Message) -> bool:
    """Обрабатывает ввод пользователем суммы для покупки. Возвращает True если обработано."""
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    with _state_lock:
        method = payment_custom_amount_state.pop(user_id, None)
    if not method or not message.text:
        return False
    text = (message.text or "").strip().replace(" ", "").replace(",", ".")
    try:
        amount = int(float(text))
    except ValueError:
        bot.reply_to(message, t(lang, "enter_number_example"))
        with _state_lock:
            payment_custom_amount_state[user_id] = method
        return True
    if amount <= 0:
        bot.reply_to(message, t(lang, "amount_must_be_positive"))
        with _state_lock:
            payment_custom_amount_state[user_id] = method
        return True
    if method == "rub":
        if not YOOKASSA_SHOP_ID or not YOOKASSA_SECRET_KEY:
            bot.reply_to(message, t(lang, "payment_rub_not_configured"))
            return True
        rate = get_exchange_rate("RUB", "COINS") or PAYMENT_RUB_TO_COINS
        coins = int(amount * rate)
        if coins <= 0:
            bot.reply_to(message, t(lang, "amount_too_low"))
            return True
        try:
            import yookassa
            from yookassa import Payment
            yookassa.Configuration.account_id = YOOKASSA_SHOP_ID
            yookassa.Configuration.secret_key = YOOKASSA_SECRET_KEY
            payment = Payment.create({
                "amount": {"value": str(amount), "currency": "RUB"},
                "confirmation": {"type": "redirect", "return_url": f"https://t.me/{bot.get_me().username or 'YourBot'}"},
                "capture": True,
                "description": f"Пополнение баланса на {coins} {COM_EMOJI}",
                "metadata": {"user_id": str(user_id), "coins": str(coins)},
            })
            url = payment.confirmation.confirmation_url
            record_payment_transaction(
                user_id=user_id,
                coins_received=coins,
                payment_method="card",
                payment_system="yookassa",
                transaction_id=payment.id,
                amount_rub=float(amount),
                status="pending",
            )
            bot.reply_to(message, t(lang, "payment_link_rub", amount=amount, coins=coins, sign=COM_EMOJI, url=url), parse_mode="Markdown")
        except Exception as e:
            logger.exception("YooKassa create: %s", e)
            bot.reply_to(message, t(lang, "payment_create_error"))
    else:
        if not STRIPE_SECRET_KEY:
            bot.reply_to(message, t(lang, "payment_cards_not_configured"))
            return True
        rate = get_exchange_rate("USD", "COINS") or 900.0
        coins = int(amount * rate)
        if coins <= 0:
            bot.reply_to(message, t(lang, "amount_too_low"))
            return True
        try:
            import stripe
            stripe.api_key = STRIPE_SECRET_KEY
            session = stripe.checkout.Session.create(
                payment_method_types=["card"],
                line_items=[{
                    "price_data": {
                        "currency": "usd",
                        "product_data": {"name": f"Пополнение баланса на {coins} {COM_EMOJI}"},
                        "unit_amount": amount * 100,
                    },
                    "quantity": 1,
                }],
                mode="payment",
                success_url=f"https://t.me/{bot.get_me().username or 'YourBot'}?start=payment_success",
                cancel_url=f"https://t.me/{bot.get_me().username or 'YourBot'}?start=payment_cancel",
                metadata={"user_id": str(user_id), "coins": str(coins)},
            )
            record_payment_transaction(
                user_id=user_id,
                coins_received=coins,
                payment_method="card",
                payment_system="stripe",
                transaction_id=session.id,
                amount_usd=float(amount),
                status="pending",
            )
            bot.reply_to(message, t(lang, "payment_link_usd", amount=amount, coins=coins, sign=COM_EMOJI, url=session.url), parse_mode="Markdown")
        except Exception as e:
            logger.exception("Stripe Session: %s", e)
            bot.reply_to(message, t(lang, "session_create_error"))
    return True


