@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("amount_rub_"))
@safe_handler
def cb_amount_rub(callback: CallbackQuery):
    """Создание платежа ЮKassa (рубли)."""
    lang = get_user_language(callback.from_user.id)
    parts = callback.data.split("_")
    if len(parts) < 4:
        bot.answer_callback_query(callback.id, t(lang, "err_generic"))
        return
    amount_rub, coins = int(parts[2]), int(parts[3])
    user_id = callback.from_user.id
    try:
        import yookassa
        from yookassa import Payment
        yookassa.Configuration.account_id = YOOKASSA_SHOP_ID
        yookassa.Configuration.secret_key = YOOKASSA_SECRET_KEY
        payment = Payment.create({
            "amount": {"value": str(amount_rub), "currency": "RUB"},
            "confirmation": {"type": "redirect", "return_url": f"https://t.me/{bot.get_me().username or 'YourBot'}"},
            "capture": True,
            "description": f"Пополнение баланса на {coins} {COM_EMOJI}",
            "metadata": {"user_id": str(user_id), "coins": str(coins)},
        })
        url = payment.confirmation.confirmation_url
        record_payment_transaction(
            user_id=user_id,
            coins_received=coins,
            payment_method="card",
            payment_system="yookassa",
            transaction_id=payment.id,
            amount_rub=float(amount_rub),
            status="pending",
        )
        text = f"💳 **Оплата {amount_rub}₽** → {coins} {COM_EMOJI}\n\n[Перейти к оплате]({url})"
        try:
            bot.edit_message_text(text, callback.message.chat.id, callback.message.message_id, parse_mode="Markdown")
        except Exception:
            bot.send_message(callback.message.chat.id, text, parse_mode="Markdown")
    except ImportError:
        bot.answer_callback_query(callback.id, t(lang, "yookassa_not_configured"), show_alert=True)
    except Exception as e:
        logger.exception("YooKassa create: %s", e)
        bot.answer_callback_query(callback.id, t(lang, "payment_create_error"), show_alert=True)
    bot.answer_callback_query(callback.id)


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("amount_usd_"))
@safe_handler
def cb_amount_usd(callback: CallbackQuery):
    """Создание сессии Stripe Checkout (USD)."""
    lang = get_user_language(callback.from_user.id)
    parts = callback.data.split("_")
    if len(parts) < 4:
        bot.answer_callback_query(callback.id, t(lang, "err_generic"))
        return
    amount_usd, coins = int(parts[2]), int(parts[3])
    user_id = callback.from_user.id
    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        session = stripe.checkout.Session.create(
            payment_method_types=["card"],
            line_items=[{
                "price_data": {
                    "currency": "usd",
                    "product_data": {"name": f"Пополнение баланса на {coins} {COM_EMOJI}"},
                    "unit_amount": amount_usd * 100,
                },
                "quantity": 1,
            }],
            mode="payment",
            success_url=f"https://t.me/{bot.get_me().username or 'YourBot'}?start=payment_success",
            cancel_url=f"https://t.me/{bot.get_me().username or 'YourBot'}?start=payment_cancel",
            metadata={"user_id": str(user_id), "coins": str(coins)},
        )
        record_payment_transaction(
            user_id=user_id,
            coins_received=coins,
            payment_method="card",
            payment_system="stripe",
            transaction_id=session.id,
            amount_usd=float(amount_usd),
            status="pending",
        )
        text = f"💳 **Оплата ${amount_usd}** → {coins} {COM_EMOJI}\n\n[Перейти к оплате]({session.url})"
        try:
            bot.edit_message_text(text, callback.message.chat.id, callback.message.message_id, parse_mode="Markdown")
        except Exception:
            bot.send_message(callback.message.chat.id, text, parse_mode="Markdown")
    except ImportError:
        bot.answer_callback_query(callback.id, t(lang, "stripe_not_configured"), show_alert=True)
    except Exception as e:
        logger.exception("Stripe Session: %s", e)
        bot.answer_callback_query(callback.id, t(lang, "session_create_error_alert"), show_alert=True)
    bot.answer_callback_query(callback.id)


def on_crypto_payment_webhook(invoice_id: str, user_id: int, amount_usd: float, asset: str) -> bool:
    """
    Вызывается вебхуком Crypto Pay при оплате счёта.
    Начисляет монеты, записывает платёж, защита от повтора по invoice_id.
    """
    if is_payment_transaction_processed(invoice_id):
        return True
    rate = get_exchange_rate("USD", "COINS") or 900.0
    coins = int(amount_usd * rate)
    add_coins(user_id, coins, reason="Покупка криптой (Crypto Pay)", admin_id=None)
    apply_purchase_commissions(user_id, coins)
    record_payment_transaction(
        user_id=user_id,
        coins_received=coins,
        payment_method="crypto",
        payment_system="cryptopay",
        transaction_id=invoice_id,
        amount_usd=amount_usd,
        status="completed",
    )
    try:
        lang = get_user_language(user_id)
        bot.send_message(user_id, t(lang, "balance_topup_ok", coins_amt=coins, sign=COM_EMOJI))
    except Exception:
        pass
    return True


def on_yookassa_payment_webhook(payment_id: str, user_id: int, amount_rub: float, coins: int, status: str) -> bool:
    """Обработка уведомления ЮKassa: начисление монет при payment.succeeded."""
    if status != "succeeded":
        return True
    if is_payment_transaction_processed(payment_id):
        return True
    add_coins(user_id, coins, reason="Покупка (ЮKassa)", admin_id=None)
    apply_purchase_commissions(user_id, coins)
    update_payment_transaction_completed(payment_id)
    try:
        lang = get_user_language(user_id)
        bot.send_message(user_id, t(lang, "balance_topup_ok", coins_amt=coins, sign=COM_EMOJI))
    except Exception:
        pass
    return True


