@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and p2p_state.get(m.from_user.id, {}).get("step") == "amount")
@safe_handler
def p2p_process_amount(message: Message):
    """Обработка введённой суммы для продажи P2P."""
    user_id = message.from_user.id
    state = p2p_state.get(user_id)
    if not state or state.get("step") != "amount":
        return
    if not message.text:
        bot.reply_to(message, "❌ Введите число текстом")
        return
    try:
        amount = int(message.text.strip())
    except ValueError:
        bot.reply_to(message, "❌ Пожалуйста, введите число")
        return
    balance = get_balance(user_id)
    if amount <= 0:
        bot.reply_to(message, "❌ Сумма должна быть больше 0")
        return
    if amount > balance:
        bot.reply_to(message, f"❌ Недостаточно монет. Доступно: {format_com_amount(balance)}")
        return
    with _state_lock:
        p2p_state[user_id] = {"step": "currency", "amount": amount}
    lang = get_user_language(user_id)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("🇷🇺 RUB", callback_data="p2p_currency_RUB"), InlineKeyboardButton("🇺🇸 USD", callback_data="p2p_currency_USD")],
        [InlineKeyboardButton("🇺🇦 UAH", callback_data="p2p_currency_UAH"), InlineKeyboardButton("🇪🇺 EUR", callback_data="p2p_currency_EUR")],
        [InlineKeyboardButton("💵 USDT", callback_data="p2p_currency_USDT"), InlineKeyboardButton("💎 TON", callback_data="p2p_currency_TON")],
        [InlineKeyboardButton(t(lang, "withdraw_cancel_btn"), callback_data="withdraw_p2p_menu")]
    ])
    bot.reply_to(message, f"📢 Продажа {format_com_amount(amount)}\n\nВыберите валюту получения:", reply_markup=keyboard)


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("p2p_currency_"))
@safe_handler
def p2p_process_currency(call: CallbackQuery):
    user_id = call.from_user.id
    state = p2p_state.get(user_id)
    if not state or state.get("step") != "currency":
        bot.answer_callback_query(call.id, "❌ Сессия истекла. Начните заново.")
        return
    currency = call.data.replace("p2p_currency_", "")
    amount = state["amount"]
    rate = P2P_COM_RATES.get(currency, 1.0)
    estimated = amount * rate
    with _state_lock:
        p2p_state[user_id] = {"step": "price", "amount": amount, "currency": currency, "estimated": estimated}
    price_per_com = rate
    lang = get_user_language(call.from_user.id)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"По рынку ({estimated:.2f} {currency})", callback_data=f"p2p_price_market_{price_per_com:.6f}".replace(".", "_"))],
        [InlineKeyboardButton(t(lang, "back_btn"), callback_data="p2p_create_sell")]
    ])
    text = (
        f"📢 Продажа {format_com_amount(amount)}\n"
        f"💱 Валюта: {currency}\n"
        f"📊 Примерная сумма: {estimated:.2f} {currency}\n\n"
        f"Выберите тип цены:"
    )
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=keyboard, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=keyboard, parse_mode="Markdown")
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("p2p_price_market_"))
@safe_handler
def p2p_create_order_market(call: CallbackQuery):
    """Выбор цены -> переход к опциональным лимитам (способ оплаты, min/max) или сразу создание ордера."""
