@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("p2p_cancel_order_"))
@safe_handler
def p2p_cancel_order(call: CallbackQuery):
    """Отмена ордера на продажу: возврат COM на баланс продавца."""
    try:
        order_id = int(call.data.replace("p2p_cancel_order_", ""))
    except ValueError:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "error_short"), show_alert=True)
        return
    user_id = call.from_user.id
    with database_connection(ECONOMY_DB) as conn:
        row = conn.execute(
            "SELECT user_id, remaining_com, status FROM p2p_sell_orders WHERE id = ?",
            (order_id,)
        ).fetchone()
        if not row:
            bot.answer_callback_query(call.id, "Ордер не найден", show_alert=True)
            return
        seller_id, remaining_com, status = row
        if seller_id != user_id:
            bot.answer_callback_query(call.id, "Не ваш ордер", show_alert=True)
            return
        if status != "active" or remaining_com <= 0:
            bot.answer_callback_query(call.id, "Ордер уже не активен", show_alert=True)
            return
        conn.execute("UPDATE users SET balance = balance + ? WHERE user_id = ?", (remaining_com, user_id))
        conn.execute("UPDATE p2p_sell_orders SET status = 'cancelled', remaining_com = 0 WHERE id = ?", (order_id,))
        conn.commit()
    cache_delete(f"balance_{user_id}")
    bot.answer_callback_query(call.id, f"Ордер #{order_id} отменён. {format_com_amount(remaining_com)} возвращены на баланс.", show_alert=True)
    p2p_my_orders(call)


