@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and p2p_state.get(m.from_user.id, {}).get("step") == "buy_amount")
@safe_handler
def p2p_process_buy_amount(message: Message):
    user_id = message.from_user.id
    state = p2p_state.get(user_id)
    if not state or state.get("step") != "buy_amount":
        return
    if not message.text:
        bot.reply_to(message, "❌ Введите число текстом")
        return
    try:
        amount = int(message.text.strip())
    except ValueError:
        bot.reply_to(message, "❌ Введите число")
        return
    order_id = state["order_id"]
    with database_connection(ECONOMY_DB) as conn:
        order = conn.execute(
            "SELECT user_id, remaining_com, price_per_com, fiat_currency FROM p2p_sell_orders WHERE id = ? AND status = 'active'",
            (order_id,)
        ).fetchone()
    if not order:
        bot.reply_to(message, "❌ Ордер уже не активен")
        with _state_lock:
            p2p_state.pop(user_id, None)
        return
    seller_id, rem, price, cur = order
    if amount <= 0 or amount > rem:
        bot.reply_to(message, f"❌ Доступно только {format_com_amount(rem)}")
        return
    if seller_id == user_id:
        bot.reply_to(message, "❌ Нельзя купить у самого себя")
        with _state_lock:
            p2p_state.pop(user_id, None)
        return
    with _state_lock:
        p2p_state.pop(user_id, None)
    _p2p_do_buy(message.chat.id, None, user_id, order_id, amount, None)
    bot.reply_to(message, "✅ Заявка создана. Проверьте сообщение выше.")


def _p2p_do_buy(chat_id: int, message_id: Optional[int], buyer_id: int, order_id: int, amount: int, callback_query_id: Optional[str]):
    """Создаёт сделку P2P и уведомляет продавца."""
    with database_connection(ECONOMY_DB) as conn:
        order = conn.execute(
            "SELECT user_id, remaining_com, price_per_com, fiat_currency FROM p2p_sell_orders WHERE id = ? AND status = 'active'",
            (order_id,)
        ).fetchone()
        if not order:
            if callback_query_id:
                bot.answer_callback_query(callback_query_id, "❌ Ордер не активен", show_alert=True)
            return
        seller_id, rem, price, cur = order
        total_fiat = amount * price
        conn.execute(
            "INSERT INTO p2p_trades (order_id, seller_id, buyer_id, amount_com, price_per_com, total_fiat, fiat_currency, status) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending')",
            (order_id, seller_id, buyer_id, amount, price, total_fiat, cur)
        )
        trade_id = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
        new_rem = rem - amount
        if new_rem == 0:
            conn.execute("UPDATE p2p_sell_orders SET status = 'completed', remaining_com = 0 WHERE id = ?", (order_id,))
        else:
            conn.execute("UPDATE p2p_sell_orders SET remaining_com = ? WHERE id = ?", (new_rem, order_id))
        conn.commit()
    try:
        bot.send_message(
            seller_id,
            f"🛒 **Новая заявка на покупку!**\n\n👤 Покупатель: ID {buyer_id}\n💰 Сумма: {format_com_amount(amount)}\n💱 К оплате: {total_fiat:.2f} {cur}\n🆔 Сделка: #{trade_id}\n\nОжидайте оплату, затем подтвердите получение.",
            parse_mode="Markdown"
        )
    except Exception:
        pass
    _lang = get_user_language(buyer_id)
    text = (
        f"✅ **Заявка создана!**\n\n"
        f"🆔 Сделка: #{trade_id}\n"
        f"💰 Покупка: {format_com_amount(amount)}\n"
        f"💱 К оплате: {total_fiat:.2f} {cur}\n\n"
        + t(_lang, "p2p_trade_important")
    )
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(t(_lang, "p2p_i_paid_btn"), callback_data=f"p2p_trade_paid_{trade_id}")],
        [InlineKeyboardButton("📋 " + t(_lang, "p2p_my_trades_btn"), callback_data="p2p_my_trades")],
        [InlineKeyboardButton(t(_lang, "p2p_open_dispute_btn"), callback_data=f"p2p_dispute_{trade_id}")]
    ])
    if message_id:
        try:
            bot.edit_message_text(text, chat_id, message_id, reply_markup=keyboard, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=keyboard, parse_mode="Markdown")
    else:
        bot.send_message(chat_id, text, reply_markup=keyboard, parse_mode="Markdown")
    if callback_query_id:
        bot.answer_callback_query(callback_query_id, "✅ Сделка создана")


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("p2p_trade_paid_"))
@safe_handler
def p2p_trade_paid(call: CallbackQuery):
    """Покупатель подтверждает оплату."""
    trade_id = int(call.data.replace("p2p_trade_paid_", ""))
    buyer_id = call.from_user.id
    with database_connection(ECONOMY_DB) as conn:
        trade = conn.execute(
            "SELECT seller_id, buyer_id, amount_com, total_fiat, fiat_currency, status FROM p2p_trades WHERE id = ? AND buyer_id = ?",
            (trade_id, buyer_id)
        ).fetchone()
        if not trade:
            bot.answer_callback_query(call.id, "❌ Сделка не найдена", show_alert=True)
            return
        seller_id, _, amount_com, total_fiat, cur, status = trade
        if status != "pending":
            bot.answer_callback_query(call.id, "❌ Сделка уже обработана", show_alert=True)
            return
        conn.execute("UPDATE p2p_trades SET status = 'paid', paid_at = datetime('now') WHERE id = ?", (trade_id,))
        conn.commit()
    try:
        bot.send_message(
            seller_id,
            f"✅ **Покупатель подтвердил оплату!**\n\n🆔 Сделка: #{trade_id}\n💰 Сумма: {format_com_amount(amount_com)}\n💱 Получено: {total_fiat} {cur}\n\nПроверьте поступление и подтвердите получение (отправьте COM покупателю).",
            parse_mode="Markdown"
        )
    except Exception:
        pass
    _seller_lang = get_user_language(seller_id)
    try:
        bot.send_message(
            seller_id,
            "Подтвердите получение денег и отправку COM:",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(t(_seller_lang, "p2p_confirm_com_sent_btn"), callback_data=f"p2p_seller_confirm_{trade_id}")]
            ])
        )
    except Exception:
        pass
    bot.answer_callback_query(call.id, "✅ Статус обновлён. Ожидайте подтверждения продавца.", show_alert=True)
    _buyer_lang = get_user_language(buyer_id)
    try:
        bot.edit_message_text(
            f"✅ Вы подтвердили оплату по сделке #{trade_id}. Ожидайте, пока продавец отправит COM.",
            call.message.chat.id,
            call.message.message_id,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("📋 " + t(_buyer_lang, "p2p_my_trades_btn"), callback_data="p2p_my_trades")]])
        )
    except Exception:
        pass


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("p2p_seller_confirm_"))
@safe_handler
def p2p_seller_confirm(call: CallbackQuery):
    """Продавец подтверждает получение денег и освобождает COM покупателю."""
    trade_id = int(call.data.replace("p2p_seller_confirm_", ""))
    seller_id = call.from_user.id
    with database_connection(ECONOMY_DB) as conn:
        trade = conn.execute(
            "SELECT id, seller_id, buyer_id, amount_com, status FROM p2p_trades WHERE id = ? AND seller_id = ?",
            (trade_id, seller_id)
        ).fetchone()
        if not trade:
            bot.answer_callback_query(call.id, "❌ Сделка не найдена", show_alert=True)
            return
        _, _, buyer_id, amount_com, status = trade
        if status != "paid":
            bot.answer_callback_query(call.id, "❌ Покупатель ещё не подтвердил оплату", show_alert=True)
            return
        conn.execute("UPDATE users SET balance = balance + ? WHERE user_id = ?", (amount_com, buyer_id))
        conn.execute("UPDATE p2p_trades SET status = 'confirmed', confirmed_at = datetime('now') WHERE id = ?", (trade_id,))
        conn.execute("INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)", (seller_id,))
        conn.execute(
            "UPDATE user_withdrawal_limits SET successful_trades = successful_trades + 1, total_withdrawn_com = total_withdrawn_com + ? WHERE user_id = ?",
            (amount_com, seller_id)
        )
        conn.commit()
    cache_delete(f"balance_{buyer_id}")
    try:
        bot.send_message(buyer_id, f"✅ **Сделка завершена!**\n\n🆔 Сделка: #{trade_id}\n💰 Получено: {format_com_amount(amount_com)}\n\nCOM зачислены на ваш баланс!", parse_mode="Markdown")
    except Exception:
        pass
    bot.answer_callback_query(call.id, "✅ COM отправлены покупателю!", show_alert=True)
    try:
        _seller_lang = get_user_language(seller_id)
        bot.edit_message_text(
            f"✅ Сделка #{trade_id} завершена. COM успешно отправлены покупателю.",
            call.message.chat.id,
            call.message.message_id,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("📋 " + t(_seller_lang, "p2p_my_trades_btn"), callback_data="p2p_my_trades")]])
        )
    except Exception:
        pass


@bot.callback_query_handler(func=lambda c: c.data == "p2p_my_trades")
@safe_handler
def p2p_my_trades(call: CallbackQuery):
    """Список сделок пользователя."""
    user_id = call.from_user.id
    with database_connection(ECONOMY_DB) as conn:
        trades = conn.execute(
            "SELECT id, order_id, seller_id, buyer_id, amount_com, total_fiat, fiat_currency, status FROM p2p_trades WHERE seller_id = ? OR buyer_id = ? ORDER BY id DESC LIMIT 20",
            (user_id, user_id)
        ).fetchall()
    if not trades:
        text = "📋 У вас пока нет сделок."
    else:
        text = "📋 **Ваши сделки**\n\n"
        for t in trades:
            tid, oid, sid, bid, amt, tf, cur, st = t
            role = "Продавец" if sid == user_id else "Покупатель"
            text += f"#{tid} {role} {format_com_amount(amt)} {tf:.2f} {cur} — {st}\n"
    lang = get_user_language(user_id)
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton(t(lang, "back_btn"), callback_data="withdraw_p2p_menu")]])
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=keyboard, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=keyboard, parse_mode="Markdown")
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda c: c.data == "p2p_order_book" or (c.data and c.data.startswith("p2p_order_book_")))
@safe_handler
def p2p_order_book(call: CallbackQuery):
    """Книга ордеров с фильтром по валюте. p2p_order_book или p2p_order_book_RUB."""
    currency_filter = None
    if call.data and call.data != "p2p_order_book" and call.data.startswith("p2p_order_book_"):
        currency_filter = call.data.replace("p2p_order_book_", "", 1).strip() or None
    lang = get_user_language(call.from_user.id)
    with database_connection(ECONOMY_DB) as conn:
        if currency_filter:
            orders = conn.execute(
                """SELECT id, user_id, remaining_com, amount_com, price_per_com, fiat_currency, payment_methods, min_amount, max_amount
                   FROM p2p_sell_orders WHERE status = 'active' AND fiat_currency = ? ORDER BY price_per_com ASC LIMIT 25""",
                (currency_filter,)
            ).fetchall()
        else:
            orders = conn.execute(
                """SELECT id, user_id, remaining_com, amount_com, price_per_com, fiat_currency, payment_methods, min_amount, max_amount
                   FROM p2p_sell_orders WHERE status = 'active' ORDER BY price_per_com ASC, fiat_currency LIMIT 25"""
            ).fetchall()
    if not orders:
        text = t(lang, "p2p_no_orders") + (f" ({currency_filter})" if currency_filter else "")
        keyboard = InlineKeyboardMarkup([[_p2p_filter_currency_row(lang, "p2p_order_book")], [InlineKeyboardButton(t(lang, "back_btn"), callback_data="withdraw_p2p_menu")]])
    else:
        text = "📊 **" + t(lang, "p2p_order_book_title") + "**"
        if currency_filter:
            text += f" — {currency_filter}\n\n"
        else:
            text += "\n\n"
        for o in orders:
            oid, uid, rem, amt, price, cur, pay_m, min_a, max_a = (o[0], o[1], o[2], o[3], o[4], o[5], (o[6] or "")[:50], o[7], o[8])
            line = f"#{oid} — {format_com_amount(rem)} по {price:.4f} {cur}/COM"
            if pay_m:
                line += f" | {pay_m}"
            if min_a is not None or max_a is not None:
                line += f" | {min_a or 0}–{max_a or '∞'} {cur}"
            text += line + "\n"
        buttons = []
        for o in orders[:12]:
            oid, rem, price, cur = o[0], o[2], o[4], o[5]
            buttons.append([InlineKeyboardButton(f"#{oid} {format_com_amount(rem)} @ {price:.4f} {cur}", callback_data=f"p2p_buy_order_{oid}")])
        buttons.append(_p2p_filter_currency_row(lang, "p2p_order_book"))
        buttons.append([InlineKeyboardButton(t(lang, "back_btn"), callback_data="withdraw_p2p_menu")])
        keyboard = InlineKeyboardMarkup(buttons)
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=keyboard, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=keyboard, parse_mode="Markdown")
    bot.answer_callback_query(call.id)


def _p2p_filter_currency_row(lang, base_callback: str) -> List[InlineKeyboardButton]:
    """Ряд кнопок фильтра по валюте для книги ордеров."""
    return [
        InlineKeyboardButton("🇷🇺", callback_data=f"{base_callback}_RUB"),
        InlineKeyboardButton("🇺🇸", callback_data=f"{base_callback}_USD"),
        InlineKeyboardButton("🇺🇦", callback_data=f"{base_callback}_UAH"),
        InlineKeyboardButton("🇪🇺", callback_data=f"{base_callback}_EUR"),
        InlineKeyboardButton("💵", callback_data=f"{base_callback}_USDT"),
        InlineKeyboardButton("💎", callback_data=f"{base_callback}_TON"),
        InlineKeyboardButton(t(lang, "p2p_filter_all_btn"), callback_data=base_callback),
    ]


