@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("admin_p2p_dispute_refund_"))
@safe_handler
def admin_p2p_dispute_refund(call: CallbackQuery):
    """Админ: решение спора в пользу покупателя — возврат COM покупателю."""
    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id)
        return
    try:
        trade_id = int(call.data.replace("admin_p2p_dispute_refund_", ""))
    except ValueError:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "error_short"), show_alert=True)
        return
    with database_connection(ECONOMY_DB) as conn:
        trade = conn.execute(
            "SELECT seller_id, buyer_id, amount_com, status FROM p2p_trades WHERE id = ?",
            (trade_id,)
        ).fetchone()
        if not trade or trade[3] != "disputed":
            bot.answer_callback_query(call.id, "Сделка не в статусе спора или не найдена", show_alert=True)
            return
        seller_id, buyer_id, amount_com, _ = trade
        conn.execute("UPDATE users SET balance = balance + ? WHERE user_id = ?", (amount_com, buyer_id))
        conn.execute(
            "UPDATE p2p_trades SET status = 'dispute_refund_buyer', dispute_resolved_by = ?, dispute_resolved_at = datetime('now') WHERE id = ?",
            (call.from_user.id, trade_id)
        )
        conn.execute("INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)", (seller_id,))
        conn.execute(
            "UPDATE user_withdrawal_limits SET dispute_count = dispute_count + 1 WHERE user_id = ?",
            (seller_id,)
        )
        conn.commit()
    cache_delete(f"balance_{buyer_id}")
    try:
        bot.send_message(buyer_id, f"✅ **Спор по сделке #{trade_id} решён в вашу пользу.** COM возвращены на баланс.", parse_mode="Markdown")
    except Exception:
        pass
    try:
        bot.send_message(seller_id, f"⚠️ Спор по сделке #{trade_id} решён в пользу покупателя. COM возвращены покупателю.", parse_mode="Markdown")
    except Exception:
        pass
    bot.answer_callback_query(call.id, "COM возвращены покупателю", show_alert=True)
    try:
        bot.edit_message_text(
            f"✅ Спор #{trade_id}: решение — в пользу покупателя (COM возвращены).",
            call.message.chat.id, call.message.message_id
        )
    except Exception:
        pass


