@bot.message_handler(commands=["withdraw_status"])
@safe_handler
def cmd_withdraw_status(message: Message):
    """Статус заявок на вывод."""
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id
    with database_connection(ECONOMY_DB) as conn:
        rows = conn.execute(
            "SELECT id, amount_com, amount_fiat, currency, status, created_at FROM withdrawal_requests WHERE user_id = ? ORDER BY id DESC LIMIT 10",
            (user_id,)
        ).fetchall()
    if not rows:
        bot.reply_to(message, "📊 У вас нет заявок на вывод.")
        return
    text = "📊 **Ваши заявки на вывод**\n\n"
    for r in rows:
        rid, amt, fiat, cur, st, created = r
        text += f"#{rid} {format_com_amount(amt)} → {fiat} {cur} — {st} ({created})\n"
    bot.reply_to(message, text, parse_mode="Markdown")


@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and withdraw_state.get(m.from_user.id, {}).get("step") in ("amount_rub", "card_details", "amount_crypto", "crypto_address"))
@safe_handler
def withdraw_direct_message(message: Message):
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    state = withdraw_state.get(user_id)
    if not state:
        return
    if not message.text:
        bot.reply_to(message, "❌ Введите число текстом")
        return
    step = state.get("step")
    if step == "amount_crypto":
        try:
            amount = int(message.text.strip())
        except ValueError:
            bot.reply_to(message, "❌ Введите число")
            return
        balance = get_balance(user_id)
        limits = get_withdrawal_limits(user_id)
        daily_avail = (limits["daily_limit_com"] or 10000) - (limits["daily_used_com"] or 0)
        if amount <= 0 or amount > balance:
            bot.reply_to(message, f"❌ Недостаточно монет. Доступно: {format_com_amount(balance)}")
            return
        if amount > daily_avail:
            bot.reply_to(message, f"❌ Превышен дневной лимит вывода. Доступно сегодня: {format_com_amount(daily_avail)} COM")
            return
        with _state_lock:
            withdraw_state[user_id] = {"step": "crypto_address", "amount": amount}
        bot.reply_to(message, "₿ Введите адрес криптокошелька (USDT TRC20 или TON):")
        return
    if step == "crypto_address":
        address = message.text.strip()
        if len(address) < 10:
            bot.reply_to(message, "❌ Введите корректный адрес кошелька.")
            return
        amount = state["amount"]
        with database_connection(ECONOMY_DB) as conn:
            conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (amount, user_id))
            cur = conn.execute(
                "INSERT INTO withdrawal_requests (user_id, amount_com, currency, payment_method, payment_details, status) VALUES (?, ?, 'USDT', 'crypto', ?, 'pending')",
                (user_id, amount, address)
            )
            req_id = cur.lastrowid
            conn.execute("INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)", (user_id,))
            conn.execute(
                "UPDATE user_withdrawal_limits SET daily_used_com = daily_used_com + ? WHERE user_id = ?",
                (amount, user_id)
            )
            conn.commit()
        cache_delete(f"balance_{user_id}")
        with _state_lock:
            withdraw_state.pop(user_id, None)
        try:
            bot.send_message(
                ADMIN_CHAT_ID,
                f"₿ **Вывод на крипту**\n\n🆔 #{req_id}\n👤 {message.from_user.full_name or user_id} (ID: {user_id})\n💰 {format_com_amount(amount)} COM\n📮 Адрес: {address}",
                parse_mode="Markdown"
            )
        except Exception:
            pass
        bot.reply_to(
            message,
            f"✅ Заявка #{req_id} создана. {format_com_amount(amount)} COM → адрес {address[:12]}...\n\nОбработка до 24 ч.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(t(lang, "withdraw_status_btn"), callback_data="withdraw_status")],
                [InlineKeyboardButton(t(lang, "back_btn"), callback_data="withdraw_menu_back")]
            ]),
        )
        return
    if step == "amount_rub":
        try:
            amount = int(message.text.strip())
        except ValueError:
            bot.reply_to(message, "❌ Введите число")
            return
        balance = get_balance(user_id)
        limits = get_withdrawal_limits(user_id)
        daily_avail = (limits["daily_limit_com"] or 10000) - (limits["daily_used_com"] or 0)
        if amount <= 0:
            bot.reply_to(message, "❌ Сумма должна быть больше 0")
            return
        if amount > balance:
            bot.reply_to(message, f"❌ Недостаточно монет. Доступно: {format_com_amount(balance)}")
            return
        if amount > daily_avail:
            bot.reply_to(message, f"❌ Превышен дневной лимит. Доступно: {format_com_amount(daily_avail)} COM")
            return
        rub_amount = amount * (1 - WITHDRAW_DIRECT_FEE)
        with _state_lock:
            withdraw_state[user_id] = {"step": "card_details", "amount": amount, "rub_amount": rub_amount}
        bot.reply_to(message, f"💳 Сумма: {format_com_amount(amount)} → {rub_amount:.2f} RUB (комиссия 2%)\n\nВведите номер карты (16 цифр):")
        return
    if step == "card_details":
        card = message.text.strip().replace(" ", "")
        if len(card) < 16 or not card.isdigit():
            bot.reply_to(message, "❌ Некорректный номер карты. Введите 16+ цифр.")
            return
        amount = state["amount"]
        rub_amount = state["rub_amount"]
        with database_connection(ECONOMY_DB) as conn:
            conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (amount, user_id))
            cur = conn.execute(
                "INSERT INTO withdrawal_requests (user_id, amount_com, amount_fiat, currency, payment_method, payment_details, status) VALUES (?, ?, ?, 'RUB', 'card_rub', ?, 'pending')",
                (user_id, amount, rub_amount, card)
            )
            req_id = cur.lastrowid
            conn.execute("INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)", (user_id,))
            conn.execute(
                "UPDATE user_withdrawal_limits SET daily_used_com = daily_used_com + ? WHERE user_id = ?",
                (amount, user_id)
            )
            conn.commit()
        cache_delete(f"balance_{user_id}")
        with _state_lock:
            withdraw_state.pop(user_id, None)
        try:
            bot.send_message(
                ADMIN_CHAT_ID,
                f"💰 **Новая заявка на вывод**\n\n🆔 #{req_id}\n👤 {message.from_user.full_name or user_id} (ID: {user_id})\n💳 {format_com_amount(amount)} → {rub_amount:.2f} RUB\n📞 Карта: {card}\n⏳ {datetime.now().strftime('%d.%m.%Y %H:%M')}",
                parse_mode="Markdown"
            )
        except Exception:
            pass
        bot.reply_to(
            message,
            f"✅ **Заявка создана!**\n\n🆔 #{req_id}\n💰 Списано: {format_com_amount(amount)}\n💵 К выплате: {rub_amount:.2f} RUB\n💳 Карта: {card[:4]}****{card[-4:]}\n\n⏳ До 24 часов. Статус: /withdraw_status",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(t(lang, "withdraw_status_btn"), callback_data="withdraw_status")],
                [InlineKeyboardButton(t(lang, "back_btn"), callback_data="withdraw_menu_back")]
            ]),
            parse_mode="Markdown"
        )


