@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and withdraw_state.get(m.from_user.id, {}).get("step") == "instant_amount")
@safe_handler
def withdraw_instant_amount(message: Message):
    user_id = message.from_user.id
    state = withdraw_state.get(user_id)
    if not state or state.get("step") != "instant_amount":
        return
    if not message.text:
        bot.reply_to(message, "❌ Введите число текстом")
        return
    try:
        amount = int(message.text.strip())
    except ValueError:
        bot.reply_to(message, "❌ Введите число")
        return
    balance = get_balance(user_id)
    limits = get_withdrawal_limits(user_id)
    daily_avail = (limits["daily_limit_com"] or 10000) - (limits["daily_used_com"] or 0)
    if amount <= 0 or amount > balance:
        bot.reply_to(message, f"❌ Недостаточно монет. Доступно: {format_com_amount(balance)}")
        return
    if amount > daily_avail:
        bot.reply_to(message, f"❌ Превышен дневной лимит вывода. Доступно сегодня: {format_com_amount(daily_avail)} COM")
        with _state_lock:
            withdraw_state.pop(user_id, None)
        return
    payout = amount * INSTANT_RATE
    with _state_lock:
        withdraw_state.pop(user_id, None)
    text = (
        f"⚡ **Срочный выкуп**\n\n"
        f"💰 Продажа: {format_com_amount(amount)}\n"
        f"💵 К получению: {payout:.2f} RUB\n"
        f"📉 Комиссия за срочность: 5%\n\n"
        f"Обработка вручную администратором. Создана заявка на вывод по курсу срочного выкупа."
    )
    with database_connection(ECONOMY_DB) as conn:
        conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (amount, user_id))
        conn.execute(
            "INSERT INTO withdrawal_requests (user_id, amount_com, amount_fiat, currency, payment_method, status) VALUES (?, ?, ?, 'RUB', 'instant', 'pending')",
            (user_id, amount, payout)
        )
        conn.execute("INSERT OR IGNORE INTO user_withdrawal_limits (user_id) VALUES (?)", (user_id,))
        conn.execute(
            "UPDATE user_withdrawal_limits SET daily_used_com = daily_used_com + ? WHERE user_id = ?",
            (amount, user_id)
        )
        conn.commit()
    cache_delete(f"balance_{user_id}")
    try:
        bot.send_message(
            ADMIN_CHAT_ID,
            f"⚡ **Срочный выкуп**\n\n👤 {message.from_user.full_name or user_id} (ID: {user_id})\n💰 {format_com_amount(amount)} → {payout:.2f} RUB",
            parse_mode="Markdown"
        )
    except Exception:
        pass
    bot.reply_to(message, text, parse_mode="Markdown")


