@bot.message_handler(commands=["admin_withdrawals"])
@safe_handler
def cmd_admin_withdrawals(message: Message):
    if message.from_user.id not in DEVELOPER_IDS:
        return
    lang = get_user_language(message.from_user.id)
    with database_connection(ECONOMY_DB) as conn:
        pending = conn.execute(
            "SELECT id, user_id, amount_com, amount_fiat, currency, payment_details, created_at FROM withdrawal_requests WHERE status = 'pending' ORDER BY id ASC"
        ).fetchall()
        stats = conn.execute(
            "SELECT COUNT(*), COALESCE(SUM(amount_fiat), 0) FROM withdrawal_requests WHERE status = 'pending'"
        ).fetchone()
    total_pending, total_rub = (stats[0] or 0), (stats[1] or 0)
    text = (
        f"🔧 **Панель управления выводами**\n\n"
        f"📊 Ожидают: {total_pending} заявок\n"
        f"💵 Сумма: {total_rub:.2f} RUB\n\n**Последние заявки:**\n"
    )
    buttons = []
    for req in pending[:5]:
        rid, uid, amt, fiat, cur, details, created = req
        details_short = (details or "")[:20] + "..." if (details and len(details) > 20) else (details or "—")
        text += f"\n🆔 #{rid} | ID {uid}\n💰 {amt} COM → {fiat} {cur} | {details_short}\n⏳ {created}\n"
        buttons.append([InlineKeyboardButton(t(lang, "admin_process_btn") + f" #{rid}", callback_data=f"admin_process_withdrawal_{rid}")])
    buttons.append([InlineKeyboardButton(t(lang, "admin_refresh_btn"), callback_data="admin_refresh_withdrawals")])
    keyboard = InlineKeyboardMarkup(buttons)
    bot.reply_to(message, text, reply_markup=keyboard, parse_mode="Markdown")


