    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id)
        return
    req_id = int(call.data.replace("admin_reject_withdrawal_", ""))
    with database_connection(ECONOMY_DB) as conn:
        req = conn.execute("SELECT user_id, amount_com FROM withdrawal_requests WHERE id = ? AND status = 'pending'", (req_id,)).fetchone()
