def _pvp_only_hint(lang: str = "ru") -> str:
    return t(lang, "pvp_only_hint")


def _pvp_list_user_groups(user_id: int) -> List[Tuple[int, str]]:
    rows = execute_query(
        USERS_DB,
        # фильтруем по пользователю и, если есть колонка bot_has_admin_rights, только там где бот админ
        "SELECT chat_id, chat_title FROM bot_groups WHERE added_by_user_id = ? ORDER BY added_at DESC",
        (user_id,),
    ) or []
    out: List[Tuple[int, str]] = []
    for r in rows:
        try:
            cid = int(r[0])
            title = (r[1] or str(cid)).strip()
            out.append((cid, title))
        except Exception:
            continue
    # fallback to main chat if known
    if not out:
        try:
            main_chat = int(globals().get("CHAT_ID") or 0)
            if main_chat:
                out.append((main_chat, "Main chat"))
        except Exception:
            pass
    return out[:12]


def pvp_cancel_offer(offer_id: int, by_user_id: int) -> Tuple[bool, str]:
    """Отмена pending-оффера: только создатель. Возвращает (ok, message)."""
    pvp_expire_offers()
    with database_connection(ECONOMY_DB) as conn:
        row = conn.execute(
            "SELECT status, player1_id, player2_id, bet FROM pvp_offers WHERE id=?",
            (offer_id,),
        ).fetchone()
        if not row:
            return False, "❌ Игра не найдена"
        status, p1, p2, bet = row
        p1 = int(p1)
        if by_user_id != p1:
            return False, "❌ Отменить может только создатель"
        if status != "pending" or p2 is not None:
            return False, "⏳ Уже нельзя отменить (принято/завершено)"
        conn.execute(
            "UPDATE pvp_offers SET status='cancelled', finished_at=? WHERE id=? AND status='pending' AND player2_id IS NULL",
            (_pvp_now_ts(), offer_id),
        )
        escrow = conn.execute(
            "SELECT amount, status FROM pvp_escrow WHERE offer_id=? AND user_id=?",
            (offer_id, p1),
        ).fetchone()
        if escrow and escrow[1] == "held":
            _pvp_refund(conn, offer_id, p1, int(escrow[0] or bet or 0), f"PvP: отмена вызова — возврат ставки (оффер #{offer_id})")
        conn.commit()
    return True, "✅ Вызов отменён, ставка возвращена."


@bot.message_handler(commands=["pvp_dice"])
@safe_handler
@rate_limit(10)
def cmd_pvp_dice(message: Message):
    """PvP кости. Создаётся только в ЛС, затем публикуется в группу."""
    if message.chat.type != "private":
        lang = get_group_language(message.chat.id) or "ru"
        bot.send_message(message.chat.id, _pvp_only_hint(lang), parse_mode="Markdown")
        return
    user_id = message.from_user.id
    lang = get_user_language(user_id) or "ru"
    pvp_expire_offers()
    args = (message.text or "").split()
    if len(args) < 2:
        bot.send_message(user_id, t(lang, "pvp_dice_usage"), parse_mode="Markdown")
        return
    try:
        bet = int(args[1])
    except Exception:
        bot.send_message(user_id, "❌ Укажи числом размер ставки", parse_mode="Markdown")
        return
    try:
        offer_id = pvp_create_offer(user_id, "dice", bet, {"mode": "higher"})
    except ValueError as e:
        bot.send_message(user_id, str(e), parse_mode="Markdown")
        return
    groups = _pvp_list_user_groups(user_id)
    markup = InlineKeyboardMarkup()
    for cid, title in groups:
        markup.add(InlineKeyboardButton(f"📣 Опубликовать в: {title}", callback_data=f"pvp_post_{offer_id}_{cid}"))
    markup.add(InlineKeyboardButton("❌ Отменить", callback_data=f"pvp_cancel_{offer_id}"))
    bot.send_message(
        user_id,
        f"🎲 PvP-вызов создан (оффер #{offer_id}). Ставка {bet} {COM_EMOJI} удержана в эскроу.\n\nВыбери группу для публикации:",
        reply_markup=markup,
        parse_mode="Markdown",
    )


@bot.message_handler(commands=["pvp_coin"])
@safe_handler
@rate_limit(10)
def cmd_pvp_coin(message: Message):
    """PvP монетка. Создаётся только в ЛС, выбор стороны задаёт player1."""
    if message.chat.type != "private":
        lang = get_group_language(message.chat.id) or "ru"
        bot.send_message(message.chat.id, _pvp_only_hint(lang), parse_mode="Markdown")
        return
    user_id = message.from_user.id
    lang = get_user_language(user_id) or "ru"
    pvp_expire_offers()
    args = (message.text or "").split()
