@bot.message_handler(commands=['duel'])
@safe_handler
@rate_limit(10)
def cmd_duel(message: Message):
    """
    Команда для вызова на дуэль.
    Использование: /duel 100 3 (ответом на сообщение)
    """
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "games", message.from_user.id):
        return
    # Сообщение команды может быть автоудалено — не используем message.message_id для reply/delete
    user_id = message.from_user.id
    chat_id = message.chat.id

    if message.chat.type not in ['group', 'supergroup']:
        bot.send_message(chat_id, "❌ Дуэли доступны только в группах")
        return
    
    if not message.reply_to_message:
        text = f"""
⚔️ **ДУЭЛЬ**

**Правила:**
• Вызови противника ответом на его сообщение
• Оба кидаете кубики
• Кто первый наберёт N побед - выигрывает

**Лимиты:**
• Мин. ставка: {Duel.MIN_BET} {COM_EMOJI}
• Макс. ставка: {Duel.MAX_BET} {COM_EMOJI}
• Макс. раундов: {Duel.MAX_ROUNDS}

**Использование:** `/duel 100 3` (ответом на сообщение)
        """
        bot.send_message(chat_id, text, parse_mode="Markdown")
        return
    
    opponent = message.reply_to_message.from_user
    opponent_id = opponent.id
    
    if user_id == opponent_id:
        bot.send_message(chat_id, "❌ Нельзя вызвать на дуэль самого себя")
        return
    
    args = (message.text or "").split()
    
    try:
        bet = int(args[1]) if len(args) > 1 else 100
        max_wins = int(args[2]) if len(args) > 2 else 1
    except Exception:
        bot.send_message(chat_id, "❌ Неверные аргументы. Использование: `/duel 100 3`", parse_mode="Markdown")
        return
    
    if bet < Duel.MIN_BET:
        bot.send_message(chat_id, f"❌ Минимальная ставка: {Duel.MIN_BET} {COM_EMOJI}")
        return
    
    if bet > Duel.MAX_BET:
        bot.send_message(chat_id, f"❌ Максимальная ставка: {Duel.MAX_BET} {COM_EMOJI}")
        return
    
    if max_wins < 1 or max_wins > Duel.MAX_ROUNDS:
        bot.send_message(chat_id, f"❌ Количество побед должно быть от 1 до {Duel.MAX_ROUNDS}")
        return
    
    chall_balance = get_balance(user_id)
    opp_balance = get_balance(opponent_id)
    
    if chall_balance < bet:
        bot.send_message(chat_id, f"❌ У тебя недостаточно монет. Нужно: {bet} {COM_EMOJI}")
        return
    
    if opp_balance < bet:
        bot.send_message(chat_id, f"❌ У противника недостаточно монет. Нужно: {bet} {COM_EMOJI}")
        return
    
    duel = duel_manager.create_duel(user_id, opponent_id, bet, max_wins, chat_id=chat_id)
    
    if not duel:
        bot.send_message(chat_id, "❌ Не удалось создать дуэль")
        return
    
    _lang = get_user_language(user_id)
    markup = InlineKeyboardMarkup()
    markup.add(
        InlineKeyboardButton("✅ " + t(_lang, "duel_accept_btn"), callback_data=f"duel_accept_{duel.id}"),
        InlineKeyboardButton("❌ " + t(_lang, "duel_decline_btn"), callback_data=f"duel_decline_{duel.id}"),
    )
    
    text = f"""
⚔️ **НОВАЯ ДУЭЛЬ!** ⚔️

👤 **Вызвал:** {get_user_mention(user_id, message.from_user.first_name)}
👤 **Противник:** {get_user_mention(opponent_id, opponent.first_name)}

💰 **Ставка:** `{bet}` {COM_EMOJI}
🏆 **Побед для победы:** `{max_wins}`

⏳ **Время на принятие:** 5 минут
    """
    
    bot.send_message(
        chat_id,
        text,
        reply_markup=markup,
        parse_mode="Markdown"
    )
    
    # Сообщение команды может быть уже удалено — не вызываем delete_message

@bot.callback_query_handler(func=lambda call: call.data.startswith('duel_'))
def callback_duel(call: CallbackQuery):
    """
    Обработчик кнопок дуэлей.
    """
    chat_id = getattr(call.message, "chat", None) and getattr(call.message.chat, "id", None)
    if chat_id is not None and chat_id < 0 and not is_feature_enabled_for_chat(chat_id, "games", call.from_user.id):
        require_group_feature(chat_id, "games", call.from_user.id, from_callback=True, call=call)
        return
    try:
        data = call.data.split('_')
        if len(data) < 3:
            bot.answer_callback_query(call.id, "❌ Неверный формат")
            return
        action = data[1]
        duel_id = int(data[2])
    except (ValueError, IndexError):
        bot.answer_callback_query(call.id, "❌ Ошибка данных")
        return

    user_id = call.from_user.id
    chat_id = call.message.chat.id

    # Получаем дуэль
    duel = duel_manager.get_duel(duel_id)
    
    if not duel:
        bot.answer_callback_query(call.id, "❌ Дуэль не найдена")
        bot.edit_message_text(
            "❌ Дуэль не найдена или уже завершена",
            chat_id,
            call.message.message_id
        )
        return
    
    if action == "accept":
        # Принимаем дуэль
        can, msg = duel.can_join(user_id)
        
        if not can:
            bot.answer_callback_query(call.id, msg)
            return
        
        success, msg = duel.accept(user_id)
        
        if success:
            # Обновляем сообщение
            _lang = get_user_language(call.from_user.id)
            markup = InlineKeyboardMarkup()
            markup.add(
                InlineKeyboardButton("🎲 " + t(_lang, "duel_roll_btn"), callback_data=f"duel_roll_{duel.id}")
            )
            
            bot.edit_message_text(
                f"⚔️ **ДУЭЛЬ ПРИНЯТА!** ⚔️\n\n"
                f"👤 {get_user_mention(duel.challenger_id)} vs {get_user_mention(duel.opponent_id)}\n"
                f"💰 Ставка: {duel.bet} {COM_EMOJI}\n"
                f"🏆 Счёт: 0 : 0\n\n"
                f"Нажмите кнопку, чтобы кинуть кубик!",
                chat_id,
                call.message.message_id,
                reply_markup=markup,
                parse_mode="Markdown"
            )
            
            bot.answer_callback_query(call.id, "✅ Дуэль принята! Кидай кубик!")
        else:
            bot.answer_callback_query(call.id, msg)
    
    elif action == "decline":
        # Отклоняем дуэль
        success, msg = duel.decline(user_id)
        
        if success:
            bot.edit_message_text(
                f"❌ Дуэль отклонена",
                chat_id,
                call.message.message_id
            )
            bot.answer_callback_query(call.id, "❌ Дуэль отклонена")
            duel_manager.remove_duel(duel_id)
        else:
            bot.answer_callback_query(call.id, msg)
    
    elif action == "roll":
        # Кидаем кубик
        if duel.status != "active":
            bot.answer_callback_query(call.id, "❌ Дуэль не активна")
            return
        
        if user_id not in [duel.challenger_id, duel.opponent_id]:
            bot.answer_callback_query(call.id, "❌ Ты не участвуешь в этой дуэли")
            return
        
        roll = random.randint(1, 6)
        success, msg, round_complete = duel.roll(user_id, roll)
        
        if not success:
            bot.answer_callback_query(call.id, msg)
            return
        
        bot.answer_callback_query(call.id, f"🎲 Ты выбросил {roll}!")
        
        # Если раунд завершён, обновляем сообщение
        if round_complete:
            # Проверяем, завершена ли дуэль
            if duel.is_finished():
                winner_id, pot = duel.finish()
                
                if winner_id:
                    try:
                        winner = bot.get_chat_member(chat_id, winner_id)
                        winner_name = winner.user.first_name
                    except Exception:
                        winner_name = "Игрок"
                    
                    text = f"""
⚔️ **ДУЭЛЬ ЗАВЕРШЕНА!** ⚔️

🏆 **Победитель:** {get_user_mention(winner_id, winner_name)}
💰 **Выигрыш:** `{pot}` {COM_EMOJI}
📊 **Счёт:** {duel.challenger_wins} : {duel.opponent_wins}

🎲 **Результаты раундов:**
"""
                    
                    for i, round_result in enumerate(duel.round_results, 1):
                        text += f"\nРаунд {i}: {round_result['challenger_roll']} vs {round_result['opponent_roll']}"
                        if round_result['winner'] == "challenger":
                            text += " → 🏆"
                        elif round_result['winner'] == "opponent":
                            text += " → 🏆"
                    
                    bot.edit_message_text(
                        text,
                        chat_id,
                        call.message.message_id,
                        parse_mode="Markdown"
                    )
                    
                    duel_manager.remove_duel(duel_id)
                else:
                    # Ничья
                    bot.edit_message_text(
                        f"⚔️ **ДУЭЛЬ ЗАВЕРШЕНА!** ⚔️\n\n"
                        f"🤝 **Ничья!** Ставки возвращены.\n"
                        f"📊 **Счёт:** {duel.challenger_wins} : {duel.opponent_wins}",
                        chat_id,
                        call.message.message_id,
                        parse_mode="Markdown"
                    )
                    
                    duel_manager.remove_duel(duel_id)
            else:
                # Следующий раунд
                markup = InlineKeyboardMarkup()
                markup.add(
                    InlineKeyboardButton("🎲 " + t(get_user_language(call.from_user.id), "duel_roll_btn"), callback_data=f"duel_roll_{duel.id}")
                )
                
                bot.edit_message_text(
                    f"⚔️ **ДУЭЛЬ ПРОДОЛЖАЕТСЯ!** ⚔️\n\n"
                    f"👤 {get_user_mention(duel.challenger_id)} vs {get_user_mention(duel.opponent_id)}\n"
                    f"💰 Ставка: {duel.bet} {COM_EMOJI}\n"
                    f"🏆 Счёт: {duel.challenger_wins} : {duel.opponent_wins}\n\n"
                    f"Раунд {duel.current_round + 1}! Кидайте кубики!",
                    chat_id,
                    call.message.message_id,
                    reply_markup=markup,
                    parse_mode="Markdown"
                )
    else:
        bot.answer_callback_query(call.id, "⚠️ Неизвестное действие")

@bot.message_handler(commands=['duel_stats'])
@safe_handler
def cmd_duel_stats(message: Message):
    """
    Команда для просмотра статистики дуэлей.
    Использование: /duel_stats
    """
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "games", message.from_user.id):
        return
    user_id = message.from_user.id
    
    # Получаем статистику
    stats = get_duel_stats(user_id)
    
    if stats["total_duels"] == 0:
        text = "📭 Ты ещё не участвовал в дуэлях"
    else:
        text = f"""
⚔️ **ТВОЯ СТАТИСТИКА ДУЭЛЕЙ**

📊 **Всего дуэлей:** `{stats['total_duels']}`
🏆 **Побед:** `{stats['wins']}`
❌ **Поражений:** `{stats['losses']}`
📈 **Процент побед:** `{stats['win_rate']:.1f}%`

💰 **Общая прибыль:** `{format_number(stats['total_profit'])}` {COM_EMOJI}
📊 **Средняя ставка:** `{format_number(stats['avg_bet'])}` {COM_EMOJI}

🏅 **Лучший выигрыш:** `{format_number(stats['max_win'])}` {COM_EMOJI}
💔 **Худший проигрыш:** `{format_number(abs(stats['max_loss']))}` {COM_EMOJI}
        """
    
    msg = bot.send_message(message.chat.id, text, parse_mode="Markdown")
    
    if AUTO_DELETE_GAMES and msg:
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)


