# ============================================================================
# БРАКИ И ОТНОШЕНИЯ (как в IRIS)
# ============================================================================

def _pair(u1: int, u2: int) -> Tuple[int, int]:
    return (min(u1, u2), max(u1, u2))


# Через сколько дней после выхода из группы автоматически завершать брак и отношения (при следующем обращении к ним)
DAYS_AFTER_LEFT_TO_END_BONDS = 7
# Сколько XP отношений терять за день без активности между партнёрами
RELATIONSHIP_DECAY_PER_DAY = 5


def _cleanup_left_users_bonds(chat_id: int) -> None:
    """Завершает браки и отношения участников, которые вышли из чата более DAYS_AFTER_LEFT_TO_END_BONDS дней назад."""
    try:
        threshold = (datetime.now() - timedelta(days=DAYS_AFTER_LEFT_TO_END_BONDS)).isoformat()
        rows = execute_query(USERS_DB, "SELECT user_id, left_at FROM user_chat_left WHERE chat_id = ? AND left_at < ?", (chat_id, threshold))
        if not rows:
            return
        now = datetime.now().isoformat()
        restore_end = (datetime.now() + timedelta(days=3)).isoformat()
        for row in rows:
            uid = int(row[0])
            # Не завершаем, если пользователь снова в чате (перезашёл; запись в user_chat_left могла остаться)
            try:
                member = bot.get_chat_member(chat_id, uid)
                if getattr(member, "status", "") not in ("left", "kicked"):
                    execute_query(USERS_DB, "DELETE FROM user_chat_left WHERE user_id = ? AND chat_id = ?", (uid, chat_id))
                    continue
            except Exception:
                # Не можем проверить (ошибка API и т.д.) — не завершаем отношения, чтобы не скрыть пару по ошибке
                continue
            # Завершаем все отношения этого пользователя в этом чате
            execute_query(USERS_DB, "UPDATE relationships SET status = 'ended', ended_at = ? WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?) AND (status IS NULL OR status = 'active')", (now, chat_id, uid, uid))
            # Расторгаем все браки этого пользователя в этом чате (мягкий развод)
            marriage_rows = execute_query(USERS_DB, "SELECT user1_id, user2_id FROM marriages WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?) AND (status IS NULL OR status = 'active')", (chat_id, uid, uid))
            for m in (marriage_rows or []):
                u1, u2 = int(m[0]), int(m[1])
                execute_query(USERS_DB, "UPDATE marriages SET status = 'divorced', divorced_at = ?, restore_until = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (now, restore_end, chat_id, u1, u2))
    except Exception as e:
        logger.debug("_cleanup_left_users_bonds: %s", e)


# Уровни брака: названия по уровню (новобрачные, супруги и т.д.)
MARRIAGE_XP_PER_LEVEL = 100
MARRIAGE_LEVEL_NAMES = {
    1: ("Новобрачные", "Newlyweds"),
    2: ("Супруги", "Spouses"),
    3: ("Семья", "Family"),
    4: ("Ветераны брака", "Marriage veterans"),
    5: ("Неразлучны", "Inseparable"),
}
MARRIAGE_ACTIVITIES = [
    {"key": "dinner", "name_ru": "🍽 Совместный ужин", "name_en": "🍽 Dinner together", "cost": 100, "xp": 15},
    {"key": "flowers_m", "name_ru": "🌸 Букет супругу", "name_en": "🌸 Flowers for spouse", "cost": 150, "xp": 25},
    {"key": "date", "name_ru": "🎬 Свидание", "name_en": "🎬 Date night", "cost": 300, "xp": 50},
    {"key": "anniversary", "name_ru": "🎂 Отметить годовщину", "name_en": "🎂 Celebrate anniversary", "cost": 600, "xp": 100},
    {"key": "gift", "name_ru": "🎁 Подарок супругу", "name_en": "🎁 Gift for spouse", "cost": 1000, "xp": 150},
    {"key": "trip_m", "name_ru": "✈️ Поездка вдвоём", "name_en": "✈️ Trip together", "cost": 2000, "xp": 250},
]


def marriage_xp_to_level(experience: int) -> int:
    return max(1, 1 + (experience // MARRIAGE_XP_PER_LEVEL))


def marriage_level_name(level: int, lang: str) -> str:
    names = MARRIAGE_LEVEL_NAMES.get(level, ("Супруги", "Spouses"))
    return names[0] if lang == "ru" else names[1]


def marriage_add_xp(chat_id: int, user1_id: int, user2_id: int, xp: int, activity_key: str = "", paid_by_user_id: int = 0) -> bool:
    """Начисляет опыт паре в браке и сохраняет запись в БД (marriage_activity_log + last_activity_at)."""
    a, b = _pair(user1_id, user2_id)
    now = datetime.now().isoformat()
    try:
        execute_query(
            USERS_DB,
            "UPDATE marriages SET experience = experience + ?, last_activity_at = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
            (xp, now, chat_id, a, b),
        )
        if activity_key and paid_by_user_id:
            execute_query(
                USERS_DB,
                "INSERT INTO marriage_activity_log (chat_id, user1_id, user2_id, activity_key, xp_gained, paid_by_user_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                (chat_id, a, b, activity_key, xp, paid_by_user_id, now),
            )
        return True
    except Exception:
        return False


def _coerce_timestamp_value(val: Any) -> Optional[str]:
    """SQLite TIMESTAMP после PARSE_DECLTYPES может быть str или datetime — приводим к строке для fromisoformat."""
    if val is None:
        return None
    if isinstance(val, datetime):
        return val.isoformat(sep=" ", timespec="seconds")
    s = str(val).strip()
    return s if s else None


def _format_db_timestamp_as_date(created_at: Any) -> str:
    """Дата YYYY-MM-DD для UI (статус отношений/брака, логи). datetime нельзя резать [:10]."""
    if created_at is None:
        return "—"
    if isinstance(created_at, datetime):
        return created_at.strftime("%Y-%m-%d")
    s = str(created_at).strip()
    return s[:10] if len(s) >= 10 else (s if s else "—")


def _format_marriage_duration(created_at_str: Optional[Any], lang: str) -> str:
    """Сколько прошло с даты создания: «X дней», «Y месяцев», «Z лет»."""
    created_at_str = _coerce_timestamp_value(created_at_str)
    if not created_at_str:
        return "—"
    try:
        created = datetime.fromisoformat(created_at_str.replace("Z", "+00:00"))
        if created.tzinfo:
            created = created.replace(tzinfo=None)
    except Exception:
        return created_at_str[:10] if len(created_at_str or "") >= 10 else "—"
    delta = datetime.now() - created
    days = delta.days
    if days < 1:
        return "0 " + ("дней" if lang == "ru" else "days")
    if days < 31:
        return f"{days} " + ("дн." if lang == "ru" else "days")
    if days < 365:
        months = days // 30
        return f"{months} " + ("мес." if lang == "ru" else "mo.")
    years = days // 365
    return f"{years} " + ("лет" if lang == "ru" else "yr.")


def _marriage_duration_days(created_at_str: Optional[Any], extra_days: int = 0) -> int:
    """Число дней с даты брака + купленные (extra_days)."""
    created_at_str = _coerce_timestamp_value(created_at_str)
    if not created_at_str:
        return extra_days
    try:
        created = datetime.fromisoformat(created_at_str.replace("Z", "+00:00"))
        if created.tzinfo:
            created = created.replace(tzinfo=None)
        return max(0, (datetime.now() - created).days + extra_days)
    except Exception:
        return extra_days


def _marriage_category(created_at_str: Optional[Any], duration_days_extra: int = 0, lang: str = "ru") -> str:
    """Категория брака по сроку: Молодожёны (<1 мес), Опытные (1–6), Семейные (6–12), Ветераны (>1 года)."""
    days = _marriage_duration_days(created_at_str, duration_days_extra)
    if days < 31:
        return t(lang, "marriage_cat_newlyweds")
    if days < 31 * 6:
        return t(lang, "marriage_cat_experienced")
    if days < 365:
        return t(lang, "marriage_cat_family")
    return t(lang, "marriage_cat_veterans")


def _rp_action_key_and_xp(action: str) -> Optional[tuple]:
    """Возвращает (activity_key, xp, t_key, min_level) для РП-действия или None."""
    key = (action or "").strip().lower()
    spec = RP_ACTION_SPEC.get(key)
    if not spec:
        return None
    min_level, xp, t_key, activity_key = spec
    return (activity_key, xp, t_key, min_level)


def handle_rp_relationship_action(message: Message, action: str) -> bool:
    """
    РП-действие в чате.
    - Универсальные РП (пожать руку, обнять, поцеловать, пнуть, выебать, трахнуть и т.д.): в любой момент,
      в любого участника, без отношений; если пара в отношениях/браке — начисляется XP.
    - РП 18+ универсальные (поцеловать, выебать, трахнуть): при включённом РП 18+ в группе доступны всем на любого.
    - VIP вне отношений: при включённой настройке группы VIP может использовать любые РП (в т.ч. ужин, цветы и т.д.) на любого — без XP.
    - РП только для отношений (ужин, цветы, признание, кольцо, предложение, свадьба): только для пары с учётом уровня; иначе «нужны отношения».
    - 18+: команды с min_level >= 5 доступны только если в группе включено РП 18+.
    """
    if getattr(message.chat, "type", "") not in ("group", "supergroup"):
        return False
    _cleanup_left_users_bonds(message.chat.id)
    rp = _rp_action_key_and_xp(action)
    if not rp:
        return False
    activity_key, xp, t_key, min_level = rp
    chat_id = message.chat.id
    user_id = message.from_user.id
    gs = get_group_settings(chat_id)

    # 18+: проверка включения в группе; один раз спросить админа «Включить?» с кнопками
    if min_level >= RP_18_MIN_LEVEL and not gs.get("rp_18_enabled"):
        lang = get_user_language(user_id)
        prompt_sent = gs.get("rp_18_prompt_sent", False)
        is_admin = has_group_admin_rights(user_id, chat_id)
        if is_admin and not prompt_sent:
            # Один раз показать окошко с кнопками
            _update_group_setting_rp(chat_id, rp_18_prompt_sent=True)
            _lang = get_user_language(user_id)
            text = t(_lang, "rp18_prompt_text")
            markup = InlineKeyboardMarkup()
            markup.add(InlineKeyboardButton(t(_lang, "rp18_enable_btn"), callback_data="rp18_once_yes"))
            markup.add(InlineKeyboardButton(t(_lang, "rp18_no_btn"), callback_data="rp18_once_no"))
            bot.reply_to(message, text, reply_markup=markup, parse_mode="Markdown")
        else:
            bot.reply_to(message, t(get_user_language(user_id), "rp18_disabled"))
        return True

    # Rate limit
    if not rp_rate_limit_tracker.check_and_add(chat_id, user_id, RP_RATE_LIMIT_PER_MINUTE):
        bot.reply_to(message, t(get_user_language(user_id), "rel_rp_rate_limit"))
        return True

    target = None
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        target = message.reply_to_message.from_user
    # «Выебать @user» / «Трахнуть @user» — цель из текста сообщения
    if not target and (action or "").strip().lower() in ("выебать", "трахнуть") and getattr(message, "text", None):
        parts = (message.text or "").strip().split(maxsplit=1)
        if len(parts) >= 2 and parts[1].strip():
            username = parts[1].strip().lstrip("@")
            row = _get_user_by_username(username)
            if row and row.get("user_id"):
                try:
                    member = bot.get_chat_member(chat_id, row["user_id"])
                    if getattr(member, "user", None):
                        target = member.user
                except Exception:
                    pass
    if not target:
        lang = get_user_language(user_id)
        bot.reply_to(message, t(lang, "rel_rp_reply"))
        return True
    target_id = target.id
    if target_id == user_id:
        lang = get_user_language(user_id)
        bot.reply_to(message, t(lang, "rel_rp_self"))
        return True
    if getattr(target, "is_bot", False):
        return False
    lang = get_user_language(user_id)
    from_mention = get_user_mention(user_id, (message.from_user.first_name or "").strip() or get_user_display_name(chat_id, user_id))
    to_mention = get_user_mention(target_id, (target.first_name or "").strip() or get_user_display_name(chat_id, target_id))
    reply_to_msg = message.reply_to_message if (message.reply_to_message and message.reply_to_message.message_id) else message

    # Брак: как раньше
    marriage = _get_marriage(chat_id, user_id)
    if marriage and marriage["partner_id"] == target_id:
        marriage_add_xp(chat_id, marriage["user1_id"], marriage["user2_id"], xp, activity_key=activity_key, paid_by_user_id=user_id)
        bot.reply_to(reply_to_msg, t(lang, t_key, from_mention=from_mention, to_mention=to_mention, xp=xp), parse_mode="Markdown")
        return True

    # Отношения: проверка уровня
    rel = _get_relationship_with_partner(chat_id, user_id, target_id)
    if rel:
        level = rel.get("level", 0)
        allowed = level >= min_level or (level == 0 and min_level == 1)
        if not allowed:
            bot.reply_to(message, t(lang, "rel_rp_level_required", level=min_level, level_name=relationship_level_name(min_level, lang)))
            return True
        relationship_add_xp(chat_id, rel["user1_id"], rel["user2_id"], xp, activity_key=activity_key, paid_by_user_id=user_id)
        bot.reply_to(reply_to_msg, t(lang, t_key, from_mention=from_mention, to_mention=to_mention, xp=xp), parse_mode="Markdown")
        return True

    # Универсальные РП: можно в любого, без отношений — только текст (без XP). В т.ч. 18+ (поцеловать, выебать, трахнуть) при включённом РП 18+ в группе.
    if (action or "").strip().lower() in RP_UNIVERSAL_ACTIONS:
        text = t(lang, f"{t_key}_general", from_mention=from_mention, to_mention=to_mention)
        bot.reply_to(reply_to_msg, text, parse_mode="Markdown")
        return True

    # VIP вне отношений: при включённой настройке группы VIP может использовать любые РП (в т.ч. «только для отношений») на любого — без XP
    if min_level >= RP_VIP_OUTSIDE_MIN_LEVEL and gs.get("rp_vip_outside_enabled", True):
        vip = ItemEffects.get_vip_profile(user_id, group_id=chat_id)
        if vip and (vip.get("expires") or 0) > time.time():
            text = t(lang, f"{t_key}_general", from_mention=from_mention, to_mention=to_mention)
            bot.reply_to(reply_to_msg, text, parse_mode="Markdown")
            return True

    # Только для отношений: романтический ужин, цветы, признание, кольцо, предложение, свадьба и т.д.
    bot.reply_to(message, t(lang, "rel_rp_no_pair"))
    return True


def _get_marriage(chat_id: int, user_id: int) -> Optional[Dict]:
    """Возвращает активный брак пользователя в чате или None. Учитывает status (active/divorced)."""
    rows = execute_query(
        USERS_DB,
        """SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience,
           COALESCE(status, 'active') AS mstatus, divorced_at, restore_until, COALESCE(in_top, 0) AS in_top, COALESCE(auto_divorce, 'off') AS auto_divorce, COALESCE(duration_days, 0) AS duration_days
           FROM marriages WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?) AND (status IS NULL OR status = 'active')""",
        (chat_id, user_id, user_id),
    )
    if not rows or len(rows) == 0:
        return None
    r = rows[0]
    partner_id = r[2] if r[1] == user_id else r[1]
    experience = int(r[4]) if len(r) > 4 and r[4] is not None else 0
    level = marriage_xp_to_level(experience)
    return {
        "id": r[0], "user1_id": r[1], "user2_id": r[2], "created_at": r[3],
        "partner_id": partner_id, "experience": experience, "level": level,
        "in_top": bool(r[8]) if len(r) > 8 else False,
        "auto_divorce": (r[9] or "off") if len(r) > 9 else "off",
        "duration_days": int(r[10]) if len(r) > 10 and r[10] is not None else 0,
    }


def _apply_relationship_decay(chat_id: int, user1_id: int, user2_id: int) -> int:
    """Применяет спад опыта за дни без активности. Возвращает актуальный experience после списания."""
    a, b = _pair(user1_id, user2_id)
    rows = execute_query(USERS_DB, "SELECT experience, last_activity_at FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ? AND (status IS NULL OR status = 'active')", (chat_id, a, b))
    if rows is None:
        rows = execute_query(
            USERS_DB,
            "SELECT experience, last_activity_at FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
            (chat_id, a, b),
        )
    if not rows:
        return 0
    exp = int(rows[0][0]) if rows[0][0] is not None else 0
    last_at = rows[0][1] if len(rows[0]) > 1 else None
    if not last_at:
        return exp
    try:
        last = datetime.fromisoformat(str(last_at).replace("Z", "+00:00"))
        if last.tzinfo:
            last = last.replace(tzinfo=None)
        days = (datetime.now() - last).days
    except Exception:
        return exp
    if days <= 0:
        return exp
    decay = min(exp, days * RELATIONSHIP_DECAY_PER_DAY)
    new_exp = max(0, exp - decay)
    now = datetime.now().isoformat()
    execute_query(USERS_DB, "UPDATE relationships SET experience = ?, last_activity_at = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (new_exp, now, chat_id, a, b))
    return new_exp


def _get_relationships_list(chat_id: int, user_id: int) -> List[Dict]:
    """Список всех активных отношений пользователя в чате (с учётом спада опыта при отсутствии активности)."""
    rows = execute_query(
        USERS_DB,
        "SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience, last_activity_at, status FROM relationships WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?) AND (status IS NULL OR status = 'active')",
        (chat_id, user_id, user_id),
    )
    # execute_query при ошибке SQL возвращает None — «if not rows» ошибочно принимает это за пустой список,
    # из-за чего пользователь видит «не в отношениях» при живой записи в БД (нет колонки status и т.п.).
    if rows is None:
        rows = execute_query(
            USERS_DB,
            "SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience, last_activity_at FROM relationships WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?)",
            (chat_id, user_id, user_id),
        )
    if rows is None:
        return []
    # Fallback без фильтра status: отфильтруем ended в Python, если колонка есть
    filtered: List[Any] = []
    for r in rows:
        try:
            st = r["status"] if "status" in r.keys() else None
        except Exception:
            st = None
        if st == "ended":
            continue
        filtered.append(r)
    rows = filtered
    if not rows:
        return []
    result = []
    for r in rows:
        partner_id = r[2] if r[1] == user_id else r[1]
        experience = _apply_relationship_decay(chat_id, r[1], r[2])
        level = relationship_xp_to_level(experience)
        result.append({
            "id": r[0], "user1_id": r[1], "user2_id": r[2], "created_at": r[3],
            "partner_id": partner_id, "experience": experience, "level": level,
        })
    return result


def _get_relationship_with_partner(chat_id: int, user_id: int, partner_id: int) -> Optional[Dict]:
    """Отношения с конкретным партнёром в чате (активные), с учётом спада опыта при отсутствии активности."""
    a, b = _pair(user_id, partner_id)
    rows = execute_query(
        USERS_DB,
        "SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience, status FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ? AND (status IS NULL OR status = 'active')",
        (chat_id, a, b),
    )
    if rows is None:
        rows = execute_query(
            USERS_DB,
            "SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience, status FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
            (chat_id, a, b),
        )
    if rows is None:
        rows = execute_query(
            USERS_DB,
            "SELECT id, user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
            (chat_id, a, b),
        )
    if rows is None:
        return None
    if rows:
        try:
            st = rows[0]["status"] if "status" in rows[0].keys() else None
        except Exception:
            st = None
        if st == "ended":
            return None
    if not rows or len(rows) == 0:
        return None
    r = rows[0]
    experience = _apply_relationship_decay(chat_id, a, b)
    level = relationship_xp_to_level(experience)
    return {
        "id": r[0], "user1_id": r[1], "user2_id": r[2], "created_at": r[3],
        "partner_id": partner_id, "experience": experience, "level": level,
    }


def _get_relationship(chat_id: int, user_id: int) -> Optional[Dict]:
    """Один партнёр (для обратной совместимости): первый из списка или None."""
    lst = _get_relationships_list(chat_id, user_id)
    return lst[0] if lst else None


def _create_marriage(chat_id: int, u1: int, u2: int) -> bool:
    """Создаёт запись о браке в БД. Возвращает True только при успешной записи."""
    a, b = _pair(u1, u2)
    now = datetime.now().isoformat()
    result = execute_query(USERS_DB, "INSERT INTO marriages (chat_id, user1_id, user2_id, created_at, experience) VALUES (?, ?, ?, ?, 0)", (chat_id, a, b, now))
    return result is not None


def _delete_marriage(chat_id: int, user_id: int) -> bool:
    """Мягкое расторжение брака: status=divorced, restore_until=now+3 дня (можно восстановить)."""
    now = datetime.now().isoformat()
    restore_end = (datetime.now() + timedelta(days=3)).isoformat()
    rows = execute_query(
        USERS_DB,
        "SELECT user1_id, user2_id FROM marriages WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?) AND (status IS NULL OR status = 'active')",
        (chat_id, user_id, user_id),
    )
    if not rows:
        return False
    u1, u2 = int(rows[0][0]), int(rows[0][1])
    execute_query(
        USERS_DB,
        "UPDATE marriages SET status = 'divorced', divorced_at = ?, restore_until = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
        (now, restore_end, chat_id, u1, u2),
    )
    return True


def _create_relationship(chat_id: int, u1: int, u2: int) -> bool:
    """Создаёт запись об отношениях в БД. Возвращает True только при успешной записи."""
    a, b = _pair(u1, u2)
    now = datetime.now().isoformat()
    result = execute_query(USERS_DB, "INSERT INTO relationships (chat_id, user1_id, user2_id, created_at, experience) VALUES (?, ?, ?, ?, 0)", (chat_id, a, b, now))
    if result is not None:
        return True
    # UNIQUE(chat_id, user1_id, user2_id): пара уже есть (в т.ч. со status=ended) — реактивируем или пересоздаём
    upd = execute_query(
        USERS_DB,
        "UPDATE relationships SET status = 'active', ended_at = NULL, created_at = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?",
        (now, chat_id, a, b),
    )
    if upd is not None:
        chk = execute_query(
            USERS_DB,
            "SELECT 1 FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ? AND (status IS NULL OR status = 'active')",
            (chat_id, a, b),
        )
        if chk:
            return True
    execute_query(USERS_DB, "DELETE FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (chat_id, a, b))
    result2 = execute_query(USERS_DB, "INSERT INTO relationships (chat_id, user1_id, user2_id, created_at, experience) VALUES (?, ?, ?, ?, 0)", (chat_id, a, b, now))
    return result2 is not None


def _delete_relationship(chat_id: int, user_id: int) -> bool:
    """Удаляет все отношения пользователя в чате."""
    execute_query(USERS_DB, "DELETE FROM relationships WHERE chat_id = ? AND (user1_id = ? OR user2_id = ?)", (chat_id, user_id, user_id))
    return True


def _delete_relationship_with_partner(chat_id: int, user_id: int, partner_id: int) -> bool:
    """Расторгнуть отношения только с указанным партнёром."""
    a, b = _pair(user_id, partner_id)
    execute_query(USERS_DB, "DELETE FROM relationships WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (chat_id, a, b))
    return True


def _insert_relationship_proposal(chat_id: int, from_id: int, to_id: int) -> Optional[int]:
    """Создаёт запись в relationship_proposals и возвращает id. Совместимо с SQLite без RETURNING."""
    now = datetime.now().isoformat()
    rows = execute_query(
        USERS_DB,
        "INSERT INTO relationship_proposals (chat_id, from_id, to_id, created_at) VALUES (?, ?, ?, ?) RETURNING id",
        (chat_id, from_id, to_id, now),
    )
    if rows and len(rows) > 0:
        return int(rows[0][0])
    if rows is not None:
        return None
    try:
        with database_connection(USERS_DB) as conn:
            cur = conn.execute(
                "INSERT INTO relationship_proposals (chat_id, from_id, to_id, created_at) VALUES (?, ?, ?, ?)",
                (chat_id, from_id, to_id, now),
            )
            conn.commit()
            return cur.lastrowid
    except Exception as e:
        logger.error("_insert_relationship_proposal: %s", e)
        return None


