def _rp_commands_for_level(level: int) -> Set[str]:
    """Возвращает множество РП-команд (ключей RP_ACTION_SPEC), доступных на данном уровне и ниже."""
    out: Set[str] = set()
    for cmd, spec in RP_ACTION_SPEC.items():
        if spec[0] <= level:
            out.add(cmd)
    return out


def relationship_xp_to_level(experience: int) -> int:
    """Уровень отношений по опыту: 0 XP -> 0, 150+ -> 1, 1500+ -> 2, ... 10M+ -> 11."""
    level = 0
    for L in range(1, len(RELATIONSHIP_LEVEL_XP)):
        if experience >= RELATIONSHIP_LEVEL_XP[L]:
            level = L
    return level


def relationship_xp_for_next_level(level: int) -> int:
    """Сколько всего XP нужно для перехода на следующий уровень (нижняя граница)."""
    if level >= 11:
        return RELATIONSHIP_LEVEL_XP[11]
    return RELATIONSHIP_LEVEL_XP[level + 1]
