def _resolve_target_user_from_message(message: Message):
    """Цель из ответа на сообщение или из упоминания (text_mention) в message.entities."""
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        return message.reply_to_message.from_user
    for ent in (getattr(message, "entities", None) or []):
        if getattr(ent, "type", None) == "text_mention" and getattr(ent, "user", None):
            return ent.user
    return None


# Стоимость продления брака за 1 день (монеты)
MARRIAGE_EXTEND_COST_PER_DAY = 10


