@bot.message_handler(commands=['marry_extend', 'брак_продлить'])
@safe_handler
def cmd_marry_extend(message: Message):
    """Брак продлить <дни> — продлить срок брака за монеты."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    marriage = _get_marriage(chat_id, user_id)
    if not marriage:
        bot.reply_to(message, t(lang, "marry_single"))
        return
    parts = (message.text or "").strip().split()
    days = None
    for i, p in enumerate(parts):
        if i > 0 and p.isdigit():
            days = min(365, max(1, int(p)))
            break
    if days is None:
        bot.reply_to(message, t(lang, "marry_extend_usage", cost_per_day=MARRIAGE_EXTEND_COST_PER_DAY, sign=COM_EMOJI))
        return
    cost = days * MARRIAGE_EXTEND_COST_PER_DAY
    if not remove_coins(user_id, cost, reason="marriage_extend", admin_id=None):
        bot.reply_to(message, t(lang, "marry_extend_no_coins", cost=cost, sign=COM_EMOJI))
        return
    a, b = _pair(marriage["user1_id"], marriage["user2_id"])
    now = datetime.now().isoformat()
    execute_query(USERS_DB, "UPDATE marriages SET duration_days = COALESCE(duration_days, 0) + ?, last_extended = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (days, now, chat_id, a, b))
    bot.reply_to(message, t(lang, "marry_extend_ok", days=days, cost=cost, sign=COM_EMOJI))


@bot.message_handler(commands=['marry_auto_divorce', 'брак_режим_развода'])
@safe_handler
def cmd_marry_auto_divorce(message: Message):
    """Брак режим развода один|два|выключить."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    marriage = _get_marriage(chat_id, user_id)
    if not marriage:
        bot.reply_to(message, t(lang, "marry_single"))
        return
    text = (message.text or "").strip().lower()
    mode = None
    for word in text.split():
        if word in ("один", "one", "1"):
            mode = "one"
            break
        if word in ("два", "two", "2"):
            mode = "two"
            break
        if word in ("выключить", "off", "отключить"):
            mode = "off"
            break
    if mode is None:
        bot.reply_to(message, t(lang, "marry_auto_divorce_usage"))
        return
    a, b = _pair(marriage["user1_id"], marriage["user2_id"])
    execute_query(USERS_DB, "UPDATE marriages SET auto_divorce = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (mode, chat_id, a, b))
    if mode == "off":
        bot.reply_to(message, t(lang, "marry_auto_divorce_off"))
    else:
        bot.reply_to(message, t(lang, "marry_auto_divorce_set", mode=mode))


