def _resolve_two_users_from_message(message: Message) -> List[Any]:
    """Два пользователя из ответов или упоминаний (text_mention) для админ-команд «Поженить пару» / «Развести пару»."""
    users: List[Any] = []
    seen: Set[int] = set()
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        u = message.reply_to_message.from_user
        if u.id not in seen and not getattr(u, "is_bot", False):
            users.append(u)
            seen.add(u.id)
    for ent in (getattr(message, "entities", None) or []):
        if getattr(ent, "type", None) == "text_mention" and getattr(ent, "user", None):
            u = ent.user
            if u.id not in seen and not getattr(u, "is_bot", False):
                users.append(u)
                seen.add(u.id)
    return users[:2]


@bot.message_handler(func=lambda m: m.text and m.chat.type in ("group", "supergroup") and (
    m.text.strip().lower().startswith("поженить пару") or m.text.strip().lower().startswith("!поженить пару")))
@safe_handler
def cmd_admin_marry_pair(message: Message):
    """Админ: Поженить пару @user1 @user2."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    if not has_group_admin_rights(user_id, chat_id):
        bot.reply_to(message, t(lang, "marry_admin_denied"))
        return
    two = _resolve_two_users_from_message(message)
    if len(two) < 2:
        bot.reply_to(message, t(lang, "marry_admin_need_two"))
        return
    u1, u2 = two[0].id, two[1].id
    if u1 == u2:
        bot.reply_to(message, t(lang, "marry_self"))
        return
    a, b = _pair(u1, u2)
    if _get_marriage(chat_id, u1) or _get_marriage(chat_id, u2):
        bot.reply_to(message, t(lang, "marry_target_married"))
        return
    now = datetime.now().isoformat()
    execute_query(USERS_DB, "INSERT INTO marriages (chat_id, user1_id, user2_id, created_at, experience) VALUES (?, ?, ?, ?, 0)", (chat_id, a, b, now))
    bot.reply_to(message, t(lang, "marry_admin_married_ok", u1=get_user_mention(u1), u2=get_user_mention(u2)), parse_mode="Markdown")


