@bot.message_handler(func=lambda m: m.text and m.chat.type in ("group", "supergroup") and (
    (m.text.strip().lower() == "!развести вышедших") or (m.text.strip().lower() == "развести вышедших")))
@safe_handler
def cmd_admin_divorce_left(message: Message):
    """Админ: !Развести вышедших — расторгнуть браки участников, покинувших чат."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    if not has_group_admin_rights(user_id, chat_id):
        bot.reply_to(message, t(lang, "marry_admin_denied"))
        return
    rows = execute_query(USERS_DB, "SELECT user1_id, user2_id FROM marriages WHERE chat_id = ? AND (status IS NULL OR status = 'active')", (chat_id,))
    divorced = 0
    now = datetime.now().isoformat()
    restore_end = (datetime.now() + timedelta(days=3)).isoformat()
    for row in (rows or []):
        u1, u2 = int(row[0]), int(row[1])
        try:
            m1 = bot.get_chat_member(chat_id, u1)
            m2 = bot.get_chat_member(chat_id, u2)
        except Exception:
            continue
        s1 = getattr(m1, "status", "") or ""
        s2 = getattr(m2, "status", "") or ""
        if s1 in ("left", "kicked") or s2 in ("left", "kicked"):
            a, b = _pair(u1, u2)
            execute_query(USERS_DB, "UPDATE marriages SET status = 'divorced', divorced_at = ?, restore_until = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (now, restore_end, chat_id, a, b))
            divorced += 1
    bot.reply_to(message, t(lang, "marry_admin_left_divorced", count=divorced))


@bot.message_handler(commands=['marriages', 'браки', 'пары'])
@safe_handler
def cmd_marriages(message: Message):
    """Список пар в этом чате: уровень и сколько в браке."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    _cleanup_left_users_bonds(chat_id)
    lang = get_user_language(message.from_user.id)
    rows = execute_query(USERS_DB, "SELECT user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience, COALESCE(duration_days, 0) AS duration_days FROM marriages WHERE chat_id = ? AND (status IS NULL OR status = 'active') ORDER BY experience DESC, created_at", (chat_id,))
    if not rows:
        bot.reply_to(message, t(lang, "marry_no_couples"))
        return
    lines = []
    for i, row in enumerate(rows, 1):
        u1, u2 = int(row[0]), int(row[1])
        created = row[2]
        exp = int(row[3]) if len(row) > 3 and row[3] is not None else 0
        extra_days = int(row[4]) if len(row) > 4 and row[4] is not None else 0
        level = marriage_xp_to_level(exp)
        level_name = marriage_level_name(level, lang)
        date_str = _format_db_timestamp_as_date(created)
        duration = _format_marriage_duration(created, lang)
        category = _marriage_category(created, extra_days, lang)
        lines.append(f"{i}. {get_user_mention(u1)} 💒 {get_user_mention(u2)} — {category}, {level_name} ({date_str}, {duration})")
    bot.reply_to(message, t(lang, "marry_list_header") + "\n" + "\n".join(lines), parse_mode="Markdown")


@bot.callback_query_handler(func=lambda c: c.data == "marriage_activity_menu")
@safe_handler
def callback_marriage_activity_menu(call: CallbackQuery):
    """Меню совместных действий в браке."""
    if not ensure_call_access(call, require_group=True):
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    marriage = _get_marriage(chat_id, user_id)
