    for act in MARRIAGE_ACTIVITIES:
        name = act["name_ru"] if lang == "ru" else act["name_en"]
        label = f"{name} — {act['cost']} {COM_EMOJI} (+{act['xp']} XP)"
        markup.add(InlineKeyboardButton(label, callback_data=f"marriage_do_{act['key']}"))
    markup.add(InlineKeyboardButton(t(lang, "marry_history_btn"), callback_data="marriage_history"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="marriage_activity_back"))
