@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("rel_activity_menu"))
@safe_handler
def callback_rel_activity_menu(call: CallbackQuery):
    """Меню совместных действий с выбранным партнёром (кафе, подарки и т.д.)."""
    if not ensure_call_access(call, require_group=True):
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    data = call.data or ""
    if "_" in data and data.replace("rel_activity_menu_", "").isdigit():
        partner_id = int(data.replace("rel_activity_menu_", ""))
    else:
        bot.answer_callback_query(call.id, "❌")
        return
    rel = _get_relationship_with_partner(chat_id, user_id, partner_id)
    if not rel:
        bot.answer_callback_query(call.id, t(lang, "rel_single"))
        return
    rel_level = int(rel.get("level", 0) or 0)
    balance = get_balance(user_id)
    name_me = get_user_display_name_in_chat(user_id, chat_id, get_user_display_name(chat_id, user_id, lang))
    name_partner = get_user_display_name_in_chat(partner_id, chat_id, get_user_display_name(chat_id, partner_id, lang))
    header = t(lang, "rel_activity_list_header", me=name_me, partner=name_partner)
    coin_suffix = t(lang, "rel_activity_coin_suffix")
    acts_sorted = sorted(RELATIONSHIP_ACTIVITIES, key=lambda x: -int(x.get("cost", 0) or 0))
    lines: List[str] = []
    for act in acts_sorted:
        tr = act["title_ru"] if lang == "ru" else act["title_en"]
        em = _rel_activity_row_emoji(rel_level, balance, act)
        xp_s = _format_rel_xp_short(int(act.get("xp", 0) or 0))
        cost_s = format_number(int(act.get("cost", 0) or 0))
        lines.append(f"{em} «{tr}» {xp_s}, {cost_s} {coin_suffix}")
    body = header + "\n\n" + "\n".join(lines) + "\n\n" + t(lang, "rel_activity_rp_unlock_lines") + "\n\n" + t(lang, "rel_activity_footer_hint")
    markup = InlineKeyboardMarkup(row_width=1)
    for act in acts_sorted:
        title_short = (act["title_ru"] if lang == "ru" else act["title_en"])[:28]
        ok = _rel_activity_row_available(rel_level, balance, act)
        prefix = "✅ " if ok else "🕔 "
        label = f"{prefix}{title_short} · {act['cost']}{COM_EMOJI}"
        if len(label) > 64:
            label = label[:61] + "…"
        markup.add(InlineKeyboardButton(label, callback_data=f"rel_do_{act['key']}_{partner_id}"))
    markup.add(InlineKeyboardButton(t(lang, "rel_history_btn"), callback_data=f"rel_history_{partner_id}"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="rel_activity_back"))
    bot.edit_message_text(body, chat_id, call.message.message_id, reply_markup=markup, parse_mode=None)
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("rel_do_"))
@safe_handler
def callback_rel_do_activity(call: CallbackQuery):
    """Совершить совместное действие с выбранным партнёром (списать монеты, начислить XP этой паре)."""
    if not ensure_call_access(call, require_group=True):
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    parts = (call.data or "").replace("rel_do_", "").split("_")
    if len(parts) < 2:
        bot.answer_callback_query(call.id, "❌")
        return
    key = parts[0]
    try:
        partner_id = int(parts[1])
    except (ValueError, IndexError):
        bot.answer_callback_query(call.id, "❌")
        return
    rel = _get_relationship_with_partner(chat_id, user_id, partner_id)
    if not rel:
        bot.answer_callback_query(call.id, t(lang, "rel_single"))
        return
    activity = next((a for a in RELATIONSHIP_ACTIVITIES if a["key"] == key), None)
    if not activity:
        bot.answer_callback_query(call.id, "❌")
        return
    rel_level = int(rel.get("level", 0) or 0)
    balance = get_balance(user_id)
    if not _rel_activity_row_available(rel_level, balance, activity):
        bot.answer_callback_query(call.id, t(lang, "rel_activity_locked"), show_alert=True)
        return
    cost = activity["cost"]
    xp = activity["xp"]
    if not remove_coins(user_id, cost, reason=f"rel_activity:{key}", admin_id=None):
        bot.answer_callback_query(call.id, t(lang, "rel_activity_no_coins", cost=cost, sign=COM_EMOJI))
        return
    if not relationship_add_xp(chat_id, rel["user1_id"], rel["user2_id"], xp, activity_key=key, paid_by_user_id=user_id):
        add_coins(user_id, cost, "Возврат: ошибка начисления XP в отношениях")
        bot.answer_callback_query(call.id, t(lang, "rel_save_error"))
        return
    rel_updated = _get_relationship_with_partner(chat_id, user_id, partner_id)
    level = rel_updated.get("level", 1)
    exp = rel_updated.get("experience", 0)
    done_text = _build_rel_activity_done_message(
        lang, chat_id, user_id, partner_id, activity, xp, level, exp
    )
    bot.edit_message_text(done_text, chat_id, call.message.message_id, parse_mode=None)
    bot.answer_callback_query(call.id, f"+{xp} XP 💕")


@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("rel_history_"))
@safe_handler
def callback_rel_history(call: CallbackQuery):
    """Показать историю действий с партнёром (в духе Ирис)."""
    if not ensure_call_access(call, require_group=True):
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    data = (call.data or "").replace("rel_history_", "").strip()
    try:
        partner_id = int(data)
    except ValueError:
        bot.answer_callback_query(call.id, "❌")
        return
    rel = _get_relationship_with_partner(chat_id, user_id, partner_id)
    if not rel:
        bot.answer_callback_query(call.id, t(lang, "rel_single"))
        return
    a, b = rel["user1_id"], rel["user2_id"]
    log = _get_relationship_activity_log(chat_id, a, b, limit=15)
    lines = []
    for key, xp, created_at in log:
        act = next((x for x in RELATIONSHIP_ACTIVITIES if x["key"] == key), None)
        if act:
            name = act["name_ru"] if lang == "ru" else act["name_en"]
        elif key in RELATIONSHIP_ACTIVITIES_LEGACY_NAMES:
            name = RELATIONSHIP_ACTIVITIES_LEGACY_NAMES[key][0] if lang == "ru" else RELATIONSHIP_ACTIVITIES_LEGACY_NAMES[key][1]
        else:
            rp = RELATIONSHIP_RP_DISPLAY.get(key) or ("—", "—")
            name = rp[0] if lang == "ru" else rp[1]
        date_str = _format_db_timestamp_as_date(created_at)
        lines.append(f"• {name} (+{xp} XP) — {date_str}")
    title = t(lang, "rel_history_title")
    text = title + "\n\n" + ("\n".join(lines) if lines else t(lang, "rel_history_empty"))
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="rel_activity_back"))
    bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    bot.answer_callback_query(call.id)


