@bot.message_handler(commands=['breakup', 'расстаться'])
@safe_handler
def cmd_breakup(message: Message):
    """Прекратить отношения с одним человеком: ответь на его сообщение и вызови /breakup."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    if not message.reply_to_message or not message.reply_to_message.from_user:
        bot.reply_to(message, t(lang, "rel_breakup_reply"))
        return
    partner_id = message.reply_to_message.from_user.id
    if partner_id == user_id:
        bot.reply_to(message, t(lang, "rel_breakup_self"))
        return
    rel = _get_relationship_with_partner(chat_id, user_id, partner_id)
    if not rel:
        bot.reply_to(message, t(lang, "rel_breakup_not_together"))
        return
    _delete_relationship_with_partner(chat_id, user_id, partner_id)
    bot.reply_to(message, t(lang, "rel_breakup"))


@bot.message_handler(commands=['relations', 'отношения_список', 'отны'])
@safe_handler
def cmd_relations(message: Message):
    """Список пар в отношениях в этом чате."""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    _cleanup_left_users_bonds(chat_id)
    lang = get_user_language(message.from_user.id)
    rows = execute_query(USERS_DB, "SELECT user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience FROM relationships WHERE chat_id = ? AND (status IS NULL OR status = 'active') ORDER BY experience DESC, created_at", (chat_id,))
    if rows is None:
        # Запрос мог упасть из-за отсутствия колонки status (старая БД) — берём все пары в чате
        rows = execute_query(USERS_DB, "SELECT user1_id, user2_id, created_at, COALESCE(experience, 0) AS experience FROM relationships WHERE chat_id = ? ORDER BY experience DESC, created_at", (chat_id,)) or []
    if not rows:
        bot.reply_to(message, t(lang, "rel_no_couples"))
        return
    lines = []
    for i, row in enumerate(rows, 1):
        u1, u2 = int(row[0]), int(row[1])
        created = row[2]
        exp = int(row[3]) if len(row) > 3 and row[3] is not None else 0
        level = relationship_xp_to_level(exp)
        date_str = _format_db_timestamp_as_date(created)
        name1 = get_user_display_name_in_chat(u1, chat_id, get_user_display_name(chat_id, u1, lang))
        name2 = get_user_display_name_in_chat(u2, chat_id, get_user_display_name(chat_id, u2, lang))
        lines.append(f"{i}. {get_user_mention(u1, name1, lang=lang)} 💕 {get_user_mention(u2, name2, lang=lang)} — {t(lang, 'rel_level_short', level=level)} ({date_str})")
    bot.reply_to(message, t(lang, "rel_list_header") + "\n" + "\n".join(lines), parse_mode="Markdown")


@bot.message_handler(commands=['rp_commands', 'рп_команды'])
@safe_handler
def cmd_rp_commands(message: Message):
    """Список РП: универсальные (на любого) и только для отношений (по уровням)."""
    if not ensure_user_access(message):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    is_group = getattr(message.chat, "type", "") in ("group", "supergroup")
    lines = []
    # Универсальные РП — без отношений; список разделён на русские и английские команды
    def _is_cyrillic(s: str) -> bool:
        return any("\u0400" <= c <= "\u04FF" for c in s)
    universal_ru = sorted(c for c in RP_UNIVERSAL_ACTIONS if _is_cyrillic(c))
    universal_en = sorted(c for c in RP_UNIVERSAL_ACTIONS if not _is_cyrillic(c))
    lines.append(t(lang, "rp_universal_header"))
    if universal_ru:
        lines.append(t(lang, "rp_universal_ru_label") + " " + ", ".join(universal_ru[:25]) + ("..." if len(universal_ru) > 25 else ""))
    if universal_en:
        lines.append(t(lang, "rp_universal_en_label") + " " + ", ".join(universal_en[:25]) + ("..." if len(universal_en) > 25 else ""))
    lines.append("")
    lines.append(t(lang, "rp_vip_outside"))
    lines.append("")
    lines.append(t(lang, "rp_only_relations_header"))
    if is_group:
        rels = _get_relationships_list(chat_id, user_id)
        max_level = max((r.get("level", 0) for r in rels), default=0)
        if max_level > 0:
            lines.append(t(lang, "rel_rp_commands_your_level", level=max_level, level_name=relationship_level_name(max_level, lang)))
        else:
            lines.append(t(lang, "rel_rp_commands_no_rel"))
    else:
        lines.append(t(lang, "rel_rp_commands_private"))
    lines.append("")
    for lev in range(1, 12):
        xp_req = RELATIONSHIP_LEVEL_XP[lev] if lev < len(RELATIONSHIP_LEVEL_XP) else 0
        name = relationship_level_name(lev, lang)
        cmds = [c for c, spec in RP_ACTION_SPEC.items() if spec[0] == lev and c not in RP_UNIVERSAL_ACTIONS]
        if not cmds:
            continue
        uniq = list(dict.fromkeys(cmds))
        lines.append(t(lang, "rp_level_line", lev=lev, name=name, xp_req=format_number(xp_req)) + " " + ", ".join(uniq[:15]) + ("..." if len(uniq) > 15 else ""))
    lines.append("")
    lines.append(t(lang, "rel_marry_at_level6", level=MARRIAGE_MIN_RELATIONSHIP_LEVEL, level_name=relationship_level_name(MARRIAGE_MIN_RELATIONSHIP_LEVEL, lang), xp_req=format_number(RELATIONSHIP_LEVEL_XP[MARRIAGE_MIN_RELATIONSHIP_LEVEL])))
    lines.append("")
    lines.append(t(lang, "rel_rp_commands_hint"))
    bot.reply_to(message, "\n".join(lines), parse_mode="Markdown")


# ---------- Callback: одноразовый запрос «Включить РП 18+?» (при первой 18+ команде) ----------

@bot.callback_query_handler(func=lambda call: call.data == "rp18_once_yes")
@safe_handler
def cb_rp18_once_yes(call: CallbackQuery):
    """Включить РП 18+ по кнопке из одноразового запроса."""
    if not call.message or not call.message.chat or call.message.chat.id >= 0:
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id
    if not has_group_admin_rights(call.from_user.id, chat_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    _update_group_setting_rp(chat_id, rp_18_enabled=True, rp_18_confirmed_at=datetime.now().isoformat())
    lang = get_group_language(chat_id) or get_user_language(call.from_user.id)
    bot.answer_callback_query(call.id, t(lang, "rp18_enabled"))
    try:
        me = bot.get_me()
        bot_username = getattr(me, "username", None) or "bot"
        rp_markup = InlineKeyboardMarkup()
        rp_markup.add(InlineKeyboardButton(t(lang, "go_to_dm_btn"), url=f"https://t.me/{bot_username}?start=group_setup_{chat_id}"))
        rp_text = ("✅ **РП 18+ включены** в этой группе. " if lang == "ru" else "✅ **RP 18+ enabled** in this group. ") + t(lang, "rp18_settings_hint")
        bot.edit_message_text(
            rp_text,
            call.message.chat.id, call.message.message_id, parse_mode="Markdown",
            reply_markup=rp_markup,
        )
    except Exception:
        pass


@bot.callback_query_handler(func=lambda call: call.data == "rp18_once_no")
@safe_handler
def cb_rp18_once_no(call: CallbackQuery):
    """Отказ от включения РП 18+ по одноразовому запросу."""
    if not call.message or not call.message.chat:
        bot.answer_callback_query(call.id)
        return
    group_chat_id = call.message.chat.id
    lang = get_group_language(group_chat_id) or get_user_language(call.from_user.id)
    bot.answer_callback_query(call.id, t(lang, "ok_short"))
    try:
        me = bot.get_me()
        bot_username = getattr(me, "username", None) or "bot"
        rp_markup = InlineKeyboardMarkup()
        rp_markup.add(InlineKeyboardButton(t(lang, "go_to_dm_btn"), url=f"https://t.me/{bot_username}?start=group_setup_{group_chat_id}"))
        rp_no_text = ("🔞 РП 18+ остаются выключенными. " if lang == "ru" else "🔞 RP 18+ remain disabled. ") + t(lang, "rp18_off_can_enable")
        bot.edit_message_text(
            rp_no_text,
            call.message.chat.id, call.message.message_id,
            reply_markup=rp_markup,
        )
    except Exception:
        pass


