# КОМАНДЫ МАГАЗИНА
# ============================================================================

def _send_shop_items_message(
    chat_id: int,
    user_id: int,
    lang: str,
    edit_message_id: Optional[int] = None,
    page: Optional[int] = None,
) -> None:
    """Отправляет или редактирует сообщение с товарами магазина. Используется после выбора группы или при открытии без групп."""
    items = ShopManager.get_all_items()
    if not items:
        if edit_message_id:
            try:
                bot.edit_message_text(t(lang, "shop_empty"), chat_id, edit_message_id, parse_mode="Markdown")
            except Exception:
                bot.send_message(chat_id, t(lang, "shop_empty"), parse_mode="Markdown")
        else:
            bot.send_message(chat_id, t(lang, "shop_empty"), parse_mode="Markdown")
        return
    balance = get_balance(user_id)
    balance_str = format_amount_for_user(user_id, balance)
    markup = InlineKeyboardMarkup(row_width=1)
    def _shop_item_display(it: object) -> Tuple[str, str]:
        """Best-effort: ensure item name/description are English when lang='en'."""
        if (lang or "").strip().lower() != "en":
            return getattr(it, "name", ""), getattr(it, "description", "")

        itype = getattr(it, "type", None)
        data = getattr(it, "data", None) or {}
        # Known default items from ShopManager.init_default_items()
        if itype == "vip":
            days = int(data.get("duration") or 0)
            if days == 30:
                name = "👑 VIP (1 month)"
                desc = "VIP status in the group for 30 days: +1 coin per message, +15% to daily, -50% transfer tax. Works only in the group where you bought it."
            elif days == 90:
                name = "👑 VIP (3 months)"
                desc = "VIP status in the group for 90 days with a discount. Works only in the group where you bought it."
            elif days == 180:
                name = "👑 VIP (6 months)"
                desc = "VIP status in the group for 180 days — half a year of privileges. Works only in the group where you bought it."
            elif days == 365:
                name = "👑 VIP (1 year)"
                desc = "VIP status in the group for a full year! Maximum benefits. Works only in the group where you bought it."
            else:
                name = "👑 VIP"
                desc = "VIP status in the group. Works only in the group where you bought it."
            return name, desc

        if itype == "luck":
            mn = int(data.get("min") or 0)
            mx = int(data.get("max") or 0)
            if mn == 10 and mx == 100:
                return "🎁 Secret gift", "A random prize from 10 to 100 coins (most often around 50, sometimes higher)."
            if mn == 100 and mx == 500:
                return "🎁 Big gift", "A random prize from 100 to 500 coins (most often around 200, sometimes higher)."
            return "🎁 Gift", "A random prize."

        if itype == "unwarn":
            return "🛡️ Remove warning", "Removes one warning."

        if itype == "mute_protection":
            hours = int(data.get("duration") or 0)
            return "🔇 Mute protection", f"Protects against mute for {hours} hours."

        if itype == "double_daily":
            return "✨ Double daily", "Your next daily bonus will be x2."

        if itype == "xp_boost":
            hours = int(data.get("duration") or 0)
            mult = int(data.get("multiplier") or 2)
            return "⚡ XP boost", f"x{mult} coins per message for {hours} hours."

        if itype == "legend":
            return "💎 Legendary status", "Forever in the group chat history — a special role. Works only in the group where you bought it."

        if itype == "ad":
            return "📢 Advertising", "Submit an advertising request for the chat."

        if itype == "custom_title":
            return "📝 Custom title", "Set a custom title for yourself."

        if itype == "color_nick":
            return "🌈 Color nick", "Change your nickname color."

        if itype == "custom_color":
            return "🎨 Custom color", "Set your custom nickname color."

        if itype == "gift":
            return "🎁 Gift", "A random prize."

        # Generic safe fallback (avoid leaking Russian admin-entered text in EN mode)
        return "🛒 Shop item", "—"

    total_items = len(items)
    page_size = max(1, int(SHOP_PAGE_SIZE))
    total_pages = max(1, (total_items + page_size - 1) // page_size)
    cur_page = _shop_page_by_user.get(user_id, 0) if page is None else int(page)
    if cur_page < 0:
        cur_page = 0
    if cur_page >= total_pages:
        cur_page = total_pages - 1
    _shop_page_by_user[user_id] = cur_page
    start = cur_page * page_size
    end = start + page_size
    page_items = items[start:end]

    for item in page_items:
        if getattr(item, "type", None) == "vip" and item.stock == -1:
            stock_text = ""
        else:
            stock_text = t(lang, "shop_stock_count", count=item.stock) if item.stock > 0 else t(lang, "shop_stock_infinite") if item.stock == -1 else t(lang, "shop_stock_none")
        price_str = format_amount_for_user(user_id, item.price)
        item_name, _item_desc = _shop_item_display(item)
        button_text = f"{item_name} - {price_str}{stock_text}"
        markup.add(InlineKeyboardButton(button_text, callback_data=f"shop_buy_{item.id}"))
    if total_pages > 1:
        nav_row = []
        if cur_page > 0:
            nav_row.append(InlineKeyboardButton("⬅️", callback_data=f"shop_page_prev_{cur_page}"))
        nav_row.append(InlineKeyboardButton(f"{cur_page + 1}/{total_pages}", callback_data="shop_page_noop"))
        if cur_page < total_pages - 1:
            nav_row.append(InlineKeyboardButton("➡️", callback_data=f"shop_page_next_{cur_page}"))
        markup.row(*nav_row)
    markup.add(InlineKeyboardButton(t(lang, "shop_close_btn"), callback_data="shop_close"))
    markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
    cur = currency_manager.get_user_currency(user_id)
    currency_hint = (f"\n💱 Цены в {cur}. /currency — изменить." if lang == "ru" else f"\n💱 Prices in {cur}. /currency to change.")
    group_note = ""
    gid = _shop_selected_group.get(user_id)
    if gid:
        group_note = (
            "\n📍 Purchase for the group (part of the amount goes to the group treasury).\n"
            if (lang or "").strip().lower() == "en"
            else "\n📍 Покупка для группы (часть суммы пойдёт в казну группы).\n"
        )
    text = (
        f"{t(lang, 'shop_title')}\n\n"
        f"{t(lang, 'shop_your_balance')} {balance_str}{currency_hint}{group_note}\n"
        f"{t(lang, 'shop_available')}\n"
        f"\n📄 {cur_page + 1}/{total_pages}"
    )
    for item in page_items:
        if getattr(item, "type", None) == "vip" and item.stock == -1:
            stock_text = ""
        else:
            stock_text = t(lang, "shop_stock_in", stock=item.stock) if item.stock > 0 else t(lang, "shop_stock_infinite") if item.stock == -1 else t(lang, "shop_stock_none")
        price_str = format_amount_for_user(user_id, item.price)
        item_name, item_desc = _shop_item_display(item)
        text += f"\n\n**{item_name}**{stock_text}\n{t(lang, 'shop_desc')} {item_desc}\n{t(lang, 'shop_price')} {price_str}"
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id, edit_message_id, reply_markup=markup, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
    else:
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")


@bot.message_handler(commands=['shop', 'kom_shop'])
@safe_handler
@require_category("shop")
def cmd_shop(message: Message):
    """
    Команда для открытия магазина. Если у пользователя есть группы — сначала выбор группы (покупка привязана к группе, % в казну).
    """
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "shop", message.from_user.id):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    register_user(user_id)
    lang = get_user_language(user_id)

    items = ShopManager.get_all_items()
    if not items:
        bot.reply_to(message, t(lang, "shop_empty"), parse_mode="Markdown")
        return

    groups = get_groups_added_by_user(user_id)
    if groups:
        _shop_page_by_user[user_id] = 0
        markup = InlineKeyboardMarkup(row_width=1)
        for gid, title, _ in groups[:15]:
            if title:
                name = str(title)[:40]
            else:
                name = (f"Group {gid}" if (lang or "").strip().lower() == "en" else f"Группа {gid}")[:40]
            markup.add(InlineKeyboardButton(f"👥 {name}", callback_data=f"shop_group_{gid}"))
        markup.add(InlineKeyboardButton("🛒 Без группы (глобально)" if lang == "ru" else "🛒 No group (global)", callback_data="shop_group_0"))
        markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
        bot.send_message(
            message.chat.id,
            "👥 **Выберите группу для покупки**\n\nПокупка для группы: VIP и товары привязаны к группе, часть суммы идёт в казну группы." if lang == "ru" else "👥 **Choose group for purchase**\n\nPurchase for group: VIP is per group, part of the sum goes to group treasury.",
            reply_markup=markup,
            parse_mode="Markdown",
        )
        return

    _shop_selected_group[user_id] = None
    _shop_page_by_user[user_id] = 0
    _send_shop_items_message(message.chat.id, user_id, lang, page=0)
    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)


@bot.message_handler(commands=["cancel"])
@safe_handler
def cmd_cancel(message: Message):
    """
    Global cancel: best-effort exit from in-memory FSM states and temporary inputs.
    Useful when a user is stuck in a step expecting numeric/text input and other commands get intercepted.
    """
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id if message.from_user else 0
    lang = get_user_language(user_id) if user_id else "ru"
    with _state_lock:
        try:
            p2p_state.pop(user_id, None)
        except Exception:
            pass
        try:
            withdraw_state.pop(user_id, None)
        except Exception:
            pass
    try:
        clear_temp_data(user_id)
    except Exception:
        pass
    try:
        bot.reply_to(message, t(lang, "cancel") or ("✅ Отменено." if lang == "ru" else "✅ Cancelled."), parse_mode="Markdown")
    except Exception:
        try:
            bot.send_message(message.chat.id, t(lang, "cancel") or ("✅ Отменено." if lang == "ru" else "✅ Cancelled."))
        except Exception:
            pass


@bot.message_handler(commands=['inventory', 'inv'])
@safe_handler
def cmd_inventory(message: Message):
    """Показывает инвентарь пользователя."""
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    items = InventoryManager.get_user_inventory(user_id, include_used=False, include_expired=False)

    if not items:
        bot.reply_to(message, t(lang, "inventory_empty"), parse_mode="Markdown")
        return

    markup = InlineKeyboardMarkup(row_width=1)
    text = ("🎒 **YOUR INVENTORY**\n\n" if lang == "en" else "🎒 **ТВОЙ ИНВЕНТАРЬ**\n\n")

    def _inventory_item_display(it: object) -> str:
        if lang != "en":
            return getattr(it, "name", "")
        itype = getattr(it, "type", None)
        data = getattr(it, "data", None) or {}
        if itype == "vip":
            days = int(data.get("duration") or 0)
            if days == 30:
                return "👑 VIP (1 month)"
            if days == 90:
                return "👑 VIP (3 months)"
            if days == 180:
                return "👑 VIP (6 months)"
            if days == 365:
                return "👑 VIP (1 year)"
            return "👑 VIP"
        if itype == "luck":
            mn = int(data.get("min") or 0)
            mx = int(data.get("max") or 0)
            if mn == 10 and mx == 100:
                return "🎁 Secret gift"
            if mn == 100 and mx == 500:
                return "🎁 Big gift"
            return "🎁 Gift"
        if itype == "unwarn":
            return "🛡️ Remove warning"
        if itype == "mute_protection":
            return "🔇 Mute protection"
        if itype == "double_daily":
            return "✨ Double daily"
        if itype == "xp_boost":
            return "⚡ XP boost"
        if itype == "legend":
            return "💎 Legendary status"
        if itype == "ad":
            return "📢 Advertising"
        if itype == "custom_title":
            return "📝 Custom title"
        if itype == "color_nick":
            return "🌈 Color nick"
        if itype == "custom_color":
            return "🎨 Custom color"
        if itype == "gift":
            return "🎁 Gift"
        return "🛒 Shop item"

    for inv in items[:30]:
        item = inv.item
        expires_text = ""
        if inv.expires:
            expires_text = (
                f" (until {inv.expires.strftime('%d.%m.%Y %H:%M')})"
                if lang == "en"
                else f" (до {inv.expires.strftime('%d.%m.%Y %H:%M')})"
            )
        item_name = _inventory_item_display(item)
        text += f"• **{item_name}**{expires_text}\n"
        markup.add(
            InlineKeyboardButton(
                t(lang, "shop_use_item_btn", name=item_name),
                callback_data=f"use_{inv.inventory_id}",
            )
        )

    msg = bot.send_message(message.chat.id, text, reply_markup=markup, parse_mode="Markdown")
    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)


def process_custom_color(message: Message):
    """Обрабатывает ввод HEX-цвета для предмета custom_color."""
    user_id = message.from_user.id
    inv_id = get_temp_data(user_id, "custom_color_item")
    color = (message.text or "").strip()

    if not inv_id:
        bot.reply_to(message, "❌ Сессия истекла, открой инвентарь заново.")
        return

    if not re.match(r"^#[0-9A-Fa-f]{6}$", color):
        bot.reply_to(message, "❌ Неверный формат. Пример: `#FF0000`", parse_mode="Markdown")
        return

    ItemEffects.apply_color_nick(user_id, color=color, duration=30)
    execute_query(
        ECONOMY_DB,
        "UPDATE inventory SET used=1, used_date=? WHERE id=?",
        (datetime.now(), inv_id),
    )
    clear_temp_data(user_id, "custom_color_item")
    bot.reply_to(message, f"✅ Цвет ника сохранён: `{color}`", parse_mode="Markdown")


def process_custom_title(message: Message):
    """Обрабатывает ввод кастомного титула."""
    user_id = message.from_user.id
    inv_id = get_temp_data(user_id, "custom_title_item")
    title = (message.text or "").strip()

    if not inv_id:
        bot.reply_to(message, "❌ Сессия истекла, открой инвентарь заново.")
        return

    if not title:
        bot.reply_to(message, "❌ Титул не может быть пустым.")
        return

    ItemEffects.apply_custom_title(user_id, title, duration=7)
    execute_query(
        ECONOMY_DB,
        "UPDATE inventory SET used=1, used_date=? WHERE id=?",
        (datetime.now(), inv_id),
    )
    clear_temp_data(user_id, "custom_title_item")
    bot.reply_to(message, f"✅ Титул установлен: {title}")

@bot.callback_query_handler(func=lambda call: call.data.startswith('shop_'))
def callback_shop(call: CallbackQuery):
    """
    Обработчик кнопок магазина (покупки и админ-панель).
    """
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    data = call.data
    
    # ===== АДМИН-ПАНЕЛЬ (НОВЫЕ ФУНКЦИИ) =====
    if data == "shop_list_items":
        shop_list_items(call)
        return
    
    elif data == "shop_stats":
        shop_stats(call)
        return
    
    elif data == "shop_add_item":
        shop_add_item(call)
        return
    
    elif data.startswith('shop_list_next_'):
        shop_list_next(call)
        return
    
    elif data.startswith('shop_list_prev_'):
        shop_list_prev(call)
        return
    
    elif data.startswith('shop_edit_') and not any([
        data.startswith('shop_edit_name_'),
        data.startswith('shop_edit_desc_'),
        data.startswith('shop_edit_price_'),
        data.startswith('shop_edit_stock_')
    ]):
        shop_edit_item(call)
        return
    
    elif data.startswith('shop_edit_name_'):
        shop_edit_name(call)
        return
    
    elif data.startswith('shop_edit_desc_'):
        shop_edit_desc(call)
        return
    
    elif data.startswith('shop_edit_price_'):
        shop_edit_price(call)
        return
    
    elif data.startswith('shop_quick_price_'):
        shop_quick_price(call)
        return
    
    elif data.startswith('shop_custom_price_'):
        shop_custom_price(call)
        return
    
    elif data.startswith('shop_edit_stock_'):
        shop_edit_stock(call)
        return
    
    elif data.startswith('shop_delete_'):
        shop_delete_item(call)
        return
    
    elif data.startswith('shop_confirm_delete_'):
        shop_confirm_delete(call)
        return
    
    # ===== ВЫБОР ГРУППЫ ДЛЯ ПОКУПКИ =====
    if data.startswith('shop_group_'):
        try:
            gid_str = data.replace('shop_group_', '')
            gid = int(gid_str)
        except ValueError:
            bot.answer_callback_query(call.id)
            return
        user_id = call.from_user.id
        _shop_selected_group[user_id] = gid if gid != 0 else None
        _shop_page_by_user[user_id] = 0
        lang = get_user_language(user_id)
        _send_shop_items_message(call.message.chat.id, user_id, lang, edit_message_id=call.message.message_id, page=0)
        bot.answer_callback_query(call.id)
        return

    if data == "shop_page_noop":
        bot.answer_callback_query(call.id)
        return

    if data.startswith("shop_page_prev_") or data.startswith("shop_page_next_"):
        user_id = call.from_user.id
        lang = get_user_language(user_id)
        try:
            cur_page = int(data.rsplit("_", 1)[-1])
        except Exception:
            cur_page = _shop_page_by_user.get(user_id, 0)
        target_page = cur_page - 1 if data.startswith("shop_page_prev_") else cur_page + 1
        _send_shop_items_message(
            call.message.chat.id,
            user_id,
            lang,
            edit_message_id=call.message.message_id,
            page=target_page,
        )
        bot.answer_callback_query(call.id)
        return

    # ===== ПОДТВЕРЖДЕНИЕ ПОКУПКИ =====
    if data.startswith('shop_confirm_buy_'):
        item_id = int(data.replace('shop_confirm_buy_', ''))
        user_id = call.from_user.id
        group_id = _shop_selected_group.get(user_id)
        success, msg, inv_item = buy_item(user_id, item_id, group_id=group_id)
        shop_lang = get_user_language(user_id)
        bot.answer_callback_query(call.id, t(shop_lang, "shop_bought_ok") if success else msg)
        if success:
            try:
                bot.delete_message(call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            class TempMessage:
                def __init__(self, original):
                    self.chat = original.chat
                    self.from_user = original.from_user
                    self.message_id = original.message_id
                    self.text = "/shop"
                    self.chat.id = original.chat.id
            temp_msg = TempMessage(call.message)
            cmd_shop(temp_msg)
            bot.send_message(call.message.chat.id, msg, parse_mode="Markdown")
        return

    # ===== ВОЗВРАТ В СПИСОК ТОВАРОВ (с экрана подтверждения) =====
    if data == "shop_back_to_list":
        user_id = call.from_user.id
        register_user(user_id)
        shop_lang = get_user_language(user_id)
        _send_shop_items_message(
            call.message.chat.id,
            user_id,
            shop_lang,
            edit_message_id=call.message.message_id,
            page=_shop_page_by_user.get(user_id, 0),
        )
        bot.answer_callback_query(call.id)
        return

    # ===== ПОКУПКИ: показ подтверждения =====
    parts = data.split('_')
    if len(parts) < 2:
        shop_lang = get_user_language(call.from_user.id) if getattr(call, 'from_user', None) else "ru"
        bot.answer_callback_query(call.id, t(shop_lang, "shop_unknown_action"))
        return
    action = parts[1]
    
    if action == "buy":
        if len(parts) < 3:
            shop_lang = get_user_language(call.from_user.id) if getattr(call, 'from_user', None) else "ru"
            bot.answer_callback_query(call.id, t(shop_lang, "shop_item_not_found"))
            return
        try:
            item_id = int(parts[2])
        except (ValueError, TypeError):
            shop_lang = get_user_language(call.from_user.id) if getattr(call, 'from_user', None) else "ru"
            bot.answer_callback_query(call.id, t(shop_lang, "shop_item_not_found"))
            return
        user_id = call.from_user.id
        item = ShopManager.get_item(item_id)
        if not item:
            shop_lang = get_user_language(user_id)
            bot.answer_callback_query(call.id, t(shop_lang, "shop_item_not_found"))
            return
        balance = get_balance(user_id)
        shop_lang = get_user_language(user_id)
        if getattr(item, "type", None) == "vip" and item.stock == -1:
            stock_text = ""
        else:
            stock_text = t(shop_lang, "shop_stock_in", stock=item.stock) if item.stock > 0 else t(shop_lang, "shop_stock_infinite") if item.stock == -1 else t(shop_lang, "shop_stock_none_alt")
        desc_line = f"\n{t(shop_lang, 'shop_desc')} {item.description}\n" if (item.description and item.description.strip()) else ""
        confirm_text = (
            t(shop_lang, "shop_confirm_title")
            + f"**{item.name}**{stock_text}\n"
            + desc_line
            + f"{t(shop_lang, 'shop_price')} **{item.price}** {COM_EMOJI}\n"
            f"{t(shop_lang, 'shop_confirm_balance')} **{format_number(balance)}** {COM_EMOJI}\n\n"
            + t(shop_lang, "shop_confirm_confirm")
        )
        markup = InlineKeyboardMarkup(row_width=1)
        markup.add(InlineKeyboardButton(t(shop_lang, "shop_confirm_btn"), callback_data=f"shop_confirm_buy_{item_id}"))
        markup.add(InlineKeyboardButton(t(shop_lang, "shop_cancel_btn"), callback_data="shop_back_to_list"))
        bot.answer_callback_query(call.id)
        bot.edit_message_text(
            confirm_text,
            call.message.chat.id,
            call.message.message_id,
            reply_markup=markup,
            parse_mode="Markdown",
        )
        return
    
    elif action == "close":
        # Закрыть магазин → в личке главное меню; в группе — быстрые кнопки (не send_start_panel: там текст «перейди в ЛС» для админов)
        user_id = call.from_user.id
        chat_id = call.message.chat.id
        chat_type = getattr(call.message.chat, "type", "private")
        clear_temp_data(user_id)
        lang = get_user_language(user_id)
        if chat_type == "private":
            bot.answer_callback_query(call.id, t(lang, "shop_to_menu"))
            try:
                bot.delete_message(chat_id, call.message.message_id)
            except Exception:
                pass
            send_start_panel(chat_id, user_id, lang, chat_type)
        elif chat_type in ("group", "supergroup"):
            bot.answer_callback_query(call.id, t(lang, "shop_to_menu"))
            _show_group_quick_menu_in_message(call, answer_callback=False)
        else:
            bot.answer_callback_query(call.id, t(lang, "shop_to_menu"))
            try:
                bot.delete_message(chat_id, call.message.message_id)
            except Exception:
                pass
    else:
        shop_lang = get_user_language(call.from_user.id)
        bot.answer_callback_query(call.id, "⚠️ " + t(shop_lang, "shop_unknown_action"))

# ============================================================================
# КОМАНДЫ ДОСТИЖЕНИЙ
# ============================================================================

@bot.message_handler(commands=['achievements', 'ach'])
@safe_handler
def cmd_achievements(message: Message):
    """
    Команда для просмотра достижений.
    Использование: /achievements
    """
    if not ensure_user_access(message):
        return
    try_delete_message(message.chat.id, message.message_id)
    user_id = message.from_user.id
    
    # Получаем достижения пользователя
    user_achs = get_user_achievements(user_id)
    
    # Получаем статистику
    stats = get_user_stats(user_id)

    lang = get_user_language(user_id)

    if (lang or "").strip().lower() == "en":
        text = f"🏆 **Your achievements**\n\n"
        text += f"📊 **Progress:** {len(user_achs)}/{len(achievements)}\n\n"
        if user_achs:
            text += "**Earned:**\n"
            for ach in user_achs[:10]:
                text += f"• {ach.get('icon', '🏆')} **{ach['name']}** - {ach['desc']}\n"
                if ach.get("earned_date"):
                    date_str = ach["earned_date"][:10] if isinstance(ach["earned_date"], str) else str(ach["earned_date"])[:10]
                    text += f"  🗓️ {date_str}\n"
        else:
            text += "📭 **No achievements**\n\nPlay games, earn coins and get achievements!"

        text += f"\n💰 **Balance:** `{format_number(get_balance(user_id))}` {COM_EMOJI}"
        text += f"\n🎮 **Games played:** `{stats['games_played']}`"
        text += f"\n🏆 **Wins:** `{stats['games_won']}`"
    else:
        text = f"🏆 **ТВОИ ДОСТИЖЕНИЯ**\n\n"
        text += f"📊 **Прогресс:** {len(user_achs)}/{len(achievements)}\n\n"
        if user_achs:
            text += "**Получены:**\n"
            for ach in user_achs[:10]:
                text += f"• {ach.get('icon', '🏆')} **{ach['name']}** - {ach['desc']}\n"
                if ach.get("earned_date"):
                    date_str = ach["earned_date"][:10] if isinstance(ach["earned_date"], str) else str(ach["earned_date"])[:10]
                    text += f"  🗓️ {date_str}\n"
        else:
            text += "📭 **Нет достижений**\n\nИграй в игры, зарабатывай монеты и получай достижения!"

        text += f"\n💰 **Баланс:** `{format_number(get_balance(user_id))}` {COM_EMOJI}"
        text += f"\n🎮 **Игр сыграно:** `{stats['games_played']}`"
        text += f"\n🏆 **Побед:** `{stats['games_won']}`"

    msg = bot.reply_to(message, text, parse_mode="Markdown")
    
    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)


def _build_group_quick_menu_markup(lang: str) -> InlineKeyboardMarkup:
    """Кнопки быстрого меню в группе (как у приветствия нового участника)."""
    welcome_markup = InlineKeyboardMarkup(row_width=2)
    telegraph_url = get_telegraph_commands_url(lang)
    if telegraph_url:
        welcome_markup.add(
            InlineKeyboardButton("📄 " + t(lang, "menu_commands"), url=telegraph_url),
        )
    welcome_markup.add(
        InlineKeyboardButton(t(lang, "menu_help"), callback_data="group_welcome_help"),
        InlineKeyboardButton(t(lang, "menu_balance"), callback_data="group_welcome_balance"),
        InlineKeyboardButton(t(lang, "menu_daily"), callback_data="group_welcome_daily"),
        InlineKeyboardButton(t(lang, "menu_shop"), callback_data="group_welcome_shop"),
        InlineKeyboardButton(t(lang, "menu_faq"), callback_data="group_welcome_faq"),
    )
    return welcome_markup


def _show_group_quick_menu_in_message(call: CallbackQuery, *, answer_callback: bool = True) -> None:
    """В группе: быстрые кнопки вместо главного меню из ЛС (кнопка «В меню» из магазина и т.д.)."""
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    msg_id = call.message.message_id
    group_lang = get_group_language(chat_id) or get_user_language(user_id)
    text = (
        t(group_lang, "group_welcome_hi") + "\n\n"
        + t(group_lang, "group_welcome_quick") + "\n\n"
        + t(group_lang, "group_welcome_full_list")
    )
    markup = _build_group_quick_menu_markup(group_lang)
    try:
        bot.edit_message_text(
            text,
            chat_id=chat_id,
            message_id=msg_id,
            reply_markup=markup,
            parse_mode="Markdown",
        )
    except Exception:
        try:
            bot.delete_message(chat_id, msg_id)
        except Exception:
            pass
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
    if answer_callback:
        bot.answer_callback_query(call.id)


def _show_main_menu_in_message(call: CallbackQuery) -> None:
    """Редактирует сообщение (или отправляет новое) на главное меню. В группе — быстрые кнопки (не ЛС-меню)."""
    ctype = getattr(call.message.chat, "type", "")
    if ctype in ("group", "supergroup"):
        _show_group_quick_menu_in_message(call)
        return
    if ctype != "private":
        bot.answer_callback_query(call.id)
        return
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    lang = get_user_language(user_id)
    name = getattr(call.from_user, "first_name", None) if call.from_user else None
    text = get_greeting(user_id, lang, name=name)
    text += "\n" + get_balance_widget(user_id, lang)
    text += "\n\n" + t(lang, "choose_action")
    keyboard = build_main_menu_keyboard(user_id, lang)
    try:
        bot.edit_message_text(
            text,
            chat_id=chat_id,
            message_id=msg_id,
            reply_markup=keyboard,
            parse_mode="Markdown",
        )
    except Exception:
        try:
            bot.delete_message(chat_id, msg_id)
        except Exception:
            pass
        bot.send_message(chat_id, text, reply_markup=keyboard, parse_mode="Markdown")
    bot.answer_callback_query(call.id)


def _is_donation_rating_callback(call: CallbackQuery) -> bool:
    d = (call.data or "").strip()
    return (
        d == "rating" or d == "rating_current" or d == "main_menu"
        or d.startswith("rating_page_")
        or d.startswith("group_stats_")
        or d.startswith("donate_")
        or d.startswith("group_chart_")
        or d.startswith("group_inventory_")
    )


@bot.callback_query_handler(func=lambda c: c.data and _is_donation_rating_callback(c))
@safe_handler
def callback_donation_rating(call: CallbackQuery):
    """Обработчик кнопок: рейтинг групп, статистика группы, донат (меню, сумма, подтверждение)."""
    data = (call.data or "").strip()
    # Возврат в главное меню — без проверки подписки, чтобы кнопка «Назад» работала из любого экрана
    if data == "main_menu" or data == "rating_current":
        _show_main_menu_in_message(call)
        return
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    lang = get_user_language(user_id)

    if data == "rating":
        send_rating_page(chat_id, user_id, 1)
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return

    if data.startswith("rating_page_"):
        try:
            page = int(data.replace("rating_page_", ""))
        except ValueError:
            page = 1
        send_rating_page(chat_id, user_id, page)
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return

    if data.startswith("group_stats_"):
        try:
            gid = int(data.replace("group_stats_", ""))
        except ValueError:
            bot.answer_callback_query(call.id, t(lang, "rating_error"))
            return
        stats = get_group_donation_stats(gid)
        if not stats:
            bot.answer_callback_query(call.id, t(lang, "rating_group_not_found"), show_alert=True)
            return
        g = stats["group"]
        xp_unit = t(lang, "group_xp_unit")
        text = (
            f"📊 **{t(lang, 'group_stats_title')}**\n\n"
            f"👥 {g['group_name'] or t(lang, 'group_default_name')}\n"
            f"⚡ {t(lang, 'group_xp_label')}: **{g.get('group_xp', g['total_donations'])}** {xp_unit}\n"
            f"🏆 {t(lang, 'rating_position_label')}: {g['rating_position'] or '—'}\n\n"
            f"🏅 **{t(lang, 'top_donators_title')}:**\n"
        )
        for i, d in enumerate(stats["top_donators"][:10], 1):
            uid = d["user_id"]
            display_name = get_user_display_name_in_chat(uid, gid, get_user_display_name(gid, uid))
            name = get_user_mention(uid, display_name) or f"User {uid}"
            text += f"{i}. {name} — {d['total_donated']} {COM_EMOJI}\n"
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "btn_donate"), callback_data=f"donate_menu_{gid}"))
        markup.add(InlineKeyboardButton(t(lang, "btn_chart"), callback_data=f"group_chart_{gid}"))
        markup.add(InlineKeyboardButton(t(lang, "btn_group_inventory"), callback_data=f"group_inventory_{gid}"))
        markup.add(InlineKeyboardButton(t(lang, "btn_back_to_rating"), callback_data="rating"))
        try:
            bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        bot.answer_callback_query(call.id)
        return

    if data.startswith("group_chart_"):
        try:
            gid = int(data.replace("group_chart_", ""))
        except ValueError:
            bot.answer_callback_query(call.id, "❌")
            return
        stats = get_group_donation_stats(gid)
        if not stats or not stats.get("history"):
            bot.answer_callback_query(call.id, t(lang, "no_chart_data"), show_alert=True)
            return
        xp_unit = t(lang, "group_xp_unit")
        lines = [f"📈 {t(lang, 'group_xp_label')} {t(lang, 'chart_xp_by_days')}:\n"]
        for h in stats["history"][:14]:
            lines.append(f"  {h['date']}: {h['total_donations']} {xp_unit}")
        try:
            bot.edit_message_text("\n".join(lines), chat_id, call.message.message_id, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, "\n".join(lines), parse_mode="Markdown")
        bot.answer_callback_query(call.id)
        return

    if data.startswith("group_inventory_"):
        try:
            gid = int(data.replace("group_inventory_", ""))
        except ValueError:
            bot.answer_callback_query(call.id, t(lang, "rating_error"))
            return
        items = get_group_inventory_list(gid)
        if not items:
            text = f"🛒 **{t(lang, 'group_inventory_title')}**\n\n{t(lang, 'group_inventory_empty')}"
        else:
            text = f"🛒 **{t(lang, 'group_inventory_title')}**\n\n"
            for i, it in enumerate(items[:25], 1):
                mention = get_user_mention(it["user_id"]) or f"ID{it['user_id']}"
                used = " ✓" if it["used"] else ""
                date_str = str(it.get("purchase_date") or "")[:10]
                text += f"{i}. {mention} — {it.get('item_name', '?')}{used} ({date_str})\n"
            if len(items) > 25:
                text += "\n" + t(lang, "and_more", count=len(items) - 25)
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "back_btn"), callback_data=f"group_stats_{gid}"))
        try:
            bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        bot.answer_callback_query(call.id)
        return

    if data.startswith("donate_menu_"):
        try:
            gid = int(data.replace("donate_menu_", ""))
        except ValueError:
            bot.answer_callback_query(call.id, "❌")
            return
        register_user(user_id)
        balance = get_balance(user_id)
        balance_str = format_amount_for_user(user_id, balance)
        text = f"💸 **{t(lang, 'donate_menu_title')}**\n\n{t(lang, 'balance_label_short')}: {balance_str}\n\n{t(lang, 'choose_amount')}:"
        markup = InlineKeyboardMarkup()
        for amt in [50, 100, 500, 1000]:
            amt_str = format_amount_for_user(user_id, amt)
            markup.add(InlineKeyboardButton(amt_str, callback_data=f"donate_{gid}_{amt}"))
        markup.add(InlineKeyboardButton(t(lang, "custom_amount"), callback_data=f"donate_custom_{gid}"))
        markup.add(InlineKeyboardButton(t(lang, "back_btn"), callback_data=f"group_stats_{gid}"))
        try:
            bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        bot.answer_callback_query(call.id)
        return

    if data.startswith("donate_custom_"):
        try:
            gid = int(data.replace("donate_custom_", ""))
        except ValueError:
            bot.answer_callback_query(call.id, "❌")
            return
        bot.answer_callback_query(call.id, t(lang, "donate_custom_hint"))
        return

    if data.startswith("donate_confirm_"):
        parts = data.split("_")
        if len(parts) != 4:
            bot.answer_callback_query(call.id, "❌")
            return
        try:
            gid = int(parts[2])
            amount = int(parts[3])
        except (ValueError, IndexError):
            bot.answer_callback_query(call.id, "❌")
            return
        if amount < DONATE_MIN_AMOUNT or amount > DONATE_MAX_AMOUNT:
            bot.answer_callback_query(call.id, t(lang, "invalid_amount"), show_alert=True)
            return
        key = user_id
        now_ts = time.time()
        if key in _donate_last_time and (now_ts - _donate_last_time[key]) < DONATE_COOLDOWN_SEC:
            bot.answer_callback_query(call.id, "⏳ " + t(lang, "wait_seconds", sec=DONATE_COOLDOWN_SEC), show_alert=True)
            return
        ok, err = donations_do_donate(user_id, gid, amount, "")
        if ok:
            _donate_last_time[key] = now_ts
            group_xp = get_group_xp(gid)
            xp_unit = t(lang, "group_xp_unit")
            try:
                bot.send_message(
                    gid,
                    "🎉 " + t(lang, "user_donated_to_group", name=call.from_user.full_name or "—", amount=f"{amount} {COM_EMOJI}") + f"\n⚡ {t(lang, 'group_xp_label')}: {group_xp} {xp_unit}",
                )
            except Exception:
                pass
            amount_str = format_amount_for_user(user_id, amount)
            bot.answer_callback_query(call.id, "✅ " + t(lang, "donate_success_toast", amount=amount_str), show_alert=True)
            stats = get_group_donation_stats(gid)
            if stats:
                g = stats["group"]
                text = f"📊 **{t(lang, 'group_stats_title')}**\n\n👥 {g['group_name'] or t(lang, 'group_default_name')}\n⚡ {t(lang, 'group_xp_label')}: **{g.get('group_xp', g['total_donations'])}** {xp_unit}\n\n🏅 **{t(lang, 'top_donators_title')}:**\n"
                for i, d in enumerate(stats["top_donators"][:10], 1):
                    uid = d["user_id"]
                    display_name = get_user_display_name_in_chat(uid, gid, get_user_display_name(gid, uid))
                    name = get_user_mention(uid, display_name) or f"User {uid}"
                    text += f"{i}. {name} — {d['total_donated']} {COM_EMOJI}\n"
                markup = InlineKeyboardMarkup()
                markup.add(InlineKeyboardButton(t(lang, "btn_donate"), callback_data=f"donate_menu_{gid}"))
                markup.add(InlineKeyboardButton(t(lang, "btn_back_to_rating"), callback_data="rating"))
                try:
                    bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
                except Exception:
                    pass
        else:
            bot.answer_callback_query(call.id, f"❌ {err}", show_alert=True)
        return

    if data.startswith("donate_"):
        parts = data.split("_")
        if len(parts) != 3:
            bot.answer_callback_query(call.id)
            return
        try:
            gid = int(parts[1])
            amount = int(parts[2])
        except (ValueError, IndexError):
            bot.answer_callback_query(call.id, "❌")
            return
        if amount < DONATE_MIN_AMOUNT:
            bot.answer_callback_query(call.id, t(lang, "min_coins_donate", min=DONATE_MIN_AMOUNT), show_alert=True)
            return
        balance = get_balance(user_id)
        if balance < amount:
            bot.answer_callback_query(call.id, t(lang, "insufficient_balance_short", balance=balance), show_alert=True)
            return
        text = t(lang, "confirm_donate_prompt", amount=f"{amount} {COM_EMOJI}")
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "confirm_btn"), callback_data=f"donate_confirm_{gid}_{amount}"))
        markup.add(InlineKeyboardButton(t(lang, "cancel_btn"), callback_data=f"group_stats_{gid}"))
        try:
            bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
        except Exception:
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        bot.answer_callback_query(call.id)
        return


