@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("lang_set_"))
@safe_handler
def callback_lang_set(call: CallbackQuery):
    """Установка языка по кнопке. В личке — стартовая панель; в группе — только подтверждение, без перехода в меню управления."""
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    chat_type = getattr(call.message.chat, "type", "private")
    if chat_type in ("group", "supergroup") and not is_chat_owner(user_id, chat_id):
        bot.answer_callback_query(call.id, t(get_user_language(user_id), "groupadmin_only_owner")[:50], show_alert=True)
        return
    register_user(user_id)
    update_user_info(user_id, call.from_user)
    if call.data == "lang_set_en":
        set_user_language(user_id, "en")
        msg = t("en", "lang_changed_en")
    else:
        set_user_language(user_id, "ru")
        msg = t("ru", "lang_changed")
    bot.answer_callback_query(call.id, msg[:50])
    try:
        bot.edit_message_text(msg, chat_id, call.message.message_id)
    except Exception:
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
    clear_temp_data(user_id)
    if chat_type == "private":
        lang = get_user_language(user_id)
        send_start_panel(chat_id, user_id, lang, chat_type)


