def send_mygroups_panel(chat_id: int, user_id: int, lang: str, reply_to_message_id: Optional[int] = None) -> None:
    """Отправляет панель «Мои группы»: список групп, куда пользователь добавил бота, и кнопки перехода. Используется в /mygroups и при /start group_setup."""
    groups = get_groups_added_by_user(user_id)
    text = t(lang, "mygroups_text")
    if groups:
        text += "\n\n" + t(lang, "mygroups_list_header") + "\n"
        lines = [f"• {g_title}" for _, g_title, _ in groups[:30]]
        text += "\n".join(lines)
        markup = InlineKeyboardMarkup(row_width=1)
        for g_chat_id, g_title, _ in groups[:10]:
            try:
                chat = bot.get_chat(g_chat_id)
                uname = getattr(chat, "username", None)
                if uname:
                    markup.add(InlineKeyboardButton(f"🛡 {g_title[:50]}", url=f"https://t.me/{uname}"))
            except Exception:
                pass
        markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
        bot.send_message(
            chat_id, text, parse_mode="Markdown",
            reply_markup=markup,
            reply_to_message_id=reply_to_message_id,
        )
    else:
        empty_markup = InlineKeyboardMarkup()
        empty_markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))
        bot.send_message(
            chat_id, text + "\n\n" + t(lang, "mygroups_no_groups"), parse_mode="Markdown",
            reply_markup=empty_markup,
            reply_to_message_id=reply_to_message_id,
        )


