@bot.message_handler(commands=['donate', 'kom_donate'])
@safe_handler
def cmd_donate(message: Message):
    """Донат в текущую группу: /donate [сумма] или /donate (выбор суммы кнопками). Только в группе."""
    if not ensure_user_access(message):
        return
    if message.chat.type in ("group", "supergroup") and not require_group_feature(message, "economy", message.from_user.id):
        return
    if message.chat.type not in ("group", "supergroup"):
        bot.reply_to(message, "❌ Донаты доступны только в группах. Используйте /donate в чате группы.")
        return
    if getattr(message, "sender_chat", None) is not None:
        bot.reply_to(message, "❌ Донат недоступен из анонимного режима.")
        return
    user_id = message.from_user.id
    chat_id = message.chat.id
    register_user(user_id)
    parts = (message.text or "").strip().split(maxsplit=1)
    amount_arg = (parts[1].strip() if len(parts) > 1 else "").replace(" ", "")
    if amount_arg and amount_arg.isdigit():
        amount = int(amount_arg)
        if amount < DONATE_MIN_AMOUNT:
            bot.reply_to(message, f"❌ Минимальная сумма доната: {DONATE_MIN_AMOUNT} монет.")
            return
        if amount > DONATE_MAX_AMOUNT:
            bot.reply_to(message, f"❌ Максимальная сумма доната: {DONATE_MAX_AMOUNT} монет.")
            return
        key = user_id
        now_ts = time.time()
        if key in _donate_last_time and (now_ts - _donate_last_time[key]) < DONATE_COOLDOWN_SEC:
            bot.reply_to(message, f"⏳ Подождите {DONATE_COOLDOWN_SEC} сек. перед следующим донатом.")
            return
        donations_ensure_group(chat_id, message.chat.title or "", None, None)
        ok, err = donations_do_donate(user_id, chat_id, amount, "")
        if ok:
            _donate_last_time[key] = now_ts
            total = get_group_total_donations(chat_id)
            try:
                bot.send_message(
                    chat_id,
                    f"🎉 Пользователь {message.from_user.full_name or 'Кто-то'} задонатил {amount} {COM_EMOJI} в группу!\n💰 Всего донатов: {total} {COM_EMOJI}",
                )
            except Exception:
                pass
            bot.reply_to(message, f"✅ Донат {amount} {COM_EMOJI} зачислен в группу! Всего донатов: {total} {COM_EMOJI}")
        else:
            bot.reply_to(message, f"❌ {err}")
        return
    donations_ensure_group(chat_id, message.chat.title or "", None, None)
    balance = get_balance(user_id)
    text = f"💸 **Донат в группу**\n\nБаланс: {balance} {COM_EMOJI}\n\nВыберите сумму или напишите: /donate [число]"
    markup = InlineKeyboardMarkup()
    for amt in [50, 100, 500, 1000]:
        markup.add(InlineKeyboardButton(f"{amt} {COM_EMOJI}", callback_data=f"donate_{chat_id}_{amt}"))
    markup.add(InlineKeyboardButton("✏️ Своя сумма", callback_data=f"donate_custom_{chat_id}"))
    bot.reply_to(message, text, reply_markup=markup, parse_mode="Markdown")


