@bot.message_handler(commands=['group_pay', 'выплата_из_казны'])
@safe_handler
def cmd_group_pay(message: Message):
    """Вывод из казны группы на свой баланс. Только владелец группы, только на себя, не ниже минимальной суммы. Использование: /group_pay сумма"""
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    user_id = message.from_user.id
    lang = get_user_language(user_id)
    if not is_chat_owner(user_id, chat_id):
        bot.reply_to(message, t(lang, "group_pay_owner_only"))
        return
    # Владелец может выводить только на свой баланс — цель всегда user_id
    target = _resolve_target_user_from_message(message)
    if target and target.id != user_id:
        bot.reply_to(message, t(lang, "group_pay_self_only"))
        return
    to_user_id = user_id
    text = (message.text or "").strip()
    parts = text.split()
    amount = None
    for p in parts:
        if p.isdigit():
            amount = int(p)
            break
    if amount is None or amount < 1:
        bot.reply_to(message, t(lang, "group_pay_specify_amount"))
        return
    if amount < GROUP_TREASURY_MIN_WITHDRAWAL:
        bot.reply_to(message, t(lang, "group_pay_min_amount", min=GROUP_TREASURY_MIN_WITHDRAWAL, sign=COM_EMOJI))
        return
    ok, err = group_treasury_pay(chat_id, user_id, to_user_id, amount)
    if ok:
        to_mention = get_user_mention(to_user_id) or (getattr(message.from_user, "first_name", None) or str(to_user_id))
        bot.reply_to(message, t(lang, "group_pay_done", amount=amount, sign=COM_EMOJI, mention=to_mention), parse_mode="Markdown")
        try:
            bot.send_message(to_user_id, t(get_user_language(to_user_id), "group_pay_recipient_notify", amount=amount, sign=COM_EMOJI), parse_mode="Markdown")
        except Exception:
            pass
    else:
        bot.reply_to(message, f"❌ {err}")


