def _markdown_link_escape(text: str) -> str:
    """Экранирует текст для подстановки внутрь ``[text](url)`` в Markdown.

    Внутри квадратных скобок разметка продолжает разбираться, поэтому
    набора ``\\ [ ]`` мало: название группы со звёздочкой или
    подчёркиванием ломало разбор всей страницы рейтинга — её не видел
    никто. Делегируем полному набору, чтобы правило жило в одном месте.
    """
    return _escape_markdown_caption(text)


def send_rating_page(chat_id: int, user_id: int, page: int) -> None:
    """Отправляет страницу рейтинга групп по очкам (Гром/Thunder). Уникальная ссылка на группу добавляется в название."""
    lang = get_user_language(user_id)
    groups, total_count = get_rating_groups_page(page)
    if not groups:
        bot.send_message(chat_id, t(lang, "no_groups_with_donates"))
        return
    updated_any = False
    for g in groups[:2]:
        if not (g.get("group_link") or "").strip():
            if update_group_invite_link(g["group_id"], g.get("group_name")):
                updated_any = True
    if updated_any:
        groups, total_count = get_rating_groups_page(page)
    xp_unit = t(lang, "group_xp_unit")
    rating_title = t(lang, "rating_page_title")
    text = f"🏆 **{rating_title}** ({t(lang, 'rating_page_short')} {page})\n\n"
    for g in groups:
        name = (g.get("group_name") or str(g["group_id"]))[:40]
        link = (g.get("group_link") or "").strip()
        xp_val = g.get("group_xp", g["total_donations"])
        if link:
            name_display = f"[{_markdown_link_escape(name)}]({link})"
        else:
            name_display = _markdown_link_escape(name)
        text += f"{g['rating_position']}. {name_display} — {xp_val} {xp_unit}\n"
    markup = InlineKeyboardMarkup()
    for g in groups:
        name = (g.get("group_name") or str(g["group_id"]))[:35]
        xp_val = g.get("group_xp", g["total_donations"])
        btn_text = f"{g['rating_position']}. {name} — {xp_val} {xp_unit}"
        markup.add(InlineKeyboardButton(
            btn_text,
            callback_data=f"group_stats_{g['group_id']}",
        ))
    nav = []
    if page > 1:
        nav.append(InlineKeyboardButton("⬅️", callback_data=f"rating_page_{page - 1}"))
    nav.append(InlineKeyboardButton(f"{page}", callback_data="rating_current"))
    if page * RATING_PAGE_SIZE < total_count:
        nav.append(InlineKeyboardButton("➡️", callback_data=f"rating_page_{page + 1}"))
    if nav:
        markup.row(*nav)
    markup.add(InlineKeyboardButton(t(lang, "back_to_menu"), callback_data="main_menu"))
    try:
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
    except Exception as e:
        logger.error(f"send_rating_page: {e}")


