TELEGRAPH_COMMANDS_URL_RU = ""
TELEGRAPH_COMMANDS_URL_EN = ""


@bot.message_handler(commands=['help', 'h', 'commands', 'kom_help'])
@safe_handler
def cmd_help(message: Message):
    """
    Краткая справка + кнопка со ссылкой на полный гайд на сайте бота (RU/EN).
    """
    if not ensure_user_access(message):
        return
    # Сбрасываем незавершённые шаги (заявка, поддержка), чтобы не путать с новыми действиями
    if message.from_user:
        clear_temp_data(message.from_user.id)
    in_group = message.chat.type in ("group", "supergroup")
    if in_group:
        delete_last_slot_message(message.chat.id, f"help_{message.from_user.id}")
    help_lang = get_user_language(message.from_user.id)
    telegraph_url = get_telegraph_commands_url(help_lang)
    if not telegraph_url:
        telegraph_url = (TELEGRAPH_COMMANDS_URL_RU if (help_lang or "").strip().lower() != "en" else TELEGRAPH_COMMANDS_URL_EN) or None
    games_lines_md = ""
    if PVP_GAMES_ONLY:
        games_lines_md = (
            t(help_lang, "help_bullet_pvp_dice") + "\n"
            + t(help_lang, "help_bullet_pvp_coin") + "\n"
        )
    else:
        # Telegram Markdown treats '_' as italics, so we escape '_' in /duel_stats.
        if (help_lang or "").strip().lower() == "en":
            games_lines_md = (
                "🎮 *Games*: /roulette, /dice, /duel, /duel\\_stats, /roll, /flip, /calc\n"
            )
        else:
            games_lines_md = (
                "🎮 *Игры*: /roulette, /dice, /duel, /duel\\_stats, /roll, /flip, /calc\n"
            )

    text = (
        t(help_lang, "help_title") + "\n\n"
        + t(help_lang, "help_intro") + "\n\n"
        + t(help_lang, "help_quick_access") + "\n"
        + t(help_lang, "help_bullet_start") + "\n"
        + games_lines_md
        + t(help_lang, "help_bullet_ai") + "\n"
        + t(help_lang, "help_bullet_help") + "\n\n"
        + t(help_lang, "help_footer_btn")
    )
    btn_text = t(help_lang, "help_btn_list")
    uid = message.from_user.id if message.from_user else None
    reply_markup = InlineKeyboardMarkup()
    if telegraph_url:
        reply_markup.add(InlineKeyboardButton(btn_text, url=telegraph_url))
    menu_kb = build_main_menu_keyboard(uid, help_lang) if uid else None
    if menu_kb:
        for row in menu_kb.keyboard:
            reply_markup.row(*row)
    if not reply_markup.keyboard and uid:
        reply_markup.add(InlineKeyboardButton("🔙 " + t(help_lang, "back_to_menu"), callback_data="main_menu"))
    msg = bot.reply_to(message, text, parse_mode="Markdown", reply_markup=reply_markup)
    try_delete_message(message.chat.id, message.message_id)
    if message.chat.type in ("group", "supergroup"):
        remember_slot_message(message.chat.id, f"help_{message.from_user.id}", msg.message_id, ttl=6 * 3600)
    
    if AUTO_DELETE_GAMES:
        schedule_deletion(message.chat.id, message.message_id, GAME_MESSAGES_TTL)
        schedule_deletion(message.chat.id, msg.message_id, GAME_MESSAGES_TTL)


