@bot.message_handler(commands=['create_check', 'check'])
@safe_handler
def cmd_create_check(message: Message):
    """Создать чек: /create_check random min max claims | fixed amount claims | individual amount @user (только владелец)."""
    if message.from_user.id not in DEVELOPER_IDS:
        return
    parts = (message.text or "").strip().split()
    if len(parts) < 3:
        bot.reply_to(
            message,
            "❌ **Использование:**\n\n"
            "`/create_check random мин макс кол-во_активаций`\n"
            "`/create_check fixed сумма кол-во_активаций`\n"
            "`/create_check individual сумма @username`\n\n"
            "Доп. параметры: `lang=ru` `premium=true` `sub=true` `expires=24`",
            parse_mode="Markdown",
        )
        return
    creator_id = message.from_user.id
    balance = get_balance(creator_id, use_cache=False)
    extra = {}
    for p in parts[3:]:
        if "=" in p:
            k, v = p.split("=", 1)
            extra[k.strip().lower()] = v.strip()
    expires_h = int(extra.get("expires", "24").replace("h", "").replace("H", "") or "24")
    expires_at = (datetime.now() + timedelta(hours=expires_h)).isoformat()
    req_lang = extra.get("lang") or None
    req_premium = 1 if extra.get("premium", "").lower() == "true" else 0
    req_sub = 1 if extra.get("sub", "").lower() == "true" else 0
    ctype = parts[1].lower()
    try:
        if ctype == "random":
            min_a = int(parts[2])
            max_a = int(parts[3])
            max_claims = int(parts[4])
            avg = (min_a + max_a) // 2
            total = avg * max_claims
            if balance < total:
                bot.reply_to(message, f"❌ Недостаточно монет. Нужно: {total}")
                return
            code = _generate_check_code()
            with database_connection(ECONOMY_DB) as conn:
                conn.execute(
                    "INSERT INTO checks (code, creator_id, type, total_amount, remaining_amount, min_amount, max_amount, max_claims, required_language, required_premium, required_subscription, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (code, creator_id, "random", total, total, min_a, max_a, max_claims, req_lang, req_premium, req_sub, expires_at),
                )
                conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (total, creator_id))
                conn.commit()
            cache_delete(f"balance_{creator_id}")
            me = bot.get_me()
            bot_username = getattr(me, "username", None) or "YourBot"
            bot.reply_to(
                message,
                f"✅ **Чек создан!**\n\n📋 Код: `{code}`\n💰 Сумма: от {min_a} до {max_a} монет\n👥 Активаций: {max_claims}\n💸 Списано: {total} монет\n\n🔗 Ссылка: https://t.me/{bot_username}?start=check_{code}",
                parse_mode="Markdown",
            )
        elif ctype == "fixed":
            fixed_a = int(parts[2])
            max_claims = int(parts[3])
            total = fixed_a * max_claims
            if balance < total:
                bot.reply_to(message, f"❌ Недостаточно монет. Нужно: {total}")
                return
            code = _generate_check_code()
            with database_connection(ECONOMY_DB) as conn:
                conn.execute(
                    "INSERT INTO checks (code, creator_id, type, total_amount, remaining_amount, fixed_amount, max_claims, required_language, required_premium, required_subscription, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (code, creator_id, "fixed", total, total, fixed_a, max_claims, req_lang, req_premium, req_sub, expires_at),
                )
                conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (total, creator_id))
                conn.commit()
            cache_delete(f"balance_{creator_id}")
            bot.reply_to(message, f"✅ **Чек создан!**\n\n📋 Код: `{code}`\n💰 Сумма: {fixed_a} монет\n👥 Активаций: {max_claims}\n💸 Списано: {total} монет", parse_mode="Markdown")
        elif ctype == "individual":
            fixed_a = int(parts[2])
            target_username = parts[3].lstrip("@")
            target = _get_user_by_username(target_username)
            if not target:
                bot.reply_to(message, "❌ Пользователь не найден в базе.")
                return
            if balance < fixed_a:
                bot.reply_to(message, "❌ Недостаточно монет.")
                return
            code = _generate_check_code()
            with database_connection(ECONOMY_DB) as conn:
                conn.execute(
                    "INSERT INTO checks (code, creator_id, type, total_amount, remaining_amount, fixed_amount, target_user_id, required_language, required_premium, required_subscription, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (code, creator_id, "individual", fixed_a, fixed_a, fixed_a, target["user_id"], req_lang, req_premium, req_sub, expires_at),
                )
                conn.execute("UPDATE users SET balance = balance - ? WHERE user_id = ?", (fixed_a, creator_id))
                conn.commit()
            cache_delete(f"balance_{creator_id}")
            try:
                bot.send_message(
                    target["user_id"],
                    f"🎁 Вам подарок от {message.from_user.full_name or 'Администратора'}!\n\n💰 Сумма: {fixed_a} монет\n🔗 Активируйте: https://t.me/{(bot.get_me().username or 'YourBot')}?start=check_{code}",
                )
            except Exception:
                pass
            bot.reply_to(message, f"✅ **Персональный чек создан!**\n\n📋 Код: `{code}`\n👤 Для: @{target_username}\n💰 Сумма: {fixed_a} монет", parse_mode="Markdown")
        else:
            bot.reply_to(message, "❌ Тип чека: random, fixed или individual.")
    except (ValueError, IndexError) as e:
        bot.reply_to(message, f"❌ Ошибка в параметрах: {e}")


@bot.message_handler(commands=['add_required_chat'])
@safe_handler
def cmd_add_required_chat(message: Message):
    """Добавить обязательную подписку: /add_required_chat @channel_name Название (только владелец)."""
    if message.from_user.id not in DEVELOPER_IDS:
        return
    parts = (message.text or "").strip().split(maxsplit=2)
    if len(parts) < 3:
        bot.reply_to(message, "Формат: /add_required_chat @channel_name Название")
        return
    username = parts[1].lstrip("@")
    title = parts[2].strip()
    if not username:
        bot.reply_to(message, "Укажите @username канала.")
        return
    try:
        chat = bot.get_chat("@" + username)
        chat_id = chat.id
    except Exception as e:
        logger.warning("add_required_chat get_chat %s: %s", username, e)
        bot.reply_to(message, "❌ Канал не найден или бот не админ.")
        return
    with database_connection(USERS_DB) as conn:
        conn.execute(
            "INSERT INTO required_subscriptions (chat_id, chat_username, title, is_mandatory, created_by) VALUES (?, ?, ?, 1, ?)",
            (chat_id, "@" + username, title, message.from_user.id),
        )
    bot.reply_to(message, f"✅ Канал «{title}» добавлен в обязательные подписки.")


