@bot.message_handler(commands=['logs'])
@admin_only
@safe_handler
def cmd_logs(message: Message):
    """Просмотр последних строк лога (только разработчик)."""
    if message.chat.type != "private":
        return
    line_count = 30
    parts = (message.text or "").split()
    if len(parts) > 1:
        try:
            line_count = min(100, max(5, int(parts[1])))
        except ValueError:
            pass
    log_path = Path("logs") if Path("logs").exists() else Path(".")
    log_files = list(log_path.glob("*.log")) or list(Path(".").glob("*.log"))
    if not log_files:
        bot.reply_to(message, "Файлы логов не найдены.")
        return
    latest = max(log_files, key=lambda p: p.stat().st_mtime)
    try:
        with open(latest, "r", encoding="utf-8", errors="replace") as f:
            tail = "".join(deque(f, maxlen=line_count))
        if len(tail) > 4000:
            tail = tail[-4000:]
        bot.reply_to(message, f"📋 **Лог** ({latest.name}, последние {line_count} строк):\n\n`{html.escape(tail)}`", parse_mode="Markdown")
    except Exception as e:
        bot.reply_to(message, f"Ошибка чтения лога: {e}")


@bot.message_handler(commands=['rate_stats'])
@admin_only
@safe_handler
def cmd_rate_stats(message: Message):
    """Показывает статистику rate limit (только для разработчика)."""
    if message.chat.type != "private":
        return
    with _rate_limit_manager._global_lock:
        total_users = len(_rate_limit_manager._last_calls)
        total_locks = len(_rate_limit_manager._locks)
        active_users = sorted(
            [(uid, len(calls)) for uid, calls in _rate_limit_manager._last_calls.items()],
            key=lambda x: x[1],
            reverse=True
        )[:5]
    text = "📊 **Rate Limit Статистика**\n\n"
    text += f"👥 Активных пользователей: {total_users}\n"
    text += f"🔒 Активных блокировок: {total_locks}\n\n"
    if active_users:
        text += "**Топ активных:**\n"
        for uid, count in active_users:
            text += f"• ID {uid}: {count} запросов в минуту\n"
    else:
        text += "Нет активных пользователей"
    bot.reply_to(message, text, parse_mode="Markdown")


@bot.message_handler(commands=['backup'])
@admin_only
@safe_handler
def cmd_backup(message: Message):
    """Создать бэкап баз данных (только разработчик)."""
    if message.chat.type != "private":
        return
    import shutil as _shutil
    backup_dir = Path("backups")
    backup_dir.mkdir(exist_ok=True)
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    created = []
    for name, db_path in [("users", USERS_DB), ("moderation", MODERATION_DB), ("economy", ECONOMY_DB), ("activity", ACTIVITY_DB)]:
        if getattr(db_path, "exists", None) and db_path.exists():
            dest = backup_dir / f"{name}_{ts}.db"
            try:
                _shutil.copy2(db_path, dest)
                created.append(dest.name)
            except Exception as e:
                logger.exception("backup %s: %s", name, e)
    if created:
        bot.reply_to(message, f"✅ Бэкап создан: {', '.join(created)}")
    else:
        bot.reply_to(message, "❌ Не удалось создать бэкап.")


