@bot.message_handler(commands=['sql'])
@admin_only
@safe_handler
def cmd_sql(message: Message):
    """Выполнить SQL запрос (только разработчик, только в ЛС)."""
    if message.chat.type != "private":
        return

    user_id = message.from_user.id
    query = (message.text or "").replace("/sql", "", 1).strip()

    if not query:
        bot.reply_to(message, "Использование: /sql SELECT * FROM users LIMIT 5")
        return

    logger.warning(f"[SQL] User {user_id} executed: {query}")

    db_path = USERS_DB
    if query.upper().startswith("MODERATION:"):
        query = query.split(":", 1)[1].strip()
        db_path = MODERATION_DB
    elif query.upper().startswith("ECONOMY:"):
        query = query.split(":", 1)[1].strip()
        db_path = ECONOMY_DB

    is_select = query.strip().upper().startswith("SELECT")
    if not is_select:
        dangerous_keywords = ["DROP", "TRUNCATE", "ALTER", "DELETE", "UPDATE"]
        for kw in dangerous_keywords:
            if kw in query.upper():
                markup = InlineKeyboardMarkup()
                markup.add(
                    InlineKeyboardButton("✅ Подтвердить", callback_data=f"sql_confirm_{hash(query) & 0x7FFFFFFF}"),
                    InlineKeyboardButton("❌ Отмена", callback_data="sql_cancel")
                )
                save_temp_data(user_id, "pending_sql", {
                    "query": query,
                    "db_path": str(db_path),
                    "timestamp": time.time()
                })
                bot.reply_to(
                    message,
                    f"⚠️ **Опасная операция!**\n\n"
                    f"Вы собираетесь выполнить:\n`{html.escape(query[:200])}`\n\n"
                    f"Это может удалить или изменить данные.\n"
                    f"Подтвердите действие:",
                    reply_markup=markup,
                    parse_mode="Markdown"
                )
                return

    try:
        if is_select:
            rows = execute_query(db_path, query)
            if rows is None:
                bot.reply_to(message, "❌ Ошибка выполнения запроса.")
                return
            max_rows = 100
            shown = min(len(rows), max_rows)
            text = f"📊 **Результат (первые {shown} из {len(rows)}):**\n\n"
            for i, row in enumerate(rows[:max_rows]):
                text += f"`{dict(row)}`\n"
                if i >= 50:
                    remainder = len(rows) - i - 1
                    if remainder > 0:
                        text += f"\n_… и ещё {remainder} строк_"
                    break
            bot.reply_to(message, text[:4000], parse_mode="Markdown")
            logger.info(f"[SQL] SELECT returned {len(rows)} rows for user {user_id}")
        else:
            with database_connection(db_path) as conn:
                cursor = conn.execute(query)
                conn.commit()
                rows_affected = getattr(cursor, "rowcount", -1)
            bot.reply_to(message, f"✅ Запрос выполнен. Затронуто строк: {rows_affected}")
            logger.info(f"[SQL] {query.split()[0]} affected {rows_affected} rows (user {user_id})")
    except Exception as e:
        error_msg = str(e)
        logger.error(f"[SQL] Error for user {user_id}: {error_msg}")
        bot.reply_to(message, f"❌ Ошибка: {html.escape(error_msg[:200])}")


@bot.callback_query_handler(func=lambda call: call.data == "sql_cancel")
@admin_only
@safe_handler
def sql_cancel_callback(call: CallbackQuery):
    """Отмена опасного SQL-запроса."""
    user_id = call.from_user.id
    clear_temp_data(user_id, "pending_sql")
    bot.answer_callback_query(call.id, "❌ Запрос отменён")
    try:
        bot.edit_message_text(
            "❌ Опасная операция отменена.",
            call.message.chat.id,
            call.message.message_id
        )
    except Exception:
        pass


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("sql_confirm_"))
@admin_only
@safe_handler
def sql_confirm_callback(call: CallbackQuery):
    """Подтверждение опасного SQL-запроса."""
    user_id = call.from_user.id
    pending = get_temp_data(user_id, "pending_sql")

    if not pending:
        bot.answer_callback_query(call.id, "⏳ Запрос устарел или не найден", show_alert=True)
        return

    if time.time() - pending["timestamp"] > 300:
        clear_temp_data(user_id, "pending_sql")
        bot.answer_callback_query(call.id, "⏳ Время подтверждения истекло", show_alert=True)
        return

    query = pending["query"]
    db_path = Path(pending["db_path"])

    bot.answer_callback_query(call.id, "✅ Выполняю...")

    try:
        with database_connection(db_path) as conn:
            cursor = conn.execute(query)
            conn.commit()
            rows_affected = getattr(cursor, "rowcount", -1)
        clear_temp_data(user_id, "pending_sql")

        try:
            bot.edit_message_text(
                f"✅ **Опасная операция выполнена!**\n\nЗатронуто строк: {rows_affected}",
                call.message.chat.id,
                call.message.message_id,
                parse_mode="Markdown"
            )
        except Exception:
            pass

        logger.warning(f"[SQL] DANGEROUS OPERATION confirmed by user {user_id}: {query}")
    except Exception as e:
        error_msg = str(e)
        logger.error(f"[SQL] Error in confirmed operation for user {user_id}: {error_msg}")
        try:
            bot.edit_message_text(
                f"❌ Ошибка при выполнении: {html.escape(error_msg[:200])}",
                call.message.chat.id,
                call.message.message_id
            )
        except Exception:
            pass


