    for cur in ["RUB", "USD", "EUR", "GBP", "CNY", "TON"]:
        rate = currency_manager.get_rate(cur)
        com_per_cur = 1.0 / rate if rate and rate > 0 else 0
        text += "• **%s**: 1 COM = %.6f %s | 1 %s = %.2f COM\n" % (cur, rate, cur, cur, com_per_cur)
