# Состояние для рассылки
_broadcast_state: Dict[int, str] = {}  # user_id -> "waiting_text" | "waiting_confirm"


@bot.message_handler(commands=['broadcast'])
@admin_only
@safe_handler
def cmd_broadcast(message: Message):
    """Массовая рассылка (только разработчик). Введите текст после подтверждения."""
    if message.chat.type != "private":
        return
    _broadcast_state[message.from_user.id] = "waiting_text"
    bot.reply_to(message, "📢 **Массовая рассылка**\n\nВведите текст сообщения для рассылки всем пользователям:", parse_mode="Markdown")


@bot.message_handler(func=lambda m: m.from_user and m.from_user.id in _broadcast_state and m.chat.type == "private")
@safe_handler
def cmd_broadcast_process(message: Message):
    """Обработка ввода текста рассылки и подтверждение."""
    uid = message.from_user.id
    if uid not in DEVELOPER_IDS:
        _broadcast_state.pop(uid, None)
        return
    state = _broadcast_state.get(uid)
    if not state:
        return
    if state == "waiting_text":
        text = (message.text or "").strip()
        if not text:
            bot.reply_to(message, "Введите непустой текст.")
            return
        _broadcast_state[uid] = f"confirm:{text[:3500]}"
        bot.reply_to(
            message,
            "⚠️ Отправить это сообщение **всем** пользователям из базы?\n\n" + text[:500] + ("…" if len(text) > 500 else ""),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup().row(
                InlineKeyboardButton("✅ Да", callback_data="broadcast_confirm"),
                InlineKeyboardButton("❌ Отмена", callback_data="broadcast_cancel"),
            ),
        )
        return
    if state.startswith("confirm:"):
        _broadcast_state.pop(uid, None)
        bot.reply_to(message, "Используйте кнопки ✅ Да / ❌ Отмена для рассылки.")
        return


@bot.callback_query_handler(func=lambda call: call.data in ("broadcast_confirm", "broadcast_cancel"))
@safe_handler
def cb_broadcast_confirm_cancel(call: CallbackQuery):
    """Подтверждение или отмена рассылки."""
    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id)
        return
    if call.data == "broadcast_cancel":
        _broadcast_state.pop(call.from_user.id, None)
        bot.answer_callback_query(call.id, "Отменено")
        try:
            bot.edit_message_text("❌ Рассылка отменена.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        return
    # broadcast_confirm: get text from state
    uid = call.from_user.id
    state = _broadcast_state.pop(uid, "")
    if not state.startswith("confirm:"):
        bot.answer_callback_query(call.id, "Сессия истекла")
        return
    text = state.replace("confirm:", "", 1)
    bot.answer_callback_query(call.id)
    try:
        bot.edit_message_text("📤 Рассылка началась…", call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    try:
        rows = execute_query(USERS_DB, "SELECT user_id FROM users")
        users = [int(r[0]) for r in (rows or []) if r and r[0]]
        sent, failed = 0, 0
        for u in users:
            try:
                bot.send_message(u, text, parse_mode="HTML")
                sent += 1
                time.sleep(0.05)
            except Exception:
                failed += 1
        bot.send_message(call.message.chat.id, f"✅ Рассылка завершена.\n📨 Отправлено: {sent}\n❌ Не доставлено: {failed}")
    except Exception as e:
        bot.send_message(call.message.chat.id, f"❌ Ошибка рассылки: {e}")


