def cmd_maintenance(message: Message):
    """
    Управление режимом техобслуживания.
    Использование: /maintenance [on|off|status]
    """
    global MAINTENANCE_MODE

    if message.from_user.id not in DEVELOPER_IDS:
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return

    args = (message.text or "").split(maxsplit=1)
    action = args[1].strip().lower() if len(args) > 1 else "status"

    if action in ("on", "enable", "1", "вкл"):
        MAINTENANCE_MODE = True
        settings["maintenance_mode"] = True
        save_settings(settings)
        logger.info("[owner] maintenance_mode=on by user_id=%s", message.from_user.id)
        bot.reply_to(message, "🛠 Режим техобслуживания включён.")
    elif action in ("off", "disable", "0", "выкл"):
        MAINTENANCE_MODE = False
        settings["maintenance_mode"] = False
        save_settings(settings)
        logger.info("[owner] maintenance_mode=off by user_id=%s", message.from_user.id)
        bot.reply_to(message, "✅ Режим техобслуживания выключен.")
    else:
        status = "включён" if MAINTENANCE_MODE else "выключен"
        bot.reply_to(
            message,
            f"🛠 Техобслуживание сейчас: {status}\n"
            f"Использование: /maintenance on | /maintenance off | /maintenance status"
        )

