def admin_callback_only(func):
    """Декоратор для callback-функций, доступных только разработчику (глобальная админка)."""
    @wraps(func)
    def wrapper(call: CallbackQuery, *args, **kwargs):
        if not is_admin(call.from_user.id):
            lang = get_user_language(call.from_user.id)
            bot.answer_callback_query(call.id, t(lang, "not_for_you"))
            return
        return func(call, *args, **kwargs)
    return wrapper


def group_admin_callback_only(func):
    """
    Декоратор для callback'ов управления группой: доступно разработчику бота или любому администратору
    этой группы в Telegram (владелец или админ с правами модерации).
    В режиме теста «как админ группы» разработчик может пользоваться панелью модерации и в личке.
    В группе бот сам должен быть администратором — иначе настройки недоступны.
    """
    @wraps(func)
    def wrapper(call: CallbackQuery, *args, **kwargs):
        user_id = call.from_user.id
        if user_id in DEVELOPER_IDS and get_developer_testing_mode() == "group_admin":
            return func(call, *args, **kwargs)
        chat_id = getattr(call.message, "chat", None) and getattr(call.message.chat, "id", None)
        chat_type = getattr(call.message, "chat", None) and getattr(call.message.chat, "type", "")
        if is_owner(user_id):
            return func(call, *args, **kwargs)
        if chat_type in ("group", "supergroup") and chat_id is not None and not is_feature_enabled_for_chat(chat_id, "group_admin", user_id):
            require_group_feature(chat_id, "group_admin", user_id, from_callback=True, call=call)
            return
        if chat_type in ("group", "supergroup") and chat_id and has_group_admin_rights(user_id, chat_id):
            try:
                me = bot.get_me()
                bot_member = bot.get_chat_member(chat_id, me.id)
                if getattr(bot_member, "status", "") not in ("administrator", "creator"):
                    lang = get_user_language(call.from_user.id)
                    bot.answer_callback_query(call.id, t(lang, "bot_must_be_admin"), show_alert=True)
                    return
            except Exception:
                pass
            return func(call, *args, **kwargs)
        lang = get_user_language(call.from_user.id)
        bot.answer_callback_query(call.id, t(lang, "insufficient_rights"))
        return
    return wrapper

def save_temp_data(user_id: int, key: str, value: Any) -> None:
    """
    Сохраняет временные данные для пользователя.
    Ключи хранятся с префиксом TEMP_DATA_PREFIX, чтобы не конфликтовать с другими агентами.
    """
    cache_set(f"admin_temp_{user_id}_{TEMP_DATA_PREFIX}{key}", value, ttl=600)  # 10 минут

def get_temp_data(user_id: int, key: str) -> Any:
    """Получает временные данные пользователя (с префиксом TEMP_DATA_PREFIX)."""
    return cache_get(f"admin_temp_{user_id}_{TEMP_DATA_PREFIX}{key}")

def clear_temp_data(user_id: int, key: str = None) -> None:
    """Очищает временные данные пользователя (key=None — все ключи этого агента)."""
    if key:
        cache_delete(f"admin_temp_{user_id}_{TEMP_DATA_PREFIX}{key}")
    else:
        prefix = f"admin_temp_{user_id}_{TEMP_DATA_PREFIX}"
        for k in list(cache.keys()):
            if k.startswith(prefix):
                cache_delete(k)

