def _run_translate_missing_en(chat_id: int) -> None:
    """Background thread: translate welcome_text and button_text to EN if _en is empty; save and notify."""
    if _translator is None:
        try:
            bot.send_message(chat_id, "⚠️ Библиотека googletrans недоступна. Установите: pip install googletrans==4.0.0-rc1")
        except Exception:
            pass
        return
    done = []
    try:
        if (WELCOME_TEXT or "").strip() and not (settings.get("welcome_text_en") or "").strip():
            r = _translator.translate(WELCOME_TEXT.strip(), dest="en")
            text_en = (r.text or "").strip()
            if text_en:
                settings["welcome_text_en"] = text_en
                globals()["WELCOME_TEXT_EN"] = text_en
                done.append("welcome_text_en")
        if (BUTTON_TEXT or "").strip() and not (settings.get("button_text_en") or "").strip():
            r = _translator.translate(BUTTON_TEXT.strip(), dest="en")
            text_en = (r.text or "").strip()
            if text_en:
                settings["button_text_en"] = text_en
                globals()["BUTTON_TEXT_EN"] = text_en
                done.append("button_text_en")
        if done:
            save_settings(settings)
        try:
            bot.send_message(
                chat_id,
                f"✅ **Перевод сохранён:** {', '.join(done)}" if done else "ℹ️ Все тексты уже переведены на EN.",
                parse_mode="Markdown",
            )
        except Exception:
            pass
    except Exception as e:
        logger.warning("Translate missing EN failed: %s", e)
        try:
            bot.send_message(chat_id, f"⚠️ Ошибка перевода: {html.escape(str(e)[:300])}")
        except Exception:
            pass


@bot.callback_query_handler(func=lambda call: call.data == "admin_translate_missing_en")
@admin_callback_only
def admin_translate_missing_en(call: CallbackQuery):
    """Translate missing EN versions of welcome and button text (developer panel)."""
    bot.answer_callback_query(call.id, "Перевожу в фоне…")
    threading.Thread(
        target=_run_translate_missing_en,
        args=(call.message.chat.id,),
        daemon=True,
    ).start()


