@bot.callback_query_handler(func=lambda call: call.data == "admin_categories")
@admin_callback_only
def admin_categories(call: CallbackQuery):
    """Раздел управления категориями (вкл/выкл разделы бота)."""
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    groups_with_keys = [
        ("group_label_economy", ["economy", "shop", "donations", "p2p", "withdraw"]),
        ("group_label_fun", ["games", "ai", "marriage", "relationships"]),
        ("group_label_profile", ["profile", "stats", "referrals", "achievements"]),
        ("group_label_moderation", ["moderation"]),
        ("group_label_status", ["vip", "legend"]),
    ]
    games_subcategories = ["games_dice", "games_roulette", "games_duel", "games_flip", "games_cpc", "games_roll", "games_calc"]
    text = t(lang, "categories_screen_title") + t(lang, "categories_screen_intro")
    markup = InlineKeyboardMarkup(row_width=2)
    for group_key, categories in groups_with_keys:
        group_name = t(lang, group_key)
        text += f"**{group_name}**\n"
        for cat in categories:
            status = CATEGORY_STATUS.get(cat, True)
            status_emoji = "✅" if status else "❌"
            display_name = get_category_display_name(cat, lang)
            text += f"{status_emoji} {display_name}\n"
            markup.add(InlineKeyboardButton(
                f"{status_emoji} {display_name}",
                callback_data=f"toggle_category_{cat}",
            ))
            if cat == "games":
                for subcat in games_subcategories:
                    st = CATEGORY_STATUS.get(subcat, True)
                    em = "✅" if st else "❌"
                    name = get_category_display_name(subcat, lang)
                    text += f"  {em} {name}\n"
                    markup.add(InlineKeyboardButton(
                        f"{em} {name}",
                        callback_data=f"toggle_category_{subcat}",
                    ))
        text += "\n"
    markup.add(InlineKeyboardButton(t(lang, "categories_bulk_actions"), callback_data="admin_categories_bulk"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_back"))
    try:
        bot.edit_message_text(
            text,
            call.message.chat.id,
            call.message.message_id,
            reply_markup=markup,
            parse_mode="Markdown",
        )
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("toggle_category_"))
@admin_callback_only
def toggle_category(call: CallbackQuery):
    """Переключает статус категории."""
    category = call.data.replace("toggle_category_", "")
    if category not in CATEGORY_STATUS:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "category_not_found"))
        return
    CATEGORY_STATUS[category] = not CATEGORY_STATUS.get(category, True)
    settings["category_status"] = dict(CATEGORY_STATUS)
    save_settings(settings)
    lang = get_user_language(call.from_user.id)
    display_name = get_category_display_name(category, lang)
    key = "category_toggled_on" if CATEGORY_STATUS[category] else "category_toggled_off"
    bot.answer_callback_query(call.id, t(lang, key, name=display_name))
    call.data = "admin_categories"
    admin_categories(call)


