@bot.callback_query_handler(func=lambda call: call.data == "admin_bot_groups")
@admin_callback_only
def admin_bot_groups(call: CallbackQuery):
    """Список всех групп, куда добавлен бот, и кто добавил (только для владельца)."""
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    if user_id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id, t(lang, "admin_owner_only"))
        return
    bot.answer_callback_query(call.id)
    groups = get_all_groups_for_features_panel()
    lines = [
        t(lang, "botgroupstitle"),
        "",
        t(lang, "botgroupstotal", count=len(groups)),
        "",
    ]
    for i, row in enumerate(groups[:50], 1):
        g_chat_id = row[0]
        g_title = row[1]
        added_by_uid = row[2]
        added_at = row[3]
        bot_has_admin = (row[4] if len(row) > 4 else 0) != 0
        # Название группы задаёт её владелец, а карточка уходит с
        # parse_mode="Markdown": подмена одной звёздочки на «·» не
        # спасала от _ ` [ ] — панель ломалась на чужом названии.
        safe_title = _escape_markdown_caption((g_title or str(g_chat_id))[:40])
        when = ""
        if added_at:
            try:
                when = datetime.fromisoformat(str(added_at).replace("Z", "+00:00")).strftime("%d.%m.%Y %H:%M")
            except Exception:
                when = str(added_at)[:16]
        if added_by_uid:
            name, username = _get_user_profile_brief(added_by_uid)
            safe_name = _escape_markdown_caption((name or str(added_by_uid))[:30])
            adder = f"{safe_name}" + (f" @{username}" if username else "") + f" (ID `{added_by_uid}`)"
        else:
            adder = "—" if lang == "ru" else "—"
        admin_status = t(lang, "bot_groups_admin_yes") if bot_has_admin else t(lang, "bot_groups_admin_no")
        lines.append(
            f"**{i}.**\n"
            f"• {t(lang, 'bot_groups_group_line')} {safe_title}\n"
            f"• ID чата: `{g_chat_id}`\n"
            f"• {t(lang, 'bot_groups_added_by')} {adder} {f'— {when}' if when else ''}\n"
            f"• {t(lang, 'bot_groups_admin_rights')} {admin_status}"
        )
    if len(groups) > 50:
        lines.append(f"\n_… и ещё {len(groups) - 50} групп._")
    text = "\n".join(lines)
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_system"))
    try:
        bot.edit_message_text(
            text,
            call.message.chat.id,
            call.message.message_id,
            reply_markup=markup,
            parse_mode="Markdown",
        )
    except Exception as e:
        if "message is too long" in str(e).lower() or "too long" in str(e).lower():
            parts = _split_admin_text("\n\n".join(lines[4:]), 3500)
            bot.edit_message_text(
                lines[0] + "\n\n" + lines[1] + "\n" + lines[2] + "\n\n" + (parts[0] if parts else t(lang, "no_data")),
                call.message.chat.id,
                call.message.message_id,
                reply_markup=markup,
                parse_mode="Markdown",
            )
        else:
            raise


@bot.callback_query_handler(func=lambda call: call.data == "admin_group_features")
@admin_callback_only
def admin_group_features(call: CallbackQuery):
    """Панель: список групп и переключение режима full (все функции) / restricted (только AI). Только владелец."""
    user_id = call.from_user.id
    lang = get_user_language(user_id)

    if user_id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id, t(lang, "admin_owner_only"))
        return

    bot.answer_callback_query(call.id)

    # Получаем группы
    groups = get_all_groups_for_features_panel()

    # Статистика для диагностики
    total_bot_groups = len(get_all_bot_groups())
    total_group_settings = 0
    try:
        rows = execute_query(USERS_DB, "SELECT COUNT(*) FROM group_settings")
        if rows and rows[0]:
            total_group_settings = rows[0][0]
    except Exception:
        pass

    lines = [
        t(lang, "group_modes_title"),
        "",
        "📊 **Статистика:**",
        f"• Групп в bot_groups: {total_bot_groups}",
        f"• Групп в group_settings: {total_group_settings}",
        f"• Отображается: {len(groups)}",
        "",
        t(lang, "group_modes_full_desc"),
        t(lang, "group_modes_restricted_desc"),
        "",
        t(lang, "group_modes_total", count=len(groups)),
        "",
    ]

    if not groups:
        lines.append("_" + t(lang, "group_modes_no_groups") + "_")
        lines.append("")
        lines.append("💡 **Возможные причины:**")
        lines.append("• Бот не добавлен ни в одну группу")
        lines.append("• Таблица bot_groups пуста")
        lines.append("• Нет групп в group_settings")
        lines.append("")
        lines.append("🛠 **Диагностика:**")
        lines.append("```sql")
        lines.append("SELECT COUNT(*) FROM bot_groups;")
        lines.append("SELECT COUNT(*) FROM group_settings;")
        lines.append("```")

    markup = InlineKeyboardMarkup()
    for g_chat_id, g_title, _added_by, _added_at in groups[:25]:
        gs = get_group_settings(g_chat_id)
        mode = (gs.get("features_mode") or "full").strip().lower()
        safe_title = (g_title or str(g_chat_id))[:35].replace("*", "·")

        if mode == "restricted":
            markup.add(InlineKeyboardButton(
                f"🔴 {safe_title}",
                callback_data=f"group_features_full_{g_chat_id}"
            ))
        else:
            markup.add(InlineKeyboardButton(
                f"✅ {safe_title}",
                callback_data=f"group_features_restricted_{g_chat_id}"
            ))

    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_system"))

    text = "\n".join(lines)
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and (call.data.startswith("group_features_full_") or call.data.startswith("group_features_restricted_")))
@admin_callback_only
def admin_group_features_toggle(call: CallbackQuery):
    """Переключение режима группы: full или restricted."""
    lang = get_user_language(call.from_user.id)
    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id)
        return
    try:
        if call.data.startswith("group_features_full_"):
            gid = int(call.data.replace("group_features_full_", "").strip())
            set_group_features_mode(gid, "full")
            bot.answer_callback_query(call.id, t(lang, "group_mode_full_toast"))
        else:
            gid = int(call.data.replace("group_features_restricted_", "").strip())
            set_group_features_mode(gid, "restricted")
            bot.answer_callback_query(call.id, t(lang, "group_mode_restricted_toast"))
    except ValueError:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "error_short"))
        return
    call.data = "admin_group_features"
    admin_group_features(call)


# ---------- Админ-панель в ЛС: управление группой (admin_group_*, group_filter_*, group_roles_*) ----------

# Сообщение при устаревших/недействительных callback_data (кнопки после перезапуска)
CALLBACK_STALE_MSG = "⚠️ Кнопка устарела. Откройте настройки заново."

def _admin_group_can_manage(user_id: int, group_id: int) -> bool:
    """Проверяет, может ли пользователь управлять группой (owner или в group_roles)."""
    if user_id in DEVELOPER_IDS:
        return True
    groups = get_user_manageable_groups(user_id)
    return any(g["id"] == group_id for g in groups)


# Инициализация новой архитектуры (Этап 2) после определения всех зависимостей
try:
    _init_new_architecture()
except Exception as _e:
    logger.debug("Инициализация новой архитектуры (Этап 2): %s", _e)


def _build_user_groups_admin_panel(user_id: int) -> Tuple[str, InlineKeyboardMarkup]:
    """Формирует текст и клавиатуру админ-панели «мои группы»: активная группа, переключатель, список групп."""
    groups = get_user_manageable_groups(user_id)
    current_id = get_user_current_group(user_id)
    current_title = None
    if current_id:
        for g in groups:
            if g["id"] == current_id:
                current_title = g.get("title", str(current_id))[:40]
                break
        else:
            current_id = None
    lines = ["👑 **Админ-панель**\n"]
    if current_title:
        lines.append(f"🎯 Активная группа: **{current_title}**\n")
    else:
        lines.append("🎯 Активная группа не выбрана\n")
    lines.append("Выберите группу для управления:\n")
    text = "".join(lines)
    markup = InlineKeyboardMarkup()
    if current_id:
        markup.add(InlineKeyboardButton("⚙️ Управление активной", callback_data="admin_open_current_group"))
    markup.add(InlineKeyboardButton("🔄 Сменить группу", callback_data="admin_panel_switch_group"))
    for g in groups[:20]:
        role_emoji = "👑" if g.get("role") == "owner" else "🛡"
        markup.add(InlineKeyboardButton(
            text=f"{role_emoji} {g.get('title', str(g['id']))[:40]}",
            callback_data=f"admin_group_{g['id']}"
        ))
    return text, markup


def _send_group_management_panel(chat_id: int, user_id: int, group_id: int) -> None:
    """Отправляет в чат (ЛС) панель управления группой — та же, что по admin_group_<id>. Используется при переходе по ссылке start=group_setup_<id>."""
    if not _admin_group_can_manage(user_id, group_id):
        return
    set_user_current_group(user_id, group_id)
    lang = get_user_language(user_id)
    title = "Группа"
    try:
        chat = bot.get_chat(group_id)
        title = getattr(chat, "title", None) or title
    except Exception:
        pass
    text = (
        f"⚙️ **Управление группой**\n\n"
        f"📌 {title}\n\n"
        f"Выберите раздел:"
    )
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("🛡 Модерация", callback_data=f"group_moderation_{group_id}"))
    markup.add(InlineKeyboardButton("🔤 Фильтр слов", callback_data=f"group_filter_{group_id}"))
    markup.add(InlineKeyboardButton(t(lang, "group_roles_and_perms_btn"), callback_data=f"group_roles_{group_id}"))
    markup.add(InlineKeyboardButton("📊 Статистика", callback_data=f"group_stats_{group_id}"))
    markup.add(InlineKeyboardButton("⚙️ Настройки", callback_data=f"group_settings_{group_id}"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_panel_back"))
    bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")


