@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("group_filter_"))
@safe_handler
def cb_group_filter_menu(call: CallbackQuery):
    """Меню фильтра слов группы."""
    try:
        group_id = int(call.data.replace("group_filter_", "").strip())
    except ValueError:
        try:
            bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        except Exception:
            pass
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    lang = get_user_language(call.from_user.id)
    gs = get_group_settings(group_id)
    words = get_filter_words_for_group(group_id)
    status = "✅ Включён" if gs.get("filter_enabled") else "❌ Выключен"
    text = f"🔤 **Фильтр слов**\n\nСтатус: {status}\n\n"
    if words:
        text += "**Запрещённые слова:**\n"
        for w in words[:15]:
            act = (w.get("action") or "delete").lower()
            act_key = f"filter_action_{act}"
            act_label = t(lang, act_key)
            if act_label == act_key:
                act_label = t(lang, "filter_action_other")
            text += f"• {w['word']} — {act_label}\n"
    else:
        text += "Список пуст.\n"
    markup = InlineKeyboardMarkup()
    markup.row(
        InlineKeyboardButton("✅ Вкл", callback_data=f"filter_on_{group_id}"),
        InlineKeyboardButton("❌ Выкл", callback_data=f"filter_off_{group_id}"),
    )
    markup.add(InlineKeyboardButton("➕ Добавить слово", callback_data=f"filter_add_{group_id}"))
    markup.add(InlineKeyboardButton("📋 Список слов", callback_data=f"filter_list_{group_id}"))
    markup.add(InlineKeyboardButton("🔙 Назад", callback_data=f"admin_group_{group_id}"))
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


