    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    try:
        with database_connection(USERS_DB) as conn:
            conn.execute(
                """INSERT INTO group_settings (group_id, filter_enabled, updated_at) VALUES (?, 1, CURRENT_TIMESTAMP)
                   ON CONFLICT(group_id) DO UPDATE SET filter_enabled = 1, updated_at = CURRENT_TIMESTAMP""",
                (group_id,),
            )
            conn.commit()
    except Exception as e:
        logger.debug("filter_on: %s", e)
    bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "filter_on"))
    call.data = f"group_filter_{group_id}"
    cb_group_filter_menu(call)


