@bot.message_handler(func=lambda m: m.chat.type == "private" and m.from_user and m.from_user.id in _filter_add_state and m.text)
@safe_handler
def msg_filter_add_word(message: Message):
    """Обработка введённого слова для добавления в фильтр группы."""
    uid = message.from_user.id
    with _state_lock:
        group_id = _filter_add_state.pop(uid, None)
    if group_id is None:
        return
    word = (message.text or "").strip().lower()
    if not word:
        bot.reply_to(message, "Слово не введено. Попробуйте снова из меню фильтра.")
        return
    if add_filter_word_for_group(group_id, word, action="delete", created_by=uid):
        bot.reply_to(message, f"✅ Слово «{word}» добавлено в фильтр группы.")
    else:
        bot.reply_to(message, "❌ Не удалось добавить слово (возможно, уже есть).")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("group_roles_"))
@safe_handler
def cb_group_roles_menu(call: CallbackQuery):
    """Меню ролей и полномочий группы."""
    try:
        group_id = int(call.data.replace("group_roles_", "").strip())
    except ValueError:
        try:
            bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        except Exception:
            pass
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    bot.answer_callback_query(call.id)
    lang = get_user_language(call.from_user.id)
    rows = execute_query(USERS_DB, "SELECT user_id, role FROM group_roles WHERE group_id = ? ORDER BY role DESC, user_id", (group_id,)) or []
    owner_row = execute_query(USERS_DB, "SELECT added_by_user_id FROM bot_groups WHERE chat_id = ?", (group_id,))
    owner_id = int(owner_row[0][0]) if owner_row and owner_row[0] else None
    owner_label = get_group_role_display_name(group_id, "owner", lang=lang)
    text = t(lang, "group_roles_title") + "\n\n" + t(lang, "group_roles_owner_added", owner_label=owner_label) + " "
    if owner_id:
        name, uname = _get_user_profile_brief(owner_id)
        text += f"{name or owner_id}" + (f" @{uname}" if uname else "") + "\n\n"
    text += t(lang, "group_roles_assigned") + "\n"
    for r in rows:
        if r[0] == owner_id:
            continue
        role_raw = (r[1] or "").strip().lower()
        role_emoji = "👑" if role_raw == "owner" else "🛡"
        role_display = get_group_role_display_name(group_id, role_raw or r[1], lang=lang)
        name, uname = _get_user_profile_brief(r[0])
        text += f"{role_emoji} {name or r[0]} — {role_display}\n"
    if not rows and not owner_id:
        text += "—\n"
    markup = InlineKeyboardMarkup()
    creator_id = get_chat_creator_id(group_id)
    is_owner = creator_id is not None and call.from_user.id == creator_id
    if is_owner:
        markup.add(InlineKeyboardButton(t(lang, "group_roles_btn_add_staff"), callback_data=f"role_add_{group_id}"))
        markup.add(InlineKeyboardButton(t(lang, "group_roles_btn_remove_staff"), callback_data=f"role_remove_{group_id}"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data=f"admin_group_{group_id}"))
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("role_remove_"))
@safe_handler
def cb_role_remove_list(call: CallbackQuery):
    """Список участников, у которых можно снять роль (кроме владельца). Только владелец группы."""
    try:
        group_id = int(call.data.replace("role_remove_", "").strip())
    except ValueError:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    creator_id = get_chat_creator_id(group_id)
    if creator_id is None or call.from_user.id != creator_id:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "group_roles_owner_only"), show_alert=True)
        return
    bot.answer_callback_query(call.id)
    lang = get_user_language(call.from_user.id)
    rows = execute_query(USERS_DB, "SELECT user_id, role FROM group_roles WHERE group_id = ? ORDER BY role DESC, user_id", (group_id,)) or []
    removable = [(r[0], r[1]) for r in rows if r[0] != creator_id]
    if not removable:
        text = t(lang, "group_roles_title") + "\n\n" + (t(lang, "group_roles_nobody_to_remove") or "Нет кого снять — только владелец в списке.")
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "back"), callback_data=f"group_roles_{group_id}"))
    else:
        text = t(lang, "group_roles_title") + "\n\n" + (t(lang, "group_roles_remove_hint") or "Выберите, у кого снять права:")
        markup = InlineKeyboardMarkup()
        for uid, role in removable[:25]:
            name, uname = _get_user_profile_brief(uid)
            label = (name or str(uid)) + (f" @{uname}" if uname else "") + f" — {role}"
            if len(label) > 35:
                label = (name or str(uid))[:20] + f" — {role}"
            markup.add(InlineKeyboardButton("➖ " + label, callback_data=f"role_revoke_{group_id}_{uid}"))
        markup.add(InlineKeyboardButton(t(lang, "back"), callback_data=f"group_roles_{group_id}"))
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("role_revoke_"))
@safe_handler
def cb_role_revoke(call: CallbackQuery):
    """Снять роль у участника. Только владелец. Нельзя снять владельца."""
    parts = (call.data or "").replace("role_revoke_", "").strip().split("_")
    if len(parts) != 2:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        return
    try:
        group_id, user_id = int(parts[0]), int(parts[1])
    except ValueError:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    creator_id = get_chat_creator_id(group_id)
    if creator_id is None or call.from_user.id != creator_id:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "group_roles_owner_only"), show_alert=True)
        return
    if user_id == creator_id:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "group_roles_cannot_remove_owner"), show_alert=True)
        return
    execute_query(USERS_DB, "DELETE FROM group_roles WHERE group_id = ? AND user_id = ?", (group_id, user_id))
    bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "group_roles_removed") or "✅ Права сняты.")
    call.data = f"group_roles_{group_id}"
    cb_group_roles_menu(call)


