def process_role_add_user(message: Message):
    """Обработка ввода ID/username после выбора роли при добавлении админа/модера."""
    user_id = message.from_user.id if message.from_user else 0
    if message.chat.type != "private":
        return
    data = get_temp_data(user_id, "role_add")
    if not data or not isinstance(data, dict):
        return
    group_id = data.get("group_id")
    role = data.get("role", "admin")
    if group_id is None:
        clear_temp_data(user_id, "role_add")
        return
    text = (message.text or "").strip()
    lang = get_user_language(user_id)
    if text in ("/cancel", "отмена", "cancel"):
        clear_temp_data(user_id, "role_add")
        bot.reply_to(message, t(lang, "cancel"))
        return
    target_uid = None
    if text.isdigit():
        target_uid = int(text)
    elif text.startswith("@"):
        username = text.lstrip("@")
        rows = execute_query(USERS_DB, "SELECT user_id FROM users WHERE LOWER(TRIM(username)) = LOWER(?) LIMIT 1", (username,))
        if rows and rows[0]:
            target_uid = int(rows[0][0])
        else:
            try:
                admins = bot.get_chat_administrators(group_id)
                for m in (admins or []):
                    u = getattr(m, "user", None)
                    if u and (getattr(u, "username", "") or "").strip().lower() == username.lower():
                        target_uid = u.id
                        break
                else:
                    target_uid = None
            except Exception:
                target_uid = None
    if target_uid is None:
        bot.reply_to(message, t(lang, "group_roles_invalid_user") or "❌ Укажите числовой ID или @username участника группы.")
        return
    creator_id = get_chat_creator_id(group_id)
    if target_uid == creator_id:
        bot.reply_to(message, t(lang, "group_roles_owner_already") or "❌ Владелец уже имеет полные права.")
        clear_temp_data(user_id, "role_add")
        return
    with database_connection(USERS_DB) as conn:
        conn.execute(
            """INSERT OR REPLACE INTO group_roles (group_id, user_id, role, assigned_at)
               VALUES (?, ?, ?, CURRENT_TIMESTAMP)""",
            (group_id, target_uid, role),
        )
        conn.commit()
    clear_temp_data(user_id, "role_add")
    name, _ = _get_user_profile_brief(target_uid)
    bot.reply_to(message, (t(lang, "group_roles_assigned_success") or "✅ Назначено: {name} — {role}").format(name=name or target_uid, role=role))
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "group_roles_back_menu"), callback_data=f"group_roles_{group_id}"))
    try:
        bot.send_message(message.chat.id, "👥 " + t(lang, "group_roles_title"), reply_markup=markup, parse_mode="Markdown")
    except Exception:
        pass


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("role_add_sel_"))
@safe_handler
def cb_role_add_select(call: CallbackQuery):
    """Выбор роли при добавлении: role_add_sel_{group_id}_{role} -> запрос ID пользователя."""
    raw = (call.data or "").replace("role_add_sel_", "").strip()
    parts = raw.split("_", 1)
    if len(parts) < 2:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        return
    try:
        group_id = int(parts[0])
        role = (parts[1] or "admin").strip().lower()
    except ValueError:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        return
    if role not in ("admin", "moderator", "senior_mod", "junior_mod"):
        role = "admin"
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    creator_id = get_chat_creator_id(group_id)
    if creator_id is None or call.from_user.id != creator_id:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "group_roles_owner_only"), show_alert=True)
        return
    save_temp_data(call.from_user.id, "role_add", {"group_id": group_id, "role": role})
    lang = get_user_language(call.from_user.id)
    hint = t(lang, "group_roles_send_user_id") or "Отправьте числовой ID пользователя Telegram (или @username)."
    bot.answer_callback_query(call.id)
    try:
        bot.edit_message_text(hint, call.message.chat.id, call.message.message_id, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, hint, parse_mode="Markdown")
    bot.register_next_step_handler(call.message, process_role_add_user)


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("group_settings_"))
@safe_handler
def cb_group_settings_menu(call: CallbackQuery):
    try:
        group_id = int(call.data.replace("group_settings_", "").strip())
    except ValueError:
        try:
            bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        except Exception:
            pass
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
