@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("voice_stats_"))
@safe_handler
def cb_voice_stats(call: CallbackQuery):
    try:
        group_id = int(call.data.replace("voice_stats_", "").strip())
    except ValueError:
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    bot.answer_callback_query(call.id)
    rows = execute_query(
        USERS_DB,
        "SELECT COUNT(*), COUNT(DISTINCT user_id), COALESCE(SUM(duration),0), COALESCE(AVG(processing_time),0) FROM voice_transcriptions WHERE group_id = ?",
        (group_id,),
    )
    model_row = execute_query(USERS_DB, "SELECT model_used FROM voice_transcriptions WHERE group_id = ? ORDER BY id DESC LIMIT 1", (group_id,))
    today_rows = execute_query(USERS_DB, "SELECT COUNT(*) FROM voice_transcriptions WHERE group_id = ? AND DATE(created_at) = DATE('now')", (group_id,))
    today = today_rows[0][0] if today_rows and today_rows[0] else 0
    total, users, total_dur, avg_time, pop_model = 0, 0, 0, 0, "—"
    if rows and rows[0]:
        r = rows[0]
        total = r[0] or 0
        users = r[1] or 0
        total_dur = r[2] or 0
        avg_time = r[3] or 0
    if model_row and model_row[0] and model_row[0][0]:
        pop_model = model_row[0][0]
    transcriber = get_voice_transcriber()
    ws = transcriber.get_stats() if transcriber else {}
    text = (
        f"📊 **Статистика транскрипций**\n\n"
        f"📅 Всего: {total}\n👥 Пользователей: {users}\n🎤 Длительность: {total_dur} сек\n"
        f"⚡ Среднее время: {avg_time:.0f} мс\n🤖 Модель: {pop_model}\n📈 Сегодня: {today}\n\n"
        f"🖥️ **faster-whisper:** обработано {ws.get('total_processed', 0)}, моделей в кеше: {len(ws.get('active_models', []))}"
    )
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("🔙 Назад", callback_data=f"voice_settings_{group_id}"))
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="Markdown")
    except Exception:
        bot.send_message(call.message.chat.id, text, reply_markup=markup, parse_mode="Markdown")


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("vfull_"))
@safe_handler
def cb_voice_show_full(call: CallbackQuery):
    """По кнопке «Показать полностью» отправляет полный текст расшифровки голосового в виде цитаты."""
    try:
        parts = call.data.replace("vfull_", "", 1).split("_", 1)
        if len(parts) != 2:
            bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "error_short"))
            return
        group_id, msg_id = int(parts[0]), int(parts[1])
        full_text = cache_get(f"voice_full_{group_id}_{msg_id}")
        if not full_text:
            bot.answer_callback_query(call.id, "Текст больше недоступен (истёк кэш).", show_alert=True)
            return
        def _escape_md(s: str) -> str:
            for ch, rep in (("\\", "\\\\"), ("_", "\\_"), ("*", "\\*"), ("`", "\\`"), ("[", "\\[")):
                s = s.replace(ch, rep)
            return s
        quoted = "\n".join("> " + line for line in _escape_md(full_text).split("\n"))
        if len(quoted) > 4000:
            quoted = quoted[:3990] + "\n\n_… обрезано_"
        bot.answer_callback_query(call.id)
        bot.send_message(
            call.message.chat.id,
            "📄 **Полная расшифровка:**\n\n" + quoted,
            parse_mode="Markdown",
            reply_to_message_id=call.message.message_id,
        )
    except (ValueError, TypeError) as e:
        logger.debug("cb_voice_show_full: %s", e)
        try:
            bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "error_short"))
        except Exception:
            pass


@bot.callback_query_handler(func=lambda call: call.data and (call.data.startswith("svc_del_on_") or call.data.startswith("svc_del_off_")))
@safe_handler
def cb_group_svc_del_toggle(call: CallbackQuery):
    """Вкл/выкл автоудаление системных уведомлений в группе."""
    try:
        if call.data.startswith("svc_del_on_"):
            group_id = int(call.data.replace("svc_del_on_", "").strip())
            value = 1
        else:
            group_id = int(call.data.replace("svc_del_off_", "").strip())
            value = 0
    except ValueError:
        try:
            bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
        except Exception:
            pass
        return
    if not _admin_group_can_manage(call.from_user.id, group_id):
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "no_access"))
        return
    try:
        with database_connection(USERS_DB) as conn:
            conn.execute(
                """INSERT INTO group_settings (group_id, delete_service_notifications, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP)
                   ON CONFLICT(group_id) DO UPDATE SET delete_service_notifications = ?, updated_at = CURRENT_TIMESTAMP""",
                (group_id, value, value),
            )
            conn.commit()
    except Exception as e:
        logger.debug("svc_del toggle: %s", e)
    status = "включено" if value else "выключено"
    bot.answer_callback_query(call.id, f"Автоудаление уведомлений {status}")
    call.data = f"group_settings_{group_id}"
    cb_group_settings_menu(call)


