def _split_admin_text(text: str, max_len: int = 3500) -> List[str]:
    """Разбивает текст на части не длиннее max_len по границам строк."""
    if len(text) <= max_len:
        return [text] if text else []
    parts = []
    current = []
    current_len = 0
    for line in text.split("\n"):
        if current_len + len(line) + 1 > max_len and current:
            parts.append("\n".join(current))
            current = []
            current_len = 0
        current.append(line)
        current_len += len(line) + 1
    if current:
        parts.append("\n".join(current))
    return parts


