def _rank_permissions_help_text(lang: str) -> str:
    """Текст-справка: список возможностей прав ранга с описаниями (по языку)."""
    lines = []
    for k in sorted(RankPermissions.PERMISSIONS.keys()):
        short = _perm_short_label(k, lang)
        desc = t(lang, f"perm_desc_{k}") if t(lang, f"perm_desc_{k}") != f"perm_desc_{k}" else RankPermissions.PERMISSIONS.get(k, k)
        lines.append(f"• **{short}** — {desc}")
    return "\n".join(lines)


def _perm_short_label(perm_key: str, lang: Optional[str] = None) -> str:
    """Короткое название права для кнопок (по языку)."""
    if lang:
        label = t(lang, f"perm_short_{perm_key}")
        if label != f"perm_short_{perm_key}":
            return label
    mapping = {
        "can_warn": "Warn",
        "can_unwarn": "Unwarn",
        "can_mute": "Mute",
        "can_unmute": "Unmute",
        "can_ban": "Ban",
        "can_unban": "Unban",
        "can_kick": "Kick",
        "can_pin": "Pin",
        "can_clear": "Clear",
        "can_manage_mods": "Mods",
        "can_manage_ranks": "Ranks",
        "can_view_logs": "Logs",
        "can_change_settings": "Settings",
        "can_manage_economy": "Economy",
        "can_give_coins": "GiveCoins",
        "can_take_coins": "TakeCoins",
        "can_manage_shop": "Shop",
        "can_manage_activity": "Activity",
        "can_run_cleanup": "Cleanup",
        "can_broadcast": "Broadcast",
        "can_manage_achievements": "Achv",
        "can_bypass_limits": "Bypass",
        "can_bypass_mute": "BypassMute",
        "can_see_hidden": "Hidden",
    }
    return mapping.get(perm_key, perm_key)


def _render_constructor_menu(call: CallbackQuery) -> None:
    """Основное меню конструктора."""
    lang = get_user_language(call.from_user.id)
    custom_aliases = get_custom_command_aliases()
    aliases_count = len(custom_aliases) if custom_aliases else 0
    emoji_cfg = settings.get("custom_emojis", {}) or {}
    if not isinstance(emoji_cfg, dict):
        emoji_cfg = {}
    emoji_count = len(emoji_cfg)

    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(t(lang, "constructor_button_text_btn"), callback_data="constructor_button_text"),
        InlineKeyboardButton(t(lang, "constructor_aliases_btn"), callback_data="constructor_aliases"),
        InlineKeyboardButton(t(lang, "constructor_modcfg_btn"), callback_data="constructor_modcfg"),
        InlineKeyboardButton(t(lang, "constructor_perms_btn"), callback_data="constructor_perms"),
        InlineKeyboardButton(t(lang, "constructor_emojis_btn"), callback_data="constructor_emojis"),
        InlineKeyboardButton(t(lang, "constructor_cmd_access_btn"), callback_data="constructor_cmd_access"),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_system"),
    )

    btn_preview = (BUTTON_TEXT or "").strip() or "—"
    mod_auto = "✅" if AUTO_MODERATE else "❌"
    mod_prof = "✅" if PROFANITY_ENABLED else "❌"
    mod_ban = "✅" if AUTO_BAN_ON_MAX_WARNINGS else "❌"

    text = (
        t(lang, "constructor_main_title") + "\n\n"
        "Здесь настраиваются интерфейс и поведение бота без правки кода: текст кнопки приглашения, альтернативные команды, модерация, права по рангам, кастомные эмодзи и доступ к командам.\n\n"
        "**Текущее состояние:**\n"
        f"• **Кнопка приглашения:** «{btn_preview}»\n"
        f"• **Алиасов команд:** {aliases_count}\n"
        f"• **Модерация:** автомод {mod_auto}, мат {mod_prof}, автобан {mod_ban} · max warn: {MAX_WARNINGS}, мут: {MUTE_DURATION} ч\n"
        f"• **Кастомных эмодзи:** {emoji_count} ключей\n"
        "• **Доступ команд:** по рангам и категориям (ниже)\n\n"
        "**Разделы:**\n"
        "• **Текст кнопки** — надпись на кнопке «Пригласить в чат» (например «Вступить», «Залететь»).\n"
        "• **Алиасы** — свои названия команд: например `инфо` вместо `chatinfo`.\n"
        "• **Модерация** — автомодерация, фильтр мата, автобан по варнам, лимит варнов, длительность мута.\n"
        "• **Права рангов** — какие действия доступны рангам 1–5 (кик, бан, рассылка и т.д.).\n"
        "• **Эмодзи** — подмена эмодзи по ключам (coins, vip, legend, rank_owner и др.).\n"
        "• **Доступ команд** — ограничение команд по рангам и категориям."
    )
    bot.edit_message_text(
        text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown",
    )


