def _render_perm_rank_editor(call: CallbackQuery, rank: str) -> None:
    """Меню прав конкретного ранга."""
    lang = get_user_language(call.from_user.id)
    perms = rank_permissions.get(rank, {})
    markup = InlineKeyboardMarkup(row_width=2)
    for perm_key in sorted(RankPermissions.PERMISSIONS.keys()):
        enabled = bool(perms.get(perm_key, False))
        mark = "✅" if enabled else "❌"
        new_val = "0" if enabled else "1"
        callback = f"conperm|{rank}|{perm_key}|{new_val}"
        markup.add(InlineKeyboardButton(f"{mark} {_perm_short_label(perm_key, lang)}", callback_data=callback))
    markup.add(InlineKeyboardButton(t(lang, "perm_back_to_ranks"), callback_data="constructor_perms"))

    help_block = _rank_permissions_help_text(lang)
    text = (
        t(lang, "perm_rank_editor_title", rank=rank) + "\n\n"
        + t(lang, "perm_rank_editor_hint") + "\n\n"
        + t(lang, "perm_rank_editor_help") + "\n" + help_block
    )
    bot.edit_message_text(
        text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown",
    )


