def get_content_welcome_text(lang: str) -> str:
    """Returns welcome text for the given language (from developer panel content)."""
    if lang == "en" and (WELCOME_TEXT_EN or "").strip():
        return WELCOME_TEXT_EN.strip()
    return (WELCOME_TEXT or "").strip()


def get_content_button_text(lang: str) -> str:
    """Returns button text for the given language (from developer panel content)."""
    if lang == "en" and (BUTTON_TEXT_EN or "").strip():
        return BUTTON_TEXT_EN.strip()
    return (BUTTON_TEXT or "").strip()


def _build_welcome_preview_content(user_id: int):
    """Собирает текст и клавиатуру для экрана «Приветствие и превью»."""
    lang = get_user_language(user_id)
    welcome_ru = _truncate_preserving_emoji(WELCOME_TEXT or "—", 200) + ("..." if len(WELCOME_TEXT or "") > 200 else "")
    welcome_en = _truncate_preserving_emoji(WELCOME_TEXT_EN or "—", 200) + ("..." if len(WELCOME_TEXT_EN or "") > 200 else "") if (WELCOME_TEXT_EN or "").strip() else ""
    status = "✅ есть" if PREVIEW_FILE_ID or PREVIEW_URL else "❌ нет"
    preview_type = "фото" if PREVIEW_FILE_ID else "ссылка" if PREVIEW_URL else "не установлено"
    block = "**🇷🇺 RU:**\n" + welcome_ru + "\n\n"
    if welcome_en:
        block += "**🇬🇧 EN:**\n" + welcome_en + "\n\n"
    text = (
        "📝 **Приветствие и превью**\n\n"
        "**Текст приветствия:**\n" + block +
        "**Превью:** " + status + " (" + preview_type + ")\n\n"
        + t(lang, "choose_action")
    )
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton("✏️ Изменить текст приветствия", callback_data="admin_edit_welcome"),
        InlineKeyboardButton("📤 Загрузить фото", callback_data="admin_upload_photo"),
        InlineKeyboardButton("🔗 Вставить ссылку", callback_data="admin_url_photo"),
        InlineKeyboardButton("🗑 Удалить превью", callback_data="admin_remove_preview"),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_content"),
    )
    return text, markup


