def process_admin_input(message: Message):
    """Обработка ввода от админа."""
    user_id = message.from_user.id
    action = get_temp_data(user_id, "action")
    text_lower = (message.text or "").strip().lower()

    # Если нажата кнопка быстрого доступа (Панель разработчика, Ком и т.д.) — отменяем текущий ввод и открываем меню
    if text_lower in OWNER_QUICK_BUTTON_TEXTS and user_id in DEVELOPER_IDS:
        clear_temp_data(user_id)
        owner_quick_buttons_handler(message)
        return

    if not action:
        bot.reply_to(message, "❌ Сессия истекла. Начни заново.")
        return

    global INVITE_LINK, WELCOME_TEXT, BUTTON_TEXT, PREVIEW_URL, PREVIEW_FILE_ID
    global WELCOME_TEXT_EN, BUTTON_TEXT_EN

    try:
        if action == "set_welcome":
            new_text = (message.text or "").strip() if message.text else ""
            if not new_text:
                bot.reply_to(message, "❌ Текст не получен. Отправь текст приветствия.", parse_mode="Markdown")
                clear_temp_data(user_id)
                return
            settings["welcome_text"] = new_text
            WELCOME_TEXT = new_text
            save_settings(settings)
            bot.reply_to(
                message,
                "✅ **Welcome text (RU) updated!** Translating to EN in background…",
                parse_mode="Markdown",
            )
            threading.Thread(
                target=_auto_translate_ru_to_en_and_save,
                args=(new_text, "welcome_text_en", message.chat.id, "\n_(EN version saved.)"),
                daemon=True,
            ).start()

        elif action == "set_link":
            new_link = (message.text or "").strip()
            if not new_link:
                bot.reply_to(message, "❌ Ссылка не получена. Отправь ссылку текстом.", parse_mode="Markdown")
                clear_temp_data(user_id)
                return
            settings["invite_link"] = new_link
            INVITE_LINK = new_link
            save_settings(settings)
            bot.reply_to(message, f"✅ **Ссылка обновлена!**\n\n{new_link}", parse_mode="Markdown")
        
        elif action == "set_button":
            new_text = (message.text or "").strip()[:64]
            if not new_text or new_text.startswith("/"):
                bot.reply_to(message, "❌ Текст кнопки не может быть пустым или командой. Отправь обычный текст.", parse_mode="Markdown")
                clear_temp_data(user_id)
                return
            settings["button_text"] = new_text
            BUTTON_TEXT = new_text
            save_settings(settings)
            bot.reply_to(
                message,
                f"✅ **Текст кнопки (RU) обновлён.**\n\nНовый текст: {new_text}",
                parse_mode="Markdown",
            )
            threading.Thread(
                target=_auto_translate_ru_to_en_and_save,
                args=(new_text, "button_text_en", message.chat.id, "\n_(EN сохранён.)"),
                daemon=True,
            ).start()
        
        elif action == "set_preview_photo":
            if message.photo:
                file_id = message.photo[-1].file_id
                settings["preview_file_id"] = file_id
                settings["preview_url"] = None
                PREVIEW_FILE_ID = file_id
                PREVIEW_URL = None
                save_settings(settings)
                bot.reply_to(message, "✅ **Превью установлено!**", parse_mode="Markdown")
                text, markup = _build_welcome_preview_content(user_id)
                bot.send_message(message.chat.id, text, reply_markup=markup, parse_mode="Markdown")
            else:
                bot.reply_to(message, "❌ Это не фото. Отправь изображение.", parse_mode="Markdown")
        
        elif action == "set_preview_url":
            url = (message.text or "").strip()
            if not url:
                bot.reply_to(message, "❌ Ссылка не получена. Отправь ссылку текстом.", parse_mode="Markdown")
                clear_temp_data(user_id)
                return
            settings["preview_url"] = url
            settings["preview_file_id"] = None
            PREVIEW_URL = url
            PREVIEW_FILE_ID = None
            save_settings(settings)
            bot.reply_to(message, "✅ **Ссылка на превью сохранена!**", parse_mode="Markdown")
    
    except Exception as e:
        err_msg = str(e) if e else "Неизвестная ошибка"
        bot.reply_to(message, f"❌ Ошибка: {err_msg}", parse_mode="Markdown")
    
    finally:
        clear_temp_data(user_id)

