def build_watermark_menu_content(user_id: Optional[int] = None) -> Tuple[str, InlineKeyboardMarkup]:
    """Builds watermark menu text and keyboard. user_id used for back button language."""
    lang = get_user_language(user_id) if user_id else "en"
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(f"🔄 Вкл/Выкл: {'✅' if watermark_settings['enabled'] else '❌'}", 
                            callback_data="watermark_toggle"),
        InlineKeyboardButton("📤 Загрузить картинку", callback_data="watermark_upload"),
        InlineKeyboardButton("🔆 Прозрачность", callback_data="watermark_opacity"),
        InlineKeyboardButton("📏 Размер", callback_data="watermark_size"),
        InlineKeyboardButton("📍 Позиция", callback_data="watermark_position"),
        InlineKeyboardButton("👁️ Предпросмотр", callback_data="watermark_preview"),
        InlineKeyboardButton("🗑 Удалить водяной знак", callback_data="watermark_delete"),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_content")
    )
    
    pos_names = {
        "bottom_right": "Правый нижний",
        "bottom_left": "Левый нижний",
        "top_right": "Правый верхний",
        "top_left": "Левый верхний",
        "center": "По центру"
    }
    
    status = "✅ Включён" if watermark_settings['enabled'] else "❌ Отключён"
    has_image = "✅" if (watermark_settings.get('file_id') or watermark_settings.get('local_path')) else "❌"
    position = pos_names.get(watermark_settings['position'], "Правый нижний")
    text = (
        f"🖼️ **Водяной знак**\n\n"
        f"**Статус:** {status}\n"
        f"**Изображение:** {has_image}\n"
        f"**Позиция:** {position}\n"
        f"**Размер:** {watermark_settings['size']}px\n"
        f"**Прозрачность:** {int(watermark_settings['opacity'] * 100)}%\n\n"
        + t(lang, "choose_action")
    )
    return text, markup


def send_watermark_menu(chat_id: int, user_id: Optional[int] = None) -> None:
    """Отправляет меню водяного знака отдельным сообщением."""
    text, markup = build_watermark_menu_content(user_id)
    bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")

