def process_watermark_image(message: Message):
    """Обработка загруженного водяного знака."""
    user_id = message.from_user.id
    
    if message.photo:
        file_id = message.photo[-1].file_id
    elif message.document and message.document.mime_type.startswith('image/'):
        file_id = message.document.file_id
    else:
        _lang = get_user_language(user_id)
        bot.reply_to(message, "❌ Отправьте изображение для водяного знака.")
        clear_temp_data(user_id)
        return
    
    # Сохраняем Telegram file_id и локальную копию файла,
    # чтобы watermark переживал перезапуски/обновления скрипта.
    watermark_settings['file_id'] = file_id
    watermark_settings['enabled'] = True
    try:
        WATERMARKS_DIR.mkdir(parents=True, exist_ok=True)
        file_info = bot.get_file(file_id)
        downloaded_file = bot.download_file(file_info.file_path)
        ext = Path(file_info.file_path).suffix.lower() if getattr(file_info, "file_path", None) else ".png"
        if ext not in {".png", ".jpg", ".jpeg", ".webp"}:
            ext = ".png"
        local_wm_path = WATERMARKS_DIR / f"current_watermark{ext}"
        with open(local_wm_path, "wb") as f:
            f.write(downloaded_file)
        watermark_settings["local_path"] = str(local_wm_path)
    except Exception as e:
        logger.error(f"Не удалось сохранить локальную копию watermark: {e}")

    _sync_watermark_settings_to_config()
    save_settings(settings)
    
    _lang = get_user_language(message.from_user.id)
    bot.reply_to(
        message,
        "✅ **" + t(_lang, "watermark_loaded") + "**\n\n" + t(_lang, "watermark_loaded_hint"),
        parse_mode="Markdown"
    )
    # Сразу возвращаем пользователя в меню раздела без лишних шагов.
    send_watermark_menu(message.chat.id, user_id)
    clear_temp_data(user_id)

