def get_chat_message_count_for_date(chat_id: int, date_str: str) -> int:
    """
    Возвращает общее количество сообщений в чате за указанную дату (исключая ботов).
    date_str: дата в формате "YYYY-MM-DD".
    """
    try:
        rows = execute_query(
            MESSAGE_STATS_DB,
            "SELECT user_id, count FROM message_counts WHERE chat_id = ? AND date = ?",
            (chat_id, date_str),
        ) or []
        total = 0
        for row in rows:
            if is_excluded_bot_user(int(row[0])):
                continue
            total += int(row[1] or 0)
        return total
    except Exception as e:
        logger.error("Ошибка get_chat_message_count_for_date: %s", e)
        return 0


def get_message_count_for_days(chat_id: int, days: int, user_id: Optional[int] = None) -> int:
    """
    Возвращает количество сообщений за период (в днях), исключая ботов.
    days=1 -> только сегодня.
    """
    try:
        if user_id is not None and is_excluded_bot_user(user_id):
            return 0

        if days <= 1:
            query = "SELECT user_id, count FROM message_counts WHERE chat_id=? AND date=date('now')"
            params: Tuple[Any, ...] = (chat_id,)
        else:
            query = "SELECT user_id, count FROM message_counts WHERE chat_id=? AND date>=date('now', ?)"
            params = (chat_id, f"-{days - 1} days")

        if user_id is not None:
            query += " AND user_id=?"
            params += (user_id,)

        rows = execute_query(MESSAGE_STATS_DB, query, params) or []
        total = 0
        for row in rows:
            uid = int(row[0])
            if is_excluded_bot_user(uid):
                continue
            total += int(row[1] or 0)
        return total
    except Exception as e:
        logger.error(f"Ошибка get_message_count_for_days: {e}")
        return 0


def get_distinct_active_users(chat_id: int, days: int = 7) -> int:
    """Возвращает число активных участников за период, исключая ботов."""
    try:
        if days <= 1:
            rows = execute_query(
                MESSAGE_STATS_DB,
                "SELECT DISTINCT user_id FROM message_counts WHERE chat_id=? AND date=date('now')",
                (chat_id,),
            ) or []
        else:
            rows = execute_query(
                MESSAGE_STATS_DB,
                "SELECT DISTINCT user_id FROM message_counts WHERE chat_id=? AND date>=date('now', ?)",
                (chat_id, f"-{days - 1} days"),
            ) or []
        return sum(1 for row in rows if not is_excluded_bot_user(int(row[0])))
    except Exception as e:
        logger.error(f"Ошибка get_distinct_active_users: {e}")
        return 0


def get_user_message_stats(user_id: int, chat_id: int) -> Dict[str, int]:
    """Возвращает статистику сообщений пользователя по конкретной группе (chat_id) — day/week/month/year/total."""
    if is_excluded_bot_user(user_id):
        return {"day": 0, "week": 0, "month": 0, "year": 0, "total": 0}
    try:
        result = execute_query(
            MESSAGE_STATS_DB,
            """SELECT COALESCE(SUM(count), 0)
               FROM message_counts
               WHERE user_id = ? AND chat_id = ?""",
            (user_id, chat_id),
        )
        total = int(result[0][0] or 0) if result and result[0] else 0
        return {
            "day": get_message_count_for_days(chat_id, 1, user_id=user_id),
            "week": get_message_count_for_days(chat_id, 7, user_id=user_id),
            "month": get_message_count_for_days(chat_id, 30, user_id=user_id),
            "year": get_message_count_for_days(chat_id, 365, user_id=user_id),
            "total": total,
        }
    except Exception as e:
        logger.error(f"Ошибка получения статистики пользователя {user_id}: {e}")
    return {"day": 0, "week": 0, "month": 0, "year": 0, "total": 0}


def _get_top_message_rows(chat_id: int, days: int, limit: Optional[int] = 5) -> List[Tuple[int, str, int]]:
    """Возвращает пользователей по сообщениям за период: (user_id, name, count). limit=None — весь список участников."""
    try:
        period_clause = "date = date('now')" if days == 1 else "date >= date('now', ?)"
        params: List[Any] = [chat_id]
        if days != 1:
            params.append(f"-{days - 1} days")
        if limit is not None:
            params.append(max(limit * 5, 40))

        query = f"""SELECT user_id, COALESCE(SUM(count), 0) AS total
                    FROM message_counts
                    WHERE chat_id = ? AND {period_clause}
                    GROUP BY user_id
                    ORDER BY total DESC"""
        if limit is not None:
            query += " LIMIT ?"
        result = execute_query(MESSAGE_STATS_DB, query, tuple(params))
        rows: List[Tuple[int, str, int]] = []
        if not result:
            return rows

        for row in result:
            user_id = int(row[0])
            if is_excluded_bot_user(user_id):
                continue
            total = int(row[1] or 0)
            try:
                member = bot.get_chat_member(chat_id, user_id)
                name = (member.user.first_name or f"ID{user_id}").replace("`", "")
            except Exception:
                name = f"ID{user_id}"
            name = get_user_display_name_in_bot(user_id, name)
            rows.append((user_id, name, total))
            if limit is not None and len(rows) >= limit:
                break
        return rows
    except Exception as e:
        logger.error(f"Ошибка получения таблицы топа сообщений: {e}")
        return []


def _format_top_table(title: str, rows: List[Tuple[str, int]]) -> str:
    """Форматирует таблицу топа для отправки в Markdown-кодблоке."""
    lines = [title, "№  Пользователь        Сообщений", "-- ------------------ ---------"]
    if not rows:
        lines.append(".. нет данных")
    else:
        for i, (name, count) in enumerate(rows, 1):
            lines.append(f"{i:>2} {name[:18]:<18} {count:>9}")
    return "```text\n" + "\n".join(lines) + "\n```"


def create_stats_animation(title: str, rows: List[Tuple[str, int]], subtitle: str = "") -> bytes:
    """Создаёт простую GIF-анимацию для статистики."""
    width, height = 900, 520
    frames: List[Image.Image] = []
    max_value = max((v for _, v in rows), default=1)
    steps = 10

    font_title = get_pil_font(36)
    font_sub = get_pil_font(20)
    font_row = get_pil_font(20)

    watermark_overlay = _load_watermark_overlay(watermark_settings)

    for step in range(1, steps + 1):
        img = Image.new("RGB", (width, height), color=(16, 22, 30))
        draw = ImageDraw.Draw(img)

        for y in range(height):
            c = (16 + y // 20, 22 + y // 20, 30 + y // 18)
            draw.line([(0, y), (width, y)], fill=c)

        draw.rectangle([0, 0, width, 78], fill=(34, 45, 60))
        draw.text((24, 24), title, fill=(245, 245, 245), font=font_title)
        if subtitle:
            draw.text((24, 84), subtitle, fill=(180, 190, 200), font=font_sub)

        start_y = 130
        bar_x0 = 430
        bar_x1 = 860
        row_h = 46

        for idx, (label, value) in enumerate(rows[:8], 1):
            y0 = start_y + (idx - 1) * row_h
            y1 = y0 + 36
            draw.rectangle([24, y0, 876, y1], fill=(29, 38, 52), outline=(60, 80, 110), width=1)
            draw.text((34, y0 + 8), f"{idx}. {label[:26]}", fill=(232, 236, 241), font=font_row)
            draw.text((350, y0 + 8), str(value), fill=(255, 216, 130), font=font_row)

            progress = (value / max_value) if max_value > 0 else 0
            animated = progress * (step / steps)
            bx = int(bar_x0 + (bar_x1 - bar_x0) * animated)
            draw.rectangle([bar_x0, y0 + 8, bar_x1, y0 + 28], fill=(45, 60, 82))
            draw.rectangle([bar_x0, y0 + 8, bx, y0 + 28], fill=(92, 170, 255))

        draw.text((24, height - 28), get_moscow_time().strftime("%d.%m.%Y %H:%M"), fill=(120, 130, 145), font=font_sub)
        _apply_watermark(img, watermark_overlay, watermark_settings)
        frames.append(img)

    out = io.BytesIO()
    frames[0].save(
        out,
        format="GIF",
        save_all=True,
        append_images=frames[1:],
        duration=90,
        loop=0,
        optimize=False,
    )
    out.seek(0)
    return out.getvalue()


def create_stats_preview_image(
    title: str,
    rows: List[Tuple[str, Any]],
    subtitle: str = "",
    allow_emoji: bool = False,
) -> bytes:
    """Статичная превью-картинка статистики (читаемая PNG, без GIF). Значения в rows приводятся к int.
    allow_emoji=True — не убирать эмодзи из заголовка, подзаголовка и подписей строк (для карточки пользователя с ником)."""
    width, height = 1200, 760
    img = Image.new("RGB", (width, height), color=(16, 22, 30))
    draw = ImageDraw.Draw(img)
    font_title = get_pil_font(46)
    font_sub = get_pil_font(24)
    font_row = get_pil_font(28)

    def _safe_text(t: str, max_len: int = 30) -> str:
        if not t:
            return ""
        s = str(t)[:max_len]
        return _strip_emoji_for_image(s) if not allow_emoji else s

    safe_rows: List[Tuple[str, int]] = []
    for label, val in (rows or [])[:9]:
        try:
            raw = str(label) if label else ""
            if allow_emoji:
                safe_label = _truncate_preserving_emoji(raw, 30)
            else:
                safe_label = _safe_text(raw, 30) or raw[:30]
            safe_rows.append((safe_label, int(val) if val is not None else 0))
        except (TypeError, ValueError):
            safe_rows.append((_truncate_preserving_emoji(str(label), 30) if allow_emoji else (str(label)[:30] if label else ""), 0))
    max_value = max((v for _, v in safe_rows), default=1)

    for y in range(height):
        c = (16 + y // 24, 22 + y // 24, 30 + y // 22)
        draw.line([(0, y), (width, y)], fill=c)

    draw.rectangle([0, 0, width, 92], fill=(34, 45, 60))
    title_str = _truncate_preserving_emoji(title or "", 60) if allow_emoji else (title or "")[:60]
    if allow_emoji:
        _draw_text_with_emoji(img, draw, 30, 26, title_str, font_title, (245, 245, 245), emoji_size=40)
    else:
        draw.text((30, 26), _safe_text(title, 60), fill=(245, 245, 245), font=font_title)
    if subtitle:
        sub_str = _truncate_preserving_emoji(subtitle or "", 80) if allow_emoji else (subtitle or "")[:80]
        if allow_emoji:
            _draw_text_with_emoji(img, draw, 30, 108, sub_str, font_sub, (180, 190, 200), emoji_size=24)
        else:
            draw.text((30, 108), _safe_text(subtitle, 80), fill=(180, 190, 200), font=font_sub)

    start_y = 160
    bar_x0 = 560
    bar_x1 = width - 48
    row_h = 64
    for idx, (label, value) in enumerate(safe_rows, 1):
        y0 = start_y + (idx - 1) * row_h
        y1 = y0 + 50
        draw.rectangle([28, y0, width - 32, y1], fill=(29, 38, 52), outline=(60, 80, 110), width=1)
        row_label = f"{idx}. {_truncate_preserving_emoji(label, 30) if allow_emoji else (label or '')[:30]}"
        if allow_emoji:
            _draw_text_with_emoji(img, draw, 42, y0 + 10, row_label, font_row, (232, 236, 241), emoji_size=26)
        else:
            draw.text((42, y0 + 10), row_label, fill=(232, 236, 241), font=font_row)
        draw.text((460, y0 + 10), str(value), fill=(255, 216, 130), font=font_row)

        progress = (value / max_value) if max_value > 0 else 0
        bx = int(bar_x0 + (bar_x1 - bar_x0) * progress)
        draw.rectangle([bar_x0, y0 + 12, bar_x1, y0 + 36], fill=(45, 60, 82))
        draw.rectangle([bar_x0, y0 + 12, bx, y0 + 36], fill=(92, 170, 255))

    draw.text((30, height - 36), get_moscow_time().strftime("%d.%m.%Y %H:%M"), fill=(120, 130, 145), font=font_sub)
    _apply_watermark(img, _load_watermark_overlay(watermark_settings), watermark_settings)

    out = io.BytesIO()
    img.save(out, format="PNG")
    out.seek(0)
    return out.getvalue()


def _send_png_as_document(
    chat_id: int,
    png_bytes: bytes,
    filename: str,
    caption: str,
    parse_mode: Optional[str] = "Markdown",
) -> Optional[Message]:
    """
    Отправляет PNG как документ (без сжатия Telegram), с подписью.
    Это решает проблему «в превью ничего не видно» из-за компрессии.
    """
    try:
        cap = (caption or "").strip()
        # Telegram caption лимит ~1024 символа; обрезаем по границе графемы, чтобы не резать эмодзи (❤️ = U+2764+FE0F)
        if len(cap) > 1000:
            cap = _truncate_preserving_emoji(cap, 997) + "…"
            parse_mode = None  # чтобы не ломать Markdown при обрезке
        doc = io.BytesIO(png_bytes or b"")
        doc.name = filename or "stats.png"
        return bot.send_document(chat_id, doc, caption=cap, parse_mode=parse_mode)
    except Exception as e:
        logger.error(f"Ошибка отправки PNG как document: {e}")
        return None

