@bot.callback_query_handler(func=lambda call: call.data == "stats_periods_config")
@admin_callback_only
@safe_handler
def stats_periods_config(call: CallbackQuery):
    """Настройка периодов статистики для превью."""
    current = ", ".join(str(x) for x in normalize_stats_periods(STATS_PERIOD_DAYS))
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="admin_stats"))
    bot.edit_message_text(
        "⚙️ **Периоды статистики**\n\n"
        f"Текущие периоды (дни): `{current}`\n\n"
        "Отправь новые значения через запятую.\n"
        "Пример: `1,3,7,30,90,365`\n"
        "Допустимо: 1..3650 дней, максимум 8 значений.",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown",
    )
    save_temp_data(call.from_user.id, "action", "stats_periods_set")
    bot.register_next_step_handler(call.message, process_stats_periods_input)
    bot.answer_callback_query(call.id)


@safe_handler
def process_stats_periods_input(message: Message):
    """Обработка ввода периодов статистики."""
    user_id = message.from_user.id
    action = get_temp_data(user_id, "action")
    text_lower = (message.text or "").strip().lower()

    # Если нажата кнопка быстрого доступа (Панель разработчика, Ком и т.д.) — отменяем ввод и открываем меню
    if text_lower in OWNER_QUICK_BUTTON_TEXTS and user_id in DEVELOPER_IDS:
        clear_temp_data(user_id)
        owner_quick_buttons_handler(message)
        return

    if action != "stats_periods_set":
        return
    try:
        periods = update_stats_periods(message.text or "")
        bot.reply_to(
            message,
            f"✅ Периоды статистики обновлены: `{', '.join(str(x) for x in periods)}`",
            parse_mode="Markdown",
        )
    except Exception as e:
        bot.reply_to(message, f"❌ Ошибка: {e}")
    finally:
        clear_temp_data(message.from_user.id)

def create_admin_stats_image(data: Dict[str, Any], watermark: Dict[str, Any]) -> bytes:
    """
    Создаёт изображение статистики для админ-панели с водяным знаком.
    """
    from PIL import Image, ImageDraw, ImageFont
    import io
    
    # Создаём изображение
    img = Image.new('RGB', (1000, 700), color=(18, 20, 25))
    draw = ImageDraw.Draw(img)
    
    # Загружаем шрифты с поддержкой кириллицы
    font_title = get_pil_font(44)
    font_normal = get_pil_font(28)
    font_stats = get_pil_font(22)
    
    # Градиентный фон
    for y in range(700):
        color = (int(18 + y * 0.04), int(20 + y * 0.04), int(25 + y * 0.04))
        draw.line([(0, y), (1000, y)], fill=color)
    
    # Заголовок
    draw.rectangle([0, 0, 1000, 80], fill=(35, 40, 55))
    draw.text((500, 40), "СТАТИСТИКА БОТА", fill=(255, 215, 0), font=font_title, anchor="mm")
    
    # Пользователи
    draw.text((50, 120), "Пользователи", fill=(200, 200, 200), font=font_normal)
    draw.text((50, 160), f"Всего: {data['users']}", fill=(255, 255, 255), font=font_stats)
    draw.text((50, 190), f"Получили ссылки: {data['notified']}", fill=(255, 255, 255), font=font_stats)
    draw.text((50, 220), f"Активных ссылок: {data['links']}", fill=(255, 255, 255), font=font_stats)
    
    # Экономика
    draw.text((350, 120), "Экономика", fill=(200, 200, 200), font=font_normal)
    draw.text((350, 160), f"Всего монет: {format_number(data['eco'].get('total_coins', 0))}", fill=(255, 215, 0), font=font_stats)
    draw.text((350, 190), f"Пользователей: {data['eco'].get('total_users', 0)}", fill=(255, 255, 255), font=font_stats)
    draw.text((350, 220), f"Ср. баланс: {format_number(data['eco'].get('avg_balance', 0))}", fill=(255, 255, 255), font=font_stats)
    
    # Игры
    draw.text((650, 120), "Игры", fill=(200, 200, 200), font=font_normal)
    draw.text((650, 160), f"Всего игр: {data['games'].get('total_games', 0)}", fill=(100, 200, 255), font=font_stats)
    draw.text((650, 190), f"Побед: {data['games'].get('total_wins', 0)}", fill=(100, 255, 100), font=font_stats)
    draw.text((650, 220), f"Игроков: {data['games'].get('unique_players', 0)}", fill=(255, 255, 255), font=font_stats)
    
    # Модерация
    draw.text((50, 300), "Модерация", fill=(200, 200, 200), font=font_normal)
    draw.text((50, 340), f"Предупреждений: {data['mod']['warnings']}", fill=(255, 100, 100), font=font_stats)
    draw.text((50, 370), f"Мутов: {data['mod']['mutes']}", fill=(255, 165, 0), font=font_stats)
    draw.text((50, 400), f"Банов: {data['mod']['bans']}", fill=(255, 0, 0), font=font_stats)
    
    # Транзакции
    draw.text((350, 300), "Транзакции", fill=(200, 200, 200), font=font_normal)
    draw.text((350, 340), f"За неделю: {data['eco'].get('transactions_week', 0)}", fill=(255, 255, 255), font=font_stats)
    draw.text((350, 370), f"Объём: {format_number(data['eco'].get('transaction_volume_week', 0))}", fill=(255, 215, 0), font=font_stats)
    
    # ===== ВОДЯНОЙ ЗНАК =====
    if watermark.get('enabled', False):
        try:
            file_id = watermark.get('file_id')
            if file_id:
                file_info = bot.get_file(file_id)
                downloaded_file = bot.download_file(file_info.file_path)
                watermark_img = Image.open(io.BytesIO(downloaded_file)).convert('RGBA')
                
                watermark_size = watermark.get('size', 100)
                watermark_img = watermark_img.resize((watermark_size, watermark_size))
                
                opacity = int(watermark.get('opacity', 0.3) * 255)
                watermark_img.putalpha(opacity)
                
                positions = {
                    'bottom_right': (img.width - watermark_img.width - 20, img.height - watermark_img.height - 20),
                    'bottom_left': (20, img.height - watermark_img.height - 20),
                    'top_right': (img.width - watermark_img.width - 20, 20),
                    'top_left': (20, 20),
                    'center': ((img.width - watermark_img.width) // 2, (img.height - watermark_img.height) // 2)
                }
                pos = positions.get(watermark.get('position', 'bottom_right'))
                img.paste(watermark_img, pos, watermark_img)
        except Exception as e:
            logger.warning("Ошибка водяного знака в админ-статистике: %s", e)
    # ===== КОНЕЦ ВОДЯНОГО ЗНАКА =====
    
    # Нижний колонтитул
    draw.text((500, 650), f"• {get_moscow_time().strftime('%d.%m.%Y %H:%M')} •", fill=(100, 100, 100), font=font_stats, anchor="mm")
    
    # Сохраняем
    img_bytes = io.BytesIO()
    img.save(img_bytes, format='PNG')
    img_bytes.seek(0)
    return img_bytes.getvalue()

