@bot.callback_query_handler(func=lambda call: call.data == "admin_reload")
@admin_callback_only
def admin_reload(call: CallbackQuery):
    """Перезагружает настройки из файла (все глобальные переменные из settings)."""
    user_id = call.from_user.id
