        global COINS_ENABLED, COINS_NAME, COINS_SIGN, COINS_START_BALANCE, COINS_MESSAGE_REWARD
        global COINS_DAILY_REWARD, COINS_DAILY_STREAK_BONUS, COINS_MAX_STREAK, COINS_TRANSFER_TAX, REFERRAL_COMMISSION_PERCENT, DEVELOPER_COMMISSION_PERCENT, PURCHASE_DONATION_TO_GROUP_PERCENT
        global TRANSFER_CONFIRM_THRESHOLD, TRANSFER_RATE_LIMIT_PER_MINUTE
        global DAILY_RANDOM_ENABLED, DAILY_RANDOM_MIN, DAILY_RANDOM_MAX
        global MESSAGE_REWARD_MIN_CHARS, MESSAGE_REWARD_COOLDOWN_SEC, MESSAGE_REWARD_MAX_PER_MINUTE, MESSAGE_REWARD_DUPLICATE_WINDOW_SEC
