@bot.callback_query_handler(func=lambda call: call.data == "admin_maintenance_toggle")
@admin_callback_only
def admin_maintenance_toggle(call: CallbackQuery):
    """Вкл/выкл режим техобслуживания (только владелец)."""
    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "owner_only"))
        return
    global MAINTENANCE_MODE
    MAINTENANCE_MODE = not MAINTENANCE_MODE
    settings["maintenance_mode"] = MAINTENANCE_MODE
    save_settings(settings)
    logger.info("[owner] maintenance_toggle via callback: mode=%s by user_id=%s", MAINTENANCE_MODE, call.from_user.id)
    _lang = get_user_language(call.from_user.id)
    status = "включён 🛠" if MAINTENANCE_MODE else "выключен ✅"
    if _lang == "en":
        status = "on 🛠" if MAINTENANCE_MODE else "off ✅"
    bot.answer_callback_query(call.id, t(_lang, "maintenance_status", status=status))
    markup = create_admin_keyboard(_lang)
    maintenance_text = "Maintenance mode is on. Users won't be able to use the bot until it's off." if _lang == "en" else "Обычные пользователи не смогут пользоваться ботом, пока режим включён."
    bot.edit_message_text(
        t(_lang, "admin_panel_title") + "\n\n🛠 **" + ("Maintenance" if _lang == "en" else "Техработы") + ":** " + status + "\n\n" + maintenance_text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


def _update_telegraph_commands() -> str:
    """Инфо для админки: ссылки на гайды на сайте бота (/commands, /commands/en, /commands/edit)."""
    try:
        from guide_site import COMMANDS_EDIT_PATH, COMMANDS_GUIDE_PATH_EN, COMMANDS_GUIDE_PATH_RU
    except ImportError:
        COMMANDS_GUIDE_PATH_RU, COMMANDS_GUIDE_PATH_EN, COMMANDS_EDIT_PATH = "/commands", "/commands/en", "/commands/edit"
    base = (os.getenv("WEBHOOK_URL") or "").strip().rstrip("/")
    lines: List[str] = ["✅ **Гайды команд** на сайте бота (`/commands`, `/commands/en`)."]
    if base:
        lines.append(f"• RU: {base}{COMMANDS_GUIDE_PATH_RU}")
        lines.append(f"• EN: {base}{COMMANDS_GUIDE_PATH_EN}")
        lines.append(f"• Редактор: {base}{COMMANDS_EDIT_PATH} — секрет `GUIDES_EDIT_SECRET` в `.env`")
        lines.append("Источник: `telegraph_guide_ru.md` / `telegraph_guide_en.md` или переопределение в настройках.")
    else:
        lines.append("⚠️ Не задан `WEBHOOK_URL` — укажите базовый URL бота в `.env`.")
    return "\n".join(lines)


def get_telegraph_commands_url(lang: Optional[str] = None) -> Optional[str]:
    """
    URL полного гайда: сайт бота (`WEBHOOK_URL` + `/commands` или `/commands/en`).
    Без `WEBHOOK_URL` — полные URL из settings: `telegraph_commands_url` / `telegraph_commands_url_en`.
    """
    try:
        from guide_site import COMMANDS_GUIDE_PATH_EN, COMMANDS_GUIDE_PATH_RU
    except ImportError:
        COMMANDS_GUIDE_PATH_RU = "/commands"
        COMMANDS_GUIDE_PATH_EN = "/commands/en"
    base = (os.getenv("WEBHOOK_URL") or "").strip().rstrip("/")
    if base:
        use_en = (lang or "").strip().lower() == "en"
        return base + (COMMANDS_GUIDE_PATH_EN if use_en else COMMANDS_GUIDE_PATH_RU)
    use_en = (lang or "").strip().lower() == "en"
    if use_en:
        url = (settings.get("telegraph_commands_url_en") or "").strip()
        if url:
            return url
    url = (settings.get("telegraph_commands_url") or "").strip()
    if url:
        return url
    return None


def _run_deploy_to_server() -> str:
    """Загружает файлы Telegram Invite Bot на сервер: копирует bot.py, translations.py и др. в папку (deploy_destination). Настройки и БД на сервере не трогаются."""
    deploy_script = BASE_DIR / "deploy_to_server.py"
    if not deploy_script.exists():
        return "❌ Скрипт deploy_to_server.py не найден в папке бота.\nДеплой возможен только при запуске из папки проекта."
    env = {**os.environ}
    deploy_dest = (settings.get("deploy_destination") or "").strip()
    if deploy_dest:
        env["DEPLOY_DEST"] = deploy_dest
    try:
        result = subprocess.run(
            [sys.executable, str(deploy_script), "--backup"],
            cwd=str(BASE_DIR),
            capture_output=True,
            text=True,
            timeout=120,
            env=env,
        )
        out = (result.stdout or "").strip()
        err = (result.stderr or "").strip()
        if result.returncode != 0:
            return f"❌ Деплой завершился с ошибкой (код {result.returncode})\n\n{out}\n{err}"[:4000]
        return f"✅ Деплой выполнен успешно.\n\n{out}\n{err}"[:4000]
    except subprocess.TimeoutExpired:
        return "❌ Таймаут деплоя (120 с)."
    except Exception as e:
        return f"❌ Ошибка запуска деплоя: {e}"


