@bot.callback_query_handler(func=lambda call: call.data == "admin_restart_bot")
@admin_callback_only
def admin_restart_bot(call: CallbackQuery):
    """Перезапуск: при launcher — горячая перезагрузка (/reload); иначе — завершение процесса для внешнего цикла."""
    if call.from_user.id not in DEVELOPER_IDS:
        bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "owner_only"))
        return
    logger.info("[owner] admin_restart_bot requested by user_id=%s", call.from_user.id)
    bot.answer_callback_query(call.id, t(get_user_language(call.from_user.id), "restarting"))

    # Под webhook — перезагрузка кода без перезапуска процесса
    if _webhook_reload_event is not None:
        _lang = get_user_language(call.from_user.id)
        bot.send_message(
            call.message.chat.id,
            t(_lang, "dev_reload_loading"),
            parse_mode="Markdown",
        )
        _webhook_reload_event.set()
        logger.info("Перезагрузка кода запрошена из админ-панели (кнопка «Перезапуск», webhook)")
        return
    # Под launcher — горячая перезагрузка (без 409)
    if _reload_event is not None:
        bot.send_message(
            call.message.chat.id,
            "🔄 Горячая перезагрузка... Состояние сохраняется, новый код подхватится через несколько секунд.",
            parse_mode="Markdown",
        )
        if monolith_reloader.request_reload():
            logger.info("Перезапуск запрошен из админ-панели (кнопка «Перезапуск») — горячая перезагрузка")
        else:
            bot.send_message(call.message.chat.id, "❌ Не удалось запустить перезагрузку.")
        return

    bot.send_message(
        call.message.chat.id,
        "🔄 Бот завершает работу для перезапуска.\n\n"
        "Если запускаешь через systemd с Restart=always — процесс поднимется автоматически.\n\n"
        "Иначе перезапусти вручную: `python main.py`",
        parse_mode="Markdown"
    )
    # Сохраняем уведомление об успехе — отправится после следующего запуска
    try:
        _lang = get_user_language(call.from_user.id)
        success_text = t(_lang, "dev_reload_success")
        execute_query(
            USERS_DB,
            "INSERT INTO pending_notifications (user_id, chat_id, message) VALUES (?, ?, ?)",
            (call.from_user.id, call.message.chat.id, success_text),
        )
    except Exception as e:
        logger.warning("Не удалось сохранить отложенное уведомление: %s", e)
    logger.info("Завершение по запросу из админ-панели (перезапуск)")
    os._exit(0)


