    """Меню управления модерацией."""
    user_id = call.from_user.id
    lang = get_user_language(user_id)
    bot.answer_callback_query(call.id)
    clear_temp_data(user_id, "action")
    markup = get_moderation_menu_keyboard(lang)
    
