@bot.callback_query_handler(func=lambda call: call.data == "moderation_stats")
@group_admin_callback_only
def moderation_stats(call: CallbackQuery):
    """Статистика модерации. Для админа группы — только его чат; для разработчика — глобально."""
    bot.answer_callback_query(call.id)
    chat_id = call.message.chat.id
    is_developer = call.from_user.id in DEVELOPER_IDS
    if is_developer:
        _wr = execute_query(MODERATION_DB, "SELECT COUNT(*) FROM warnings WHERE active=1")
        _mr = execute_query(MODERATION_DB, "SELECT COUNT(*) FROM mutes")
        _br = execute_query(MODERATION_DB, "SELECT COUNT(*) FROM bans")
        warnings_count = (_wr[0][0] or 0) if _wr and len(_wr) > 0 else 0
        mutes_count = (_mr[0][0] or 0) if _mr and len(_mr) > 0 else 0
        bans_count = (_br[0][0] or 0) if _br and len(_br) > 0 else 0
        last_actions = execute_query(
            MODERATION_DB,
            "SELECT action, date FROM moderation_log ORDER BY date DESC LIMIT 5"
        ) or []
    else:
        _wr = execute_query(MODERATION_DB, "SELECT COUNT(*) FROM warnings WHERE active=1 AND chat_id=?", (chat_id,))
        warnings_count = (_wr[0][0] or 0) if _wr and len(_wr) > 0 else 0
        _mr = execute_query(MODERATION_DB, "SELECT COUNT(*) FROM mutes WHERE chat_id=?", (chat_id,))
        mutes_count = (_mr[0][0] or 0) if _mr and len(_mr) > 0 else 0
        _br = execute_query(
            MODERATION_DB,
            "SELECT COUNT(*) FROM bans WHERE chat_id=? AND (expires IS NULL OR expires > datetime('now'))",
            (chat_id,)
        )
        bans_count = (_br[0][0] or 0) if _br and len(_br) > 0 else 0
        last_actions = execute_query(
            MODERATION_DB,
            "SELECT action, date FROM moderation_log WHERE chat_id=? ORDER BY date DESC LIMIT 5",
            (chat_id,)
        ) or []
    words_count = len(profanity_filter.words)
    
    actions_text = ""
    for action in last_actions:
        actions_text += f"• {action[0]} - {action[1][:16]}\n"
    
    lang = get_user_language(call.from_user.id)
    if not actions_text:
        actions_text = t(lang, "no_actions")
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "refresh"), callback_data="moderation_stats"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_moderation"))
    body = (
        t(lang, "mod_stats_title")
        + t(lang, "mod_stats_warnings", count=warnings_count)
        + t(lang, "mod_stats_mutes", count=mutes_count)
        + t(lang, "mod_stats_bans", count=bans_count)
        + t(lang, "mod_stats_words", count=words_count)
        + t(lang, "mod_stats_last", text=actions_text)
    )
    bot.edit_message_text(
        body,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


@bot.callback_query_handler(func=lambda call: call.data == "moderation_mods")
@group_admin_callback_only
def moderation_mods(call: CallbackQuery):
    """Управление персоналом (модераторы и админы). Парсинг прав Telegram: снятие ранга при снятии модерки, автовыдача только при реальных правах."""
    bot.answer_callback_query(call.id)
    clear_temp_data(call.from_user.id, "action")
    sync_ranks_with_telegram_admins(call.message.chat.id)

    staff_list = []
    lang = get_user_language(call.from_user.id)
    viewer_id = call.from_user.id
    group_chat_id = call.message.chat.id
    # Разработчик в списке — только по логике группы (если есть роль в группе), не как отдельный «Разработчик»
    if viewer_id in DEVELOPER_IDS:
        dev_display_rank = get_user_rank_for_display(ADMIN_CHAT_ID, "supergroup", chat_id=group_chat_id)
        if dev_display_rank >= 1:
            try:
                owner_member = bot.get_chat_member(group_chat_id, ADMIN_CHAT_ID)
                owner_name = owner_member.user.first_name if owner_member and owner_member.user else t(lang, "owner")
            except Exception:
                owner_name = t(lang, "owner")
            staff_list.append((ADMIN_CHAT_ID, owner_name, dev_display_rank))

    for user_id, rank in user_ranks.items():
        if rank >= 1 and user_id not in DEVELOPER_IDS:
            try:
                user = bot.get_chat_member(group_chat_id, user_id)
                name = user.user.first_name
                staff_list.append((user_id, name, rank))
            except Exception:
                continue

    text = t(lang, "staff_title") + "\n\n" + t(lang, "staff_desc")
    if staff_list:
        for uid, name, rank in staff_list:
            rank_name = get_group_rank_display_name(group_chat_id, rank, lang=lang)
            text += f"• {name} — {rank_name} (ID: `{uid}`)\n"
    else:
        text += t(lang, "no_staff")

    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "add_to_staff"), callback_data="moderation_add_mod"))
    markup.add(InlineKeyboardButton(t(lang, "remove_from_staff"), callback_data="moderation_remove_mod"))
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_moderation"))
    
    bot.edit_message_text(
        text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


