@safe_handler
def process_moderation_mod_input(message: Message):
    """Обработка ввода назначения/снятия модератора из админки."""
    action = get_temp_data(message.from_user.id, "action")
    if action not in {"moderation_add_mod", "moderation_remove_mod"}:
        return
    try:
        if action == "moderation_add_mod":
            parts = (message.text or "").split()
            if len(parts) < 2:
                bot.reply_to(message, "❌ Формат: `user_id ранг`", parse_mode="Markdown")
                return
            user_id = int(parts[0])
            rank = int(parts[1])
            if rank < 1 or rank > 4:
                bot.reply_to(message, "❌ Ранг должен быть от 1 до 4.")
                return
            if set_user_rank(user_id, rank, admin_id=message.from_user.id):
                bot.reply_to(message, f"✅ Пользователю `{user_id}` выдан ранг {rank} ({get_rank_name(rank)}).", parse_mode="Markdown")
            else:
                bot.reply_to(message, "❌ Не удалось выдать ранг.")
            return

        user_id = int((message.text or "").strip())
        if set_user_rank(user_id, 0, admin_id=message.from_user.id):
            bot.reply_to(message, f"✅ С пользователя `{user_id}` сняты права (Staff).", parse_mode="Markdown")
        else:
            bot.reply_to(message, "❌ Не удалось снять права.")
    except ValueError:
        bot.reply_to(message, "❌ Некорректные данные.")
    finally:
        clear_temp_data(message.from_user.id)


def _parse_duration_minutes(s: str, allow_permanent: bool = True):
    """
    Парсит строку длительности в минуты.
    Поддержка: 10m, 30m, 1h, 24h, 1d, 7d, 1w, 0/forever/навсегда (permanent).
    Returns: (minutes or None для «навсегда», error_str or None).
    """
    if not s or not isinstance(s, str):
        return None, None
    s = s.strip().lower()
    if allow_permanent and s in ("0", "forever", "навсегда", "permanent", "∞", "permanently"):
        return None, None
    m = re.match(r"^(\d+)\s*([mhdw])?$", s)
    if not m:
        return None, "invalid"
    num = int(m.group(1))
    unit = (m.group(2) or "m").lower()
    if num <= 0:
        return (None, None) if allow_permanent else (None, "invalid")
    mult = {"m": 1, "h": 60, "d": 24 * 60, "w": 7 * 24 * 60}
    minutes = num * mult.get(unit, 1)
    max_minutes = 365 * 24 * 60  # 1 год
    if minutes > max_minutes:
        minutes = max_minutes
    return minutes, None


def _moderation_target_from_reply(message: Message):
    """Возвращает (target_id, error_message). Ошибка — если нет ответа на сообщение или цель бот."""
    lang = get_user_language(message.from_user.id) if message.from_user else "ru"
    if not message.reply_to_message or not message.reply_to_message.from_user:
        return None, t(lang, "mod_reply_required")
    target = message.reply_to_message.from_user
    if getattr(target, "is_bot", False) or is_excluded_bot_user(target.id):
        return None, t(lang, "mod_cannot_target_bot")
    return target.id, None


_DURATION_SPECIAL = {"0", "forever", "навсегда", "permanent", "∞", "permanently"}


def _moderation_clean_token(token: str) -> str:
    return (token or "").strip().strip(",;:.!?")


def _moderation_is_duration_token(token: str, *, allow_permanent: bool) -> bool:
    s = (_moderation_clean_token(token) or "").lower()
    if not s:
        return False
    if allow_permanent and s in _DURATION_SPECIAL:
        return True
    # /7d, /10m, /1h, /3w etc
    return re.match(r"^\d+\s*[mhdw]$", s) is not None


def _moderation_split_targets_and_rest(tokens: List[str], *, require_at_prefix: bool) -> Tuple[List[str], List[str]]:
    """
    Splits leading tokens into "targets" and the remainder.
    require_at_prefix=True: targets are only tokens starting with '@' (recommended for /unwarn|/unmute|/unban to avoid ambiguity).
    """
    target_tokens: List[str] = []
    i = 0
    while i < len(tokens):
        tok = tokens[i].strip()
        if require_at_prefix:
            if tok.startswith("@"):
                target_tokens.append(tok)
                i += 1
                continue
            break
        if tok.startswith("@") or tok.isdigit():
            target_tokens.append(tok)
            i += 1
            continue
        break
    return target_tokens, tokens[i:]


def _moderation_token_to_user_id(chat_id: int, token: str, lang: str) -> Tuple[Optional[int], Optional[str]]:
    tok = _moderation_clean_token(token)
    if not tok:
        return None, t(lang, "mod_reply_required")
    if tok.startswith("@"):
        tok = tok[1:]
    if tok.isdigit():
        uid = int(tok)
        if is_excluded_bot_user(uid):
            return None, t(lang, "mod_cannot_target_bot")
        return uid, None

    # Resolve @username
    user_obj = find_user_by_username(chat_id, tok)
    if user_obj and getattr(user_obj, "id", None) is not None:
        uid = int(user_obj.id)
        if is_excluded_bot_user(uid):
            return None, t(lang, "mod_cannot_target_bot")
        return uid, None
    return None, t(lang, "mod_target_not_found")


def _moderation_resolve_user_tokens(chat_id: int, target_tokens: List[str], lang: str) -> Tuple[List[int], Optional[str]]:
    ids: List[int] = []
    for tok in target_tokens:
        uid, err = _moderation_token_to_user_id(chat_id, tok, lang)
        if err:
            return [], err
        if uid is not None:
            ids.append(uid)
    return ids, None


def _parse_bang_rank_command(text: str) -> Optional[tuple]:
    """
    Парсит команды вида !повысить, !!повысить @user, !!!понизить @u1 @u2 и т.д.
    RU: повысить, понизить, разжаловать. EN: promote, demote, strip.
    Количество «!» задаёт уровень: 1 = помощник (1), 2 = модератор (2), ..., 5 = владелец (5).
    После команды допускается текст (например @username). Возвращает ("promote"|"demote"|"strip", target_level) или None.
    """
    if not text or not isinstance(text, str):
        return None
    txt = text.strip()
    # Разрешаем в конце пробелы и любой текст (для "!повысить @user" или "!!promote @u1 @u2")
    m = re.match(r"^(!+)\s*(повысить|понизить|разжаловать|promote|demote|strip)(?:\s+.*)?$", txt, re.IGNORECASE)
    if not m:
        return None
    bang_count = len(m.group(1))
    cmd = m.group(2).lower()
    if bang_count < 1 or bang_count > 5:
        return None
    if cmd in ("повысить", "promote"):
        return ("promote", min(5, bang_count))
    if cmd in ("понизить", "demote"):
        return ("demote", max(0, bang_count - 1))
    if cmd in ("разжаловать", "strip"):
        return ("strip", 0)
    return None


def _get_bang_rank_targets(message: Message) -> tuple:
    """
    Возвращает (список user_id целей, None) или ([], ключ_ошибки).
    Цели: из reply_to_message или из entities (text_mention, mention через find_user_by_username).
    Исключаются боты.
    """
    chat_id = getattr(message, "chat", None) and getattr(message.chat, "id", None)
    if not chat_id:
        return [], "rank_no_targets"
    targets = []
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        u = message.reply_to_message.from_user
        if not getattr(u, "is_bot", True):
            targets.append(u.id)
    if not targets and getattr(message, "entities", None):
        text = (message.text or "")
        for entity in message.entities:
            tp = getattr(entity, "type", None)
            if tp == "text_mention" and getattr(entity, "user", None):
                uid = entity.user.id
                if not getattr(entity.user, "is_bot", True) and uid not in targets:
                    targets.append(uid)
            elif tp == "mention":
                off = getattr(entity, "offset", 0)
                length = getattr(entity, "length", 0)
                mention_text = text[off : off + length]
                user_obj = find_user_by_username(chat_id, mention_text)
                if user_obj and getattr(user_obj, "id", None) and not getattr(user_obj, "is_bot", False):
                    if user_obj.id not in targets:
                        targets.append(user_obj.id)
    if not targets:
        return [], "rank_no_targets"
    return targets, None


def _is_bang_rank_message(message: Message) -> bool:
    """True, если сообщение — команда вида !*повысить/понизить/разжаловать."""
    if not message or not getattr(message, "text", None):
        return False
    return _parse_bang_rank_command(message.text) is not None


@bot.message_handler(func=lambda m: m.chat and getattr(m.chat, "type", "") in ("group", "supergroup") and _is_bang_rank_message(m))
@safe_handler
def cmd_bang_rank(message: Message):
    """Обработка команд !повысить, !!понизить и т.д. Цели: ответ на сообщение или @user / @user1 @user2. Уровень по количеству «!» (1–5)."""
    if not message.from_user:
        return
    if not require_group_feature(message, "moderation", message.from_user.id):
        return
    if not require_group_moderation(message, "can_manage_ranks"):
        return
    targets, err_key = _get_bang_rank_targets(message)
    if err_key:
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, err_key))
        return
    parsed = _parse_bang_rank_command(message.text)
    if not parsed:
        return
    action, level = parsed
    lang = get_user_language(message.from_user.id)
    rank_label = t(lang, "rank_level_" + str(level))
    success_count = 0
    skipped_dev = 0
    for target_id in targets:
        if target_id in DEVELOPER_IDS and level != 6:
            skipped_dev += 1
            continue
        if action == "promote":
            if set_user_rank(target_id, level, admin_id=message.from_user.id):
                success_count += 1
        elif action == "demote":
            if set_user_rank(target_id, level, admin_id=message.from_user.id):
                success_count += 1
        elif action == "strip":
            if set_user_rank(target_id, 0, admin_id=message.from_user.id):
                success_count += 1
    if skipped_dev and not success_count:
        bot.reply_to(message, t(lang, "rank_cannot_change_dev"))
        return
    if success_count == 0:
        bot.reply_to(message, t(lang, "rank_set_fail") if action == "promote" else t(lang, "rank_demote_fail") if action == "demote" else t(lang, "rank_strip_fail"))
        return
    if success_count == 1 and len(targets) == 1:
        if action == "promote":
            bot.reply_to(message, t(lang, "rank_set_done", rank_name=rank_label))
        elif action == "demote":
            bot.reply_to(message, t(lang, "rank_demote_done", rank_name=rank_label))
        else:
            bot.reply_to(message, t(lang, "rank_strip_done"))
    else:
        bot.reply_to(message, t(lang, "rank_done_multi", count=success_count))


@bot.message_handler(commands=["warn", "варн", "kom_warn"])
@safe_handler
def cmd_warn(message: Message):
    """Предупреждение пользователю. Использование: /warn [причина] (ответом на сообщение). Доступно владельцу группы или по рангу."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "moderation", message.from_user.id):
        return
    if not require_group_moderation(message, "can_warn"):
        return
    lang = get_user_language(message.from_user.id)
    chat_id = message.chat.id
    max_w = get_effective_warn_limit(chat_id)
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    # Reply mode: legacy single-target behavior (reply sets target).
    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return
        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_warn"))
            return

        if get_warnings_count(target_id, chat_id) >= max_w:
            bot.reply_to(message, t(lang, "warn_limit_reached", max=max_w))
            return

        parts = (message.text or "").strip().split()
        # /warn [срок 7d/30d/0] [причина]
        reason = t(lang, "warn_default_reason")
        expires_days = 30
        if len(parts) > 1:
            mins, err_d = _parse_duration_minutes(parts[1], allow_permanent=True)
            if err_d is None:
                if mins is None:
                    expires_days = 0
                else:
                    expires_days = max(0, mins // (24 * 60)) or 30
                reason = " ".join(parts[2:]).strip() if len(parts) > 2 else t(lang, "warn_default_reason")
            else:
                reason = " ".join(parts[1:]).strip() if len(parts) > 1 else t(lang, "warn_default_reason")

        wid = add_warning(
            user_id=target_id,
            chat_id=chat_id,
            reason=reason,
            admin_id=message.from_user.id,
            expires_days=expires_days,
        )
        if wid:
            count = get_warnings_count(target_id, chat_id)
            if AUTO_BAN_ON_MAX_WARNINGS and count >= max_w:
                ok_bot, _ = bot_has_ban_rights(chat_id)
                if ok_bot:
                    add_ban(
                        user_id=target_id,
                        chat_id=chat_id,
                        admin_id=message.from_user.id,
                        reason=reason or t(lang, "warn_limit_reason", max=max_w),
                        duration_minutes=24 * 7 * 60,
                    )
                    bot.reply_to(message, t(lang, "warn_success_ban", count=count, max=max_w))
                else:
                    bot.reply_to(message, t(lang, "warn_success", count=count, max=max_w))
            else:
                bot.reply_to(message, t(lang, "warn_success", count=count, max=max_w))
        else:
            bot.reply_to(message, t(lang, "warn_fail"))
        return

    # Args mode: /warn [duration] @user1 @user2 ... [reason]
    parts = (message.text or "").strip().split()
    tokens = parts[1:]

    expires_days = 30
    reason = t(lang, "warn_default_reason")

    if tokens and not tokens[0].startswith("@") and _moderation_is_duration_token(tokens[0], allow_permanent=True):
        mins, err_d = _parse_duration_minutes(tokens[0], allow_permanent=True)
        if err_d is None:
            if mins is None:
                expires_days = 0
            else:
                expires_days = max(0, mins // (24 * 60)) or 30
            tokens = tokens[1:]

    target_tokens, rest_tokens = _moderation_split_targets_and_rest(tokens, require_at_prefix=False)
    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    reason = " ".join(rest_tokens).strip() if rest_tokens else t(lang, "warn_default_reason")
    for target_id in target_ids:
        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_warn"))
            continue

        if get_warnings_count(target_id, chat_id) >= max_w:
            bot.reply_to(message, t(lang, "warn_limit_reached", max=max_w))
            continue

        wid = add_warning(
            user_id=target_id,
            chat_id=chat_id,
            reason=reason,
            admin_id=message.from_user.id,
            expires_days=expires_days,
        )
        if not wid:
            bot.reply_to(message, t(lang, "warn_fail"))
            continue

        count = get_warnings_count(target_id, chat_id)
        if AUTO_BAN_ON_MAX_WARNINGS and count >= max_w:
            ok_bot, _ = bot_has_ban_rights(chat_id)
            if ok_bot:
                add_ban(
                    user_id=target_id,
                    chat_id=chat_id,
                    admin_id=message.from_user.id,
                    reason=reason or t(lang, "warn_limit_reason", max=max_w),
                    duration_minutes=24 * 7 * 60,
                )
                bot.reply_to(message, t(lang, "warn_success_ban", count=count, max=max_w))
            else:
                bot.reply_to(message, t(lang, "warn_success", count=count, max=max_w))
        else:
            bot.reply_to(message, t(lang, "warn_success", count=count, max=max_w))


@bot.message_handler(commands=["unwarn", "разварн", "снять_предупреждение", "kom_unwarn"])
@safe_handler
def cmd_unwarn(message: Message):
    """Снять предупреждение. Использование: /unwarn (ответом на сообщение) или /unwarn [id] (ответом). Доступно по праву can_unwarn."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_moderation(message, "can_unwarn"):
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    max_w = get_effective_warn_limit(chat_id)
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return
        parts = (message.text or "").split()
        warning_id = None
        if len(parts) > 1:
            try:
                warning_id = int(parts[1])
            except ValueError:
                warning_id = None
        reason = " ".join(parts[2:]).strip() if len(parts) > 2 else ""
        if remove_warning(target_id, chat_id, warning_id=warning_id, admin_id=message.from_user.id, reason=reason):
            count = get_warnings_count(target_id, chat_id)
            bot.reply_to(message, t(lang, "unwarn_success", count=count, max=max_w))
        else:
            bot.reply_to(message, t(lang, "unwarn_fail"))
        return

    parts = (message.text or "").strip().split()
    tokens = parts[1:]
    if not tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    if any(tok.startswith("@") for tok in tokens):
        target_tokens, rest = _moderation_split_targets_and_rest(tokens, require_at_prefix=True)
        warning_id = int(rest[0]) if rest and rest[0].isdigit() else None
        reason = " ".join(rest[1:]).strip() if warning_id is not None and len(rest) > 1 else (" ".join(rest).strip() if rest else "")
    else:
        # Legacy-style: /unwarn <user_id> [warning_id]
        target_tokens = [tokens[0]] if tokens[0].isdigit() else []
        rest = tokens[1:]
        warning_id = int(rest[0]) if rest and rest[0].isdigit() else None
        reason = " ".join(rest[1:]).strip() if warning_id is not None and len(rest) > 1 else ""

    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    for target_id in target_ids:
        ok = remove_warning(
            target_id,
            chat_id,
            warning_id=warning_id,
            admin_id=message.from_user.id,
            reason=reason or "",
        )
        if ok:
            count = get_warnings_count(target_id, chat_id)
            bot.reply_to(message, t(lang, "unwarn_success", count=count, max=max_w))
        else:
            bot.reply_to(message, t(lang, "unwarn_fail"))


@bot.message_handler(commands=["warnings", "варны", "предупреждения"])
@safe_handler
def cmd_warnings(message: Message):
    """Показать свои предупреждения в этом чате. Только в группе."""
    if not ensure_user_access(message, require_group=True):
        return
    user_id = message.from_user.id
    chat_id = message.chat.id
    lang = get_user_language(user_id)
    max_w = get_effective_warn_limit(chat_id)
    count = get_warnings_count(user_id, chat_id)
    warnings_list = get_user_warnings(user_id, chat_id, limit=10, active_only=True)
    text = t(lang, "warnings_list_title", count=count, max=max_w)
    if warnings_list:
        for w in warnings_list:
            reason = (w.get("reason") or "—")[:80]
            date_str = (w.get("date") or "")[:16] if w.get("date") else "—"
            text += f"• ID {w.get('id', '?')}: {reason}\n  📅 {date_str}\n\n"
    else:
        text += t(lang, "warnings_list_empty")
    bot.reply_to(message, text, parse_mode="Markdown")


@bot.message_handler(commands=["mute", "мут", "kom_mute"])
@safe_handler
def cmd_mute(message: Message):
    """Мут пользователя. Использование: /mute [часы] (ответом на сообщение). Доступно владельцу группы или по рангу."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "moderation", message.from_user.id):
        return
    if not require_group_moderation(message, "can_mute"):
        return
    lang = get_user_language(message.from_user.id)
    chat_id = message.chat.id
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    # Common checks
    ok_bot, err_bot = bot_has_restrict_rights(chat_id)
    if not ok_bot:
        bot.reply_to(message, err_bot)
        return

    duration_minutes = MUTE_DURATION * 60  # default: hours -> minutes
    reason = t(lang, "mute_default_reason")

    # Reply mode: single target (reply sets target).
    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return

        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_mute"))
            return

        parts = (message.text or "").strip().split()
        if len(parts) > 1:
            mins, err_d = _parse_duration_minutes(parts[1], allow_permanent=False)
            if err_d is None and mins is not None:
                duration_minutes = max(1, min(525600, mins))
                reason = " ".join(parts[2:]).strip() if len(parts) > 2 else t(lang, "mute_default_reason")
            else:
                reason = " ".join(parts[1:]).strip() if len(parts) > 1 else t(lang, "mute_default_reason")

        if ItemEffects.has_mute_protection(target_id):
            bot.reply_to(
                message,
                "🛡️ This user is protected from mute. Bot will not mute them." if lang == "en" else "🛡️ Этот пользователь под защитой от мута. Команда бота не замутит его.",
            )
            return

        if set_mute(target_id, chat_id, duration_minutes, message.from_user.id, reason=reason or t(lang, "mute_default_reason")):
            if duration_minutes < 60:
                bot.reply_to(message, t(lang, "mute_success_minutes", minutes=duration_minutes))
            else:
                bot.reply_to(message, t(lang, "mute_success", hours=round(duration_minutes / 60)))
        else:
            bot.reply_to(message, t(lang, "mute_fail"))
        return

    # Args mode: /mute [duration] @user1 @user2 ... [reason]
    parts = (message.text or "").strip().split()
    tokens = parts[1:]
    if tokens and not tokens[0].startswith("@") and _moderation_is_duration_token(tokens[0], allow_permanent=False):
        mins, err_d = _parse_duration_minutes(tokens[0], allow_permanent=False)
        if err_d is None and mins is not None:
            duration_minutes = max(1, min(525600, mins))
        tokens = tokens[1:]

    target_tokens, rest_tokens = _moderation_split_targets_and_rest(tokens, require_at_prefix=False)
    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    reason = " ".join(rest_tokens).strip() if rest_tokens else t(lang, "mute_default_reason")
    for target_id in target_ids:
        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_mute"))
            continue

        if ItemEffects.has_mute_protection(target_id):
            bot.reply_to(
                message,
                "🛡️ This user is protected from mute. Bot will not mute them." if lang == "en" else "🛡️ Этот пользователь под защитой от мута. Команда бота не замутит его.",
            )
            continue

        if set_mute(target_id, chat_id, duration_minutes, message.from_user.id, reason=reason or t(lang, "mute_default_reason")):
            if duration_minutes < 60:
                bot.reply_to(message, t(lang, "mute_success_minutes", minutes=duration_minutes))
            else:
                bot.reply_to(message, t(lang, "mute_success", hours=round(duration_minutes / 60)))
        else:
            bot.reply_to(message, t(lang, "mute_fail"))


@bot.message_handler(commands=["unmute", "размут", "kom_unmute"])
@safe_handler
def cmd_unmute(message: Message):
    """Снять мут с пользователя. Использование: /unmute (ответом на сообщение). Доступно владельцу группы или по рангу can_unmute."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_moderation(message, "can_unmute"):
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return
        parts = (message.text or "").split(maxsplit=1)
        reason = (parts[1].strip() if len(parts) > 1 else "") or ""
        if remove_mute(target_id, chat_id, message.from_user.id, reason=reason):
            bot.reply_to(message, t(lang, "unmute_success"))
        else:
            bot.reply_to(message, t(lang, "unmute_fail"))
        return

    parts = (message.text or "").strip().split()
    tokens = parts[1:]
    if not tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    # Args mode: /unmute @user1 @ID2 ... (recommended) or legacy: /unmute <user_id>
    if any(tok.startswith("@") for tok in tokens):
        target_tokens, rest = _moderation_split_targets_and_rest(tokens, require_at_prefix=True)
        reason = " ".join(rest).strip()
    else:
        target_tokens = [tokens[0]] if tokens and tokens[0].isdigit() else []
        reason = " ".join(tokens[1:]).strip() if len(tokens) > 1 else ""

    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    for target_id in target_ids:
        ok = remove_mute(target_id, chat_id, message.from_user.id, reason=reason or "")
        bot.reply_to(message, t(lang, "unmute_success") if ok else t(lang, "unmute_fail"))


@bot.message_handler(commands=["ban", "бан", "kom_ban"])
@safe_handler
def cmd_ban(message: Message):
    """Бан пользователя. Использование: /ban [часы] (ответом на сообщение). Доступно владельцу группы или по рангу."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_moderation(message, "can_ban"):
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    # Bot rights for ban
    ok_bot, err_bot = bot_has_ban_rights(chat_id)
    if not ok_bot:
        bot.reply_to(message, err_bot)
        return

    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return
        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_ban"))
            return

        parts = (message.text or "").strip().split()
        # Legacy: /ban [duration] [reason] in reply_mode
        duration_minutes = 24 * 7 * 60
        reason = t(lang, "ban_default_reason")
        if len(parts) > 1:
            mins, err_d = _parse_duration_minutes(parts[1], allow_permanent=True)
            if err_d is None:
                duration_minutes = mins  # None = permanent
                reason = " ".join(parts[2:]).strip() if len(parts) > 2 else t(lang, "ban_default_reason")
            else:
                reason = " ".join(parts[1:]).strip() if len(parts) > 1 else t(lang, "ban_default_reason")

        if duration_minutes is not None:
            duration_minutes = max(1, min(525600, duration_minutes))

        if duration_minutes is None:
            duration_suffix = t(lang, "ban_forever")
        elif duration_minutes < 60:
            duration_suffix = t(lang, "ban_duration_minutes", minutes=duration_minutes)
        else:
            duration_suffix = t(lang, "ban_duration", hours=round(duration_minutes / 60))

        if add_ban(
            target_id,
            chat_id,
            message.from_user.id,
            reason=reason or t(lang, "ban_default_reason"),
            duration_minutes=duration_minutes,
        ):
            bot.reply_to(message, t(lang, "ban_success", duration=duration_suffix))
        else:
            bot.reply_to(message, t(lang, "ban_fail"))
        return

    # Args mode: /ban [duration] @user1 @user2 ... [reason]
    parts = (message.text or "").strip().split()
    tokens = parts[1:]
    if not tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    duration_minutes: Optional[int] = 24 * 7 * 60
    reason = t(lang, "ban_default_reason")

    if tokens and not tokens[0].startswith("@") and _moderation_is_duration_token(tokens[0], allow_permanent=True):
        mins, err_d = _parse_duration_minutes(tokens[0], allow_permanent=True)
        if err_d is None:
            duration_minutes = mins  # None = permanent
            tokens = tokens[1:]

    target_tokens, rest_tokens = _moderation_split_targets_and_rest(tokens, require_at_prefix=False)
    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    reason = " ".join(rest_tokens).strip() if rest_tokens else t(lang, "ban_default_reason")

    if duration_minutes is not None:
        duration_minutes = max(1, min(525600, duration_minutes))

    if duration_minutes is None:
        duration_suffix = t(lang, "ban_forever")
    elif duration_minutes < 60:
        duration_suffix = t(lang, "ban_duration_minutes", minutes=duration_minutes)
    else:
        duration_suffix = t(lang, "ban_duration", hours=round(duration_minutes / 60))

    for target_id in target_ids:
        ok, err_msg = can_moderate(message.from_user.id, target_id, chat_id)
        if not ok:
            bot.reply_to(message, err_msg or t(lang, "mod_cannot_ban"))
            continue

        ok2 = add_ban(
            target_id,
            chat_id,
            message.from_user.id,
            reason=reason or t(lang, "ban_default_reason"),
            duration_minutes=duration_minutes,
        )
        bot.reply_to(message, t(lang, "ban_success", duration=duration_suffix) if ok2 else t(lang, "ban_fail"))


