@bot.message_handler(commands=['unban', 'разбан', 'kom_unban'])
@safe_handler
def cmd_unban(message: Message):
    """Снять бан с пользователя. Использование: /unban (ответом на сообщение). Только в группе."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_moderation(message, "can_unban"):
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    reply_mode = bool(message.reply_to_message and getattr(message.reply_to_message, "from_user", None))

    if reply_mode:
        target_id, err = _moderation_target_from_reply(message)
        if err:
            bot.reply_to(message, err)
            return
        parts = (message.text or "").split(maxsplit=1)
        reason = (parts[1].strip() if len(parts) > 1 else "") or ""
        if remove_ban(target_id, chat_id, message.from_user.id, reason=reason):
            bot.reply_to(message, t(lang, "unban_success"))
        else:
            bot.reply_to(message, t(lang, "unban_fail"))
        return

    parts = (message.text or "").strip().split()
    tokens = parts[1:]
    if not tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    # Args mode: /unban @ID1 @ID2 ... [reason]
    if any(tok.startswith("@") for tok in tokens):
        target_tokens, rest_tokens = _moderation_split_targets_and_rest(tokens, require_at_prefix=True)
        reason = " ".join(rest_tokens).strip()
    else:
        # Legacy: /unban <user_id> [reason]
        target_tokens = [tokens[0]] if tokens and tokens[0].isdigit() else []
        reason = " ".join(tokens[1:]).strip() if len(tokens) > 1 else ""

    if not target_tokens:
        bot.reply_to(message, t(lang, "mod_reply_required"))
        return

    target_ids, err = _moderation_resolve_user_tokens(chat_id, target_tokens, lang)
    if err:
        bot.reply_to(message, err)
        return

    for target_id in target_ids:
        ok = remove_ban(target_id, chat_id, message.from_user.id, reason=reason or "")
        bot.reply_to(message, t(lang, "unban_success") if ok else t(lang, "unban_fail"))


def _handle_moderation_report(message: Message) -> bool:
    """
    Обрабатывает репорт в личку бота: пересланное сообщение из группы или /report с ответом на пересланное.
    Уведомляет администрацию группы о репорте.
    Returns True если сообщение обработано как репорт.
    """
    if message.chat.type != "private" or not message.from_user:
        return False
    report_chat = None
    comment = ""
    reported_message = None
    if getattr(message, "forward_from_chat", None):
        report_chat = message.forward_from_chat
        comment = (message.caption or "").strip()
        reported_message = message
    elif message.reply_to_message and getattr(message.reply_to_message, "forward_from_chat", None):
        report_chat = message.reply_to_message.forward_from_chat
        parts = (message.text or "").strip().split(maxsplit=1)
        comment = (parts[1].strip() if len(parts) > 1 else "") or ""
        reported_message = message.reply_to_message
    else:
        return False
    if not report_chat or report_chat.id >= 0:
        return False
    report_chat_id = report_chat.id
    try:
        ch = bot.get_chat(report_chat_id)
        chat_title = getattr(ch, "title", None) or str(report_chat_id)
    except Exception:
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "report_bot_not_in_group"))
        return True
    admin_ids = get_group_admin_ids(report_chat_id)
    reporter_name = message.from_user.first_name or ""
    if getattr(message.from_user, "username", None):
        reporter_name += f" (@{message.from_user.username})"
    reporter_name = reporter_name.strip() or str(message.from_user.id)
    comment_str = comment if comment else ""
    lang = get_user_language(message.from_user.id)
    report_body = t(lang, "report_notify_body",
                    chat_title=chat_title,
                    reporter=reporter_name,
                    comment=comment_str or t(lang, "report_no_comment"))
    notified = 0
    for admin_id in admin_ids:
        if admin_id == message.from_user.id:
            continue
        try:
            bot.send_message(admin_id, report_body, parse_mode="Markdown")
            if reported_message:
                bot.forward_message(admin_id, message.chat.id, reported_message.message_id)
            notified += 1
        except Exception:
            pass
    bot.reply_to(message, t(lang, "report_sent", count=notified))
    return True


def _is_report_message(m):
    if m.chat.type != "private" or not m.from_user:
        return False
    if getattr(m, "forward_from_chat", None):
        return True
    if m.reply_to_message and getattr(m.reply_to_message, "forward_from_chat", None) and m.text:
        txt = m.text.strip().lower()
        return txt.startswith("/report") or txt.startswith("report") or txt.startswith("репорт")
    return False


@bot.message_handler(func=_is_report_message)
@safe_handler
def handle_moderation_report(message: Message):
    """Репорт в личку: пересланное сообщение из группы или ответ /report на пересланное — уведомление админов группы."""
    if _handle_moderation_report(message):
        return
    # Не репорт (например, личный чат переслан) — не перехватываем
    pass


