@bot.message_handler(commands=['setrules', 'установить_правила'])
@safe_handler
def cmd_setrules(message: Message):
    """Установить правила группы. Только админ/владелец. Использование: /setrules [текст правил]"""
    if not ensure_user_access(message, require_group=True):
        return
    if not has_group_admin_rights(message.from_user.id, message.chat.id):
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "groupadmin_only_owner"))
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    parts = (message.text or "").strip().split(maxsplit=1)
    rules_text = (parts[1].strip() if len(parts) > 1 else "").strip()
    if not rules_text:
        bot.reply_to(message, t(lang, "setrules_usage"))
        return
    if len(rules_text) > 4000:
        bot.reply_to(message, t(lang, "setrules_too_long"))
        return
    try:
        with database_connection(USERS_DB) as conn:
            cur = conn.execute(
                "UPDATE group_settings SET rules = ?, updated_at = CURRENT_TIMESTAMP WHERE group_id = ?",
                (rules_text, chat_id),
            )
            if cur.rowcount == 0:
                conn.execute(
                    "INSERT INTO group_settings (group_id, rules, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP)",
                    (chat_id, rules_text),
                )
            conn.commit()
        bot.reply_to(message, t(lang, "setrules_ok"))
    except Exception as e:
        logger.exception("setrules: %s", e)
        bot.reply_to(message, "❌ " + (t(lang, "setrules_error") or "Ошибка сохранения правил."))


@bot.message_handler(commands=['clear', 'очистить', 'очистка'])
@safe_handler
def cmd_clear(message: Message):
    """Очистить сообщения в чате. /clear [N] — последние N (по умолчанию 100); или ответом на сообщение — очистка сообщений этого пользователя. Только в группе. При clear_command_only_owner — только владелец группы."""
    if not ensure_user_access(message, require_group=True):
        return
    if not require_group_feature(message, "moderation", message.from_user.id):
        return
    if not require_group_moderation(message, "can_clear"):
        return
    chat_id = message.chat.id
    gs = get_group_settings(chat_id)
    if gs.get("clear_command_only_owner", True):
        role = get_user_role_in_group(message.from_user.id, chat_id)
        is_creator = get_chat_creator_id(chat_id) == message.from_user.id
        if role != "owner" and not is_creator and message.from_user.id not in DEVELOPER_IDS:
            bot.reply_to(message, "❌ Очистка чата доступна только владельцу группы.")
            return
    user_id = None
    limit = 100
    parts = (message.text or "").split()
    if message.reply_to_message and message.reply_to_message.from_user:
        user_id = message.reply_to_message.from_user.id
        if len(parts) > 1:
            try:
                limit = max(1, min(500, int(parts[1])))
            except (ValueError, IndexError):
                pass
    elif len(parts) > 1:
        try:
            limit = max(1, min(500, int(parts[1])))
        except (ValueError, IndexError):
            pass
    deleted = clear_messages(chat_id, user_id=user_id, limit=limit)
    lang = get_user_language(message.from_user.id)
    bot.reply_to(message, t(lang, "clear_success", count=deleted))


