@bot.callback_query_handler(func=lambda call: call.data == "moderation_words")
@group_admin_callback_only
def moderation_words(call: CallbackQuery):
    """Управление списком запрещённых слов."""
    bot.answer_callback_query(call.id)
    clear_temp_data(call.from_user.id, "action")
    words = profanity_filter.words
    
    words_list = "\n".join([f"• {w}" for w in words[:20]])
    if len(words) > 20:
        words_list += f"\n... и ещё {len(words) - 20}"
    
    markup = InlineKeyboardMarkup()
    markup.add(
        InlineKeyboardButton("➕ Добавить слово", callback_data="moderation_add_word"),
        InlineKeyboardButton("➖ Удалить слово", callback_data="moderation_remove_word"),
        InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="admin_moderation")
    )
    
    bot.edit_message_text(
        f"📝 **Запрещённые слова**\n\n"
        f"Всего слов: {len(words)}\n\n"
        f"{words_list}",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )

@bot.callback_query_handler(func=lambda call: call.data == "moderation_add_word")
@group_admin_callback_only
def moderation_add_word(call: CallbackQuery):
    """Добавление запрещённого слова."""
    bot.answer_callback_query(call.id)
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="moderation_words"))
    
    bot.edit_message_text(
        "➕ **Добавление запрещённого слова**\n\n"
        "Отправь слово для добавления в фильтр:",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )
    
    save_temp_data(call.from_user.id, "action", "add_banned_word")
    bot.register_next_step_handler(call.message, process_banned_word)

@bot.callback_query_handler(func=lambda call: call.data == "moderation_remove_word")
@group_admin_callback_only
def moderation_remove_word(call: CallbackQuery):
    """Удаление запрещённого слова."""
    bot.answer_callback_query(call.id)
    words = profanity_filter.words
    
    if not words:
        bot.answer_callback_query(call.id, "📭 Нет слов для удаления")
        moderation_words(call)
        return
    
    # Создаём кнопки для каждого слова
    markup = InlineKeyboardMarkup(row_width=3)
    for word in words[:15]:
        markup.add(InlineKeyboardButton(word, callback_data=f"moderation_del_{word}"))
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="moderation_words"))
    
    bot.edit_message_text(
        "➖ **Выбери слово для удаления:**",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )

@bot.callback_query_handler(func=lambda call: call.data.startswith('moderation_del_'))
@group_admin_callback_only
def moderation_del_word(call: CallbackQuery):
    """Удаление конкретного слова."""
    word = call.data.replace('moderation_del_', '')
    
    if profanity_filter.remove_word(word):
        bot.answer_callback_query(call.id, f"✅ Слово '{word}' удалено")
    else:
        bot.answer_callback_query(call.id, f"❌ Ошибка при удалении")
    
    # Возвращаемся к списку
    moderation_words(call)

def process_banned_word(message: Message):
    """Обработка добавления запрещённого слова."""
    user_id = message.from_user.id
    raw = (message.text or "").strip()
    # Команды (в т.ч. /groupadmin@botname) не добавляем в фильтр
    if raw.startswith("/"):
        clear_temp_data(user_id)
        lang = get_user_language(user_id)
        bot.reply_to(message, t(lang, "filter_cmd_ignored"))
        return
    word = raw.lower()
    
    if profanity_filter.add_word(word):
        bot.reply_to(message, f"✅ **Слово '{word}' добавлено в фильтр**", parse_mode="Markdown")
    else:
        bot.reply_to(message, f"❌ **Слово '{word}' уже существует**", parse_mode="Markdown")
    
    clear_temp_data(user_id)

