def get_economy_menu_keyboard(lang: str = "ru") -> InlineKeyboardMarkup:
    """Клавиатура раздела «Экономика и магазин» (подменю). Все подписи через t(lang, key)."""
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(t(lang, "economy_settings_btn"), callback_data="economy_settings"),
        InlineKeyboardButton(t(lang, "economy_stats_btn"), callback_data="economy_stats"),
    )
    markup.add(
        InlineKeyboardButton(t(lang, "economy_set_name_btn"), callback_data="economy_set_name"),
        InlineKeyboardButton(t(lang, "economy_give_coins_btn"), callback_data="economy_give_coins"),
    )
    markup.add(
        InlineKeyboardButton(t(lang, "back_to_admin_btn"), callback_data="admin_back"),
    )
    return markup


