@bot.callback_query_handler(func=lambda call: call.data.startswith('economy_toggle_'))
@admin_callback_only
def economy_toggle(call: CallbackQuery):
    """Переключение настроек экономики."""
    action = call.data.replace('economy_toggle_', '')
    
    global COINS_ENABLED, DAILY_RANDOM_ENABLED
    
    if action == "enabled":
        COINS_ENABLED = not COINS_ENABLED
        settings["coins_enabled"] = COINS_ENABLED
        save_settings(settings)
        bot.answer_callback_query(call.id, f"✅ Экономика: {'вкл' if COINS_ENABLED else 'выкл'}")
    elif action == "daily_random":
        DAILY_RANDOM_ENABLED = not DAILY_RANDOM_ENABLED
        DailyBonus.RANDOM_ENABLED = DAILY_RANDOM_ENABLED
        settings["daily_random_enabled"] = DAILY_RANDOM_ENABLED
        save_settings(settings)
        bot.answer_callback_query(call.id, f"✅ Daily random: {'вкл' if DAILY_RANDOM_ENABLED else 'выкл'}")
    
    economy_settings(call)


