@admin_callback_only
def economy_set_name(call: CallbackQuery):
    """Изменение названия валюты — одно поле обновляет отображение везде в боте."""
    lang = get_user_language(call.from_user.id)
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "back"), callback_data="admin_economy"))
    title = t(lang, "coin_name_screen_title")
    cur_name = t(lang, "coin_name_current_label")
    cur_sign = t(lang, "coin_name_sign_label")
    prompt = t(lang, "coin_name_prompt")
    bot.edit_message_text(
        f"{title}\n\n**{cur_name}:** {COINS_NAME}\n**{cur_sign}:** {COINS_SIGN}\n\n{prompt}",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )
    
    save_temp_data(call.from_user.id, "action", "set_coin_name")
    bot.register_next_step_handler(call.message, process_coin_name)

def process_coin_name(message: Message):
    """Обработка изменения названия монеты. Обновляет COINS_NAME/COINS_SIGN и все структуры, где они отображаются."""
    user_id = message.from_user.id
    global COINS_NAME, COINS_SIGN, COM_EMOJI
    
    new_name = (message.text or "").strip()
    if not new_name:
        lang = get_user_language(user_id)
        bot.reply_to(message, "❌ " + t(lang, "coin_name_enter_new"))
        clear_temp_data(user_id)
        return
    
    # Извлекаем эмодзи из строки (если есть) для обновления символа
    import re
    emoji_match = re.search(r'([\U0001F300-\U0001F9FF]|[\u2600-\u26FF])', new_name)
    
    if emoji_match:
        COINS_SIGN = emoji_match.group(0)
        COINS_NAME = new_name
    else:
        COINS_NAME = new_name
        # COINS_SIGN не меняем — меняется только название
    
    settings["coins_name"] = COINS_NAME
    settings["coins_sign"] = COINS_SIGN
    save_settings(settings)
    # Чтобы COM и TON не совпадали по эмодзи
    COM_EMOJI = "🪙" if COINS_SIGN == TON_EMOJI else COINS_SIGN
    # Обновить везде, где отображается название/символ валюты
    CURRENCY_EMOJI["COM"] = COM_EMOJI
    EMOJI_UI["COM"] = EMOJI_UI["COM_SMALL"] = EMOJI_UI["COM_MEDIUM"] = COM_EMOJI
    AVAILABLE_CURRENCIES["COM"]["name"] = COINS_NAME
    AVAILABLE_CURRENCIES["COM"]["symbol"] = AVAILABLE_CURRENCIES["COM"]["emoji"] = COM_EMOJI
    lang = get_user_language(user_id)
    ok_msg = t(lang, "coin_name_updated", name=COINS_NAME)
    bot.reply_to(message, ok_msg, parse_mode="Markdown")
    clear_temp_data(user_id)

