@bot.callback_query_handler(func=lambda call: call.data == "admin_games")
@admin_callback_only
def admin_games(call: CallbackQuery):
    """Меню управления играми."""
    stats = get_games_stats()
    
    lang = get_user_language(call.from_user.id)
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(t(lang, "admin_games_settings_btn"), callback_data="games_settings"),
        InlineKeyboardButton(t(lang, "admin_games_stats_btn"), callback_data="games_stats"),
        InlineKeyboardButton(t(lang, "admin_games_limits_btn"), callback_data="games_limits"),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_moderation_games")
    )
    
    by_game = stats.get('by_game', {})
    
    text = f"🎮 **{t(lang, 'admin_games_title')}**\n\n"
    text += f"**{t(lang, 'admin_games_total_stats')}**\n"
    text += f"• Всего игр: {stats.get('total_games', 0)}\n"
    text += f"• Побед: {stats.get('total_wins', 0)}\n"
    text += f"• Прибыль игроков: {format_number(stats.get('total_profit', 0))} {COM_EMOJI}\n"
    text += f"• Уникальных игроков: {stats.get('unique_players', 0)}\n\n"
    text += f"**По играм:**\n"
    
    for game, gstats in by_game.items():
        game_name = {"roulette": "🎲 Рулетка", "dice": "🎯 Кости", "duel": "⚔️ Дуэли"}.get(game, game)
        text += f"• {game_name}: {gstats.get('total', 0)} игр, прибыль {format_number(gstats.get('profit', 0))} {COM_EMOJI}\n"
    
    bot.edit_message_text(
        text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )

