@bot.callback_query_handler(func=lambda call: call.data == "games_stats")
@admin_callback_only
def games_stats(call: CallbackQuery):
    """Статистика игр."""
    stats = get_games_stats()
    
    # Игр за сегодня — только из games (в game_stats нет даты по дням)
    games_today = 0
    try:
        r = execute_query(ECONOMY_DB, "SELECT COUNT(*) FROM games WHERE date(date) = date('now')")
        if r and r[0]:
            games_today = int(r[0][0] or 0)
    except Exception:
        pass
    
    # Топ игроков и топ побед — из games, при пустой таблице из game_stats
    top_players = execute_query(
        ECONOMY_DB,
        """SELECT user_id, COUNT(*) as games FROM games GROUP BY user_id ORDER BY games DESC LIMIT 3"""
    ) or []
    top_winners = execute_query(
        ECONOMY_DB,
        """SELECT user_id, SUM(win) as wins FROM games GROUP BY user_id ORDER BY wins DESC LIMIT 3"""
    ) or []
    if not top_players and stats.get("total_games"):
        top_players = execute_query(
            ECONOMY_DB,
            """SELECT user_id, SUM(games_played) as games FROM game_stats GROUP BY user_id ORDER BY games DESC LIMIT 3"""
        ) or []
    if not top_winners and stats.get("total_games"):
        top_winners = execute_query(
            ECONOMY_DB,
            """SELECT user_id, SUM(games_won) as wins FROM game_stats GROUP BY user_id ORDER BY wins DESC LIMIT 3"""
        ) or []
    
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "refresh_btn"), callback_data="games_stats"))
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="admin_games"))
    
    # Формируем текст с топами
    top_players_text = ""
    for i, row in enumerate(top_players, 1):
        user_id = row[0]
        games = row[1]
        try:
            user = bot.get_chat_member(call.message.chat.id, user_id)
            name = user.user.first_name
        except Exception:
            name = f"ID:{user_id}"
        top_players_text += f"{i}. {name} - {games} игр\n"
    
    top_winners_text = ""
    for i, row in enumerate(top_winners, 1):
        user_id = row[0]
        wins = row[1]
        try:
            user = bot.get_chat_member(call.message.chat.id, user_id)
            name = user.user.first_name
        except Exception:
            name = f"ID:{user_id}"
        top_winners_text += f"{i}. {name} - {wins} побед\n"
    
    bot.edit_message_text(
        f"📊 **Статистика игр**\n\n"
        f"**Общая:**\n"
        f"• Всего игр: {stats.get('total_games', 0)}\n"
        f"• За сегодня: {games_today}\n"
        f"• Побед: {stats.get('total_wins', 0)}\n"
        f"• Процент побед: {stats.get('avg_winrate', 0):.1f}%\n"
        f"• Прибыль игроков: {format_number(stats.get('total_profit', 0))} {COM_EMOJI}\n"
        f"• Уникальных игроков: {stats.get('unique_players', 0)}\n\n"
        
        f"**По играм:**\n"
        f"• Рулетка: {stats.get('by_game', {}).get('roulette', {}).get('total', 0)} игр\n"
        f"• Кости: {stats.get('by_game', {}).get('dice', {}).get('total', 0)} игр\n"
        f"• Дуэли: {stats.get('by_game', {}).get('duel', {}).get('total', 0)} игр\n\n"
        
        f"**🏆 Топ игроков:**\n{top_players_text if top_players_text else 'Нет данных'}\n"
        f"**🎯 Топ победителей:**\n{top_winners_text if top_winners_text else 'Нет данных'}",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


