@bot.callback_query_handler(func=lambda call: call.data.startswith('games_toggle_'))
@admin_callback_only
def games_toggle(call: CallbackQuery):
    """Переключение настроек игр."""
    action = call.data.replace('games_toggle_', '')
    
    global GAMES_ENABLED, DUELS_ENABLED, AUTO_DELETE_GAMES
    
    if action == "enabled":
        GAMES_ENABLED = not GAMES_ENABLED
        settings["games_enabled"] = GAMES_ENABLED
        save_settings(settings)
        bot.answer_callback_query(call.id, f"✅ Игры: {'вкл' if GAMES_ENABLED else 'выкл'}")
    
    elif action == "duels":
        DUELS_ENABLED = not DUELS_ENABLED
        settings["duels_enabled"] = DUELS_ENABLED
        save_settings(settings)
        bot.answer_callback_query(call.id, f"✅ Дуэли: {'вкл' if DUELS_ENABLED else 'выкл'}")
    
    elif action == "autodelete":
        AUTO_DELETE_GAMES = not AUTO_DELETE_GAMES
        settings["auto_delete_games"] = AUTO_DELETE_GAMES
        save_settings(settings)
        bot.answer_callback_query(call.id, f"✅ Автоудаление: {'вкл' if AUTO_DELETE_GAMES else 'выкл'}")
    
    games_settings(call)


