@bot.callback_query_handler(func=lambda call: call.data.startswith('shop_list_next_'))
@admin_callback_only
def shop_list_next(call: CallbackQuery):
    """Следующая страница списка товаров."""
    offset = int(call.data.replace('shop_list_next_', '')) + 10
    items = ShopManager.get_all_items(include_out_of_stock=True)
    
    markup = InlineKeyboardMarkup(row_width=1)
    for item in items[offset:offset+10]:
        if getattr(item, "type", None) == "vip" and item.stock == -1:
            stock_text = ""
        else:
            stock_text = f" ({item.stock} шт.)" if item.stock > 0 else " (∞)" if item.stock == -1 else " (0)"
        button_text = f"{item.name} - {item.price}{COM_EMOJI}{stock_text}"
        markup.add(InlineKeyboardButton(button_text, callback_data=f"shop_edit_{item.id}"))
    
    nav_buttons = []
    if offset > 0:
        nav_buttons.append(InlineKeyboardButton("⬅️ Назад", callback_data=f"shop_list_prev_{offset}"))
    if offset + 10 < len(items):
        nav_buttons.append(InlineKeyboardButton("Далее ➡️", callback_data=f"shop_list_next_{offset}"))
    
    if nav_buttons:
        markup.row(*nav_buttons)
    
    markup.add(InlineKeyboardButton("🔙 В меню", callback_data="admin_shop"))
    
    text = f"📦 **Товары в магазине** (страница {offset//10 + 1})\n\n"
    for i, item in enumerate(items[offset:offset+10], offset+1):
        if getattr(item, "type", None) == "vip" and item.stock == -1:
            stock = "подписка"
        else:
            stock = f"в наличии: {item.stock}" if item.stock > 0 else "∞" if item.stock == -1 else "нет"
        text += f"{i}. **{item.name}**\n"
        text += f"   💰 {item.price} {COM_EMOJI} | 📦 {stock}\n"
    
    bot.edit_message_text(
        text,
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


