@bot.callback_query_handler(func=lambda call: call.data == "shop_stats")
@admin_callback_only
def shop_stats(call: CallbackQuery):
    """Статистика магазина."""
    stats = get_shop_stats()
    items = ShopManager.get_all_items(include_out_of_stock=True)
    
    # Получаем топ продаж
    top_selling = execute_query(
        ECONOMY_DB,
        """SELECT item_id, COUNT(*) as sold 
           FROM inventory 
           GROUP BY item_id 
           ORDER BY sold DESC 
           LIMIT 3"""
    ) or []
    
    top_selling_text = ""
    for row in top_selling:
        item_id = row[0]
        sold = row[1]
        item = ShopManager.get_item(item_id)
        if item:
            top_selling_text += f"• {item.name} - {sold} шт.\n"
    
    if not top_selling_text:
        top_selling_text = "Нет продаж\n"
    
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("🔄 Обновить", callback_data="shop_stats"))
    markup.add(InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data="admin_shop"))
    
    bot.edit_message_text(
        f"📊 **Статистика магазина**\n\n"
        f"**Товары:**\n"
        f"• Всего: {stats.get('total_items', 0)}\n"
        f"• В наличии: {stats.get('in_stock', 0)}\n"
        f"• Нет в наличии: {stats.get('out_of_stock', 0)}\n"
        f"• Бесконечные: {stats.get('unlimited', 0)}\n\n"
        
        f"**Цены:**\n"
        f"• Минимальная: {stats.get('min_price', 0)} {COM_EMOJI}\n"
        f"• Максимальная: {stats.get('max_price', 0)} {COM_EMOJI}\n\n"
        
        f"**Продажи (30 дней):**\n"
        f"• Количество: {stats.get('purchases_30d', 0)}\n"
        f"• Оборот: {format_number(stats.get('volume_30d', 0))} {COM_EMOJI}\n\n"
        
        f"**🏆 Топ продаж:**\n{top_selling_text}",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )


