def process_add_shop_item(message: Message):
    """Обработка добавления товара."""
    user_id = message.from_user.id
    if get_temp_data(user_id, "action") != "add_shop_item":
        return
    clear_temp_data(user_id)
    text = (message.text or "").strip()
    if not text or text.startswith("/"):
        bot.reply_to(message, "❌ Отправь данные в формате: `название | описание | цена | количество | тип | данные`", parse_mode="Markdown")
        return
    try:
        # Парсим введённые данные
        parts = [p.strip() for p in text.split('|')]
        if len(parts) < 6:
            raise ValueError("Недостаточно данных")
        
        name = parts[0]
        description = parts[1]
        price = int(parts[2])
        stock = int(parts[3])
        item_type = parts[4]
        
        # Парсим JSON данные
        try:
            data = json.loads(parts[5])
        except Exception:
            data = {}
        
        # Добавляем товар
        item_id = ShopManager.add_item(
            name=name,
            description=description,
            price=price,
            stock=stock,
            item_type=item_type,
            data=data,
            admin_id=user_id
        )
        
        if item_id:
            bot.reply_to(
                message,
                f"✅ **Товар успешно добавлен!**\n\n"
                f"ID: {item_id}\n"
                f"Название: {name}\n"
                f"Цена: {price} {COM_EMOJI}",
                parse_mode="Markdown"
            )
        else:
            bot.reply_to(message, "❌ Ошибка при добавлении товара")
    
    except ValueError as e:
        bot.reply_to(
            message,
            f"❌ Ошибка формата: {e}\n\n"
            f"Используй формат:\n"
            f"`название | описание | цена | количество | тип | данные`",
            parse_mode="Markdown"
        )
    except Exception as e:
        bot.reply_to(message, f"❌ Ошибка: {e}")
    
    markup = InlineKeyboardMarkup()
    lang = get_user_language(message.from_user.id)
    markup.add(InlineKeyboardButton(t(lang, "admin_back_to_shop"), callback_data="admin_shop"))
    try:
        bot.send_message(message.chat.id, t(lang, "choose_action"), reply_markup=markup)
    except Exception:
        pass


