@admin_callback_only
def shop_quick_price(call: CallbackQuery):
    """Быстрая установка предустановленной цены."""
    try:
        payload = call.data.replace('shop_quick_price_', '')
        item_id_str, price_str = payload.split('_', 1)
        item_id = int(item_id_str)
        price = int(price_str)
    except Exception:
        bot.answer_callback_query(call.id, "❌ Ошибка")
        return

    if price <= 0:
        bot.answer_callback_query(call.id, "❌ Цена должна быть > 0")
        return

    success = ShopManager.update_item(item_id=item_id, price=price, admin_id=call.from_user.id)
    clear_temp_data(call.from_user.id)
    bot.answer_callback_query(call.id, f"✅ Цена: {price} {COM_EMOJI}" if success else "❌ Ошибка")
    # Обновляем экран редактирования
    old_data = call.data
    call.data = f"shop_edit_{item_id}"
    shop_edit_item(call)
    call.data = old_data


