def process_shop_edit(message: Message):
    """Обработка редактирования товара."""
    user_id = message.from_user.id
    item_id = get_temp_data(user_id, "edit_item_id")
    field = get_temp_data(user_id, "edit_field")
    
    if not item_id or not field:
        bot.reply_to(message, "❌ Сессия истекла")
        clear_temp_data(user_id)
        return
    
    try:
        value = message.text.strip()
        
        if field == "price" or field == "stock":
            value = int(value)
            if field == "price" and value <= 0:
                bot.reply_to(message, "❌ Цена должна быть положительным числом")
                return
        
        # Обновляем товар
        success = ShopManager.update_item(
            item_id=item_id,
            **{field: value},
            admin_id=user_id
        )
        
        if success:
            bot.reply_to(message, f"✅ Поле '{field}' успешно обновлено!")
        else:
            bot.reply_to(message, "❌ Ошибка при обновлении")
    
    except ValueError:
        bot.reply_to(message, f"❌ Неверный формат. Для {field} нужно число")
    except Exception as e:
        bot.reply_to(message, f"❌ Ошибка: {e}")
    
    clear_temp_data(user_id)


@bot.message_handler(commands=['shop_prices'])
@admin_only
@safe_handler
def cmd_shop_prices(message: Message):
    """Показать все товары и цены (для админов/разработчика)."""
    items = ShopManager.get_all_items(include_out_of_stock=True)
    if not items:
        bot.reply_to(message, "🛒 Товаров нет.")
        return
    lines = ["🛒 **ТОВАРЫ И ЦЕНЫ**", ""]
    for item in items:
        stock_text = "∞" if item.stock == -1 else str(item.stock)
        lines.append(f"#{item.id}: **{item.name}**")
        lines.append(f"   💰 {item.price} {COM_EMOJI} | 📦 {stock_text}")
        lines.append("")
    bot.reply_to(message, "\n".join(lines[:200]), parse_mode="Markdown")


