        InlineKeyboardButton("🎥 Видео", callback_data="broadcast_type_video"),
        InlineKeyboardButton("👁️ Предпросмотр", callback_data="broadcast_preview"),
        InlineKeyboardButton("📤 Отправить рассылку", callback_data="broadcast_send"),
