@bot.callback_query_handler(func=lambda call: call.data.startswith("settings_"))
@admin_callback_only
@safe_handler
def settings_toggle_callback(call: CallbackQuery):
    """Обработчик кнопок общих настроек."""
    global AUTO_MODERATE, COINS_ENABLED, GAMES_ENABLED, AUTO_DELETE_GAMES
    global COLLECT_STATS, LANGUAGE, DELETE_SERVICE_NOTIFICATIONS

    data = call.data
    admin_lang = get_user_language(call.from_user.id)
    state_on = t(admin_lang, "setting_on")
    state_off = t(admin_lang, "setting_off")

    if data == "settings_auto_moderate":
        AUTO_MODERATE = not AUTO_MODERATE
        settings["auto_moderate"] = AUTO_MODERATE
        toast = t(admin_lang, "settings_toast_auto_mod", state=state_on if AUTO_MODERATE else state_off)
    elif data == "settings_economy":
        COINS_ENABLED = not COINS_ENABLED
        settings["coins_enabled"] = COINS_ENABLED
        toast = t(admin_lang, "settings_toast_economy", state=state_on if COINS_ENABLED else state_off)
    elif data == "settings_games":
        GAMES_ENABLED = not GAMES_ENABLED
        settings["games_enabled"] = GAMES_ENABLED
        toast = t(admin_lang, "settings_toast_games", state=state_on if GAMES_ENABLED else state_off)
    elif data == "settings_auto_delete":
        AUTO_DELETE_GAMES = not AUTO_DELETE_GAMES
        settings["auto_delete_games"] = AUTO_DELETE_GAMES
        toast = t(admin_lang, "settings_toast_auto_del", state=state_on if AUTO_DELETE_GAMES else state_off)
    elif data == "settings_service_notifications":
        DELETE_SERVICE_NOTIFICATIONS = not DELETE_SERVICE_NOTIFICATIONS
        settings["delete_service_notifications"] = DELETE_SERVICE_NOTIFICATIONS
        toast = t(admin_lang, "settings_toast_service", state=state_on if DELETE_SERVICE_NOTIFICATIONS else state_off)
    elif data == "settings_stats":
        COLLECT_STATS = not COLLECT_STATS
        settings["collect_stats"] = COLLECT_STATS
        toast = t(admin_lang, "settings_toast_stats", state=state_on if COLLECT_STATS else state_off)
    elif data == "settings_language":
        # Подменю выбора языка: две кнопки (Русский / English) и Назад
        lang = get_user_language(call.from_user.id)
        text = t(lang, "lang_select")
        markup = InlineKeyboardMarkup(row_width=1)
        markup.add(
            InlineKeyboardButton(t("ru", "lang_ru"), callback_data="admin_lang_ru"),
            InlineKeyboardButton(t("en", "lang_en"), callback_data="admin_lang_en"),
            InlineKeyboardButton(t(lang, "back"), callback_data="admin_settings"),
        )
        try:
            bot.edit_message_text(
                text,
                call.message.chat.id,
                call.message.message_id,
                reply_markup=markup,
                parse_mode="Markdown",
            )
        except Exception as e:
            logger.debug("edit_message_text language submenu: %s", e)
        bot.answer_callback_query(call.id)
        return
    else:
        bot.answer_callback_query(call.id, t(admin_lang, "settings_unknown"))
        return

    save_settings(settings)
    admin_settings(call)
    bot.answer_callback_query(call.id, toast)


