def _tail_text_file(path: Path, max_lines: int = 30) -> List[str]:
    """Возвращает последние строки файла (без падения на ошибках чтения)."""
    try:
        if not path.exists():
            return []
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()
        return [line.rstrip("\n") for line in lines[-max_lines:]]
    except Exception as e:
        logger.error(f"Ошибка чтения лога {path}: {e}")
        return []


def _render_logs_page(title: str, lines: List[str], refresh_cb: str, user_id: int = 0) -> Tuple[str, InlineKeyboardMarkup]:
    """Формирует текст и клавиатуру страницы логов."""
    lang = get_user_language(user_id)
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(t(lang, "logs_refresh_btn"), callback_data=refresh_cb),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_logs"),
    )
    if not lines:
        body = t(lang, "no_data")
    else:
        # Обрезаем длину, чтобы не упираться в лимит Telegram.
        safe_lines = [html.escape(line) for line in lines][-25:]
        body = "\n".join(safe_lines)
        if len(body) > 3400:
            body = body[-3400:]
    text = f"<b>{html.escape(title)}</b>\n\n<pre>{body}</pre>"
    return text, markup


