def clear_log_files() -> Tuple[bool, str]:
    """Очищает (обрезает) файлы логов за сегодня. Возвращает (успех, сообщение)."""
    try:
        today = datetime.now().strftime("%Y%m%d")
        main_log = LOGS_DIR / f"bot_{today}.log"
        err_log = LOGS_DIR / f"errors_{today}.log"
        cleared = []
        for path in (main_log, err_log):
            if path.exists():
                with open(path, "w", encoding="utf-8") as f:
                    f.write("")
                cleared.append(path.name)
        if cleared:
            logger.info("Логи очищены: %s", ", ".join(cleared))
            return True, "Очищены: " + ", ".join(cleared)
        return True, "Файлы логов за сегодня пусты или отсутствуют."
    except Exception as e:
        logger.error("Ошибка очистки логов: %s", e)
        return False, str(e)


