@bot.callback_query_handler(func=lambda call: call.data == "admin_backups")
@admin_callback_only
def admin_backups(call: CallbackQuery):
    """Управление бэкапами."""
    lang = get_user_language(call.from_user.id)
    # Получаем список бэкапов
    backups = []
    for ext in ['*.db', '*.db.gz', '*.json', '*.json.gz']:
        backups.extend(BACKUPS_DIR.glob(ext))
    
    backups.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    
    markup = InlineKeyboardMarkup()
    markup.add(
        InlineKeyboardButton(t(lang, "backup_create_btn"), callback_data="backup_create"),
        InlineKeyboardButton(t(lang, "backup_restore_btn"), callback_data="backup_restore"),
        InlineKeyboardButton(t(lang, "backup_cleanup_btn"), callback_data="backup_cleanup"),
        InlineKeyboardButton(t(lang, "back"), callback_data="admin_logs_backups")
    )
    
    backups_text = ""
    for i, backup in enumerate(backups[:5], 1):
        size = backup.stat().st_size / 1024 / 1024  # MB
        date = datetime.fromtimestamp(backup.stat().st_mtime).strftime("%d.%m.%Y %H:%M")
        backups_text += f"{i}. {backup.name} ({size:.1f} MB) - {date}\n"
    
    if not backups_text:
        backups_text = t(lang, "backup_none")
    
    bot.edit_message_text(
        t(lang, "backup_manage_title") + "\n\n"
        + t(lang, "backup_recent_label") + "\n" + backups_text + "\n"
        + t(lang, "backup_total_label") + f" {len(backups)}\n\n"
        + t(lang, "choose_action"),
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="Markdown"
    )

