@bot.callback_query_handler(func=lambda call: call.data == "backup_restore_confirm")
@admin_callback_only
@safe_handler
def backup_restore_confirm(call: CallbackQuery):
    """Восстанавливает последние доступные бэкапы по каждому типу."""
    targets = {
        "moderation": MODERATION_DB,
        "activity": ACTIVITY_DB,
        "economy": ECONOMY_DB,
        "users": USERS_DB,
        "settings": SETTINGS_FILE,
    }
    restored = 0
    attempted = 0

    for key, target in targets.items():
        patterns = [f"{key}_backup_*.db.gz", f"{key}_backup_*.db", f"{key}_backup_*.json.gz", f"{key}_backup_*.json"]
        candidates: List[Path] = []
        for pattern in patterns:
            candidates.extend(BACKUPS_DIR.glob(pattern))
        if not candidates:
            continue
        candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        attempted += 1
        if restore_from_backup(candidates[0], target):
            restored += 1

    bot.send_message(
        call.message.chat.id,
        f"🔄 **Восстановление завершено**\n\n"
        f"Успешно: {restored}/{attempted}\n"
        f"Рекомендуется перезапустить бота после восстановления.",
        parse_mode="Markdown",
    )
    bot.answer_callback_query(call.id, "✅ Готово")
    admin_backups(call)

