def process_admin_answer(message: Message):
    """Обработка ответа админа на тикет."""
    admin_id = message.from_user.id
    ticket_id = get_temp_data(admin_id, "answer_ticket_id")
    
    if not ticket_id:
        bot.reply_to(message, "❌ Сессия истекла")
        return
    
    ticket = support_manager.get_ticket(ticket_id)
    if not ticket:
        bot.reply_to(message, "❌ Тикет не найден")
        clear_temp_data(admin_id)
        return
    
    # Сохраняем ответ
    support_manager.answer_ticket(ticket_id, admin_id, message.text)
    
    # Отправляем пользователю
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("✅ " + t(get_user_language(call.from_user.id), "user_close_btn"), callback_data=f"user_close_{ticket_id}"))
    
    bot.send_message(
        ticket.user_id,
        f"📬 **Ответ на обращение #{ticket_id}**\n\n"
        f"{message.text}\n\n"
        f"Если проблема решена, нажми кнопку ниже:",
        reply_markup=markup,
        parse_mode="Markdown"
    )
    
    bot.reply_to(message, f"✅ Ответ отправлен пользователю")
    clear_temp_data(admin_id)

