@bot.callback_query_handler(func=lambda call: call.data == "check_sub")
@safe_handler
def callback_check_subscription(call: CallbackQuery):
    """Проверка подписки по кнопке «Я подписался»: сбрасываем кэш, перепроверяем, при успехе — показываем главное меню (в личке)."""
    user_id = call.from_user.id
    chat_id = call.message.chat.id
    lang = get_user_language(user_id)
    # Удаляем старое сообщение с кнопкой
    try:
        bot.delete_message(chat_id, call.message.message_id)
    except Exception:
        pass
    cache_delete(f"last_sub_message_{user_id}")
    _clear_subscription_cache(user_id)
    if is_user_in_chat(user_id, use_cache=False):
        # Очищаем сохранённые ID сообщений о подписке для этого пользователя
        for key in list(cache.keys()):
            if key.startswith(f"last_sub_message_{user_id}"):
                cache_delete(key)
        bot.answer_callback_query(call.id, t(lang, "check_sub_ok"), show_alert=True)
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        first_name = getattr(call.from_user, "first_name", None) if call.from_user else None
        private_chat_id = user_id if call.message.chat.type != "private" else chat_id
        # Если пользователь подписался после перехода по ссылке «настроить группу» — сразу открываем панель этой группы
        pending_gid = get_temp_data(user_id, "pending_group_setup_chat_id")
        if pending_gid is not None:
            clear_temp_data(user_id, "pending_group_setup_chat_id")
            delete_bot_added_setup_messages_for_user(user_id)
            if _admin_group_can_manage(user_id, pending_gid):
                _send_group_management_panel(private_chat_id, user_id, pending_gid)
            else:
                send_mygroups_panel(private_chat_id, user_id, lang)
        else:
            send_start_panel(private_chat_id, user_id, lang, "private", first_name=first_name)
    else:
        msg = t(lang, "check_sub_fail")
        bot.answer_callback_query(call.id, msg, show_alert=True)


@bot.callback_query_handler(func=lambda call: call.data == "inv_back_to_start")
@safe_handler
def back_to_start_callback(call: CallbackQuery):
    """Кнопка «В меню»: выход из тупиковых экранов (пустой магазин и т.д.) — в ЛС стартовая панель, в группе — быстрые кнопки."""
    chat_id = call.message.chat.id
    user_id = call.from_user.id
    chat_type = getattr(call.message.chat, "type", "private")
    if chat_type == "private":
        bot.answer_callback_query(call.id)
        clear_temp_data(user_id)
        lang = get_user_language(user_id)
        first_name = getattr(call.from_user, "first_name", None) if call.from_user else None
        send_start_panel(chat_id, user_id, lang, "private", first_name=first_name)
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
    elif chat_type in ("group", "supergroup"):
        bot.answer_callback_query(call.id)
        clear_temp_data(user_id)
        _show_group_quick_menu_in_message(call, answer_callback=False)
    else:
        bot.answer_callback_query(call.id)


