class _FakeMessage:
    """Минимальный объект сообщения для вызова cmd_* из callback."""
    def __init__(self, chat_id: int, from_user: Any, message_id: int, text: str = ""):
        self.chat = type("Chat", (), {"id": chat_id, "type": "private"})()
        self.from_user = from_user
        self.message_id = message_id
        self.text = text


