@bot.callback_query_handler(func=lambda call: call.data and call.data in ("group_lang_ru", "group_lang_en"))
@safe_handler
def group_language_callback(call: CallbackQuery):
    """Выбор языка группы при первом добавлении бота: сохраняем язык и показываем приветствие (выдать права / перейти в ЛС)."""
    chat_id = call.message.chat.id
    if getattr(call.message.chat, "type", "") not in ("group", "supergroup"):
        bot.answer_callback_query(call.id)
        return
    lang = "en" if call.data == "group_lang_en" else "ru"
    set_group_language(chat_id, lang)
    bot.answer_callback_query(call.id, "✅ Русский" if lang == "ru" else "✅ English")
    try:
        if lang == "ru":
            bot.edit_message_text("✅ Язык группы: Русский", chat_id, call.message.message_id)
        else:
            bot.edit_message_text("✅ Group language: English", chat_id, call.message.message_id)
    except Exception:
        pass
    inviter_id = None
    try:
        row = execute_query(USERS_DB, "SELECT added_by_user_id FROM bot_groups WHERE chat_id = ? LIMIT 1", (chat_id,))
        if row and row[0]:
            inviter_id = int(row[0][0])
    except Exception:
        pass
    me = None
    try:
        me = bot.get_me()
        me_id = me.id
        bot_member = bot.get_chat_member(chat_id, me_id)
        is_admin = getattr(bot_member, "status", "") in ("administrator", "creator")
    except Exception:
        is_admin = False
    bot_username = getattr(me, "username", None) if me else None
    configure_url = f"https://t.me/{bot_username}?start=group_setup_{chat_id}" if bot_username else None
    if is_admin:
        group_markup = InlineKeyboardMarkup()
        if configure_url:
            group_markup.add(InlineKeyboardButton(t(lang, "bot_added_btn_configure"), url=configure_url))
        sent = bot.send_message(
            chat_id,
            t(lang, "bot_added_admin_ok"),
            parse_mode="Markdown",
            reply_markup=group_markup if group_markup.keyboard else None,
        )
        if inviter_id and getattr(sent, "message_id", None):
            save_bot_added_setup_message(inviter_id, chat_id, sent.message_id)
    else:
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(t(lang, "bot_admin_confirm_btn"), callback_data=f"group_setup_confirm_{chat_id}"))
        if configure_url:
            markup.add(InlineKeyboardButton(t(lang, "bot_added_btn_configure"), url=configure_url))
        need_admin_text = t(lang, "bot_added_need_admin") + "\n\n" + t(lang, "bot_required_permissions")
        sent = bot.send_message(
            chat_id,
            need_admin_text,
            parse_mode="Markdown",
            reply_markup=markup,
        )
        if inviter_id and getattr(sent, "message_id", None):
            save_bot_added_setup_message(inviter_id, chat_id, sent.message_id)


@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("group_setup_confirm_"))
@safe_handler
def group_setup_confirm_callback(call: CallbackQuery):
    """Пользователь нажал «Я выдал права» после добавления бота в группу — проверяем и подтверждаем."""
    lang = get_user_language(call.from_user.id) if getattr(call, "from_user", None) else "ru"
    try:
        chat_id = int(call.data.replace("group_setup_confirm_", "").strip())
    except ValueError:
        bot.answer_callback_query(call.id, t(lang, "rating_error"))
        return
    if call.message.chat.id != chat_id:
        bot.answer_callback_query(call.id, t(lang, "group_setup_wrong_chat"))
        return
    try:
        me_id = bot.get_me().id
        bot_member = bot.get_chat_member(chat_id, me_id)
        is_admin = getattr(bot_member, "status", "") in ("administrator", "creator")
    except Exception as e:
        logger.debug(f"group_setup_confirm: {e}")
        bot.answer_callback_query(call.id, t(lang, "rights_check_failed"))
        return
    if is_admin:
        update_bot_admin_status(chat_id, True)
        try:
            chat_title = getattr(call.message.chat, "title", None) or ""
            if not chat_title:
                try:
                    chat = bot.get_chat(chat_id)
                    chat_title = getattr(chat, "title", None) or str(chat_id)
                except Exception:
                    chat_title = str(chat_id)
            notify_developer_bot_admin_rights_changed(chat_id, chat_title, granted=True)
        except Exception:
            pass
        try:
            bot.edit_message_text(
                t(lang, "bot_added_admin_ok"),
                call.message.chat.id,
                call.message.message_id,
                parse_mode="Markdown",
            )
        except Exception:
            pass
        bot.answer_callback_query(call.id, t(lang, "bot_admin_confirm_ok"))
    else:
        bot.answer_callback_query(call.id, t(lang, "bot_admin_not_yet"), show_alert=True)


