# ============================================================================
# РЕКЛАМНЫЕ ЗАЯВКИ
# ============================================================================

class AdRequest:
    """Класс для рекламной заявки."""
    
    def __init__(self, req_id: int, user_id: int, username: str, first_name: str):
        self.id = req_id
        self.user_id = user_id
        self.username = username
        self.first_name = first_name
        self.text = ""
        self.status = "new"  # new, viewed, contacted, completed
        self.created_at = datetime.now()
        self.viewed_at = None
        self.viewed_by = None
    
    def to_dict(self) -> Dict[str, Any]:
        """Преобразует заявку в словарь."""
        return {
            "id": self.id,
            "user_id": self.user_id,
            "username": self.username,
            "first_name": self.first_name,
            "text": self.text,
            "status": self.status,
            "created_at": self.created_at.isoformat(),
            "viewed_at": self.viewed_at.isoformat() if self.viewed_at else None,
            "viewed_by": self.viewed_by
        }

class AdManager:
    """Менеджер рекламных заявок."""
    
    def __init__(self):
        self.requests: Dict[int, AdRequest] = {}
        self.counter = 0
    
    def create_request(self, user_id: int, username: str, first_name: str) -> int:
        """Создаёт новую заявку."""
        self.counter += 1
        req = AdRequest(self.counter, user_id, username, first_name)
        self.requests[self.counter] = req
        logger.info(f"✅ Создана рекламная заявка #{self.counter} от пользователя {user_id}")
        return self.counter
    
    def get_request(self, req_id: int) -> Optional[AdRequest]:
        """Возвращает заявку по ID."""
        return self.requests.get(req_id)
    
    def mark_viewed(self, req_id: int, admin_id: int) -> bool:
        """Отмечает заявку как просмотренную."""
        req = self.requests.get(req_id)
        if not req:
            return False
        req.status = "viewed"
        req.viewed_at = datetime.now()
        req.viewed_by = admin_id
        return True

# Создаём менеджер рекламы
ad_manager = AdManager()

def _can_create_ad_request(user_id: int) -> Tuple[bool, str]:
    """Проверка анти-абуза: можно ли создать заявку на рекламу. Возвращает (ok, сообщение об ошибке)."""
    if user_id in DEVELOPER_IDS:
        return True, ""
    last_ts = ad_request_last_time.get(user_id)
    if last_ts is None:
        return True, ""
    cooldown_sec = AD_REQUEST_COOLDOWN_HOURS * 3600
    if time.time() - last_ts < cooldown_sec:
        left = int(cooldown_sec - (time.time() - last_ts))
        hours_left = left // 3600
        mins = (left % 3600) // 60
        return False, f"⏳ Следующая заявка доступна через {hours_left} ч {mins} мин. (не чаще 1 раза в {AD_REQUEST_COOLDOWN_HOURS} ч)"
    return True, ""


def get_chat_members_count_no_bots(chat_id: int) -> int:
    """
    Возвращает количество участников чата без учёта ботов.
    Telegram API не даёт отдельно число без ботов — вычитаем количество ботов из настройки main_chat_bots_count.
    """
    try:
        total = bot.get_chat_members_count(chat_id)
        bots_count = int(settings.get("main_chat_bots_count", 1))
        return max(0, total - bots_count)
    except Exception:
        return 0


def get_premium_count_for_ad_stats() -> int:
    """
    Количество пользователей бота с Telegram Premium (таблица users).
    Используется в статистике для рекламодателей и в разделе «Аудитория».
    """
    try:
        row = execute_query(
            USERS_DB,
            "SELECT COUNT(*) FROM users WHERE is_premium = 1 OR is_premium = '1'",
        )
        if row and row[0]:
            return int(row[0][0] or 0)
    except Exception as e:
        logger.debug("get_premium_count_for_ad_stats: %s", e)
    return 0


def get_ad_stats() -> Dict[str, Any]:
    """
    Собирает статистику для раздела «Рекламодателям»: пользователи и активность
    без учёта ботов (BOT_USER_IDS). Используется в форме заявки и при автообновлении.
    """
    bot_ids = tuple(BOT_USER_IDS)
    ph = ",".join("?" * len(bot_ids)) if bot_ids else ""
    excl_sql = f" AND user_id NOT IN ({ph})" if bot_ids else ""
    excl_params = (CHAT_ID,) + bot_ids if bot_ids else (CHAT_ID,)

    result = {
        "total_users": 0,
        "dau": 0,
        "wau": 0,
        "mau": 0,
        "avg_7d": 0,
        "med_7d": 0,
        "avg_30d": 0,
        "med_30d": 0,
        "lang_stats": [],
        "bot_lang_stats": [],   # язык интерфейса бота (ru/en) из user_settings
        "city_stats": [],       # гео: топ городов из user_cities
        "premium_count": get_premium_count_for_ad_stats(),
        "members_no_bots": get_chat_members_count_no_bots(CHAT_ID),
    }

    try:
        # Всего пользователей (без ботов)
        if bot_ids:
            row = execute_query(
                USERS_DB,
                f"SELECT COUNT(*) FROM users WHERE user_id NOT IN ({ph})",
                bot_ids,
            )
        else:
            row = execute_query(USERS_DB, "SELECT COUNT(*) FROM users")
        if row and row[0]:
            result["total_users"] = int(row[0][0] or 0)

        # DAU / WAU / MAU (без ботов)
        for key, date_cond, params in [
            ("dau", "date=date('now')", (CHAT_ID,) + (bot_ids if bot_ids else ())),
            ("wau", "date>=date('now','-6 days')", excl_params),
            ("mau", "date>=date('now','-29 days')", excl_params),
        ]:
            if key == "dau" and bot_ids:
                q = f"SELECT COUNT(DISTINCT user_id) FROM message_counts WHERE chat_id=? AND date=date('now') AND user_id NOT IN ({ph})"
                row = execute_query(MESSAGE_STATS_DB, q, (CHAT_ID,) + bot_ids)
            elif key == "dau":
                row = execute_query(
                    MESSAGE_STATS_DB,
                    "SELECT COUNT(DISTINCT user_id) FROM message_counts WHERE chat_id=? AND date=date('now')",
                    (CHAT_ID,),
                )
            else:
                q = f"SELECT COUNT(DISTINCT user_id) FROM message_counts WHERE chat_id=? AND {date_cond}{excl_sql}"
                row = execute_query(MESSAGE_STATS_DB, q, excl_params)
            if row and row[0]:
                result[key] = int(row[0][0] or 0)

        # Среднее и медиана сообщений за 7/30 дней (только не-боты)
        for days, avg_key, med_key in [(7, "avg_7d", "med_7d"), (30, "avg_30d", "med_30d")]:
            q = f"""SELECT user_id, SUM(count) AS c FROM message_counts
                    WHERE chat_id=? AND date>=date('now',?) GROUP BY user_id"""
            rows = execute_query(MESSAGE_STATS_DB, q, (CHAT_ID, f"-{days - 1} days")) or []
            vals = [int(r[1] or 0) for r in rows if not is_excluded_bot_user(int(r[0]))]
            if vals:
                vals_sorted = sorted(vals)
                n = len(vals_sorted)
                result[avg_key] = int(round(sum(vals_sorted) / float(n)))
                result[med_key] = vals_sorted[n // 2] if n % 2 == 1 else int(round((vals_sorted[n // 2 - 1] + vals_sorted[n // 2]) / 2.0))

        # Языки (топ-5, без ботов)
        if result["total_users"] > 0:
            if bot_ids:
                q = f"""SELECT COALESCE(language_code, 'n/d') AS lang, COUNT(*) FROM users
                        WHERE user_id NOT IN ({ph}) GROUP BY lang ORDER BY COUNT(*) DESC"""
                lang_rows = execute_query(USERS_DB, q, bot_ids) or []
            else:
                lang_rows = execute_query(
                    USERS_DB,
                    "SELECT COALESCE(language_code, 'n/d') AS lang, COUNT(*) FROM users GROUP BY lang ORDER BY COUNT(*) DESC",
                ) or []
            for lang, cnt in (lang_rows or [])[:5]:
                c = int(cnt or 0)
                pct = int(round(c * 100.0 / result["total_users"]))
                result["lang_stats"].append(((lang or "n/d"), c, pct))

        # Язык интерфейса бота (ru/en) из user_settings
        try:
            bot_lang_rows = execute_query(
                USERS_DB,
                "SELECT COALESCE(language, 'ru') AS lang, COUNT(*) FROM user_settings GROUP BY language ORDER BY COUNT(*) DESC",
            ) or []
            result["bot_lang_stats"] = [(str(r[0] or "ru"), int(r[1] or 0)) for r in bot_lang_rows]
        except Exception:
            result["bot_lang_stats"] = []

        # Гео: топ городов (из user_cities)
        try:
            from collections import Counter
            city_counts = Counter(user_cities.values())
            result["city_stats"] = city_counts.most_common(10)
        except Exception:
            result["city_stats"] = []
    except Exception as e:
        logger.debug("get_ad_stats: %s", e)
    return result


# Сообщения форм заявки на рекламу для автообновления числа участников: (chat_id, message_id, req_id)
ad_form_messages_to_update: set = set()
ad_form_update_lock = threading.Lock()
AD_FORM_UPDATE_INTERVAL = 180  # обновлять каждые 3 минуты


def _ad_form_auto_update_worker() -> None:
    """Фоновый поток: периодически обновляет число участников в открытых формах заявки на рекламу."""
    while True:
        try:
            time.sleep(AD_FORM_UPDATE_INTERVAL)
            with ad_form_update_lock:
                to_update = list(ad_form_messages_to_update)
            failed = []
            for chat_id, message_id, req_id in to_update:
                try:
                    text = _build_ad_request_form_text(req_id)
                    bot.edit_message_text(
                        text,
                        chat_id,
                        message_id,
                        reply_markup=_ad_request_form_markup(),
                        parse_mode="Markdown",
                    )
                except Exception:
                    failed.append((chat_id, message_id, req_id))
            if failed:
                with ad_form_update_lock:
                    for t in failed:
                        ad_form_messages_to_update.discard(t)
        except Exception as e:
            logger.debug("ad_form_auto_update_worker: %s", e)


# Запуск фонового обновления форм заявки на рекламу (число участников обновляется каждые 3 мин)
if not any(t.name == "ad_form_updater" for t in threading.enumerate()):
    threading.Thread(target=_ad_form_auto_update_worker, daemon=True, name="ad_form_updater").start()


def _build_ad_request_form_text(req_id: int) -> str:
    """Собирает текст формы заявки на рекламу с актуальной статистикой (без учёта ботов)."""
    try:
        bot_me = bot.get_me()
        bot_name = getattr(bot_me, "first_name", None) or "Бот"
    except Exception:
        bot_name = "Бот"
    s = get_ad_stats()
    members = s["members_no_bots"]
    total = s["total_users"]
    dau = s["dau"]
    wau = s["wau"]
    mau = s["mau"]
    avg_7d = s["avg_7d"]
    premium = s["premium_count"]
    lang_block = ""
    if s["lang_stats"]:
        lang_block = "\n🌍 **География (языки, топ-5):**\n"
        for lang, cnt, pct in s["lang_stats"]:
            lang_block += f"• {lang} — {cnt} (~{pct}%)\n"
        lang_block += "\n"
    return (
        f"📢 **РЕКЛАМОДАТЕЛЯМ**\n\n"
        f"╔════════════════════════════════╗\n"
        f"║     💼 **СОТРУДНИЧЕСТВО**       ║\n"
        f"╚════════════════════════════════╝\n\n"
        f"**{bot_name}** — бот для активного чата: экономика, игры, модерация. Аудитория вовлечена и ежедневно онлайн.\n\n"
        f"📊 **АУДИТОРИЯ (без учёта ботов):**\n"
        f"• 👥 Участников в чате: **{members}**\n"
        f"• 📈 Всего пользователей бота: **{total}**\n"
        f"• 📅 Активных сегодня (DAU): **{dau}** | за 7 дней (WAU): **{wau}** | за 30 дней (MAU): **{mau}**\n"
        f"• 💬 Сообщений на активного за неделю: ~**{avg_7d}** (медиана)\n"
        f"• 👑 С Telegram Premium: **{premium}**\n"
        f"{lang_block}"
        f"🎯 **ФОРМАТЫ РАЗМЕЩЕНИЯ:**\n"
        f"• 📢 Рассылка в чат (текст, фото, кнопки)\n"
        f"• 📌 Пост с закрепом на 24 ч\n"
        f"• 🤝 Нативная реклама и интеграции с ботом\n"
        f"• 🎁 Конкурсы и розыгрыши\n\n"
        f"💰 **УСЛОВИЯ:**\n"
        f"• Стоимость от **3000₽** за рассылку (зависит от формата)\n"
        f"• Тестовый период: скидка 50% на первый пост\n"
        f"• Пост-отчёт со статистикой (охват, клики)\n"
        f"• Оплата: по договорённости (карта, СБП)\n\n"
        f"📝 **Оставить заявку №{req_id}:**\n"
        f"Напишите ниже:\n"
        f"1. Имя/компания\n"
        f"2. Что рекламируете\n"
        f"3. Бюджет\n"
        f"4. Контакт (Telegram, почта)\n\n"
        f"⏳ **Ответ в течение 24 часов**\n"
        f"_(если не отправишь текст в течение 10 мин — заявка отменится)_"
    )


def _ad_request_form_markup() -> InlineKeyboardMarkup:
    """Клавиатура формы заявки на рекламу (обновить статистику, FAQ, отмена)."""
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("🔄 Обновить статистику", callback_data="ad_refresh_stats"))
    markup.add(InlineKeyboardButton("❓ FAQ", callback_data="inv_faq"))
    markup.add(InlineKeyboardButton("❌ Отмена", callback_data="ad_request_cancel"))
    return markup


def _send_ad_request_form(chat_id: int, user_id: int, username: str, first_name: str) -> Optional[Message]:
    """
    Отправляет форму заявки на рекламу и регистрирует next_step.
    Работает только в личке. Возвращает отправленное сообщение или None при ошибке.
    Количество участников подставляется при каждой отправке и при нажатии «Обновить статистику».
    """
    req_id = ad_manager.create_request(user_id, username, first_name)
    text = _build_ad_request_form_text(req_id)
    msg = bot.send_message(
        chat_id,
        text,
        reply_markup=_ad_request_form_markup(),
        parse_mode="Markdown",
    )
    save_temp_data(user_id, "ad_request_id", req_id)
    bot.register_next_step_handler(msg, process_ad_message)
    with ad_form_update_lock:
        ad_form_messages_to_update.add((chat_id, msg.message_id, req_id))
    # Удаление подсказки через 10 мин, чтобы не засорять чат старыми сообщениями
    schedule_deletion(chat_id, msg.message_id, delay=600)
    return msg


@bot.callback_query_handler(func=lambda call: call.data == "ad_refresh_stats")
@safe_handler
def callback_ad_refresh_stats(call: CallbackQuery):
    """Обновляет число участников в форме заявки на рекламу (актуальные данные из чата)."""
    user_id = call.from_user.id
    req_id = get_temp_data(user_id, "ad_request_id")
    if req_id is None:
        bot.answer_callback_query(call.id, "⏳ Сессия истекла. Открой форму заново: /ad")
        return
    text = _build_ad_request_form_text(req_id)
    try:
        bot.edit_message_text(
            text,
            call.message.chat.id,
            call.message.message_id,
            reply_markup=_ad_request_form_markup(),
            parse_mode="Markdown",
        )
        members_no_bots = get_chat_members_count_no_bots(CHAT_ID)
        bot.answer_callback_query(call.id, f"✅ Обновлено: участников {members_no_bots}")
    except Exception:
        bot.answer_callback_query(call.id, "❌ Не удалось обновить")


@bot.callback_query_handler(func=lambda call: call.data == "ad_request_cancel")
@safe_handler
def callback_ad_request_cancel(call: CallbackQuery):
    """Отмена заявки на рекламу: выход из FSM без отправки текста."""
    user_id = call.from_user.id
    clear_temp_data(user_id, "ad_request_id")
    lang = get_user_language(user_id)
    cancel_text = "❌ Заявка отменена. Нажми «📢 Заявка на рекламу» в меню или /ad, чтобы начать заново." if lang == "ru" else "❌ Request cancelled. Use «📢 Ad request» in menu or /ad to start again."
    try:
        bot.edit_message_text(cancel_text, call.message.chat.id, call.message.message_id)
    except Exception:
        bot.send_message(call.message.chat.id, cancel_text)
    bot.answer_callback_query(call.id, "Отменено")


@bot.message_handler(commands=['ad', 'ads', 'reklama'])
@safe_handler
def cmd_ad(message: Message):
    """
    Команда для рекламных предложений. Работает только в личке с ботом.
    Использование: /ad
    """
    if not ensure_user_access(message):
        return
    if message.chat.type != "private":
        bot.reply_to(
            message,
            "📢 Заявки на рекламу принимаются только в личке с ботом. Напиши боту в личные сообщения: /ad",
            parse_mode="Markdown",
        )
        return
    user_id = message.from_user.id
    username = message.from_user.username or ""
    first_name = message.from_user.first_name
    ok, err = _can_create_ad_request(user_id)
    if not ok:
        bot.reply_to(message, err)
        return
    _send_ad_request_form(message.chat.id, user_id, username, first_name)

def _handle_ad_message_no_request(message: Message, user_id: int) -> None:
    """Обработка сообщения без активной заявки."""
    text_lower = (message.text or "").strip().lower()
    if text_lower in OWNER_QUICK_BUTTON_TEXTS and user_id in DEVELOPER_IDS:
        clear_temp_data(user_id)
        owner_quick_buttons_handler(message)
        return
    bot.reply_to(message, "❌ Сессия истекла. Начни заново с /ad")


def _process_ad_request(message: Message, req: Any, req_id: int) -> None:
    """Обработка активной заявки."""
    req.text = message.text
    admin_text = f"""
📢 **НОВАЯ РЕКЛАМНАЯ ЗАЯВКА**

📋 **Номер:** `#{req_id}`
👤 **Пользователь:** {req.first_name}
🆔 **ID:** `{req.user_id}`
📝 **Текст:**
{message.text}

⏰ **Время:** {datetime.now().strftime('%d.%m.%Y %H:%M')}
    """
    bot.send_message(ADMIN_CHAT_ID, admin_text, parse_mode="Markdown")
    ad_request_last_time[message.from_user.id] = time.time()
    bot.reply_to(
        message,
        f"✅ **Заявка #{req_id} принята!**\n\n"
        f"Наш менеджер свяжется с вами в ближайшее время.\n"
        f"Спасибо за интерес к нашему чату!",
        parse_mode="Markdown"
    )
    clear_temp_data(message.from_user.id)


def process_ad_message(message: Message):
    """Обработка текста рекламной заявки."""
    user_id = message.from_user.id
    req_id = get_temp_data(user_id, "ad_request_id")
    if not req_id:
        _handle_ad_message_no_request(message, user_id)
        return
    req = ad_manager.get_request(req_id)
    if not req:
        bot.reply_to(message, "❌ Заявка не найдена")
        clear_temp_data(user_id)
        return
    _process_ad_request(message, req, req_id)

