class AIAssistant:
    """Класс для работы с DeepSeek API."""
    
    def __init__(self):
        self.api_key = DEEPSEEK_API_KEY
        self.api_url = "https://api.deepseek.com/v1/chat/completions"
        self.model = DEEPSEEK_MODEL
        self.temperature = DEEPSEEK_TEMPERATURE
        self.max_tokens = DEEPSEEK_MAX_TOKENS
        self.enabled = bool(self.api_key)
        
        # История диалогов: ключ (user_id, chat_id) — в группе контекст свой на каждый чат, в личке chat_id = user_id
        self.histories: Dict[Tuple[int, int], List[Dict[str, str]]] = {}
        self.history_lock = threading.Lock()
        
        # Системные промпты для разных режимов (базовые; в группе подставляется название чата)
        self.system_prompts = {
            "default": "Ты — умный помощник в Telegram-боте (Ком). Отвечай на вопросы пользователей, помогай с настройкой бота, объясняй команды, давай советы. Отвечай кратко, но информативно; используй эмодзи для дружелюбности. Если не знаешь ответа — честно скажи об этом.",
            "chat": "Ты Ком, свой человек в чате. Общайся естественно и неформально, с лёгким современным сленгом, поддерживай разговор и вайб тусовки. Не будь грубым, не провоцируй конфликты.",
            "party": "Ты Ком в режиме тусовки: общаешься живо, энергично, по-молодёжному, с аккуратным сленгом 2026 и мемным вайбом, но без оскорблений и перегибов. Поддерживай диалог как друг, предлагай темы для общения и активности в чате.",
            "help": "Ты помощник, объясняющий функции бота. Отвечай чётко, структурированно, по делу.",
            "creative": "Ты креативный помощник. Генерируй идеи, пиши стихи, рассказы, помогай с творческими задачами.",
            "code": "Ты эксперт по программированию. Помогай с кодом, объясняй алгоритмы, давай примеры.",
            "expert": "Ты эксперт. Дай развёрнутый, детальный ответ с примерами и пояснениями. Структурируй ответ (списки, абзацы), не упускай важные детали."
        }
        
        # Текущий режим для каждого пользователя
        self.user_modes: Dict[int, str] = {}
    
    def is_enabled(self) -> bool:
        """Проверяет, включён ли ИИ."""
        return self.enabled and bool(self.api_key)
    
    def set_mode(self, user_id: int, mode: str) -> bool:
        """Устанавливает режим для пользователя."""
        if mode in self.system_prompts:
            self.user_modes[user_id] = mode
            return True
        return False
    
    def get_mode(self, user_id: int) -> str:
        """Возвращает текущий режим пользователя."""
        return self.user_modes.get(user_id, "default")
    
    def get_system_prompt(self, user_id: int) -> str:
        """Возвращает системный промпт для пользователя. Без VIP доступен только режим «Обычный»."""
        mode = self.get_mode(user_id)
        if user_id not in DEVELOPER_IDS and not _is_vip_for_ai(user_id):
            mode = "default"
        base = self.system_prompts.get(mode, self.system_prompts["default"])
        # Защита от выдумывания фактов.
        guard = (
            " ВАЖНО: не выдумывай факты, числа, погоду, новости и статусы сервисов. "
            "Если точных данных нет — прямо скажи, что не знаешь/не можешь проверить сейчас."
        )
        # Язык ответа по настройкам пользователя
        try:
            lang = get_user_language(user_id)
            lang_instruction = (
                "Язык ответа: русский. Отвечай только на русском."
                if lang == "ru" else "Response language: English. Reply in English only."
            )
        except Exception:
            lang_instruction = "Язык ответа: русский."
        return base + guard + "\n\n" + lang_instruction
    
    def _history_key(self, user_id: int, chat_id: int) -> Tuple[int, int]:
        """Ключ истории: в личке chat_id = user_id, в группе — id группы."""
        return (user_id, chat_id)

    def get_history(self, user_id: int, chat_id: Optional[int] = None) -> List[Dict[str, str]]:
        """Возвращает историю диалога пользователя в данном чате (в личке chat_id можно не передавать)."""
        cid = chat_id if chat_id is not None else user_id
        key = self._history_key(user_id, cid)
        with self.history_lock:
            if key not in self.histories:
                self.histories[key] = []
            return list(self.histories[key])

    def add_to_history(self, user_id: int, role: str, content: str, chat_id: Optional[int] = None):
        """Добавляет сообщение в историю в данном чате."""
        cid = chat_id if chat_id is not None else user_id
        key = self._history_key(user_id, cid)
        with self.history_lock:
            if key not in self.histories:
                self.histories[key] = []
            self.histories[key].append({
                "role": role,
                "content": content,
                "timestamp": time.time()
            })
            if len(self.histories[key]) > 10:
                self.histories[key] = self.histories[key][-10:]

    def clear_history(self, user_id: int, chat_id: Optional[int] = None):
        """Очищает историю пользователя в данном чате."""
        cid = chat_id if chat_id is not None else user_id
        key = self._history_key(user_id, cid)
        with self.history_lock:
            if key in self.histories:
                del self.histories[key]

    def history_size(self, user_id: int, chat_id: Optional[int] = None) -> int:
        """Возвращает количество сообщений в истории пользователя в данном чате."""
        cid = chat_id if chat_id is not None else user_id
        key = self._history_key(user_id, cid)
        with self.history_lock:
            return len(self.histories.get(key, []))

    def render_history_text(self, user_id: int, chat_id: Optional[int] = None) -> str:
        """Возвращает историю диалога в текстовом виде."""
        history = self.get_history(user_id, chat_id)
        if not history:
            return "История диалога пуста."

        lines = []
        for item in history:
            role = item.get("role", "unknown")
            who = "Ты" if role == "user" else ("Ком" if role == "assistant" else role)
            ts = item.get("timestamp")
            if isinstance(ts, (int, float)):
                dt = datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")
            else:
                dt = "-"
            content = str(item.get("content", "")).strip()
            lines.append(f"[{dt}] {who}: {content}")
        return "\n\n".join(lines)

    def save_history_snapshot(self, user_id: int, chat_id: Optional[int] = None) -> Optional[Path]:
        """Сохраняет историю диалога пользователя в файл и возвращает путь."""
        try:
            dialogs_dir = BASE_DIR / "ai_dialogs"
            dialogs_dir.mkdir(parents=True, exist_ok=True)
            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            cid = chat_id if chat_id is not None else user_id
            path = dialogs_dir / f"ai_dialog_{user_id}_{cid}_{stamp}.txt"
            content = self.render_history_text(user_id, chat_id)
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
            return path
        except Exception as e:
            logger.error(f"Ошибка сохранения истории ИИ для {user_id}: {e}")
            return None
    
    async def _ask_async(
        self,
        user_id: int,
        question: str,
        chat_id: Optional[int] = None,
        extra_system: Optional[str] = None,
    ) -> str:
        """Асинхронный запрос к DeepSeek. chat_id — чат, откуда запрос (в группе — id группы, в личке — можно не передавать).
        extra_system — доп. инструкции в конец system (например, цель реплая в группе)."""
        if not self.is_enabled():
            return "🤖 **ИИ-помощник временно недоступен**\n\nАдминистратор не настроил API-ключ DeepSeek."

        cid = chat_id if chat_id is not None else user_id
        logger.info("AI request user_id=%s chat_id=%s q_len=%s", user_id, cid, len(question))
        is_group = cid != user_id or cid < 0

        # Получаем историю для этого чата (в группе — своя на каждый чат)
        history = self.get_history(user_id, cid)
        had_history = len(history) > 0

        # Кеш для повторяющихся вопросов без контекста (не сохраняем в историю при ответе из кеша)
        if not had_history and len(question.strip()) < 200:
            cache_key = f"ai_q_{user_id}_{hashlib.md5(question.strip().lower().encode()).hexdigest()}"
            cached = cache_get(cache_key)
            if cached and isinstance(cached, str) and len(cached) > 0:
                logger.info("AI cache hit user_id=%s", user_id)
                return cached

        # Системный промпт + контекст времени и города для оживлённых ответов
        system_content = self.get_system_prompt(user_id)
        # Ответ всегда в стиле выбранной роли (режима): оживлённый, в характере — Обычный/Тусовка/Эксперт и т.д.
        mode = self.get_mode(user_id)
        mode_hint = {"party": "тусовка", "expert": "эксперт", "chat": "дружеский", "help": "помощник", "creative": "креативный", "code": "код"}.get(mode, "обычный")
        system_content += (
            f"\n\n[При ответе на запросы с префиксом «ком» или «ии» отвечай оживлённо, с лёгкой игривостью и в характере выбранной роли (режим: {mode_hint}). "
            "Не сухо: тусовка — энергично и по-дружески; эксперт — развёрнуто и по делу; обычный — кратко и по-человечески.]"
        )
        # В группе: подставляем название чата и контекст недавних сообщений (бот может быть в разных группах)
        # Если запрос с реплаем — не подмешиваем ленту: в ней чужие @username, модель путает адресата.
        reply_focus = bool(
            extra_system
            and ("КРИТИЧЕСКИ ВАЖНО" in extra_system or "CRITICAL — reply target" in extra_system)
        )
        if is_group:
            chat_title = _get_chat_title_for_kom(cid)
            system_content += f"\n\nСейчас ты отвечаешь в групповом чате «{chat_title}». Учитывай контекст беседы."
            if reply_focus:
                system_content += (
                    "\n\n[Запрос отправлен ответом на сообщение конкретного человека — не опирайся на «ленту» чата для выбора адресата; "
                    "адресат задан отдельной инструкцией ниже.]"
                )
            else:
                recent = _get_group_context_for_kom(cid)
                if recent:
                    system_content += (
                        f"\n\n[Недавние сообщения в этом чате (учитывай при ответе):\n{recent}\n"
                        "Отвечай с учётом контекста, можно ссылаться на то, о чём говорили.]"
                    )
        try:
            time_str, date_str, weekday_ru = get_moscow_time_str()
            user_city = get_user_city(user_id)
            # Приоритет: город из запроса («погода и время в Казани») → иначе город из /city
            city_for_time = None
            tz_name = None
            location_from_question = _normalize_weather_location(question)
            if location_from_question and location_from_question.lower() not in WEATHER_LOCATION_PLACEHOLDERS:
                geo_q = _try_geocode_location(location_from_question)
                if geo_q and geo_q.get("timezone"):
                    city_for_time = (geo_q.get("name") or location_from_question, geo_q.get("timezone"))
            if not city_for_time and user_city:
                geo_time = _try_geocode_location(user_city)
                if geo_time and geo_time.get("timezone"):
                    city_for_time = ((geo_time or {}).get("name") or user_city, geo_time.get("timezone"))
            time_ctx = f"Сейчас по Москве — {time_str}, {date_str}, {weekday_ru}. Город пользователя: {user_city or 'не указан (можно задать командой /city)'}."
            if city_for_time:
                city_label, tz_name = city_for_time
                loc_time, loc_date, loc_weekday = get_local_time_str(tz_name)
                if loc_time:
                    time_ctx = (
                        f"В городе ({city_label}) сейчас: {loc_time}, {loc_date}, {loc_weekday}. "
                        f"По Москве: {time_str}, {date_str}. "
                        "Используй именно это локальное время, когда говоришь «сейчас в …»."
                    )
            system_content += (
                f"\n\n[Контекст времени: {time_ctx} "
                "На вопросы о времени или дате отвечай живо, по-человечески и в игровой форме, не шаблонно — как живой собеседник (нейросеть), без сухого перечисления «Сейчас X, дата Y».]"
            )
            if is_time_query(question):
                system_content += (
                    " Сейчас пользователь как раз спрашивает время — ответь в оживлённой, играющей форме, включи время в естественную фразу."
                )
            if is_weather_query(question):
                weather_ctx = get_weather_context_for_kom(question, user_id)
                if weather_ctx:
                    system_content += (
                        f"\n\n[Контекст погоды (данные для ответа):\n{weather_ctx}\n"
                        "На вопросы о погоде отвечай живо, по-дружески, как живой собеседник — не сухим списком. "
                        "Включи температуру и условия в естественную фразу, можешь добавить короткий совет (одежда, зонт и т.д.).]"
                    )
                    system_content += (
                        " Сейчас пользователь спрашивает про погоду — ответь в оживлённой форме, используй данные выше."
                    )
                else:
                    system_content += (
                        " Пользователь спрашивает про погоду, но город не указан или не найден. "
                        "Ответь дружелюбно и подскажи указать город (например: «погода Краснодар», «погода Москва на 10 дней»)."
                    )
            # Комбинированные запросы: «ком брось кубик и скажи погоду и время» — результат броска подставляем в контекст
            dice_roll = _detect_dice_in_question(question)
            if dice_roll is not None:
                system_content += (
                    f"\n\n[Пользователь попросил бросить кубик. Результат броска: {dice_roll}. "
                    f"Включи это в ответ в оживлённой форме (например: «Кинул кубик — выпало {dice_roll}!»), "
                    "можно в начале ответа, затем продолжай про погоду/время или остальное по запросу.]"
                )
        except Exception:
            pass
        if extra_system:
            system_content += extra_system
        messages = [
            {"role": "system", "content": system_content}
        ]
        
        # Добавляем историю
        for msg in history[-5:]:  # Последние 5 сообщений
            messages.append({"role": msg["role"], "content": msg["content"]})
        
        # Добавляем текущий вопрос
        messages.append({"role": "user", "content": question})
        
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        max_tokens = self.max_tokens
        if self.get_mode(user_id) == "expert":
            max_tokens = min(2000, self.max_tokens + 500)
        data = {
            "model": self.model,
            "messages": messages,
            "temperature": self.temperature,
            "max_tokens": max_tokens,
            "frequency_penalty": 0.3,
            "presence_penalty": 0.3,
        }

        # Сетевые ошибки на длинных ответах бывают спорадические: делаем ретраи.
        max_attempts = 3
        for attempt in range(1, max_attempts + 1):
            try:
                timeout = aiohttp.ClientTimeout(total=45, connect=12, sock_read=40)
                async with aiohttp.ClientSession(timeout=timeout) as session:
                    async with session.post(self.api_url, headers=headers, json=data) as resp:
                        if resp.status == 200:
                            result = await resp.json()
                            answer = result.get("choices") and result["choices"][0].get("message", {}).get("content")
                            if not answer or not str(answer).strip():
                                return "❌ Ком не смог сформулировать ответ. Попробуй переформулировать вопрос."
                            answer = str(answer).strip()
                            # Сохраняем в историю (для этого чата)
                            self.add_to_history(user_id, "user", question, cid)
                            self.add_to_history(user_id, "assistant", answer, cid)
                            if not had_history and len(question.strip()) < 200:
                                cache_key = f"ai_q_{user_id}_{hashlib.md5(question.strip().lower().encode()).hexdigest()}"
                                cache_set(cache_key, answer, ttl=3600)
                            usage = result.get("usage")
                            if usage:
                                logger.info("AI usage user_id=%s prompt_tokens=%s completion_tokens=%s", user_id, usage.get("prompt_tokens"), usage.get("completion_tokens"))
                            return answer

                        error_text = await resp.text()
                        logger.warning(
                            f"DeepSeek API status={resp.status}, attempt={attempt}/{max_attempts}: {error_text[:300]}"
                        )
                        # 5xx и 429 имеет смысл повторить, остальные статусы считаем финальными
                        if resp.status in (429, 500, 502, 503, 504) and attempt < max_attempts:
                            await asyncio.sleep(0.8 * attempt)
                            continue
                        if resp.status == 401:
                            return "❌ Ошибка доступа к ИИ: неверный API-ключ. Обратись к администратору."
                        if resp.status == 402:
                            return "❌ ИИ временно недоступен: исчерпан баланс на аккаунте DeepSeek. Обратись к администратору."
                        return "❌ ИИ временно недоступен. Попробуй ещё раз чуть позже."

            except (
                aiohttp.ClientError,
                aiohttp.ClientPayloadError,
                asyncio.TimeoutError,
            ) as e:
                logger.warning(f"Сетевая ошибка DeepSeek attempt={attempt}/{max_attempts}: {e}")
                if attempt < max_attempts:
                    await asyncio.sleep(0.8 * attempt)
                    continue
                return "❌ Связь с ИИ нестабильна. Попробуй повторить запрос через пару секунд."
            except Exception as e:
                logger.error(f"Неожиданная ошибка DeepSeek: {e}")
                return "❌ Внутренняя ошибка ИИ. Попробуй ещё раз позже."

        return "❌ ИИ временно недоступен. Попробуй позже."
    
    def ask(
        self,
        user_id: int,
        question: str,
        chat_id: Optional[int] = None,
        extra_system: Optional[str] = None,
    ) -> str:
        """
        Выполняет запрос к ИИ (вызывать лучше из отдельного потока).
        chat_id — чат, откуда запрос: в группе передай id группы, в личке можно не передавать.
        extra_system — доп. фрагмент system prompt (последним блоком).
        """
        loop = asyncio.new_event_loop()
        try:
            asyncio.set_event_loop(loop)
            return loop.run_until_complete(
                asyncio.wait_for(
                    self._ask_async(user_id, question, chat_id, extra_system=extra_system),
                    timeout=45,
                )
            )
        except asyncio.TimeoutError:
            logger.warning("AI request timeout user_id=%s", user_id)
            return "⏰ Запрос к Ком занял слишком много времени. Попробуй короче или позже."
        except Exception as e:
            logger.error(f"Ошибка выполнения запроса к ИИ: {e}")
            return "❌ Ошибка выполнения запроса. Попробуй ещё раз."
        finally:
            loop.close()


