# Фразы «в моём городе», «у меня», «здесь» — подставляем город из /city (в вызывающем коде)
WEATHER_LOCATION_PLACEHOLDERS = frozenset({
    "моём городе", "моем городе", "у меня", "здесь", "тут",
    "мой город", "моего города", "в моём городе", "в моем городе",
    "моём", "моем", "у нас", "здесь у нас",
})


def _normalize_weather_location(raw: str) -> str:
    """Нормализует фразу с городом для погодного запроса. Поддерживает разные формулировки."""
    q = (raw or "").strip()
    # Убираем префикс «ком » / «ии » если передан полный текст сообщения
    q = re.sub(r"^\s*(ком|ии|ai)\s+", "", q, flags=re.IGNORECASE)
    # Явный формат: "погода <город>", "weather <город>"
    q = re.sub(r"^\s*(погода|weather)\s*[:,-]?\s*", "", q, flags=re.IGNORECASE)
    # Естественные фразы: "... погоду/погода/weather ..." — берём текст после слова погода
    m = re.search(r"\b(погод[ауыев]?|weather)\b", q, flags=re.IGNORECASE)
    if m:
        q = q[m.end():].strip()
    q = re.sub(r"^\s*(в|во)\s+", "", q, flags=re.IGNORECASE)
    q = re.sub(r"\b(сегодня|завтра|today|tomorrow)\b", "", q, flags=re.IGNORECASE)
    q = re.sub(r"\b(?:на\s+)?\d{1,2}\s*(дн(?:я|ей)?|day|days)\b", "", q, flags=re.IGNORECASE)
    # «погода и время в Казани» / «время и погода в Москве» — извлекаем город после « в »
    if " в " in q:
        parts = q.split(" в ", 1)
        suffix = (parts[-1] or "").strip().strip("?!.,")
        if len(suffix) > 1 and suffix.lower() not in WEATHER_LOCATION_PLACEHOLDERS:
            q = suffix
    q = q.strip(" \t\r\n.,!?")
    if q.lower() in WEATHER_LOCATION_PLACEHOLDERS or not q:
        return ""
    # «погода и время» без города — пустая строка, чтобы использовался город из /city
    if re.match(r"^и\s+(время|дата|погод)", q, re.IGNORECASE) or re.match(r"^(время|дата)\s+и\s+", q, re.IGNORECASE):
        return ""
    return q


def _try_geocode_location(query: str) -> Optional[Dict[str, Any]]:
    """Ищет координаты города через Open-Meteo geocoding API."""
    if not query:
        return None

    variants = [query]
    if query.lower().startswith("в "):
        variants.append(query[2:].strip())
    if " " not in query and len(query) > 4 and query.endswith("е"):
        variants.append(query[:-1])
    if " " not in query and len(query) > 4 and query.endswith("у"):
        variants.append(query[:-1])

    seen: Set[str] = set()
    for name in variants:
        key = name.lower()
        if key in seen or not name:
            continue
        seen.add(key)
        try:
            resp = requests.get(
                "https://geocoding-api.open-meteo.com/v1/search",
                params={
                    "name": name,
                    "count": 1,
                    "language": "ru",
                    "format": "json",
                },
                timeout=12,
            )
            if resp.status_code != 200:
                continue
            data = resp.json()
            results = data.get("results") or []
            if results:
                return results[0]
        except Exception:
            continue
    return None


def _detect_weather_period(raw: str) -> Tuple[str, int]:
    """
    Определяет период прогноза:
    - today: сегодня
    - tomorrow: завтра
    - range: N дней
    """
    low = (raw or "").lower()

    if re.search(r"\b(завтра|tomorrow)\b", low):
        return "tomorrow", 2

    m = re.search(r"\b(?:на\s+)?(\d{1,2})\s*(дн(?:я|ей)?|day|days)\b", low)
    if m:
        try:
            days = int(m.group(1))
        except ValueError:
            days = 1
        days = max(1, min(10, days))
        if days == 1:
            return "today", 1
        return "range", days

    return "today", 1


def _fetch_weather_forecast(lat: float, lon: float, days: int) -> Optional[Dict[str, Any]]:
    """Получает текущую погоду и прогноз на N дней через Open-Meteo."""
    days = max(1, min(10, int(days)))
    try:
        resp = requests.get(
            "https://api.open-meteo.com/v1/forecast",
            params={
                "latitude": lat,
                "longitude": lon,
                "current": "temperature_2m,weather_code,wind_speed_10m,relative_humidity_2m",
                "daily": "weather_code,temperature_2m_max,temperature_2m_min",
                "timezone": "auto",
                "forecast_days": days,
            },
            timeout=12,
        )
        if resp.status_code != 200:
            return None
        return resp.json()
    except Exception:
        return None


def maybe_send_weather_reply(message: Message, query_text: str) -> bool:
    """
    Если текст похож на запрос погоды — отправляет сводку и возвращает True.
    """
    raw = (query_text or "").strip()
    low = raw.lower()
    # Поддержка не только "погода <город>", но и фраз:
    # "скажи погоду в магадане", "какая погода в..."
    if not (
        low.startswith("погода")
        or low.startswith("weather")
        or re.search(r"\bпогод[ауыев]?\b", low)
        or re.search(r"\bweather\b", low)
    ):
        return False

    location = _normalize_weather_location(raw)
    if not location or location.strip().lower() in WEATHER_LOCATION_PLACEHOLDERS:
        if message.from_user:
            location = get_user_city(message.from_user.id) or location
    if not location:
        bot.reply_to(message, "🌤 Напиши город после слова «погода» или сохрани город через /city. Пример: `погода Краснодар`", parse_mode="Markdown")
        return True

    period_mode, period_days = _detect_weather_period(raw)

    geo = _try_geocode_location(location)
    if not geo and message.from_user:
        fallback = get_user_city(message.from_user.id)
        if fallback and fallback != location:
            geo = _try_geocode_location(fallback)
            if geo:
                location = fallback
    if not geo:
        bot.reply_to(message, f"❌ Не нашёл локацию: {location}")
        return True

    lat = float(geo.get("latitude"))
    lon = float(geo.get("longitude"))
    weather = _fetch_weather_forecast(lat, lon, period_days)
    if not weather:
        bot.reply_to(message, "❌ Не удалось получить погоду. Попробуй чуть позже.")
        return True

    current = weather.get("current", {}) or {}
    daily = weather.get("daily", {}) or {}

    city_name = geo.get("name") or location
    admin1 = geo.get("admin1")
    country = geo.get("country")
    region_parts = [x for x in (admin1, country) if x]
    region = ", ".join(region_parts)

    temp = current.get("temperature_2m")
    wind = current.get("wind_speed_10m")
    hum = current.get("relative_humidity_2m")

    d_codes = daily.get("weather_code") or []
    d_tmin = daily.get("temperature_2m_min") or []
    d_tmax = daily.get("temperature_2m_max") or []
    d_dates = daily.get("time") or []

    title = html.escape(city_name)
    if region:
        title += f" ({html.escape(region)})"

    lines: List[str] = [f"🌤 <b>Погода: {title}</b>", ""]

    if period_mode == "today":
        code = int(current.get("weather_code", -1)) if current.get("weather_code") is not None else -1
        status = WEATHER_CODE_LABELS_RU.get(code, "Состояние не определено")
        lines.extend(
            [
                "📅 <b>Сегодня</b>",
                f"• Сейчас: <b>{temp}°C</b>" if temp is not None else "• Сейчас: н/д",
                f"• Состояние: {html.escape(status)}",
                f"• Влажность: {hum}%" if hum is not None else "• Влажность: н/д",
                f"• Ветер: {wind} км/ч" if wind is not None else "• Ветер: н/д",
            ]
        )
        if d_tmin and d_tmax:
            lines.append(f"• Диапазон: {d_tmin[0]}°C ... {d_tmax[0]}°C")
    elif period_mode == "tomorrow":
        lines.append("📅 <b>Завтра</b>")
        if len(d_dates) > 1:
            date_label = str(d_dates[1])
            code = int(d_codes[1]) if len(d_codes) > 1 and d_codes[1] is not None else -1
            status = WEATHER_CODE_LABELS_RU.get(code, "Состояние не определено")
            min_v = d_tmin[1] if len(d_tmin) > 1 else "н/д"
            max_v = d_tmax[1] if len(d_tmax) > 1 else "н/д"
            lines.append(f"• Дата: {date_label}")
            lines.append(f"• Состояние: {html.escape(status)}")
            lines.append(f"• Температура: {min_v}°C ... {max_v}°C")
        else:
            lines.append("• Нет данных на завтра.")
    else:
        lines.append(f"📅 <b>Прогноз на {period_days} дней</b>")
        max_rows = min(period_days, len(d_dates), len(d_tmin), len(d_tmax))
        if max_rows == 0:
            lines.append("• Нет данных по запрошенному периоду.")
        else:
            for i in range(max_rows):
                date_label = str(d_dates[i])[5:] if len(str(d_dates[i])) >= 5 else str(d_dates[i])
                code = int(d_codes[i]) if i < len(d_codes) and d_codes[i] is not None else -1
                status = WEATHER_CODE_LABELS_RU.get(code, "н/д")
                lines.append(f"• {date_label}: {d_tmin[i]}°C ... {d_tmax[i]}°C, {html.escape(status)}")

    bot.reply_to(message, "\n".join(lines), parse_mode="HTML")
    return True


def _detect_dice_in_question(question: Optional[str]) -> Optional[int]:
    """
    Если в вопросе просят бросить кубик — возвращает результат броска (1–6).
    Иначе None. Используется для комбинированных запросов типа «ком брось кубик и скажи погоду».
    """
    if not question or not question.strip():
        return None
    low = question.strip().lower()
    patterns = [
        r"\bбрось\s+кубик\b", r"\bкинь\s+кубик\b", r"\bкинуть\s+кубик\b",
        r"\bбросай\s+кубик\b", r"\bкубик\s*[!.,]?\s*$", r"\bбрось\s+кости\b",
        r"\bкинь\s+кости\b", r"\broll\s+(?:кубик|dice)?\b",
    ]
    if not any(re.search(p, low) for p in patterns):
        return None
    return random.randint(1, 6)


def is_weather_query(text: Optional[str]) -> bool:
    """Проверяет, является ли фраза запросом погоды (для передачи Кому в оживлённой форме)."""
    if not text:
        return False
    low = text.strip().lower()
    return (
        low.startswith("погода")
        or low.startswith("weather")
        or bool(re.search(r"\bпогод[ауыев]?\b", low))
        or bool(re.search(r"\bweather\b", low))
        or bool(re.search(r"какая\s+погода|погоду\s+(?:в|на)|что\s+по\s+погоде|расскажи\s+про\s+погод", low))
    )


def get_weather_context_for_kom(question: str, user_id: Optional[int] = None) -> Optional[str]:
    """
    Получает данные погоды по тексту запроса и возвращает краткий контекст для Кома.
    Если город не указан в тексте — используется город пользователя из /city (при переданном user_id).
    Если город не найден — возвращает None.
    """
    raw = (question or "").strip()
    location = _normalize_weather_location(raw)
    # Пустой город или плейсхолдеры («в моём городе», «здесь», «у меня») — берём город из /city
    if (not location or location.strip().lower() in WEATHER_LOCATION_PLACEHOLDERS) and user_id:
        location = get_user_city(user_id)
    if not location:
        return None
    period_mode, period_days = _detect_weather_period(raw)
    geo = _try_geocode_location(location)
    # Если по тексту город не найден (например «и время») — пробуем город из /city
    if not geo and user_id:
        fallback_city = get_user_city(user_id)
        if fallback_city and fallback_city.strip():
            geo = _try_geocode_location(fallback_city)
            if geo:
                location = fallback_city
    if not geo:
        return None
    lat = float(geo.get("latitude"))
    lon = float(geo.get("longitude"))
    weather = _fetch_weather_forecast(lat, lon, period_days)
    if not weather:
        return None
    current = weather.get("current", {}) or {}
    daily = weather.get("daily", {}) or {}
    city_name = geo.get("name") or location
    admin1 = geo.get("admin1")
    country = geo.get("country")
    region_parts = [x for x in (admin1, country) if x]
    region = ", ".join(region_parts)
    temp = current.get("temperature_2m")
    wind = current.get("wind_speed_10m")
    hum = current.get("relative_humidity_2m")
    d_codes = daily.get("weather_code") or []
    d_tmin = daily.get("temperature_2m_min") or []
    d_tmax = daily.get("temperature_2m_max") or []
    d_dates = daily.get("time") or []

    lines: List[str] = [f"Погода: {city_name}" + (f" ({region})" if region else "") + "."]
    if period_mode == "today":
        code = int(current.get("weather_code", -1)) if current.get("weather_code") is not None else -1
        status = WEATHER_CODE_LABELS_RU.get(code, "н/д")
        lines.append(f"Сегодня: сейчас {temp}°C, {status}." if temp is not None else f"Сегодня: {status}.")
        if hum is not None:
            lines.append(f"Влажность {hum}%, ветер {wind} км/ч." if wind is not None else f"Влажность {hum}%.")
        if d_tmin and d_tmax:
            lines.append(f"Диапазон за день: {d_tmin[0]}°C ... {d_tmax[0]}°C.")
    elif period_mode == "tomorrow" and len(d_dates) > 1:
        code = int(d_codes[1]) if len(d_codes) > 1 and d_codes[1] is not None else -1
        status = WEATHER_CODE_LABELS_RU.get(code, "н/д")
        min_v = d_tmin[1] if len(d_tmin) > 1 else "н/д"
        max_v = d_tmax[1] if len(d_tmax) > 1 else "н/д"
        lines.append(f"Завтра ({d_dates[1]}): {status}, {min_v}°C ... {max_v}°C.")
    else:
        lines.append(f"Прогноз на {period_days} дн.:")
        max_rows = min(period_days, len(d_dates), len(d_tmin), len(d_tmax))
        for i in range(max_rows):
            date_label = str(d_dates[i])[5:] if len(str(d_dates[i])) >= 5 else str(d_dates[i])
            code = int(d_codes[i]) if i < len(d_codes) and d_codes[i] is not None else -1
            status = WEATHER_CODE_LABELS_RU.get(code, "н/д")
            lines.append(f"  {date_label}: {d_tmin[i]}°C ... {d_tmax[i]}°C, {status}.")
    return "\n".join(lines)


def _extract_city_from_time_query(text: Optional[str]) -> Optional[str]:
    """Извлекает город из фраз типа «сколько времени в Магадане», «который час в Москве», «время в Владивостоке»."""
    if not text or not text.strip():
        return None
    low = text.strip().lower()
    # «времени в X», «час в X», «время в X» — город в конце или после « в »
    for pattern in (
        r"(?:сколько\s+)?(?:сейчас\s+)?времени?\s+в\s+([^?!.,]+?)\s*[?!.]*$",
        r"который\s+час\s+в\s+([^?!.,]+?)\s*[?!.]*$",
        r"время\s+в\s+([^?!.,]+?)\s*[?!.]*$",
        r"в\s+([^?!.,]+?)\s+сейчас\s+время",
    ):
        m = re.search(pattern, low, re.IGNORECASE)
        if m:
            city = m.group(1).strip().strip("?!.,")
            if len(city) > 1 and city not in ("моём", "моем", "твоём", "твоем"):
                return city
    return None


def is_time_query(text: Optional[str]) -> bool:
    """Проверяет, является ли фраза запросом текущего времени (в т.ч. «время в городе»)."""
    if not text:
        return False
    low = text.strip().lower()
    patterns = [
        r"\bсколько\s+сейчас\s+времени\b",
        r"\bсколько\s+времени?\b",  # «сколько времени» и «сколько время»
        r"\bкоторый\s+час\b",
        r"^\s*время\s*\??\s*$",
        r"\bwhat\s+time\s+is\s+it\b",
        r"\bвремени?\s+в\s+\w+",   # время в Москве, времени в Магадане
        r"\bчас\s+в\s+\w+",        # который час в Владивостоке
    ]
    return any(re.search(p, low) for p in patterns)


def maybe_send_time_reply(message: Message, query_text: str) -> bool:
    """
    Если текст похож на запрос времени — отправляет московское время и, при указании города
    или при наличии /city, время в этом городе.
    """
    if not is_time_query(query_text):
        return False
    time_str, date_str, weekday_ru = get_moscow_time_str()
    parts = [
        f"🕒 **Московское время (МСК)**\n\n• Сейчас: `{time_str}`\n• Дата: `{date_str}` ({weekday_ru})"
    ]
    # Город из запроса: «сколько времени в Магадане»
    city_from_query = _extract_city_from_time_query(query_text)
    if city_from_query:
        geo = _try_geocode_location(city_from_query)
        if geo and geo.get("timezone"):
            loc_time, loc_date, loc_weekday = get_local_time_str(geo["timezone"])
            if loc_time:
                city_name = geo.get("name") or city_from_query
                parts.append(f"\n\n🕐 **В {city_name}**\n\n• Сейчас: `{loc_time}`\n• Дата: `{loc_date}` ({loc_weekday})")
    # Без города в запросе — показываем время в сохранённом городе (/city) или подсказку
    if not city_from_query:
        user_city = get_user_city(message.from_user.id) if message.from_user else None
        if user_city:
            geo = _try_geocode_location(user_city)
            if geo and geo.get("timezone"):
                loc_time, loc_date, loc_weekday = get_local_time_str(geo["timezone"])
                if loc_time:
                    parts.append(f"\n\n📍 Твой город: **{user_city}**\n\n🕐 **В твоём городе**\n\n• Сейчас: `{loc_time}`\n• Дата: `{loc_date}` ({loc_weekday})")
        else:
            lang = get_user_language(message.from_user.id) if message.from_user else "ru"
            parts.append("\n\n" + t(lang, "time_city_hint"))
    bot.reply_to(message, "\n".join(parts), parse_mode="Markdown")
    return True


def extract_ai_direct_question(text: Optional[str]) -> Optional[str]:
    """
    Извлекает вопрос к Ком-ассистенту из фраз:
    - "ии ...", "ии, ..."
    - "ком ...", "ком, ..."
    - Только "ком" или "ии" (без вопроса) — возвращает "", чтобы обработчик показал подсказку.
    """
    if not text:
        return None
    t = text.strip()
    if not t:
        return None
    low = t.lower()

    for prefix in ("ии", "ком"):
        if low.startswith(prefix + " "):
            return t[len(prefix):].strip()
        if low.startswith(prefix + ","):
            return t[len(prefix) + 1:].strip()
        if low.startswith(prefix + ":"):
            return t[len(prefix) + 1:].strip()

    # Сообщение только "ком" или "ии" (с эмодзи или без) — вернём "", чтобы бот ответил подсказкой
    normalized = low.replace("\u200b", "").replace("\u200c", "").strip()
    if normalized in ("ком", "ии", "ai"):
        return ""
    # "🤖 ком", "🤖 ии" и т.п.
    no_emoji = "".join(c for c in normalized if c.isalnum() or c in " ,").strip()
    if no_emoji in ("ком", "ии", "ai"):
        return ""
    return None


def has_chat_access_for_kom(user_id: int) -> bool:
    """
    Проверяет, вступил ли пользователь в основной чат (для доступа к Кому).
    Результат кэшируется на короткое время.
    """
    if user_id in DEVELOPER_IDS:
        return True
    key = f"kom_chat_access_{user_id}"
    cached = cache_get(key)
    if cached is not None:
        return bool(cached)

    result = is_user_in_chat(user_id)
    cache_set(key, result, ttl=120)
    return result


def ensure_kom_access_or_reply(message: Message) -> bool:
    """
    Гейт доступа к Кому:
    - В группе/супергруппе: доступ всем участникам (не только разработчику и не только подписчикам основного чата).
    - В личке: только подписчики основного чата или разработчик; иначе — подсказка вступить и ссылка.
    """
    user_id = message.from_user.id
    chat_type = getattr(message.chat, "type", "private")
    # В группе Ком доступен всем участникам чата
    if chat_type in ("group", "supergroup"):
        return True
    if has_chat_access_for_kom(user_id):
        return True

    if chat_type == "private":
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton("🔑 Вступить в чат", url=_inline_keyboard_http_url(INVITE_LINK)))
        bot.reply_to(
            message,
            "🚫 Ком доступен только участникам чата.\n\n"
            "Сначала вступи в чат по кнопке ниже, потом снова нажми /ai.",
            reply_markup=markup,
        )
    return False


