def migrate_old_flags_from_settings() -> None:
    """Переносит старые флаги из settings.json в SQLite (однократно)."""
    try:
        old_welcome = settings.get("join_welcome_sent_users", [])
        if old_welcome:
            for user_id in old_welcome:
                try:
                    uid = int(user_id)
                    _ensure_user_flags(uid)
                    execute_query(
                        USERS_DB,
                        "UPDATE user_flags SET welcome_sent = 1 WHERE user_id = ? AND welcome_sent = 0",
                        (uid,),
                    )
                except Exception as e:
                    logger.debug("Error migrating welcome_sent for %s: %s", user_id, e)
            logger.info("Migrated %s welcome_sent flags", len(old_welcome))
        old_notified = settings.get("notified_users", [])
        if old_notified:
            for user_id in old_notified:
                try:
                    uid = int(user_id)
                    _ensure_user_flags(uid)
                    execute_query(
                        USERS_DB,
                        "UPDATE user_flags SET notified = 1 WHERE user_id = ? AND notified = 0",
                        (uid,),
                    )
                except Exception as e:
                    logger.debug("Error migrating notified for %s: %s", user_id, e)
            logger.info("Migrated %s notified flags", len(old_notified))
        old_new_member = settings.get("new_member_notified_user_ids", [])
        if old_new_member:
            for user_id in old_new_member:
                try:
                    uid = int(user_id)
                    _ensure_user_flags(uid)
                    execute_query(
                        USERS_DB,
                        "UPDATE user_flags SET new_member_notified = 1 WHERE user_id = ? AND new_member_notified = 0",
                        (uid,),
                    )
                except Exception as e:
                    logger.debug("Error migrating new_member_notified for %s: %s", user_id, e)
            logger.info("Migrated %s new_member_notified flags", len(old_new_member))
        if old_welcome or old_notified or old_new_member:
            settings.pop("join_welcome_sent_users", None)
            settings.pop("notified_users", None)
            settings.pop("new_member_notified_user_ids", None)
            save_settings(settings)
        # Перенос из user_first_join и users в user_flags (однократно)
        for row in execute_query(USERS_DB, "SELECT user_id FROM user_first_join WHERE welcome_sent = 1", ()) or []:
            try:
                uid = int(row[0])
                _ensure_user_flags(uid)
                execute_query(USERS_DB, "UPDATE user_flags SET welcome_sent = 1 WHERE user_id = ? AND welcome_sent = 0", (uid,))
            except Exception as e:
                logger.debug("Migrate welcome_sent from user_first_join: %s", e)
        for row in execute_query(USERS_DB, "SELECT user_id FROM user_first_join WHERE notified = 1", ()) or []:
            try:
                uid = int(row[0])
                _ensure_user_flags(uid)
                execute_query(USERS_DB, "UPDATE user_flags SET notified = 1 WHERE user_id = ? AND notified = 0", (uid,))
            except Exception as e:
                logger.debug("Migrate notified from user_first_join: %s", e)
        for row in execute_query(USERS_DB, "SELECT user_id FROM users WHERE new_member_notified_at IS NOT NULL", ()) or []:
            try:
                uid = int(row[0])
                _ensure_user_flags(uid)
                execute_query(USERS_DB, "UPDATE user_flags SET new_member_notified = 1 WHERE user_id = ? AND new_member_notified = 0", (uid,))
            except Exception as e:
                logger.debug("Migrate new_member_notified from users: %s", e)
    except Exception as e:
        logger.error("Error migrating old flags: %s", e)


# Миграция флагов из settings (вызывается после определения функции; init_all_databases уже создал user_flags)
migrate_old_flags_from_settings()


