def ensure_user_first_join_recorded(user_id: int) -> None:
    """Создаёт запись в user_first_join с first_joined при первом запуске бота (только если записи ещё нет)."""
    if is_excluded_bot_user(user_id):
        return
    try:
        now_ts = datetime.now()
        execute_query(
            USERS_DB,
            """INSERT INTO user_first_join (user_id, first_joined, last_seen, welcome_sent, notified)
               VALUES (?, ?, ?, 0, 0)
               ON CONFLICT(user_id) DO NOTHING""",
            (user_id, now_ts, now_ts),
        )
    except Exception as e:
        logger.debug("ensure_user_first_join_recorded: %s", e)


def get_user_first_joined(user_id: int) -> Optional[datetime]:
    """Возвращает дату первого входа пользователя из user_first_join."""
    try:
        result = execute_query(
            USERS_DB,
            "SELECT first_joined FROM user_first_join WHERE user_id=?",
            (user_id,),
        )
        if result and result[0][0] and isinstance(result[0][0], str):
            return datetime.fromisoformat(result[0][0])
    except Exception as e:
        logger.debug("get_user_first_joined: %s", e)
    return None


def _user_first_join_notified(user_id: int) -> bool:
    """Проверяет в user_first_join (и users.admin_notified_at для совместимости), было ли отправлено уведомление админу."""
    try:
        result = execute_query(
            USERS_DB,
            "SELECT notified FROM user_first_join WHERE user_id=?",
            (user_id,),
        )
        if result and result[0][0]:
            return True
        # Fallback: старые данные в users
        r2 = execute_query(USERS_DB, "SELECT admin_notified_at FROM users WHERE user_id=?", (user_id,))
        return bool(r2 and r2[0][0])
    except Exception:
        return False


def _user_first_join_welcome_sent(user_id: int) -> bool:
    """Проверяет в user_first_join (и users.welcome_dm_sent_at для совместимости), был ли отправлен welcome-подарок."""
    try:
        result = execute_query(
            USERS_DB,
            "SELECT welcome_sent FROM user_first_join WHERE user_id=?",
            (user_id,),
        )
        if result and result[0][0]:
            return True
        r2 = execute_query(USERS_DB, "SELECT welcome_dm_sent_at FROM users WHERE user_id=?", (user_id,))
        return bool(r2 and r2[0][0])
    except Exception:
        return False


def _user_first_join_set_notified(user_id: int) -> None:
    """Устанавливает в user_first_join флаг notified=1, создаёт запись при необходимости."""
    try:
        now_ts = datetime.now()
        execute_query(
            USERS_DB,
            """INSERT INTO user_first_join (user_id, first_joined, last_seen, welcome_sent, notified)
               VALUES (?, ?, ?, 0, 1)
               ON CONFLICT(user_id) DO UPDATE SET last_seen=?, notified=1""",
            (user_id, now_ts, now_ts, now_ts),
        )
    except Exception as e:
        logger.debug("_user_first_join_set_notified: %s", e)


def _user_first_join_set_welcome_sent(user_id: int) -> None:
    """Устанавливает в user_first_join флаг welcome_sent=1, создаёт запись при необходимости."""
    try:
        now_ts = datetime.now()
        execute_query(
            USERS_DB,
            """INSERT INTO user_first_join (user_id, first_joined, last_seen, welcome_sent, notified)
               VALUES (?, ?, ?, 1, 0)
               ON CONFLICT(user_id) DO UPDATE SET last_seen=?, welcome_sent=1""",
            (user_id, now_ts, now_ts, now_ts),
        )
    except Exception as e:
        logger.debug("_user_first_join_set_welcome_sent: %s", e)


def _count_notified_users() -> int:
    """Количество пользователей с notified=1 в user_flags."""
    try:
        result = execute_query(USERS_DB, "SELECT COUNT(*) FROM user_flags WHERE notified=1", ())
        return int(result[0][0]) if result and result[0] else 0
    except Exception:
        return 0


def _mark_new_member_notified_in_db(user_id: int) -> None:
    """Фиксирует в БД, что админ уведомлён о новом участнике группы."""
    try:
        execute_query(
            USERS_DB,
            "UPDATE users SET new_member_notified_at = ? WHERE user_id = ?",
            (datetime.now(), user_id),
        )
    except Exception as e:
        logger.debug("_mark_new_member_notified_in_db: %s", e)


@bot.message_handler(commands=['ai', 'ask', 'chat', 'kom_ai'])
@safe_handler
def cmd_ai(message: Message):
    """Команда для вызова ИИ. /ask [вопрос] или /ai [вопрос] — быстрый вопрос без входа в меню."""
    if not ensure_user_access(message):
        return
    if not ensure_kom_access_or_reply(message):
        return
    user_id = message.from_user.id
    text = (message.text or "").strip()
    # Быстрый вопрос: /ask что такое API или /ai как работает бан
    for prefix in ("/ask ", "/ai "):
        if text.lower().startswith(prefix) and len(text) > len(prefix):
            question = text[len(prefix):].strip()
            if question:
                _run_ai_request(message, question)
                return
    chat_type = getattr(message.chat, "type", "private")
    chat_id = message.chat.id
    markup = create_ai_control_keyboard(user_id, chat_type, chat_id if chat_type in ("group", "supergroup") else None)
    
    status = "✅ Активен" if ai_assistant.is_enabled() else "❌ Не настроен"
    key_status = "✅ Есть" if DEEPSEEK_API_KEY else "❌ Нет"
    session_status = "🟢 Включён" if user_id in ai_request_tracker.active_users else "⚪ Выключен"
    mode = ai_assistant.get_mode(user_id)
    mode_title = AI_MODE_TITLES.get(mode, mode)
    
    text = f"""
🤖 **КОМ (DeepSeek)**

**Статус:** {status}
**API ключ:** {key_status}
**Режим диалога с Ком:** {session_status}
**Текущий стиль:** {mode_title}

**Как использовать:**
• `ком [вопрос]` или `ии [вопрос]` — спросить в чате
• `/ask [вопрос]` или `/ai [вопрос]` — быстрый вопрос без входа в меню
• В личке: «▶️ Войти в Ком» — потом обычные сообщения и голосовые
• `/reset` — сбросить контекст (новый диалог)
• `/ai_limits` — твои лимиты на сегодня

**Режимы общения:**
• 💬 Обычный • 🤝 Дружеский • 🔥 Тусовка 17 • ❓ Помощник • 🎨 Креативный • 💻 Код • 📚 Эксперт (развёрнутые ответы)
""" + (
        "\n\n📌 **Смена роли Кома:** по умолчанию — владелец группы; в настройках модерации группы можно разрешить от N звёзд. Удобнее — в **личке** с ботом (кнопка ниже): перейди и нажми «Запустить» для смены роли в этой группе."
        if chat_type in ("group", "supergroup") else ""
    ) + """

**Примеры:**
• `ком, как стать лучше` • `/ask что такое API` • `ком напиши стих про кота`
    """
    
    bot.send_message(
        message.chat.id,
        text,
        reply_markup=markup,
        parse_mode="Markdown"
    )


@bot.callback_query_handler(func=lambda call: call.data.startswith('ai_mode_'))
@safe_handler
def ai_mode_callback(call: CallbackQuery):
    """Установка режима ИИ. В группе смена роли не выполняется — предлагаем перейти в личку."""
    chat_type = getattr(call.message.chat, "type", "private")
    if chat_type in ("group", "supergroup"):
        bot.answer_callback_query(
            call.id,
            "Сменить роль Кома удобнее в личке с ботом",
            show_alert=False,
        )
        markup = InlineKeyboardMarkup()
        group_chat_id = call.message.chat.id
        role_url = f"{get_bot_pm_link()}?start=role_selection_{group_chat_id}"
        markup.add(InlineKeyboardButton("🤖 Открыть бота в личке", url=role_url))
        gs = get_group_settings(call.message.chat.id)
        kom_min = gs.get("kom_role_min_rank", 0)
        who_can = "владелец группы" if kom_min <= 0 else f"владелец группы или от {kom_min} зв."
        try:
            bot.send_message(
                call.message.chat.id,
                "📌 **Смена роли Кома** делается в личных сообщениях с ботом — так удобнее и не засоряет чат.\n\n"
                f"Кто может менять роль в этой группе: {who_can}. (Настраивается в настройках модерации группы.)",
                reply_markup=markup,
                parse_mode="Markdown",
            )
        except Exception:
            pass
        return

    if not can_change_ai_role(call.from_user.id):
        bot.answer_callback_query(call.id, "🚫 Смена роли Кома доступна только владельцу и пользователям с 👑 VIP")
        return

    mode = call.data.replace('ai_mode_', '')
    
    if ai_assistant.set_mode(call.from_user.id, mode):
        ai_request_tracker.active_users.add(call.from_user.id)
        bot.answer_callback_query(call.id, f"✅ Режим '{mode}' активирован")
    else:
        bot.answer_callback_query(call.id, "❌ Неизвестный режим")
    
    # Показываем текущий режим
    current = ai_assistant.get_mode(call.from_user.id)
    current_title = AI_MODE_TITLES.get(current, current)
    bot.edit_message_text(
        f"🤖 **Текущий режим:** {current_title}\n\n"
        f"✅ Диалог с Ком включён.\n"
        f"Теперь можешь писать обычные сообщения (в личке).",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=create_ai_control_keyboard(call.from_user.id, chat_type),
        parse_mode="Markdown"
    )


