@bot.message_handler(commands=['ai_limits'])
@safe_handler
def cmd_ai_limits(message: Message):
    """Показать лимиты запросов к Ком (дневной и антифлуд)."""
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id
    used = _get_ai_daily_count(user_id)
    limit = AI_NON_VIP_DAILY_LIMIT
    if _is_vip_for_ai(user_id) or user_id in DEVELOPER_IDS:
        bot.reply_to(message, "📊 **Лимиты Ком:** безлимит (VIP/владелец).\nАнтифлуд: не более 8 запросов в минуту, пауза 5 сек между запросами.", parse_mode="Markdown")
        return
    left = max(0, limit - used)
    bot.reply_to(
        message,
        f"📊 **Твои лимиты на сегодня:**\n"
        f"• Использовано: {used} запросов\n"
        f"• Осталось: {left} из {limit}\n"
        f"• Антифлуд: не более 8 запросов в минуту, пауза 5 сек между запросами.",
        parse_mode="Markdown",
    )


AI_MODE_TITLES = {
    "default": "💬 Обычный",
    "chat": "🤝 Дружеский",
    "party": "🔥 Тусовка 17",
    "help": "❓ Помощник",
    "creative": "🎨 Креативный",
    "code": "💻 Код",
    "expert": "📚 Эксперт",
}


def _is_vip_for_ai(user_id: int) -> bool:
    """Проверяет, считается ли пользователь VIP для доступа к ролям Кома и безлимиту."""
    if user_id in DEVELOPER_IDS:
        return True
    return ItemEffects.get_vip_profile(user_id) is not None


def can_change_ai_role(user_id: int) -> bool:
    """Смена роли Кома доступна только владельцу бота и пользователям с VIP (в личке)."""
    return user_id in DEVELOPER_IDS or _is_vip_for_ai(user_id)


def can_change_kom_role_in_group(user_id: int, chat_id: int) -> bool:
    """
    Может ли пользователь менять роль Кома в данной группе.
    По умолчанию — только владелец группы; в настройках модерации можно разрешить от N звёзд (ранг).
    """
    if chat_id >= 0:
        return can_change_ai_role(user_id)
    if is_chat_owner(user_id, chat_id):
        return True
    gs = get_group_settings(chat_id)
    min_rank = gs.get("kom_role_min_rank", 0) or 0
    if min_rank <= 0:
        return False
    return get_user_rank(user_id) >= min_rank


def create_ai_control_keyboard(user_id: int, chat_type: Optional[str] = None, chat_id: Optional[int] = None) -> InlineKeyboardMarkup:
    """Клавиатура управления диалогом с Ком. В группе кнопки смены роли не показываем — только «Сменить роль в личке»."""
    active = user_id in ai_request_tracker.active_users
    active_button = (
        InlineKeyboardButton("⏸ Выйти из Ком", callback_data="ai_exit")
        if active
        else InlineKeyboardButton("▶️ Войти в Ком", callback_data="ai_enter")
    )

    markup = InlineKeyboardMarkup(row_width=2)
    is_group = chat_type in ("group", "supergroup")
    can_change = can_change_ai_role(user_id) if not is_group or chat_id is None else can_change_kom_role_in_group(user_id, chat_id)
    if can_change:
        if is_group:
            role_url = f"{get_bot_pm_link()}?start=role_selection_{chat_id}" if chat_id is not None else get_bot_pm_link()
            markup.add(
                InlineKeyboardButton("🤖 Сменить роль (в личке)", url=role_url),
            )
        else:
            markup.add(
                InlineKeyboardButton("💬 Обычный", callback_data="ai_mode_default"),
                InlineKeyboardButton("🤝 Дружеский", callback_data="ai_mode_chat"),
                InlineKeyboardButton("🔥 Тусовка 17", callback_data="ai_mode_party"),
                InlineKeyboardButton("❓ Помощник", callback_data="ai_mode_help"),
                InlineKeyboardButton("🎨 Креативный", callback_data="ai_mode_creative"),
                InlineKeyboardButton("💻 Код", callback_data="ai_mode_code"),
                InlineKeyboardButton("📚 Эксперт", callback_data="ai_mode_expert"),
            )

    markup.add(
        active_button,
        InlineKeyboardButton("🧹 Очистить контекст", callback_data="ai_reset"),
        InlineKeyboardButton("📤 Экспорт чата", callback_data="ai_export"),
        InlineKeyboardButton("💾 Сохранить на сервере", callback_data="ai_save"),
    )
    return markup


def _get_ai_daily_count(user_id: int) -> int:
    """Возвращает число запросов к КОМ за сегодня для пользователя (из БД)."""
    today_str = date.today().isoformat()
    rows = execute_query(USERS_DB, "SELECT count FROM ai_daily_requests WHERE user_id = ? AND date_iso = ?", (user_id, today_str))
    if not rows or len(rows) == 0:
        return 0
    return int(rows[0]["count"]) if rows[0]["count"] is not None else 0


def _increment_ai_daily_count(user_id: int) -> None:
    """Увеличивает счётчик запросов к КОМ за сегодня (в БД, переживает перезапуск)."""
    today_str = date.today().isoformat()
    execute_query(
        USERS_DB,
        "INSERT INTO ai_daily_requests (user_id, date_iso, count) VALUES (?, ?, 1) "
        "ON CONFLICT(user_id, date_iso) DO UPDATE SET count = count + 1",
        (user_id, today_str),
    )


def _check_ai_daily_limit_non_vip(user_id: int) -> Optional[str]:
    """Проверяет дневной лимит запросов к КОМ для пользователей без VIP. VIP и владелец — без лимита."""
    if _is_vip_for_ai(user_id):
        return None
    limit = AI_NON_VIP_DAILY_LIMIT
    if limit <= 0:
        return None
    used = _get_ai_daily_count(user_id)
    if used >= limit:
        return (
            f"⏳ Дневной лимит запросов к Ком для пользователей без VIP исчерпан ({limit} в день). "
            "Вернись завтра или получи 👑 VIP в магазине для безлимитного доступа."
        )
    return None


def create_limit_reached_keyboard(user_id: int) -> InlineKeyboardMarkup:
    """Клавиатура при достижении дневного лимита запросов к Ком (не-VIP): оформить VIP или в меню."""
    lang = get_user_language(user_id)
    markup = InlineKeyboardMarkup(row_width=1)
    markup.add(InlineKeyboardButton(
        "👑 " + t(lang, "buy_vip_btn"),
        callback_data="start_menu_shop",
    ))
    markup.add(InlineKeyboardButton(
        "🔙 " + t(lang, "back_to_menu"),
        callback_data="main_menu",
    ))
    return markup


def _kom_extra_system_instructions(message: Message) -> str:
    """
    Доп. system-блок для Кома: кто адресат при реплае (чтобы не путать с лентой чата),
    и лёгкий «вайб» без канцелярских мед. отмазок на утешениях.
    """
    parts: List[str] = []
    try:
        rm = message.reply_to_message
        if rm and getattr(rm, "from_user", None) and not getattr(rm.from_user, "is_bot", False):
            chat_id = message.chat.id
            target = rm.from_user
            tid = target.id
            lang = get_user_language(message.from_user.id) if message.from_user else "ru"
            disp = get_user_display_name(chat_id, tid, lang)
            un = (getattr(target, "username", None) or "").strip()
            at = f"@{un}" if un else ""
            if lang == "ru":
                who = f"«{disp}»" + (f" ({at})" if at else "")
                parts.append(
                    f"\n\n[КРИТИЧЕСКИ ВАЖНО — цель реплая: автор написал ответом на сообщение участника {who}. "
                    f"Обращения, поддержка, шутки, «обнимашки», упоминания @username — только к этому человеку ({disp}). "
                    "Имена из блока «недавние сообщения в чате» могут относиться к другим — не подставляй их вместо адресата реплая.]"
                )
            else:
                who = f'"{disp}"' + (f" ({at})" if at else "")
                parts.append(
                    f"\n\n[CRITICAL — reply target: the user replied to {who}. "
                    f"Comfort, jokes, hugs, @mentions apply ONLY to this person ({disp}). "
                    "Names in recent chat log may refer to others — do not substitute them for the reply target.]"
                )
    except Exception:
        pass
    try:
        lang = get_user_language(message.from_user.id) if message.from_user else "ru"
        if lang == "ru":
            parts.append(
                "\n\n[Тон в группе: тепло и чуть игриво, по-живому. "
                "Если просят утешить или «обнять» без медицинской темы — без длинных предупреждений про скорую и врачей "
                "(это портит шутку); если явно про симптомы/здоровье — можно одной короткой фразой предложить врача.]"
            )
        else:
            parts.append(
                "\n\n[Tone in groups: warm and a bit playful. "
                "If asked to comfort or hug in a casual way — skip long medical disclaimers; "
                "for real health concerns, one short line to see a professional is enough.]"
            )
    except Exception:
        pass
    return "".join(parts)


def _run_ai_request(message: Message, question: str) -> None:
    """Запускает запрос к Ком в фоне и отправляет результат пользователю."""
    user_id = message.from_user.id
    is_private = getattr(message.chat, "type", None) == "private"
    chat_type = getattr(message.chat, "type", "private")
    cid = message.chat.id
    kom_keyboard = create_ai_control_keyboard(user_id, chat_type, cid if chat_type in ("group", "supergroup") else None) if is_private else None

    allowed, limit_error = ai_request_tracker.check_and_add(user_id)
    if not allowed and limit_error:
        bot.reply_to(message, limit_error, reply_markup=kom_keyboard)
        return
    daily_error = _check_ai_daily_limit_non_vip(user_id)
    if daily_error:
        ai_request_tracker.active_users.discard(user_id)
        lang = get_user_language(user_id)
        markup = create_limit_reached_keyboard(user_id)
        bot.reply_to(
            message,
            daily_error + "\n\n" + t(lang, "choose_action"),
            reply_markup=markup,
            parse_mode="Markdown",
        )
        return

    try:
        bot.send_chat_action(message.chat.id, "typing")
    except Exception:
        pass
    _increment_ai_daily_count(user_id)
    wait_msg = bot.reply_to(
        message,
        "⏳ Ком думает... Это займёт несколько секунд",
        reply_markup=kom_keyboard,
    )

    def process_ai() -> None:
        try:
            chat_id = message.chat.id
            extra = _kom_extra_system_instructions(message)
            answer = ai_assistant.ask(user_id, question, chat_id, extra_system=extra)
            parts = split_long_message(answer)
            for i, part in enumerate(parts):
                # В личке к последнему сообщению ответа прикрепляем клавиатуру, чтобы кнопки были снизу
                reply_markup = kom_keyboard if (is_private and i == len(parts) - 1) else None
                bot.send_message(chat_id, part, reply_markup=reply_markup)
        except Exception as e:
            logger.error(f"Ошибка обработки ИИ-сообщения: {e}")
            bot.reply_to(
                message,
                "❌ Не удалось получить ответ от Ком. Попробуй ещё раз.",
                reply_markup=kom_keyboard,
            )
        finally:
            try:
                bot.delete_message(wait_msg.chat.id, wait_msg.message_id)
            except Exception:
                pass

    thread = threading.Thread(target=process_ai, daemon=True)
    thread.start()


def _get_ai_stt_model():
    """Ленивая инициализация faster-whisper модели для Кома."""
    global ai_stt_model
    if ai_stt_model is not None:
        return ai_stt_model

    with ai_stt_model_lock:
        if ai_stt_model is not None:
            return ai_stt_model
        try:
            from faster_whisper import WhisperModel  # type: ignore
        except Exception as e:
            raise RuntimeError(
                "faster-whisper не установлен. Установи зависимости: pip install faster-whisper"
            ) from e

        ai_stt_model = WhisperModel(
            AI_STT_MODEL_SIZE,
            device=AI_STT_DEVICE,
            compute_type=AI_STT_COMPUTE_TYPE,
        )
        return ai_stt_model


def _clean_transcription_with_deepseek(raw_text: str) -> str:
    """Пост-обработка транскрипции через DeepSeek: пунктуация, грамматика, убрать слова-паразиты."""
    if not raw_text or not raw_text.strip():
        return raw_text
    if deepseek_client is None:
        return raw_text
    try:
        response = deepseek_client.chat.completions.create(
            model="deepseek-chat",
            messages=[
                {
                    "role": "system",
                    "content": "Ты редактор текста. Исправь транскрипцию голосового сообщения: расставь знаки препинания, исправь грамматические ошибки, убери слова-паразиты (эээ, ммм, ну, типа). Сделай текст читабельным, не меняя смысл. Верни только исправленный текст без комментариев.",
                },
                {"role": "user", "content": raw_text},
            ],
            temperature=0.3,
        )
        cleaned = (response.choices[0].message.content or "").strip()
        return cleaned if cleaned else raw_text
    except Exception as e:
        logger.warning("DeepSeek пост-обработка недоступна: %s", e)
        return raw_text


def _transcribe_for_kom(audio_bytes: bytes, filename: str = "voice.ogg") -> Tuple[bool, str]:
    """Распознаёт голосовое через faster-whisper."""
    try:
        model = _get_ai_stt_model()
        suffix = os.path.splitext(filename)[1] or ".ogg"
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=True) as tmp:
            tmp.write(audio_bytes)
            tmp.flush()
            segments, _info = model.transcribe(tmp.name, beam_size=3, vad_filter=True)
            text = " ".join((seg.text or "").strip() for seg in segments).strip()
        if not text:
            return False, "❌ Не удалось распознать голосовое (пустой результат)."
        return True, text
    except Exception as e:
        logger.error(f"Ошибка faster-whisper: {e}")
        return False, f"❌ Ошибка распознавания голоса: {e}"


# ========== Транскрипция голосовых в группах (faster-whisper) ==========

def _get_ffmpeg_path() -> Optional[str]:
    """Возвращает путь к ffmpeg (из PATH или типичный /usr/bin/ffmpeg). None если не найден."""
    path = shutil.which("ffmpeg")
    if path:
        return path
    for candidate in ("/usr/bin/ffmpeg", "/usr/local/bin/ffmpeg"):
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    return None


def _convert_ogg_to_wav_sync(ogg_data: bytes, wav_path: str) -> Tuple[bool, Optional[str]]:
    """
    Конвертирует OGG Opus в WAV 16kHz моно через ffmpeg.
    Возвращает (True, None) при успехе, (False, reason) при ошибке.
    reason: "no_ffmpeg" — ffmpeg не установлен, иначе — текст ошибки конвертации.
    """
    import tempfile
    ffmpeg_path = _get_ffmpeg_path()
    if not ffmpeg_path:
        return False, "no_ffmpeg"
    try:
        with tempfile.NamedTemporaryFile(suffix=".ogg", delete=False) as f:
            f.write(ogg_data)
            ogg_path = f.name
        try:
            subprocess.run(
                [ffmpeg_path, "-y", "-i", ogg_path, "-acodec", "pcm_s16le", "-ar", "16000", "-ac", "1", wav_path],
                capture_output=True,
                timeout=30,
                check=True,
            )
            return True, None
        finally:
            try:
                os.unlink(ogg_path)
            except Exception:
                pass
    except FileNotFoundError:
        return False, "no_ffmpeg"
    except subprocess.CalledProcessError as e:
        logger.debug("_convert_ogg_to_wav_sync ffmpeg error: %s", e.stderr or e)
        return False, "convert_error"
    except Exception as e:
        logger.debug("_convert_ogg_to_wav_sync: %s", e)
        return False, "convert_error"


def save_transcription_stats(
    group_id: int, user_id: int, message_id: Optional[int],
    file_id: str, file_unique_id: str, duration: int,
    transcribed_text: str, language: str, model_used: str, processing_time: int,
) -> None:
    """Сохраняет запись в voice_transcriptions."""
    try:
        execute_query(
            USERS_DB,
            """INSERT INTO voice_transcriptions
               (group_id, user_id, message_id, file_id, file_unique_id, duration, transcribed_text, language, model_used, processing_time)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (group_id, user_id, message_id, file_id, file_unique_id, duration, transcribed_text or "", language or "", model_used or "tiny", processing_time),
        )
    except Exception as e:
        logger.debug("save_transcription_stats: %s", e)


# Максимум символов расшифровки в сообщении без кнопки «Показать полностью»
VOICE_TRANSCRIPTION_VISIBLE_CHARS = 600
VOICE_FULL_CACHE_TTL = 3600


def _format_transcription_as_quote(raw_text: str, max_chars: int = VOICE_TRANSCRIPTION_VISIBLE_CHARS) -> Tuple[str, Optional[str]]:
    """
    Форматирует текст расшифровки как цитату (blockquote) и при необходимости сжимает.
    Возвращает (блок цитаты для вставки в сообщение, полный текст или None если не сжимали).
    """
    def _escape_md(s: str) -> str:
        for ch, rep in (("\\", "\\\\"), ("_", "\\_"), ("*", "\\*"), ("`", "\\`"), ("[", "\\[")):
            s = s.replace(ch, rep)
        return s

    def _to_blockquote(s: str) -> str:
        escaped = _escape_md(s)
        return "\n".join("> " + line for line in escaped.split("\n"))

    text = (raw_text or "").strip() or "(пусто)"
    if len(text) <= max_chars:
        return _to_blockquote(text), None
    truncated = text[:max_chars].rstrip()
    rest = len(text) - len(truncated)
    body = _to_blockquote(truncated) + "\n\n_… ещё {} символов_".format(rest)
    return body, text


def send_transcription_to_target(
    bot_instance: "telebot.TeleBot",
    text: str,
    settings: Dict[str, Any],
    group_id: int,
    original_msg: Message,
    reply_markup: Optional[InlineKeyboardMarkup] = None,
) -> None:
    """Отправляет расшифровку в чат, в ЛС, админам или в log_chat. Текст уже приходит отформатированным (цитата, сжатие)."""
    target = settings.get("transcription_target") or "chat"
    try:
        if target == "chat":
            bot_instance.reply_to(original_msg, text, parse_mode="Markdown", reply_markup=reply_markup)
        elif target == "private":
            try:
                bot_instance.send_message(
                    original_msg.from_user.id,
                    f"📝 **Расшифровка вашего голосового в чате**\n\n{text}",
                    parse_mode="Markdown",
                    reply_markup=reply_markup,
                )
            except Exception:
                bot_instance.reply_to(original_msg, "❌ Не удалось отправить расшифровку в ЛС. Разрешите боту писать вам в личку.")
        elif target == "admins":
            admin_ids = get_group_admin_ids(group_id)
            for uid in admin_ids:
                try:
                    bot_instance.send_message(
                        uid,
                        f"📝 **Голосовое в группе**\n\n{text}",
                        parse_mode="Markdown",
                        reply_markup=reply_markup,
                    )
                except Exception:
                    pass
        elif target == "log_chat":
            log_chat_id = settings.get("transcription_log_chat_id")
            if log_chat_id:
                bot_instance.send_message(int(log_chat_id), text, parse_mode="Markdown", reply_markup=reply_markup)
            else:
                bot_instance.reply_to(original_msg, text, parse_mode="Markdown", reply_markup=reply_markup)
        else:
            bot_instance.reply_to(original_msg, text, parse_mode="Markdown", reply_markup=reply_markup)
    except Exception as e:
        logger.debug("send_transcription_to_target: %s", e)
        try:
            bot_instance.reply_to(original_msg, str(text)[:4000], parse_mode=None)
        except Exception:
            pass


class FasterWhisperTranscriber:
    """Транскрипция голосовых в группах через faster-whisper с кешем моделей."""

    def __init__(self, bot_instance: "telebot.TeleBot"):
        self.bot = bot_instance
        self._executor = __import__("concurrent.futures").futures.ThreadPoolExecutor(max_workers=2)
        self._models: Dict[str, Any] = {}
        self._models_lock = threading.Lock()
        self.total_processed = 0
        self.start_time = time.time()

    def _get_model(self, model_size: str = "tiny", device: str = "cpu") -> Any:
        cache_key = f"{model_size}_{device}"
        with self._models_lock:
            if cache_key in self._models:
                return self._models[cache_key]
        try:
            from faster_whisper import WhisperModel  # type: ignore
        except ImportError as e:
            raise RuntimeError("faster-whisper не установлен. pip install faster-whisper") from e
        compute_type = "int8" if device == "cpu" else "float16"
        model = WhisperModel(
            model_size,
            device=device,
            compute_type=compute_type,
            cpu_threads=os.cpu_count() or 2,
            num_workers=1,
        )
        with self._models_lock:
            self._models[cache_key] = model
        logger.info("Модель whisper %s загружена на %s", model_size, device)
        return model

    def transcribe_sync(
        self,
        file_id: str,
        file_unique_id: str,
        language: str = "ru",
        model_size: str = "tiny",
        device: str = "cpu",
    ) -> Dict[str, Any]:
        """Скачивает голосовое, конвертирует в WAV, распознаёт. Возвращает dict с success, text, language, processing_time, model или error."""
        start = time.time()
        _ffmpeg_err = (
            "❌ Системная ошибка: ffmpeg не установлен.\n"
            "Администратору нужно выполнить: sudo apt install ffmpeg (Ubuntu/Debian) или apk add ffmpeg (Alpine)."
        )
        try:
            if not _get_ffmpeg_path():
                return {"success": False, "error": _ffmpeg_err, "processing_time": int((time.time() - start) * 1000)}
            tg_file = self.bot.get_file(file_id)
            audio_bytes = self.bot.download_file(tg_file.file_path)
            if not audio_bytes:
                return {"success": False, "error": "Не удалось скачать файл", "processing_time": int((time.time() - start) * 1000)}

            wav_path = os.path.join(tempfile.gettempdir(), f"voice_{file_unique_id}.wav")
            ok, conv_reason = _convert_ogg_to_wav_sync(audio_bytes, wav_path)
            if not ok:
                err_msg = _ffmpeg_err if conv_reason == "no_ffmpeg" else (
                    "Ошибка конвертации аудио. Проверьте, что ffmpeg установлен и доступен: sudo apt install ffmpeg"
                )
                return {"success": False, "error": err_msg, "processing_time": int((time.time() - start) * 1000)}
            try:
                model = self._get_model(model_size, device)
                lang_param = None if (not language or language == "auto") else language
                segments, info = model.transcribe(
                    wav_path,
                    language=lang_param,
                    task="transcribe",
                    beam_size=5,
                    best_of=5,
                    temperature=0.0,
                    vad_filter=True,
                    vad_parameters=dict(threshold=0.5, min_speech_duration_ms=250, min_silence_duration_ms=100),
                )
                full_text = " ".join((seg.text or "").strip() for seg in segments).strip()
                self.total_processed += 1
                return {
                    "success": True,
                    "text": full_text,
                    "language": getattr(info, "language", language),
                    "segments": [],
                    "processing_time": int((time.time() - start) * 1000),
                    "model": model_size,
                }
            finally:
                try:
                    os.unlink(wav_path)
                except Exception:
                    pass
        except Exception as e:
            logger.exception("transcribe_sync: %s", e)
            return {"success": False, "error": str(e), "processing_time": int((time.time() - start) * 1000)}

    def get_available_models(self) -> List[Dict[str, Any]]:
        """Список моделей из БД whisper_models."""
        rows = execute_query(USERS_DB, "SELECT name, size_mb, description, ram_required FROM whisper_models ORDER BY size_mb") or []
        return [{"name": r[0], "size_mb": r[1], "description": r[2] or "", "ram_required": r[3] or 0} for r in rows]

    def get_stats(self) -> Dict[str, Any]:
        return {
            "total_processed": self.total_processed,
            "uptime_hours": (time.time() - self.start_time) / 3600,
            "active_models": list(self._models.keys()),
        }


_voice_transcriber: Optional[FasterWhisperTranscriber] = None


def get_voice_transcriber() -> Optional[FasterWhisperTranscriber]:
    global _voice_transcriber
    if _voice_transcriber is None:
        try:
            _voice_transcriber = FasterWhisperTranscriber(bot)
        except Exception as e:
            logger.warning("FasterWhisperTranscriber не инициализирован: %s", e)
    return _voice_transcriber


# Блокировка повторной обработки голоса в одном чате (защита от рекурсии/дублей)
_voice_processing_locks: dict = {}

# Глобальная блокировка для предотвращения рекурсии голосовых сообщений
voice_processing = threading.Lock()
voice_processing_active = False
# Защита от повторов: ID уже обработанных голосовых
processed_voice_messages = set()
processed_voice_lock = threading.Lock()

# Словарь блокировок по пользователям (параллельная обработка от разных пользователей)
user_voice_locks: Dict[int, bool] = {}
user_voice_locks_lock = threading.Lock()

# Доп. защита от рекурсии и флуда: кеш по сообщению и интервал
_voice_safe_cache: dict = {}
_voice_safe_last_time: dict = {}

def safe_voice_handler(func):
    """Декоратор: не обрабатывать бота, дубли сообщений, флуд; не допускать рекурсии."""
    @wraps(func)
    def wrapper(message, *args, **kwargs):
        if not getattr(message, "from_user", None):
            return None
        if getattr(message.from_user, "is_bot", False):
            return None
        try:
            me = bot.get_me()
            if me and message.from_user.id == me.id:
                return None
        except Exception:
            pass
        chat_id = getattr(message.chat, "id", None)
        message_id = getattr(message, "message_id", None)
        if chat_id is None:
            return None
        cache_key = f"{chat_id}_{message_id}"
        if cache_key in _voice_safe_cache:
            return None
        current_time = time.time()
        if chat_id in _voice_safe_last_time and (current_time - _voice_safe_last_time[chat_id]) < 5:
            return None
        _voice_safe_last_time[chat_id] = current_time
        _voice_safe_cache[cache_key] = True
        try:
            return func(message, *args, **kwargs)
        except RecursionError as e:
            logger.exception("RecursionError in voice handler: %s", e)
            return None
        except Exception as e:
            logger.exception("Voice handler error: %s", e)
            return None
        finally:
            def _cleanup():
                time.sleep(10)
                _voice_safe_cache.pop(cache_key, None)
            try:
                threading.Thread(target=_cleanup, daemon=True).start()
            except Exception:
                _voice_safe_cache.pop(cache_key, None)
    return wrapper


def _process_group_voice_transcription(message: Message, processing_msg: Message) -> None:
    """Выполняется в фоновом потоке: распознавание голосового и отправка результата."""
    group_id = message.chat.id
    try:
        if not _get_ffmpeg_path():
            try:
                bot.edit_message_text(
                    "❌ **Ошибка распознавания**\n\n"
                    "Системная ошибка: ffmpeg не установлен.\n"
                    "Администратору нужно выполнить: sudo apt install ffmpeg (Ubuntu/Debian) или apk add ffmpeg (Alpine).",
                    processing_msg.chat.id,
                    processing_msg.message_id,
                    parse_mode="Markdown",
                )
            except Exception:
                pass
            return
        user_id = message.from_user.id if message.from_user else 0
        settings = get_group_settings(group_id)
        transcriber = get_voice_transcriber()
        if not transcriber:
            try:
                bot.edit_message_text("❌ Транскрипция недоступна (faster-whisper не загружен).", processing_msg.chat.id, processing_msg.message_id)
            except Exception:
                pass
            return
        voice = message.voice
        if not voice:
            return
        device = settings.get("transcription_device") or "cpu"
        model_size = settings.get("transcription_model") or "tiny"
        lang = settings.get("transcription_language") or "ru"
        try:
            result = transcriber.transcribe_sync(voice.file_id, voice.file_unique_id, language=lang, model_size=model_size, device=device)
        except RecursionError:
            logger.exception("RecursionError in voice transcribe_sync")
            try:
                bot.edit_message_text(
                    "❌ **Ошибка распознавания**\n\nВнутренняя ошибка (превышена глубина рекурсии). Перезапустите бота.",
                    processing_msg.chat.id,
                    processing_msg.message_id,
                    parse_mode="Markdown",
                )
            except Exception:
                pass
            return
        try:
            if result.get("success"):
                raw_text = result.get("text", "") or ""
                save_transcription_stats(
                    group_id, user_id, message.message_id,
                    voice.file_id, voice.file_unique_id, voice.duration,
                    raw_text, result.get("language", ""), result.get("model", "tiny"), result.get("processing_time", 0),
                )
                body_quote, full_text = _format_transcription_as_quote(raw_text)
                header = (
                    f"📝 **Расшифровка голосового**\n\n"
                    f"👤 Отправитель: {message.from_user.full_name if message.from_user else '—'}\n"
                    f"🎤 Длительность: {voice.duration} сек\n"
                    f"🤖 Модель: {result.get('model', 'tiny')}\n"
                    f"⚡ Время: {result.get('processing_time', 0)} мс\n"
                    f"🌍 Язык: {result.get('language', lang)}\n\n"
                    f"💬 **Текст:**\n\n"
                )
                transcript_text = header + body_quote
                reply_markup = None
                if full_text is not None:
                    cache_set(f"voice_full_{group_id}_{message.message_id}", full_text, ttl=VOICE_FULL_CACHE_TTL)
                    reply_markup = InlineKeyboardMarkup()
                    reply_markup.add(InlineKeyboardButton("📄 Показать полностью", callback_data=f"vfull_{group_id}_{message.message_id}"))
                send_transcription_to_target(bot, transcript_text, settings, group_id, message, reply_markup=reply_markup)
                if settings.get("auto_delete_voice"):
                    try:
                        bot.delete_message(message.chat.id, message.message_id)
                    except Exception:
                        pass
                try:
                    bot.delete_message(processing_msg.chat.id, processing_msg.message_id)
                except Exception:
                    pass
            else:
                err = result.get("error", "Неизвестная ошибка")
                bot.edit_message_text(f"❌ **Ошибка распознавания**\n\n{err}", processing_msg.chat.id, processing_msg.message_id, parse_mode="Markdown")
        except Exception as e:
            logger.exception("_process_group_voice_transcription send: %s", e)
            try:
                bot.edit_message_text("❌ Ошибка отправки результата.", processing_msg.chat.id, processing_msg.message_id)
            except Exception:
                pass
    finally:
        _voice_processing_locks.pop(group_id, None)


def test_voice_transcription_system() -> List[str]:
    """Проверка компонентов транскрипции: БД, модели, transcriber. Возвращает список ошибок (пустой = ок)."""
    errors: List[str] = []
    try:
        rows = execute_query(USERS_DB, "SELECT name FROM whisper_models LIMIT 1")
        if not rows:
            errors.append("Таблица whisper_models пуста или отсутствует")
    except Exception as e:
        errors.append(f"whisper_models: {e}")
    try:
        transcriber = get_voice_transcriber()
        if not transcriber:
            errors.append("FasterWhisperTranscriber не инициализирован")
        elif not transcriber.get_available_models():
            errors.append("Список моделей пуст")
    except Exception as e:
        errors.append(f"get_voice_transcriber: {e}")
    return errors


