@bot.callback_query_handler(func=lambda call: call.data in {"ai_enter", "ai_exit", "ai_export", "ai_save"})
@safe_handler
def ai_controls_callback(call: CallbackQuery):
    """Обработчик кнопок управления AI-диалогом."""
    user_id = call.from_user.id

    if call.data == "ai_enter":
        if not has_chat_access_for_kom(user_id):
            bot.answer_callback_query(call.id, "🚫 Сначала вступи в чат")
            ctype = getattr(call.message.chat, "type", "private")
            if ctype == "private":
                markup = InlineKeyboardMarkup()
                markup.add(InlineKeyboardButton("🔑 Вступить в чат", url=_inline_keyboard_http_url(INVITE_LINK)))
                bot.send_message(
                    call.message.chat.id,
                    "Ком доступен только участникам чата.",
                    reply_markup=markup,
                )
            return
        ai_request_tracker.active_users.add(user_id)
        bot.answer_callback_query(call.id, "✅ Диалог с Ком включён")
        ctype = getattr(call.message.chat, "type", "private")
        cid = call.message.chat.id
        bot.edit_message_text(
            "🟢 **Режим Ком включён**\n\nПиши обычные сообщения в этом чате, Ком будет отвечать.",
            call.message.chat.id,
            call.message.message_id,
            reply_markup=create_ai_control_keyboard(user_id, ctype, cid if ctype in ("group", "supergroup") else None),
            parse_mode="Markdown",
        )
        return

    if call.data == "ai_exit":
        ai_request_tracker.active_users.discard(user_id)
        bot.answer_callback_query(call.id, "✅ Режим Ком выключен")
        ctype = getattr(call.message.chat, "type", "private")
        cid = call.message.chat.id
        bot.edit_message_text(
            "⏸ **Режим Ком выключен**\n\nДиалог сохранён. Можно включить снова в любой момент.",
            call.message.chat.id,
            call.message.message_id,
            reply_markup=create_ai_control_keyboard(user_id, ctype, cid if ctype in ("group", "supergroup") else None),
            parse_mode="Markdown",
        )
        return

    if call.data == "ai_export":
        chat_id = call.message.chat.id
        history_text = ai_assistant.render_history_text(user_id, chat_id)
        payload = io.BytesIO(history_text.encode("utf-8"))
        payload.name = f"ai_chat_{user_id}_{chat_id}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        bot.send_document(call.message.chat.id, payload, caption="📤 Экспорт диалога с Ком")
        bot.answer_callback_query(call.id, "✅ Чат экспортирован")
        return

    if call.data == "ai_save":
        chat_id = call.message.chat.id
        path = ai_assistant.save_history_snapshot(user_id, chat_id)
        if path:
            bot.answer_callback_query(call.id, "✅ Диалог сохранён")
            bot.send_message(
                call.message.chat.id,
                f"💾 Диалог сохранён в файл:\n`{path}`",
                parse_mode="Markdown",
            )
        else:
            bot.answer_callback_query(call.id, "❌ Ошибка сохранения")


