@safe_handler
def ai_session_message_handler(message: Message):
    """Ответ Ком на обычные сообщения в личке при активном режиме."""
    if not ensure_user_access(message):
        return
    if not ensure_kom_access_or_reply(message):
        ai_request_tracker.active_users.discard(message.from_user.id)
        return
    user_id = message.from_user.id
    daily_error = _check_ai_daily_limit_non_vip(user_id)
    if daily_error:
        ai_request_tracker.active_users.discard(user_id)
        markup = create_limit_reached_keyboard(user_id)
        lang = get_user_language(user_id)
        bot.reply_to(
            message,
            daily_error + "\n\n" + t(lang, "choose_action"),
            reply_markup=markup,
            parse_mode="Markdown",
        )
        return
    question = message.text.strip()
    if not question:
        return
    # Время и погоду передаём Кому — ответит в оживлённой форме (контекст подставляется в промпт)
    _run_ai_request(message, question)


@bot.message_handler(
    content_types=['voice', 'audio'],
    func=lambda message: (
        message.chat.type == 'private'
        and message.from_user
        and not message.from_user.is_bot
    )
)
@safe_handler
def private_voice_kom_handler(message: Message):
    """
    Голосовые в личке: транскрипция и ответ Кома.
    Доступ к Кому в ЛС проверяется через ensure_kom_access_or_reply.
    """
    if not ensure_user_access(message):
        return
    if not ensure_kom_access_or_reply(message):
        return
    user_id = message.from_user.id
    with user_voice_locks_lock:
        if user_voice_locks.get(user_id, False):
            try:
                bot.reply_to(
                    message,
                    "⏳ Предыдущее голосовое ещё обрабатывается. Подожди немного."
                )
            except Exception:
                pass
            return
        user_voice_locks[user_id] = True

    wait_msg = bot.reply_to(message, "🎙 Секунду, разбираю текст...")

    def worker():
        try:
            file_id = None
            filename = "voice.ogg"
            if message.voice:
                file_id = message.voice.file_id
            elif message.audio:
                file_id = message.audio.file_id
                filename = (message.audio.file_name or "audio.ogg")
            if not file_id:
                try:
                    bot.edit_message_text(
                        "❌ Не удалось получить аудиофайл",
                        message.chat.id,
                        wait_msg.message_id,
                    )
                except Exception:
                    pass
                return
            file_info = bot.get_file(file_id)
            audio_bytes = bot.download_file(file_info.file_path)
            ok, result = _transcribe_for_kom(audio_bytes, filename)
            try:
                if ok:
                    bot.edit_message_text(
                        f"📝 **Распознанный текст:**\n\n{result}",
                        message.chat.id,
                        wait_msg.message_id,
                        parse_mode="Markdown",
                    )
                    _run_ai_request(message, result)
                else:
                    bot.edit_message_text(
                        result,
                        message.chat.id,
                        wait_msg.message_id,
                    )
            except Exception as e:
                logger.exception("private_voice_kom edit/send: %s", e)
                try:
                    bot.edit_message_text(
                        "❌ Ошибка отправки результата.",
                        message.chat.id,
                        wait_msg.message_id,
                    )
                except Exception:
                    pass
        except Exception as e:
            logger.exception("private_voice_kom: %s", e)
            try:
                bot.edit_message_text(
                    f"❌ Ошибка: {str(e)[:200]}",
                    message.chat.id,
                    wait_msg.message_id,
                )
            except Exception:
                pass
        finally:
            with user_voice_locks_lock:
                user_voice_locks[user_id] = False

    threading.Thread(target=worker, daemon=True).start()


@bot.message_handler(
    content_types=['voice', 'audio'],
    func=lambda message: (
        message.chat.type in ['group', 'supergroup']
        and message.from_user
        and not message.from_user.is_bot
    )
)
@safe_handler
def group_voice_transcription_handler(message: Message):
    """
    В группах — только транскрипция голосового (без диалога с Ком).
    Работает только если в настройках группы включена транскрипция (по умолчанию выключена).
    """
    group_id = message.chat.id
    gs = get_group_settings(group_id)
    if not gs.get("voice_transcription"):
        return

    user_id = message.from_user.id

    if message.from_user.is_bot:
        return
    if message.text and message.text.startswith(("🎙", "📝", "❌")):
        return

    # ===== ПОЛЬЗОВАТЕЛЬСКАЯ БЛОКИРОВКА =====
    with user_voice_locks_lock:
        if user_voice_locks.get(user_id, False):
            try:
                bot.reply_to(
                    message,
                    "⏳ Твоё предыдущее голосовое ещё обрабатывается. Подожди немного."
                )
            except Exception:
                pass
            return
        user_voice_locks[user_id] = True
    # ========================================

    # Сразу отвечаем, что начали разбор
    try:
        wait_msg = bot.reply_to(
            message,
            "🎙 Секунду, разбираю текст..."
        )
    except Exception as e:
        logger.warning("group_voice: не удалось отправить «Секунду...»: %s", e)
        with user_voice_locks_lock:
            user_voice_locks[user_id] = False
        try:
            bot.reply_to(message, "❌ Не удалось начать распознавание. Попробуй ещё раз.")
        except Exception:
            pass
        return

    def transcribe_worker():
        old_limit = sys.getrecursionlimit()
        text = ""
        try:
            # Таймаут 60 сек (только на Unix, в потоке может не сработать)
            try:
                import signal
                if hasattr(signal, "SIGALRM"):
                    def _timeout_handler(signum, frame):
                        raise TimeoutError("Распознавание заняло слишком много времени")
                    signal.signal(signal.SIGALRM, _timeout_handler)
                    signal.alarm(60)
            except (AttributeError, ValueError, OSError):
                pass

            # Получаем файл
            file_id = None
            filename = "voice.ogg"

            if message.voice:
                file_id = message.voice.file_id
            elif message.audio:
                file_id = message.audio.file_id
                filename = message.audio.file_name or "audio.ogg"

            if not file_id:
                try:
                    bot.edit_message_text(
                        "❌ Не удалось получить аудиофайл",
                        message.chat.id,
                        wait_msg.message_id
                    )
                except Exception:
                    try:
                        bot.reply_to(message, "❌ Не удалось получить аудиофайл")
                    except Exception:
                        pass
                return

            # Скачиваем
            file_info = bot.get_file(file_id)
            audio_bytes = bot.download_file(file_info.file_path)

            # Распознаём (поднимаем лимит рекурсии для библиотеки)
            import tempfile
            sys.setrecursionlimit(50000)
            try:
                with tempfile.NamedTemporaryFile(suffix=os.path.splitext(filename)[1] or ".ogg", delete=True) as tmp:
                    tmp.write(audio_bytes)
                    tmp.flush()

                    model = _get_ai_stt_model()

                    segments, _ = model.transcribe(tmp.name, beam_size=3, vad_filter=True)
                    text = " ".join((seg.text or "").strip() for seg in segments).strip()
            finally:
                sys.setrecursionlimit(old_limit)

            try:
                import signal
                if hasattr(signal, "alarm"):
                    signal.alarm(0)
            except (AttributeError, ValueError, OSError):
                pass

            if not text:
                try:
                    bot.edit_message_text(
                        "❌ Не удалось распознать речь (пустой результат)",
                        message.chat.id,
                        wait_msg.message_id
                    )
                except Exception:
                    try:
                        bot.reply_to(message, "❌ Не удалось распознать речь (пустой результат)")
                    except Exception:
                        pass
                return

            # Пост-обработка через DeepSeek (пунктуация, грамматика, без слов-паразитов)
            text = _clean_transcription_with_deepseek(text)

            # Отправляем результат транскрипции (edit или reply, если в группе нет прав на edit)
            transcription_text = f"📝 **Распознанный текст:**\n\n{text}"
            try:
                bot.edit_message_text(
                    transcription_text,
                    message.chat.id,
                    wait_msg.message_id,
                    parse_mode="Markdown"
                )
            except Exception:
                try:
                    bot.reply_to(message, transcription_text, parse_mode="Markdown")
                except Exception:
                    pass

        except TimeoutError:
            logger.error("Таймаут распознавания голоса для пользователя %s", user_id)
            err_text = "❌ Распознавание заняло слишком много времени. Попробуй ещё раз."
            try:
                bot.edit_message_text(err_text, message.chat.id, wait_msg.message_id)
            except Exception:
                try:
                    bot.reply_to(message, err_text)
                except Exception:
                    pass
        except RecursionError as e:
            logger.error("RecursionError при распознавании голоса: %s", e)
            err_text = "❌ Ошибка распознавания (перегрузка). Попробуй короче голосовое или позже."
            try:
                bot.edit_message_text(err_text, message.chat.id, wait_msg.message_id)
            except Exception:
                try:
                    bot.reply_to(message, err_text)
                except Exception:
                    pass
        except Exception as e:
            logger.error("Ошибка распознавания голоса в группе: %s", e)
            err_text = f"❌ Ошибка распознавания: {str(e)[:200]}"
            try:
                bot.edit_message_text(err_text, message.chat.id, wait_msg.message_id)
            except Exception:
                try:
                    bot.reply_to(message, err_text)
                except Exception:
                    pass
        finally:
            sys.setrecursionlimit(old_limit)
            # ===== СНИМАЕМ БЛОКИРОВКУ ПОЛЬЗОВАТЕЛЯ =====
            with user_voice_locks_lock:
                user_voice_locks[user_id] = False
            # ==========================================

    # Запускаем в отдельном потоке
    threading.Thread(target=transcribe_worker, daemon=True).start()


def _cleanup_voice_locks():
    """Периодическая очистка зависших блокировок голосовых (каждые 5 мин)."""
    while True:
        time.sleep(300)
        with user_voice_locks_lock:
            pass


_cleanup_voice_thread = threading.Thread(target=_cleanup_voice_locks, daemon=True)
_cleanup_voice_thread.start()


