# Создаём экземпляр ИИ
ai_assistant = AIAssistant()

def send_self_profile_with_preview(chat_id: int, user) -> None:
    """Профиль для себя: в группе — полная карточка со статистикой сообщений по этой группе; в личке — только общие данные без статистики по чату.
    Вся статистика (сообщения, предупреждения, дата вступления в группу) привязана к переданному chat_id — в разных группах разная статистика."""
    user_id = user.id
    # Обновляем first_name/username в БД из Telegram, чтобы в карточке не отображалось «ID 123»
    update_user_info(user_id, user)
    if getattr(user, "is_bot", False) or is_excluded_bot_user(user_id):
        bot.send_message(chat_id, "🤖 Для ботов персональная статистика отключена.")
        return
    in_group = isinstance(chat_id, int) and chat_id < 0
    if in_group:
        ensure_user_group_joined(user_id, datetime.now(), source="observed_private_check", chat_id=chat_id)
    lang = get_user_language(user_id)
    name_for_display = (getattr(user, "first_name", None) or "").strip() or _resolve_profile_display_name(user_id, chat_id if in_group else None, lang, in_group, getattr(user, "first_name", None))
    balance = get_balance(user_id)
    city = get_user_city(user_id)
    lifecycle = _get_user_lifecycle(user_id, chat_id if in_group else None)
    chat_type = "supergroup" if in_group else "private"
    display_rank = get_user_rank_for_display(user_id, chat_type, chat_id=chat_id if in_group else None)
    if in_group and chat_id:
        status_name = get_group_rank_display_name(chat_id, display_rank, lang=lang)
    else:
        status_name = get_rank_name(display_rank, in_group=in_group)
    privileges = get_privileges_display(user_id, group_id=chat_id if in_group else None)
    vip_expiry_line = get_vip_expiry_display(user_id, group_id=chat_id if in_group else None, lang=lang)
    maybe_notify_vip_expiring(user_id)
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton(t(lang, "profile_btn_transactions"), callback_data=f"profile_balance_{user_id}"),
        InlineKeyboardButton(t(lang, "profile_btn_stats"), callback_data=f"profile_stats_{user_id}"),
        InlineKeyboardButton(t(lang, "profile_btn_achievements"), callback_data=f"profile_achievements_{user_id}"),
        InlineKeyboardButton(t(lang, "profile_btn_history"), callback_data=f"profile_history_{user_id}"),
        InlineKeyboardButton(t(lang, "my_referrals_title"), callback_data=f"profile_referrals_{user_id}"),
        InlineKeyboardButton(t(lang, "my_commissions_title"), callback_data=f"profile_commission_{user_id}"),
        InlineKeyboardButton(t(lang, "my_relations_title"), callback_data=f"profile_relations_{user_id}"),
        InlineKeyboardButton(t(lang, "my_family_title"), callback_data=f"profile_marriage_{user_id}"),
    )
    markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))

    if not in_group:
        # В личке — только общие данные, без статистики сообщений и без «В группе с»
        # Ник целиком под контролем пользователя (/nick), а карточка уходит
        # с parse_mode="Markdown". Экранируем весь служебный набор, а не одну
        # "]": иначе `[Поддержка](https://evil)` в нике становится живой
        # ссылкой от имени бота, а одиночная * / _ / ` ломает разбор и
        # карточка падает в «Временная ошибка».
        safe_nick = _escape_markdown_caption(get_user_display_name_in_bot(user_id, name_for_display or "—"))
        nick_link = f"[{safe_nick}](tg://user?id={user_id})"
        card_title = t(lang, "profile_card_title")
        registered_str = format_datetime_for_user(lifecycle.get("joined_date"), lang)
        city_display = city if city else "—"
        # Город — свободный ввод пользователя (/city), та же Markdown-ветка.
        city_line = f"📍 **{t(lang, 'city_label')}:** {_escape_markdown_caption(city_display)}\n"
        if not city:
            city_line += f"   _{t(lang, 'city_profile_hint')}_\n"
        text = (
            f"🪪 **{card_title}**\n\n"
            f"👤 {nick_link}\n"
            f"🆔 `{user_id}`\n"
            f"{city_line}"
            f"🕰 **{t(lang, 'in_bot_since_label')}:** {registered_str}\n"
            f"👤 **{t(lang, 'status_label')}:** {status_name}\n"
            f"📋 **{t(lang, 'privileges_label')}:** {privileges}{vip_expiry_line}\n"
            f"💰 {t(lang, 'balance_label')}: {_profile_balance_display(user_id, balance, lang, for_markdown=True)}\n\n"
            f"💬 {t(lang, 'profile_card_group_only')}"
        )
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
        return

    # В группе — полная карточка: статистика только по этой группе (chat_id = текущий чат)
    stats = get_user_message_stats(user_id, chat_id)
    period_days = normalize_stats_periods(STATS_PERIOD_DAYS)
    period_rows = [(d, get_message_count_for_days(chat_id, d, user_id=user_id)) for d in period_days]
    group_admin_line = (
        "\n👥 **Group admin of this chat:** yes"
        if (lang == "en" and has_group_admin_rights(user_id, chat_id))
        else ("\n👥 **Админ этой группы:** да" if has_group_admin_rights(user_id, chat_id) else "")
    )
    msg_since_join, _ = get_messages_since_group_join(user_id, chat_id)
    total_msgs = stats.get("total", 0)
    mod_block_self = ""
    mod_block_self_html = ""
    # Для владельца группы (creator) блок предупреждений не показываем
    if get_chat_creator_id(chat_id) != user_id:
        warn_count = get_warnings_count(user_id, chat_id)
        max_w = get_effective_warn_limit(chat_id)
        last_logs = get_moderation_logs(limit=3, user_id=user_id, chat_id=chat_id, days=90)
        mod_block_self = f"\n⚠️ **{t(lang, 'warnings_in_chat')}:** `{warn_count}` / {max_w}\n"
        mod_block_self_html = f"\n⚠️ <b>{t(lang, 'warnings_in_chat')}:</b> <code>{warn_count}</code> / {max_w}\n"
    else:
        last_logs = []
    if last_logs:
        parts = []
        parts_html = []
        for log in last_logs:
            act = log.get("action", "")
            act_label = _log_action_label(lang, act)
            reason = (log.get("reason") or "").strip() or "—"
            date_raw = log.get("date")
            # В некоторых случаях sqlite/ORM возвращает datetime, а не строку.
            # Форматируем универсально и приводим к виду "DD.MM.YYYY HH:MM" без суффикса UTC/МСК.
            date_str = format_datetime_for_user(date_raw, lang)
            if date_str != "—":
                date_str = date_str.replace(" UTC", "").replace(" МСК", "")
            parts.append(f"  • {act_label} ({date_str}): {reason[:50]}")
            parts_html.append(f"  • {_escape_html_caption(act_label)} ({date_str}): {_escape_html_caption(reason[:50])}")
        mod_block_self += "📋 **" + t(lang, "profile_last_actions") + ":**\n" + "\n".join(parts) + "\n"
        mod_block_self_html += "📋 <b>" + _escape_html_caption(t(lang, "profile_last_actions")) + ":</b>\n" + "\n".join(parts_html) + "\n"
    try:
        p_map = {int(d): int(v or 0) for d, v in period_rows}
        if lang == "en":
            today_label = "Today"
            day_label = lambda n: f"{n} day(s)"
            total_label = "Total"
        else:
            today_label = "сегодня"
            day_label = lambda n: f"{n} дн."
            total_label = "всего"

        preview_rows = [(today_label if d == 1 else day_label(d), int(v) if v is not None else 0) for d, v in period_rows]
        preview_rows.append((total_label, int(total_msgs)))
        preview = create_stats_preview_image(
            ("Card: " if lang == "en" else "Карточка: ")
            + get_user_display_name_in_chat(user_id, chat_id, name_for_display or ("You" if lang == "en" else "Вы")),
            preview_rows,
            "Personal activity graph" if lang == "en" else "Личный график активности",
            allow_emoji=True,
        )
        nick_display = get_user_display_name_in_chat(user_id, chat_id, name_for_display or "—")
        nick_display_esc = _escape_html_caption(nick_display)
        nick_link = f'<a href="tg://user?id={user_id}">{nick_display_esc}</a>'
        city_display = city if city else "—"
        city_esc = _escape_html_caption(city_display)
        city_line_html = f"📍 {t(lang, 'city_label')}: <b>{city_esc}</b>\n"
        if not city:
            city_line_html += f"   <i>{t(lang, 'city_profile_hint')}</i>\n"
        registered_str = format_datetime_for_user(lifecycle.get("joined_date"), lang)
        group_join_str = _format_group_join_label(lifecycle, use_msk=(lang == "ru"), lang=lang)
        joined_esc = _escape_html_caption(registered_str)
        group_join_esc = _escape_html_caption(group_join_str)
        status_esc = _escape_html_caption(status_name)
        priv_esc = _escape_html_caption(privileges)
        admin_line_html = (
            "\n👥 <b>Group admin of this chat:</b> yes"
            if (lang == "en" and has_group_admin_rights(user_id, chat_id))
            else ("\n👥 <b>Админ этой группы:</b> да" if has_group_admin_rights(user_id, chat_id) else "")
        )
        card_title = t(lang, "profile_card_title")
        messages_header = t(lang, "messages_in_group")
        caption = (
            f"🪪 <b>{card_title}</b>\n"
            f"👤 {nick_link}\n"
            f"🆔 <code>{user_id}</code>\n"
            f"{city_line_html}"
            f"🕰 {t(lang, 'in_bot_since_label')}: <b>{joined_esc}</b>\n"
            f"👥 {t(lang, 'in_group_since_label')}: <b>{group_join_esc}</b>\n"
            f"👤 {t(lang, 'status_label')}: <b>{status_esc}</b>\n"
            f"📋 {t(lang, 'privileges_label')}: <b>{priv_esc}</b>{admin_line_html}\n"
            f"💰 {t(lang, 'balance_label')}: {_escape_html_caption(_profile_balance_display(user_id, balance, lang, for_markdown=False))}\n\n"
            f"💬 <b>{messages_header}</b>\n"
            f"• {t(lang, 'today')}: <code>{p_map.get(1, 0)}</code>\n"
            f"• {t(lang, 'last_7_days')}: <code>{p_map.get(7, 0)}</code>\n"
            f"• {t(lang, 'last_30_days')}: <code>{p_map.get(30, 0)}</code>\n"
            f"• {t(lang, 'since_join')}: <code>{msg_since_join if msg_since_join is not None else '—'}</code>\n"
            f"• {t(lang, 'total')}: <code>{total_msgs}</code>{mod_block_self_html}"
        )
        cap = (caption or "").strip()
        if len(cap) > 1000:
            cap = _truncate_preserving_emoji(cap, 997) + "…"
            parse_mode = None
        else:
            parse_mode = "HTML"
        doc = io.BytesIO(preview or b"")
        doc.name = "profile_stats.png"
        bot.send_photo(chat_id, doc, caption=cap, parse_mode=parse_mode, reply_markup=markup)
    except Exception as e:
        logger.error(f"Ошибка создания превью профиля: {e}")
        safe_nick = _escape_markdown_caption(get_user_display_name_in_chat(user_id, chat_id, name_for_display or "—"))
        nick_link = f"[{safe_nick}](tg://user?id={user_id})"
        card_title = t(lang, "profile_card_title")
        registered_str = format_datetime_for_user(lifecycle.get("joined_date"), lang)
        group_join_str = _format_group_join_label(lifecycle, use_msk=(lang == "ru"), lang=lang)
        period_lines = "\n".join(
            [
                f"• {t(lang, 'today') if d == 1 else t(lang, 'last_7_days') if d == 7 else t(lang, 'last_30_days') if d == 30 else (str(d) + (' day(s)' if lang == 'en' else ' дн.'))}: `{v or 0}`"
                for d, v in period_rows
            ]
        )
        city_display_fb = city if city else "—"
        city_line_fb = f"📍 **{t(lang, 'city_label')}:** {_escape_markdown_caption(city_display_fb)}\n"
        if not city:
            city_line_fb += f"   _{t(lang, 'city_profile_hint')}_\n"
        text = (
            f"🪪 **{card_title}**\n\n"
            f"👤 {nick_link}\n"
            f"🆔 `{user_id}`\n"
            f"{city_line_fb}"
            f"🕰 **{t(lang, 'in_bot_since_label')}:** {registered_str}\n"
            f"👥 **{t(lang, 'in_group_since_label')}:** {group_join_str}\n"
            f"👤 **{t(lang, 'status_label')}:** {status_name}\n"
            f"📋 **{t(lang, 'privileges_label')}:** {privileges}{vip_expiry_line}{group_admin_line}\n"
            f"💰 {t(lang, 'balance_label')}: {_profile_balance_display(user_id, balance, lang, for_markdown=True)}\n\n"
            f"💬 **{t(lang, 'messages_in_group')}**\n{period_lines}\n"
            f"• {t(lang, 'since_join')}: `{msg_since_join if msg_since_join is not None else '—'}`\n"
            f"• {t(lang, 'total')}: `{total_msgs}`{mod_block_self}"
        )
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")


def send_profile_card(chat_id: int, target_id: int, viewer_id: Optional[int] = None, lang: Optional[str] = None) -> None:
    """Карточка профиля: в группе — с статистикой сообщений по этой группе; в личке — только общие данные без статистики по чату.
    В группе вся статистика (сообщения, предупреждения, дата вступления) привязана к chat_id — в разных группах разная статистика. viewer_id — кто смотрит. lang — язык (если None, у target_id)."""
    register_user(target_id)
    stats = get_user_stats(target_id) or {
        "games_played": 0,
        "games_won": 0,
        "win_rate": 0.0,
        "total_earned": 0,
        "total_spent": 0,
    }
    balance = get_balance(target_id)
    in_group = isinstance(chat_id, int) and chat_id < 0
    display_rank = get_user_rank_for_display(target_id, "supergroup" if in_group else "private", chat_id=chat_id if in_group else None)
    if in_group and chat_id:
        status_name = get_group_rank_display_name(chat_id, display_rank, lang=lang or get_user_language(target_id))
    else:
        status_name = get_rank_name(display_rank, in_group=in_group)
    privileges = get_privileges_display(target_id, group_id=chat_id if in_group else None)
    vip_expiry_line = get_vip_expiry_display(target_id, group_id=chat_id if in_group else None, lang=lang or get_user_language(target_id))
    group_admin_line = (
        "\n👥 **Group admin of this chat:** yes"
        if (in_group and lang == "en" and has_group_admin_rights(target_id, chat_id))
        else ("\n👥 **Админ этой группы:** да" if (in_group and has_group_admin_rights(target_id, chat_id)) else "")
    )
    achievements_count = len(get_user_achievements(target_id))
    # В группе — данные по этой группе (chat_id); в личке — только «в боте с», без групповой статистики
    effective_chat = chat_id if in_group else None
    if in_group and effective_chat:
        ensure_user_group_joined(target_id, datetime.now(), source="observed_private_check", chat_id=effective_chat)
    lifecycle = _get_user_lifecycle(target_id, effective_chat)

    city = get_user_city(target_id)
    if lang is None:
        lang = get_user_language(target_id)
    first_name = _resolve_profile_display_name(target_id, chat_id if in_group else None, lang, in_group)
    display_name = get_user_display_name_in_chat(target_id, chat_id if in_group else None, first_name or "")
    mod_block = ""
    last_logs = []
    if in_group and chat_id and get_chat_creator_id(chat_id) != target_id:
        warn_count = get_warnings_count(target_id, chat_id)
        max_w = get_effective_warn_limit(chat_id)
        last_logs = get_moderation_logs(limit=3, user_id=target_id, chat_id=chat_id, days=90)
        mod_block = f"\n⚠️ **{t(lang, 'warnings_in_chat')}:** `{warn_count}` / {max_w}\n"
        if last_logs:
            parts = []
            for log in last_logs:
                act = log.get("action", "")
                act_label = _log_action_label(lang, act)
                reason = (log.get("reason") or "").strip() or "—"
                date_raw = log.get("date")
                date_str = format_datetime_for_user(date_raw, lang)
                if date_str != "—":
                    date_str = date_str.replace(" UTC", "").replace(" МСК", "")
                parts.append(f"  • {act_label} ({date_str}): {reason[:50]}")
            mod_block += "📋 **" + t(lang, "profile_last_actions") + ":**\n" + "\n".join(parts) + "\n"

    profile_title = t(lang, "profile_view_title")
    registered_str = format_datetime_for_user(lifecycle.get("joined_date"), lang)
    group_join_str = _format_group_join_label(lifecycle, use_msk=(lang == "ru"), lang=lang) if in_group else ""
    markup = InlineKeyboardMarkup(row_width=2)
    is_own_profile = viewer_id is not None and viewer_id == target_id
    if is_own_profile:
        markup.add(
            InlineKeyboardButton(t(lang, "profile_btn_transactions"), callback_data=f"profile_balance_{target_id}"),
            InlineKeyboardButton(t(lang, "profile_btn_stats"), callback_data=f"profile_stats_{target_id}"),
            InlineKeyboardButton(t(lang, "profile_btn_achievements"), callback_data=f"profile_achievements_{target_id}"),
            InlineKeyboardButton(t(lang, "profile_btn_history"), callback_data=f"profile_history_{target_id}"),
        )
        markup.add(
            InlineKeyboardButton(t(lang, "my_relations_title"), callback_data=f"profile_relations_{target_id}"),
            InlineKeyboardButton(t(lang, "my_family_title"), callback_data=f"profile_marriage_{target_id}"),
        )
    else:
        # Чужой профиль («кто ты?»): только неприватные кнопки — достижения
        markup.add(InlineKeyboardButton(t(lang, "profile_btn_achievements"), callback_data=f"profile_achievements_{target_id}"))
    # В группе — кнопка закрытия профиля (удаление сообщения); в личке — «В меню»
    if in_group:
        markup.add(InlineKeyboardButton("❌ " + t(lang, "user_close_btn"), callback_data="profile_close"))
    else:
        markup.add(InlineKeyboardButton("🔙 " + t(lang, "back_to_menu"), callback_data="main_menu"))

    if in_group:
        msg_since_join, _ = get_messages_since_group_join(target_id, chat_id)
        city_display = city if city else "—"
        # Город — свободный ввод пользователя (/city), та же Markdown-ветка.
        city_line = f"📍 **{t(lang, 'city_label')}:** {_escape_markdown_caption(city_display)}\n"
        if not city:
            city_line += f"   _{t(lang, 'city_profile_hint')}_\n"
        text = (
            f"👤 **{profile_title}**\n\n"
            f"👤 **{'Name' if lang == 'en' else 'Имя'}:** {_escape_markdown_caption(display_name)}\n"
            f"🆔 ID: `{target_id}`\n"
            f"{city_line}"
            f"🕰 **{t(lang, 'in_bot_since_label')}:** {registered_str}\n"
            f"👥 **{t(lang, 'in_group_since_label')}:** {group_join_str}\n"
            f"💬 **{t(lang, 'since_join')}:** `{msg_since_join if msg_since_join is not None else '—'}`\n"
            f"👤 **{t(lang, 'status_label')}:** {status_name}\n"
            f"📋 **{t(lang, 'privileges_label')}:** {privileges}{vip_expiry_line}{group_admin_line}\n"
            f"💰 {t(lang, 'balance_label')}: {_profile_balance_display(target_id, balance, lang, for_markdown=True)}\n"
            + (  # translate hardcoded labels for EN
                f"🎮 Games: `{stats.get('games_played', 0)}`\n"
                f"🏆 Wins: `{stats.get('games_won', 0)}` ({stats.get('win_rate', 0):.1f}%)\n"
                f"💸 Earned: `{format_number(stats.get('total_earned', 0))}` {COM_EMOJI}\n"
                f"💳 Spent: `{format_number(stats.get('total_spent', 0))}` {COM_EMOJI}\n"
                f"🏆 Achievements: `{achievements_count}`{mod_block}"
                if lang == "en"
                else f"🎮 Игр: `{stats.get('games_played', 0)}`\n"
                f"🏆 Побед: `{stats.get('games_won', 0)}` ({stats.get('win_rate', 0):.1f}%)\n"
                f"💸 Заработано: `{format_number(stats.get('total_earned', 0))}` {COM_EMOJI}\n"
                f"💳 Потрачено: `{format_number(stats.get('total_spent', 0))}` {COM_EMOJI}\n"
                f"🏆 Достижений: `{achievements_count}`{mod_block}"
            )
        )
        # Превью-график по сообщениям в группе (как у своего профиля)
        try:
            stats_msg = get_user_message_stats(target_id, chat_id)
            period_days = normalize_stats_periods(STATS_PERIOD_DAYS)
            period_rows = [(d, get_message_count_for_days(chat_id, d, user_id=target_id)) for d in period_days]
            total_msgs = stats_msg.get("total", 0)
            p_map = {int(d): int(v or 0) for d, v in period_rows}
            if lang == "en":
                today_label = "Today"
                day_label = lambda n: f"{n} day(s)"
                total_label = "Total"
            else:
                today_label = "сегодня"
                day_label = lambda n: f"{n} дн."
                total_label = "всего"

            preview_rows = [
                (today_label if d == 1 else day_label(d), int(v) if v is not None else 0)
                for d, v in period_rows
            ]
            preview_rows.append((total_label, int(total_msgs)))
            preview = create_stats_preview_image(
                ("Card: " if lang == "en" else "Карточка: ") + display_name,
                preview_rows,
                "Personal activity graph" if lang == "en" else "Личный график активности",
                allow_emoji=True,
            )
            mod_block_html = ""
            if get_chat_creator_id(chat_id) != target_id:
                mod_block_html = f"\n⚠️ <b>{t(lang, 'warnings_in_chat')}:</b> <code>{warn_count}</code> / {max_w}\n"
                if last_logs:
                    mod_block_html += "📋 <b>Recent actions:</b>\n" if lang == "en" else "📋 <b>Последние действия:</b>\n"
                    for log in last_logs:
                        act = log.get("action", "")
                        reason = (log.get("reason") or "").strip() or "—"
                        date_raw = log.get("date")
                        date_str = format_datetime_for_user(date_raw, lang)
                        if date_str != "—":
                            date_str = date_str.replace(" UTC", "").replace(" МСК", "")
                        mod_block_html += f"  • {_escape_html_caption(act)} ({date_str}): {_escape_html_caption(reason[:50])}\n"
            nick_display_esc = _escape_html_caption(display_name)
            nick_link = f'<a href="tg://user?id={target_id}">{nick_display_esc}</a>'
            city_display_o = city if city else "—"
            city_esc = _escape_html_caption(city_display_o)
            city_line_html_o = f"📍 {t(lang, 'city_label')}: <b>{city_esc}</b>\n"
            if not city:
                city_line_html_o += f"   <i>{t(lang, 'city_profile_hint')}</i>\n"
            joined_esc = _escape_html_caption(registered_str)
            group_join_esc = _escape_html_caption(group_join_str)
            status_esc = _escape_html_caption(status_name)
            priv_esc = _escape_html_caption(privileges)
            vip_expiry_esc = "\n" + _escape_html_caption(vip_expiry_line.strip()) if vip_expiry_line else ""
            admin_line_html = (
                "\n👥 <b>Group admin of this chat:</b> yes"
                if (lang == "en" and in_group and has_group_admin_rights(target_id, chat_id))
                else ("\n👥 <b>Админ этой группы:</b> да" if (in_group and has_group_admin_rights(target_id, chat_id)) else "")
            )
            messages_header = t(lang, "messages_in_group")
            caption = (
                f"👤 <b>{profile_title}</b>\n"
                f"👤 {nick_link}\n"
                f"🆔 <code>{target_id}</code>\n"
                f"{city_line_html_o}"
                f"🕰 {t(lang, 'in_bot_since_label')}: <b>{joined_esc}</b>\n"
                f"👥 {t(lang, 'in_group_since_label')}: <b>{group_join_esc}</b>\n"
                f"👤 {t(lang, 'status_label')}: <b>{status_esc}</b>\n"
                f"📋 {t(lang, 'privileges_label')}: <b>{priv_esc}</b>{vip_expiry_esc}{admin_line_html}\n"
                f"💰 {t(lang, 'balance_label')}: {_escape_html_caption(_profile_balance_display(target_id, balance, lang, for_markdown=False))}\n\n"
                f"💬 <b>{messages_header}</b>\n"
                f"• {t(lang, 'today')}: <code>{p_map.get(1, 0)}</code>\n"
                f"• {t(lang, 'last_7_days')}: <code>{p_map.get(7, 0)}</code>\n"
                f"• {t(lang, 'last_30_days')}: <code>{p_map.get(30, 0)}</code>\n"
                f"• {t(lang, 'since_join')}: <code>{msg_since_join if msg_since_join is not None else '—'}</code>\n"
                f"• {t(lang, 'total')}: <code>{total_msgs}</code>{mod_block_html}"
            )
            cap = (caption or "").strip()
            if len(cap) > 1000:
                cap = _truncate_preserving_emoji(cap, 997) + "…"
                parse_mode = None
            else:
                parse_mode = "HTML"
            doc = io.BytesIO(preview or b"")
            doc.name = "profile_stats.png"
            bot.send_photo(chat_id, doc, caption=cap, parse_mode=parse_mode, reply_markup=markup)
        except Exception as e:
            logger.debug("Превью профиля (чужой): %s", e)
            bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")
    else:
        city_display_p = city if city else "—"
        city_line_p = f"📍 **{t(lang, 'city_label')}:** {_escape_markdown_caption(city_display_p)}\n"
        if not city:
            city_line_p += f"   _{t(lang, 'city_profile_hint')}_\n"
        text = (
            f"👤 **{profile_title}**\n\n"
            f"👤 **{'Name' if lang == 'en' else 'Имя'}:** {_escape_markdown_caption(display_name)}\n"
            f"🆔 ID: `{target_id}`\n"
            f"{city_line_p}"
            f"🕰 **{t(lang, 'in_bot_since_label')}:** {registered_str}\n"
            f"👤 **{t(lang, 'status_label')}:** {status_name}\n"
            f"📋 **{t(lang, 'privileges_label')}:** {privileges}{vip_expiry_line}\n"
            f"💰 {t(lang, 'balance_label')}: {_profile_balance_display(target_id, balance, lang, for_markdown=True)}\n"
            f"🎮 {'Games' if lang == 'en' else 'Игр'}: `{stats.get('games_played', 0)}`\n"
            f"🏆 {'Wins' if lang == 'en' else 'Побед'}: `{stats.get('games_won', 0)}` ({stats.get('win_rate', 0):.1f}%)\n"
            f"💸 {'Earned' if lang == 'en' else 'Заработано'}: `{format_number(stats.get('total_earned', 0))}` {COM_EMOJI}\n"
            f"💳 {'Spent' if lang == 'en' else 'Потрачено'}: `{format_number(stats.get('total_spent', 0))}` {COM_EMOJI}\n"
            f"🏆 {'Achievements' if lang == 'en' else 'Достижений'}: `{achievements_count}`\n\n"
            f"_{t(get_user_language(chat_id), 'profile_card_group_only_other')}_"
        )
        bot.send_message(chat_id, text, reply_markup=markup, parse_mode="Markdown")


def find_user_by_username(chat_id: int, username: str):
    """Ищет пользователя по username: в группе через get_chat_member, иначе в БД. Возвращает User-like объект с .id или None."""
    username = (username or "").strip().lstrip("@")
    if not username:
        return None
    if isinstance(chat_id, int) and chat_id < 0:
        try:
            member = bot.get_chat_member(chat_id, username)
            if member and getattr(member, "user", None):
                return member.user
        except Exception:
            pass
    try:
        rows = execute_query(
            USERS_DB,
            "SELECT user_id, first_name FROM users WHERE LOWER(REPLACE(COALESCE(username, ''), '@', '')) = ? LIMIT 1",
            (username.lower(),),
        )
        if rows and rows[0][0]:
            uid, fn = int(rows[0][0]), (rows[0][1] if len(rows[0]) > 1 else None)
            return type("User", (), {"id": uid, "first_name": fn or username, "username": username, "is_bot": False})()
    except Exception as e:
        logger.debug("find_user_by_username %s: %s", username, e)
    return None


@bot.message_handler(commands=['profile', 'info', 'инфо', 'kom_profile'])
@safe_handler
@require_category("profile")
def cmd_profile(message: Message):
    """Команда профиля: свой профиль или профиль по reply/упоминанию (@username)."""
    if not ensure_user_access(message):
        return
    chat_id = message.chat.id
    viewer_id = message.from_user.id
    target_user = None
    if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
        target_user = message.reply_to_message.from_user
    if not target_user and getattr(message, "entities", None):
        for entity in message.entities:
            tp = getattr(entity, "type", None)
            if tp == "text_mention" and getattr(entity, "user", None):
                target_user = entity.user
                break
            if tp == "mention":
                off = getattr(entity, "offset", 0)
                length = getattr(entity, "length", 0)
                mention_text = (message.text or "")[off : off + length]
                target_user = find_user_by_username(chat_id, mention_text)
                if target_user:
                    break
    if not target_user:
        send_self_profile_with_preview(chat_id, message.from_user)
        return
    target_id = target_user.id
    if target_id == viewer_id:
        send_self_profile_with_preview(chat_id, message.from_user)
        return
    can_view, error_msg = can_view_profile(viewer_id, target_id, chat_id if chat_id < 0 else None)
    if not can_view:
        lang = get_user_language(viewer_id)
        bot.reply_to(message, error_msg or t(lang, "view_profile_denied"))
        return
    send_profile_card(chat_id, target_id, viewer_id=viewer_id)


def can_view_profile(viewer_id: int, target_id: int, chat_id: Optional[int] = None) -> Tuple[bool, Optional[str]]:
    """Проверяет, может ли viewer смотреть профиль target. Возвращает (разрешено, сообщение об ошибке)."""
    if viewer_id == target_id:
        return True, None
    if viewer_id in DEVELOPER_IDS:
        return True, None
    if chat_id is not None and chat_id < 0 and has_group_admin_rights(viewer_id, chat_id):
        return True, None
    if chat_id is not None and chat_id < 0:
        min_rank = get_min_rank_for_view_profiles(chat_id)
        viewer_rank = get_user_rank(viewer_id)
        if viewer_rank < min_rank:
            lang = get_user_language(viewer_id)
            return False, t(lang, "view_profile_rank_required", rank=min_rank)
    return True, None


def _can_view_profile(viewer_id: int, target_id: int, chat_id: Optional[int] = None) -> bool:
    """Проверяет, может ли viewer смотреть детали профиля target (баланс, транзакции, достижения, история)."""
    if viewer_id == target_id:
        return True
    if viewer_id in DEVELOPER_IDS:
        return True
    return bool(has_permission_in_chat(viewer_id, chat_id, "can_see_hidden"))


@bot.message_handler(commands=["debug_vip"])
@safe_handler
def cmd_debug_vip(message: Message):
    """Проверка VIP-статуса (для диагностики)."""
    if not ensure_user_access(message):
        return
    user_id = message.from_user.id
    chat_id = message.chat.id if message.chat.type in ("group", "supergroup") else None
    vip = ItemEffects.get_vip_profile(user_id, group_id=chat_id)
    text = "📊 **VIP ДИАГНОСТИКА**\n\n"
    text += f"👤 User ID: `{user_id}`\n"
    text += f"👥 Group ID: `{chat_id}`\n\n"
    if vip:
        expires_ts = vip.get("expires", 0)
        try:
            exp_dt = datetime.fromtimestamp(expires_ts)
            days_left = (exp_dt - datetime.now()).days
            text += "✅ **VIP активен**\n"
            text += f"📅 Истекает: {exp_dt.strftime('%d.%m.%Y %H:%M')}\n"
            text += f"⏳ Осталось дней: {days_left}\n"
        except Exception:
            text += "✅ **VIP активен**\n"
        text += f"📦 Бонус за сообщения: +{vip.get('message_bonus', 0)}\n"
        text += f"📈 Бонус к daily: +{vip.get('daily_bonus_percent', 0)}%\n"
        text += f"💰 Скидка на налог: {vip.get('tax_discount_percent', 0)}%"
    else:
        text += "❌ VIP не активен"
    bot.reply_to(message, text, parse_mode="Markdown")


def _edit_profile_message(chat_id: int, message_id: int, text: str, parse_mode: str = "Markdown") -> None:
    """Редактирует сообщение профиля: если это фото (карточка в группе) — правим caption, иначе — text."""
    try:
        bot.edit_message_text(text, chat_id, message_id, parse_mode=parse_mode)
    except Exception as e:
        err = str(e).lower()
        if "no text in the message" in err or "message to edit" in err:
            try:
                bot.edit_message_caption(chat_id=chat_id, message_id=message_id, caption=text, parse_mode=parse_mode)
            except Exception as e2:
                logger.warning("profile_callback edit_message_caption: %s", e2)
        else:
            raise


@bot.callback_query_handler(func=lambda call: call.data.startswith('profile_') and not call.data.startswith('profile_back_'))
def profile_callback(call: CallbackQuery):
    """Обработчик кнопок профиля."""
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    if not getattr(call, 'from_user', None):
        return
    parts = call.data.split('_')
    if len(parts) < 3:
        bot.answer_callback_query(call.id, "❌ Неверный формат", show_alert=True)
        return
    try:
        action = parts[1]
        target_id = int(parts[2])
    except (ValueError, TypeError, IndexError):
        bot.answer_callback_query(call.id, "❌ Неверный формат", show_alert=True)
        return
    viewer_id = call.from_user.id
    chat_id = getattr(call.message.chat, "id", None) if getattr(call.message, "chat", None) else None

    if not _can_view_profile(viewer_id, target_id, chat_id):
        lang = get_user_language(viewer_id)
        bot.answer_callback_query(call.id, _truncate_preserving_emoji(t(lang, "not_for_you"), 200), show_alert=True)
        return

    lang = get_user_language(viewer_id)
    msg = getattr(call, "message", None)
    _edit = lambda t, pm="Markdown": _edit_profile_message(msg.chat.id, msg.message_id, t, pm) if msg else None

    if action == "balance":
        # Показываем историю баланса в валюте смотрящего
        balance = get_balance(target_id)
        transactions = get_transaction_history(target_id, limit=5)
        balance_str = format_amount_for_user(viewer_id, balance)
        text = t(lang, "profile_balance_title")
        text += f"{t(lang, 'profile_balance_current')} {balance_str}\n\n"
        
        if transactions:
            text += t(lang, "profile_last_ops")
            for tx in transactions:
                if tx['from_id'] == target_id:
                    sign = "-"
                    other = tx['to_id']
                else:
                    sign = "+"
                    other = tx['from_id']
                
                date = tx['date'][:16] if isinstance(tx['date'], str) else str(tx['date'])[:16]
                amount = abs(tx['amount'])
                text += f"• {sign}{amount} {COM_EMOJI} ({date})\n"
        else:
            text += t(lang, "profile_no_transactions")
        
        _edit(text)
    
    elif action == "stats":
        # Показываем детальную статистику
        stats = get_user_stats(target_id)
        game_stats = get_game_stats(target_id)
        
        text = t(lang, "profile_stats_title")
        text += t(lang, "profile_economy")
        text += f"• {t(lang, 'profile_earned')}: {format_number(stats['total_earned'])} {COM_EMOJI}\n"
        text += f"• {t(lang, 'profile_spent')}: {format_number(stats['total_spent'])} {COM_EMOJI}\n"
        text += f"• {t(lang, 'profile_efficiency')}: {(stats['total_earned'] / max(1, stats['total_spent'])):.2f}\n\n"
        
        text += t(lang, "profile_games")
        if game_stats.get("games"):
            for game in game_stats["games"]:
                win_rate = (game["won"] / game["played"] * 100) if game["played"] > 0 else 0
                text += f"• {game['game']}: {game['played']} — {win_rate:.1f}%\n"
        else:
            text += t(lang, "profile_no_games")
        
        _edit(text)
    
    elif action == "achievements":
        # Показываем достижения
        user_achs = get_user_achievements(target_id)
        
        text = t(lang, "profile_achievements_title")
        if user_achs:
            for ach in user_achs[:10]:
                text += f"• {ach.get('icon', '🏆')} **{ach['name']}**\n"
                text += f"  {ach['desc']}\n"
                if ach.get('earned_date'):
                    date_str = ach['earned_date'][:10] if isinstance(ach['earned_date'], str) else str(ach['earned_date'])[:10]
                    text += f"  🗓️ {date_str}\n\n"
        else:
            text += t(lang, "profile_no_achievements")
        
        _edit(text)
    
    elif action == "history":
        # Показываем историю активности
        history = get_user_history(target_id, limit=10)
        _action_labels = {
            "message": "profile_activity_message",
            "command": "profile_activity_command",
            "game": "profile_activity_game",
            "transaction": "profile_activity_transaction",
            "daily": "profile_activity_daily",
        }
        text = t(lang, "profile_history_title")
        if history:
            for item in history:
                key = _action_labels.get(item['action'])
                action_name = t(lang, key) if key else t(lang, "profile_activity_other")
                if action_name == key:
                    action_name = t(lang, "profile_activity_other")
                date = item['date'][:16] if isinstance(item['date'], str) else str(item['date'])[:16]
                text += f"• {action_name} - {date}\n"
                if item.get('details'):
                    text += f"  {item['details']}\n"
        else:
            text += t(lang, "profile_no_history")
        
        _edit(text)
    
    elif action == "referrals":
        if viewer_id != target_id:
            bot.answer_callback_query(call.id, "❌ " + t(lang, "profile_only_self"), show_alert=True)
            return
        refs = get_referrals_list(target_id)
        total_earned = get_referral_earnings(target_id)
        text = f"**{t(lang, 'my_referrals_title')}**\n\n{t(lang, 'profile_referrals_invited')}: **{len(refs)}**\n{t(lang, 'profile_referrals_earned')}: **{total_earned}** {COM_EMOJI}\n\n"
        for i, r in enumerate(refs[:15], 1):
            mention = get_user_mention(r["user_id"]) or f"ID{r['user_id']}"
            text += f"{i}. {mention} — {r['balance']} {COM_EMOJI}\n"
        if len(refs) > 15:
            text += f"... +{len(refs) - 15}\n"
        _edit(text)
    
    elif action == "commission":
        if viewer_id != target_id:
            bot.answer_callback_query(call.id, "❌ " + t(lang, "profile_only_self"), show_alert=True)
            return
        total = get_referral_earnings(target_id)
        percent = REFERRAL_COMMISSION_PERCENT
        text = f"**{t(lang, 'my_commissions_title')}**\n\n{t(lang, 'profile_commission_earned')}: **{total}** {COM_EMOJI}\n{t(lang, 'profile_commission_rate')}: {percent}%"
        _edit(text)

    elif action == "relations":
        if viewer_id != target_id:
            bot.answer_callback_query(call.id, "❌ " + t(lang, "profile_only_self"), show_alert=True)
            return
        chat_id_for_rel = call.message.chat.id
        if getattr(call.message.chat, "type", "") in ("group", "supergroup"):
            rels = _get_relationships_list(chat_id_for_rel, target_id)
            if not rels:
                text = t(lang, "rel_single")
            else:
                text = t(lang, "rel_status_header") + "\n\n"
                for rel in rels:
                    partner_id = rel["partner_id"]
                    level = rel.get("level", 0)
                    exp = rel.get("experience", 0)
                    level_name = relationship_level_name(level, lang) if level > 0 else "—"
                    level_short = t(lang, "rel_level_short", level=level)
                    text += "• " + (get_user_mention(partner_id) or f"ID{partner_id}") + f" — {level_name} ({level_short}), {exp:,} XP\n"
        else:
            text = "💕 " + t(lang, "profile_relations_use_in_group")
        _edit(text)

    elif action == "marriage":
        if viewer_id != target_id:
            bot.answer_callback_query(call.id, "❌ " + t(lang, "profile_only_self"), show_alert=True)
            return
        chat_id_for_mar = call.message.chat.id
        if getattr(call.message.chat, "type", "") in ("group", "supergroup"):
            marriage = _get_marriage(chat_id_for_mar, target_id)
            if not marriage:
                text = t(lang, "marry_not_in_chat")
            else:
                partner_mention = get_user_mention(marriage["partner_id"]) or f"ID{marriage['partner_id']}"
                text = t(lang, "marry_married_with") + f"{partner_mention}\n" + t(lang, "marry_since") + f"{_format_db_timestamp_as_date(marriage.get('created_at'))}"
        else:
            text = "💍 " + t(lang, "profile_marriage_use_in_group")
        _edit(text)
    
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton(t(lang, "profile_back_btn"), callback_data=f"profile_back_{target_id}"))
    bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=markup)
    
    bot.answer_callback_query(call.id)

def create_profile_image_legacy(data: Dict[str, Any], message: Message, watermark: Dict[str, Any]) -> bytes:
    """
    Legacy-версия генератора профиля (оставлена для совместимости).
    """
    from PIL import Image, ImageDraw, ImageFont
    import io
    
    # Создаём изображение
    img = Image.new('RGB', (1200, 800), color=(18, 20, 25))
    draw = ImageDraw.Draw(img)
    
    # Загружаем шрифты
    try:
        font_title = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 48)
        font_normal = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 28)
        font_stats = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 22)
        font_small = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 16)
    except Exception:
        font_title = ImageFont.load_default()
        font_normal = ImageFont.load_default()
        font_stats = ImageFont.load_default()
        font_small = ImageFont.load_default()
    
    # Градиентный фон
    for y in range(800):
        color = (int(18 + y * 0.03), int(20 + y * 0.03), int(25 + y * 0.03))
        draw.line([(0, y), (1200, y)], fill=color)
    
    # Верхняя плашка
    draw.rectangle([0, 0, 1200, 100], fill=(35, 40, 55))
    
    # ===== ЛОГОТИП В КРУЖОЧКЕ (вместо эмодзи) =====
    try:
        # Пробуем загрузить логотип из файла
        logo_path = "/Users/owner/Desktop/telegram_invite_bot/logo.png"  # Укажи путь к твоему логотипу
        if os.path.exists(logo_path):
            logo = Image.open(logo_path).convert('RGBA')
            # Изменяем размер под кружок (80x80)
            logo = logo.resize((80, 80))
            
            # Создаем маску для круга
            mask = Image.new('L', (80, 80), 0)
            mask_draw = ImageDraw.Draw(mask)
            mask_draw.ellipse((0, 0, 80, 80), fill=255)
            
            # Вставляем логотип с маской
            img.paste(logo, (40, 10), mask)
        else:
            # Если логотипа нет, рисуем красивый градиентный круг
            draw.ellipse([40, 10, 120, 90], fill=(45, 50, 65))
            
            # Градиент внутри круга
            for i in range(40, 121, 2):
                color = (45 + i//10, 50 + i//10, 65 + i//10)
                draw.ellipse([i-2, (i-2)//2 + 10, i+2, (i+2)//2 + 10], fill=color)
            
            # Инициалы пользователя в круге
            initials = data['user'][0].upper() if data['user'] else '?'
            draw.text((80, 50), initials, fill=(255, 215, 0), font=font_normal, anchor="mm")
    except Exception as e:
        # Если ошибка, рисуем простой круг
        draw.ellipse([40, 10, 120, 90], fill=(45, 50, 65), outline=(100, 150, 255), width=3)
        draw.text((80, 50), "👤", fill=(255, 255, 255), font=font_normal, anchor="mm")
    # ===== КОНЕЦ ЛОГОТИПА =====
    
    # Имя пользователя
    draw.text((150, 35), data['user'], fill=(255, 255, 255), font=font_title)
    draw.text((150, 75), data['username'], fill=(150, 150, 150), font=font_small)
    
    # Ранг (сдвинут левее, чтобы не прилипал к правому краю)
    draw.text((900, 50), data['rank'], fill=(255, 215, 0), font=font_normal, anchor="mm")
    
    # ===== УБИРАЕМ КВАДРАТИКИ, ДЕЛАЕМ КРАСИВЫЕ КАРТОЧКИ =====
    stats_blocks = [
        {'x': 150, 'value': data['balance'], 'label': 'Баланс', 'color': (255, 215, 0), 'icon': '💰'},
        {'x': 400, 'value': data['games_played'], 'label': 'Игр', 'color': (100, 200, 255), 'icon': '🎮'},
        {'x': 650, 'value': data['achievements'], 'label': 'Достижения', 'color': (100, 255, 100), 'icon': '🏆'},
        {'x': 900, 'value': f"{data['win_rate']:.1f}%", 'label': 'Побед', 'color': (255, 100, 100), 'icon': '⚡'}
    ]
    
    for block in stats_blocks:
        # Красивая карточка с закругленными углами
        card_x1 = block['x'] - 30
        card_y1 = 110
        card_x2 = block['x'] + 190
        card_y2 = 190
        
        # Тень
        draw.rectangle([card_x1+2, card_y1+2, card_x2+2, card_y2+2], fill=(10, 10, 15))
        
        # Основная карточка с градиентом
        for i in range(card_y1, card_y2):
            gradient = int(30 + (i - card_y1) * 0.3)
            draw.line([(card_x1, i), (card_x2, i)], fill=(gradient, gradient+5, gradient+10))
        
        # Рамка
        draw.rectangle([card_x1, card_y1, card_x2, card_y2], outline=block['color'], width=2)
        
        # Иконка
        draw.text((card_x1 + 15, card_y1 + 10), block['icon'], fill=block['color'], font=font_normal)
        
        # Значение
        draw.text((card_x1 + 110, card_y1 + 30), str(block['value']), fill=block['color'], font=font_normal, anchor="mm")
        
        # Подпись
        draw.text((card_x1 + 110, card_y2 - 15), block['label'], fill=(150, 150, 150), font=font_small, anchor="mm")
    
    # График активности
    draw.text((50, 220), "📈 Активность за неделю", fill=(200, 200, 200), font=font_normal)
    
    activity_data = get_user_activity(data['user_id'])
    
    grid_x_start, grid_x_end = 100, 700
    grid_y_start, grid_y_end = 280, 480
    
    # Красивая сетка
    for i in range(8):
        x = grid_x_start + (grid_x_end - grid_x_start) * i // 7
        draw.line([(x, grid_y_start), (x, grid_y_end)], fill=(40, 45, 55), width=1)
    
    for i in range(5):
        y = grid_y_start + (grid_y_end - grid_y_start) * i // 4
        draw.line([(grid_x_start, y), (grid_x_end, y)], fill=(40, 45, 55), width=1)
    
    # Рамка с закругленными углами
    draw.rectangle([grid_x_start, grid_y_start, grid_x_end, grid_y_end], outline=(70, 130, 200), width=2)
    
    # Столбцы с градиентом
    max_value = max(activity_data['values']) if max(activity_data['values']) > 0 else 1
    bar_width = (grid_x_end - grid_x_start - 20) // 7
    
    for i, value in enumerate(activity_data['values']):
        bar_height = (value / max_value) * (grid_y_end - grid_y_start - 30)
        bar_x = grid_x_start + 10 + i * bar_width
        bar_y = grid_y_end - 20 - bar_height
        
        # Градиентный столбец
        for h in range(int(bar_height)):
            color_intensity = 70 + int((h / bar_height) * 100)
            draw.line([(bar_x, bar_y + h), (bar_x + bar_width - 5, bar_y + h)], 
                     fill=(color_intensity, 130 + h//2, 200))
        
        # Дни недели
        day_names = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс']
        draw.text((bar_x + bar_width//2, grid_y_end + 5), day_names[i], fill=(150, 150, 150), font=font_small, anchor="ma")
    
    # Игровая статистика (тоже убираем квадратики)
    draw.text((800, 220), "🎮 Игровая статистика", fill=(200, 200, 200), font=font_normal)
    
    game_stats = [
        ('🎲 Рулетка', data['roulette_games'], data['roulette_wins']),
        ('🎯 Кости', data['dice_games'], data['dice_wins']),
        ('⚔️ Дуэли', data['duel_games'], data['duel_wins'])
    ]
    
    y_pos = 280
    for game, total, wins in game_stats:
        # Карточка игры
        card_y1 = y_pos
        card_y2 = y_pos + 50
        
        # Тень
        draw.rectangle([802, card_y1+2, 1152, card_y2+2], fill=(10, 10, 15))
        
        # Основная карточка
        draw.rectangle([800, card_y1, 1150, card_y2], fill=(30, 35, 45), outline=(50, 55, 65), width=1)
        
        # Игра с иконкой
        draw.text((820, card_y1 + 15), game, fill=(200, 200, 200), font=font_stats)
        
        win_rate = (wins / total * 100) if total > 0 else 0
        
        # Статистика
        if total > 0:
            draw.text((1070, card_y1 + 15), f"{wins}/{total}", 
                     fill=(100, 255, 100) if win_rate > 50 else (255, 100, 100), 
                     font=font_stats, anchor="ra")
            draw.text((1130, card_y1 + 15), f"({win_rate:.0f}%)", 
                     fill=(150, 150, 150), font=font_small)
        else:
            draw.text((1100, card_y1 + 15), "нет игр", fill=(150, 150, 150), font=font_small, anchor="mm")
        
        y_pos += 60
    
    # Достижения
    draw.text((50, 520), "🏆 Последние достижения", fill=(200, 200, 200), font=font_normal)
    
    y_pos = 570
    for ach in data['achievements_list']:
        # Карточка достижения
        draw.rectangle([52, y_pos+2, 552, y_pos+42], fill=(10, 10, 15))
        draw.rectangle([50, y_pos, 550, y_pos+40], fill=(30, 35, 45), outline=(70, 130, 200), width=1)
        
        # Иконка
        draw.text((70, y_pos+10), ach.get('icon', '🏆'), fill=(255, 215, 0), font=font_normal)
        
        # Название
        draw.text((120, y_pos+10), ach.get('name', 'Достижение'), fill=(200, 200, 200), font=font_stats)
        
        y_pos += 45
    
    # Streak
    draw.text((650, 520), "🔥 Streak", fill=(200, 200, 200), font=font_normal)
    
    streak_value = data['streak']
    if streak_value >= 30:
        streak_color = (255, 215, 0)
    elif streak_value >= 7:
        streak_color = (100, 255, 100)
    else:
        streak_color = (255, 100, 100)
    
    # Карточка streak
    draw.rectangle([652, 572, 902, 632], fill=(10, 10, 15))
    draw.rectangle([650, 570, 900, 630], fill=(30, 35, 45), outline=streak_color, width=2)
    draw.text((775, 600), f"{streak_value} дней", fill=streak_color, font=font_title, anchor="mm")
    
    # Прогресс-бар
    progress = min(streak_value / 30, 1.0)
    draw.rectangle([650, 640, 900, 660], fill=(40, 45, 55))
    draw.rectangle([650, 640, 650 + int(250 * progress), 660], fill=streak_color)
    draw.text((775, 670), f"Цель: 30 дней", fill=(150, 150, 150), font=font_small, anchor="mm")
    
    # Водяной знак
    if watermark.get('enabled', False):
        try:
            file_id = watermark.get('file_id')
            if file_id:
                file_info = bot.get_file(file_id)
                downloaded_file = bot.download_file(file_info.file_path)
                watermark_img = Image.open(io.BytesIO(downloaded_file)).convert('RGBA')
                
                watermark_size = watermark.get('size', 100)
                watermark_img = watermark_img.resize((watermark_size, watermark_size))
                
                opacity = int(watermark.get('opacity', 0.3) * 255)
                watermark_img.putalpha(opacity)
                
                positions = {
                    'bottom_right': (img.width - watermark_img.width - 20, img.height - watermark_img.height - 20),
                    'bottom_left': (20, img.height - watermark_img.height - 20),
                    'top_right': (img.width - watermark_img.width - 20, 20),
                    'top_left': (20, 20),
                    'center': ((img.width - watermark_img.width) // 2, (img.height - watermark_img.height) // 2)
                }
                pos = positions.get(watermark.get('position', 'bottom_right'))
                img.paste(watermark_img, pos, watermark_img)
        except Exception as e:
            logger.warning("Ошибка водяного знака: %s", e)
    
    # Сохраняем
    img_bytes = io.BytesIO()
    img.save(img_bytes, format='PNG')
    img_bytes.seek(0)
    return img_bytes.getvalue()

@bot.callback_query_handler(func=lambda call: call.data == "profile_close")
@safe_handler
def profile_close_callback(call: CallbackQuery):
    """Закрытие карточки профиля в группе: удаление сообщения."""
    try:
        bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    lang = get_user_language(call.from_user.id) if getattr(call, "from_user", None) else "ru"
    bot.answer_callback_query(call.id, t(lang, "profile_closed"))


@bot.callback_query_handler(func=lambda call: call.data.startswith('profile_back_'))
def profile_back_callback(call: CallbackQuery):
    """Возврат в основной профиль."""
    if not ensure_call_access(call):
        bot.answer_callback_query(call.id)
        return
    if not getattr(call, 'from_user', None):
        return
    parts = call.data.split('_')
    if len(parts) < 3 or not parts[2].strip():
        bot.answer_callback_query(call.id, "❌ Неверный формат", show_alert=True)
        return
    try:
        target_id = int(parts[2])
    except (ValueError, TypeError):
        bot.answer_callback_query(call.id, "❌ Ошибка данных", show_alert=True)
        return
    viewer_id = call.from_user.id
    chat_id = call.message.chat.id
    is_group = call.message.chat.type in ("group", "supergroup")

    if not _can_view_profile(viewer_id, target_id, chat_id):
        lang = get_user_language(viewer_id)
        bot.answer_callback_query(call.id, _truncate_preserving_emoji(t(lang, "not_for_you"), 200), show_alert=True)
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        return

    try:
        bot.delete_message(chat_id, call.message.message_id)
    except Exception:
        pass

    lang = get_user_language(viewer_id)
    send_profile_card(chat_id, target_id, viewer_id=viewer_id, lang=lang)
    bot.answer_callback_query(call.id)

def get_game_stats_detail(user_id: int) -> Dict[str, Dict[str, int]]:
    """Получает детальную статистику по каждой игре."""
    result = {}
    games = ['roulette', 'dice', 'duel']
    
    for game in games:
        data = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*), SUM(win) FROM games WHERE user_id=? AND game=?",
            (user_id, game)
        )
        if data and data[0]:
            played = data[0][0] or 0
            won = data[0][1] or 0
            result[game] = {'played': played, 'won': won}
    
    return result

def get_user_activity(user_id: int, days: int = 7) -> Dict[str, Any]:
    """
    Получает данные активности пользователя за последние N дней.
    """
    values = []
    days_list = []
    
    for i in range(days):
        date = (datetime.now() - timedelta(days=i)).strftime('%Y-%m-%d')
        days_list.append(date)
        
        result = execute_query(
            MESSAGE_STATS_DB,
            "SELECT COALESCE(SUM(count), 0) FROM message_counts WHERE user_id=? AND date=?",
            (user_id, date)
        )
        count = result[0][0] if result else 0
        values.append(count)
    
    return {
        'values': list(reversed(values)),
        'days': list(reversed(days_list))
    }

def create_profile_image(data: Dict[str, Any], message: Message, watermark: Dict[str, Any]) -> bytes:
    """
    Создаёт изображение профиля с графиками активности.
    """
    from PIL import Image, ImageDraw, ImageFont
    import io
    
    # Создаём изображение
    img = Image.new('RGB', (1200, 800), color=(18, 20, 25))
    draw = ImageDraw.Draw(img)
    
    # Загружаем шрифты
    try:
        font_title = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 48)
        font_normal = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 28)
        font_stats = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 22)
        font_small = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 16)
    except Exception:
        font_title = ImageFont.load_default()
        font_normal = ImageFont.load_default()
        font_stats = ImageFont.load_default()
        font_small = ImageFont.load_default()
    
    # Градиентный фон
    for y in range(800):
        color = (int(18 + y * 0.03), int(20 + y * 0.03), int(25 + y * 0.03))
        draw.line([(0, y), (1200, y)], fill=color)
    
    # Верхняя плашка
    draw.rectangle([0, 0, 1200, 100], fill=(35, 40, 55))
    
