@bot.message_handler(commands=['chatstats', 'cstats'])
@safe_handler
def cmd_chatstats(message: Message):
    """
    Команда для просмотра статистики чата: превью-график + краткий текст.
    Использование: /chatstats
    """
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id

    try:
        chat = bot.get_chat(chat_id)
        members_count = bot.get_chat_members_count(chat_id)
        active_users = get_distinct_active_users(chat_id, days=7)
        period_days = normalize_stats_periods(STATS_PERIOD_DAYS)
        period_counts: List[Tuple[int, int]] = [
            (d, get_message_count_for_days(chat_id, d)) for d in period_days
        ]
        messages_today = next((c for d, c in period_counts if d == 1), 0)
        messages_week = get_message_count_for_days(chat_id, 7)
        avg_per_day = messages_week // 7 if messages_week else 0

        games_today_row = execute_query(
            ECONOMY_DB,
            "SELECT COUNT(*) FROM games WHERE date(date) = date('now')"
        )
        games_today = int(games_today_row[0][0]) if games_today_row and games_today_row[0] else 0
        economy_stats = get_economy_stats()
        total_games = economy_stats.get("total_games", 0)
        total_wins = economy_stats.get("total_wins", 0)
        total_coins = economy_stats.get("total_coins", 0)
        avg_balance = economy_stats.get("avg_balance", 0)
        max_balance = economy_stats.get("max_balance", 0)

        _notified_count = _count_notified_users()
        new_week = (members_count - _notified_count) if chat_id == CHAT_ID else None

        # Превью-график: активность по периодам
        preview_rows: List[Tuple[str, int]] = [
            ("сегодня" if d == 1 else f"{d} дн.", int(c)) for d, c in period_counts
        ]
        preview = None
        if preview_rows:
            try:
                preview = create_stats_preview_image(
                    "Статистика чата",
                    preview_rows,
                    "Активность по периодам",
                    allow_emoji=True,
                )
            except Exception as e:
                logger.debug("Создание превью chatstats: %s", e)

        # Короткая подпись (до 1024 символов)
        parts = []
        parts.append("👥 <b>Участники</b>")
        new_line = f" • Всего: {members_count} | За 7 дн.: {active_users}"
        if new_week is not None:
            new_line += f" | Новых: {new_week}"
        parts.append(new_line)
        parts.append("")
        parts.append("💬 <b>Активность</b>")
        parts.append(f" • Сегодня: {messages_today} | За неделю: {format_number(messages_week)} | В ср.: {avg_per_day}/день")
        parts.append("")
        parts.append("🎮 <b>Игры</b>")
        parts.append(f" • Сегодня: {games_today} | Всего: {format_number(total_games)}")
        parts.append("")
        parts.append("💰 <b>Экономика</b>")
        parts.append(f" • В обороте: {format_number(total_coins)} {COM_EMOJI} | Ср. баланс: {format_number(avg_balance)} {COM_EMOJI} | Богач: {format_number(max_balance)} {COM_EMOJI}")
        # Донаты и место в рейтинге групп
        donations_ensure_group(chat_id, getattr(chat, "title", None) or "", None, members_count)
        group_don = get_group_donation_stats(chat_id)
        if group_don and group_don.get("group"):
            g = group_don["group"]
            total_don = g.get("total_donations") or 0
            pos = g.get("rating_position") or 0
            pos_str = str(pos) if pos else "—"
            parts.append("")
            parts.append("💸 <b>Донаты</b>")
            parts.append(f" • Всего донатов: {format_number(total_don)} {COM_EMOJI} | Место в рейтинге: {pos_str}")
        top_rows = _get_top_message_rows(chat_id, 7, limit=3)
        if top_rows:
            parts.append("")
            parts.append("💬 <b>Топ-3 по сообщениям</b> (за 7 дн.)")
            for i, (uid, name, count) in enumerate(top_rows, 1):
                name_esc = (name or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                parts.append(f' {i}. <a href="tg://user?id={uid}">{name_esc}</a> — {format_number(count)} сообщ.')
        caption = "\n".join(parts)
        if len(caption) > 1000:
            caption = _truncate_preserving_emoji(caption, 997) + "…"

        chatstats_lang = get_user_language(message.from_user.id)
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton("💸 " + t(chatstats_lang, "donate_menu_title"), callback_data=f"donate_menu_{chat_id}"))
        markup.add(InlineKeyboardButton(t(chatstats_lang, "btn_rating_groups"), callback_data="rating"))

        if preview:
            doc = io.BytesIO(preview)
            msg = bot.send_photo(chat_id, doc, caption=caption, parse_mode="HTML", reply_markup=markup)
            if AUTO_DELETE_GAMES and msg and getattr(msg, "message_id", None):
                schedule_deletion(chat_id, msg.message_id, 120)
        else:
            msg = bot.send_message(chat_id, caption, parse_mode="HTML", reply_markup=markup)
            if AUTO_DELETE_GAMES and msg and getattr(msg, "message_id", None):
                schedule_deletion(chat_id, msg.message_id, 120)

        if AUTO_DELETE_GAMES:
            schedule_deletion(chat_id, message.message_id, 120)
    except Exception as e:
        logger.error("Ошибка получения статистики чата: %s", e)
        bot.reply_to(message, "❌ Ошибка получения статистики")


@bot.message_handler(commands=['stats'])
@safe_handler
def cmd_user_stats(message: Message):
    """
    Статистика пользователя по сообщениям.
    Использование:
    - /stats (своя статистика)
    - /stats ответом на сообщение (статистика другого пользователя)
    """
    if not ensure_user_access(message):
        return
    chat_id = message.chat.id
    lang = get_user_language(message.from_user.id)
    target_user = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    target_id = target_user.id
    target_name = target_user.first_name or f"ID {target_id}"
    if getattr(target_user, "is_bot", False) or is_excluded_bot_user(target_id):
        bot.reply_to(message, "🤖 Боты не участвуют в пользовательской статистике.")
        return

    stats = get_user_message_stats(target_id, chat_id)
    period_days = normalize_stats_periods(STATS_PERIOD_DAYS)
    period_rows = [(d, get_message_count_for_days(chat_id, d, user_id=target_id)) for d in period_days]
    by_days = execute_query(
        MESSAGE_STATS_DB,
        """SELECT date, count
           FROM message_counts
           WHERE user_id = ? AND chat_id = ? AND date >= date('now', '-6 days')
           ORDER BY date DESC""",
        (target_id, chat_id),
    ) or []

    rows: List[Tuple[str, int]] = []
    for row in by_days:
        date_str = str(row[0])[5:]  # MM-DD
        rows.append((date_str, int(row[1] or 0)))

    if (lang or "").strip().lower() == "en":
        day_table_lines = ["Last 7 days", "№  Date        Messages", "-- ---------- ---------"]
        if not rows:
            day_table_lines.append(".. no data")
        else:
            for i, (name, count) in enumerate(rows, 1):
                day_table_lines.append(f"{i:>2} {name[:18]:<12} {count:>9}")
        day_table = "```text\n" + "\n".join(day_table_lines) + "\n```"
    else:
        day_table = _format_top_table("Последние 7 дней", rows)
    total_stats = stats.get("total", 0)
    if (lang or "").strip().lower() == "en":
        period_text = "\n".join(
            [
                f"• {'Today' if d == 1 else f'{d} day(s)'}: `{v}`"
                for d, v in period_rows
            ]
        )
    else:
        period_text = "\n".join(
            [f"• За {'сегодня' if d == 1 else f'{d} дн.'}: `{v}`" for d, v in period_rows]
        )
    # Одно сообщение: PNG (document, без сжатия) + подпись
    try:
        if (lang or "").strip().lower() == "en":
            preview_rows = [
                ("Today" if d == 1 else f"{d} day(s)", int(v) if v is not None else 0)
                for d, v in period_rows
            ]
        else:
            preview_rows = [
                ("сегодня" if d == 1 else f"{d} дн.", int(v) if v is not None else 0)
                for d, v in period_rows
            ]
        preview_total_label = "Total" if (lang or "").strip().lower() == "en" else "всего"
        preview_rows.append((preview_total_label, int(total_stats)))
        preview = create_stats_preview_image(
            (f"Statistics: {target_name}" if (lang or "").strip().lower() == "en" else f"Статистика: {target_name}"),
            preview_rows,
            ("Messages by periods" if (lang or "").strip().lower() == "en" else "Сообщения за периоды"),
            allow_emoji=True,
        )
        # Короткая подпись (HTML — эмодзи в превью отображаются корректно)
        p_map = {int(d): int(v or 0) for d, v in period_rows}
        name_esc = _escape_html_caption(target_name)
        if (lang or "").strip().lower() == "en":
            caption = (
                f"📈 <b>Message statistics: {name_esc}</b>\n"
                f"• Today: <code>{p_map.get(1, 0)}</code>\n"
                f"• 7 day(s): <code>{p_map.get(7, 0)}</code>\n"
                f"• 30 day(s): <code>{p_map.get(30, 0)}</code>\n"
                f"• Total: <code>{total_stats}</code>"
            )
        else:
            caption = (
                f"📈 <b>Статистика сообщений: {name_esc}</b>\n"
                f"• Сегодня: <code>{p_map.get(1, 0)}</code>\n"
                f"• 7 дн.: <code>{p_map.get(7, 0)}</code>\n"
                f"• 30 дн.: <code>{p_map.get(30, 0)}</code>\n"
                f"• Всего: <code>{total_stats}</code>"
            )
        _send_png_as_document(chat_id, preview, "user_stats.png", caption, parse_mode="HTML")
    except Exception as e:
        logger.exception("Ошибка создания PNG статистики пользователя (fallback на текст): %s", e)
        # fallback
        if (lang or "").strip().lower() == "en":
            text = (
                f"📈 **Message statistics: {_escape_markdown_caption(target_name)}**\n\n"
                f"{period_text}\n"
                f"• For all time: `{total_stats}`\n\n"
                f"{day_table}"
            )
        else:
            text = (
                f"📈 **Статистика сообщений: {_escape_markdown_caption(target_name)}**\n\n"
                f"{period_text}\n"
                f"• За всё время: `{total_stats}`\n\n"
                f"{day_table}"
            )
        bot.reply_to(message, text, parse_mode="Markdown")


@bot.message_handler(commands=["chatpreview"])
@safe_handler
def cmd_chatpreview(message: Message):
    """
    Превью со статистикой активности чата по дням (последние N дней).
    Работает только в группах.
    """
    if not ensure_user_access(message):
        return
    if message.chat.type not in ("group", "supergroup"):
        lang = get_user_language(message.from_user.id)
        bot.reply_to(message, t(lang, "only_in_group"))
        return
    chat_id = message.chat.id
    N_DAYS = 7
    today = date.today()
    date_labels_ru = ["сегодня", "вчера", "позавчера"]
    preview_rows: List[Tuple[str, int]] = []
    for i in range(N_DAYS):
        d = today - timedelta(days=i)
        date_str = d.strftime("%Y-%m-%d")
        count = get_chat_message_count_for_date(chat_id, date_str)
        if i < len(date_labels_ru):
            label = date_labels_ru[i]
        else:
            label = d.strftime("%d.%m")
        preview_rows.append((label, count))
    try:
        preview = create_stats_preview_image(
            "Статистика чата",
            preview_rows,
            "Активность по дням",
            allow_emoji=True,
        )
        total = sum(v for _, v in preview_rows)
        caption = (
            "📊 <b>Статистика чата</b>\n"
            + "\n".join(f"• {label}: <code>{val}</code>" for label, val in preview_rows)
            + f"\n\n• Всего за {N_DAYS} дн.: <code>{total}</code>"
        )
        doc = io.BytesIO(preview)
        bot.send_photo(chat_id, doc, caption=caption, parse_mode="HTML")
    except Exception as e:
        logger.exception("Ошибка создания превью чата: %s", e)
        bot.reply_to(message, "❌ Ошибка построения графика.")


