def _parse_stata_period(rest: str) -> Optional[Tuple[int, str]]:
    """Парсит период для .стата: день/неделя/месяц/год или число. Возвращает (дней, подпись) или None."""
    if not rest or not rest.strip():
        return None
    word = rest.strip().lower().split()[0]
    period_map = {
        "день": (1, "день"), "дня": (1, "день"), "дней": (1, "день"),
        "неделя": (7, "неделю"), "недели": (7, "неделю"), "недель": (7, "неделю"),
        "месяц": (30, "месяц"), "месяца": (30, "месяц"), "месяцев": (30, "месяц"),
        "год": (365, "год"), "года": (365, "год"), "лет": (365, "год"),
    }
    if word in period_map:
        return period_map[word]
    try:
        n = int(word)
        if 1 <= n <= 365:
            return (n, f"{n} дн." if n != 1 else "день")
    except ValueError:
        pass
    return None


def cmd_stata_period(message: Message, days: int, period_label: str) -> None:
    """
    Локальная статистика по сообщениям в этом чате за период (день/неделя/месяц/год/кастом).
    Все данные привязаны к группе, где вызвана команда (message.chat.id).
    """
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id  # только эта группа — локальная стата
    total = get_message_count_for_days(chat_id, days)
    active = get_distinct_active_users(chat_id, days)
    rows = _get_top_message_rows(chat_id, days, limit=None)
    if not rows and total == 0:
        bot.reply_to(message, f"📭 Нет данных по сообщениям в этом чате за {period_label}.")
        return
    parts = [
        f"📊 **Статистика чата** за {period_label}\n",
        f"💬 Сообщений в этом чате: **{format_number(total)}**",
        f"👥 Участников писали: **{active}**\n",
    ]
    if rows:
        parts.append("**Участники по сообщениям:**")
        for i, (uid, name, count) in enumerate(rows, 1):
            medal = {1: "🥇", 2: "🥈", 3: "🥉"}.get(i, f"{i}.")
            # Ник задаётся самим участником через /nick, а таблица уходит
            # с parse_mode="Markdown". Ручной набор ниже экранировал только
            # \ [ ] — одна звёздочка или подчёркивание в чужом нике ломала
            # разбор ВСЕЙ таблицы, и статистику не видел никто в чате.
            safe_name = _escape_markdown_caption(name or "")
            name_link = f"[{safe_name}](tg://user?id={uid})"
            parts.append(f"{medal} {name_link} — {format_number(count)}")
    text = "\n".join(parts)
    bot.reply_to(message, text, parse_mode="Markdown")


@bot.message_handler(commands=['ping', 'kom_ping'])
@safe_handler
def cmd_ping(message: Message):
    """
    Проверка скорости ответа бота и Telegram API.
    """
    if not ensure_user_access(message):
        return
    started = time.perf_counter()
    update_lag_ms = max(0, int((time.time() - int(message.date)) * 1000)) if getattr(message, "date", None) else 0

    api_ms = None
    try:
        t0 = time.perf_counter()
        bot.get_me()
        api_ms = int((time.perf_counter() - t0) * 1000)
    except Exception:
        pass

    process_ms = int((time.perf_counter() - started) * 1000)
    api_text = f"`{api_ms} ms`" if api_ms is not None else "`н/д`"

    bot.reply_to(
        message,
        "🏓 **Понг!**\n\n"
        f"• Доставка апдейта: `{update_lag_ms} ms`\n"
        f"• RTT к Telegram API: {api_text}\n"
        f"• Обработка команды: `{process_ms} ms`",
        parse_mode="Markdown",
    )


