def _diagnostic_version_check() -> List[str]:
    """Проверяет, какие «версии» кода активны (превью статистики, город из профиля, погода, помощь с кнопкой)."""
    results = []
    try:
        # Статистика /stats — превью (create_stats_preview_image + _send_png_as_document) или текст
        src = inspect.getsource(cmd_user_stats)
        if "_send_png_as_document" in src and "create_stats_preview_image" in src:
            results.append("✅ Статистика (/stats): версия с превью (PNG)")
        elif "send_message" in src or "reply_to" in src:
            results.append("⚠️ Статистика (/stats): текстовая версия (без превью)")
        else:
            results.append("❓ Статистика (/stats): неизвестная версия")

        # Время — использование get_user_city
        src = inspect.getsource(cmd_time)
        if "get_user_city" in src and "get_user_timezone" in src:
            results.append("✅ Время (/time): с городом из профиля и часовым поясом")
        else:
            results.append("⚠️ Время (/time): без определения города из /city")

        # Погода — Open-Meteo / maybe_send_weather_reply
        src = inspect.getsource(cmd_weather)
        if "maybe_send_weather_reply" in src:
            results.append("✅ Погода (/weather): через maybe_send_weather_reply")
        else:
            results.append("⚠️ Погода (/weather): другая реализация")

        # Помощь — кнопка гайда на сайте и build_participant_help_text
        src = inspect.getsource(cmd_help)
        if "telegraph_url" in src and "InlineKeyboardButton" in src:
            results.append("✅ Помощь (/help): с кнопкой гайда на сайте и меню")
        elif "build_participant_help_text" in src:
            results.append("✅ Помощь (/help): build_participant_help_text (список команд)")
        else:
            results.append("❓ Помощь (/help): неизвестная версия")
    except Exception as e:
        results.append(f"❌ Ошибка проверки: {e}")
    return results


@bot.message_handler(commands=['debug'])
@safe_handler
def cmd_debug(message: Message):
    """Диагностика: версии кода, город, погода, URL гайда (только владелец)."""
