@bot.message_handler(commands=['staff_me'])
@safe_handler
def cmd_staff_me(message: Message):
    """
    Выдаёт базовый ранг модератора Telegram-админу через ЛС.

    Сценарий: админ с включённой анонкой (пишет от лица канала/чата) пишет боту в личку `/staff_me`,
    бот проверяет, что он числится админом основной группы и выдаёт ему ранг MODERATOR, если его ещё нет.
    """
    # Работает только в личке, чтобы не светить внутренние ID и статусы
    if message.chat.type != "private":
        bot.reply_to(message, "🔒 Команду `/staff_me` используй в личных сообщениях с ботом.", parse_mode="Markdown")
        return

    user_id = message.from_user.id
    # Владелец и так имеет максимальный ранг
    if user_id in DEVELOPER_IDS:
        bot.reply_to(message, "👑 У тебя уже максимальные права владельца.")
        return

    # Проверяем, является ли пользователь Telegram-админом в основном чате
    try:
        member = bot.get_chat_member(CHAT_ID, user_id)
        status = getattr(member, "status", "")
    except Exception:
        status = ""

    if status not in {"creator", "administrator"}:
        bot.reply_to(
            message,
            "🚫 Команда доступна только администраторам основного чата.\n"
            "Сначала получи права админа через настройки Telegram-группы.",
        )
        return

    current_rank = get_user_rank(user_id)
    if current_rank >= RankLevel.JUNIOR_MOD.value:
        bot.reply_to(
            message,
            f"✅ У тебя уже есть staff-ранг: {get_rank_name(current_rank)}.",
        )
        return

    # Выдаём базовый модераторский ранг
    if set_user_rank(user_id, RankLevel.MODERATOR.value, admin_id=ADMIN_CHAT_ID):
        bot.reply_to(
            message,
            f"✅ Ты получил модераторский ранг: {get_rank_name(RankLevel.MODERATOR.value)}.\n"
            "Теперь все staff-функции бота будут доступны и для тебя.",
        )
    else:
        bot.reply_to(message, "❌ Не удалось выдать модераторский ранг. Попробуй позже или обратись к владельцу.")


@bot.message_reaction_handler()
@safe_handler
def handle_message_reaction(update):
    """
    Реагирует на реакции пользователей в основном чате, с учётом их роли.
    Сейчас бот отвечает только в личку пользователю, чтобы не засорять чат.
    """
    try:
        chat = getattr(update, "chat", None)
        if not chat or chat.id != CHAT_ID:
            return

        # Кто поставил/убрал реакцию
        actor = getattr(update, "user", None)
        if not actor:
            # Для анонимных реакций есть отдельный message_reaction_count, его здесь игнорируем
            return
        user_id = actor.id

        if is_excluded_bot_user(user_id) or user_id == bot.get_me().id:
            return

        # Список новых реакций (после изменения)
        new_reactions = getattr(update, "new_reaction", []) or []
        if not new_reactions:
            # Только сняли реакцию — можно ничего не делать
            return

        # Собираем человекочитаемую строку реакций
        emojis: List[str] = []
        for rt in new_reactions:
            emoji_val = getattr(rt, "emoji", None)
            if emoji_val:
                emojis.append(emoji_val)
        emoji_str = " ".join(emojis) if emojis else "реакция"

        rank = get_user_rank(user_id)
        rank_name = get_rank_name(rank)

        # Разный тон ответа в зависимости от роли.
        if rank >= RankLevel.ADMIN.value:
            reply_text = (
                f"👑 {rank_name}, увидел твою реакцию {emoji_str}.\n"
                "Спасибо за сигнал, учту это в статистике и поведении бота."
            )
        elif rank >= RankLevel.JUNIOR_MOD.value:
            reply_text = (
                f"🛡 {rank_name}, принял твою реакцию {emoji_str}.\n"
                "Модераторская активность тоже важна для поддержания атмосферы."
            )
        else:
            reply_text = (
                f"✨ Я вижу твою реакцию {emoji_str}.\n"
                f"Твой текущий статус: {rank_name}.\n"
                "Спасибо, что реагируешь — это помогает понимать, что заходит аудитории."
            )

        try:
            bot.send_message(user_id, reply_text)
        except Exception as e:
            logger.debug(f"Не удалось отправить личное сообщение по реакции пользователю {user_id}: {e}")
    except Exception as e:
        logger.error(f"Ошибка в handle_message_reaction: {e}")


def _lookup_user_id_by_username(uname: str) -> Optional[int]:
    """Ищет пользователя по username в users.db (человек должен когда-либо писать боту/в группе)."""
    uname = (uname or "").strip().lstrip("@").lower()
    if not uname:
        return None
    try:
        rows = execute_query(
            USERS_DB,
            """SELECT user_id
               FROM users
               WHERE lower(username) = ?
               ORDER BY last_seen DESC
               LIMIT 1""",
            (uname,),
        ) or []
        if rows and rows[0]:
            return int(rows[0][0])
    except Exception:
        pass
    return None


@bot.message_handler(commands=["transfer_rights"])
@safe_handler
def cmd_transfer_rights(message: Message):
    """
    Передаёт права владельца другому человеку (смена owner_user_id в settings.json).
    Только ЛС и только текущий владелец.

    Использование:
    - /transfer_rights ответом на сообщение
    - /transfer_rights @username
    - /transfer_rights 123456789
    """
    if message.chat.type != "private":
        bot.reply_to(message, "🔒 Передача прав доступна только в личных сообщениях с ботом.")
        return
    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Только владелец может передавать права.")
        return

    # Анти-абуз: кулдаун
    cd_key = f"transfer_rights_cd_{message.from_user.id}"
    if cache_get(cd_key):
        bot.reply_to(message, "⏳ Подожди немного перед следующей попыткой передачи прав.")
        return
    cache_set(cd_key, True, ttl=30)

    target_id: Optional[int] = None
    target_hint = ""

    if message.reply_to_message and message.reply_to_message.from_user:
        target_id = message.reply_to_message.from_user.id
        target_hint = message.reply_to_message.from_user.first_name or str(target_id)
    else:
        args = (message.text or "").split(maxsplit=1)
        if len(args) < 2:
            bot.reply_to(message, "❌ Укажи пользователя: ответом на сообщение или `/transfer_rights @username`.", parse_mode="Markdown")
            return
        token = args[1].strip()
        if token.isdigit():
            target_id = int(token)
            target_hint = token
        else:
            found = _lookup_user_id_by_username(token)
            if found:
                target_id = found
                target_hint = token

    if not target_id:
        bot.reply_to(message, "❌ Не смог найти пользователя. Он должен хотя бы раз написать боту/в группе (чтобы попал в базу).")
        return
    if target_id == message.from_user.id:
        bot.reply_to(message, "❌ Нельзя передать права самому себе.")
        return
    if is_excluded_bot_user(target_id):
        bot.reply_to(message, "❌ Нельзя передать права боту.")
        return
    if not is_user_in_chat(target_id):
        bot.reply_to(message, "❌ Этот пользователь сейчас не в основной группе — сначала пусть вступит.")
        return

    # Анти-абуз: подтверждение
    token = secrets.token_hex(6)
    key = f"transfer_rights_pending_{token}"
    cache_set(
        key,
        {"from_id": message.from_user.id, "to_id": target_id, "created": time.time()},
        ttl=5 * 60,
    )

    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton("✅ Подтвердить", callback_data=f"transfer_rights_confirm_{token}"),
        InlineKeyboardButton("❌ Отмена", callback_data=f"transfer_rights_cancel_{token}"),
    )
    bot.reply_to(
        message,
        "⚠️ **Передача прав владельца**\n\n"
        f"Ты собираешься передать права пользователю: `{target_id}` ({target_hint}).\n\n"
        "После подтверждения:\n"
        "- новый владелец получит доступ к админ-панели и настройкам\n"
        "- админ-уведомления будут приходить уже ему\n\n"
        "**Подтвердить?**",
        parse_mode="Markdown",
        reply_markup=markup,
    )


@bot.callback_query_handler(func=lambda call: call.data.startswith("transfer_rights_confirm_") or call.data.startswith("transfer_rights_cancel_"))
@safe_handler
def transfer_rights_callback(call: CallbackQuery):
    try:
        if not is_owner(call.from_user.id):
            bot.answer_callback_query(call.id, "🚫 Только владелец", show_alert=True)
            return

        parts = call.data.split("_")
        if len(parts) < 4:
            bot.answer_callback_query(call.id, "❌ Неверный формат", show_alert=True)
            return
        action = parts[2]  # confirm/cancel
        token = parts[3]
        key = f"transfer_rights_pending_{token}"
        pending = cache_get(key) or {}
        from_id = int(pending.get("from_id") or 0)
        to_id = int(pending.get("to_id") or 0)
        if not token or not from_id or not to_id or from_id != call.from_user.id:
            bot.answer_callback_query(call.id, "⏳ Запрос не найден или истёк.", show_alert=True)
            return

        if action == "cancel":
            cache_delete(key)
            bot.answer_callback_query(call.id, "Отменено")
            try:
                bot.edit_message_text("❌ Передача прав отменена.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            return

        # confirm
        if not is_user_in_chat(to_id):
            bot.answer_callback_query(call.id, "❌ Пользователь больше не в группе.", show_alert=True)
            return

        global ADMIN_CHAT_ID, settings
        settings["owner_user_id"] = int(to_id)
        save_settings(settings)
        ADMIN_CHAT_ID = int(to_id)
        cache_delete(key)

        bot.answer_callback_query(call.id, "✅ Права переданы", show_alert=True)
        try:
            bot.edit_message_text(
                f"✅ Права владельца переданы пользователю `{to_id}`.\n"
                "Теперь админ-панель и уведомления принадлежат новому владельцу.",
                call.message.chat.id,
                call.message.message_id,
                parse_mode="Markdown",
            )
        except Exception:
            pass

        # Уведомим нового владельца
        try:
            bot.send_message(
                to_id,
                "👑 Тебе передали права владельца бота.\n\n"
                "Открой ЛС с ботом и напиши `/start` чтобы увидеть админ-панель.",
                parse_mode="Markdown",
            )
        except Exception:
            pass
    except Exception as e:
        logger.error(f"Ошибка transfer_rights_callback: {e}")
        try:
            bot.answer_callback_query(call.id, "❌ Ошибка", show_alert=True)
        except Exception:
            pass


# Режим тестирования разработчика: "user" — видит бота как пользователь, "group_admin" — как владелец группы
DEVELOPER_TESTING_MODE: Optional[str] = None  # None | "user" | "group_admin"


def get_developer_testing_mode() -> Optional[str]:
    """Текущий режим тестирования разработчика (None = выключен)."""
    return DEVELOPER_TESTING_MODE


def is_owner(user_id: int) -> bool:
    """Проверяет, является ли пользователь владельцем бота. В режиме теста «как админ группы» — False."""
    if user_id in DEVELOPER_IDS and get_developer_testing_mode() == "group_admin":
        return False
    return user_id in DEVELOPER_IDS


def get_user_language(user_id: int) -> str:
    """
    Returns user language: 'ru' or 'en'.
    Order: cache → user_settings.language → users.language_code (Telegram) → 'en' (default).
    """
    cache_key = f"user_lang_{user_id}"
    cached = cache_get(cache_key)
    if cached in ("ru", "en"):
        return cached
    try:
        row = execute_query(
            USERS_DB,
            "SELECT language FROM user_settings WHERE user_id = ? LIMIT 1",
            (user_id,),
        )
        if row and row[0] and str(row[0][0]).strip().lower() == "en":
            cache_set(cache_key, "en", ttl=3600)
            return "en"
        if row and row[0]:
            cache_set(cache_key, "ru", ttl=3600)
            return "ru"
        lc = execute_query(
            USERS_DB,
            "SELECT language_code FROM users WHERE user_id = ? LIMIT 1",
            (user_id,),
        )
        if lc and lc[0] and lc[0][0]:
            code = (lc[0][0] or "").strip().lower()
            if code.startswith("en"):
                cache_set(cache_key, "en", ttl=3600)
                return "en"
    except Exception as e:
        logger.debug(f"get_user_language {user_id}: {e}")
    # Язык в БД не установлен (NULL) — по умолчанию русский
    cache_set(cache_key, "ru", ttl=3600)
    return "ru"


def set_user_language(user_id: int, lang: str) -> None:
    """Устанавливает язык пользователя ('ru' или 'en') в user_settings и сбрасывает кэш."""
    lang = "en" if lang == "en" else "ru"
    try:
        execute_query(
            USERS_DB,
            """INSERT INTO user_settings (user_id, language) VALUES (?, ?)
               ON CONFLICT(user_id) DO UPDATE SET language = excluded.language""",
            (user_id, lang),
        )
        cache_delete(f"user_lang_{user_id}")
        # EN: в интерфейсе суммы в $ (USD), если пользователь не выбирал другую валюту явно
        if lang == "en":
            try:
                rows = execute_query(
                    ECONOMY_DB,
                    "SELECT display_currency FROM users WHERE user_id = ?",
                    (user_id,),
                )
                stored = (rows[0][0] or "").strip().upper() if rows and rows[0] and rows[0][0] else ""
                if not stored or stored == "RUB":
                    currency_manager.set_user_currency(user_id, "USD")
            except Exception as e:
                logger.debug("set_user_language: currency USD for EN: %s", e)
    except Exception as e:
        logger.error(f"set_user_language {user_id}: {e}")


def get_user_timezone(user_id: int) -> Optional[str]:
    """Возвращает часовой пояс пользователя из user_settings (например Europe/Moscow) или None."""
    try:
        row = execute_query(
            USERS_DB,
            "SELECT timezone FROM user_settings WHERE user_id = ? AND timezone IS NOT NULL AND timezone != '' LIMIT 1",
            (user_id,),
        )
        if row and row[0] and row[0][0]:
            return str(row[0][0]).strip()
    except Exception as e:
        logger.debug(f"get_user_timezone {user_id}: {e}")
    return None


def set_user_timezone(user_id: int, tz: Optional[str]) -> None:
    """Устанавливает часовой пояс пользователя (например Europe/Moscow). Пустая строка или None — сброс."""
    try:
        execute_query(
            USERS_DB,
            """INSERT INTO user_settings (user_id, language, timezone) VALUES (?, 'ru', ?)
               ON CONFLICT(user_id) DO UPDATE SET timezone = excluded.timezone""",
            (user_id, tz or ""),
        )
    except Exception as e:
        logger.error(f"set_user_timezone {user_id}: {e}")


def get_user_current_group(user_id: int) -> Optional[int]:
    """Возвращает ID активной группы пользователя в ЛС (для переключения между группами) или None."""
