def _profile_balance_display(owner_id: int, balance: int, lang: str, for_markdown: bool = False) -> str:
    """Строка баланса для карточки профиля: либо сумма, либо «скрыт», если пользователь выключил отображение."""
    if not get_user_show_balance(owner_id):
        return t(lang, "balance_hidden")
    if for_markdown:
        return f"`{format_number(balance)}` {COM_EMOJI}"
    return format_amount_for_user(owner_id, balance)


def parse_toggle(value: str) -> Optional[bool]:
    """Парсит on/off значение."""
    value = value.strip().lower()
    if value in {"on", "1", "true", "yes", "да", "вкл"}:
        return True
    if value in {"off", "0", "false", "no", "нет", "выкл"}:
        return False
    return None


def normalize_alias_token(token: str) -> str:
    """Нормализует слово-алиас для командного конструктора."""
    return re.sub(r"[^\wа-яё]+", "", token.lower(), flags=re.IGNORECASE).strip()


