def get_custom_command_aliases() -> Dict[str, str]:
    """Возвращает пользовательские алиасы команд из настроек."""
    raw = settings.get("command_aliases", {})
    if not isinstance(raw, dict):
        return {}

    handlers = get_shortcut_handler_map()
    result: Dict[str, str] = {}
    for alias, command in raw.items():
        alias_key = normalize_alias_token(str(alias))
        command_str = str(command).strip()
        if not alias_key or not command_str:
            continue
        if not command_str.startswith("/"):
            command_str = "/" + command_str
        command_str = command_str.split()[0]
        if command_str in handlers:
            result[alias_key] = command_str
    return result


def invalidate_permissions_cache() -> None:
    """Очищает кэш прав/рангов после изменений в ролях."""
    for key in list(cache.keys()):
        if key.startswith("user_permissions_") or key.startswith("user_all_permissions_") or key.startswith("user_rank_"):
            cache_delete(key)


@bot.message_handler(commands=['cfg_button', 'setbutton'])
@safe_handler
def cmd_cfg_button(message: Message):
    """
    Конструктор: смена названия кнопки приглашения.
    Использование: /cfg_button Новый текст кнопки
    """
    global BUTTON_TEXT
    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return
    parts = (message.text or "").split(maxsplit=1)
    if len(parts) < 2 or not parts[1].strip():
        bot.reply_to(message, "Использование: /cfg_button Новый текст")
        return
    new_text = parts[1].strip()[:64]
    BUTTON_TEXT = new_text
    settings["button_text"] = new_text
    save_settings(settings)
    bot.reply_to(message, f"✅ Button text (RU) updated. Translating to EN in background…")
    threading.Thread(
        target=_auto_translate_ru_to_en_and_save,
        args=(new_text, "button_text_en", message.chat.id, "\n_(EN saved.)"),
        daemon=True,
    ).start()


@bot.message_handler(commands=['alias', 'aliases'])
@safe_handler
def cmd_alias(message: Message):
    """
    Конструктор алиасов.
    /alias add <слово> <команда>
    /alias del <слово>
    /alias list
    """
    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2:
        bot.reply_to(
            message,
            "Использование:\n"
            "/alias add <слово> <команда>\n"
            "/alias del <слово>\n"
            "/alias list"
        )
        return

    action = parts[1].lower()
    aliases_cfg = settings.get("command_aliases", {})
    if not isinstance(aliases_cfg, dict):
        aliases_cfg = {}
        settings["command_aliases"] = aliases_cfg

    if action == "list":
        custom = get_custom_command_aliases()
        if not custom:
            bot.reply_to(message, "ℹ️ Дополнительных алиасов пока нет.")
            return
        lines = ["🧩 **Дополнительные алиасы:**", ""]
        for alias_key, command_str in sorted(custom.items()):
            lines.append(f"• `{alias_key}` → `{command_str}`")
        bot.reply_to(message, "\n".join(lines), parse_mode="Markdown")
        return

    if action == "add":
        if len(parts) < 4:
            bot.reply_to(message, "Использование: /alias add <слово> <команда>")
            return
        alias_raw = parts[2]
        alias_key = normalize_alias_token(alias_raw)
        command_str = parts[3].strip()
        if not command_str.startswith("/"):
            command_str = "/" + command_str
        command_str = command_str.split()[0]
        handlers = get_shortcut_handler_map()
        if not alias_key:
            bot.reply_to(message, "❌ Некорректный алиас.")
            return
        if command_str not in handlers:
            supported = ", ".join(sorted(handlers.keys()))
            bot.reply_to(
                message,
                f"❌ Команда `{command_str}` не поддерживается конструктором.\n\n"
                f"Доступные: {supported}",
                parse_mode="Markdown"
            )
            return
        aliases_cfg[alias_key] = command_str
        settings["command_aliases"] = aliases_cfg
        save_settings(settings)
        bot.reply_to(message, f"✅ Алиас добавлен: `{alias_key}` → `{command_str}`", parse_mode="Markdown")
        return

    if action in {"del", "delete", "remove", "rm"}:
        if len(parts) < 3:
            bot.reply_to(message, "Использование: /alias del <слово>")
            return
        alias_key = normalize_alias_token(parts[2])
        if alias_key in aliases_cfg:
            del aliases_cfg[alias_key]
            settings["command_aliases"] = aliases_cfg
            save_settings(settings)
            bot.reply_to(message, f"✅ Алиас `{alias_key}` удалён.", parse_mode="Markdown")
        else:
            bot.reply_to(message, "ℹ️ Такой алиас не найден.")
        return

    bot.reply_to(message, "❌ Неизвестное действие. Используй: add / del / list")


@bot.message_handler(commands=['modcfg'])
@safe_handler
def cmd_modcfg(message: Message):
    """
    Конструктор модерации:
    /modcfg show
    /modcfg auto_moderate on|off
    /modcfg profanity on|off
    /modcfg auto_ban on|off
    /modcfg max_warn <1-10>
    /modcfg mute_hours <1-720>
    """
    global AUTO_MODERATE, PROFANITY_ENABLED, AUTO_BAN_ON_MAX_WARNINGS, MAX_WARNINGS, MUTE_DURATION

    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2 or parts[1].lower() == "show":
        bot.reply_to(
            message,
            "🛡️ Текущая модерация:\n"
            f"• auto_moderate: {'on' if AUTO_MODERATE else 'off'}\n"
            f"• profanity: {'on' if PROFANITY_ENABLED else 'off'}\n"
            f"• auto_ban: {'on' if AUTO_BAN_ON_MAX_WARNINGS else 'off'}\n"
            f"• max_warn: {MAX_WARNINGS}\n"
            f"• mute_hours: {MUTE_DURATION}"
        )
        return

    if len(parts) < 3:
        bot.reply_to(message, "Использование: /modcfg <параметр> <значение>")
        return

    key = parts[1].lower()
    value = parts[2]

    if key in {"auto_moderate", "profanity", "auto_ban"}:
        parsed = parse_toggle(value)
        if parsed is None:
            bot.reply_to(message, "❌ Используй on/off")
            return
        if key == "auto_moderate":
            AUTO_MODERATE = parsed
            settings["auto_moderate"] = parsed
        elif key == "profanity":
            PROFANITY_ENABLED = parsed
            settings["profanity_enabled"] = parsed
        else:
            AUTO_BAN_ON_MAX_WARNINGS = parsed
            settings["auto_ban_on_max_warnings"] = parsed
        save_settings(settings)
        bot.reply_to(message, f"✅ {key} = {'on' if parsed else 'off'}")
        return

    if key == "max_warn":
        try:
            n = int(value)
            if not (1 <= n <= 10):
                raise ValueError
        except ValueError:
            bot.reply_to(message, "❌ max_warn: число 1..10")
            return
        MAX_WARNINGS = n
        settings["max_warnings"] = n
        save_settings(settings)
        bot.reply_to(message, f"✅ max_warn = {n}")
        return

    if key == "mute_hours":
        try:
            n = int(value)
            if not (1 <= n <= 720):
                raise ValueError
        except ValueError:
            bot.reply_to(message, "❌ mute_hours: число 1..720")
            return
        MUTE_DURATION = n
        settings["mute_duration"] = n
        save_settings(settings)
        bot.reply_to(message, f"✅ mute_hours = {n}")
        return

    bot.reply_to(message, "❌ Неизвестный параметр. Используй /modcfg show")


@bot.message_handler(commands=['perm', 'rankperm'])
@safe_handler
def cmd_perm(message: Message):
    """
    Конструктор прав рангов:
    /perm list <rank>
    /perm set <rank> <permission> on|off
    """
    global rank_permissions

    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return

    parts = (message.text or "").split()
    if len(parts) < 3:
        bot.reply_to(
            message,
            "Использование:\n"
            "/perm list <rank>\n"
            "/perm set <rank> <permission> on|off"
        )
        return

    action = parts[1].lower()
    rank = parts[2]
    if rank not in {"1", "2", "3", "4", "5"}:
        bot.reply_to(message, "❌ rank должен быть от 1 до 5.")
        return

    if action == "list":
        perms = rank_permissions.get(rank, {})
        if not perms:
            bot.reply_to(message, f"ℹ️ У ранга {rank} нет настроенных прав.")
            return
        lines = [f"🛡️ **Права ранга {rank}**", ""]
        for perm_key in sorted(RankPermissions.PERMISSIONS.keys()):
            mark = "✅" if perms.get(perm_key, False) else "❌"
            lines.append(f"{mark} `{perm_key}`")
        bot.reply_to(message, "\n".join(lines), parse_mode="Markdown")
        return

    if action == "set":
        if len(parts) < 5:
            bot.reply_to(message, "Использование: /perm set <rank> <permission> on|off")
            return
        perm_key = parts[3].strip()
        if perm_key not in RankPermissions.PERMISSIONS:
            allowed = ", ".join(sorted(RankPermissions.PERMISSIONS.keys()))
            bot.reply_to(
                message,
                f"❌ Неизвестное право `{perm_key}`.\n\nДоступные: {allowed}",
                parse_mode="Markdown",
            )
            return
        parsed = parse_toggle(parts[4])
        if parsed is None:
            bot.reply_to(message, "❌ Используй on/off")
            return

        rank_permissions.setdefault(rank, {})
        rank_permissions[rank][perm_key] = parsed
        settings["rank_permissions"] = rank_permissions
        save_settings(settings)
        # Локальные права в group_roles.permissions не трогаем — они остаются у админов/модераторов в группах
        invalidate_permissions_cache()
        bot.reply_to(message, f"✅ Ранг {rank}: `{perm_key}` = {'on' if parsed else 'off'}", parse_mode="Markdown")
        return

    bot.reply_to(message, "❌ Неизвестное действие. Используй list/set.")



