def _telegraph_render_one_command(
    key: str,
    desc: str,
    example: str,
    catalog_by_key: Dict[str, Dict[str, Any]],
    parts: List[str],
) -> None:
    """Пишет в parts один блок команды (команды, заголовок, описание, пример)."""
    row = catalog_by_key.get(key)
    if row:
        cmds = row.get("commands", [row["key"]])
        title = html.escape(str(row.get("title", key)))
    else:
        cmds = [key]
        title = html.escape(key)
    cmd_str = ", ".join(f"<b>/{c}</b>" for c in cmds)
    safe_desc = html.escape(desc)
    line = f"<p>{cmd_str}<br><b>{title}</b><br>{safe_desc}"
    if example:
        line += f"<br><i>Пример: {html.escape(example)}</i>"
    line += "</p>"
    parts.append(line)


def build_telegraph_commands_html() -> str:
    """Собирает HTML справочника команд: категории, подкатегории и подробные описания (локальный экспорт / превью).
    Команды из COMMAND_CATALOG, которых нет в TELEGRAPH_HELP_STRUCTURE, добавляются автоматически
    в свою категорию с описанием по умолчанию (title), порядок по id сохраняется.
    Категории из TELEGRAPH_EXCLUDE_CATEGORIES (например admin) в разметку не попадают."""
    catalog_by_key = {r["key"]: r for r in COMMAND_CATALOG}
    # Только блоки для публичной страницы (без команд владельца)
    structure_blocks = [b for b in TELEGRAPH_HELP_STRUCTURE if b.get("category", "") not in TELEGRAPH_EXCLUDE_CATEGORIES]
    keys_in_structure: Set[str] = set()
    for block in structure_blocks:
        for sub in block.get("subcategories", []):
            for item in sub.get("commands", []):
                keys_in_structure.add(item.get("key", ""))

    parts = [
        "<h3>🌟 Все команды бота — подробная справка</h3>",
        "<p>Ниже все команды разбиты по категориям. Описания написаны простым языком; где нужно — есть примеры использования.</p>",
        "<p>В группе можно писать без слэша: <code>бот баланс</code>, <code>.дейли</code>, <code>?топ</code> — бот поймёт.</p>",
        "<hr>",
    ]

    for block in structure_blocks:
        cat = block.get("category", "")
        cat_label = block.get("category_label", "")
        cat_intro = block.get("category_intro", "")
        parts.append(f"<h4>{cat_label}</h4>")
        if cat_intro:
            parts.append(f"<p><i>{html.escape(cat_intro)}</i></p>")
        for sub in block.get("subcategories", []):
            sub_label = sub.get("sub_label", "")
            parts.append(f"<p><b>{html.escape(sub_label)}</b></p>")
            for item in sub.get("commands", []):
                key = item.get("key", "")
                desc = item.get("description", "")
                example = item.get("example", "")
                _telegraph_render_one_command(key, desc, example, catalog_by_key, parts)
            parts.append("")
        # Автоматически добавить команды из каталога этой категории, которых нет в структуре (порядок по id)
        catalog_in_cat = sorted(
            [r for r in COMMAND_CATALOG if r.get("category") == cat and r["key"] not in keys_in_structure],
            key=lambda r: r["id"],
        )
        if catalog_in_cat:
            parts.append(f"<p><b>{html.escape('Другие команды')}</b></p>")
            for row in catalog_in_cat:
                key = row["key"]
                default_desc = str(row.get("title", key))
                _telegraph_render_one_command(key, default_desc, "", catalog_by_key, parts)
            parts.append("")
        parts.append("")

    # Секция РП-команд: универсальные, VIP вне отношений, 18+, только для отношений
    parts.append("<h4>🎭 РП-команды</h4>")
    parts.append(
        "<p><b>Работают только в группе</b>. Ответом на сообщение напиши слово действия.</p>"
        "<p><b>Универсальные</b> (на любого, без отношений): <code>пожать руку</code>, <code>обнять</code>, <code>поцеловать</code>, <code>пнуть</code>, <code>выебать</code>, <code>трахнуть</code> и др.</p>"
        "<p><b>🔞 РП 18+</b> (поцеловать, выебать, трахнуть): при включённых в группе — универсальны для всех.</p>"
        "<p><b>👑 VIP вне отношений</b>: при включённой настройке группы VIP может использовать любые РП на любого (ужин, цветы и т.д.), без XP.</p>"
        "<p><b>Только для отношений</b> (нужна пара и уровень): романтический ужин, цветы, признание, кольцо, предложение, свадьба. Список: <b>/rp_commands</b>.</p>"
    )
    level_to_cmds: Dict[int, List[str]] = {}
    seen_activity: Set[str] = set()
    for cmd_name, spec in RP_ACTION_SPEC.items():
        min_level, xp, _t_key, activity_key = spec
        if activity_key in seen_activity:
            continue
        seen_activity.add(activity_key)
        level_to_cmds.setdefault(min_level, []).append(cmd_name)
    for lev in range(1, 12):
        cmds = level_to_cmds.get(lev, [])
        if not cmds:
            continue
        level_names = RELATIONSHIP_LEVEL_NAMES.get(lev, ("", ""))
        level_name_ru = level_names[0] if level_names else f"Уровень {lev}"
        xp_req = RELATIONSHIP_LEVEL_XP[lev] if lev < len(RELATIONSHIP_LEVEL_XP) else 0
        cmd_list = ", ".join(html.escape(c) for c in sorted(cmds, key=lambda x: x.lower()))
        parts.append(f"<p><b>Ур. {lev} — {html.escape(level_name_ru)}</b> (от {xp_req:,} XP): {cmd_list}</p>")
    parts.append("<p><i>Пример:</i> в группе ответь на сообщение партнёра текстом <code>обнять</code> или <code>бот обнять</code> — бот отправит действие и начислит паре XP.</p>")
    parts.append("")

    # Категории из каталога, которых нет в structure_blocks — вывести отдельным блоком (admin уже исключён)
    categories_in_structure = {b.get("category", "") for b in structure_blocks}
    for row in COMMAND_CATALOG:
        c = row.get("category", "")
        if c and c not in TELEGRAPH_EXCLUDE_CATEGORIES and c not in categories_in_structure:
            categories_in_structure.add(c)  # вывести блок один раз
            cat_label = COMMAND_ACCESS_CATEGORIES.get(c, f"📌 {c}")
            parts.append(f"<h4>{cat_label}</h4>")
            in_cat = sorted([r for r in COMMAND_CATALOG if r.get("category") == c], key=lambda r: r["id"])
            for r in in_cat:
                _telegraph_render_one_command(
                    r["key"], str(r.get("title", r["key"])), "", catalog_by_key, parts
                )
            parts.append("")

    parts.append("<hr>")
    parts.append("<p>📎 Часть команд работает только в группе, часть — только в личке. Для многих действий нужна подписка на основную группу бота.</p>")
    author = (settings.get("telegraph_author_name") or "").strip()
    if author:
        parts.append(f"<p>Бот: <a href=\"https://t.me/{author.lstrip('@')}\">{author}</a></p>")
    return "\n".join(parts)


def _extract_command_name(text: Optional[str]) -> Optional[str]:
    """Возвращает имя slash-команды без '/' и @botname."""
    if not text:
        return None
    value = text.strip()
    if not value.startswith("/"):
        return None
    token = value.split()[0][1:]
    if not token:
        return None
    return token.split("@", 1)[0].lower()


def resolve_command_entry(ref: str) -> Optional[Dict[str, Any]]:
    """Ищет команду по ID, /имени или алиасу."""
    if not ref:
        return None
    raw = ref.strip().lower()
    if raw.startswith("/"):
        raw = raw[1:]

    if raw.isdigit():
        return COMMAND_BY_ID.get(int(raw))

    key = COMMAND_ALIAS_TO_KEY.get(raw)
    if not key:
        return None
    return next((row for row in COMMAND_CATALOG if row["key"] == key), None)


def get_command_required_rank(command_key: str) -> int:
    """
    Возвращает минимальный ранг для команды.
    0 = всем, 6 = команда отключена.
    """
    entry = next((row for row in COMMAND_CATALOG if row["key"] == command_key), None)
    if entry is None:
        return 0

    default_rank = int(entry.get("default_rank", 0))
    overrides = settings.get("command_rank_overrides", {})
    if not isinstance(overrides, dict):
        return default_rank

    value = overrides.get(command_key, default_rank)
    try:
        rank = int(value)
    except Exception:
        rank = default_rank
    return max(0, min(6, rank))


def set_command_required_rank(command_key: str, rank_value: int) -> None:
    """Сохраняет минимальный ранг команды."""
    rank_value = max(0, min(6, int(rank_value)))
    overrides = settings.get("command_rank_overrides")
    if not isinstance(overrides, dict):
        overrides = {}

    entry = next((row for row in COMMAND_CATALOG if row["key"] == command_key), None)
    default_rank = int(entry.get("default_rank", 0)) if entry else 0

    if rank_value == default_rank:
        overrides.pop(command_key, None)
    else:
        overrides[command_key] = rank_value

    settings["command_rank_overrides"] = overrides
    save_settings(settings)


def reset_command_required_rank(command_key: str) -> None:
    """Сбрасывает команду к дефолтному рангу."""
    overrides = settings.get("command_rank_overrides")
    if isinstance(overrides, dict) and command_key in overrides:
        del overrides[command_key]
        settings["command_rank_overrides"] = overrides
        save_settings(settings)


def check_command_access(message: Message, silent: bool = False) -> bool:
    """
    Проверяет доступ пользователя к slash-команде по таблице рангов.
    """
    if not getattr(message, "text", None):
        return True

    cmd_name = _extract_command_name(message.text)
    if not cmd_name:
        return True

    command_key = COMMAND_ALIAS_TO_KEY.get(cmd_name)
    if not command_key:
        return True

    user_id = message.from_user.id
    if user_id in DEVELOPER_IDS:
        return True

    required_rank = get_command_required_rank(command_key)
    if required_rank >= 6:
        if not silent:
            bot.reply_to(message, "⛔ Эта команда сейчас отключена.")
        return False

    user_rank = get_user_rank(user_id)
    if user_rank < required_rank:
        if not silent:
            bot.reply_to(
                message,
                "🚫 Недостаточно прав для этой команды.\n"
                f"Твой ранг: {user_rank}\n"
                f"Нужно: {required_rank}",
            )
        return False

    return True


def _format_access_rank(rank_value: int) -> str:
    """Текстовый формат уровня доступа."""
    if rank_value <= 0:
        return "0 (всем)"
    if rank_value >= 6:
        return "6 (выкл)"
    return f"{rank_value} (от {rank_value}⭐)"


HELP_CATEGORY_ORDER = ["basic", "economy", "games", "profile", "stats", "social", "moderation", "admin"]
USER_HELP_CATEGORIES = {"basic", "economy", "games", "profile", "stats", "social"}
OWNER_HELP_CATEGORIES = {"moderation", "admin"}

COMMAND_HELP_HINTS: Dict[str, str] = {
    "send": "/send @username 100 [комментарий] или /send 100 ответом",
    "top": "/top balance|games|wins|streak",
    "roulette": "/roulette 100",
    "dice": "/dice 100 5",
    "roll": "/roll 4 или /roll 100 4 (ставка)",
    "flip": "/flip орёл или /flip 50 орёл (ставка)",
    "duel": "/duel 100 3 (ответом)",
    "top_activity": "/top_activity [дни]",
    "mute": "/mute [часы] [причина] — ответом на сообщение",
    "ban": "/ban [часы] [причина] — ответом; 0 или пусто = навсегда",
    "clear": "/clear [N] или ответом на сообщение — удалить сообщения",
    "maintenance": "/maintenance on|off|status",
    "cfg_button": "/cfg_button Новый текст",
    "alias": "/alias add|del|list ...",
    "modcfg": "/modcfg show|set ...",
    "perm": "/perm list|set ...",
    "cmdcfg": "/cmdcfg list|show|set|reset ...",
}


def _render_command_aliases_html(commands: List[str]) -> str:
    if not commands:
        return ""
    first = f"<code>/{html.escape(str(commands[0]))}</code>"
    rest = "".join(f" (<code>/{html.escape(str(alias))}</code>)" for alias in commands[1:])
    return first + rest


def _build_help_lines_for_categories(categories: Set[str], include_access_status: bool = False) -> List[str]:
    lines: List[str] = []
    for category in HELP_CATEGORY_ORDER:
        if category not in categories:
            continue
        rows = [row for row in COMMAND_CATALOG if row.get("category") == category]
        if not rows:
            continue
        rows.sort(key=lambda x: int(x.get("id", 0)))
        lines.append(f"{COMMAND_ACCESS_CATEGORIES.get(category, category)}")
        for row in rows:
            aliases_html = _render_command_aliases_html(row.get("commands", []))
            note = COMMAND_HELP_HINTS.get(row["key"], row.get("title", ""))
            status = ""
            if include_access_status:
                required = get_command_required_rank(row["key"])
                if required >= 6:
                    status = " <i>[выкл]</i>"
                elif required > 0:
                    status = f" <i>[от {required}⭐]</i>"
            if note:
                lines.append(f"• {aliases_html} — {html.escape(str(note))}{status}")
            else:
                lines.append(f"• {aliases_html}{status}")
        lines.append("")
    return lines


def build_participant_help_text(in_group: bool = False, user_id: Optional[int] = None, chat_id: Optional[int] = None, lang: Optional[str] = None) -> str:
    """Актуальная справка по командам. В группе блок модерации показывается только админам/владельцам. lang — для выбора URL гайда (ru/en)."""
    show_admin_commands = False
    if in_group and user_id is not None and chat_id is not None and chat_id < 0:
        role = get_user_role_in_group(user_id, chat_id)
        show_admin_commands = role in ("owner", "admin")
    games_line = (
        "🎮 <b>Игры</b>: /pvp_dice, /pvp_coin, /duel, /duel_stats, /roll, /flip, /calc"
        if PVP_GAMES_ONLY
        else "🎮 <b>Игры</b>: /roulette, /dice, /duel, /duel_stats, /roll, /flip, /calc"
    )
    lines: List[str] = [
        "🤖 <b>КОМАНДЫ БОТА</b>",
        "",
        "⚡ <b>Как вызвать</b>: <code>/help</code>, <code>бот команды</code>, <code>.команды</code>, <code>?команды</code>",
        "",
        "📌 <b>Старт</b>: <code>/start</code> — главное меню (нужна подписка на группу; реферальная ссылка даёт бонусы).",
        "📌 <b>Основное</b>: /time, /city, /lang, /ping, /weather, /joke, /joke18, /quote",
        "💰 <b>Экономика</b>: /balance, /daily, /send, /top, /shop, /inventory, /buy",
        games_line,
        "👤 <b>Профиль</b>: /whoami, /profile, /achievements",
        "📛 <b>Ник в группе</b>: /nick Имя или /nick (сброс) — только в группе",
        "📊 <b>Статистика</b>: /stats" + (", /chatstats, /chatinfo, /top_activity" if not in_group else ""),
        "💒 <b>Браки</b> (один партнёр, уровни, срок): /marry, /marriage, /divorce, /marriages",
        "💕 <b>Отношения</b> (несколько партнёров, уровни по каждому): /relationship, /breakup — ответом на сообщение, /relations",
        "🤖 <b>Ком и поддержка</b>: /ai, /support, /feedback, /faq; <code>/ad</code> — заявка на рекламу (в личке).",
    ]
    if show_admin_commands:
        lines.append("🛡️ <b>Команды админа</b>: /warn, /unwarn, /warnings, /mute, /unmute, /ban, /unban, /kick, /clear, /pin, /unpin, /filter, /ranks, /settings — по ответу на сообщение или в чате.")
    else:
        if in_group:
            lines.append("🛡️ <b>Модерация</b>: команды для администраторов группы (видны только им).")
    lines.extend([
        "",
        "• <code>кто я?</code>, <code>пинг</code>, <code>бот</code> — без слэша",
        "• <code>ком [вопрос]</code> — вопрос ИИ-помощнику (Ком).",
        "",
    ])
    telegraph_url = get_telegraph_commands_url(lang)
    if telegraph_url:
        lines.append("📄 <b>Полный список команд с описаниями</b> — по кнопке <b>«Все команды (сайт)»</b> ниже.")
        lines.append("")
    return "\n".join(lines)


