def _render_command_access_category(call: CallbackQuery, category: str) -> None:
    """Рендер списка команд категории и текущих уровней доступа."""
    lang = get_user_language(call.from_user.id)
    label = COMMAND_ACCESS_CATEGORIES.get(category, category)
    rows = [row for row in COMMAND_CATALOG if row.get("category") == category]

    lines = [f"🔢 <b>Доступ команд: {label}</b>", "", "Формат: <code>ID) /команда — доступ</code>"]
    for row in rows:
        current = get_command_required_rank(row["key"])
        primary = row.get("commands", [row["key"]])[0]
        lines.append(f"<code>{row['id']}) /{primary} — {_format_access_rank(current)}</code>")

    markup = InlineKeyboardMarkup(row_width=2)
    for row in rows:
        current = get_command_required_rank(row["key"])
        primary = row.get("commands", [row["key"]])[0]
        markup.add(
            InlineKeyboardButton(
                f"{row['id']}. /{primary} [{current}]",
                callback_data=f"concmd|pick|{row['id']}|{category}",
            )
        )
    markup.add(
        InlineKeyboardButton(t(lang, "back_to_categories_btn"), callback_data="constructor_cmd_access"),
        InlineKeyboardButton(t(lang, "back_to_constructor_btn"), callback_data="admin_constructor"),
    )

    bot.edit_message_text(
        "\n".join(lines),
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="HTML",
    )


def _render_command_access_pick(call: CallbackQuery, command_id: int, category: str) -> None:
    """Экран выбора уровня доступа для одной команды."""
    entry = COMMAND_BY_ID.get(command_id)
    if not entry:
        bot.answer_callback_query(call.id, "❌ Команда не найдена")
        return

    current = get_command_required_rank(entry["key"])
    default_rank = int(entry.get("default_rank", 0))
    primary = entry.get("commands", [entry["key"]])[0]

    markup = InlineKeyboardMarkup(row_width=4)
    rank_buttons = [
        InlineKeyboardButton("0", callback_data=f"concmd|set|{command_id}|0|{category}"),
        InlineKeyboardButton("1", callback_data=f"concmd|set|{command_id}|1|{category}"),
        InlineKeyboardButton("2", callback_data=f"concmd|set|{command_id}|2|{category}"),
        InlineKeyboardButton("3", callback_data=f"concmd|set|{command_id}|3|{category}"),
        InlineKeyboardButton("4", callback_data=f"concmd|set|{command_id}|4|{category}"),
        InlineKeyboardButton("5", callback_data=f"concmd|set|{command_id}|5|{category}"),
        InlineKeyboardButton("6 (выкл)", callback_data=f"concmd|set|{command_id}|6|{category}"),
    ]
    markup.add(*rank_buttons)
    markup.add(
        InlineKeyboardButton("♻️ Сброс к умолчанию", callback_data=f"concmd|reset|{command_id}|{category}"),
        InlineKeyboardButton(t(get_user_language(call.from_user.id), "back"), callback_data=f"concmd|back|{category}"),
    )

    bot.edit_message_text(
        f"🔢 <b>Команда #{entry['id']}</b>\n\n"
        f"<b>Команда:</b> <code>/{primary}</code>\n"
        f"<b>Категория:</b> {COMMAND_ACCESS_CATEGORIES.get(entry['category'], entry['category'])}\n"
        f"<b>Текущий доступ:</b> {_format_access_rank(current)}\n"
        f"<b>По умолчанию:</b> {_format_access_rank(default_rank)}\n\n"
        f"Выбери уровень доступа:",
        call.message.chat.id,
        call.message.message_id,
        reply_markup=markup,
        parse_mode="HTML",
    )


@bot.message_handler(commands=['cmdcfg', 'cmdaccess'])
@safe_handler
def cmd_cmdcfg(message: Message):
    """
    Настройка доступа к командам по ID/рангу.
    /cmdcfg list [category]
    /cmdcfg show <id|cmd>
    /cmdcfg set <id|cmd> <0-6>
    /cmdcfg reset <id|cmd|all>
    """
    if not is_owner(message.from_user.id):
        bot.reply_to(message, "🚫 Команда доступна только владельцу.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2:
        bot.reply_to(
            message,
            "Использование:\n"
            "/cmdcfg list [category]\n"
            "/cmdcfg show <id|cmd>\n"
            "/cmdcfg set <id|cmd> <0-6>\n"
            "/cmdcfg reset <id|cmd|all>\n\n"
            "Категории: " + ", ".join(COMMAND_ACCESS_CATEGORIES.keys())
        )
        return

    action = parts[1].lower()

    if action == "list":
        category = parts[2].lower() if len(parts) > 2 else "all"
        cats = [category] if category != "all" else list(COMMAND_ACCESS_CATEGORIES.keys())
        invalid = [c for c in cats if c not in COMMAND_ACCESS_CATEGORIES]
        if invalid:
            bot.reply_to(message, f"❌ Неизвестная категория: {', '.join(invalid)}")
            return

        lines = ["🔢 <b>Доступ к командам</b>", "", "<code>0=всем | 1..5=по рангу | 6=off</code>", ""]
        for cat in cats:
            lines.append(f"<b>{COMMAND_ACCESS_CATEGORIES[cat]}</b>")
            for row in [x for x in COMMAND_CATALOG if x['category'] == cat]:
                current = get_command_required_rank(row['key'])
                primary = row['commands'][0]
                lines.append(f"<code>{row['id']}) /{primary} -> {current}</code>")
            lines.append("")

        bot.reply_to(message, "\n".join(lines), parse_mode="HTML")
        return

    if action == "show":
        if len(parts) < 3:
            bot.reply_to(message, "Использование: /cmdcfg show <id|cmd>")
            return
        entry = resolve_command_entry(parts[2])
        if not entry:
            bot.reply_to(message, "❌ Команда не найдена.")
            return
        current = get_command_required_rank(entry['key'])
        default_rank = int(entry.get("default_rank", 0))
        aliases = ", ".join(f"/{x}" for x in entry.get("commands", []))
        bot.reply_to(
            message,
            "🔎 <b>Команда</b>\n\n"
            f"ID: <code>{entry['id']}</code>\n"
            f"Команды: <code>{aliases}</code>\n"
            f"Категория: {COMMAND_ACCESS_CATEGORIES.get(entry['category'], entry['category'])}\n"
            f"Текущий доступ: <code>{current}</code>\n"
            f"По умолчанию: <code>{default_rank}</code>",
            parse_mode="HTML",
        )
        return

    if action == "set":
        if len(parts) < 4:
            bot.reply_to(message, "Использование: /cmdcfg set <id|cmd> <0-6>")
            return
        entry = resolve_command_entry(parts[2])
        if not entry:
            bot.reply_to(message, "❌ Команда не найдена.")
            return
        try:
            rank_value = int(parts[3])
            if rank_value < 0 or rank_value > 6:
                raise ValueError
        except ValueError:
            bot.reply_to(message, "❌ Ранг должен быть числом 0..6")
            return

        set_command_required_rank(entry['key'], rank_value)
        bot.reply_to(
            message,
            f"✅ Для /{entry['commands'][0]} установлен уровень: <code>{rank_value}</code>",
            parse_mode="HTML",
        )
        return

    if action == "reset":
        if len(parts) < 3:
            bot.reply_to(message, "Использование: /cmdcfg reset <id|cmd|all>")
            return
        target = parts[2].lower()
        if target == "all":
            settings["command_rank_overrides"] = {}
            save_settings(settings)
            bot.reply_to(message, "♻️ Все переопределения доступа команд сброшены.")
            return
        entry = resolve_command_entry(parts[2])
        if not entry:
            bot.reply_to(message, "❌ Команда не найдена.")
            return
        reset_command_required_rank(entry['key'])
        bot.reply_to(message, f"♻️ /{entry['commands'][0]} сброшена к доступу по умолчанию.")
        return

    bot.reply_to(message, "❌ Неизвестное действие. Используй list/show/set/reset")


