def process_text_shortcut_command(message: Message) -> bool:
    """
    Обрабатывает короткие команды в группе. Обязательный префикс (иначе не сработает):
    - «бот слово» или «ком слово» / «ии слово» — вызов команды по алиасу
    - «.слово» или «?слово» — то же
    Без префикса работают только явные фразы: «меню», «кто я», «чат инфа», «пинг», «бот».
    """
    if message.content_type != "text" or not message.text:
        return False

    raw_text = message.text.strip()
    lower = raw_text.lower()
    payload = ""
    normalized = re.sub(r"[^\wа-яё]+", " ", lower, flags=re.IGNORECASE).strip()
    normalized_single = re.sub(r"\s+", "", normalized)  # без пробелов для «ктоя», «чатинфа»

    # «Кто ты?» ответом на сообщение — показать профиль того, кому ответили (только в группе)
    if getattr(message.chat, "type", "") in ("group", "supergroup"):
        if message.reply_to_message and getattr(message.reply_to_message, "from_user", None):
            who_ru = (lower in ("кто ты?", "кто ты", "кто это?", "кто это", "докс") or
                      normalized in ("кто ты", "кто это", "докс"))
            who_en = (lower in ("who are you?", "who are you", "who is this?", "who is this") or
                      normalized in ("who are you", "who is this"))
            if who_ru or who_en:
                if not ensure_user_access(message):
                    return False
                target_user = message.reply_to_message.from_user
                if getattr(target_user, "is_bot", False):
                    return False
                viewer_id = message.from_user.id
                chat_id = message.chat.id
                can_view, error_msg = can_view_profile(viewer_id, target_user.id, chat_id)
                if not can_view:
                    lang = get_user_language(viewer_id)
                    bot.reply_to(message, error_msg or t(lang, "view_profile_denied"))
                    return True
                register_user(target_user.id)
                send_profile_card(chat_id, target_user.id, viewer_id=viewer_id)
                return True

    aliases = {**get_builtin_shortcut_aliases(), **get_custom_command_aliases()}

    # Префиксы: обязательны для вызова команд по слову (бот / ком / ии / . / ? / !)
    if raw_text.startswith(".") or raw_text.startswith("?"):
        payload = raw_text[1:].strip()
    elif lower.startswith("! "):
        payload = raw_text[2:].strip()
    elif lower.startswith("!"):
        payload = raw_text[1:].strip()
    elif lower.startswith("бот "):
        payload = raw_text[4:].strip()
    elif lower.startswith("ком "):
        payload = raw_text[4:].strip()
    elif lower.startswith("ии "):
        payload = raw_text[3:].strip()
    # Без префикса — только эти фразы целиком
    elif lower in ("меню", "команды", "команда", "commands", "menu"):
        payload = raw_text.strip()
    elif normalized in ("кто я", "ктоя", "whoami", "me") or normalized_single == "ктоя":
        payload = "ктоя"
    elif normalized in ("чат инфа", "чатинфа", "чат инфо", "чатинфо", "chat info", "chatinfo") or normalized_single == "чатинфа":
        payload = "чатинфа"
    elif normalized in ("пинг", "ping"):
        payload = "пинг"
    elif normalized in ("бот", "bot"):
        payload = "ботпроверка"
    elif lower.startswith("выебать ") or lower == "выебать" or lower.startswith("трахнуть ") or lower == "трахнуть":
        payload = raw_text.strip()
    elif lower in ("+отн", "-отн", "отн"):
        payload = raw_text.strip()
    else:
        return False

    if not payload:
        return False

    # Текстовые команды отношений: +Отн / -Отн / Отн @user или ответом на сообщение
    if getattr(message.chat, "type", "") in ("group", "supergroup"):
        pl = payload.strip().lower()
        if pl.startswith("+отн") or pl.startswith("-отн") or pl == "отн" or pl.startswith("отн "):
            if not ensure_user_access(message, require_group=True):
                return True
            chat_id = message.chat.id
            user_id = message.from_user.id
            lang = get_user_language(user_id)
            target = _resolve_target_user_from_message(message)
            if pl.startswith("+отн"):
                if not target or target.id == user_id:
                    bot.reply_to(message, t(lang, "rel_self"))
                    return True
                if getattr(target, "is_bot", False):
                    bot.reply_to(message, t(lang, "rel_bot"))
                    return True
                if _get_relationship_with_partner(chat_id, user_id, target.id) or _get_relationship_with_partner(chat_id, target.id, user_id):
                    bot.reply_to(message, t(lang, "rel_already_with_this"))
                    return True
                now = datetime.now().isoformat()
                rows = execute_query(USERS_DB, "INSERT INTO relationship_proposals (chat_id, from_id, to_id, created_at) VALUES (?, ?, ?, ?) RETURNING id", (chat_id, user_id, target.id, now))
                prop_id = rows[0][0] if rows else None
                from_name = message.from_user.first_name or "Пользователь"
                target_name = target.first_name or "Пользователь"
                text = t(lang, "rel_proposal", from_name=from_name, target_name=target_name)
                markup = InlineKeyboardMarkup()
                if prop_id:
                    markup.add(InlineKeyboardButton(t(lang, "rel_accept_btn"), callback_data=f"rel_accept_{prop_id}"))
                    markup.add(InlineKeyboardButton(t(lang, "rel_decline_btn"), callback_data=f"rel_decline_{prop_id}"))
                bot.reply_to(message, text, reply_markup=markup, parse_mode="Markdown")
                return True
            if pl.startswith("-отн"):
                if not target or target.id == user_id:
                    bot.reply_to(message, t(lang, "rel_breakup_reply"))
                    return True
                rel = _get_relationship_with_partner(chat_id, user_id, target.id)
                if not rel:
                    bot.reply_to(message, t(lang, "rel_breakup_not_together"))
                    return True
                _delete_relationship_with_partner(chat_id, user_id, target.id)
                bot.reply_to(message, t(lang, "rel_breakup"))
                return True
            if pl == "отн" or pl.startswith("отн "):
                if not target or target.id == user_id:
                    rels = _get_relationships_list(chat_id, user_id)
                    if not rels:
                        bot.reply_to(message, t(lang, "rel_single"))
                        return True
                    status_text = t(lang, "rel_status_header") + "\n\n" + t(lang, "rel_status_multi_header")
                    for rel in rels:
                        partner_id = rel["partner_id"]
                        level = rel.get("level", 0)
                        exp = rel.get("experience", 0)
                        created = _format_db_timestamp_as_date(rel.get("created_at"))
                        level_name = relationship_level_name(level, lang) if level > 0 else "—"
                        next_threshold = RELATIONSHIP_LEVEL_XP[level + 1] if level < 11 and (level + 1) < len(RELATIONSHIP_LEVEL_XP) else RELATIONSHIP_LEVEL_XP[-1]
                        xp_left = max(0, next_threshold - exp)
                        level_xp_str = t(lang, "rel_status_level_xp_since", level=level, exp=format_number(exp), date=created)
                        partner_name = get_user_display_name_in_chat(partner_id, chat_id, get_user_display_name(chat_id, partner_id, lang))
                        status_text += "\n\n• " + get_user_mention(partner_id, partner_name, lang=lang) + " — " + level_name + " " + level_xp_str
                        if level < 11 and xp_left > 0:
                            status_text += "\n  " + t(lang, "rel_status_xp_next", xp_left=format_number(xp_left))
                    bot.reply_to(message, status_text, parse_mode="Markdown")
                    return True
                rel = _get_relationship_with_partner(chat_id, user_id, target.id)
                if not rel:
                    bot.reply_to(message, t(lang, "rel_breakup_not_together"))
                    return True
                level = rel.get("level", 0)
                exp = rel.get("experience", 0)
                level_name = relationship_level_name(level, lang) if level > 0 else "—"
                next_threshold = RELATIONSHIP_LEVEL_XP[level + 1] if level < 11 and (level + 1) < len(RELATIONSHIP_LEVEL_XP) else RELATIONSHIP_LEVEL_XP[-1]
                xp_left = max(0, next_threshold - exp)
                created = _format_db_timestamp_as_date(rel.get("created_at"))
                level_xp_str = t(lang, "rel_status_level_xp_since", level=level, exp=format_number(exp), date=created)
                text = t(lang, "rel_status_header") + "\n\n• " + get_user_mention(target.id, get_user_display_name_in_chat(target.id, chat_id, get_user_display_name(chat_id, target.id, lang)), lang=lang) + " — " + level_name + " " + level_xp_str
                if level < 11 and xp_left > 0:
                    text += "\n  " + t(lang, "rel_status_xp_next", xp_left=format_number(xp_left))
                bot.reply_to(message, text, parse_mode="Markdown")
                return True

    parts = payload.split(maxsplit=1)
    cmd = (parts[0].lower() if parts else "").strip()
    rest = (parts[1] if len(parts) > 1 else "").strip()

    # .стата день / .стата неделя / .стата месяц / .стата год / .стата 15 (кастомный период)
    if getattr(message.chat, "type", "") in ("group", "supergroup") and (cmd == "стата" or cmd == "стат"):
        if rest:
            parsed = _parse_stata_period(rest)
            if parsed:
                days, period_label = parsed
                if ensure_user_access(message, require_group=True):
                    cmd_stata_period(message, days, period_label)
                return True
        # без периода — как обычно /stats
        message.text = f"/stats {rest}".strip()
        handler_map = get_shortcut_handler_map()
        handler = handler_map.get("/stats")
        if handler:
            handler(message)
            return True

    # Вызов по отношениям в стиле точечных команд (Ирис-подобно, со своей уникальностью)
    if getattr(message.chat, "type", "") in ("group", "supergroup"):
        handler_map = get_shortcut_handler_map()
        # Мои отношения: .отнстата .отнстат .отн стата .моиотн .уровниотн .люки_мои
        if cmd in ("отнстата", "отнстат", "моиотн", "уровниотн", "люки_мои") or (cmd == "отн" and rest == "стата") or (cmd == "мои" and rest == "отн"):
            if ensure_user_access(message, require_group=True):
                handler = handler_map.get("/relationship")
                if handler:
                    message.text = "/relationship"
                    handler(message)
            return True
        # Список пар в чате: .парычата .пары .люки .чатотн .сердечки .кто_в_отн .отны
        if cmd in ("парычата", "пары", "люки", "люк", "чатотн", "сердечки", "кто_в_отн", "отны"):
            if ensure_user_access(message, require_group=True):
                handler = handler_map.get("/relations")
                if handler:
                    message.text = "/relations"
                    handler(message)
            return True
        # РП-команды: .рпкоманды .рпком .рп
        if cmd in ("рпкоманды", "рпком", "рп") or (cmd == "рп" and rest == "команды"):
            if ensure_user_access(message):
                handler = handler_map.get("/rp_commands")
                if handler:
                    message.text = "/rp_commands"
                    handler(message)
            return True

    # РП «выебать» / «трахнуть»: ответом на сообщение или «Выебать @user» / «Трахнуть @user»
    if cmd in ("выебать", "трахнуть") and (message.reply_to_message or (len(parts) > 1 and parts[1].strip())):
        if handle_rp_relationship_action(message, cmd):
            return True
    # РП-действия: одно- или многословные команды (пожать руку, обнять, романтический ужин и т.д.)
    if message.reply_to_message and message.reply_to_message.from_user:
        cmd_rp_two = (cmd + " " + parts[1].split()[0].lower()).strip() if len(parts) > 1 and parts[1] else ""
        for cmd_try in (cmd_rp_two, cmd):
            if cmd_try and _rp_action_key_and_xp(cmd_try):
                if handle_rp_relationship_action(message, cmd_try):
                    return True
                break

    # Нормализуем «слипшееся» слово для сопоставления с алиасами
    cmd_compact = re.sub(r"[^\wа-яё]", "", cmd, flags=re.IGNORECASE)
    rest = parts[1] if len(parts) > 1 else ""

    # Сначала одно слово, потом фраза целиком, полный payload, потом префикс алиаса (для «брак продлить 30» и т.п.)
    full_payload = payload.strip().lower()
    command = aliases.get(cmd) or aliases.get(cmd_compact) or aliases.get(normalized) or aliases.get(full_payload)
    if not command:
        # Префиксное совпадение: самый длинный алиас, с которого начинается payload
        prefix_rest = rest
        for key in sorted(aliases.keys(), key=len, reverse=True):
            if full_payload == key or full_payload.startswith(key + " "):
                command = aliases[key]
                prefix_rest = full_payload[len(key):].strip()
                break
        if not command:
            return False
        rest = prefix_rest
    message.text = f"{command} {rest}".strip()
    handler_map = get_shortcut_handler_map()

    handler = handler_map.get(command.split()[0])
    if not handler:
        return False

    handler(message)
    return True

# ============================================================================
# ТОП АКТИВНОСТИ
# ============================================================================

@bot.message_handler(commands=['top_activity', 'topactive'])
@safe_handler
def cmd_top_activity(message: Message):
    """
    Команда для просмотра топа активности.
    Использование: /top_activity [дней]
    """
    if not ensure_user_access(message, require_group=True):
        return
    chat_id = message.chat.id
    args = (message.text or "").split()
    
    days = 7
    if len(args) > 1:
        try:
            days = min(30, max(1, int(args[1])))
        except Exception:
            pass
    
    try:
        # Получаем топ по сообщениям
        result = execute_query(
            MESSAGE_STATS_DB,
            """SELECT user_id, SUM(count) as total 
               FROM message_counts 
               WHERE chat_id=? AND date > date('now', ?)
               GROUP BY user_id 
               ORDER BY total DESC 
               LIMIT 50""",
            (chat_id, f"-{days} days")
        )
        
        if not result:
            bot.reply_to(message, f"📭 Нет данных за последние {days} дней")
            return
        
        text = f"📊 **ТОП АКТИВНОСТИ ЗА {days} ДНЕЙ**\n\n"
        
        pos = 0
        for row in result:
            user_id = row[0]
            count = row[1]
            if is_excluded_bot_user(user_id):
                continue
            pos += 1
            
            try:
                user = bot.get_chat_member(chat_id, user_id)
                name = user.user.first_name
            except Exception:
                name = f"ID:{user_id}"
            
            medal = {1: "🥇", 2: "🥈", 3: "🥉"}.get(pos, f"{pos}.")
            text += f"{medal} {name} — {count} сообщ.\n"
            if pos >= 10:
                break
        
        msg = bot.reply_to(message, text, parse_mode="Markdown")
        
        if AUTO_DELETE_GAMES:
            schedule_deletion(chat_id, message.message_id, 120)
            schedule_deletion(chat_id, msg.message_id, 120)
            
    except Exception as e:
        logger.error(f"Ошибка получения топа активности: {e}")
        bot.reply_to(message, f"❌ Ошибка получения данных")

# ============================================================================
# ОБРАБОТКА ВСЕХ СООБЩЕНИЙ
# ============================================================================

def should_reward_message(user_id: int, message: Message) -> bool:
    """
    Проверяет, нужно ли начислять награду за сообщение.
    Блокирует короткие, повторяющиеся и слишком частые сообщения.
    """
    text = (message.text or "").strip()
    if not text:
        return False

    # Команды не награждаем
    if text.startswith("/"):
        return False

    normalized = re.sub(r"\s+", " ", text).lower().strip()
    compact = re.sub(r"\s+", "", normalized)

    # Минимальная осмысленная длина
    if len(compact) < MESSAGE_REWARD_MIN_CHARS:
        return False

    # Должны быть буквы/цифры (не только эмодзи/знаки)
    if not re.search(r"[A-Za-zА-Яа-яЁё0-9]", normalized):
        return False

    # Блок "аааааааа" / "11111111"
    if compact and len(set(compact)) == 1:
        return False

    state = message_reward_tracker[user_id]
    now = time.time()

    # Кулдаун между наградами
    if now - state["last_reward_ts"] < MESSAGE_REWARD_COOLDOWN_SEC:
        return False

    # Лимит наград в минуту
    recent_rewards = [t for t in state["recent_rewards"] if now - t < 60]
    if len(recent_rewards) >= MESSAGE_REWARD_MAX_PER_MINUTE:
        state["recent_rewards"] = recent_rewards
        return False

    # Блок одинаковых сообщений в течение окна
    last_same_time = state["last_text_times"].get(normalized)
    if last_same_time and now - last_same_time < MESSAGE_REWARD_DUPLICATE_WINDOW_SEC:
        return False

    # Обновляем трекинг только при успешном прохождении
    state["last_reward_ts"] = now
    recent_rewards.append(now)
    state["recent_rewards"] = recent_rewards
    state["last_text_times"][normalized] = now

    # Периодическая чистка карты повторов
    ttl = MESSAGE_REWARD_DUPLICATE_WINDOW_SEC * 3
    if len(state["last_text_times"]) > 200:
        state["last_text_times"] = {
            k: v for k, v in state["last_text_times"].items() if now - v <= ttl
        }

    return True

@bot.message_handler(func=lambda message: True, content_types=['text', 'photo', 'video', 'document', 'sticker'])
@safe_handler
def handle_all_messages(message: Message):
    """
    Обрабатывает все сообщения в чате:
    - Регистрирует пользователей
    - Начисляет монеты за сообщения
    - Проверяет на мат
    - Проверяет муты
    - Считает активность
    """
    user_id = message.from_user.id
    chat_id = message.chat.id
    message_id = message.message_id
    is_sender_chat_message = getattr(message, "sender_chat", None) is not None
    
    # Глобальный guard доступа (без шумных ответов на каждое сообщение).
    if not ensure_user_access(message, silent=True):
        return

    remember_user_if_bot(message.from_user)

    # Игнорируем сообщения любых ботов
    if getattr(message.from_user, "is_bot", False):
        return

    # Короткие текстовые команды (.стата / ?stats / бот баланс)
    if process_text_shortcut_command(message):
        return

    # Игнорируем негрупповые чаты
    if message.chat.type not in ['group', 'supergroup']:
        return
    
    # Проверяем, не в бане ли пользователь
    if is_banned(user_id, chat_id):
        try:
            bot.delete_message(chat_id, message_id)
        except Exception:
            pass
        return
    
    # Проверяем мут
    if is_muted(user_id, chat_id):
        try:
            bot.delete_message(chat_id, message_id)
        except Exception:
            pass
        return
    
    # Регистрируем пользователя/обновляем профиль только для обычных сообщений от пользователя.
    if not is_sender_chat_message:
        register_user(user_id)
        update_user_info(user_id, message.from_user)

        # Фиксируем первое вступление в эту группу (для каждой группы своя дата).
        try:
            when_dt = datetime.fromtimestamp(int(getattr(message, "date", 0) or 0)) if getattr(message, "date", None) else datetime.now()
        except Exception:
            when_dt = datetime.now()
        ensure_user_group_joined(user_id, when_dt, source="observed_message", chat_id=chat_id)
    
    # Начисляем монеты за сообщение (если включено)
    if (not is_sender_chat_message) and COINS_ENABLED and COINS_MESSAGE_REWARD > 0:
        if should_reward_message(user_id, message):
            # Проверяем буст
            multiplier = ItemEffects.get_xp_multiplier(user_id)
            reward = COINS_MESSAGE_REWARD * multiplier
            reward += ItemEffects.get_message_reward_bonus(user_id)
            add_coins(user_id, reward, "За сообщение в чате")
    
    # Сохраняем сообщение для истории только для обычных пользователей.
    if not is_sender_chat_message:
        save_user_message(user_id, message_id, message.text if message.text else "")
    
    # Считаем сообщение в активности
    if not is_sender_chat_message:
        increment_message_count(user_id, chat_id)
    
    # Проверяем на мат (если включено)
    if PROFANITY_ENABLED and message.text:
        has_profanity, word, severity = profanity_filter.check(message.text)
        
        if has_profanity:
            # Удаляем сообщение
            try:
                bot.delete_message(chat_id, message_id)
            except Exception:
                pass
            
            # Отправляем предупреждение
            warning_text = f"⚠️ {message.from_user.first_name}, пожалуйста, не используй запрещённые слова!"
            bot.send_message(chat_id, warning_text)
            
            # Если автомодерация включена, выдаём предупреждение (не больше лимита группы — get_effective_warn_limit)
            if AUTO_MODERATE:
                _wl = get_effective_warn_limit(chat_id)
                warnings = get_warnings_count(user_id, chat_id)
                if warnings < _wl:
                    add_warning(
                        user_id=user_id,
                        chat_id=chat_id,
                        reason=f"Мат: {word}",
                        admin_id=bot.get_me().id
                    )
                    warnings = get_warnings_count(user_id, chat_id)
                    if warnings >= _wl and AUTO_BAN_ON_MAX_WARNINGS:
                        ok_bot, _ = bot_has_ban_rights(chat_id)
                        if ok_bot:
                            add_ban(
                                user_id=user_id,
                                chat_id=chat_id,
                                admin_id=bot.get_me().id,
                                reason=f"Достигнут лимит предупреждений ({_wl})",
                                duration_minutes=24 * 7 * 60,
                            )
                            lang_chat = get_user_language(message.from_user.id)
                            bot.send_message(
                                chat_id,
                                t(lang_chat, "automod_ban_message", name=message.from_user.first_name or str(message.from_user.id))
                            )
                elif AUTO_BAN_ON_MAX_WARNINGS and warnings >= _wl:
                    ok_bot, _ = bot_has_ban_rights(chat_id)
                    if ok_bot:
                        add_ban(
                            user_id=user_id,
                            chat_id=chat_id,
                            admin_id=bot.get_me().id,
                            reason=f"Достигнут лимит предупреждений ({_wl})",
                            duration_minutes=24 * 7 * 60,
                        )
                        lang_chat = get_user_language(message.from_user.id)
                        bot.send_message(
                            chat_id,
                            t(lang_chat, "automod_ban_message", name=message.from_user.first_name or str(message.from_user.id))
                        )

# ============================================================================
# ОБРАБОТКА НОВЫХ УЧАСТНИКОВ
# ============================================================================

@bot.message_handler(content_types=['new_chat_members'])
def handle_new_members(message: Message):
    """Обработка новых участников."""
    chat_id = message.chat.id
    try_delete_service_notification(message)

    # Если в группу добавили самого бота — сбрасываем кэш владельца, сохраняем связь user->group, уведомляем в ЛС, проверяем права
    try:
        me = bot.get_me()
        me_id = me.id
        for new_member in message.new_chat_members:
            if getattr(new_member, "id", None) == me_id:
                invalidate_chat_creator_cache(chat_id)
                inviter_id = message.from_user.id if message.from_user else None
                chat_title = getattr(message.chat, "title", None) or str(chat_id)
                if not inviter_id:
                    try:
                        chat_admins = bot.get_chat_administrators(chat_id)
                        if chat_admins:
                            first_admin = chat_admins[0]
                            inviter_id = getattr(getattr(first_admin, "user", None), "id", None)
                            if inviter_id:
                                logger.info("handle_new_members: using fallback inviter_id=%s for chat_id=%s", inviter_id, chat_id)
                    except Exception as e:
                        logger.debug("handle_new_members: get_chat_administrators for fallback: %s", e)
                if inviter_id:
                    # Обязательная подписка для админов групп: кто добавил бота должен быть подписан
                    ok_sub, missing = check_all_subscriptions(inviter_id)
                    if not ok_sub and missing:
                        try:
                            bot.leave_chat(chat_id)
                        except Exception:
                            pass
                        try:
                            channels = "\n".join([f"• {ch.get('title', ch.get('chat_username', ''))}" for ch in missing])
                            bot.send_message(
                                inviter_id,
                                f"❌ **Бот удалён из группы**\n\nЧтобы использовать бота в группах, подпишитесь:\n{channels}\n\nПосле подписки попробуйте снова!",
                                parse_mode="Markdown",
                            )
                        except Exception:
                            pass
                        break
                    register_user(inviter_id)
                    if message.from_user:
                        update_user_info(inviter_id, message.from_user)
                    save_bot_added_to_group(chat_id, inviter_id, chat_title)
                    ensure_group_owner_role_and_settings(chat_id, inviter_id)
                    inviter_lang = get_user_language(inviter_id)
                    # Права админа проверим ниже после get_chat_member и уведомим разработчика
                    try:
                        dm_text = t(inviter_lang, "bot_added_dm_notify", title=chat_title) + "\n\n" + t(inviter_lang, "bot_added_dm_manage_hint")
                        dm_markup = InlineKeyboardMarkup()
                        group_username = getattr(message.chat, "username", None) if message.chat else None
                        if group_username:
                            dm_markup.add(InlineKeyboardButton(t(inviter_lang, "bot_added_dm_btn_group"), url=f"https://t.me/{group_username}"))
                        bot_username = getattr(me, "username", None)
                        if bot_username:
                            dm_markup.add(InlineKeyboardButton(t(inviter_lang, "bot_added_btn_configure"), url=f"https://t.me/{bot_username}?start=group_setup_{chat_id}"))
                        bot.send_message(inviter_id, dm_text, parse_mode="Markdown", reply_markup=dm_markup if dm_markup.keyboard else None)
                    except Exception as dm_e:
                        logger.debug("Не удалось отправить ЛС тому, кто добавил бота: %s", dm_e)
                # При первом добавлении в группу — сначала выбор языка, потом приветствие
                group_lang = get_group_language(chat_id)
                if group_lang is None:
                    lang_select_markup = InlineKeyboardMarkup()
                    lang_select_markup.add(InlineKeyboardButton("🇷🇺 Русский", callback_data="group_lang_ru"))
                    lang_select_markup.add(InlineKeyboardButton("🇬🇧 English", callback_data="group_lang_en"))
                    bot.send_message(
                        chat_id,
                        "🌐 Выберите язык группы / Please select group language:",
                        reply_markup=lang_select_markup,
                    )
                    break
                lang = group_lang
                try:
                    bot_member = bot.get_chat_member(chat_id, me_id)
                    is_admin = getattr(bot_member, "status", "") in ("administrator", "creator")
                except Exception:
                    is_admin = False
                update_bot_admin_status(chat_id, is_admin)
                if inviter_id:
                    notify_developer_bot_added_to_group(chat_id, chat_title, inviter_id, is_admin)
                bot_username = getattr(me, "username", None)
                configure_url = f"https://t.me/{bot_username}?start=group_setup_{chat_id}" if bot_username else None
                if is_admin:
                    group_markup = InlineKeyboardMarkup()
                    if configure_url:
                        group_markup.add(InlineKeyboardButton(t(lang, "bot_added_btn_configure"), url=configure_url))
                    sent = bot.send_message(
                        chat_id,
                        t(lang, "bot_added_admin_ok"),
                        parse_mode="Markdown",
                        reply_markup=group_markup if group_markup.keyboard else None,
                    )
                    if inviter_id and getattr(sent, "message_id", None):
                        save_bot_added_setup_message(inviter_id, chat_id, sent.message_id)
                else:
                    markup = InlineKeyboardMarkup()
                    markup.add(InlineKeyboardButton(t(lang, "bot_admin_confirm_btn"), callback_data=f"group_setup_confirm_{chat_id}"))
                    if configure_url:
                        markup.add(InlineKeyboardButton(t(lang, "bot_added_btn_configure"), url=configure_url))
                    need_admin_text = t(lang, "bot_added_need_admin") + "\n\n" + t(lang, "bot_required_permissions")
                    sent = bot.send_message(
                        chat_id,
                        need_admin_text,
                        parse_mode="Markdown",
                        reply_markup=markup,
                    )
                    if inviter_id and getattr(sent, "message_id", None):
                        save_bot_added_setup_message(inviter_id, chat_id, sent.message_id)
                break
    except Exception as e:
        logger.debug(f"handle_new_members bot check: {e}")

    for new_member in message.new_chat_members:
        remember_user_if_bot(new_member)
        # Игнорируем ботов (включая самого бота)
        if getattr(new_member, "is_bot", False):
            continue
        
        # Welcome message with quick-command buttons (localized)
        lang = get_user_language(new_member.id)
        welcome_text = t(
            lang, "welcome_new_member_group",
            name=new_member.first_name or "User",
            coins=COINS_START_BALANCE,
            sign=COM_EMOJI,
        )
        welcome_markup = InlineKeyboardMarkup(row_width=2)
        telegraph_url = get_telegraph_commands_url(lang)
        if telegraph_url:
            welcome_markup.add(
                InlineKeyboardButton("📄 " + t(lang, "menu_commands"), url=telegraph_url),
            )
        welcome_markup.add(
            InlineKeyboardButton(t(lang, "menu_help"), callback_data="group_welcome_help"),
            InlineKeyboardButton(t(lang, "menu_balance"), callback_data="group_welcome_balance"),
            InlineKeyboardButton(t(lang, "menu_daily"), callback_data="group_welcome_daily"),
            InlineKeyboardButton(t(lang, "menu_shop"), callback_data="group_welcome_shop"),
            InlineKeyboardButton(t(lang, "menu_faq"), callback_data="group_welcome_faq"),
        )
        bot.send_message(chat_id, welcome_text, parse_mode="Markdown", reply_markup=welcome_markup)
        
        # Регистрируем в экономике + фиксируем "первый вход в бота" в users.db
        register_user(new_member.id)
        update_user_info(new_member.id, new_member)

        # Фиксируем первое вступление в эту группу (для каждой группы своя дата).
        try:
            when_dt = datetime.fromtimestamp(int(getattr(message, "date", 0) or 0)) if getattr(message, "date", None) else datetime.now()
        except Exception:
            when_dt = datetime.now()
        ensure_user_group_joined(new_member.id, when_dt, source="event_new_chat_member", chat_id=chat_id)
        chat_title = getattr(message.chat, "title", None) or str(chat_id)
        now_ts = when_dt.isoformat(sep=" ", timespec="seconds") if isinstance(when_dt, datetime) else str(when_dt)
        try:
            execute_query(
                USERS_DB,
                """UPDATE user_group_joins SET group_title=?, last_seen=?, is_active=1, left_at=NULL
                   WHERE user_id=? AND chat_id=?""",
                (chat_title, now_ts, new_member.id, chat_id),
            )
        except Exception as e:
            logger.debug("user_group_joins group_title/last_seen: %s", e)
        execute_query(USERS_DB, "DELETE FROM user_chat_left WHERE user_id = ? AND chat_id = ?", (new_member.id, chat_id))
        _clear_subscription_cache(new_member.id)  # чтобы при нажатии «Я подписался» проверка прошла сразу
        # После вступления считаем доступ к Кому открытым.
        cache_set(f"kom_chat_access_{new_member.id}", True, ttl=3600)

        # Уведомление админу «Новый участник» приходит только при первом запуске бота (/start в личке), а не при входе в группу.

        # ЛС-уведомление о первом вступлении + подарок (кнопка запуска Кома).
        if chat_id == CHAT_ID and not is_welcome_sent(new_member.id):
            try:
                gift_markup = InlineKeyboardMarkup()
                gift_markup.add(
                    InlineKeyboardButton("✨ Открыть Подарок ✨", callback_data="gift_open_kom")
                )
                bot.send_message(
                    new_member.id,
                    "🎉 Отличная работа! Рады видеть тебя в нашей закрытой группе. "
                    "Там мы делимся фишками, новостями и общаемся с единомышленниками.\n\n"
                    "А теперь — самое интересное! Дверь в мир креатива открыта. "
                    "Нажимай на кнопку ниже, чтобы запустить Нейросеть и создать свой первый шедевр.",
                    reply_markup=gift_markup,
                )
                set_welcome_sent(new_member.id)
                _mark_welcome_dm_sent_in_db(new_member.id)
            except Exception as e:
                logger.info(f"Не удалось отправить подарочное ЛС пользователю {new_member.id}: {e}")

# ============================================================================
# ИЗМЕНЕНИЕ ПРАВ БОТА В ГРУППЕ (my_chat_member)
# ============================================================================

def _handle_my_chat_member(cmu) -> None:
    """Обрабатывает обновление прав бота в чате: сохраняет в БД и уведомляет разработчика."""
    try:
        chat_id = getattr(cmu.chat, "id", None)
        if chat_id is None or chat_id >= 0:
            return
        from_user = getattr(cmu, "from_user", None)
        from_user_id = getattr(from_user, "id", None) if from_user else None
        old_m = getattr(cmu, "old_chat_member", None)
        new_m = getattr(cmu, "new_chat_member", None)
        if not new_m:
            return
        new_status = (getattr(new_m, "status", None) or "").lower()
        old_status = (getattr(old_m, "status", None) or "").lower() if old_m else ""
        me_id = bot.get_me().id
        new_user_id = getattr(getattr(new_m, "user", None), "id", None)
        if new_user_id != me_id:
            return
        chat_title = getattr(cmu.chat, "title", None) or str(chat_id)
        is_admin_now = new_status in ("administrator", "creator")
        was_admin = old_status in ("administrator", "creator")
        update_bot_admin_status(chat_id, is_admin_now)
        if is_admin_now and not was_admin:
            notify_developer_bot_admin_rights_changed(chat_id, chat_title, granted=True)
        elif was_admin and not is_admin_now:
            notify_developer_bot_admin_rights_changed(chat_id, chat_title, granted=False)
        if new_status in ("member", "administrator", "creator") and old_status in ("left", "kicked", ""):
            save_bot_added_fallback(chat_id, chat_title, from_user_id)
    except Exception as e:
        logger.debug("_handle_my_chat_member: %s", e)


try:
    _my_chat_member_handler = getattr(bot, "my_chat_member_handler", None)
    if callable(_my_chat_member_handler):

        @_my_chat_member_handler()
        def handle_my_chat_member(cmu):
            _handle_my_chat_member(cmu)
except Exception as e:
    logger.debug("my_chat_member_handler not available: %s", e)


# ============================================================================
# ОБРАБОТКА УЧАСТНИКОВ, ПОКИНУВШИХ ЧАТ
# ============================================================================

@bot.message_handler(content_types=['left_chat_member'])
def handle_left_member(message: Message):
    """Обработка участников, покинувших чат (в т.ч. удаление бота из группы)."""
    try_delete_service_notification(message)
    left_member = message.left_chat_member
    chat_id = message.chat.id

    remember_user_if_bot(left_member)

    # Если из группы удалили самого бота — очищаем запись в bot_groups и хранилище сообщений /start
    try:
        me_id = bot.get_me().id
        if getattr(left_member, "id", None) == me_id:
            with _last_start_lock:
                if chat_id in _last_start_messages:
                    try:
                        bot.delete_message(chat_id, _last_start_messages[chat_id])
                    except Exception:
                        pass
                    del _last_start_messages[chat_id]
            remove_bot_from_group(chat_id)
            return
    except Exception:
        pass

    # Игнорируем любых ботов (кроме уже обработанного случая с ботом)
    if getattr(left_member, "is_bot", False):
        return

    try:
        execute_query(
            USERS_DB,
            "UPDATE user_group_joins SET is_active=0, left_at=? WHERE user_id=? AND chat_id=?",
            (datetime.now(), left_member.id, chat_id),
        )
    except Exception as e:
        logger.debug("user_group_joins left_at: %s", e)

    if chat_id == CHAT_ID:
        _clear_subscription_cache(left_member.id)  # чтобы при следующей проверке подписки был актуальный статус
        cache_delete(f"last_sub_message_{left_member.id}")
        for key in list(cache.keys()):
            if key.startswith(f"last_sub_message_{left_member.id}"):
                cache_delete(key)

    # Отправляем прощальное сообщение
    bot.send_message(
        message.chat.id,
        f"👋 {left_member.first_name} покинул чат... Ждём обратно!",
        parse_mode="Markdown"
    )
    
    # Очищаем историю сообщений
    clear_all_user_messages(left_member.id)

    # Авторазвод: если у брака включён режим «один» — развод при выходе одного; «два» — при выходе обоих
    try:
        left_id = left_member.id
        rows = execute_query(USERS_DB, "SELECT user1_id, user2_id, auto_divorce FROM marriages WHERE chat_id = ? AND (status IS NULL OR status = 'active') AND (auto_divorce = 'one' OR auto_divorce = 'two')", (chat_id,))
        if rows:
            now = datetime.now().isoformat()
            restore_end = (datetime.now() + timedelta(days=3)).isoformat()

            for row in rows:
                u1, u2 = int(row[0]), int(row[1])
                mode = (row[2] or "").strip().lower() if len(row) > 2 else ""
                if mode == "one" and (left_id == u1 or left_id == u2):
                    execute_query(USERS_DB, "UPDATE marriages SET status = 'divorced', divorced_at = ?, restore_until = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (now, restore_end, chat_id, u1, u2))

            for row in rows:
                u1, u2 = int(row[0]), int(row[1])
                mode = (row[2] or "").strip().lower() if len(row) > 2 else ""
                if mode != "two":
                    continue
                if left_id != u1 and left_id != u2:
                    continue
                other_id = u2 if left_id == u1 else u1
                try:
                    other_m = bot.get_chat_member(chat_id, other_id)
                    if getattr(other_m, "status", "") in ("left", "kicked"):
                        execute_query(USERS_DB, "UPDATE marriages SET status = 'divorced', divorced_at = ?, restore_until = ? WHERE chat_id = ? AND user1_id = ? AND user2_id = ?", (now, restore_end, chat_id, u1, u2))
                except Exception:
                    pass
    except Exception as e:
        logger.debug("marriage auto_divorce on leave: %s", e)

    # Фиксируем дату выхода: через N дней брак/отношения автоматически завершатся при следующем обращении к ним
    try:
        now = datetime.now().isoformat()
        execute_query(USERS_DB, "INSERT OR REPLACE INTO user_chat_left (user_id, chat_id, left_at) VALUES (?, ?, ?)", (left_member.id, chat_id, now))
    except Exception as e:
        logger.debug("user_chat_left insert: %s", e)

    # Сбрасываем привилегии (ранг) при выходе из основного чата — без группы нет прав в боте
    chat_id = message.chat.id
    if chat_id == CHAT_ID or chat_id in ALLOWED_GROUPS:
        if left_member.id not in DEVELOPER_IDS and get_user_rank(left_member.id) > 0:
            set_user_rank(left_member.id, 0)
            logger.info(f"Сброшен ранг пользователя {left_member.id} после выхода из группы")

    # Отменяем дуэли в этом чате с участием вышедшего (ставки не списывались — просто удаляем)
    try:
        for duel_id, duel in duel_manager.get_duels_in_chat_involving_user(chat_id, left_member.id):
            other_id = duel.opponent_id if duel.challenger_id == left_member.id else duel.challenger_id
            duel_manager.remove_duel(duel_id)
            try:
                bot.send_message(
                    chat_id,
                    f"⚔️ Дуэль #{duel_id} отменена: {left_member.first_name} покинул(а) чат.",
                    parse_mode="Markdown"
                )
            except Exception:
                pass
            logger.info(f"Дуэль #{duel_id} отменена: участник {left_member.id} вышел из чата {chat_id}")
    except Exception as e:
        logger.debug(f"Отмена дуэлей при выходе: {e}")

