def update_user_info(user_id: int, user: telebot.types.User):
    """
    Обновляет информацию о пользователе в БД.
    
    Args:
        user_id: ID пользователя
        user: Объект User от Telegram
    joined_date не перезаписывается (COALESCE) — дата вступления сохраняется при обновлении скрипта.
    """
    remember_user_if_bot(user)
    if is_excluded_bot_user(user_id):
        return
    try:
        now = datetime.now()
        execute_query(
            USERS_DB,
            """INSERT INTO users
               (user_id, username, first_name, last_name, language_code, is_premium, joined_date, last_seen, last_active)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(user_id) DO UPDATE SET
                 username = excluded.username,
                 first_name = excluded.first_name,
                 last_name = excluded.last_name,
                 language_code = excluded.language_code,
                 is_premium = excluded.is_premium,
                 last_seen = excluded.last_seen,
                 last_active = excluded.last_active,
                 joined_date = COALESCE(users.joined_date, excluded.joined_date)""",
            (
                user_id,
                getattr(user, "username", None),
                getattr(user, "first_name", None),
                getattr(user, "last_name", None),
                getattr(user, "language_code", None),
                getattr(user, "is_premium", 0) if hasattr(user, "is_premium") else 0,
                now,
                now,
                now,
            ),
        )
    except Exception as e:
        logger.error(f"Ошибка обновления информации пользователя {user_id}: {e}")


def _get_user_lifecycle(user_id: int, chat_id: Optional[int] = None) -> Dict[str, Any]:
    """Возвращает joined_date (первый вход в бота) и group_joined_date (вступление в указанную группу).
    chat_id: для какой группы показывать «В группе с»; если None — используется CHAT_ID (основная группа).
    Если joined_date в БД пустой — подставляется last_seen или last_active (для старых пользователей)."""
    effective_chat = chat_id if chat_id is not None else globals().get("CHAT_ID")
    result = {"joined_date": None, "group_joined_date": None, "group_join_source": None}
    try:
        rows = execute_query(
            USERS_DB,
            "SELECT joined_date, last_seen, last_active FROM users WHERE user_id=? LIMIT 1",
            (user_id,),
        ) or []
        if rows:
            r = rows[0]
            result["joined_date"] = r[0]  # joined_date
            if not result["joined_date"] and (r[1] or r[2]):
                # Для старых пользователей без joined_date — показываем самую раннюю из last_seen/last_active
                candidates = [x for x in (r[1], r[2]) if x]
                result["joined_date"] = min(candidates) if candidates else None
            if not result["joined_date"]:
                # Дата вступления в бота: подставляем из экономики (users.registered)
                result["joined_date"] = get_user_registered_at(user_id)
        if effective_chat is not None:
            row_join = execute_query(
                USERS_DB,
                """SELECT joined_at, source FROM user_group_joins
                   WHERE user_id=? AND chat_id=? AND (is_active=1 OR is_active IS NULL) LIMIT 1""",
                (user_id, effective_chat),
            )
            if row_join and row_join[0]:
                result["group_joined_date"] = row_join[0][0]
                result["group_join_source"] = row_join[0][1] if len(row_join[0]) > 1 else None
            else:
                fallback = execute_query(
                    USERS_DB,
                    "SELECT group_joined_date, group_join_source FROM users WHERE user_id=? LIMIT 1",
                    (user_id,),
                )
                if fallback and fallback[0] and effective_chat == globals().get("CHAT_ID"):
                    result["group_joined_date"] = fallback[0][0]
                    result["group_join_source"] = fallback[0][1] if len(fallback[0]) > 1 else None
    except Exception:
        pass
    return result


def _format_user_ts(ts_value: Any, use_msk: bool = False) -> str:
    if not ts_value:
        return "—"
    try:
        if isinstance(ts_value, datetime):
            dt = ts_value
        else:
            s = str(ts_value)
            try:
                dt = datetime.fromisoformat(s)
            except Exception:
                # sqlite может вернуть "YYYY-MM-DD HH:MM:SS"
                dt = datetime.strptime(s.split(".")[0], "%Y-%m-%d %H:%M:%S")
        if use_msk:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            msk = timezone(timedelta(hours=3))
            dt = dt.astimezone(msk)
            return dt.strftime("%d.%m.%Y %H:%M МСК")
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.strftime("%d.%m.%Y %H:%M UTC")
    except Exception:
        return str(ts_value)


def format_datetime_for_user(dt: Any, lang: str) -> str:
    """
    Форматирует дату для отображения: RU — МСК, EN — UTC.
    """
    if dt is None:
        return "—"
    try:
        if isinstance(dt, str):
            dt = datetime.fromisoformat(dt.replace("Z", "+00:00"))
        return _format_user_ts(dt, use_msk=(lang == "ru"))
    except Exception:
        return str(dt)[:16] if dt else "—"


def _format_group_join_label(info: Dict[str, Any], use_msk: bool = False, lang: str = "ru") -> str:
    """
    Форматирует «В группе с: ...» с пометкой
    «(учёт с момента обновления)», если дату вступления мы узнали не из события new_chat_member.
    """
    base = _format_user_ts(info.get("group_joined_date"), use_msk=use_msk)
    if base == "—":
        return base
    src = (info.get("group_join_source") or "").strip()
    if src and src != "event_new_chat_member":
        if (lang or "").strip().lower() == "en":
            return f"{base} (accounted from the update)"
        return f"{base} (учёт с момента обновления)"
    return base


def ensure_user_group_joined(
    user_id: int,
    when_dt: Optional[datetime] = None,
    source: str = "observed",
    chat_id: Optional[int] = None,
) -> None:
    """Фиксирует дату первого вступления в группу. Для каждой группы хранится своя дата (user_group_joins).
    COALESCE сохраняет уже записанную дату. chat_id: группа; если None — CHAT_ID (основная)."""
    if is_excluded_bot_user(user_id):
        return
    effective_chat = chat_id if chat_id is not None else globals().get("CHAT_ID")
    if effective_chat is None:
        return
    try:
        when_dt = when_dt or datetime.now()
        when_ts = when_dt.isoformat(sep=" ", timespec="seconds") if isinstance(when_dt, datetime) else str(when_dt)
        execute_query(
            USERS_DB,
            """INSERT INTO user_group_joins (user_id, chat_id, joined_at, source) VALUES (?, ?, ?, ?)
               ON CONFLICT(user_id, chat_id) DO UPDATE SET
                 joined_at = COALESCE(joined_at, excluded.joined_at),
                 source = COALESCE(source, excluded.source)""",
            (user_id, effective_chat, when_ts, source),
        )
        if effective_chat == globals().get("CHAT_ID"):
            execute_query(
                USERS_DB,
                """UPDATE users SET group_joined_date = COALESCE(group_joined_date, ?), group_join_source = COALESCE(group_join_source, ?) WHERE user_id = ?""",
                (when_ts, source, user_id),
            )
    except Exception as e:
        logger.error(f"Ошибка фиксации вступления в группу {effective_chat} для {user_id}: {e}")


def get_user_join_date(user_id: int, chat_id: int) -> Optional[datetime]:
    """
    Возвращает дату вступления пользователя в конкретную группу.
    Если пользователь не вступал в эту группу или вышел — возвращает None.
    """
    try:
        result = execute_query(
            USERS_DB,
            """SELECT joined_at FROM user_group_joins
               WHERE user_id=? AND chat_id=? AND (is_active=1 OR is_active IS NULL) LIMIT 1""",
            (user_id, chat_id),
        )
        if result and result[0][0]:
            raw = result[0][0]
            if isinstance(raw, datetime):
                return raw
            s = str(raw)
            try:
                return datetime.fromisoformat(s)
            except Exception:
                return datetime.strptime(s.split(".")[0], "%Y-%m-%d %H:%M:%S")
    except Exception as e:
        logger.debug("get_user_join_date: %s", e)
    return None


def get_messages_since_group_join(user_id: int, chat_id: int) -> Tuple[Optional[int], Optional[str]]:
    """
    Возвращает (count, start_date_yyyy_mm_dd) сообщений пользователя с момента вступления в эту группу.
    Если дата вступления неизвестна — (None, None).
    """
    info = _get_user_lifecycle(user_id, chat_id)
    joined = info.get("group_joined_date")
    if not joined:
        return None, None
    try:
        if isinstance(joined, datetime):
            join_dt = joined
        else:
            s = str(joined)
            try:
                join_dt = datetime.fromisoformat(s)
            except Exception:
                join_dt = datetime.strptime(s.split(".")[0], "%Y-%m-%d %H:%M:%S")
        start_date = join_dt.strftime("%Y-%m-%d")
        rows = execute_query(
            MESSAGE_STATS_DB,
            """SELECT COALESCE(SUM(count), 0)
               FROM message_counts
               WHERE user_id = ? AND chat_id = ? AND date >= ?""",
            (user_id, chat_id, start_date),
        ) or []
        total = int(rows[0][0] or 0) if rows and rows[0] else 0
        return total, start_date
    except Exception as e:
        logger.error(f"Ошибка подсчёта сообщений с вступления для {user_id}: {e}")
        return 0, None

def save_user_message(user_id: int, message_id: int, text: str):
    """
    Сохраняет сообщение пользователя в историю.
    
    Args:
        user_id: ID пользователя
        message_id: ID сообщения
        text: Текст сообщения
    """
    if is_excluded_bot_user(user_id):
        return
    try:
        execute_query(
            USERS_DB,
            """INSERT INTO user_history 
               (user_id, action, details, date)
               VALUES (?, ?, ?, ?)""",
            (
                user_id,
                "message",
                json.dumps({"message_id": message_id, "text": text[:200]}),
                datetime.now()
            )
        )
    except Exception as e:
        logger.error(f"Ошибка сохранения сообщения: {e}")

def increment_message_count(user_id: int, chat_id: int):
    """
    Увеличивает счётчик сообщений пользователя.
    
    Args:
        user_id: ID пользователя
        chat_id: ID чата
    """
    if is_excluded_bot_user(user_id):
        return
    try:
        today = datetime.now().strftime('%Y-%m-%d')
        now_ts = datetime.now()
        params = (user_id, chat_id, today, now_ts, now_ts)
        query = """INSERT INTO message_counts (user_id, chat_id, date, count, last_message)
                   VALUES (?, ?, ?, 1, ?)
                   ON CONFLICT(user_id, chat_id, date)
                   DO UPDATE SET count = count + 1, last_message = ?"""

        # Основное постоянное хранилище статистики сообщений.
        execute_query(MESSAGE_STATS_DB, query, params)
        # Дублируем в activity.db для обратной совместимости старых отчётов/миграций.
        execute_query(ACTIVITY_DB, query, params)
    except Exception as e:
        logger.error(f"Ошибка увеличения счётчика сообщений: {e}")

def get_user_history(user_id: int, limit: int = 50) -> List[Dict[str, Any]]:
    """
    Возвращает историю действий пользователя.
    
    Args:
        user_id: ID пользователя
        limit: Максимальное количество
    
    Returns:
        List[Dict[str, Any]]: История
    """
    try:
        result = execute_query(
            USERS_DB,
            "SELECT action, details, date FROM user_history WHERE user_id=? ORDER BY date DESC LIMIT ?",
            (user_id, limit)
        )
        
        history = []
        if result:
            for row in result:
                history.append({
                    "action": row[0],
                    "details": json.loads(row[1]) if row[1] else {},
                    "date": row[2]
                })
        
        return history
        
    except Exception as e:
        logger.error(f"Ошибка получения истории: {e}")
        return []

def get_user_achievements(user_id: int) -> List[Dict[str, Any]]:
    """
    Возвращает достижения пользователя.
    LEFT JOIN с таблицей achievements: если в БД нет описания достижения,
    подставляются имя/описание/иконка из словаря achievements (чтобы раздел
    «Достижения» в профиле не был пустым при пустой таблице achievements).
    """
    try:
        lang = get_user_language(user_id)
        use_en = (lang or "").strip().lower() == "en"
        achievements_fallback = achievements_en if use_en else achievements
        result = execute_query(
            ECONOMY_DB,
            """SELECT ua.achievement_id, ua.earned_date, a.name, a.description, a.icon
               FROM user_achievements ua
               LEFT JOIN achievements a ON ua.achievement_id = a.id
               WHERE ua.user_id=?
               ORDER BY ua.earned_date DESC""",
            (user_id,)
        )
        achievements_list = []
        if result:
            for row in result:
                ach_id = row[0]
                fallback = achievements_fallback.get(ach_id, {})
                achievements_list.append({
                    "id": ach_id,
                    # In EN mode we always want English text even if DB contains RU.
                    "name": (
                        fallback.get("name", row[2] if row[2] else ach_id)
                        if use_en
                        else (row[2] if row[2] else fallback.get("name", ach_id))
                    ),
                    "desc": (
                        fallback.get("description", row[3] if row[3] is not None else "")
                        if use_en
                        else (row[3] if row[3] is not None else fallback.get("description", ""))
                    ),
                    "icon": row[4] if row[4] else fallback.get("icon", "🏆"),
                    "earned_date": row[1]
                })
        return achievements_list
    except Exception as e:
        logger.error(f"Ошибка получения достижений: {e}")
        return []

def award_achievement(user_id: int, achievement_id: str) -> bool:
    """
    Выдаёт достижение пользователю.
    
    Args:
        user_id: ID пользователя
        achievement_id: ID достижения
    
    Returns:
        bool: True если выдано (или уже было)
    """
    try:
        # Проверяем, есть ли уже
        result = execute_query(
            ECONOMY_DB,
            "SELECT 1 FROM user_achievements WHERE user_id=? AND achievement_id=?",
            (user_id, achievement_id)
        )
        
        if result:
            return False  # Уже есть
        
        # Выдаём
        execute_query(
            ECONOMY_DB,
            "INSERT INTO user_achievements (user_id, achievement_id, earned_date) VALUES (?, ?, ?)",
            (user_id, achievement_id, datetime.now())
        )
        
        logger.info(f"✅ Пользователь {user_id} получил достижение {achievement_id}")
        return True
        
    except Exception as e:
        logger.error(f"Ошибка выдачи достижения: {e}")
        return False

def is_admin(user_id: int) -> bool:
    """
    Проверяет, является ли пользователь администратором (разработчиком).
    В режиме теста «как пользователь» разработчик не считается админом.
    """
    if user_id in DEVELOPER_IDS and get_developer_testing_mode() == "user":
        return False
    return user_id in DEVELOPER_IDS

# Кэш проверки подписки: TTL 90 сек, чтобы не дергать get_chat_member при каждом действии
SUBSCRIPTION_CACHE_TTL = 90


def _clear_subscription_cache(user_id: int) -> None:
    """Сбрасывает кэш подписки для пользователя (после нажатия «Я подписался»)."""
    cache_delete(f"sub_check_{user_id}")


def is_user_in_chat(user_id: int, use_cache: bool = True) -> bool:
    """
    Проверяет, находится ли пользователь в чате сейчас.
    Кэширует результат на SUBSCRIPTION_CACHE_TTL сек для снижения нагрузки на API.
    
    Args:
        user_id: ID пользователя
        use_cache: использовать кэш (False при проверке по кнопке «Я подписался»)
    
    Returns:
        bool: True если в чате
    """
    if use_cache:
        cached = cache_get(f"sub_check_{user_id}")
        if cached is not None:
            return bool(cached)
    try:
        member = bot.get_chat_member(CHAT_ID, user_id)
        # Статусы участников в чате:
        # 'creator' - создатель
        # 'administrator' - админ
        # 'member' - обычный участник
        # 'restricted' - ограничен (тоже считается в чате)
        # 'left' - покинул
        # 'kicked' - забанен
        in_chat = member.status in ['creator', 'administrator', 'member', 'restricted']
        if use_cache:
            cache_set(f"sub_check_{user_id}", in_chat, ttl=SUBSCRIPTION_CACHE_TTL)
        return in_chat
    except Exception as e:
        # Если пользователь никогда не был в чате, будет ошибка
        logger.debug("Ошибка проверки пользователя %s в чате: %s", user_id, e)
        if use_cache:
            cache_set(f"sub_check_{user_id}", False, ttl=SUBSCRIPTION_CACHE_TTL)
        return False

def format_expiry_time(expires: int) -> str:
    """
    Форматирует время до истечения.
    
    Args:
        expires: Время истечения в Unix timestamp
    
    Returns:
        str: Отформатированное время
    """
    remaining = expires - int(time.time())
    
    if remaining <= 0:
        return "истекла"
    
    hours = remaining // 3600
    minutes = (remaining % 3600) // 60
    
    if hours > 0:
        return f"{hours}ч {minutes}м"
    else:
        return f"{minutes}м"

def get_next_daily_time(user_id: int) -> Tuple[int, int]:
    """
    Возвращает время до следующего daily бонуса.
    
    Args:
        user_id: ID пользователя
    
    Returns:
        Tuple[int, int]: (часы, минуты)
    """
    try:
        result = execute_query(
            ECONOMY_DB,
            "SELECT last_daily FROM users WHERE user_id=?",
            (user_id,)
        )
        
        if result and result[0][0]:
            last_raw = result[0][0]
            try:
                if isinstance(last_raw, str) and "T" not in last_raw and " " in last_raw:
                    last = datetime.strptime(last_raw.split(".")[0], "%Y-%m-%d %H:%M:%S")
                else:
                    last = datetime.fromisoformat(str(last_raw).replace("Z", "+00:00").split(".")[0])
            except Exception:
                return 0, 0
            next_time = last + timedelta(hours=24)
            remaining = (next_time - datetime.now()).total_seconds()
            if remaining <= 0:
                return 0, 0
            hours = int(remaining // 3600)
            minutes = int((remaining % 3600) // 60)
            return hours, minutes
        
        return 0, 0
        
    except Exception:
        return 0, 0

def get_all_users() -> List[int]:
    """
    Возвращает список всех пользователей в БД.
    
    Returns:
        List[int]: Список ID
    """
    try:
        result = execute_query(USERS_DB, "SELECT user_id FROM users")
        
        if result:
            return [row[0] for row in result]
        
        return []
        
    except Exception as e:
        logger.error(f"Ошибка получения списка пользователей: {e}")
        return []

