def init_achievements():
    """Инициализирует достижения в БД."""
    for ach_id, ach_data in achievements.items():
        try:
            execute_query(
                ECONOMY_DB,
                """INSERT OR IGNORE INTO achievements 
                   (id, name, description, reward, icon) 
                   VALUES (?, ?, ?, ?, ?)""",
                (ach_id, ach_data["name"], ach_data["description"], 
                 ach_data["reward"], ach_data["icon"])
            )
        except Exception as e:
            logger.error(f"Ошибка добавления достижения {ach_id}: {e}")
    
    logger.info(f"✅ Инициализировано {len(achievements)} достижений")

# Запускаем инициализацию
init_achievements()

