@bot.message_handler(func=lambda message: True)
@safe_handler
def handle_errors(message: Message):
    """
    Глобальный обработчик: отвечает только на неизвестные slash-команды.
    """
    try:
        if not ensure_user_access(message):
            return
        text = getattr(message, "text", None) or ""
        if text.strip().startswith("/"):
            bot.reply_to(
                message,
                "❌ Неизвестная команда. Напиши /help для списка команд.",
            )
    except Exception as e:
        logger.error(f"Глобальная ошибка: {e}")

