def start_bot():
    """Запускает бота с обработкой сигналов."""
    logger.info("=" * 60)
    logger.info("🚀 ЗАПУСК БОТА")
    logger.info("=" * 60)
    
    # Проверяем подключение к чату
    try:
        bot.get_chat(CHAT_ID)
        logger.info(f"✅ Подключение к чату {CHAT_ID} успешно")
    except Exception as e:
        logger.error(f"❌ Не удалось подключиться к чату {CHAT_ID}: {e}")
        logger.error("Проверь, что бот добавлен в чат и имеет права администратора (polling продолжится)")
        # Не завершаем процесс — пробуем запустить polling (в личке бот может работать)
    
    # Проверяем права бота
    try:
        bot.get_chat_administrators(CHAT_ID)
        logger.info(f"✅ Бот имеет права администратора")
    except Exception as e:
        logger.warning(f"⚠️ Бот не является администратором чата: {e}")
    
    # Запускаем планировщики, если их ещё нет
    if not any(t.name == "duel_cleanup" for t in threading.enumerate()):
        duel_cleanup_thread = threading.Thread(
            target=scheduled_duel_cleanup, 
            daemon=True,
            name="duel_cleanup"
        )
        duel_cleanup_thread.start()
        logger.info("✅ Планировщик очистки дуэлей запущен")
    
    if BACKUP_ENABLED and not any(t.name == "backup_scheduler" for t in threading.enumerate()):
        backup_thread = threading.Thread(
            target=scheduled_backup_worker, 
            daemon=True,
            name="backup_scheduler"
        )
        backup_thread.start()
        logger.info("✅ Планировщик бэкапов запущен")

    # Фоновое обновление курсов валют раз в час
    def _currency_rate_updater():
        try:
            currency_manager.update_rates()
        except Exception as e:
            logger.warning("Первый запуск обновления курсов: %s", e)
        backoff = 1
        while True:
            time.sleep(3600)
            try:
                currency_manager.update_rates()
                backoff = 1
            except Exception as e:
                logger.warning("Ошибка обновления курсов валют: %s", e)
                time.sleep(backoff)
                backoff = min(backoff * 2, 3600)
    if not any(t.name == "currency_rate_updater" for t in threading.enumerate()):
        rate_thread = threading.Thread(target=_currency_rate_updater, daemon=True, name="currency_rate_updater")
        rate_thread.start()
        logger.info("✅ Обновление курсов валют запущено (раз в час)")
    
    if COLLECT_STATS and not any(t.name == "stats_cleanup" for t in threading.enumerate()):
        cleanup_thread = threading.Thread(
            target=scheduled_economy_cleanup, 
            daemon=True,
            name="stats_cleanup"
        )
        cleanup_thread.start()
        logger.info("✅ Планировщик очистки статистики запущен")
    
    logger.info("=" * 60)
    logger.info(f"✅ БОТ {BOT_NAME} v{BOT_VERSION} УСПЕШНО ЗАПУЩЕН")
    logger.info(f"📅 Время: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    logger.info(f"🆔 ID бота: {bot.get_me().id}")
    logger.info(f"📢 Основной чат: {CHAT_ID}")
    logger.info(f"👤 Админ: {ADMIN_CHAT_ID}")
    logger.info("=" * 60)
    
    # Polling отключён — бот запускается только через main.py (webhook).
    # Контекст для Кома: сохраняем последние сообщения из каждой группы (бот может быть в разных группах)
    try:
        bot.set_update_listener(_kom_context_update_listener)
        logger.info("✅ Listener контекста Кома для групп зарегистрирован")
    except Exception as e:
        logger.warning(f"Не удалось зарегистрировать listener контекста Кома: {e}")

    # Список команд: личка и группа для ru и en (описания из переводов, без сырых ключей)
    try:
        _pr = [
            ("start", "cmd_start"), ("lang", "cmd_lang"), ("help", "cmd_help"), ("feedback", "cmd_feedback"),
            ("time", "cmd_time"), ("city", "cmd_city"), ("weather", "cmd_weather"), ("forecast", "cmd_forecast"),
            ("timezone", "cmd_timezone"), ("crypto", "cmd_crypto"), ("ai", "cmd_ai"), ("joke", "cmd_joke"), ("joke18", "cmd_joke18"),
            ("quote", "cmd_quote"), ("flip", "cmd_flip"), ("calc", "cmd_calc"), ("balance", "cmd_balance"),
            ("currency", "cmd_currency"), ("buy", "cmd_buy"), ("daily", "cmd_daily"), ("shop", "cmd_shop"),
            ("games", "cmd_games"), ("profile", "cmd_profile"), ("whoami", "cmd_whoami"), ("support", "cmd_support"),
            ("ad", "cmd_ad"), ("faq", "cmd_faq"), ("ping", "cmd_ping"), ("rating", "cmd_rating"), ("mydonates", "cmd_mydonates"),
        ]
        _gr = [
            ("kom_start", "cmd_kom_start"), ("kom_lang", "cmd_kom_lang"), ("kom_help", "cmd_kom_help"),
            ("groupadmin", "cmd_groupadmin"), ("kom_feedback", "cmd_kom_feedback"), ("kom_time", "cmd_kom_time"),
            ("kom_city", "cmd_kom_city"), ("kom_weather", "cmd_kom_weather"), ("kom_forecast", "cmd_kom_forecast"),
            ("kom_timezone", "cmd_kom_timezone"), ("kom_crypto", "cmd_kom_crypto"), ("kom_ai", "cmd_kom_ai"),
            ("kom_rules", "cmd_kom_rules"), ("kom_joke", "cmd_kom_joke"), ("kom_quote", "cmd_kom_quote"),
            ("kom_flip", "cmd_kom_flip"), ("kom_calc", "cmd_kom_calc"), ("kom_balance", "cmd_kom_balance"),
            ("kom_currency", "cmd_kom_currency"), ("kom_buy", "cmd_kom_buy"), ("kom_daily", "cmd_kom_daily"),
            ("kom_shop", "cmd_kom_shop"), ("kom_games", "cmd_kom_games"), ("kom_profile", "cmd_kom_profile"),
            ("kom_whoami", "cmd_kom_whoami"), ("kom_faq", "cmd_kom_faq"), ("kom_ping", "cmd_kom_ping"),
            ("kom_warn", "cmd_kom_warn"), ("kom_mute", "cmd_kom_mute"), ("kom_unmute", "cmd_kom_unmute"),
            ("kom_ban", "cmd_kom_ban"), ("kom_unban", "cmd_kom_unban"), ("kom_pin", "cmd_kom_pin"),
            ("kom_unpin", "cmd_kom_unpin"), ("kom_kick", "cmd_kom_kick"), ("kom_donate", "cmd_kom_donate"),
            ("kom_donaters", "cmd_kom_donaters"), ("kom_groupstats", "cmd_kom_groupstats"),
        ]
        for lang_code, lang in [("ru", "ru"), ("en", "en")]:
            cp = [BotCommand(cmd, t(lang, key)) for cmd, key in _pr]
            cg = [BotCommand(cmd, t(lang, key)) for cmd, key in _gr]
            bot.set_my_commands(cp, scope=BotCommandScopeAllPrivateChats(), language_code=lang_code if lang_code != "ru" else None)
            bot.set_my_commands(cg, scope=BotCommandScopeAllGroupChats(), language_code=lang_code if lang_code != "ru" else None)
        logger.info("✅ Список команд обновлён (личка и группа, ru/en)")
    except Exception as e:
        logger.warning(f"Не удалось установить set_my_commands: {e}")

    # Уведомление владельцу в Telegram, что бот запустился (удобно при деплое)
    try:
        bot.send_message(
            ADMIN_CHAT_ID,
            f"✅ **Бот запущен**\n{BOT_NAME} v{BOT_VERSION}\nВремя: {datetime.now().strftime('%Y-%m-%d %H:%M')}",
            parse_mode="Markdown",
        )
    except Exception as e:
        logger.debug("Не удалось отправить уведомление о старте владельцу: %s", e)

    # Polling отключён — при прямом вызове start_bot() падаем с понятной ошибкой.
    raise RuntimeError(
        "Polling is disabled. Use webhooks: run 'python main.py' with WEBHOOK_URL set in .env. "
        "For local dev: 1) ngrok http 8080  2) set WEBHOOK_URL=https://YOUR-NGROK-URL in .env  3) python main.py"
    )


def sync_telegram_display_name_with_version() -> None:
    """
    Ставит в Telegram отображаемое имя бота (setMyName), если вырос BOT_VERSION.
    Всегда тот же шаблон: «Ком17 — Beta {версия} ✞» (см. telegram_display_name_for_profile).
    Не трогает @username. Отключить: DISABLE_TELEGRAM_NAME_SYNC=1
    """
    if os.getenv("DISABLE_TELEGRAM_NAME_SYNC", "").strip().lower() in ("1", "true", "yes"):
        return
    display_name = telegram_display_name_for_profile()
    display_name = _truncate_preserving_emoji(display_name, 64)
    prev = (settings.get("telegram_profile_version") or "").strip()
    if prev == BOT_VERSION:
        return
    try:
        bot.set_my_name(name=display_name)
        settings["telegram_profile_version"] = BOT_VERSION
        settings["bot_version"] = BOT_VERSION
        save_settings(settings)
        logger.info("✅ Имя бота в Telegram (setMyName) обновлено: %s [v%s]", display_name, BOT_VERSION)
    except Exception as e:
        logger.warning("Не удалось set_my_name (%s): %s", display_name[:48], e)


