@bot.callback_query_handler(func=lambda call: True)
def _callback_fallback_stale(call: CallbackQuery):
    """Ответ на необработанные/устаревшие callback_data (например после перезапуска бота)."""
    logger.debug("[CALLBACK] unhandled: %s from user %s", getattr(call, "data", None), getattr(call.from_user, "id", None))
    try:
        bot.answer_callback_query(call.id, CALLBACK_STALE_MSG, show_alert=True)
    except Exception:
        pass
